def is_uri(value: str) -> bool:
    return bool(re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*://", value))


def local_file_uri_path(value: str) -> Optional[Path]:
    """Resolve a local ``file://`` URI to a filesystem path when possible."""

    parsed = urlparse(value)
    if parsed.scheme.lower() != "file":
        return None
    if parsed.netloc and parsed.netloc not in {"localhost", "127.0.0.1"}:
        return None
    raw_path = unquote(parsed.path or "")
    if not raw_path:
        return None
    path = Path(raw_path).expanduser()
    if not path.is_absolute():
        path = (ROOT / path).resolve()
    return path


def verify_evidence_paths(items: Iterable[str], base: Optional[Path] = None) -> Tuple[bool, List[str], List[str]]:
    verified: List[str] = []
    missing: List[str] = []
    for raw in items:
        value = str(raw)
        if is_uri(value):
            verified.append(value)
            continue
        path = Path(value).expanduser()
        if not path.is_absolute() and base is not None:
            path = base / path
        if path.exists():
            verified.append(str(path.resolve()))
        else:
            missing.append(value)
    return bool(verified) and not missing, verified, missing


def subprocess_text(value: Any) -> str:
    if isinstance(value, str):
        return value
    if isinstance(value, bytes):
        return value.decode("utf-8", errors="replace")
    return ""


def now_iso() -> str:
    return _dt.datetime.now(_dt.timezone.utc).isoformat().replace("+00:00", "Z")


def load_config(path: Path = CONFIG) -> Dict[str, Any]:
    with path.open("r", encoding="utf-8") as f:
        config = json.load(f)
    paper_dir = config.get("paper_dir_default")
    if isinstance(paper_dir, str) and paper_dir and not Path(paper_dir).expanduser().is_absolute():
        config["paper_dir_default"] = str((ROOT / paper_dir).resolve())
    return config


def portable_tracked_template(data: Any, *, paper_dir: Optional[Path] = None) -> Any:
    """Return a deterministic, repository-relative copy for tracked templates.

    Run-local artifacts keep resolved absolute paths and timestamps.  The
    checked-in template must not capture one developer's home directory or a
    generation instant, so repository paths become root-relative and the paper
    checkout uses the documented sibling default.
    """

    repo_prefixes = (str(ROOT.resolve()), ROOT.resolve().as_posix())
    paper_prefixes: Tuple[str, ...] = ()
    if paper_dir is not None:
        resolved_paper = paper_dir.expanduser().resolve()
        paper_prefixes = (str(resolved_paper), resolved_paper.as_posix())

    def normalize(value: Any) -> Any:
        if isinstance(value, dict):
            return {
                key: (None if key == "generated_at" else normalize(item))
                for key, item in value.items()
            }
        if isinstance(value, list):
            return [normalize(item) for item in value]
        if not isinstance(value, str):
            return value

        normalized = value
        for prefix in paper_prefixes:
            if prefix:
                normalized = normalized.replace(prefix, "../rust-alloc-paper")
        for prefix in repo_prefixes:
            if not prefix:
                continue
            normalized = normalized.replace(prefix + os.sep, "")
            normalized = normalized.replace(prefix + "/", "")
            if normalized == prefix:
                normalized = "."
        return normalized

    return normalize(copy.deepcopy(data))


def portable_rust_source_span(value: str) -> str:
    """Remove checkout- and toolchain-specific prefixes from a rustc span."""

    normalized = str(value or "")
    rust_src_marker = "/lib/rustlib/src/rust/"
    if rust_src_marker in normalized:
        _prefix, _separator, suffix = normalized.partition(rust_src_marker)
        return f"$RUST_SRC/{suffix}"
    root = str(ROOT.resolve())
    if normalized.startswith(root + os.sep):
        return normalized[len(root) + 1 :]
    return normalized


def run_with_restored_file(path: Path, action: Callable[[], Any]) -> Any:
    """Run ``action`` while guaranteeing that a tracked source is restored."""

    existed = path.exists()
    original = path.read_bytes() if existed else None
    try:
        return action()
    finally:
        if existed:
            path.parent.mkdir(parents=True, exist_ok=True)
            assert original is not None
            path.write_bytes(original)
        elif path.exists():
            path.unlink()


def repository_source_path_in_scope(path: str) -> bool:
    """Return whether a repository-relative path can affect built/evaluated behavior.

    Documentation and generated evidence are deliberately outside this digest:
    editing prose must not invalidate an otherwise identical binary/evaluation,
    while allocator, compiler-pass, platform, evaluator, and workload sources do.
    """

    normalized = Path(path).as_posix()
    while normalized.startswith("./"):
        normalized = normalized[2:]
    if not normalized:
        return False
    if any(
        normalized == prefix or normalized.startswith(prefix + "/")
        for prefix in REPOSITORY_SOURCE_EXCLUDED_PREFIXES
    ):
        return False
    if normalized.startswith("evaluation/scripts/"):
        script_path = Path(normalized)
        if "__pycache__" in script_path.parts:
            return False
        if script_path.name.startswith("test_") and script_path.suffix == ".py":
            return False
    if normalized in REPOSITORY_SOURCE_TOP_LEVEL_FILES:
        return True
    return any(
        normalized == prefix or normalized.startswith(prefix + "/")
        for prefix in REPOSITORY_SOURCE_PREFIXES
    )


def git_output(root: Path, *args: str) -> Optional[bytes]:
    try:
        completed = subprocess.run(
            ["git", *args],
            cwd=root,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            check=False,
        )
    except OSError:
        return None
    return completed.stdout if completed.returncode == 0 else None


def repository_source_paths(root: Path) -> List[str]:
    tracked_and_untracked = git_output(
        root,
        "ls-files",
        "-co",
        "--exclude-standard",
        "-z",
        "--",
    )
    if tracked_and_untracked is not None:
        candidates = [
            item.decode("utf-8", errors="surrogateescape")
            for item in tracked_and_untracked.split(b"\0")
            if item
        ]
    else:
        raise RuntimeError(
            f"git source inventory is unavailable for repository fingerprint: {root}"
        )
    candidates.extend(
        path.relative_to(root).as_posix()
        for pattern in REPOSITORY_SOURCE_INCLUDED_IGNORED_GLOBS
        for path in root.glob(pattern)
        if path.is_file() or path.is_symlink()
    )
    return sorted(
        {
            Path(path).as_posix()
            for path in candidates
            if repository_source_path_in_scope(path)
        }
    )


def repository_source_fingerprint(
    root: Path = ROOT,
    *,
    refresh: bool = False,
) -> Dict[str, Any]:
    """Hash the working-tree inputs that can affect implementation/evaluation.

    The content digest, not the current commit id, is the comparison key.  This
    keeps evidence valid across a metadata-only commit while still binding it to
    dirty and untracked source files that actually participated in the run.
    """

    # ``refresh`` remains a compatibility keyword for callers/tests.  The
    # function intentionally recomputes every time: a long evaluator process
    # must never compare evidence against a cached pre-edit working tree.
    _ = refresh
    resolved_root = root.expanduser().resolve()

    entries: List[Dict[str, Any]] = []
    for relative in repository_source_paths(resolved_root):
        path = resolved_root / relative
        if path.is_symlink():
            target = os.readlink(path)
            payload = target.encode("utf-8", errors="surrogateescape")
            entries.append(
                {
                    "path": relative,
                    "kind": "symlink",
                    "git_mode": "120000",
                    "size": len(payload),
                    "sha256": hashlib.sha256(payload).hexdigest(),
                }
            )
        elif path.is_file():
            stat_result = path.stat()
            entries.append(
                {
                    "path": relative,
                    "kind": "file",
                    "git_mode": "100755" if stat_result.st_mode & 0o111 else "100644",
                    "size": stat_result.st_size,
                    "sha256": file_sha256(path),
                }
            )
        else:
            # A tracked file deleted from the working tree must affect the digest.
            entries.append({"path": relative, "kind": "missing"})

    scope = {
        "top_level_files": sorted(REPOSITORY_SOURCE_TOP_LEVEL_FILES),
        "included_prefixes": sorted(REPOSITORY_SOURCE_PREFIXES),
        "excluded_prefixes": sorted(REPOSITORY_SOURCE_EXCLUDED_PREFIXES),
        "included_ignored_globs": sorted(REPOSITORY_SOURCE_INCLUDED_IGNORED_GLOBS),
        "evaluation_test_scripts_in_digest": False,
        "documentation_in_digest": False,
        "generated_evidence_in_digest": False,
        "head_commit_in_digest": False,
    }
    digest_payload = json.dumps(
        {
            "schema_version": REPOSITORY_SOURCE_FINGERPRINT_SCHEMA_VERSION,
            "algorithm": "sha256",
            "scope": scope,
            "entries": entries,
        },
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
    ).encode("utf-8", errors="surrogateescape")
    head_output = git_output(resolved_root, "rev-parse", "HEAD")
    status_output = git_output(
        resolved_root,
        "status",
        "--porcelain=v1",
        "--untracked-files=all",
        "--",
    )
    fingerprint = {
        "schema_version": REPOSITORY_SOURCE_FINGERPRINT_SCHEMA_VERSION,
        "algorithm": "sha256",
        "source_digest": hashlib.sha256(digest_payload).hexdigest(),
        "source_file_count": len(entries),
        "missing_source_file_count": sum(
            1 for entry in entries if entry.get("kind") == "missing"
        ),
        "head_commit": (
            head_output.decode("ascii", errors="replace").strip()
            if head_output is not None
            else None
        ),
        "working_tree_dirty": bool(status_output and status_output.strip()),
        "working_tree_status_line_count": (
            len(status_output.decode("utf-8", errors="replace").splitlines())
            if status_output is not None
            else None
        ),
        "scope": scope,
    }
    return fingerprint


def evidence_source_bound_payload(
    data: Dict[str, Any],
    *,
    fingerprint: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    payload = copy.deepcopy(data)
    payload["evidence_source_fingerprint"] = copy.deepcopy(
        fingerprint if fingerprint is not None else repository_source_fingerprint()
    )
    return payload


def evidence_source_bound_payload_if_stable(
    data: Dict[str, Any],
    *,
    started: Dict[str, Any],
    finished: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Bind evidence only when repository inputs stayed unchanged during collection."""

    current = finished if finished is not None else repository_source_fingerprint()
    started_digest = str(started.get("source_digest") or "")
    finished_digest = str(current.get("source_digest") or "")
    if started_digest and started_digest == finished_digest:
        return evidence_source_bound_payload(data, fingerprint=current)
    payload = copy.deepcopy(data)
    payload.pop("evidence_source_fingerprint", None)
    existing = payload.get("evidence_source_binding_blockers", [])
    if not isinstance(existing, list):
        existing = [existing]
    payload["evidence_source_binding_blockers"] = unique_strings(
        [
            *existing,
            "repository source changed while evidence was being collected: "
            f"started={started_digest or '<missing>'}, "
            f"finished={finished_digest or '<missing>'}",
        ]
    )
    return payload


def shared_evidence_source_fingerprint(
    records: Iterable[Any],
) -> Optional[Dict[str, Any]]:
    fingerprints = [
        record.get("evidence_source_fingerprint")
        for record in records
        if isinstance(record, dict)
    ]
    if not fingerprints or any(not isinstance(item, dict) for item in fingerprints):
        return None
    identities = {
        (
            item.get("schema_version"),
            item.get("algorithm"),
            str(item.get("source_digest") or "").strip(),
        )
        for item in fingerprints
    }
    if (
        len(identities) != 1
        or next(iter(identities))[0] != REPOSITORY_SOURCE_FINGERPRINT_SCHEMA_VERSION
        or next(iter(identities))[1] != "sha256"
        or not next(iter(identities))[2]
    ):
        return None
    return copy.deepcopy(fingerprints[0])


def repository_source_binding_blockers(
    data: Any,
    *,
    current: Optional[Dict[str, Any]] = None,
) -> List[str]:
    if not isinstance(data, dict):
        return ["artifact is not a JSON object with repository source provenance"]
    recorded = data.get("evidence_source_fingerprint")
    if not isinstance(recorded, dict):
        return ["artifact is missing evidence_source_fingerprint"]
    if recorded.get("schema_version") != REPOSITORY_SOURCE_FINGERPRINT_SCHEMA_VERSION:
        return [
            "artifact repository source fingerprint schema is unsupported: "
            f"{recorded.get('schema_version')}"
        ]
    if recorded.get("algorithm") != "sha256":
        return [
            "artifact repository source fingerprint algorithm is unsupported: "
            f"{recorded.get('algorithm')}"
        ]
    recorded_digest = str(recorded.get("source_digest") or "").strip()
    if not recorded_digest:
        return ["artifact repository source fingerprint is missing source_digest"]
    current_fingerprint = current or repository_source_fingerprint()
    current_digest = str(current_fingerprint.get("source_digest") or "").strip()
    if recorded_digest != current_digest:
        return [
            "artifact repository source digest does not match the current working tree: "
            f"recorded={recorded_digest}, current={current_digest}"
        ]
    return []


def generated_evaluation_artifact_path(path: Path) -> bool:
    resolved = path.expanduser().resolve()
    for root in (RAW, RESULTS, REPORTS):
        try:
            resolved.relative_to(root.expanduser().resolve())
            return True
        except ValueError:
            continue
    return False


def write_json(path: Path, data: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(
        f".{path.name}.{os.getpid()}.{threading.get_ident()}.{time.time_ns()}.tmp"
    )
    try:
        with tmp.open("x", encoding="utf-8") as f:
            json.dump(data, f, indent=2, sort_keys=True)
            f.write("\n")
        tmp.replace(path)
    finally:
        try:
            tmp.unlink()
        except FileNotFoundError:
            pass


def file_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def read_json(path: Path) -> Any:
    with path.open("r", encoding="utf-8") as f:
        return json.load(f)


def read_json_if_exists(path: Path) -> Optional[Any]:
    return read_json(path) if path.exists() else None


def geomean(values: Iterable[float]) -> Optional[float]:
    xs = [float(v) for v in values if float(v) > 0 and math.isfinite(float(v))]
    if not xs:
        return None
    return math.exp(sum(math.log(v) for v in xs) / len(xs))


def arithmean(values: Iterable[float]) -> Optional[float]:
    xs = [float(v) for v in values if math.isfinite(float(v))]
    return sum(xs) / len(xs) if xs else None


def dat_header(line: str) -> List[str]:
    # Paper .dat files use a comment header such as:
    # # # jemalloc ptmalloc mimalloc ...
    parts = line.lstrip("#").strip().split()
    return [p for p in parts if p != "#"]


def parse_dat(path: Path) -> Dict[str, Any]:
    header: List[str] = []
    rows: List[Dict[str, Any]] = []
    for raw in path.read_text(encoding="utf-8").splitlines():
        line = raw.strip()
        if not line:
            continue
        if line.startswith("#"):
            maybe = dat_header(line)
            if maybe:
                header = maybe
            continue
        toks = shlex.split(line)
        if len(toks) < 3:
            continue
        bench_id = toks[0]
        bench = toks[1]
        nums = [float(x) for x in toks[2:]]
        if not header or len(header) != len(nums):
            header = [f"col{i+1}" for i in range(len(nums))]
        values = dict(zip(header, nums))
        rows.append({"id": bench_id, "benchmark": bench, "values": values})
    return dataset_from_rows(str(path), header, rows)


def dataset_from_rows(path: str, columns: List[str], rows: List[Dict[str, Any]], **extra: Any) -> Dict[str, Any]:
    all_values = [v for r in rows for v in r["values"].values()]
    gm = geomean(all_values)
    am = arithmean(all_values)
    data = {
        "path": path,
        "columns": columns,
        "rows": rows,
        "count": len(all_values),
        "geomean": gm,
        "arithmetic_mean": am,
        "geomean_delta_percent_vs_unialloc": None if gm is None else (gm - 1.0) * 100.0,
        "speedup_percent_vs_baselines": None if gm is None else (gm - 1.0) / gm * 100.0,
        "baseline_speedup_percent_vs_unialloc": None if gm is None else (1.0 / gm - 1.0) * 100.0,
    }
    data.update(extra)
    return data


def dat_number(value: Any) -> str:
    if value is None:
        return "nan"
    try:
        number = float(value)
    except (TypeError, ValueError):
        return str(value)
    if not math.isfinite(number):
        return "nan"
    return f"{number:.12g}"


def write_dat(path: Path, dataset: Dict[str, Any]) -> None:
    """Write a paper-shaped .dat file from a normalized dataset."""
    path.parent.mkdir(parents=True, exist_ok=True)
    columns = [str(c) for c in dataset.get("columns", [])]
    lines = ["#\t#\t" + "\t".join(columns)]
    for index, row in enumerate(dataset.get("rows", []), start=1):
        row_id = str(row.get("id") or index)
        benchmark = str(row.get("benchmark") or "")
        values = row.get("values", {})
        rendered = [dat_number(values.get(column)) for column in columns]
        lines.append(f'{row_id}\t"{benchmark}"\t' + "\t".join(rendered))
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")


def dataset_reference_gaps(
    current_ds: Dict[str, Any], reference_ds: Optional[Dict[str, Any]]
) -> Dict[str, Any]:
    current_rows = {r.get("benchmark") for r in current_ds.get("rows", [])}
    current_columns = set(current_ds.get("columns", []))
    reference_rows = {r.get("benchmark") for r in reference_ds.get("rows", [])} if reference_ds else set()
    reference_columns = set(reference_ds.get("columns", [])) if reference_ds else set()
    row_by_name = {r.get("benchmark"): r for r in current_ds.get("rows", [])}
    missing_reference_cells: List[str] = []
    if reference_ds:
        for ref_row in reference_ds.get("rows", []):
            benchmark = ref_row.get("benchmark")
            current_row = row_by_name.get(benchmark)
            values = current_row.get("values", {}) if current_row else {}
            for column in reference_columns:
                if column not in current_columns:
                    continue
                if finite_number(values.get(column)) is None:
                    missing_reference_cells.append(f"{benchmark}/{column}")
    return {
        "missing_reference_rows": sorted(reference_rows - current_rows),
        "missing_reference_columns": sorted(reference_columns - current_columns),
        "missing_reference_cells": sorted(missing_reference_cells),
        "extra_current_rows": sorted(current_rows - reference_rows) if reference_rows else sorted(current_rows),
        "extra_current_columns": sorted(current_columns - reference_columns) if reference_columns else sorted(current_columns),
    }


def load_dataset_manifest(data_dir: Path, manifest_arg: Optional[str]) -> Tuple[Optional[Dict[str, Any]], Optional[Path]]:
    candidates: List[Path] = []
    if manifest_arg:
        candidates.append(Path(manifest_arg).expanduser())
    candidates.append(data_dir / "dataset-manifest.json")
    for candidate in candidates:
        if candidate.exists():
            return read_json(candidate), candidate
    return None, None


def claims_by_dataset(cfg: Dict[str, Any]) -> Dict[str, List[Dict[str, Any]]]:
    grouped: Dict[str, List[Dict[str, Any]]] = {}
    for claim in cfg.get("claims", []):
        dataset = claim.get("dataset")
        if not dataset:
            continue
        grouped.setdefault(str(dataset), []).append(
            {
                "id": claim.get("id"),
                "description": claim.get("description"),
                "metric": claim.get("metric"),
                "threshold": claim.get("threshold"),
                "required_for_overclaim": bool(claim.get("required_for_overclaim")),
            }
        )
    return grouped


def benchmark_category_lookup(cfg: Dict[str, Any]) -> Dict[str, str]:
    lookup: Dict[str, str] = {}
    for category, benchmarks in cfg.get("benchmarks", {}).items():
        for benchmark in benchmarks:
            lookup[str(benchmark)] = str(category)
    return lookup


def allocator_feature_support(allocator: str) -> Dict[str, Any]:
    matching = [feature for feature, mapped in FEATURE_TO_ALLOCATOR.items() if mapped == allocator]
    blockers: List[str] = []
    notes: List[str] = []
    if matching:
        notes.append("run-local has a feature mapping for this allocator column")
        if allocator == "scudo" and not scudo_toolchain_available():
            blockers.append("bench_scudo is mapped, but the active Rust toolchain/target does not accept the scudo sanitizer runtime")
    elif allocator == "ptmalloc" and platform.system() != "Linux":
        blockers.append(
            f"bench_ptmalloc maps to {FEATURE_TO_ALLOCATOR.get('bench_ptmalloc')} on {platform.system()}; Linux ptmalloc evidence requires a Linux/glibc run"
        )
    elif allocator == "scudo":
        blockers.append("run-local has no bench_scudo feature mapping or dependency wrapper")
    elif allocator == "default" and platform.system() == "Linux":
        blockers.append("the paper's default column is platform-specific; Linux default allocator is modeled as ptmalloc in this runner")
    else:
        blockers.append("no run-local feature mapping for this allocator column")
    return {
        "allocator": allocator,
        "run_local_features": matching,
        "supported_by_run_local_mapping": bool(matching),
        "claim_grade_mapping_blockers": unique_strings(blockers),
        "notes": unique_strings(notes),
    }


def paper_workload_support(benchmark: str, category: Optional[str]) -> Dict[str, Any]:
    if benchmark == "Collections":
        return {
            "benchmark": benchmark,
            "category": category or "micro",
            "supported_by_in_tree_runner": True,
            "runner_path": "run-local std_bench followed by export-current-datasets --paper-shape",
            "claim_grade_notes": [
                "The in-tree runner can only aggregate local std_bench rows into the paper's Collections row.",
                "It still needs six-run methodology and verified allocator coverage before the row can be claim-grade.",
            ],
        }
    if category in {"macro_single_thread", "macro_multi_thread"}:
        return {
            "benchmark": benchmark,
            "category": category,
            "supported_by_in_tree_runner": False,
            "required_runner": "external paper macrobenchmark harness plus imported .dat/provenance manifest",
            "claim_grade_blockers": [
                "no in-tree runner currently executes this paper macrobenchmark workload"
            ],
        }
    if category == "web":
        return {
            "benchmark": benchmark,
            "category": category,
            "supported_by_in_tree_runner": False,
            "required_runner": "external web framework benchmark harness plus imported .dat/provenance manifest",
            "claim_grade_blockers": ["no in-tree runner currently executes this paper web workload"],
        }
    return {
        "benchmark": benchmark,
        "category": category or "unknown",
        "supported_by_in_tree_runner": False,
        "required_runner": "external paper-compatible harness plus imported .dat/provenance manifest",
        "claim_grade_blockers": ["benchmark is not mapped to an in-tree runner capability"],
    }


def current_dataset_import_snapshot(dataset_name: str) -> Dict[str, Any]:
    summary_path = RESULTS / "current_datasets_summary.json"
    if not summary_path.exists():
        return {"available": False, "summary_path": str(summary_path)}
    try:
        summary = read_json(summary_path)
    except json.JSONDecodeError as exc:
        return {"available": False, "summary_path": str(summary_path), "error": str(exc)}
    dataset = summary.get("datasets", {}).get(dataset_name)
    if not dataset:
        return {"available": False, "summary_path": str(summary_path)}
    scope = dataset.get("scope", {}) if isinstance(dataset.get("scope"), dict) else {}
    return {
        "available": True,
        "summary_path": str(summary_path),
        "path": dataset.get("path"),
        "claim_grade": bool(dataset.get("claim_grade")),
        "rows": [row.get("benchmark") for row in dataset.get("rows", [])],
        "columns": dataset.get("columns", []),
        "scope_complete_for_claim": bool(scope.get("complete_for_claim")),
        "claim_grade_blockers": scope.get("claim_grade_blockers", []),
        "missing_reference_rows": scope.get("missing_reference_rows", []),
        "missing_reference_columns": scope.get("missing_reference_columns", []),
    }


def build_paper_performance_target_audit(
    cfg: Dict[str, Any],
    paper_dir: Path,
    *,
    dataset_names: Optional[List[str]] = None,
    include_all_paper_data: bool = False,
) -> Dict[str, Any]:
    grouped_claims = claims_by_dataset(cfg)
    category_lookup = benchmark_category_lookup(cfg)
    if dataset_names is None:
        dataset_names = list(grouped_claims.keys())
        if include_all_paper_data:
            for name in cfg.get("paper_data", {}):
                if name not in dataset_names:
                    dataset_names.append(name)
    else:
        dataset_names = unique_strings(dataset_names)

    datasets: Dict[str, Any] = {}
    all_missing_workloads: List[str] = []
    all_missing_allocators: List[str] = []
    for dataset_name in dataset_names:
        rel = cfg.get("paper_data", {}).get(dataset_name)
        if not rel:
            continue
        ref_path = paper_dir / rel
        reference_ds = parse_dat(ref_path) if ref_path.exists() else None
        row_requirements: List[Dict[str, Any]] = []
        column_requirements: List[Dict[str, Any]] = []
        if reference_ds:
            for row in reference_ds.get("rows", []):
                benchmark = str(row.get("benchmark"))
                support = paper_workload_support(benchmark, category_lookup.get(benchmark))
                row_requirements.append(support)
            for column in reference_ds.get("columns", []):
                column_requirements.append(allocator_feature_support(str(column)))

        missing_workloads = [
            row["benchmark"]
            for row in row_requirements
            if not row.get("supported_by_in_tree_runner")
        ]
        missing_allocators = [
            col["allocator"]
            for col in column_requirements
            if not col.get("supported_by_run_local_mapping")
        ]
        all_missing_workloads.extend(missing_workloads)
        all_missing_allocators.extend(missing_allocators)
        variant_feature = {value: key for key, value in VARIANT_FEATURE_TO_DATASET.items()}.get(dataset_name)
        blockers: List[str] = []
        if not reference_ds:
            blockers.append(f"paper reference dataset missing: {ref_path}")
        if missing_workloads:
            blockers.append("in-tree runner lacks paper workload rows: " + ", ".join(missing_workloads))
        if missing_allocators:
            blockers.append("in-tree runner lacks allocator column mappings on this host: " + ", ".join(missing_allocators))
        if ref_path.exists() and dataset_name in {"default_performance", "type_isolation", "metadata_segregation", "hugepage_metadata", "pac_authentication"} and platform.system() != "Linux":
            blockers.append("paper Linux performance rows require Linux claim-run provenance; current host is " + platform.system())
        current_import = current_dataset_import_snapshot(dataset_name)
        if not current_import.get("claim_grade"):
            blockers.append("no imported current dataset is verified as claim-grade for this paper dataset")
        datasets[dataset_name] = {
            "paper_data": rel,
            "reference_path": str(ref_path),
            "reference_exists": ref_path.exists(),
            "claims": grouped_claims.get(dataset_name, []),
            "variant_feature": variant_feature,
            "methodology": cfg.get("methodology", {}),
            "required_rows": row_requirements,
            "required_columns": column_requirements,
            "missing_in_tree_workload_rows": unique_strings(missing_workloads),
            "missing_in_tree_allocator_columns": unique_strings(missing_allocators),
            "current_import": current_import,
            "import_contract": {
                "data_file": Path(rel).name,
                "manifest": "dataset-manifest.json",
                "must_cover_reference_rows_and_columns": True,
                "must_verify_raw_evidence_paths": True,
                "must_mark_claim_grade_or_complete_for_claim": True,
                "sample_import_contract": paper_performance_sample_contract(),
            },
            "claim_grade_blockers": unique_strings(blockers),
        }

    return {
        "schema_version": 1,
        "generated_at": now_iso(),
        "source": "paper-performance-target-audit",
        "paper_dir": str(paper_dir),
        "host": host_metadata(),
        "methodology": cfg.get("methodology", {}),
        "runner_capabilities": {
            "in_tree_workloads": ["Collections via std_bench aggregate export"],
            "external_sample_importer": "import-paper-performance-samples",
            "feature_to_allocator": FEATURE_TO_ALLOCATOR,
            "variant_feature_to_dataset": VARIANT_FEATURE_TO_DATASET,
            "limitations": [
                "run-local currently executes the in-tree std_bench harness only",
                "macro, multi-thread macro, web, and platform paper rows need external current-run artifacts or import-paper-performance-samples inputs",
                "allocator feature mapping is not the same as dependency/toolchain availability or claim-grade provenance",
            ],
        },
        "summary": {
            "dataset_count": len(datasets),
            "datasets_with_claims": sorted(grouped_claims),
            "missing_in_tree_workload_rows": unique_strings(all_missing_workloads),
            "missing_in_tree_allocator_columns": unique_strings(all_missing_allocators),
            "claim_grade_ready": all(not d.get("claim_grade_blockers") for d in datasets.values()),
        },
        "datasets": datasets,
    }


def write_paper_performance_target_report(path: Path, audit: Dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    lines = [
        "# Paper performance target audit",
        "",
        f"Generated: `{audit.get('generated_at')}`",
        f"Paper dir: `{audit.get('paper_dir')}`",
        "",
        "## Summary",
        "",
        f"- Dataset count: `{audit.get('summary', {}).get('dataset_count')}`",
        f"- Claim-grade ready: `{audit.get('summary', {}).get('claim_grade_ready')}`",
        "- Missing in-tree workload rows: " + ", ".join(audit.get("summary", {}).get("missing_in_tree_workload_rows", [])),
        "- Missing in-tree allocator columns: " + ", ".join(audit.get("summary", {}).get("missing_in_tree_allocator_columns", [])),
        "",
        "## Dataset blockers",
        "",
        "| dataset | claims | missing rows | missing columns | blockers |",
        "|---|---|---|---|---|",
    ]
    for name, dataset in audit.get("datasets", {}).items():
        claims = ", ".join(str(c.get("id")) for c in dataset.get("claims", [])) or "-"
        missing_rows = ", ".join(dataset.get("missing_in_tree_workload_rows", [])) or "-"
        missing_columns = ", ".join(dataset.get("missing_in_tree_allocator_columns", [])) or "-"
        blockers = "<br>".join(dataset.get("claim_grade_blockers", [])) or "-"
        lines.append(f"| `{name}` | {claims} | {missing_rows} | {missing_columns} | {blockers} |")
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")


def audit_paper_performance_targets(args: argparse.Namespace) -> int:
    cfg = load_config()
    paper_dir = Path(args.paper_dir or cfg.get("paper_dir_default", "")).expanduser()
    if not paper_dir.exists():
        print(f"paper dir not found: {paper_dir}", file=sys.stderr)
        return 2
    dataset_names = performance_plan_dataset_names(
        cfg,
        selected=args.dataset,
        include_all_paper_data=bool(args.all_paper_data),
    )
    run_id = args.run_id or _dt.datetime.now().strftime("paper-performance-targets-%Y%m%d-%H%M%S")
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)
    audit = build_paper_performance_target_audit(
        cfg,
        paper_dir,
        dataset_names=dataset_names,
        include_all_paper_data=bool(args.all_paper_data),
    )
    audit_path = out_dir / "paper-performance-targets.json"
    report_path = out_dir / "paper-performance-targets.md"
    write_json(audit_path, audit)
    write_paper_performance_target_report(report_path, audit)
    write_json(RESULTS / "paper_performance_targets.json", audit)

    sample_template_path = None
    sample_template_summary_path = None
    if args.write_sample_template:
        sample_template = build_paper_performance_sample_template(
            cfg,
            paper_dir,
            dataset_names=dataset_names,
            required_runs=int(args.required_runs or cfg.get("methodology", {}).get("runs_per_benchmark", 6)),
        )
        sample_template_path = Path(args.write_sample_template).expanduser()
        sample_template_summary_path = write_paper_performance_sample_template(sample_template_path, sample_template)

    print(
        json.dumps(
            {
                "audit": str(audit_path),
                "report": str(report_path),
                "dataset_names": dataset_names,
                "claim_grade_ready": audit["summary"]["claim_grade_ready"],
                "sample_template": str(sample_template_path) if sample_template_path else None,
                "sample_template_summary": str(sample_template_summary_path) if sample_template_summary_path else None,
            },
            indent=2,
            sort_keys=True,
        )
    )
    return 0


def finite_number(value: Any) -> Optional[float]:
    try:
        number = float(value)
    except (TypeError, ValueError):
        return None
    if not math.isfinite(number) or number <= 0:
        return None
    return number


def normalize_sample_allocator(value: Any) -> str:
    raw = str(value or "").strip()
    aliases = {
        "bench_ourself": "unialloc",
        "ourself": "unialloc",
        "uni_alloc": "unialloc",
        "uni-alloc": "unialloc",
        "UniAlloc": "unialloc",
        "bench_jemalloc": "jemalloc",
        "bench_ptmalloc": "ptmalloc",
        "bench_mimalloc": "mimalloc",
        "bench_tcmalloc": "tcmalloc",
        "bench_snmalloc": "snmalloc",
        "bench_scudo": "scudo",
    }
    return aliases.get(raw, raw)


def sample_time_value(sample: Dict[str, Any]) -> Optional[float]:
    for key in ("seconds", "time_seconds", "wall_seconds", "elapsed_seconds"):
        value = finite_number(sample.get(key))
        if value is not None:
            return value
    for key in ("ns_per_iter", "time_ns", "nanoseconds"):
        value = finite_number(sample.get(key))
        if value is not None:
            return value / 1_000_000_000.0
    for key in ("ms", "milliseconds"):
        value = finite_number(sample.get(key))
        if value is not None:
            return value / 1_000.0
    return None


def sample_successful_timing_value(sample: Dict[str, Any]) -> Optional[float]:
    """Return a timing value only for successful samples.

    Raw plan records intentionally keep `wall_seconds` for failed subprocesses
    so the audit trail can prove how an attempt ended.  That wall time is not a
    benchmark measurement and must not be counted as finite paper timing.
    """

    if not sample_succeeded(sample):
        return None
    return sample_time_value(sample)


def read_paper_performance_samples(path: Path) -> List[Dict[str, Any]]:
    suffix = path.suffix.lower()
    records: List[Dict[str, Any]] = []
    if suffix == ".csv":
        with path.open("r", encoding="utf-8", newline="") as f:
            reader = csv.DictReader(f)
            for row in reader:
                records.append(dict(row))
        return records
    for line_no, line in enumerate(path.read_text(encoding="utf-8").splitlines(), start=1):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        try:
            value = json.loads(line)
        except json.JSONDecodeError as exc:
            raise ValueError(f"{path}:{line_no}: expected JSON object per line: {exc}") from exc
        if not isinstance(value, dict):
            raise ValueError(f"{path}:{line_no}: expected JSON object per line")
        records.append(value)
    return records


def sample_run_index(sample: Dict[str, Any], fallback: int) -> int:
    for key in ("run_index", "run", "iteration", "replicate"):
        try:
            return int(sample.get(key))
        except (TypeError, ValueError):
            continue
    return fallback


def sample_succeeded(sample: Dict[str, Any]) -> bool:
    """Return whether a timing sample is eligible for current evidence import.

    External plan runners may keep failed commands in the raw JSONL so the audit
    trail is complete. The performance importer must not turn those failed
    attempts into finite cells simply because they also recorded wall time.
    Missing status fields are treated as success for hand-authored legacy CSV/
    JSONL imports; explicit failure/status fields are authoritative.
    """

    for key in ("success", "succeeded", "ok"):
        if key not in sample:
            continue
        value = sample.get(key)
        if isinstance(value, bool):
            if not value:
                return False
            continue
        lowered = str(value).strip().lower()
        if lowered in {"0", "false", "no", "failed", "failure", "error", "timeout"}:
            return False
    for key in ("status", "result"):
        if key not in sample:
            continue
        lowered = str(sample.get(key)).strip().lower()
        if lowered in {"failed", "failure", "error", "timeout", "timed_out", "skipped", "cancelled", "canceled"}:
            return False
    for key in ("exit_code", "returncode", "return_code"):
        if key not in sample:
            continue
        try:
            if int(sample.get(key)) != 0:
                return False
        except (TypeError, ValueError):
            return False
    return True


def sample_metadata_candidates(sample: Dict[str, Any]) -> List[Dict[str, Any]]:
    candidates: List[Dict[str, Any]] = [sample]
    metadata = sample.get("metric_metadata")
    if isinstance(metadata, dict):
        candidates.append(metadata)
    provenance = sample.get("provenance")
    if isinstance(provenance, dict):
        candidates.append(provenance)
    for candidate in list(candidates):
        nested = candidate.get("provenance")
        if isinstance(nested, dict) and nested not in candidates:
            candidates.append(nested)
    for candidate in list(candidates):
        child = candidate.get("child_record")
        if isinstance(child, dict) and child not in candidates:
            candidates.append(child)
    return candidates


def has_sample_command_provenance(sample: Dict[str, Any]) -> bool:
    for candidate in sample_metadata_candidates(sample):
        for key in ("command", "argv", "cmd", "command_line", "invocation"):
            value = candidate.get(key)
            if isinstance(value, list) and value:
                return True
            if str(value or "").strip():
                return True
    return False


def has_sample_host_provenance(sample: Dict[str, Any]) -> bool:
    for candidate in sample_metadata_candidates(sample):
        host = candidate.get("host")
        if isinstance(host, dict) and any(str(value).strip() for value in host.values()):
            return True
        for key in ("host_system", "system", "platform", "machine", "target", "target_triple"):
            if str(candidate.get(key) or "").strip():
                return True
    return False


def sample_evidence_entries(sample: Dict[str, Any]) -> List[Any]:
    entries: List[Any] = []
    evidence_keys = (
        "evidence",
        "evidence_paths",
        "raw_evidence",
        "raw_evidence_paths",
        "stdout",
        "stderr",
        "stdout_path",
        "stderr_path",
        "log",
        "log_path",
        "summary",
        "summary_path",
        "raw_log",
        "raw_log_path",
    )
    for candidate in sample_metadata_candidates(sample):
        for key in evidence_keys:
            value = candidate.get(key)
            if isinstance(value, list):
                entries.extend(item for item in value if str(item).strip())
            elif isinstance(value, dict):
                entries.append(value)
            elif str(value or "").strip():
                entries.append(str(value))
    ordered_keys: List[str] = []
    by_key: Dict[str, Any] = {}
    for entry in entries:
        path_key = evidence_entry_path(entry)
        key = path_key or (json.dumps(entry, sort_keys=True) if isinstance(entry, dict) else str(entry))
        if key not in by_key:
            ordered_keys.append(key)
            by_key[key] = entry
            continue
        existing = by_key[key]
        if evidence_entry_sha256(existing) is None and evidence_entry_sha256(entry) is not None:
            by_key[key] = entry
    return [by_key[key] for key in ordered_keys]


def evidence_entry_path(entry: Any) -> str:
    if isinstance(entry, dict):
        for key in ("path", "uri", "url", "file", "log", "raw_path", "log_path"):
            if str(entry.get(key) or "").strip():
                return str(entry.get(key)).strip()
        return ""
    return str(entry or "").strip()


def normalize_sha256_digest(value: Any) -> Optional[str]:
    raw = str(value or "").strip().lower()
    if raw.startswith("sha256:"):
        raw = raw.split(":", 1)[1].strip()
    if re.fullmatch(r"[0-9a-f]{64}", raw):
        return raw
    return None


def evidence_entry_sha256(entry: Any) -> Optional[str]:
    if not isinstance(entry, dict):
        return None
    for key in ("sha256", "sha256_hex", "digest", "checksum"):
        digest = normalize_sha256_digest(entry.get(key))
        if digest:
            return digest
    return None


def sample_evidence_items(sample: Dict[str, Any]) -> List[str]:
    return unique_strings(evidence_entry_path(entry) for entry in sample_evidence_entries(sample))


def verify_evidence_paths_with_roots(items: Iterable[str], roots: Iterable[Path]) -> Tuple[bool, List[str], List[str]]:
    verified: List[str] = []
    missing: List[str] = []
    for raw in items:
        value = str(raw)
        uri_path = local_file_uri_path(value) if is_uri(value) else None
        if is_uri(value) and uri_path is None:
            missing.append(value)
            continue
        path = (uri_path if uri_path is not None else Path(value)).expanduser()
        candidates = [path] if path.is_absolute() else [root / path for root in roots]
        existing = next((candidate for candidate in candidates if candidate.exists()), None)
        if existing is not None:
            verified.append(str(existing.resolve()))
        else:
            missing.append(value)
    return bool(verified) and not missing, unique_strings(verified), unique_strings(missing)


def normalized_local_path(value: Any, *, base: Path = ROOT) -> Optional[Path]:
    text = str(value or "").strip()
    if not text or is_uri(text):
        return None
    path = Path(text).expanduser()
    return path if path.is_absolute() else base / path


def append_evidence_root(roots: List[Path], path: Optional[Path]) -> None:
    if path is None:
        return
    root = path.expanduser()
    if not root.is_absolute():
        root = ROOT / root
    root = root.resolve()
    if root not in roots:
        roots.append(root)


def dataset_manifest_evidence_roots(
    data_dir: Path,
    manifest_path: Optional[Path],
    manifest: Optional[Dict[str, Any]],
    dataset_name: str,
    manifest_entry: Dict[str, Any],
) -> List[Path]:
    """Candidate roots for dataset provenance evidence entries.

    Dataset manifests are often merged from run-local manifests. Evidence may be
    relative to the active data directory, the repository root, or the source
    manifest's original `data/` directory. Keeping all of these as read roots
    prevents valid provenance from being reported missing after a safe merge,
    while still requiring the underlying files to exist.
    """

    roots: List[Path] = []
    append_evidence_root(roots, manifest_path.parent if manifest_path else data_dir)
    append_evidence_root(roots, data_dir)
    append_evidence_root(roots, ROOT)

    for run_dir_value in (
        (manifest or {}).get("run_dir") if isinstance(manifest, dict) else None,
        manifest_entry.get("run_dir"),
        (manifest_entry.get("scope") or {}).get("run_dir") if isinstance(manifest_entry.get("scope"), dict) else None,
    ):
        run_dir = normalized_local_path(run_dir_value)
        if run_dir is None:
            continue
        append_evidence_root(roots, run_dir / "data")
        append_evidence_root(roots, run_dir)

    merge_sources = (manifest or {}).get("merge_sources", {}) if isinstance(manifest, dict) else {}
    if isinstance(merge_sources, dict):
        source_values = []
        if dataset_name in merge_sources:
            source_values.append(merge_sources.get(dataset_name))
        if dataset_name != "default_performance" and merge_sources.get("other_datasets"):
            source_values.append(merge_sources.get("other_datasets"))
        for source in source_values:
            source_path = normalized_local_path(source)
            if source_path is None:
                continue
            append_evidence_root(roots, source_path.parent)
            append_evidence_root(roots, source_path.parent.parent)

    source_samples = (manifest_entry.get("scope") or {}).get("source_samples") if isinstance(manifest_entry.get("scope"), dict) else None
    sample_path = normalized_local_path(source_samples)
    if sample_path is not None:
        append_evidence_root(roots, sample_path.parent)

    return roots


def verify_evidence_entries_with_roots(
    entries: Iterable[Any],
    roots: Iterable[Path],
) -> Tuple[bool, List[str], List[str], List[str], List[str]]:
    verified: List[str] = []
    missing: List[str] = []
    missing_hashes: List[str] = []
    hash_mismatches: List[str] = []
    for entry in entries:
        value = evidence_entry_path(entry)
        if not value:
            missing.append("<empty evidence entry>")
            continue
        expected_sha256 = evidence_entry_sha256(entry)
        uri_path = local_file_uri_path(value) if is_uri(value) else None
        if is_uri(value) and uri_path is None:
            missing.append(value)
            continue
        path = (uri_path if uri_path is not None else Path(value)).expanduser()
        candidates = [path] if path.is_absolute() else [root / path for root in roots]
        existing = next((candidate for candidate in candidates if candidate.exists()), None)
        if existing is None:
            missing.append(value)
            continue
        resolved = existing.resolve()
        verified.append(str(resolved))
        if expected_sha256 is None:
            missing_hashes.append(value)
            continue
        observed = file_sha256(resolved)
        if observed != expected_sha256:
            hash_mismatches.append(f"{value}: expected {expected_sha256}, observed {observed}")
    ok = bool(verified) and not missing and not missing_hashes and not hash_mismatches
    return (
        ok,
        unique_strings(verified),
        unique_strings(missing),
        unique_strings(missing_hashes),
        unique_strings(hash_mismatches),
    )


def sample_provenance_blockers(sample: Dict[str, Any], samples_path: Path) -> List[str]:
    if not sample_succeeded(sample):
        return []
    blockers: List[str] = []
    if not has_sample_command_provenance(sample):
        blockers.append("sample lacks command/invocation provenance")
    if not has_sample_host_provenance(sample):
        blockers.append("sample lacks host/target provenance")
    evidence_entries = sample_evidence_entries(sample)
    if not evidence_entries:
        blockers.append("sample lacks raw evidence paths or URIs")
    else:
        ok, _verified, missing, missing_hashes, hash_mismatches = verify_evidence_entries_with_roots(
            evidence_entries,
            [samples_path.parent, ROOT],
        )
        if not ok:
            blockers.append("sample raw evidence paths and sha256 digests are not all verified")
            if missing:
                blockers.append("missing sample evidence: " + ", ".join(missing))
            if missing_hashes:
                blockers.append("sample evidence lacks sha256 digest: " + ", ".join(missing_hashes))
            if hash_mismatches:
                blockers.append("sample evidence sha256 mismatch: " + "; ".join(hash_mismatches))
    return unique_strings(blockers)


def metadata_declares_benchmark_owned_json(candidate: Dict[str, Any]) -> bool:
    contract = candidate.get("timing_contract") if isinstance(candidate.get("timing_contract"), dict) else {}
    measurement_source = str(
        candidate.get("measurement_source")
        or candidate.get("timing_source")
        or contract.get("measurement_source")
        or contract.get("source")
        or ""
    ).strip().lower()
    return (
        candidate.get("benchmark_owned_json") is True
        or contract.get("benchmark_owned_json") is True
        or measurement_source in {"benchmark_owned_json", "benchmark-json", "benchmark_json"}
    )


SOURCE_CONTRACT_KEYS = ("source_contract", "paper_source_contract", "external_source_contract")
SOURCE_PROVENANCE_KEYS = (
    "paper_source",
    "source_contract",
    "paper_source_contract",
    "external_source_contract",
    "source_provenance_class",
)
NON_PAPER_EXACT_SOURCE_PROVENANCE_CLASSES = {
    "diagnostic_snapshot",
    "head",
    "head_only",
    "head_pinned",
    "non_paper_exact",
    "pinned_head",
    "reproducible_snapshot",
    "snapshot",
}


def bool_contract_value(contract: Dict[str, Any], *keys: str) -> Optional[bool]:
    for key in keys:
        value = contract.get(key)
        if isinstance(value, bool):
            return value
    return None


def source_provenance_class_from_contract(contract: Dict[str, Any]) -> str:
    if contract.get("accepted_newer_checkout_pin_complete") is True:
        return USER_ACCEPTED_NEWER_SOURCE_PROVENANCE_CLASS
    if bool_contract_value(contract, "paper_exact_ref_complete", "complete") is True:
        return "paper_exact_ref"
    if bool_contract_value(contract, "reproducible_snapshot_complete") is True:
        return "head_pinned" if contract.get("head_only") is True else "reproducible_snapshot"
    if contract.get("head_only") is True:
        return "head_only"
    return "non_paper_exact"


def source_contract_claim_grade_blockers(candidate: Dict[str, Any]) -> List[str]:
    """Return blockers when external workload provenance is reproducible but not paper-exact.

    Pinned checkouts are valuable for reproducing diagnostics, but they do not
    prove that the imported workload matches the paper's exact source unless the
    adapter also carries an exact non-HEAD paper ref/version contract.
    """

    blockers: List[str] = []
    saw_paper_exact = False
    saw_source_contract = False
    for key in SOURCE_CONTRACT_KEYS:
        contract = candidate.get(key)
        if not isinstance(contract, dict):
            continue
        saw_source_contract = True
        paper_exact = bool_contract_value(contract, "paper_exact_ref_complete", "complete")
        if paper_exact is True:
            saw_paper_exact = True
            claim_grade_complete = bool_contract_value(contract, "claim_grade_complete")
            exact_checkout_pin_complete = bool_contract_value(
                contract,
                "exact_checkout_pin_complete",
            )
            accepted_newer_checkout_pin_complete = bool_contract_value(
                contract,
                "accepted_newer_checkout_pin_complete",
                "user_accepted_newer_checkout_pin_complete",
            )
            checkout_pin = contract.get("checkout_pin") if isinstance(contract.get("checkout_pin"), dict) else {}
            exact_pin_ready = (
                exact_checkout_pin_complete is True
                and checkout_pin.get("pinned") is True
                and checkout_pin.get("exact_pinned") is True
            )
            if (
                claim_grade_complete is not True
                or (not exact_pin_ready and accepted_newer_checkout_pin_complete is not True)
            ):
                blockers.append("sample source contract is paper-exact metadata but not claim-grade exact-checkout provenance")
                if not exact_pin_ready and accepted_newer_checkout_pin_complete is not True:
                    blockers.append("sample source checkout is not pinned to the exact paper ref")
                contract_blockers = contract.get("blockers")
                if isinstance(contract_blockers, list):
                    blockers.extend(
                        f"sample source contract blocker: {item}"
                        for item in contract_blockers
                        if str(item).strip()
                    )
                elif contract_blockers:
                    blockers.append(f"sample source contract blocker: {contract_blockers}")
            continue
        accepted_newer_checkout_pin_complete = bool_contract_value(
            contract,
            "accepted_newer_checkout_pin_complete",
            "user_accepted_newer_checkout_pin_complete",
        )
        if accepted_newer_checkout_pin_complete is True:
            continue
        checkout_pin = contract.get("checkout_pin") if isinstance(contract.get("checkout_pin"), dict) else {}
        reproducible = (
            bool_contract_value(contract, "reproducible_snapshot_complete") is True
            or checkout_pin.get("pinned") is True
        )
        head_only = (
            contract.get("head_only") is True
            or (
                contract.get("has_head_ref_candidate") is True
                and contract.get("has_exact_ref_candidate") is not True
            )
        )
        if paper_exact is False or reproducible or head_only:
            if reproducible:
                blockers.append("sample source is pinned/reproducible but not paper-exact provenance")
            elif head_only:
                blockers.append("sample source is HEAD-only and not paper-exact provenance")
            else:
                blockers.append("sample source contract is not paper-exact complete")
            contract_blockers = contract.get("blockers")
            if isinstance(contract_blockers, list):
                blockers.extend(
                    f"sample source contract blocker: {item}"
                    for item in contract_blockers
                    if str(item).strip()
                )
            elif contract_blockers:
                blockers.append(f"sample source contract blocker: {contract_blockers}")
    provenance_class = str(
        candidate.get("source_provenance_class") or candidate.get("paper_source_provenance_class") or ""
    ).strip().lower()
    if (
        provenance_class in NON_PAPER_EXACT_SOURCE_PROVENANCE_CLASSES
        and not saw_paper_exact
        and (saw_source_contract or provenance_class != "snapshot")
    ):
        blockers.append(f"sample source_provenance_class={provenance_class} is not paper-exact provenance")
    return unique_strings(blockers)


def sample_claim_grade_blockers(sample: Dict[str, Any], samples_path: Optional[Path] = None) -> List[str]:
    candidates = sample_metadata_candidates(sample)
    blockers: List[str] = []
    benchmark_owned_json = any(metadata_declares_benchmark_owned_json(candidate) for candidate in candidates)
    if sample.get("template_only") is True:
        blockers.append("sample is a fill-in template record, not real evidence")
    for candidate in candidates:
        if candidate.get("diagnostic_only") is True:
            blockers.append("sample is diagnostic-only evidence, not claim-grade import evidence")
        if "claim_grade_blockers" in candidate:
            raw_blockers = candidate.get("claim_grade_blockers")
            if isinstance(raw_blockers, list):
                blockers.extend(str(item) for item in raw_blockers if str(item).strip())
            elif raw_blockers:
                blockers.append(str(raw_blockers))
        if "claim_grade" in candidate:
            value = candidate.get("claim_grade")
            is_false = value is False or str(value).strip().lower() in {"0", "false", "no", "smoke"}
            if is_false:
                blockers.append("sample explicitly marks claim_grade=false")
            elif value is True:
                reason = str(candidate.get("not_claim_grade_reason") or "").strip()
                if reason:
                    blockers.append(f"sample claims claim_grade=true but still declares not_claim_grade_reason: {reason}")
        scope = str(candidate.get("claim_grade_scope") or "").strip()
        if scope and re.search(r"(?:subset|smoke|partial|filtered)", scope, re.IGNORECASE):
            blockers.append(f"sample scope is not full paper evidence: {scope}")
        note = str(candidate.get("claim_grade_note") or "").strip()
        if note and blockers:
            blockers.append(note)
        blockers.extend(source_contract_claim_grade_blockers(candidate))
    if not benchmark_owned_json:
        blockers.append("sample does not prove benchmark_owned_json=true timing")
    blockers.extend(rpolars_sample_claim_grade_blockers(sample))
    if samples_path is not None:
        blockers.extend(sample_provenance_blockers(sample, samples_path))
    return unique_strings(blockers)


def resolve_sample_artifact_path(raw: Any, samples_path: Optional[Path]) -> Optional[Path]:
    text = str(raw or "").strip()
    if not text or is_uri(text):
        return None
    path = Path(text).expanduser()
    candidates = [path] if path.is_absolute() else []
    if samples_path is not None:
        candidates.append(samples_path.parent / path)
    candidates.append(ROOT / path)
    for candidate in candidates:
        if candidate.exists():
            return candidate
    return None


def read_sample_artifact_tail(raw: Any, samples_path: Optional[Path], *, max_chars: int = 4000) -> str:
    path = resolve_sample_artifact_path(raw, samples_path)
    if path is None:
        return ""
    try:
        return path.read_text(encoding="utf-8", errors="replace")[-max_chars:]
    except OSError:
        return ""


def has_legacy_aarch64_rust_toolchain_linker_error(haystack: str) -> bool:
    return "archive member" in haystack and "lib.rmeta" in haystack and "not a mach-o file" in haystack


def sample_failure_cause(sample: Dict[str, Any], samples_path: Optional[Path] = None) -> Optional[str]:
    if sample_succeeded(sample) and sample_successful_timing_value(sample) is not None:
        return None
    allocator = normalize_sample_allocator(sample.get("allocator") or sample.get("feature"))
    text_parts: List[str] = [
        sample.get("error"),
        sample.get("metric_error"),
        sample.get("driver_error_kind"),
        sample.get("external_workload_error_kind"),
    ]
    for candidate in sample_metadata_candidates(sample):
        text_parts.extend(
            [
                candidate.get("error"),
                candidate.get("ready_detail"),
                candidate.get("server_stderr_tail"),
                candidate.get("server_stdout_tail"),
            ]
        )
    text_parts.extend(
        [
            read_sample_artifact_tail(sample.get("stderr") or sample.get("stderr_path"), samples_path),
            read_sample_artifact_tail(sample.get("stdout") or sample.get("stdout_path"), samples_path),
        ]
    )
    haystack = "\n".join(str(part or "") for part in text_parts).lower()
    if allocator == "tcmalloc" and ("library 'tcmalloc' not found" in haystack or "-ltcmalloc" in haystack):
        return "native_tcmalloc_library_missing"
    if allocator == "snmalloc" and ("is `cmake` not installed" in haystack or "is 'cmake' not installed" in haystack):
        return "native_cmake_missing_for_snmalloc"
    if has_legacy_aarch64_rust_toolchain_linker_error(haystack):
        return "legacy_aarch64_rust_toolchain_linker_incompatible"
    if (
        "requires rustc 1.65 or newer" in haystack
        or "namespaced features with the `dep:` prefix" in haystack
        or "namespaced features with the 'dep:' prefix" in haystack
        or "-z namespaced-features" in haystack
        or "requires the `-z namespaced-features` flag" in haystack
        or "requires the '-z namespaced-features' flag" in haystack
    ):
        return "old_nightly_dependency_version_incompatible"
    if "failed to run python interpreter" in haystack and "no such file or directory" in haystack:
        return "native_python_interpreter_missing"
    if "lexical-core-0.4.0" in haystack and ("mismatched types" in haystack or "could not compile `lexical-core`" in haystack):
        return "legacy_dependency_modern_rust_incompatible"
    if "no matching package named" in haystack and ("git repository" in haystack or "location searched: git" in haystack):
        return "upstream_git_dependency_resolution_failed"
    if "timed out" in haystack or "timeout" in haystack:
        return "workload_timeout"
    if sample.get("exit_code") not in (None, 0, "0"):
        return "workload_command_failed"
    if sample.get("metric_error"):
        return "missing_finite_stdout_json_timing"
    return None


def usable_sample_geomean(samples: List[Dict[str, Any]], warmup: int) -> Optional[float]:
    ordered = sorted(enumerate(samples, start=1), key=lambda item: sample_run_index(item[1], item[0]))
    values = [sample_time_value(sample) for _, sample in ordered]
    values = [value for value in values if value is not None]
    usable = values[warmup:] if len(values) > warmup else values
    return geomean(usable)


def build_sample_groups(samples: List[Dict[str, Any]]) -> Dict[Tuple[str, str, str], List[Dict[str, Any]]]:
    groups: Dict[Tuple[str, str, str], List[Dict[str, Any]]] = {}
    for sample in samples:
        if not sample_succeeded(sample):
            continue
        dataset = str(sample.get("dataset") or sample.get("dataset_name") or "").strip()
        benchmark = str(sample.get("benchmark") or sample.get("workload") or sample.get("row") or "").strip()
        allocator = normalize_sample_allocator(sample.get("allocator") or sample.get("feature"))
        if not dataset or not benchmark or not allocator:
            continue
        if sample_time_value(sample) is None:
            continue
        groups.setdefault((dataset, benchmark, allocator), []).append(sample)
    return groups


def build_dataset_from_performance_samples(
    *,
    dataset_name: str,
    reference_ds: Dict[str, Any],
    groups: Dict[Tuple[str, str, str], List[Dict[str, Any]]],
    samples_path: Path,
    warmup: int,
    required_runs: int,
) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    columns = [str(column) for column in reference_ds.get("columns", [])]
    rows: List[Dict[str, Any]] = []
    missing_cells: List[str] = []
    missing_baselines: List[str] = []
    insufficient_samples: List[str] = []
    sample_level_blockers: List[str] = []
    sample_counts: Dict[str, Dict[str, int]] = {}
    for ref_row in reference_ds.get("rows", []):
        benchmark = str(ref_row.get("benchmark"))
        baseline_samples = groups.get((dataset_name, benchmark, "unialloc"), [])
        for blocker in unique_strings(blocker for sample in baseline_samples for blocker in sample_claim_grade_blockers(sample, samples_path)):
            sample_level_blockers.append(f"{benchmark}/unialloc: {blocker}")
        baseline = usable_sample_geomean(baseline_samples, warmup)
        sample_counts.setdefault(benchmark, {})["unialloc"] = len(baseline_samples)
        if len(baseline_samples) < required_runs:
            insufficient_samples.append(f"{benchmark}/unialloc:{len(baseline_samples)}<{required_runs}")
        if baseline is None:
            missing_baselines.append(benchmark)
            continue
        values: Dict[str, float] = {}
        for column in columns:
            column_samples = groups.get((dataset_name, benchmark, column), [])
            for blocker in unique_strings(blocker for sample in column_samples for blocker in sample_claim_grade_blockers(sample, samples_path)):
                sample_level_blockers.append(f"{benchmark}/{column}: {blocker}")
            sample_counts.setdefault(benchmark, {})[column] = len(column_samples)
            if len(column_samples) < required_runs:
                insufficient_samples.append(f"{benchmark}/{column}:{len(column_samples)}<{required_runs}")
            observed = usable_sample_geomean(column_samples, warmup)
            if observed is None:
                missing_cells.append(f"{benchmark}/{column}")
                continue
            values[column] = observed / baseline
        if values:
            rows.append({"id": ref_row.get("id") or str(len(rows) + 1), "benchmark": benchmark, "values": values})
    dataset = dataset_from_rows(
        str(samples_path),
        columns,
        rows,
        claim_grade=False,
        scope={
            "kind": "paper-performance-sample-import",
            "source_samples": str(samples_path),
            "baseline_allocator": "unialloc",
            "warmup_runs_discarded": warmup,
            "ratio_meaning": "allocator time geomean after warmup / UniAlloc time geomean after warmup; values greater than 1 mean the allocator is slower than UniAlloc",
            "complete_for_claim": False,
            "sample_counts": sample_counts,
            "missing_baselines": unique_strings(missing_baselines),
            "missing_cells": unique_strings(missing_cells),
            "insufficient_samples": unique_strings(insufficient_samples),
            "sample_claim_grade_blockers": unique_strings(sample_level_blockers),
            "required_runs_per_cell": required_runs,
        },
    )
    diagnostics = {
        "missing_baselines": unique_strings(missing_baselines),
        "missing_cells": unique_strings(missing_cells),
        "insufficient_samples": unique_strings(insufficient_samples),
        "sample_claim_grade_blockers": unique_strings(sample_level_blockers),
        "required_runs_per_cell": required_runs,
        "rows_written": len(rows),
        "columns": columns,
        "sample_counts": sample_counts,
    }
    return dataset, diagnostics




def sample_cell_key(sample: Dict[str, Any]) -> Optional[Tuple[str, str, str]]:
    dataset = str(sample.get("dataset") or sample.get("dataset_name") or "").strip()
    benchmark = str(sample.get("benchmark") or sample.get("workload") or sample.get("row") or "").strip()
    allocator = normalize_sample_allocator(sample.get("allocator") or sample.get("feature"))
    if not dataset or not benchmark or not allocator:
        return None
    return dataset, benchmark, allocator


def sample_command_option_value(command: Any, *names: str) -> str:
    if isinstance(command, str):
        try:
            tokens = shlex.split(command)
        except ValueError:
            tokens = command.split()
    elif isinstance(command, list):
        tokens = [str(item) for item in command]
    else:
        return ""
    for index, token in enumerate(tokens):
        if token in names and index + 1 < len(tokens):
            return str(tokens[index + 1]).strip()
        for name in names:
            prefix = f"{name}="
            if token.startswith(prefix):
                return token[len(prefix) :].strip()
    return ""


def command_is_cargo_bench(command: Any) -> bool:
    if isinstance(command, str):
        try:
            tokens = shlex.split(command)
        except ValueError:
            tokens = command.split()
    elif isinstance(command, list):
        tokens = [str(item) for item in command]
    else:
        return False
    for index, token in enumerate(tokens):
        if Path(str(token)).name != "cargo":
            continue
        try:
            separator = tokens.index("--", index + 1)
        except ValueError:
            separator = len(tokens)
        return "bench" in tokens[index + 1 : separator]
    return False


_RPOLARS_SURFACE_CACHE: Dict[str, Dict[str, Any]] = {}
_RPOLARS_CSV_VALIDATION_CACHE: Dict[Tuple[str, int, int], Dict[str, Any]] = {}


def cached_rpolars_bench_surfaces(checkout: Path) -> Dict[str, Any]:
    key = str(checkout)
    cached = _RPOLARS_SURFACE_CACHE.get(key)
    if cached is not None:
        return cached
    surface = parse_rust_bench_surfaces(checkout)
    _RPOLARS_SURFACE_CACHE[key] = surface
    return surface


def cached_rpolars_csv_validation(path: Path) -> Dict[str, Any]:
    try:
        stat = path.stat()
    except OSError as exc:
        return {
            "path": str(path),
            "ok": False,
            "error": str(exc),
            "sha256": None,
            "data_row_count": None,
        }
    key = (str(path), int(stat.st_size), int(stat.st_mtime_ns))
    cached = _RPOLARS_CSV_VALIDATION_CACHE.get(key)
    if cached is not None:
        return cached
    validation = rpolars_csv_sha256_and_data_rows(path)
    _RPOLARS_CSV_VALIDATION_CACHE[key] = validation
    return validation


def rpolars_sample_real_workload_dir(sample: Dict[str, Any], child: Dict[str, Any]) -> Optional[Path]:
    for candidate in (child.get("real_workload_dir"), sample.get("real_workload_dir")):
        text = str(candidate or "").strip()
        if text:
            return Path(text).expanduser()
    for command in (sample.get("command"), child.get("command")):
        value = sample_command_option_value(command, "--real-workload-dir")
        if value:
            return Path(value).expanduser()
    return None


def rpolars_sample_embedded_input_provenance(child: Dict[str, Any]) -> Dict[str, Any]:
    direct = child.get("rpolars_input_provenance")
    if isinstance(direct, dict):
        return direct
    contract = child.get("claim_grade_contract") if isinstance(child.get("claim_grade_contract"), dict) else {}
    nested = contract.get("rpolars_input_provenance")
    return nested if isinstance(nested, dict) else {}


def rpolars_sample_actual_csv_src(child: Dict[str, Any]) -> Optional[Path]:
    dependency_env = child.get("dependency_env") if isinstance(child.get("dependency_env"), dict) else {}
    fixture = dependency_env.get("polars_csv_fixture") if isinstance(dependency_env.get("polars_csv_fixture"), dict) else {}
    for candidate in (
        dependency_env.get("csv_src"),
        fixture.get("selected_csv_src"),
        fixture.get("previous_csv_src"),
    ):
        text = str(candidate or "").strip()
        if text:
            return Path(text).expanduser()
    return None


def rpolars_sample_input_provenance_blockers(child: Dict[str, Any]) -> List[str]:
    provenance = rpolars_sample_embedded_input_provenance(child)
    if not provenance:
        return ["R-Polars claim-grade sample lacks embedded input provenance"]
    configured_csv = provenance.get("configured_csv") if isinstance(provenance.get("configured_csv"), dict) else {}
    input_contract = provenance.get("input_contract") if isinstance(provenance.get("input_contract"), dict) else {}
    expected_args = (
        provenance.get("expected_datagen_args") if isinstance(provenance.get("expected_datagen_args"), dict) else {}
    )
    db_source = provenance.get("db_benchmark_source") if isinstance(provenance.get("db_benchmark_source"), dict) else {}
    blockers: List[str] = []
    if provenance.get("source") != "rpolars-input-provenance-audit":
        blockers.append("R-Polars input provenance source is not rpolars-input-provenance-audit")
    if provenance.get("required_for_targets") is not True:
        blockers.append("R-Polars input provenance does not cover csv/groupby targets")
    if provenance.get("claim_grade_ready") is not True:
        blockers.append("R-Polars input provenance is not claim_grade_ready=true")
    nested = provenance.get("blockers")
    if isinstance(nested, list):
        blockers.extend(f"R-Polars input provenance blocker: {item}" for item in nested if str(item).strip())
    elif nested:
        blockers.append(f"R-Polars input provenance blocker: {nested}")
    if configured_csv.get("exists") is not True:
        blockers.append("R-Polars configured CSV does not exist according to embedded provenance")
    if configured_csv.get("missing_columns"):
        blockers.append("R-Polars embedded input provenance reports missing CSV columns")
    expected_source = str(
        provenance.get("expected_source")
        or input_contract.get("source")
        or db_source.get("source")
        or ""
    ).strip()
    if expected_source != RPOLARS_DB_BENCHMARK_SOURCE_ID:
        blockers.append(
            "R-Polars input provenance source is not the canonical Polars db-benchmark generator"
        )
    expected_name = str(
        provenance.get("expected_csv_name")
        or input_contract.get("expected_csv_name")
        or configured_csv.get("basename")
        or ""
    ).strip()
    if expected_name != RPOLARS_DB_BENCHMARK_DEFAULT_CSV:
        blockers.append(
            "R-Polars input provenance expected CSV is not canonical: "
            f"{expected_name or '<missing>'} != {RPOLARS_DB_BENCHMARK_DEFAULT_CSV}"
        )
    canonical_rows = rpolars_parse_db_benchmark_csv_name(RPOLARS_DB_BENCHMARK_DEFAULT_CSV).get("n_rows")
    observed_rows = (
        expected_args.get("n_rows")
        or input_contract.get("expected_rows")
        or configured_csv.get("data_row_count")
    )
    if observed_rows != canonical_rows:
        blockers.append(
            "R-Polars input provenance row count is not canonical: "
            f"{observed_rows if observed_rows is not None else '<missing>'} != {canonical_rows}"
        )
    configured_rows = configured_csv.get("data_row_count")
    if configured_rows != canonical_rows:
        blockers.append(
            "R-Polars configured CSV row count is not canonical: "
            f"{configured_rows if configured_rows is not None else '<missing>'} != {canonical_rows}"
        )
    expected_sha = str(configured_csv.get("sha256") or input_contract.get("csv_sha256") or "").strip().lower()
    if not re.fullmatch(r"[0-9a-f]{64}", expected_sha):
        blockers.append("R-Polars input provenance lacks a verified 64-hex CSV sha256")
    actual_csv = rpolars_sample_actual_csv_src(child)
    if actual_csv is None:
        blockers.append("R-Polars claim-grade sample does not record actual CSV_SRC")
        return unique_strings(blockers)
    try:
        actual_resolved = actual_csv.resolve()
    except OSError:
        blockers.append(f"R-Polars actual CSV_SRC cannot be resolved: {actual_csv}")
        return unique_strings(blockers)
    if not actual_resolved.exists():
        blockers.append(f"R-Polars actual CSV_SRC does not exist: {actual_resolved}")
        return unique_strings(blockers)
    configured_path = str(configured_csv.get("resolved_path") or configured_csv.get("configured_csv_src") or "").strip()
    if configured_path:
        try:
            if Path(configured_path).expanduser().resolve() != actual_resolved:
                blockers.append("R-Polars actual CSV_SRC does not match embedded configured_csv path")
        except OSError:
            blockers.append(f"R-Polars embedded configured_csv path cannot be resolved: {configured_path}")
    if actual_resolved.name != RPOLARS_DB_BENCHMARK_DEFAULT_CSV:
        blockers.append(
            "R-Polars actual CSV_SRC basename is not canonical: "
            f"{actual_resolved.name} != {RPOLARS_DB_BENCHMARK_DEFAULT_CSV}"
        )
    missing = sorted(set(RPOLARS_GROUPBY_REQUIRED_CSV_COLUMNS) - set(rpolars_csv_header(actual_resolved)))
    if missing:
        blockers.append("R-Polars actual CSV_SRC header misses required columns: " + ", ".join(missing))
    validation = cached_rpolars_csv_validation(actual_resolved)
    if validation.get("ok") is not True:
        blockers.append(f"R-Polars actual CSV_SRC could not be hashed/counted: {validation.get('error')}")
    else:
        actual_rows = validation.get("data_row_count")
        actual_sha = str(validation.get("sha256") or "").strip().lower()
        if actual_rows != canonical_rows:
            blockers.append(
                "R-Polars actual CSV_SRC row count does not match canonical input: "
                f"{actual_rows if actual_rows is not None else '<missing>'} != {canonical_rows}"
            )
        if re.fullmatch(r"[0-9a-f]{64}", expected_sha) and actual_sha != expected_sha:
            blockers.append("R-Polars actual CSV_SRC sha256 does not match embedded input provenance")
    return unique_strings(blockers)


def rpolars_sample_source_contract_blockers(sample: Dict[str, Any], child: Dict[str, Any]) -> List[str]:
    contract_record: Dict[str, Any] = {}
    child_contract = child.get("source_contract") if isinstance(child.get("source_contract"), dict) else {}
    claim_contract = child.get("claim_grade_contract") if isinstance(child.get("claim_grade_contract"), dict) else {}
    nested_contract = (
        claim_contract.get("source_contract")
        if isinstance(claim_contract.get("source_contract"), dict)
        else {}
    )
    sample_contract = sample.get("source_contract") if isinstance(sample.get("source_contract"), dict) else {}
    source_contract = child_contract or nested_contract or sample_contract
    if not source_contract:
        return ["R-Polars claim-grade sample lacks paper source_contract provenance"]
    contract_record["source_contract"] = source_contract
    provenance_class = (
        child.get("source_provenance_class")
        or sample.get("source_provenance_class")
        or source_provenance_class_from_contract(source_contract)
    )
    if provenance_class:
        contract_record["source_provenance_class"] = provenance_class
    return source_contract_claim_grade_blockers(contract_record)


def rpolars_sample_cargo_command_blockers(sample: Dict[str, Any], child: Dict[str, Any]) -> List[str]:
    blockers: List[str] = []
    target_records = child.get("target_records") if isinstance(child.get("target_records"), list) else []
    command_records = [item for item in target_records if isinstance(item, dict)] or [{"command": child.get("command")}]
    claim_contract = child.get("claim_grade_contract") if isinstance(child.get("claim_grade_contract"), dict) else {}
    contract_targets = claim_contract.get("expected_cargo_bench_targets")
    if isinstance(contract_targets, list):
        expected_targets = {str(item).strip() for item in contract_targets if str(item).strip()}
    elif isinstance(child.get("cargo_bench_targets"), list):
        expected_targets = {str(item).strip() for item in child.get("cargo_bench_targets", []) if str(item).strip()}
    else:
        expected_targets = set(command_explicit_cargo_bench_targets(sample.get("command") or child.get("command")))
    if not expected_targets:
        expected_targets = set(command_bench_targets(child.get("command")))
    observed_targets: List[str] = []
    for item in command_records:
        command = item.get("command")
        target = str(item.get("cargo_bench_target") or "").strip()
        if not target:
            target_values = command_bench_targets(command)
            target = target_values[0] if target_values else ""
        if target:
            observed_targets.append(target)
        if not command_is_cargo_bench(command):
            blockers.append("R-Polars claim-grade sample target command is not cargo bench")
        package = sample_command_option_value(command, "--package", "-p")
        if package and package != "polars":
            blockers.append(f"R-Polars claim-grade sample targets package {package!r}, not 'polars'")
    if set(observed_targets) != expected_targets:
        missing = sorted(expected_targets - set(observed_targets))
        extra = sorted(set(observed_targets) - expected_targets)
        details = []
        if missing:
            details.append("missing " + ", ".join(missing))
        if extra:
            details.append("extra " + ", ".join(extra))
        blockers.append(
            "R-Polars claim-grade sample target_records do not cover the canonical cargo bench surface"
            + (": " + "; ".join(details) if details else "")
        )
    checkout = rpolars_sample_real_workload_dir(sample, child)
    if checkout is None:
        blockers.append("R-Polars claim-grade sample does not record --real-workload-dir")
    elif not checkout.exists():
        blockers.append(f"R-Polars claim-grade real workload checkout does not exist: {checkout}")
    else:
        surfaces = cached_rpolars_bench_surfaces(checkout)
        surface_targets = {
            str(item.get("name") or "").strip()
            for item in surfaces.get("cargo_bench_targets", [])
            if isinstance(item, dict)
        }
        missing_surface_targets = sorted(expected_targets - surface_targets)
        if missing_surface_targets:
            blockers.append(
                "R-Polars real workload checkout does not expose canonical cargo bench target(s): "
                + ", ".join(missing_surface_targets)
            )
    return unique_strings(blockers)


def rpolars_sample_claim_grade_blockers(sample: Dict[str, Any]) -> List[str]:
    key = sample_cell_key(sample)
    benchmark = key[1] if key else str(sample.get("benchmark") or sample.get("workload") or "").strip()
    if benchmark != "R-Polars":
        return []
    child = rpolars_child_record(sample)
    blockers: List[str] = []
    if child.get("claim_grade") is not True:
        blockers.append("R-Polars sample lacks explicit child claim_grade=true")
    if sample.get("claim_grade") is False:
        blockers.append("R-Polars sample explicitly marks claim_grade=false")
    contract = child.get("claim_grade_contract") if isinstance(child.get("claim_grade_contract"), dict) else {}
    if not contract:
        blockers.append("R-Polars sample lacks child claim_grade_contract")
    else:
        if contract.get("mode") != "rpolars-paper-run":
            blockers.append("R-Polars claim_grade_contract mode is not rpolars-paper-run")
        if contract.get("claim_grade_ready") is not True:
            blockers.append("R-Polars claim_grade_contract is not claim_grade_ready=true")
        nested = contract.get("blockers")
        if isinstance(nested, list):
            blockers.extend(f"R-Polars claim_grade_contract blocker: {item}" for item in nested if str(item).strip())
        elif nested:
            blockers.append(f"R-Polars claim_grade_contract blocker: {nested}")
    blockers.extend(rpolars_sample_input_provenance_blockers(child))
    blockers.extend(rpolars_sample_cargo_command_blockers(sample, child))
    blockers.extend(rpolars_sample_source_contract_blockers(sample, child))
    return unique_strings(blockers)


def sample_is_claim_grade_usable(sample: Dict[str, Any], samples_path: Path) -> bool:
    return (
        sample_succeeded(sample)
        and sample_time_value(sample) is not None
        and not sample_claim_grade_blockers(sample, samples_path)
    )


def audit_paper_performance_sample_record(
    sample: Dict[str, Any],
    index: int,
    samples_path: Path,
) -> Dict[str, Any]:
    key = sample_cell_key(sample)
    issues: List[str] = []
    failure_cause = sample_failure_cause(sample, samples_path)
    if key is None:
        if not str(sample.get("dataset") or sample.get("dataset_name") or "").strip():
            issues.append("missing dataset")
        if not str(sample.get("benchmark") or sample.get("workload") or sample.get("row") or "").strip():
            issues.append("missing benchmark/workload/row")
        if not normalize_sample_allocator(sample.get("allocator") or sample.get("feature")):
            issues.append("missing allocator/feature")
    if not sample_succeeded(sample):
        issues.append("sample status is not successful")
    if sample_successful_timing_value(sample) is None:
        issues.append("sample lacks finite positive timing")
    if failure_cause:
        issues.append(f"sample failure cause: {failure_cause}")
    issues.extend(sample_claim_grade_blockers(sample, samples_path))
    record = {
        "index": index,
        "dataset": key[0] if key else str(sample.get("dataset") or sample.get("dataset_name") or "").strip(),
        "benchmark": key[1] if key else str(sample.get("benchmark") or sample.get("workload") or sample.get("row") or "").strip(),
        "allocator": key[2] if key else normalize_sample_allocator(sample.get("allocator") or sample.get("feature")),
        "run_index": sample_run_index(sample, index),
        "issues": unique_strings(issues),
    }
    if failure_cause:
        record["failure_cause"] = failure_cause
    return record


def build_paper_performance_samples_audit(
    cfg: Dict[str, Any],
    paper_dir: Path,
    samples_path: Path,
    samples: List[Dict[str, Any]],
    *,
    dataset_names: List[str],
    required_runs: int,
) -> Dict[str, Any]:
    required_cells, target_errors = required_performance_sample_cells(cfg, paper_dir, dataset_names)
    required_keys = {
        (cell["dataset"], cell["benchmark"], cell["allocator"]): cell for cell in required_cells
    }
    raw_counts: Dict[Tuple[str, str, str], int] = {}
    usable_counts: Dict[Tuple[str, str, str], int] = {}
    audited_samples: List[Dict[str, Any]] = []
    invalid_samples: List[Dict[str, Any]] = []
    nonfinite_timing_count = 0
    failed_sample_count = 0
    template_record_count = 0
    for index, sample in enumerate(samples, start=1):
        audited = audit_paper_performance_sample_record(sample, index, samples_path)
        audited_samples.append(audited)
        if audited.get("issues"):
            invalid_samples.append(audited)
        if not sample_succeeded(sample):
            failed_sample_count += 1
        if sample_successful_timing_value(sample) is None:
            nonfinite_timing_count += 1
        if sample.get("template_only") is True:
            template_record_count += 1
        key = sample_cell_key(sample)
        if key is None:
            continue
        raw_counts[key] = raw_counts.get(key, 0) + 1
        if sample_is_claim_grade_usable(sample, samples_path):
            usable_counts[key] = usable_counts.get(key, 0) + 1

    missing_raw_cells: List[Dict[str, Any]] = []
    missing_usable_cells: List[Dict[str, Any]] = []
    insufficient_usable_cells: List[Dict[str, Any]] = []
    datasets: Dict[str, Dict[str, Any]] = {}
    for key, cell in required_keys.items():
        raw_count = raw_counts.get(key, 0)
        usable_count = usable_counts.get(key, 0)
        dataset_summary = datasets.setdefault(
            cell["dataset"],
            {
                "required_cells": 0,
                "raw_covered_cells": 0,
                "usable_covered_cells": 0,
                "missing_raw_cells": 0,
                "missing_usable_cells": 0,
                "insufficient_usable_cells": 0,
                "required_reference": cell.get("reference"),
            },
        )
        dataset_summary["required_cells"] += 1
        if raw_count > 0:
            dataset_summary["raw_covered_cells"] += 1
        else:
            dataset_summary["missing_raw_cells"] += 1
            missing_raw_cells.append({**cell, "raw_samples": raw_count, "required_runs": required_runs})
        record = {
            **cell,
            "raw_samples": raw_count,
            "usable_samples": usable_count,
            "required_runs": required_runs,
            "runs_needed": max(0, required_runs - usable_count),
        }
        if usable_count == 0:
            dataset_summary["missing_usable_cells"] += 1
            missing_usable_cells.append(record)
        elif usable_count < required_runs:
            dataset_summary["insufficient_usable_cells"] += 1
            insufficient_usable_cells.append(record)
        else:
            dataset_summary["usable_covered_cells"] += 1

    extra_cells = [
        {
            "dataset": key[0],
            "benchmark": key[1],
            "allocator": key[2],
            "raw_samples": count,
            "usable_samples": usable_counts.get(key, 0),
        }
        for key, count in sorted(raw_counts.items())
        if key not in required_keys
    ]
    ready = (
        not target_errors
        and not missing_usable_cells
        and not insufficient_usable_cells
        and not invalid_samples
    )
    return {
        "schema_version": 1,
        "generated_at": now_iso(),
        "source": "paper-performance-samples-audit",
        "samples": str(samples_path),
        "paper_dir": str(paper_dir),
        "dataset_names": dataset_names,
        "required_runs_per_cell": required_runs,
        "sample_contract": paper_performance_sample_contract(),
        "summary": {
            "ready_for_claim_grade_import": ready,
            "dataset_count": len(dataset_names),
            "record_count": len(samples),
            "required_cell_count": len(required_cells),
            "raw_covered_cell_count": sum(1 for key in required_keys if raw_counts.get(key, 0) > 0),
            "usable_covered_cell_count": sum(1 for key in required_keys if usable_counts.get(key, 0) >= required_runs),
            "missing_raw_cell_count": len(missing_raw_cells),
            "missing_usable_cell_count": len(missing_usable_cells),
            "insufficient_usable_cell_count": len(insufficient_usable_cells),
            "invalid_sample_count": len(invalid_samples),
            "failed_sample_count": failed_sample_count,
            "nonfinite_timing_count": nonfinite_timing_count,
            "template_record_count": template_record_count,
            "extra_cell_count": len(extra_cells),
            "target_error_count": len(target_errors),
        },
        "datasets": datasets,
        "target_errors": target_errors,
        "invalid_samples": invalid_samples,
        "missing_raw_cells": missing_raw_cells,
        "missing_usable_cells": missing_usable_cells,
        "insufficient_usable_cells": insufficient_usable_cells,
        "extra_cells": extra_cells,
        "audited_samples": audited_samples,
    }


def audit_paper_performance_samples(args: argparse.Namespace) -> int:
    cfg = load_config()
    paper_dir = Path(args.paper_dir or cfg.get("paper_dir_default", "")).expanduser()
    samples_path = Path(args.samples).expanduser()
    if not samples_path.exists():
        print(f"samples file not found: {samples_path}", file=sys.stderr)
        return 2
    if not paper_dir.exists():
        print(f"paper dir not found: {paper_dir}", file=sys.stderr)
        return 2
    samples = read_paper_performance_samples(samples_path)
    raw_datasets = unique_strings(
        str(sample.get("dataset") or sample.get("dataset_name") or "").strip()
        for sample in samples
        if str(sample.get("dataset") or sample.get("dataset_name") or "").strip()
    )
    dataset_names = performance_plan_dataset_names(
        cfg,
        selected=args.dataset or raw_datasets or None,
        include_all_paper_data=bool(args.all_paper_data),
    )
    required_runs = int(args.required_runs or cfg.get("methodology", {}).get("runs_per_benchmark", 6))
    audit = build_paper_performance_samples_audit(
        cfg,
        paper_dir,
        samples_path,
        samples,
        dataset_names=dataset_names,
        required_runs=required_runs,
    )
    run_id = args.run_id or _dt.datetime.now().strftime("paper-performance-samples-audit-%Y%m%d-%H%M%S")
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)
    audit_path = out_dir / "paper-performance-samples-audit.json"
    write_json(audit_path, audit)
    published_results: List[str] = []
    if not args.no_update_results:
        default_results_path = RESULTS / "paper_performance_samples_audit.json"
        write_json(default_results_path, audit)
        published_results.append(str(default_results_path))
    if args.results_out:
        results_out = Path(args.results_out).expanduser()
        write_json(results_out, audit)
        published_results.append(str(results_out))
    print(
        json.dumps(
            {
                "audit": str(audit_path),
                "published_results": published_results,
                "ready_for_claim_grade_import": audit["summary"]["ready_for_claim_grade_import"],
                "summary": audit["summary"],
            },
            indent=2,
            sort_keys=True,
        )
    )
    return 0 if audit["summary"]["ready_for_claim_grade_import"] else 1


def sample_leaf_benchmark_names(sample: Dict[str, Any]) -> List[str]:
    names: List[str] = []
    for candidate in sample_metadata_candidates(sample):
        for key in (
            "benchmarks",
            "benchmark_names",
            "parsed_benchmarks",
            "benchmarks_before_failure",
            "last_bench_rows",
        ):
            value = candidate.get(key)
            if isinstance(value, str):
                text = value.strip()
                if not text:
                    continue
                if text.startswith("["):
                    try:
                        decoded = json.loads(text)
                    except json.JSONDecodeError:
                        decoded = None
                    if isinstance(decoded, list):
                        value = decoded
                    else:
                        names.extend(part.strip() for part in text.split(",") if part.strip())
                        continue
                elif "," in text:
                    names.extend(part.strip() for part in text.split(",") if part.strip())
                    continue
                else:
                    names.append(text)
                    continue
            if isinstance(value, list):
                for item in value:
                    if isinstance(item, dict):
                        for name_key in ("name", "benchmark", "label"):
                            if str(item.get(name_key) or "").strip():
                                names.append(str(item.get(name_key)).strip())
                                break
                    elif str(item or "").strip():
                        names.append(str(item).strip())
    return unique_strings(names)


def sample_parsed_bench_row_count(sample: Dict[str, Any]) -> Optional[int]:
    for candidate in sample_metadata_candidates(sample):
        for key in ("parsed_bench_rows", "parsed_rows", "bench_row_count", "benchmark_count"):
            try:
                value = int(candidate.get(key))
            except (TypeError, ValueError):
                continue
            if value >= 0:
                return value
    names = sample_leaf_benchmark_names(sample)
    return len(names) if names else None


def command_bench_filters(command: Any) -> List[str]:
    if isinstance(command, str):
        try:
            parts = shlex.split(command)
        except ValueError:
            parts = command.split()
    elif isinstance(command, list):
        parts = [str(part) for part in command]
    else:
        parts = []
    filters: List[str] = []
    for index, part in enumerate(parts):
        if part == "--bench-filter" and index + 1 < len(parts):
            filters.append(parts[index + 1])
        elif part.startswith("--bench-filter="):
            filters.append(part.split("=", 1)[1])
        elif part == "--bench-name-filter" and index + 1 < len(parts):
            filters.append(parts[index + 1])
        elif part.startswith("--bench-name-filter="):
            filters.append(part.split("=", 1)[1])
    return unique_strings(filters)


def sample_bench_filters(sample: Dict[str, Any]) -> List[str]:
    filters: List[str] = []
    for candidate in sample_metadata_candidates(sample):
        for key in ("bench_filter", "bench_name_filter", "driver_bench_filter", "filter"):
            value = str(candidate.get(key) or "").strip()
            if value:
                filters.append(value)
        for key in ("command", "argv", "cmd", "command_line", "invocation"):
            filters.extend(command_bench_filters(candidate.get(key)))
    return unique_strings(filters)


def plan_command_claim_grade_contract(command: Any) -> str:
    if isinstance(command, str):
        try:
            parts = shlex.split(command)
        except ValueError:
            parts = command.split()
    elif isinstance(command, list):
        parts = [str(part) for part in command]
    else:
        parts = []
    for index, part in enumerate(parts):
        if part == "--claim-grade-contract" and index + 1 < len(parts):
            return parts[index + 1].strip()
        if part.startswith("--claim-grade-contract="):
            return part.split("=", 1)[1].strip()
    return ""


def workload_not_claim_grade_reasons(workload: Dict[str, Any]) -> List[str]:
    """Collect explicit non-claim metadata that must fail plan preflight.

    Local external workload configs can be promoted to configured runners while
    still carrying older non-claim diagnostic reasons.  Treat those fields as
    authoritative blockers so a plan cannot become claim-grade merely because
    `claim_grade=true` was later added at the same level.
    """

    reasons: List[str] = []
    for candidate in (
        workload,
        workload.get("cargo_bench_json_wrapper") if isinstance(workload.get("cargo_bench_json_wrapper"), dict) else {},
        workload.get("plan_claim_grade_metadata") if isinstance(workload.get("plan_claim_grade_metadata"), dict) else {},
    ):
        if not isinstance(candidate, dict):
            continue
        reason = str(candidate.get("not_claim_grade_reason") or "").strip()
        if reason:
            reasons.append(reason)
        if candidate.get("diagnostic_only") is True:
            reasons.append("workload is marked diagnostic_only=true")
        if "claim_grade" in candidate:
            value = candidate.get("claim_grade")
            if value is False or str(value).strip().lower() in {"0", "false", "no", "smoke"}:
                reasons.append("workload explicitly marks claim_grade=false")
    return unique_strings(reasons)


def workload_allows_claim_grade_leaf_filter(workload: Dict[str, Any], command_for_record: Any) -> bool:
    """Return whether a leaf-level bench filter has an explicit strict contract.

    Full paper rows should not be represented by one libtest leaf selected with
    `--bench-name-filter`.  The only accepted exception is an explicitly named
    fragment workload whose wrapper uses a strict claim-grade contract and
    records the leaf split in the plan.  Target-level splits such as the normal
    R-Oxipng plan use `--cargo-bench-targets` without a leaf filter and are not
    affected by this check.
    """

    contract = plan_command_claim_grade_contract(command_for_record)
    if contract != "roxipng-paper-fragment":
        return False
    if not str(workload.get("split_libtest_bench_function") or "").strip():
        return False
    scope = str(workload.get("claim_grade_scope") or "").strip().lower()
    if "fragment" not in scope:
        return False
    return True


CARGO_BENCH_CLAIM_GRADE_CONTRACT_BY_BENCHMARK = {
    "R-Polars": "rpolars-paper-run",
    "RJS-Compiler": "rjs-compiler-paper-run",
    "RPython": "rpython-paper-run",
    "R-Oxipng": "roxipng-paper-fragment",
    "R-Oxipng*": "roxipng-paper-fragment",
}


def cargo_bench_claim_grade_contract_requirements(
    benchmarks: Iterable[str],
) -> Tuple[Optional[str], List[str]]:
    """Return the explicit full-row contract required for cargo-bench paper rows.

    Generic cargo benches are useful diagnostics, but each paper workload needs a
    workload-specific contract before a local adapter may be promoted to
    claim-grade runner status.  The whole benchmark list is checked so a mixed
    adapter cannot smuggle an unregistered row behind a registered contract.
    """

    names = [str(benchmark).strip() for benchmark in benchmarks if str(benchmark).strip()]
    if not names:
        return None, [
            "cargo-bench JSON wrapper config has no registered benchmark-specific full-row "
            "claim-grade contract for benchmark(s): <unknown>"
        ]
    unknown = [name for name in names if name not in CARGO_BENCH_CLAIM_GRADE_CONTRACT_BY_BENCHMARK]
    contract_by_name = {
        name: CARGO_BENCH_CLAIM_GRADE_CONTRACT_BY_BENCHMARK[name]
        for name in names
        if name in CARGO_BENCH_CLAIM_GRADE_CONTRACT_BY_BENCHMARK
    }
    blockers: List[str] = []
    if unknown:
        blockers.append(
            "cargo-bench JSON wrapper config has no registered benchmark-specific full-row "
            "claim-grade contract for benchmark(s): " + ", ".join(unknown)
        )
    contracts = sorted(set(contract_by_name.values()))
    if len(contracts) > 1:
        details = ", ".join(f"{name}->{contract}" for name, contract in sorted(contract_by_name.items()))
        blockers.append(
            "cargo-bench JSON wrapper config mixes benchmarks requiring different "
            f"claim-grade contracts: {details}"
        )
    if blockers or not contracts:
        return None, blockers
    return contracts[0], []


def required_cargo_bench_claim_grade_contract(benchmarks: Iterable[str]) -> Optional[str]:
    """Compatibility wrapper for callers that only need the single safe contract."""

    contract, blockers = cargo_bench_claim_grade_contract_requirements(benchmarks)
    return None if blockers else contract


def external_adapter_config_claim_grade_runner_blockers(
    config: Dict[str, Any],
    rendered_command: Any,
    real_workload_dir: Optional[Path],
) -> List[str]:
    """Return config-audit blockers that are specific to claim-grade runner promotion.

    A local adapter can be useful and runnable for diagnostics while still being
    too narrow for claim-grade paper cells.  In particular, cargo-bench JSON
    wrapper configs that only select a representative libtest leaf must not
    promote the whole external row to `external_adapter_claim_grade_runner`.
    """

    blockers: List[str] = []
    for reason in workload_not_claim_grade_reasons(config):
        if reason == "workload explicitly marks claim_grade=false":
            continue
        blockers.append(reason)
    cargo_wrapper = isinstance(config.get("cargo_bench_json_wrapper"), dict)
    serialized_command = json.dumps(rendered_command, sort_keys=True, default=str)
    cargo_wrapper = cargo_wrapper or str(config.get("source") or "") == "paper-external-workload-cargo-bench-json-wrapper"
    cargo_wrapper = cargo_wrapper or "paper_external_cargo_bench_json.py" in serialized_command
    if not cargo_wrapper:
        return unique_strings(blockers)
    contract = plan_command_claim_grade_contract(rendered_command)
    benchmarks = wrapper_match_values(config, "benchmark", "benchmarks") or []
    required_contract, contract_blockers = cargo_bench_claim_grade_contract_requirements(benchmarks)
    blockers.extend(contract_blockers)
    if required_contract is not None and contract != required_contract:
        blockers.append(
            "cargo-bench JSON wrapper config does not request the required full-row claim-grade contract"
            + (f": {contract}" if contract else "")
            + f" (expected {required_contract})"
        )
    bench_filters = command_bench_filters(rendered_command)
    if bench_filters:
        blockers.append(
            "cargo-bench JSON wrapper representative command is bench-filtered subset evidence: "
            + ", ".join(bench_filters)
        )
    if "R-Polars" in benchmarks or contract == "rpolars-paper-run":
        blockers.extend(rpolars_input_claim_grade_blockers(config, real_workload_dir))
    return unique_strings(blockers)


