def specialized_external_paper_plan_record(rule_id: str) -> Optional[Dict[str, Any]]:
    """Return compact specialized-plan readiness for macro workload rows.

    The generic adapter config audit is deliberately conservative: a local
    representative config often remains a smoke bridge even after a stricter
    benchmark-specific plan exists.  This helper keeps those two facts separate
    so worklists can say "RJS/R-Oxipng has a real paper-equivalent execution
    plan, but timing samples/import are still missing" instead of continuing to
    describe only stale representative parser/leaf commands.
    """

    metadata = SPECIALIZED_EXTERNAL_PAPER_PLAN_AUDITS.get(str(rule_id or ""))
    if not metadata:
        return None
    audit_path = Path(metadata["audit_path"])
    plan_path = Path(metadata["plan_path"])
    record: Dict[str, Any] = {
        "rule_id": str(rule_id or ""),
        "label": metadata["label"],
        "generator": metadata["generator"],
        "audit_path": str(audit_path),
        "plan_path": str(plan_path),
        "present": False,
        "ready_for_paper_equivalent_execution": False,
        "ready_for_claim_grade_import": False,
        "blockers": [f"missing {audit_path} from {metadata['generator']}"],
    }
    audit = read_json_if_exists(audit_path)
    if not isinstance(audit, dict):
        return record
    summary = audit.get("summary") if isinstance(audit.get("summary"), dict) else {}
    blockers: List[str] = []
    raw_blockers = audit.get("blockers")
    if isinstance(raw_blockers, list):
        blockers.extend(str(item) for item in raw_blockers if str(item).strip())
    claim_import_blocker = summary.get("claim_grade_import_blocker") if isinstance(summary, dict) else None
    if claim_import_blocker:
        blockers.append(str(claim_import_blocker))
    record.update(
        {
            "present": True,
            "source": audit.get("source"),
            "summary": summary,
            "ready_for_paper_equivalent_execution": summary.get("ready_for_paper_equivalent_execution") is True,
            "ready_for_reproducible_fallback_execution": summary.get("ready_for_reproducible_fallback_execution") is True,
            "ready_for_claim_grade_execution": summary.get("ready_for_claim_grade_execution") is True,
            "ready_for_claim_grade_import": summary.get("ready_for_claim_grade_import") is True,
            "source_claim_grade_complete": summary.get("source_claim_grade_complete"),
            "planned_workload_count": summary.get("planned_workload_count"),
            "required_cell_count": summary.get("required_cell_count"),
            "dry_run_probe_count": summary.get("dry_run_probe_count"),
            "dry_run_probe_failure_count": summary.get("dry_run_probe_failure_count"),
            "invalid_workload_count": summary.get("invalid_workload_count"),
            "blockers": unique_strings(blockers),
        }
    )
    return record


def sample_allocator_routing_records(sample: Dict[str, Any]) -> List[Dict[str, Any]]:
    records: List[Dict[str, Any]] = []
    for candidate in sample_metadata_candidates(sample):
        value = candidate.get("allocator_routing")
        if isinstance(value, dict) and value not in records:
            records.append(value)
    return records


def compact_allocator_routing_record(record: Dict[str, Any]) -> Dict[str, Any]:
    compact: Dict[str, Any] = {}
    for key in (
        "source",
        "requested",
        "prepared",
        "changed",
        "allocator",
        "allocator_feature",
        "real_workload_dir",
        "claim_grade",
        "not_claim_grade_reason",
    ):
        if key in record:
            compact[key] = record.get(key)
    if isinstance(record.get("routed_command"), list):
        compact["routed_command"] = record.get("routed_command")
    preparations = record.get("preparations")
    if isinstance(preparations, list):
        compact["preparations"] = [
            {
                key: item.get(key)
                for key in (
                    "source",
                    "prepared",
                    "changed",
                    "added_dependencies",
                    "added_features",
                    "added_old_nightly_pins",
                    "bench_name",
                    "repaired_inner_attribute_order",
                    "requested_feature",
                    "routed",
                )
                if isinstance(item, dict) and key in item
            }
            for item in preparations
            if isinstance(item, dict)
        ]
    return compact


def sample_claim_grade_values(sample: Dict[str, Any]) -> List[str]:
    values: List[str] = []
    for candidate in sample_metadata_candidates(sample):
        if "claim_grade" in candidate:
            values.append(str(candidate.get("claim_grade")))
    return unique_strings(values)


def sample_claim_grade_scopes(sample: Dict[str, Any]) -> List[str]:
    scopes: List[str] = []
    for candidate in sample_metadata_candidates(sample):
        scope = str(candidate.get("claim_grade_scope") or "").strip()
        if scope:
            scopes.append(scope)
    return unique_strings(scopes)


def compact_sample_evidence(sample: Dict[str, Any]) -> List[Dict[str, Any]]:
    compact: List[Dict[str, Any]] = []
    for entry in sample_evidence_entries(sample):
        path = evidence_entry_path(entry)
        if not path:
            continue
        record: Dict[str, Any] = {"path": path}
        if isinstance(entry, dict) and str(entry.get("kind") or "").strip():
            record["kind"] = str(entry.get("kind")).strip()
        digest = evidence_entry_sha256(entry)
        if digest:
            record["sha256"] = digest
        compact.append(record)
    keyed: Dict[str, Dict[str, Any]] = {}
    order: List[str] = []
    for record in compact:
        key = f"{record.get('kind', '')}:{record['path']}"
        if key not in keyed:
            order.append(key)
            keyed[key] = record
            continue
        if "sha256" not in keyed[key] and "sha256" in record:
            keyed[key] = record
    return [keyed[key] for key in order]


def build_paper_performance_shard_audit(
    samples_path: Path,
    samples: List[Dict[str, Any]],
    *,
    dataset_names: Optional[List[str]],
) -> Dict[str, Any]:
    selected_datasets = set(dataset_names or [])
    selected_samples = [
        sample for sample in samples
        if not selected_datasets or str(sample.get("dataset") or sample.get("dataset_name") or "").strip() in selected_datasets
    ]
    invalid_records: List[Dict[str, Any]] = []
    groups: Dict[Tuple[str, str, str], List[Tuple[int, Dict[str, Any]]]] = {}
    for index, sample in enumerate(selected_samples, start=1):
        key = sample_cell_key(sample)
        if key is None:
            invalid_records.append(audit_paper_performance_sample_record(sample, index, samples_path))
            continue
        groups.setdefault(key, []).append((index, sample))

    cell_summaries: List[Dict[str, Any]] = []
    parity_by_workload: Dict[Tuple[str, str], Dict[str, Any]] = {}
    all_blockers: List[str] = []
    filtered_record_count = 0
    non_claim_grade_record_count = 0
    non_full_scope_record_count = 0
    failed_record_count = 0
    finite_timing_record_count = 0
    records_with_benchmark_lists = 0
    allocator_routed_record_count = 0
    failure_cause_counts: Dict[str, int] = {}
    observed_benchmark_union: List[str] = []

    for key, indexed_records in sorted(groups.items()):
        dataset, benchmark, allocator = key
        benchmark_names: List[str] = []
        bench_filters: List[str] = []
        claim_grade_values: List[str] = []
        claim_grade_scopes: List[str] = []
        allocator_routing_records: List[Dict[str, Any]] = []
        failure_causes: List[str] = []
        parsed_row_counts: List[int] = []
        sample_indexes: List[int] = []
        evidence: List[Dict[str, Any]] = []
        successful_samples = 0
        failed_samples = 0
        finite_timing_samples = 0
        samples_with_benchmarks = 0
        cell_blockers: List[str] = []

        for sample_index, sample in indexed_records:
            sample_indexes.append(sample_index)
            succeeded = sample_succeeded(sample)
            if succeeded:
                successful_samples += 1
            else:
                failed_samples += 1
                failed_record_count += 1
                failure_cause = sample_failure_cause(sample, samples_path)
                if failure_cause:
                    failure_causes.append(failure_cause)
                    failure_cause_counts[failure_cause] = failure_cause_counts.get(failure_cause, 0) + 1
            if sample_successful_timing_value(sample) is not None:
                finite_timing_samples += 1
                finite_timing_record_count += 1
            names = sample_leaf_benchmark_names(sample)
            if names:
                samples_with_benchmarks += 1
                records_with_benchmark_lists += 1
                benchmark_names.extend(names)
                observed_benchmark_union.extend(names)
            row_count = sample_parsed_bench_row_count(sample)
            if row_count is not None:
                parsed_row_counts.append(row_count)
            filters = sample_bench_filters(sample)
            if filters:
                filtered_record_count += 1
                bench_filters.extend(filters)
            routings = sample_allocator_routing_records(sample)
            if routings:
                allocator_routing_records.extend(routings)
                if any(routing.get("prepared") is True and routing.get("allocator_feature") for routing in routings):
                    allocator_routed_record_count += 1
            values = sample_claim_grade_values(sample)
            if any(value.lower() in {"false", "0", "no", "smoke"} for value in values):
                non_claim_grade_record_count += 1
            scopes = sample_claim_grade_scopes(sample)
            if any(re.search(r"(?:subset|smoke|partial|filtered)", scope, re.IGNORECASE) for scope in scopes):
                non_full_scope_record_count += 1
            claim_grade_values.extend(values)
            claim_grade_scopes.extend(scopes)
            blockers = sample_claim_grade_blockers(sample, samples_path)
            cell_blockers.extend(blockers)
            all_blockers.extend(blockers)
            evidence.extend(compact_sample_evidence(sample))

        observed = unique_strings(sorted(benchmark_names))
        workload = parity_by_workload.setdefault(
            (dataset, benchmark),
            {
                "dataset": dataset,
                "benchmark": benchmark,
                "allocators": {},
                "observed_benchmark_union": [],
            },
        )
        workload["allocators"][allocator] = observed
        workload["observed_benchmark_union"] = unique_strings(
            sorted(list(workload["observed_benchmark_union"]) + observed)
        )

        cell_summaries.append(
            {
                "dataset": dataset,
                "benchmark": benchmark,
                "allocator": allocator,
                "raw_sample_count": len(indexed_records),
                "successful_sample_count": successful_samples,
                "failed_sample_count": failed_samples,
                "finite_timing_sample_count": finite_timing_samples,
                "sample_indexes": sample_indexes,
                "parsed_bench_rows_values": sorted(set(parsed_row_counts)),
                "observed_benchmark_count": len(observed),
                "observed_benchmarks": observed,
                "bench_filters": unique_strings(bench_filters),
                "allocator_routing": [
                    compact_allocator_routing_record(record)
                    for record in allocator_routing_records
                ],
                "failure_causes": unique_strings(failure_causes),
                "claim_grade_values": unique_strings(claim_grade_values),
                "claim_grade_scopes": unique_strings(claim_grade_scopes),
                "claim_grade_blockers": unique_strings(cell_blockers),
                "evidence": compact_sample_evidence({"evidence": evidence}),
            }
        )

    parity_groups: List[Dict[str, Any]] = []
    parity_gap_count = 0
    for (_dataset, _benchmark), workload in sorted(parity_by_workload.items()):
        union = unique_strings(sorted(workload["observed_benchmark_union"]))
        allocators: Dict[str, Any] = {}
        for allocator, names in sorted(workload["allocators"].items()):
            missing = [name for name in union if name not in names]
            if missing:
                parity_gap_count += 1
            allocators[allocator] = {
                "observed_benchmark_count": len(names),
                "missing_from_workload_union": missing,
            }
        parity_groups.append(
            {
                "dataset": workload["dataset"],
                "benchmark": workload["benchmark"],
                "allocator_count": len(allocators),
                "observed_benchmark_union_count": len(union),
                "observed_benchmark_union": union,
                "allocators": allocators,
                "all_allocators_have_same_observed_benchmarks": all(
                    not allocator_summary["missing_from_workload_union"]
                    for allocator_summary in allocators.values()
                ),
            }
        )

    cells_missing_benchmark_lists = [
        {
            "dataset": cell["dataset"],
            "benchmark": cell["benchmark"],
            "allocator": cell["allocator"],
            "raw_sample_count": cell["raw_sample_count"],
        }
        for cell in cell_summaries
        if cell["observed_benchmark_count"] == 0
    ]
    diagnostic_blockers = unique_strings(
        [
            *(["one or more samples are bench-filtered subset evidence"] if filtered_record_count else []),
            *(["one or more samples explicitly mark claim_grade=false"] if non_claim_grade_record_count else []),
            *(["one or more samples use subset/smoke/partial claim_grade_scope"] if non_full_scope_record_count else []),
            *(["one or more samples failed"] if failed_record_count else []),
            *(["sample failure causes: " + ", ".join(f"{key}={value}" for key, value in sorted(failure_cause_counts.items()))] if failure_cause_counts else []),
            *(["one or more cells lack leaf benchmark lists"] if cells_missing_benchmark_lists else []),
            *(["allocator leaf-benchmark parity has gaps"] if parity_gap_count else []),
            *all_blockers,
        ]
    )
    return {
        "schema_version": 1,
        "generated_at": now_iso(),
        "source": "paper-performance-shard-audit",
        "samples": str(samples_path),
        "dataset_names": dataset_names or [],
        "sample_contract": paper_performance_sample_contract(),
        "summary": {
            "diagnostic_only": True,
            "ready_for_claim_grade_import": False,
            "record_count": len(samples),
            "selected_record_count": len(selected_samples),
            "excluded_record_count": len(samples) - len(selected_samples),
            "cell_count": len(cell_summaries),
            "workload_count": len(parity_groups),
            "successful_record_count": len(selected_samples) - failed_record_count,
            "failed_record_count": failed_record_count,
            "finite_timing_record_count": finite_timing_record_count,
            "records_with_benchmark_list_count": records_with_benchmark_lists,
            "allocator_routed_record_count": allocator_routed_record_count,
            "failure_cause_counts": dict(sorted(failure_cause_counts.items())),
            "observed_benchmark_union_count": len(unique_strings(sorted(observed_benchmark_union))),
            "filtered_record_count": filtered_record_count,
            "non_claim_grade_record_count": non_claim_grade_record_count,
            "non_full_scope_record_count": non_full_scope_record_count,
            "cells_missing_benchmark_list_count": len(cells_missing_benchmark_lists),
            "parity_gap_count": parity_gap_count,
            "invalid_record_count": len(invalid_records),
            "diagnostic_blocker_count": len(diagnostic_blockers),
        },
        "diagnostic_blockers": diagnostic_blockers,
        "cells": cell_summaries,
        "parity_groups": parity_groups,
        "cells_missing_benchmark_lists": cells_missing_benchmark_lists,
        "invalid_records": invalid_records,
    }


def audit_paper_performance_shards(args: argparse.Namespace) -> int:
    samples_path = Path(args.samples).expanduser()
    if not samples_path.exists():
        print(f"samples file not found: {samples_path}", file=sys.stderr)
        return 2
    samples = read_paper_performance_samples(samples_path)
    audit = build_paper_performance_shard_audit(
        samples_path,
        samples,
        dataset_names=args.dataset,
    )
    run_id = args.run_id or _dt.datetime.now().strftime("paper-performance-shard-audit-%Y%m%d-%H%M%S")
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)
    audit_path = out_dir / "paper-performance-shard-audit.json"
    write_json(audit_path, audit)
    published_results: List[str] = []
    if args.results_out:
        results_out = Path(args.results_out).expanduser()
        write_json(results_out, audit)
        published_results.append(str(results_out))
    print(
        json.dumps(
            {
                "audit": str(audit_path),
                "published_results": published_results,
                "ready_for_claim_grade_import": audit["summary"]["ready_for_claim_grade_import"],
                "summary": audit["summary"],
            },
            indent=2,
            sort_keys=True,
        )
    )
    return 0

def import_paper_performance_samples(args: argparse.Namespace) -> int:
    cfg = load_config()
    paper_dir = Path(args.paper_dir or cfg.get("paper_dir_default", "")).expanduser()
    samples_path = Path(args.samples).expanduser()
    if not samples_path.exists():
        print(f"samples file not found: {samples_path}", file=sys.stderr)
        return 2
    if not paper_dir.exists():
        print(f"paper dir not found: {paper_dir}", file=sys.stderr)
        return 2
    samples = read_paper_performance_samples(samples_path)
    raw_datasets = unique_strings(
        str(sample.get("dataset") or sample.get("dataset_name") or "").strip()
        for sample in samples
        if str(sample.get("dataset") or sample.get("dataset_name") or "").strip()
    )
    groups = build_sample_groups(samples)
    discarded_failed_samples = len([sample for sample in samples if not sample_succeeded(sample)])
    selected_datasets = args.dataset or raw_datasets or sorted({key[0] for key in groups})
    if not selected_datasets:
        print("no recognizable samples found; expected dataset/benchmark/allocator fields", file=sys.stderr)
        return 2
    run_id = args.run_id or _dt.datetime.now().strftime("paper-performance-samples-%Y%m%d-%H%M%S")
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id / "data"
    out_dir.mkdir(parents=True, exist_ok=True)
    required_runs = int(cfg.get("methodology", {}).get("runs_per_benchmark", 6))
    warmup = args.warmup if args.warmup is not None else int(cfg.get("methodology", {}).get("warmup_runs_discarded", 1))
    preflight_audit = build_paper_performance_samples_audit(
        cfg,
        paper_dir,
        samples_path,
        samples,
        dataset_names=selected_datasets,
        required_runs=required_runs,
    )
    preflight_audit_path = out_dir / "paper-performance-samples-preflight-audit.json"
    write_json(preflight_audit_path, preflight_audit)
    preflight_ready = bool(preflight_audit.get("summary", {}).get("ready_for_claim_grade_import"))
    if args.claim_grade and not preflight_ready:
        summary = {
            "schema_version": 1,
            "generated_at": now_iso(),
            "samples": str(samples_path),
            "data_dir": str(out_dir),
            "manifest": None,
            "datasets": {},
            "diagnostics": {},
            "claim_grade_requested": True,
            "discarded_failed_samples": discarded_failed_samples,
            "sample_preflight_audit": str(preflight_audit_path),
            "sample_preflight_ready_for_claim_grade": False,
            "sample_preflight_summary": preflight_audit.get("summary", {}),
            "skipped": True,
            "skip_reason": "claim-grade sample preflight failed",
        }
        write_json(out_dir / "sample-import-summary.json", summary)
        if not getattr(args, "quiet", False):
            print(json.dumps(summary, indent=2, sort_keys=True))
        return 1

    manifest: Dict[str, Any] = {
        "schema_version": 1,
        "generated_at": now_iso(),
        "source": "paper-performance-samples",
        "samples": str(samples_path),
        "paper_dir": str(paper_dir),
        "claim_grade": bool(args.claim_grade),
        "complete_for_claim": bool(args.claim_grade),
        "methodology": cfg.get("methodology", {}),
        "warmup_runs_discarded": warmup,
        "required_runs_per_cell": required_runs,
        "discarded_failed_samples": discarded_failed_samples,
        "host": host_metadata(),
        "sample_preflight_audit": str(preflight_audit_path),
        "sample_preflight_ready_for_claim_grade": preflight_ready,
        "sample_preflight_summary": preflight_audit.get("summary", {}),
        "datasets": {},
    }
    written: Dict[str, str] = {}
    diagnostics: Dict[str, Any] = {}
    exit_code = 0
    for dataset_name in selected_datasets:
        rel = cfg.get("paper_data", {}).get(dataset_name)
        if not rel:
            diagnostics[dataset_name] = {"error": "dataset is not present in evaluation/config/paper_claims.json:paper_data"}
            exit_code = 1
            continue
        ref_path = paper_dir / rel
        if not ref_path.exists():
            diagnostics[dataset_name] = {"error": f"paper reference dataset missing: {ref_path}"}
            exit_code = 1
            continue
        reference_ds = parse_dat(ref_path)
        dataset, diag = build_dataset_from_performance_samples(
            dataset_name=dataset_name,
            reference_ds=reference_ds,
            groups=groups,
            samples_path=samples_path,
            warmup=warmup,
            required_runs=required_runs,
        )
        target = out_dir / Path(rel).name
        write_dat(target, dataset)
        written[dataset_name] = str(target)
        diagnostics[dataset_name] = diag
        evidence: List[str] = [target.name, str(samples_path.resolve()), str(preflight_audit_path)]
        evidence.extend(str(item) for item in (args.evidence or []))
        blockers = unique_strings(
            [
                "sample import was not marked --claim-grade" if not args.claim_grade else None,
                "sample preflight is not ready for claim-grade import" if args.claim_grade and not preflight_ready else None,
                "missing UniAlloc baseline samples: " + ", ".join(diag.get("missing_baselines", [])) if diag.get("missing_baselines") else None,
                "missing allocator samples: " + ", ".join(diag.get("missing_cells", [])) if diag.get("missing_cells") else None,
                "insufficient repeated samples: " + ", ".join(diag.get("insufficient_samples", [])) if diag.get("insufficient_samples") else None,
                "sample-level claim-grade blockers: " + "; ".join(diag.get("sample_claim_grade_blockers", [])) if diag.get("sample_claim_grade_blockers") else None,
            ]
        )
        dataset_claim_grade = bool(args.claim_grade) and preflight_ready and not blockers
        manifest["datasets"][dataset_name] = {
            "path": target.name,
            "rows": len(dataset.get("rows", [])),
            "columns": dataset.get("columns", []),
            "claim_grade": dataset_claim_grade,
            "complete_for_claim": dataset_claim_grade,
            "evidence": evidence,
            "scope": dataset.get("scope", {}),
            "claim_grade_blockers": blockers,
        }
        if args.claim_grade and not dataset_claim_grade:
            exit_code = 1
    manifest_path = out_dir / "dataset-manifest.json"
    write_json(manifest_path, manifest)
    summary = {
        "schema_version": 1,
        "generated_at": now_iso(),
        "samples": str(samples_path),
        "data_dir": str(out_dir),
        "manifest": str(manifest_path),
        "datasets": written,
        "diagnostics": diagnostics,
        "claim_grade_requested": bool(args.claim_grade),
        "discarded_failed_samples": discarded_failed_samples,
        "sample_preflight_audit": str(preflight_audit_path),
        "sample_preflight_ready_for_claim_grade": preflight_ready,
        "sample_preflight_summary": preflight_audit.get("summary", {}),
    }
    if args.import_results:
        import_status = import_current_datasets(
            argparse.Namespace(
                data_dir=str(out_dir),
                manifest=str(manifest_path),
                dataset=args.dataset,
                quiet=True,
            )
        )
        summary["import_results"] = {
            "requested": True,
            "status": import_status,
            "summary_path": str(RESULTS / "current_datasets_summary.json"),
        }
        if import_status != 0:
            exit_code = import_status
    else:
        summary["import_results"] = {"requested": False}
    write_json(out_dir / "sample-import-summary.json", summary)
    if not getattr(args, "quiet", False):
        print(json.dumps(summary, indent=2, sort_keys=True))
    return exit_code


def slugify_label(value: Any, default: str = "workload") -> str:
    text = str(value or "").strip()
    text = re.sub(r"[^A-Za-z0-9_.-]+", "-", text).strip("-._")
    return text[:96] or default


def plan_workload_label(workload: Dict[str, Any], index: int) -> str:
    explicit = workload.get("label") or workload.get("name")
    if explicit:
        return slugify_label(explicit, f"workload-{index}")
    parts = [
        workload.get("dataset"),
        workload.get("benchmark") or workload.get("workload") or workload.get("row"),
        workload.get("allocator") or workload.get("feature"),
    ]
    return slugify_label("-".join(str(part) for part in parts if part), f"workload-{index}")


def resolve_plan_cwd(raw_cwd: Any) -> Path:
    if raw_cwd is None or str(raw_cwd).strip() == "":
        return ROOT
    path = Path(str(raw_cwd)).expanduser()
    if path.is_absolute():
        return path
    return ROOT / path


def normalize_plan_command(workload: Dict[str, Any]) -> Tuple[Any, bool, List[str]]:
    shell = bool(workload.get("shell"))
    command = workload.get("command")
    if command is None:
        raise ValueError("workload is missing required field: command")
    if shell:
        if isinstance(command, list):
            rendered = " ".join(shlex.quote(str(part)) for part in command)
        else:
            rendered = str(command)
        return rendered, True, [rendered]
    if isinstance(command, list):
        argv = [str(part) for part in command]
    else:
        argv = shlex.split(str(command))
    if not argv:
        raise ValueError("workload command is empty")
    return argv, False, argv


def command_option_value(command: List[str], option: str) -> Optional[str]:
    for index, token in enumerate(command):
        if token == option and index + 1 < len(command):
            return str(command[index + 1])
        prefix = f"{option}="
        if token.startswith(prefix):
            return token[len(prefix) :]
    return None


def paper_plan_subprocess_timeout(
    command: List[str],
    *,
    workload_timeout: int,
) -> Tuple[int, Optional[Dict[str, Any]]]:
    """Return the outer process timeout for a plan workload.

    Some plan entries run a wrapper that itself applies a timeout to each
    concrete child benchmark.  The outer plan runner must give that wrapper
    enough room to report structured target-level failure JSON; otherwise the
    outer runner kills the wrapper at the same deadline and loses the completed
    target evidence.
    """

    if not any(Path(str(token)).name == "paper_external_cargo_bench_json.py" for token in command):
        return workload_timeout, None
    targets_value = command_option_value(command, "--cargo-bench-targets") or ""
    target_count = len([part for part in targets_value.split(",") if part.strip()]) or 1
    inner_timeout_raw = command_option_value(command, "--timeout")
    try:
        inner_timeout = int(inner_timeout_raw) if inner_timeout_raw else workload_timeout
    except ValueError:
        inner_timeout = workload_timeout
    outer_timeout = max(workload_timeout, inner_timeout * target_count + 120)
    if outer_timeout == workload_timeout:
        return outer_timeout, None
    return outer_timeout, {
        "source": "paper-performance-plan-outer-timeout",
        "reason": "multi-target cargo wrapper needs outer grace so it can emit structured target-level timeout/failure JSON",
        "wrapper": "paper_external_cargo_bench_json.py",
        "target_count": target_count,
        "inner_timeout_seconds": inner_timeout,
        "workload_timeout_seconds": workload_timeout,
        "outer_timeout_seconds": outer_timeout,
    }


def json_last_object(path: Path) -> Optional[Dict[str, Any]]:
    if not path.exists():
        return None
    for raw in reversed(path.read_text(encoding="utf-8", errors="replace").splitlines()):
        line = raw.strip()
        if not line:
            continue
        try:
            value = json.loads(line)
        except json.JSONDecodeError:
            continue
        if isinstance(value, dict):
            return value
    return None


def stdout_json_last_object(stdout: Path) -> Optional[Dict[str, Any]]:
    return json_last_object(stdout)


EXTERNAL_WORKLOAD_JSON_SOURCES = {
    "paper-external-workload-adapter",
    "paper-external-cargo-bench-json",
    "paper-external-http-load-json",
    "paper-external-redis-load-json",
    "paper-external-redis-benchmark-json",
}


def compact_driver_error_metadata(metadata: Dict[str, Any]) -> Dict[str, Any]:
    compact: Dict[str, Any] = {}
    for key in (
        "source",
        "error",
        "code",
        "command",
        "timeout_seconds",
        "parsed_bench_rows",
        "benchmarks_before_failure",
        "last_bench_rows",
    ):
        if key in metadata:
            compact[key] = metadata.get(key)
    for key in ("stdout_tail", "stderr_tail"):
        value = metadata.get(key)
        if isinstance(value, str) and value:
            compact[key] = value[-1000:]
    return compact


def stderr_driver_error_metadata(stderr: Path) -> Optional[Dict[str, Any]]:
    value = json_last_object(stderr)
    if not isinstance(value, dict):
        return None
    if value.get("source") != "paper-workload-driver":
        return None
    if value.get("ok") is not False:
        return None
    return value


def compact_external_workload_metadata(metadata: Dict[str, Any]) -> Dict[str, Any]:
    compact: Dict[str, Any] = {}
    for key in (
        "source",
        "error",
        "command",
        "cwd",
        "child_returncode",
        "child_json_found",
        "seconds_found",
        "claim_grade",
        "claim_grade_blockers",
        "adapter_configured",
        "bench_name_filter",
        "benchmark_owned_json",
        "measurement_source",
        "measurement_sources",
        "dataset",
        "benchmark",
        "allocator",
        "variant_feature",
        "run_index",
        "uses_redis_benchmark",
        "uses_resp_bridge",
        "source_provenance_class",
    ):
        if key in metadata:
            compact[key] = metadata.get(key)
    for key in (
        "selector_contract",
        "timing_contract",
        "source_contract",
        "paper_source",
        "external_rustup_toolchain",
        "paper_context",
    ):
        value = metadata.get(key)
        if isinstance(value, dict):
            compact[key] = value
    return compact


def external_workload_json_metadata(stdout: Path, stderr: Path) -> Optional[Dict[str, Any]]:
    candidates = [stdout_json_last_object(stdout), json_last_object(stderr)]
    for value in candidates:
        if not isinstance(value, dict):
            continue
        source = str(value.get("source") or "")
        if source in EXTERNAL_WORKLOAD_JSON_SOURCES:
            return value
        if value.get("adapter_configured") is not None or "claim_grade_blockers" in value:
            return value
    return None


def stdout_json_timing_seconds(stdout: Path, fields: List[str]) -> Tuple[Optional[float], Optional[Dict[str, Any]]]:
    supported_time_fields = {
        "seconds",
        "time_seconds",
        "wall_seconds",
        "elapsed_seconds",
        "ns_per_iter",
        "time_ns",
        "nanoseconds",
        "ms",
        "milliseconds",
    }
    value = stdout_json_last_object(stdout)
    if value is None:
        return None, None
    if fields:
        for field in fields:
            if field not in value:
                continue
            if field in supported_time_fields:
                converted = sample_time_value({field: value.get(field)})
            else:
                converted = finite_number(value.get(field))
            if converted is not None:
                return converted, value
    else:
        converted = sample_time_value(value)
        if converted is not None:
            return converted, value
    return None, value


def claim_grade_blocker_values(value: Any) -> List[str]:
    if value is None:
        return []
    if isinstance(value, list):
        return [str(item).strip() for item in value if str(item).strip()]
    text = str(value).strip()
    return [text] if text else []


def apply_plan_claim_grade_metadata(record: Dict[str, Any], workload: Dict[str, Any]) -> None:
    """Propagate plan-level claim limits onto emitted raw samples.

    Adapter wrappers often emit their own metric JSON.  A plan can be more
    restrictive than that metric source: for example a Darwin ptmalloc selector
    smoke run may successfully route cargo bench while still being only a
    std::alloc::System plumbing check, not Linux/glibc ptmalloc paper evidence.
    Keep those plan-level constraints at the top level so sample audits and
    overclaim worklists cannot accidentally treat a successful adapter bridge as
    broader evidence.
    """

    metadata: Dict[str, Any] = {}
    provenance = record.get("provenance")
    if not isinstance(provenance, dict):
        provenance = {}
        record["provenance"] = provenance
    for key in SOURCE_PROVENANCE_KEYS:
        if key not in workload:
            continue
        value = copy.deepcopy(workload.get(key))
        record[key] = value
        provenance[key] = copy.deepcopy(value)
        metadata[key] = copy.deepcopy(value)
    if "claim_grade" in workload:
        workload_claim_grade = workload.get("claim_grade")
        metadata["claim_grade"] = workload_claim_grade
        if isinstance(workload_claim_grade, bool):
            existing = record.get("claim_grade")
            if existing is False or workload_claim_grade is False:
                record["claim_grade"] = False
            elif "claim_grade" not in record:
                record["claim_grade"] = True
    scope = str(workload.get("claim_grade_scope") or "").strip()
    if scope:
        previous_scope = str(record.get("claim_grade_scope") or "").strip()
        if previous_scope and previous_scope != scope:
            record.setdefault("metric_claim_grade_scope", previous_scope)
        record["claim_grade_scope"] = scope
        metadata["claim_grade_scope"] = scope
    note = str(workload.get("claim_grade_note") or "").strip()
    if note:
        previous_note = str(record.get("claim_grade_note") or "").strip()
        if previous_note and previous_note != note:
            record.setdefault("metric_claim_grade_note", previous_note)
            record["claim_grade_note"] = f"{previous_note}; plan: {note}"
        else:
            record["claim_grade_note"] = note
        metadata["claim_grade_note"] = note
    plan_blockers = claim_grade_blocker_values(workload.get("claim_grade_blockers"))
    if plan_blockers:
        record["claim_grade_blockers"] = unique_strings(
            [*claim_grade_blocker_values(record.get("claim_grade_blockers")), *plan_blockers]
        )
        metadata["claim_grade_blockers"] = plan_blockers
    source_blockers = source_contract_claim_grade_blockers(workload)
    if source_blockers:
        record["claim_grade"] = False
        record["claim_grade_blockers"] = unique_strings(
            [*claim_grade_blocker_values(record.get("claim_grade_blockers")), *source_blockers]
        )
        metadata["source_contract_blockers"] = source_blockers
    if metadata:
        record["plan_claim_grade_metadata"] = metadata


def select_plan_sample_seconds(
    workload: Dict[str, Any],
    stdout: Path,
    wall_seconds: float,
) -> Tuple[Optional[float], str, Optional[str], Optional[Dict[str, Any]]]:
    fields: List[str] = []
    if workload.get("time_field"):
        fields.append(str(workload.get("time_field")))
    for item in workload.get("time_fields", []) or []:
        fields.append(str(item))
    measurement = str(workload.get("measurement") or workload.get("time_source") or "").strip().lower()
    if not measurement:
        measurement = "stdout_json" if fields else "wall_seconds"
    if measurement in {"stdout_json", "json", "auto"}:
        parsed, metadata = stdout_json_timing_seconds(stdout, fields)
        if parsed is not None:
            return parsed, "stdout_json", None, metadata
        if measurement != "auto":
            wanted = ", ".join(fields) if fields else "standard timing fields"
            return None, "stdout_json", f"stdout JSON timing not found ({wanted})", metadata
    return wall_seconds, "wall_seconds", None, None


def terminate_process_group(proc: subprocess.Popen[Any], *, grace_seconds: float = 2.0) -> bool:
    """Terminate a workload subprocess and any children it spawned."""
    if proc.poll() is not None:
        return False
    try:
        if os.name == "posix":
            os.killpg(proc.pid, signal.SIGTERM)
        else:  # pragma: no cover - non-posix fallback for Windows runners.
            proc.terminate()
        try:
            proc.wait(timeout=grace_seconds)
        except subprocess.TimeoutExpired:
            if os.name == "posix":
                os.killpg(proc.pid, signal.SIGKILL)
            else:  # pragma: no cover - non-posix fallback for Windows runners.
                proc.kill()
            proc.wait(timeout=grace_seconds)
        return True
    except ProcessLookupError:
        return False


def positive_int_value(value: Any, default: int) -> int:
    try:
        parsed = int(value)
    except (TypeError, ValueError):
        return default
    return parsed if parsed > 0 else default


class BoundedPipeCapture:
    """Drain a child pipe while retaining only a bounded tail in memory."""

    def __init__(self, pipe: Any, max_bytes: int) -> None:
        self.pipe = pipe
        self.max_bytes = max(1, int(max_bytes))
        self.total_bytes = 0
        self._tail = bytearray()
        self.thread = threading.Thread(target=self._drain, daemon=True)

    def start(self) -> None:
        self.thread.start()

    def join(self, timeout: float = 5.0) -> None:
        self.thread.join(timeout=timeout)

    def _drain(self) -> None:
        try:
            while True:
                chunk = self.pipe.read(64 * 1024)
                if not chunk:
                    break
                if isinstance(chunk, str):
                    chunk = chunk.encode("utf-8", errors="replace")
                self.total_bytes += len(chunk)
                self._tail.extend(chunk)
                if len(self._tail) > self.max_bytes:
                    del self._tail[: len(self._tail) - self.max_bytes]
        finally:
            try:
                self.pipe.close()
            except Exception:
                pass

    @property
    def retained_bytes(self) -> int:
        return len(self._tail)

    @property
    def truncated(self) -> bool:
        return self.total_bytes > self.retained_bytes

    def bytes(self) -> bytes:
        return bytes(self._tail)


def run_plan_command_bounded(
    command: Any,
    *,
    cwd: Path,
    env: Dict[str, str],
    shell: bool,
    timeout_seconds: int,
    max_output_bytes: int,
) -> Dict[str, Any]:
    """Run a plan command without allowing stdout/stderr to grow unbounded."""

    started_at = now_iso()
    try:
        proc = subprocess.Popen(
            command,
            cwd=str(cwd),
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            shell=shell,
            start_new_session=(os.name == "posix"),
        )
    except FileNotFoundError as exc:
        return {
            "exit_code": 127,
            "error": str(exc),
            "stdout_tail": b"",
            "stderr_tail": b"",
            "stdout_bytes": 0,
            "stderr_bytes": 0,
            "stdout_retained_bytes": 0,
            "stderr_retained_bytes": 0,
            "stdout_truncated": False,
            "stderr_truncated": False,
            "process_group_pid": None,
            "process_group_terminated": False,
            "started_at": started_at,
            "ended_at": now_iso(),
        }
    assert proc.stdout is not None
    assert proc.stderr is not None
    stdout_capture = BoundedPipeCapture(proc.stdout, max_output_bytes)
    stderr_capture = BoundedPipeCapture(proc.stderr, max_output_bytes)
    stdout_capture.start()
    stderr_capture.start()
    error = None
    process_group_terminated = False
    try:
        exit_code = proc.wait(timeout=timeout_seconds)
    except subprocess.TimeoutExpired as exc:
        exit_code = 124
        error = f"timeout after {timeout_seconds}s: {exc}"
        process_group_terminated = terminate_process_group(proc)
    except KeyboardInterrupt:
        terminate_process_group(proc)
        raise
    finally:
        stdout_capture.join()
        stderr_capture.join()
    return {
        "exit_code": exit_code,
        "error": error,
        "stdout_tail": stdout_capture.bytes(),
        "stderr_tail": stderr_capture.bytes(),
        "stdout_bytes": stdout_capture.total_bytes,
        "stderr_bytes": stderr_capture.total_bytes,
        "stdout_retained_bytes": stdout_capture.retained_bytes,
        "stderr_retained_bytes": stderr_capture.retained_bytes,
        "stdout_truncated": stdout_capture.truncated,
        "stderr_truncated": stderr_capture.truncated,
        "process_group_pid": proc.pid,
        "process_group_terminated": process_group_terminated,
        "started_at": started_at,
        "ended_at": now_iso(),
    }


def apply_plan_output_claim_grade_blockers(
    record: Dict[str, Any],
    blockers: Iterable[Any],
) -> None:
    values = unique_strings(blockers)
    if not values:
        return
    record["claim_grade"] = False
    record["claim_grade_blockers"] = unique_strings(
        [*claim_grade_blocker_values(record.get("claim_grade_blockers")), *values]
    )


def run_paper_performance_plan_one(
    *,
    workload: Dict[str, Any],
    workload_index: int,
    run_index: int,
    out_dir: Path,
    default_timeout: int,
    default_max_output_bytes: int,
    run_id: str,
) -> Dict[str, Any]:
    dataset = str(workload.get("dataset") or workload.get("dataset_name") or "").strip()
    benchmark = str(workload.get("benchmark") or workload.get("workload") or workload.get("row") or "").strip()
    allocator_input = workload.get("allocator") or workload.get("feature")
    allocator = normalize_sample_allocator(allocator_input)
    if not dataset:
        raise ValueError("workload is missing required field: dataset")
    if not benchmark:
        raise ValueError("workload is missing required field: benchmark/workload/row")
    if not allocator:
        raise ValueError("workload is missing required field: allocator/feature")
    runtime_template_fields = {"run_index": str(run_index)}
    runtime_workload = dict(workload)
    for key in ("command", "cwd", "env"):
        if key in runtime_workload and any(
            template_uses_placeholder(runtime_workload.get(key), placeholder)
            for placeholder in ADAPTER_SELECTOR_PLACEHOLDERS
        ):
            runtime_workload[key] = render_paper_performance_template_value(
                runtime_workload.get(key),
                runtime_workload,
                extra_fields=runtime_template_fields,
            )
    command, shell, command_for_record = normalize_plan_command(runtime_workload)
    cwd = resolve_plan_cwd(runtime_workload.get("cwd"))
    label = f"{workload_index:03d}-{plan_workload_label(workload, workload_index)}-run{run_index}"
    log_dir = out_dir / "logs"
    log_dir.mkdir(parents=True, exist_ok=True)
    stdout = log_dir / f"{label}.stdout.txt"
    stderr = log_dir / f"{label}.stderr.txt"
    env = os.environ.copy()
    env.setdefault("GLIBC_TUNABLES", "glibc.pthread.rseq=0")
    for key, value in (runtime_workload.get("env") or {}).items():
        env[str(key)] = str(value)
    workload_timeout = int(runtime_workload.get("timeout") or default_timeout)
    timeout, outer_timeout_record = paper_plan_subprocess_timeout(
        command_for_record,
        workload_timeout=workload_timeout,
    )
    max_output_bytes = positive_int_value(
        runtime_workload.get("max_output_bytes") or runtime_workload.get("max_log_bytes"),
        default_max_output_bytes,
    )
    started = now_iso()
    start = time.perf_counter()
    try:
        child_result = run_plan_command_bounded(
            command,
            cwd=cwd,
            env=env,
            shell=shell,
            timeout_seconds=timeout,
            max_output_bytes=max_output_bytes,
        )
    except KeyboardInterrupt:
        raise
    except Exception as exc:  # pragma: no cover - diagnostic safety net
        child_result = {
            "exit_code": 1,
            "error": str(exc),
            "stdout_tail": b"",
            "stderr_tail": b"",
            "stdout_bytes": 0,
            "stderr_bytes": 0,
            "stdout_retained_bytes": 0,
            "stderr_retained_bytes": 0,
            "stdout_truncated": False,
            "stderr_truncated": False,
            "process_group_pid": None,
            "process_group_terminated": False,
            "started_at": started,
            "ended_at": now_iso(),
        }
    stdout.write_bytes(child_result.get("stdout_tail", b""))
    stderr.write_bytes(child_result.get("stderr_tail", b""))
    exit_code = int(child_result.get("exit_code") or 0)
    error = child_result.get("error")
    process_group_pid = child_result.get("process_group_pid")
    process_group_terminated = bool(child_result.get("process_group_terminated"))
    wall = time.perf_counter() - start
    started = str(child_result.get("started_at") or started)
    ended = str(child_result.get("ended_at") or now_iso())
    seconds, measurement_source, metric_error, metric_metadata = select_plan_sample_seconds(workload, stdout, wall)
    success = exit_code == 0 and seconds is not None and metric_error is None
    host = host_metadata()
    evidence = [
        {"kind": "stdout", "path": str(stdout), "sha256": file_sha256(stdout)},
        {"kind": "stderr", "path": str(stderr), "sha256": file_sha256(stderr)},
    ]
    record = {
        "schema_version": 1,
        "source": "paper-performance-plan-run",
        "run_id": run_id,
        "label": label,
        "workload_index": workload_index,
        "workload_label": plan_workload_label(workload, workload_index),
        "dataset": dataset,
        "benchmark": benchmark,
        "allocator": allocator,
        "allocator_input": allocator_input,
        "run_index": run_index,
        "command": command_for_record,
        "shell": shell,
        "cwd": str(cwd),
        "host": host,
        "provenance": {
            "run_id": run_id,
            "workload_index": workload_index,
            "workload_label": plan_workload_label(workload, workload_index),
            "command": command_for_record,
            "cwd": str(cwd),
            "host": host,
            "measurement_source": measurement_source,
        },
        "timeout_seconds": timeout,
        "workload_timeout_seconds": workload_timeout,
        "max_output_bytes": max_output_bytes,
        "started_at": started,
        "ended_at": ended,
        "wall_seconds": wall,
        "seconds": seconds,
        "measurement_source": measurement_source,
        "exit_code": exit_code,
        "success": success,
        "stdout": str(stdout),
        "stderr": str(stderr),
        "stdout_bytes": child_result.get("stdout_bytes"),
        "stderr_bytes": child_result.get("stderr_bytes"),
        "stdout_retained_bytes": child_result.get("stdout_retained_bytes"),
        "stderr_retained_bytes": child_result.get("stderr_retained_bytes"),
        "stdout_truncated": child_result.get("stdout_truncated"),
        "stderr_truncated": child_result.get("stderr_truncated"),
        "evidence": evidence,
        "error": error,
        "metric_error": metric_error,
        "process_group_pid": process_group_pid,
        "process_group_terminated": process_group_terminated,
        # `benchmark` is the paper row name (for example, Collections).
        # `benchmark_names` is reserved for concrete leaf benchmarks parsed from
        # the workload's raw output so shard audits do not confuse a paper row
        # with the actually measured libtest rows.
        "benchmark_names": [],
    }
    for key in (
        "plan_fragment_id",
        "target_split",
        "split_cargo_bench_target",
        "target_leaf_split",
        "split_libtest_bench_function",
        "selected_cargo_bench_targets",
        "selected_libtest_bench_functions",
        "expected_cargo_bench_targets",
        "expected_libtest_bench_functions",
        "expected_libtest_bench_functions_by_target",
        "wrapper_manifest_rule_id",
        *SOURCE_PROVENANCE_KEYS,
    ):
        if key in workload:
            value = copy.deepcopy(workload.get(key))
            record[key] = value
            if isinstance(record.get("provenance"), dict):
                record["provenance"][key] = copy.deepcopy(value)
    if metric_metadata is not None:
        record["metric_metadata"] = metric_metadata
        for key in (
            "benchmarks",
            "benchmark_names",
            "bench_filter",
            "claim_grade",
            "claim_grade_scope",
            "claim_grade_note",
            "claim_grade_blockers",
            "ns_per_iter",
            "parsed_bench_rows",
            "variant_feature",
            "features",
            "bench_row_count",
            "bench_rows",
            "cargo_bench_targets",
            "target_records",
            "multi_target",
            "benchmark_owned_json",
            "rule_benchmark_owned_json",
            "child_benchmark_owned_json",
            "timing_contract",
            "measurement_sources",
            *SOURCE_PROVENANCE_KEYS,
        ):
            if key in metric_metadata and key not in record:
                record[key] = metric_metadata.get(key)
        if isinstance(metric_metadata.get("benchmarks"), list):
            record["benchmark_names"] = [
                str(item).strip()
                for item in metric_metadata.get("benchmarks", [])
                if str(item).strip()
            ]
        metric_source_blockers = source_contract_claim_grade_blockers(metric_metadata)
        if metric_source_blockers:
            apply_plan_output_claim_grade_blockers(record, metric_source_blockers)
    if outer_timeout_record is not None:
        record["outer_timeout"] = outer_timeout_record
    apply_plan_claim_grade_metadata(record, workload)
    output_blockers: List[str] = []
    if child_result.get("stdout_truncated"):
        output_blockers.append(f"plan stdout exceeded max-output-bytes={max_output_bytes}; retained tail only")
    if child_result.get("stderr_truncated"):
        output_blockers.append(f"plan stderr exceeded max-output-bytes={max_output_bytes}; retained tail only")
    apply_plan_output_claim_grade_blockers(record, output_blockers)
    driver_error_metadata = None
    if exit_code != 0 or metric_error is not None:
        driver_error_metadata = stderr_driver_error_metadata(stderr)
    if driver_error_metadata is not None:
        driver_error = compact_driver_error_metadata(driver_error_metadata)
        record["driver_error"] = driver_error
        record["driver_error_kind"] = driver_error_metadata.get("error")
        record["driver_error_code"] = driver_error_metadata.get("code")
        for key in ("parsed_bench_rows", "benchmarks_before_failure", "last_bench_rows"):
            if key in driver_error_metadata and key not in record:
                record[key] = driver_error_metadata.get(key)
    external_metadata = external_workload_json_metadata(stdout, stderr)
    if external_metadata is not None:
        external_compact = compact_external_workload_metadata(external_metadata)
        record["external_workload_metadata"] = external_compact
        if exit_code != 0 or metric_error is not None or external_metadata.get("error"):
            record["external_workload_error"] = external_compact
            record["external_workload_error_kind"] = external_metadata.get("error")
            record["external_workload_child_returncode"] = external_metadata.get("child_returncode")
        record["external_workload_source"] = external_metadata.get("source")
        external_blockers = claim_grade_blocker_values(external_metadata.get("claim_grade_blockers"))
        if external_blockers:
            apply_plan_output_claim_grade_blockers(record, external_blockers)
        for key in (
            "cargo_bench_target",
            "cargo_bench_targets",
            "target_records",
            "partial_bench_row_count",
            "partial_bench_rows",
            "timed_out",
            "benchmark_owned_json",
            "rule_benchmark_owned_json",
            "child_benchmark_owned_json",
            "timing_contract",
            "measurement_sources",
            *SOURCE_PROVENANCE_KEYS,
        ):
            if key in external_metadata and key not in record:
                record[key] = external_metadata.get(key)
        external_source_blockers = source_contract_claim_grade_blockers(external_metadata)
        if external_source_blockers:
            apply_plan_output_claim_grade_blockers(record, external_source_blockers)
    return record


def plan_dataset_names_for_audit(
    cfg: Dict[str, Any],
    plan: Dict[str, Any],
    selected: Optional[List[str]],
) -> List[str]:
    if selected:
        return performance_plan_dataset_names(cfg, selected=selected)
    raw_plan_datasets = plan.get("dataset_names") if isinstance(plan, dict) else None
    if isinstance(raw_plan_datasets, list) and raw_plan_datasets:
        return performance_plan_dataset_names(cfg, selected=[str(item) for item in raw_plan_datasets])
    workloads = plan.get("workloads") if isinstance(plan, dict) else None
    observed: List[str] = []
    if isinstance(workloads, list):
        for workload in workloads:
            if not isinstance(workload, dict):
                continue
            dataset = str(workload.get("dataset") or workload.get("dataset_name") or "").strip()
            if dataset:
                observed.append(dataset)
    if observed:
        return performance_plan_dataset_names(cfg, selected=observed)
    return performance_plan_dataset_names(cfg, selected=None)


def write_plan_preflight_audit(
    cfg: Dict[str, Any],
    plan: Dict[str, Any],
    *,
    paper_dir: Path,
    out_dir: Path,
    selected_datasets: Optional[List[str]],
    selected_benchmarks: Optional[List[str]] = None,
    selected_allocators: Optional[List[str]] = None,
    default_runs: int,
    required_runs: int,
    dry_run_probe: bool = False,
    dry_run_probe_limit: int = 0,
    dry_run_probe_timeout: int = 30,
) -> Tuple[Dict[str, Any], Path]:
    dataset_names = plan_dataset_names_for_audit(cfg, plan, selected_datasets)
    audit = build_paper_performance_plan_audit(
        cfg,
        paper_dir,
        plan,
        dataset_names=dataset_names,
        default_runs=default_runs,
        required_runs=required_runs,
        benchmark_names=selected_benchmarks,
        allocator_names=selected_allocators,
        dry_run_probe=dry_run_probe,
        dry_run_probe_limit=dry_run_probe_limit,
        dry_run_probe_timeout=dry_run_probe_timeout,
    )
    audit_path = out_dir / "paper-performance-plan-preflight-audit.json"
    write_json(audit_path, audit)
    return audit, audit_path


def plan_sample_resume_key(record: Dict[str, Any], run_index: Optional[int] = None) -> Optional[Tuple[Any, ...]]:
    key = sample_cell_key(record)
    if key is None:
        return None
    try:
        resolved_run_index = int(run_index if run_index is not None else sample_run_index(record, 0))
    except (TypeError, ValueError):
        return None
    if resolved_run_index <= 0:
        return None
    fragment = str(record.get("plan_fragment_id") or record.get("split_cargo_bench_target") or "").strip()
    if fragment:
        return key[0], key[1], key[2], resolved_run_index, fragment
    return key[0], key[1], key[2], resolved_run_index


def sample_is_resumable_success(record: Dict[str, Any]) -> bool:
    return sample_succeeded(record) and sample_time_value(record) is not None


def load_resumable_paper_plan_samples(samples_path: Path) -> Tuple[Dict[Tuple[Any, ...], Dict[str, Any]], Dict[str, Any]]:
    summary: Dict[str, Any] = {
        "resume_source": str(samples_path),
        "resume_source_exists": samples_path.exists(),
        "resume_source_archive": None,
        "resume_source_record_count": 0,
        "resume_successful_record_count": 0,
        "resume_duplicate_successful_record_count": 0,
        "resume_ineligible_record_count": 0,
        "resume_unmatched_successful_record_count": 0,
    }
    if not samples_path.exists():
        return {}, summary
    archive_path = samples_path.with_name(
        f"{samples_path.stem}.resume-source-{_dt.datetime.now(_dt.timezone.utc).strftime('%Y%m%d-%H%M%S')}{samples_path.suffix}"
    )
    shutil.copy2(samples_path, archive_path)
    summary["resume_source_archive"] = str(archive_path)
    records = read_paper_performance_samples(samples_path)
    summary["resume_source_record_count"] = len(records)
    resumable: Dict[Tuple[Any, ...], Dict[str, Any]] = {}
    for record in records:
        resume_key = plan_sample_resume_key(record)
        if resume_key is None or not sample_is_resumable_success(record):
            summary["resume_ineligible_record_count"] += 1
            continue
        if resume_key in resumable:
            summary["resume_duplicate_successful_record_count"] += 1
        resumable[resume_key] = {**record, "resumed_from_previous_run": True}
    summary["resume_successful_record_count"] = len(resumable)
    samples_path.unlink()
    for record in resumable.values():
        append_jsonl(samples_path, record)
    return resumable, summary



def normalize_run_filter_values(values: Optional[List[str]]) -> Set[str]:
    if not values:
        return set()
    result: Set[str] = set()
    for value in values:
        for part in str(value).split(','):
            item = part.strip()
            if item:
                result.add(item)
    return result


def normalize_allocator_run_filter_values(values: Optional[List[str]]) -> Set[str]:
    return {
        normalize_sample_allocator(value)
        for value in normalize_run_filter_values(values)
        if normalize_sample_allocator(value)
    }


def normalize_fragment_run_filter_values(values: Optional[List[str]]) -> Set[str]:
    return {
        str(value).strip()
        for value in normalize_run_filter_values(values)
        if str(value).strip()
    }


def normalize_int_run_filter_values(values: Optional[List[int]]) -> Set[int]:
    if not values:
        return set()
    return {int(value) for value in values if int(value) > 0}


def plan_workload_matches_run_filters(
    workload: Dict[str, Any],
    workload_index: int,
    run_index: int,
    *,
    datasets: Set[str],
    benchmarks: Set[str],
    allocators: Set[str],
    workload_indexes: Set[int],
    run_indexes: Set[int],
    plan_fragment_ids: Set[str],
    split_cargo_bench_targets: Set[str],
) -> bool:
    dataset = str(workload.get("dataset") or workload.get("dataset_name") or "").strip()
    benchmark = str(workload.get("benchmark") or workload.get("workload") or workload.get("row") or "").strip()
    allocator = normalize_sample_allocator(workload.get("allocator") or workload.get("feature"))
    plan_fragment_id = str(workload.get("plan_fragment_id") or "").strip()
    split_cargo_bench_target = str(workload.get("split_cargo_bench_target") or "").strip()
    if datasets and dataset not in datasets:
        return False
    if benchmarks and benchmark not in benchmarks:
        return False
    if allocators and allocator not in allocators:
        return False
    if workload_indexes and workload_index not in workload_indexes:
        return False
    if run_indexes and run_index not in run_indexes:
        return False
    if plan_fragment_ids and plan_fragment_id not in plan_fragment_ids:
        return False
    if split_cargo_bench_targets and split_cargo_bench_target not in split_cargo_bench_targets:
        return False
    return True


def paper_plan_run_filter_summary(args: argparse.Namespace) -> Dict[str, Any]:
    return {
        "datasets": sorted(normalize_run_filter_values(getattr(args, "dataset", None))),
        "benchmarks": sorted(normalize_run_filter_values(getattr(args, "benchmark", None))),
        "allocators": sorted(normalize_allocator_run_filter_values(getattr(args, "allocator", None))),
        "workload_indexes": sorted(normalize_int_run_filter_values(getattr(args, "workload_index", None))),
        "run_indexes": sorted(normalize_int_run_filter_values(getattr(args, "run_index", None))),
        "plan_fragment_ids": sorted(normalize_fragment_run_filter_values(getattr(args, "plan_fragment_id", None))),
        "split_cargo_bench_targets": sorted(normalize_fragment_run_filter_values(getattr(args, "split_cargo_bench_target", None))),
    }

def run_paper_performance_plan(args: argparse.Namespace) -> int:
    cfg = load_config()
    plan_path = Path(args.plan).expanduser()
    if not plan_path.exists():
        print(f"plan file not found: {plan_path}", file=sys.stderr)
        return 2
    plan = read_json(plan_path)
    workloads = plan.get("workloads") if isinstance(plan, dict) else None
    if not isinstance(workloads, list) or not workloads:
        print("plan must contain a non-empty workloads list", file=sys.stderr)
        return 2
    run_id = args.run_id or _dt.datetime.now().strftime("paper-performance-plan-%Y%m%d-%H%M%S")
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)
    samples_path = out_dir / "paper-performance.samples.jsonl"
    resume_records: Dict[Tuple[Any, ...], Dict[str, Any]] = {}
    resume_summary: Dict[str, Any] = {"resume_enabled": bool(args.resume_successful)}
    if args.resume_successful:
        try:
            resume_records, resume_summary = load_resumable_paper_plan_samples(samples_path)
        except (OSError, ValueError) as exc:
            print(f"could not load resumable samples from {samples_path}: {exc}", file=sys.stderr)
            return 2
        resume_summary["resume_enabled"] = True
    elif samples_path.exists():
        samples_path.unlink()
    default_runs = int(args.runs or plan.get("runs") or cfg.get("methodology", {}).get("runs_per_benchmark", 6))
    default_timeout = int(args.timeout or plan.get("timeout") or 1800)
    default_max_output_bytes = positive_int_value(
        getattr(args, "max_output_bytes", None) or plan.get("max_output_bytes") or plan.get("max_log_bytes"),
        DEFAULT_MAX_PLAN_OUTPUT_BYTES,
    )
    if args.resume_successful and resume_records:
        expected_resume_keys = {
            key
            for workload in workloads
            if isinstance(workload, dict)
            for run_index in plan_workload_run_indexes(workload, default_runs)
            for key in [plan_sample_resume_key(workload, run_index)]
            if key is not None
        }
        unmatched_keys = [key for key in resume_records if key not in expected_resume_keys]
        if unmatched_keys:
            resume_records = {key: record for key, record in resume_records.items() if key in expected_resume_keys}
            resume_summary["resume_unmatched_successful_record_count"] = len(unmatched_keys)
            if samples_path.exists():
                samples_path.unlink()
            for record in resume_records.values():
                append_jsonl(samples_path, record)
        else:
            resume_summary["resume_unmatched_successful_record_count"] = 0
    paper_dir = Path(args.paper_dir or cfg.get("paper_dir_default", "")).expanduser()
    required_runs = int(cfg.get("methodology", {}).get("runs_per_benchmark", 6))
    preflight_dry_run_probe = bool(getattr(args, "preflight_dry_run_probe", False))
    preflight_dry_run_probe_limit = int(getattr(args, "preflight_dry_run_probe_limit", 0) or 0)
    preflight_dry_run_probe_timeout = int(getattr(args, "preflight_dry_run_probe_timeout", 30) or 30)
    preflight_audit, preflight_audit_path = write_plan_preflight_audit(
        cfg,
        plan,
        paper_dir=paper_dir,
        out_dir=out_dir,
        selected_datasets=args.dataset,
        selected_benchmarks=args.benchmark,
        selected_allocators=args.allocator,
        default_runs=default_runs,
        required_runs=required_runs,
        dry_run_probe=preflight_dry_run_probe,
        dry_run_probe_limit=preflight_dry_run_probe_limit,
        dry_run_probe_timeout=preflight_dry_run_probe_timeout,
    )
    preflight_ready = bool(preflight_audit.get("summary", {}).get("ready_for_claim_grade_import"))
    preflight_blockers = []
    if not preflight_ready:
        summary_blockers = preflight_audit.get("summary", {})
        for key in (
            "invalid_workload_count",
            "missing_cell_count",
            "insufficient_cell_count",
            "placeholder_workload_count",
            "non_claim_grade_subset_workload_count",
            "target_error_count",
            "dry_run_probe_failure_count",
        ):
            value = int(summary_blockers.get(key) or 0)
            if value:
                preflight_blockers.append(f"{key}={value}")
    run_filter_datasets = normalize_run_filter_values(getattr(args, "dataset", None))
    run_filter_benchmarks = normalize_run_filter_values(getattr(args, "benchmark", None))
    run_filter_allocators = normalize_allocator_run_filter_values(getattr(args, "allocator", None))
    run_filter_workload_indexes = normalize_int_run_filter_values(getattr(args, "workload_index", None))
    run_filter_run_indexes = normalize_int_run_filter_values(getattr(args, "run_index", None))
    run_filter_plan_fragment_ids = normalize_fragment_run_filter_values(getattr(args, "plan_fragment_id", None))
    run_filter_split_cargo_bench_targets = normalize_fragment_run_filter_values(getattr(args, "split_cargo_bench_target", None))
    run_filter_summary = paper_plan_run_filter_summary(args)
    if args.claim_grade and not preflight_ready:
        summary_path = out_dir / "paper-performance-plan-run-summary.json"
        summary = {
            "schema_version": 1,
            "generated_at": now_iso(),
            "run_id": run_id,
            "source": "paper-performance-plan",
            "plan": str(plan_path.resolve()),
            "samples": str(samples_path),
            "host": host_metadata(),
            "workload_count": len(workloads),
            "record_count": 0,
            "selected_work_item_count": 0,
            "run_filters": run_filter_summary,
            "failed_record_count": 0,
            "failed_records": [],
            "default_runs": default_runs,
            "required_runs_per_cell_for_claim_grade": required_runs,
            "default_timeout_seconds": default_timeout,
            "default_max_output_bytes": default_max_output_bytes,
            "keep_going": bool(args.keep_going),
            "resume_successful": bool(args.resume_successful),
            "resume_summary": resume_summary,
            "plan_preflight_audit": str(preflight_audit_path),
            "plan_preflight_ready_for_claim_grade": preflight_ready,
            "plan_preflight_blockers": preflight_blockers,
            "plan_preflight_dry_run_probe_enabled": preflight_dry_run_probe,
            "plan_preflight_dry_run_probe_count": int(preflight_audit.get("summary", {}).get("dry_run_probe_count") or 0),
            "plan_preflight_dry_run_probe_failure_count": int(preflight_audit.get("summary", {}).get("dry_run_probe_failure_count") or 0),
            "skipped": True,
            "skip_reason": "claim-grade plan preflight failed",
        }
        write_json(summary_path, summary)
        print(json.dumps(summary, indent=2, sort_keys=True))
        return 1
    records: List[Dict[str, Any]] = []
    resumed_records: List[Dict[str, Any]] = []
    executed_record_count = 0
    max_records = int(getattr(args, "max_records", 0) or 0)
    execution_limit_reached = False
    exit_status = 0
    work_items: List[Tuple[int, Any, int]] = []
    if bool(getattr(args, "interleave_runs", False)):
        workload_run_counts: List[Tuple[int, Any, List[int]]] = []
        max_workload_runs = 0
        for workload_index, raw_workload in enumerate(workloads, start=1):
            workload_run_indexes = (
                plan_workload_run_indexes(raw_workload, default_runs)
                if isinstance(raw_workload, dict)
                else list(range(1, default_runs + 1))
            )
            max_workload_runs = max(max_workload_runs, len(workload_run_indexes))
            workload_run_counts.append((workload_index, raw_workload, workload_run_indexes))
        for run_offset in range(max_workload_runs):
            for workload_index, raw_workload, workload_run_indexes in workload_run_counts:
                if run_offset < len(workload_run_indexes):
                    run_index = workload_run_indexes[run_offset]
                    if (
                        not isinstance(raw_workload, dict)
                        or plan_workload_matches_run_filters(
                            raw_workload,
                            workload_index,
                            run_index,
                            datasets=run_filter_datasets,
                            benchmarks=run_filter_benchmarks,
                            allocators=run_filter_allocators,
                            workload_indexes=run_filter_workload_indexes,
                            run_indexes=run_filter_run_indexes,
                            plan_fragment_ids=run_filter_plan_fragment_ids,
                            split_cargo_bench_targets=run_filter_split_cargo_bench_targets,
                        )
                    ):
                        work_items.append((workload_index, raw_workload, run_index))
    else:
        for workload_index, raw_workload in enumerate(workloads, start=1):
            workload_run_indexes = (
                plan_workload_run_indexes(raw_workload, default_runs)
                if isinstance(raw_workload, dict)
                else list(range(1, default_runs + 1))
            )
            for run_index in workload_run_indexes:
                if (
                    not isinstance(raw_workload, dict)
                    or plan_workload_matches_run_filters(
                        raw_workload,
                        workload_index,
                        run_index,
                        datasets=run_filter_datasets,
                        benchmarks=run_filter_benchmarks,
                        allocators=run_filter_allocators,
                        workload_indexes=run_filter_workload_indexes,
                        run_indexes=run_filter_run_indexes,
                        plan_fragment_ids=run_filter_plan_fragment_ids,
                        split_cargo_bench_targets=run_filter_split_cargo_bench_targets,
                    )
                ):
                    work_items.append((workload_index, raw_workload, run_index))
    for workload_index, raw_workload, run_index in work_items:
        if not isinstance(raw_workload, dict):
            print(f"workload {workload_index} is not an object", file=sys.stderr)
            exit_status = 2
            if not args.keep_going:
                break
            continue
        expected_resume_key = plan_sample_resume_key(raw_workload, run_index)
        resumed_record = resume_records.get(expected_resume_key) if expected_resume_key is not None else None
        if resumed_record is not None:
            records.append(resumed_record)
            resumed_records.append(resumed_record)
            continue
        if max_records > 0 and executed_record_count >= max_records:
            execution_limit_reached = True
            break
        try:
            record = run_paper_performance_plan_one(
                workload=raw_workload,
                workload_index=workload_index,
                run_index=run_index,
                out_dir=out_dir,
                default_timeout=default_timeout,
                default_max_output_bytes=default_max_output_bytes,
                run_id=run_id,
            )
        except Exception as exc:
            dataset = str(raw_workload.get("dataset") or raw_workload.get("dataset_name") or "").strip()
            benchmark = str(raw_workload.get("benchmark") or raw_workload.get("workload") or raw_workload.get("row") or "").strip()
            allocator = normalize_sample_allocator(raw_workload.get("allocator") or raw_workload.get("feature"))
            record = {
                "schema_version": 1,
                "source": "paper-performance-plan-run",
                "run_id": run_id,
                "workload_index": workload_index,
                "run_index": run_index,
                "dataset": dataset,
                "benchmark": benchmark,
                "allocator": allocator,
                "plan_fragment_id": raw_workload.get("plan_fragment_id"),
                "target_split": raw_workload.get("target_split"),
                "split_cargo_bench_target": raw_workload.get("split_cargo_bench_target"),
                "host": host_metadata(),
                "exit_code": 1,
                "success": False,
                "error": str(exc),
            }
        records.append(record)
        executed_record_count += 1
        append_jsonl(samples_path, record)
        if not sample_succeeded(record):
            exit_status = 1
            if not args.keep_going:
                break
        if exit_status and not args.keep_going:
            break
    failed_records = [record for record in records if not sample_succeeded(record)]
    summary_path = out_dir / "paper-performance-plan-run-summary.json"
    summary = {
        "schema_version": 1,
        "generated_at": now_iso(),
        "run_id": run_id,
        "source": "paper-performance-plan",
        "plan": str(plan_path.resolve()),
        "samples": str(samples_path),
        "host": host_metadata(),
        "workload_count": len(workloads),
        "record_count": len(records),
        "executed_record_count": executed_record_count,
        "resumed_record_count": len(resumed_records),
        "selected_work_item_count": len(work_items),
        "run_filters": run_filter_summary,
        "max_new_records": max_records,
        "execution_limit_reached": execution_limit_reached,
        "execution_order": "interleaved_runs" if bool(getattr(args, "interleave_runs", False)) else "workload_major",
        "failed_record_count": len(failed_records),
        "failed_records": failed_records,
        "default_runs": default_runs,
        "required_runs_per_cell_for_claim_grade": required_runs,
        "default_timeout_seconds": default_timeout,
        "default_max_output_bytes": default_max_output_bytes,
        "keep_going": bool(args.keep_going),
        "resume_successful": bool(args.resume_successful),
        "resume_summary": resume_summary,
        "plan_preflight_audit": str(preflight_audit_path),
        "plan_preflight_ready_for_claim_grade": preflight_ready,
        "plan_preflight_blockers": preflight_blockers,
        "plan_preflight_dry_run_probe_enabled": preflight_dry_run_probe,
        "plan_preflight_dry_run_probe_count": int(preflight_audit.get("summary", {}).get("dry_run_probe_count") or 0),
        "plan_preflight_dry_run_probe_failure_count": int(preflight_audit.get("summary", {}).get("dry_run_probe_failure_count") or 0),
    }
    write_json(summary_path, summary)
    import_status = None
    if args.import_results:
        import_status = import_paper_performance_samples(
            argparse.Namespace(
                samples=str(samples_path),
                paper_dir=args.paper_dir,
                run_id=f"{run_id}-import",
                output_dir=str(out_dir / "data"),
                dataset=args.dataset,
                warmup=args.warmup,
                evidence=[str(plan_path.resolve()), str(summary_path.resolve())],
                claim_grade=bool(args.claim_grade),
                import_results=True,
                quiet=True,
            )
        )
        summary["import_status"] = import_status
        write_json(summary_path, summary)
        if import_status != 0:
            exit_status = import_status
    print(json.dumps(summary, indent=2, sort_keys=True))
    return exit_status


def rredis_representative_adapter_command(args: argparse.Namespace, run_index: int) -> List[str]:
    script = ROOT / "evaluation" / "external" / "RRedis" / "run_paper_workload.py"
    return [
        sys.executable,
        str(script),
        "--dataset",
        str(args.dataset),
        "--benchmark",
        str(args.benchmark),
        "--allocator",
        str(args.allocator),
        "--variant-feature",
        str(args.variant_feature),
        "--run-index",
        str(run_index),
        "--json",
    ]


def redis_child_record_from_adapter_stdout(records: List[Dict[str, Any]], adapter_record: Dict[str, Any]) -> Dict[str, Any]:
    child = adapter_record.get("child_record")
    if isinstance(child, dict):
        return child
    for record in reversed(records):
        if str(record.get("measurement_source") or "") == "redis_load_json":
            return record
    return {}


def rredis_prepare_records_from_stdout(records: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    return [
        record
        for record in records
        if str(record.get("source") or "").startswith("paper-external-rredis-runner-prepare")
    ]


def rredis_representative_sample_record(
    *,
    args: argparse.Namespace,
    run_id: str,
    run_index: int,
    command: List[str],
    stdout: Path,
    stderr: Path,
    adapter_record: Dict[str, Any],
    child_record: Dict[str, Any],
    prepare_records: List[Dict[str, Any]],
) -> Optional[Dict[str, Any]]:
    seconds = finite_number(adapter_record.get("seconds"))
    if seconds is None:
        seconds = finite_number(child_record.get("seconds"))
    if seconds is None:
        return None
    if adapter_record.get("success") is False or child_record.get("success") is False:
        return None

    host = adapter_record.get("host") if isinstance(adapter_record.get("host"), dict) else host_metadata()
    stdout_sha = file_sha256(stdout)
    stderr_sha = file_sha256(stderr)
    latest_prepare = prepare_records[-1] if prepare_records else {}
    routing_audit = read_json_if_exists(RESULTS / "rredis_allocator_routing_audit.json")
    routing_summary = routing_audit.get("summary", {}) if isinstance(routing_audit, dict) else {}
    allocator_routing_verified = routing_summary.get("allocator_routing_verified") is True
    allocator_semantics = (
        child_record.get("allocator_semantics")
        if isinstance(child_record.get("allocator_semantics"), dict)
        else adapter_record.get("allocator_semantics") if isinstance(adapter_record.get("allocator_semantics"), dict) else {}
    )
    claim_grade_blockers = unique_strings([
        "representative RRedis bridge evidence; redis-benchmark parity, full allocator-cell coverage, and full paper methodology are not yet proven",
        *claim_grade_blocker_values(adapter_record.get("claim_grade_blockers")),
        *claim_grade_blocker_values(child_record.get("claim_grade_blockers")),
        *claim_grade_blocker_values(allocator_semantics.get("claim_grade_blockers") if isinstance(allocator_semantics, dict) else []),
    ])
    return {
        "schema_version": 1,
        "source": "paper-performance-rredis-representative-sample",
        "diagnostic_only": True,
        "diagnostic_reason": (
            "representative RRedis bridge evidence; redis-benchmark parity, full "
            "allocator-cell coverage, and full paper methodology are not yet proven"
        ),
        "claim_grade": False,
        "claim_grade_blockers": claim_grade_blockers,
        "run_id": run_id,
        "dataset": str(args.dataset),
        "benchmark": str(args.benchmark),
        "allocator": normalize_sample_allocator(args.allocator),
        "variant_feature": str(args.variant_feature),
        "run_index": run_index,
        "seconds": seconds,
        "operations_per_second": finite_number(child_record.get("operations_per_second")),
        "average_latency_seconds": finite_number(child_record.get("average_latency_seconds")),
        "p50_latency_seconds": finite_number(child_record.get("p50_latency_seconds")),
        "p95_latency_seconds": finite_number(child_record.get("p95_latency_seconds")),
        "operation": child_record.get("operation"),
        "operation_count": child_record.get("operation_count") or child_record.get("operations"),
        "successful_operations": child_record.get("successful_operations"),
        "failed_operations": child_record.get("failed_operations"),
        "concurrency": child_record.get("concurrency"),
        "warmup_operations": child_record.get("warmup_operations"),
        "measurement_source": child_record.get("measurement_source") or adapter_record.get("timing_contract", {}).get("measurement_source") or "redis_load_json",
        "benchmark_owned_json": bool(child_record.get("benchmark_owned_json", True)),
        "allocator_feature": (allocator_semantics.get("allocator_feature") if isinstance(allocator_semantics, dict) else None) or child_record.get("allocator_feature") or adapter_record.get("allocator_feature"),
        "allocator_semantics": allocator_semantics if isinstance(allocator_semantics, dict) and allocator_semantics else None,
        "success": True,
        "command": command,
        "cwd": str(ROOT),
        "host": host,
        "stdout": str(stdout),
        "stderr": str(stderr),
        "raw_evidence_path_or_uri": str(stdout),
        "raw_evidence_sha256": stdout_sha,
        "evidence": [
            {"kind": "stdout", "path": str(stdout), "sha256": stdout_sha},
            {"kind": "stderr", "path": str(stderr), "sha256": stderr_sha},
        ],
        "provenance": {
            "run_id": run_id,
            "command": command,
            "cwd": str(ROOT),
            "host": host,
            "adapter_source": adapter_record.get("source"),
            "measurement_source": child_record.get("measurement_source") or "redis_load_json",
            "stdout": str(stdout),
            "stderr": str(stderr),
        },
        "rredis_runner": {
            "prepare_record_count": len(prepare_records),
            "prepare_changed_count": latest_prepare.get("changed_count"),
            "prepare_host_triple": latest_prepare.get("host_triple"),
            "real_workload_dir": latest_prepare.get("real_workload_dir") or child_record.get("server_cwd"),
            "server_command": child_record.get("server_command"),
            "server_cwd": child_record.get("server_cwd"),
            "server_exit_code": child_record.get("server_exit_code"),
        },
        "paper_context": {
            "paper_project": "Rsedis",
            "paper_benchmark": "RRedis*",
            "representative_bridge": True,
            "allocator_routing_verified": allocator_routing_verified,
            "allocator_routing_audit": str(RESULTS / "rredis_allocator_routing_audit.json") if routing_audit else None,
            "redis_benchmark_parity_verified": False,
            "allocator_semantics": allocator_semantics if isinstance(allocator_semantics, dict) and allocator_semantics else None,
        },
        "methodology_notes": [
            "Representative RESP SET/GET bridge against the upstream Rsedis server surface.",
            "Redis-benchmark parity, full paper repetitions for every cell, and exact paper provenance are still audited separately.",
        ],
    }


def run_rredis_representative_one(
    *,
    args: argparse.Namespace,
    run_id: str,
    run_index: int,
    out_dir: Path,
) -> Tuple[Dict[str, Any], Optional[Dict[str, Any]]]:
    command = rredis_representative_adapter_command(args, run_index)
    label = (
        f"{slugify_label(args.dataset, 'dataset')}-"
        f"{slugify_label(args.benchmark, 'benchmark')}-"
        f"{slugify_label(args.allocator, 'allocator')}-run{run_index:03d}"
    )
    logs_dir = out_dir / "logs"
    logs_dir.mkdir(parents=True, exist_ok=True)
    stdout = logs_dir / f"{label}.stdout.jsonl"
    stderr = logs_dir / f"{label}.stderr.txt"
    started = now_iso()
    start = time.perf_counter()
    error = None
    process_group_terminated = False
    process_group_pid = None
    with stdout.open("w", encoding="utf-8") as out, stderr.open("w", encoding="utf-8") as err:
        proc: Optional[subprocess.Popen[Any]] = None
        try:
            proc = subprocess.Popen(
                command,
                cwd=str(ROOT),
                env=os.environ.copy(),
                stdout=out,
                stderr=err,
                start_new_session=True,
            )
            process_group_pid = proc.pid
            exit_code = proc.wait(timeout=int(args.timeout))
        except subprocess.TimeoutExpired as exc:
            exit_code = 124
            error = f"timeout after {int(args.timeout)}s: {exc}"
            if proc is not None:
                process_group_terminated = terminate_process_group(proc)
        except FileNotFoundError as exc:
            exit_code = 127
            error = str(exc)
        except Exception as exc:  # pragma: no cover - diagnostic safety net
            exit_code = 1
            error = str(exc)
    ended = now_iso()
    wall_seconds = time.perf_counter() - start
    stdout_text = stdout.read_text(encoding="utf-8", errors="replace") if stdout.exists() else ""
    records = parse_json_objects_from_text(stdout_text)
    adapter_record = records[-1] if records else {}
    child_record = redis_child_record_from_adapter_stdout(records, adapter_record)
    prepare_records = rredis_prepare_records_from_stdout(records)
    sample = None
    if exit_code == 0:
        sample = rredis_representative_sample_record(
            args=args,
            run_id=run_id,
            run_index=run_index,
            command=command,
            stdout=stdout,
            stderr=stderr,
            adapter_record=adapter_record,
            child_record=child_record,
            prepare_records=prepare_records,
        )
    run_record = {
        "schema_version": 1,
        "source": "paper-performance-rredis-representative-run",
        "run_id": run_id,
        "label": label,
        "dataset": str(args.dataset),
        "benchmark": str(args.benchmark),
        "allocator": normalize_sample_allocator(args.allocator),
        "variant_feature": str(args.variant_feature),
        "run_index": run_index,
        "command": command,
        "cwd": str(ROOT),
        "timeout_seconds": int(args.timeout),
        "started_at": started,
        "ended_at": ended,
        "wall_seconds": wall_seconds,
        "exit_code": exit_code,
        "success": sample is not None,
        "error": error,
        "process_group_pid": process_group_pid,
        "process_group_terminated": process_group_terminated,
        "stdout": str(stdout),
        "stderr": str(stderr),
        "stdout_sha256": file_sha256(stdout),
        "stderr_sha256": file_sha256(stderr),
        "json_record_count": len(records),
        "prepare_record_count": len(prepare_records),
        "adapter_success": adapter_record.get("success"),
        "adapter_seconds": adapter_record.get("seconds"),
        "child_seconds": child_record.get("seconds"),
        "child_operations_per_second": child_record.get("operations_per_second"),
        "adapter_record": adapter_record,
        "child_record": child_record,
        "prepare_records": prepare_records,
    }
    return run_record, sample


def run_rredis_representative_samples(args: argparse.Namespace) -> int:
    if int(args.runs) <= 0:
        print("--runs must be positive", file=sys.stderr)
        return 2
    cfg = load_config()
    paper_dir = Path(args.paper_dir or cfg.get("paper_dir_default", "")).expanduser()
    if not paper_dir.exists():
        print(f"paper dir not found: {paper_dir}", file=sys.stderr)
        return 2
    adapter_script = ROOT / "evaluation" / "external" / "RRedis" / "run_paper_workload.py"
    if not adapter_script.exists():
        print(f"RRedis adapter script not found: {adapter_script}", file=sys.stderr)
        return 2
    run_id = args.run_id or _dt.datetime.now().strftime("rredis-representative-samples-%Y%m%d-%H%M%S")
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)
    samples_path = out_dir / "paper-performance.samples.jsonl"
    run_records_path = out_dir / "rredis-representative-run-records.jsonl"
    for path in (samples_path, run_records_path):
        if path.exists():
            path.unlink()

    run_records: List[Dict[str, Any]] = []
    samples: List[Dict[str, Any]] = []
    exit_status = 0
    start_index = int(args.run_index_start)
    for run_index in range(start_index, start_index + int(args.runs)):
        run_record, sample = run_rredis_representative_one(
            args=args,
            run_id=run_id,
            run_index=run_index,
            out_dir=out_dir,
        )
        run_records.append(run_record)
        append_jsonl(run_records_path, run_record)
        if sample is not None:
            samples.append(sample)
            append_jsonl(samples_path, sample)
        else:
            exit_status = 1
            if not args.keep_going:
                break

    required_runs = int(args.required_runs or args.runs)
    audit = build_paper_performance_samples_audit(
        cfg,
        paper_dir,
        samples_path,
        samples,
        dataset_names=performance_plan_dataset_names(cfg, selected=[str(args.dataset)]),
        required_runs=required_runs,
    )
    audit_path = out_dir / "rredis-representative-samples-audit.json"
    write_json(audit_path, audit)
    published_results: List[str] = []
    if args.publish_local_audit:
        local_audit_path = RESULTS / "paper_performance_local_samples_audit.json"
        write_json(local_audit_path, audit)
        published_results.append(str(local_audit_path))
    if args.results_out:
        results_out = Path(args.results_out).expanduser()
        write_json(results_out, audit)
        published_results.append(str(results_out))

    failed_records = [record for record in run_records if not record.get("success")]
    summary = {
        "schema_version": 1,
        "generated_at": now_iso(),
        "run_id": run_id,
        "source": "paper-performance-rredis-representative-samples",
        "samples": str(samples_path),
        "run_records": str(run_records_path),
        "audit": str(audit_path),
        "published_results": published_results,
        "host": host_metadata(),
        "dataset": str(args.dataset),
        "benchmark": str(args.benchmark),
        "allocator": normalize_sample_allocator(args.allocator),
        "variant_feature": str(args.variant_feature),
        "requested_runs": int(args.runs),
        "attempted_runs": len(run_records),
        "successful_sample_count": len(samples),
        "failed_record_count": len(failed_records),
        "failed_records": [
            {
                "run_index": record.get("run_index"),
                "exit_code": record.get("exit_code"),
                "error": record.get("error"),
                "stdout": record.get("stdout"),
                "stderr": record.get("stderr"),
            }
            for record in failed_records
        ],
        "timeout_seconds": int(args.timeout),
        "required_runs_for_local_audit": required_runs,
        "local_sample_audit_summary": audit.get("summary", {}),
        "representative_bridge_limitations": [
            "RRedis samples exercise a focused RESP SET/GET bridge against upstream Rsedis.",
            "Redis-benchmark parity, full allocator-cell coverage, all benchmark rows, and all paper datasets remain separately gated.",
        ],
    }
    summary_path = out_dir / "rredis-representative-samples-summary.json"
    write_json(summary_path, summary)
    print(json.dumps(summary, indent=2, sort_keys=True))
    return exit_status


RREDIS_REPRESENTATIVE_ALLOCATORS = (
    "unialloc",
    "jemalloc",
    "ptmalloc",
    "mimalloc",
    "tcmalloc",
    "snmalloc",
    "scudo",
)


def parse_allocator_list(value: Any) -> List[str]:
    if isinstance(value, (list, tuple)):
        raw_items = [str(item) for item in value]
    else:
        raw_items = re.split(r"[,\s]+", str(value or ""))
    allocators = [normalize_sample_allocator(item) for item in raw_items if str(item).strip()]
    return unique_strings(allocators)


def classify_rredis_allocator_failure(run_record: Dict[str, Any]) -> str:
    allocator = normalize_sample_allocator(run_record.get("allocator"))
    child = run_record.get("child_record") if isinstance(run_record.get("child_record"), dict) else {}
    adapter = run_record.get("adapter_record") if isinstance(run_record.get("adapter_record"), dict) else {}
    haystack = "\n".join(
        str(part or "")
        for part in (
            run_record.get("error"),
            run_record.get("stderr"),
            adapter.get("error"),
            child.get("error"),
            child.get("ready_detail"),
            child.get("server_stderr_tail"),
            child.get("server_stdout_tail"),
        )
    ).lower()
    if allocator == "tcmalloc" and ("library 'tcmalloc' not found" in haystack or "-ltcmalloc" in haystack):
        return "native_tcmalloc_library_missing"
    if allocator == "snmalloc" and ("is `cmake` not installed" in haystack or "is 'cmake' not installed" in haystack):
        return "native_cmake_missing_for_snmalloc"
    if has_legacy_aarch64_rust_toolchain_linker_error(haystack):
        return "legacy_aarch64_rust_toolchain_linker_incompatible"
    if (
        "requires rustc 1.65 or newer" in haystack
        or "namespaced features with the `dep:` prefix" in haystack
        or "namespaced features with the 'dep:' prefix" in haystack
        or "-z namespaced-features" in haystack
        or "requires the `-z namespaced-features` flag" in haystack
        or "requires the '-z namespaced-features' flag" in haystack
    ):
        return "old_nightly_dependency_version_incompatible"
    if "failed to run python interpreter" in haystack and "no such file or directory" in haystack:
        return "native_python_interpreter_missing"
    if "lexical-core-0.4.0" in haystack and ("mismatched types" in haystack or "could not compile `lexical-core`" in haystack):
        return "legacy_dependency_modern_rust_incompatible"
    if "no matching package named" in haystack and ("git repository" in haystack or "location searched: git" in haystack):
        return "upstream_git_dependency_resolution_failed"
    if "server was not ready" in haystack:
        return "server_failed_before_readiness"
    return "workload_command_failed"


def run_rredis_allocator_matrix_smoke(args: argparse.Namespace) -> int:
    allocators = parse_allocator_list(args.allocators)
    if not allocators:
        print("--allocators must name at least one allocator", file=sys.stderr)
        return 2
    if int(args.runs_per_allocator) <= 0:
        print("--runs-per-allocator must be positive", file=sys.stderr)
        return 2
    cfg = load_config()
    paper_dir = Path(args.paper_dir or cfg.get("paper_dir_default", "")).expanduser()
    if not paper_dir.exists():
        print(f"paper dir not found: {paper_dir}", file=sys.stderr)
        return 2
    adapter_script = ROOT / "evaluation" / "external" / "RRedis" / "run_paper_workload.py"
    if not adapter_script.exists():
        print(f"RRedis adapter script not found: {adapter_script}", file=sys.stderr)
        return 2

    run_id = args.run_id or _dt.datetime.now().strftime("rredis-allocator-matrix-smoke-%Y%m%d-%H%M%S")
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)
    samples_path = out_dir / "paper-performance.samples.jsonl"
    run_records_path = out_dir / "rredis-allocator-matrix-run-records.jsonl"
    for path in (samples_path, run_records_path):
        if path.exists():
            path.unlink()

    samples: List[Dict[str, Any]] = []
    run_records: List[Dict[str, Any]] = []
    per_allocator: Dict[str, Dict[str, Any]] = {
        allocator: {
            "attempted_runs": 0,
            "successful_runs": 0,
            "failed_runs": 0,
            "run_indices": [],
            "failed_records": [],
        }
        for allocator in allocators
    }
    exit_status = 0
    stopped_early = False
    start_index = int(args.run_index_start)
    for allocator in allocators:
        allocator_args = copy.copy(args)
        allocator_args.allocator = allocator
        allocator_args.runs = int(args.runs_per_allocator)
        allocator_args.required_runs = int(args.required_runs or args.runs_per_allocator)
        for offset in range(int(args.runs_per_allocator)):
            run_index = start_index + offset
            run_record, sample = run_rredis_representative_one(
                args=allocator_args,
                run_id=run_id,
                run_index=run_index,
                out_dir=out_dir,
            )
            run_records.append(run_record)
            append_jsonl(run_records_path, run_record)
            bucket = per_allocator[allocator]
            bucket["attempted_runs"] += 1
            bucket["run_indices"].append(run_index)
            if sample is not None:
                samples.append(sample)
                append_jsonl(samples_path, sample)
                bucket["successful_runs"] += 1
            else:
                exit_status = 1
                bucket["failed_runs"] += 1
                failed_record = {
                    "run_index": run_record.get("run_index"),
                    "exit_code": run_record.get("exit_code"),
                    "error": run_record.get("error"),
                    "failure_cause": classify_rredis_allocator_failure(run_record),
                    "stdout": run_record.get("stdout"),
                    "stderr": run_record.get("stderr"),
                }
                bucket["failed_records"].append(failed_record)
                if args.stop_on_failure:
                    stopped_early = True
                    break
        if stopped_early:
            break

    required_runs = int(args.required_runs or args.runs_per_allocator)
    audit = build_paper_performance_samples_audit(
        cfg,
        paper_dir,
        samples_path,
        samples,
        dataset_names=performance_plan_dataset_names(cfg, selected=[str(args.dataset)]),
        required_runs=required_runs,
    )
    audit_path = out_dir / "rredis-allocator-matrix-smoke-audit.json"
    write_json(audit_path, audit)

    successful_allocators = [
        allocator
        for allocator, bucket in per_allocator.items()
        if bucket["attempted_runs"] > 0 and bucket["failed_runs"] == 0 and bucket["successful_runs"] >= int(args.runs_per_allocator)
    ]
    failed_allocators = [
        allocator
        for allocator, bucket in per_allocator.items()
        if bucket["failed_runs"] > 0 or bucket["successful_runs"] < bucket["attempted_runs"]
    ]
    failed_allocator_causes = {
        allocator: sorted(
            {
                str(record.get("failure_cause") or "workload_command_failed")
                for record in bucket.get("failed_records", [])
            }
        )
        for allocator, bucket in per_allocator.items()
        if bucket.get("failed_records")
    }
    routing_audit = read_json_if_exists(RESULTS / "rredis_allocator_routing_audit.json")
    summary = {
        "schema_version": 1,
        "generated_at": now_iso(),
        "run_id": run_id,
        "source": "rredis-allocator-matrix-smoke",
        "dataset": str(args.dataset),
        "benchmark": str(args.benchmark),
        "variant_feature": str(args.variant_feature),
        "allocators": allocators,
        "runs_per_allocator": int(args.runs_per_allocator),
        "attempted_run_count": len(run_records),
        "successful_sample_count": len(samples),
        "failed_run_count": len([record for record in run_records if not record.get("success")]),
        "successful_allocator_count": len(successful_allocators),
        "failed_allocator_count": len(failed_allocators),
        "successful_allocators": successful_allocators,
        "failed_allocators": failed_allocators,
        "failed_allocator_causes": failed_allocator_causes,
        "per_allocator": per_allocator,
        "stopped_early": stopped_early,
        "timeout_seconds": int(args.timeout),
        "samples": str(samples_path),
        "run_records": str(run_records_path),
        "audit": str(audit_path),
        "local_sample_audit_summary": audit.get("summary", {}),
        "allocator_routing_audit_summary": (
            routing_audit.get("summary", {}) if isinstance(routing_audit, dict) else {}
        ),
        "claim_grade": False,
        "diagnostic_only": True,
        "diagnostic_reason": (
            "RRedis allocator matrix smoke validates local compile/run routing only; "
            "redis-benchmark parity, full repetitions, all workload rows, and paper provenance remain gated"
        ),
        "published_results": [],
        "host": host_metadata(),
    }
    summary_path = out_dir / "rredis-allocator-matrix-smoke-summary.json"
    write_json(summary_path, summary)
    published_results: List[str] = []
    if not args.no_update_results:
        results_path = RESULTS / "rredis_allocator_matrix_smoke.json"
        write_json(results_path, summary)
        published_results.append(str(results_path))
    if args.publish_local_audit:
        local_audit_path = RESULTS / "paper_performance_local_samples_audit.json"
        write_json(local_audit_path, audit)
        published_results.append(str(local_audit_path))
    if args.results_out:
        results_out = Path(args.results_out).expanduser()
        write_json(results_out, audit)
        published_results.append(str(results_out))
    if published_results:
        summary["published_results"] = published_results
        write_json(summary_path, summary)
        if not args.no_update_results:
            write_json(RESULTS / "rredis_allocator_matrix_smoke.json", summary)

    print(json.dumps(summary, indent=2, sort_keys=True))
    return exit_status


def path_from_cli_or_summary(value: Any, summary: Dict[str, Any], key: str) -> Optional[Path]:
    raw = value if str(value or "").strip() else summary.get(key)
    if not str(raw or "").strip():
        return None
    path = Path(str(raw)).expanduser()
    return path if path.is_absolute() else ROOT / path


def compact_counter(values: Iterable[Any]) -> Dict[str, int]:
    counts: Dict[str, int] = {}
    for value in values:
        key = str(value if value is not None else "<missing>")
        if not key:
            key = "<empty>"
        counts[key] = counts.get(key, 0) + 1
    return dict(sorted(counts.items()))


def sample_host_system(sample: Dict[str, Any]) -> str:
    for candidate in sample_metadata_candidates(sample):
        host = candidate.get("host")
        if isinstance(host, dict):
            system = str(host.get("system") or "").strip()
            if system:
                return system
        for key in ("host_system", "system"):
            system = str(candidate.get(key) or "").strip()
            if system:
                return system
        runner_host = candidate.get("runner_host")
        if isinstance(runner_host, dict):
            system = str(runner_host.get("system") or "").strip()
            if system:
                return system
    return ""


def sample_paper_context(sample: Dict[str, Any]) -> Dict[str, Any]:
    context = sample.get("paper_context")
    return context if isinstance(context, dict) else {}


RREDIS_PAPER_DATASETS = {
    "default_performance": "default-perf.dat",
    "type_isolation": "type-perf.dat",
    "metadata_segregation": "meta-perf.dat",
    "hugepage_metadata": "hugepage-perf.dat",
    "pac_authentication": "pac-perf.dat",
    "memory_overhead": "memory.dat",
    "windows_performance": "win-perf.dat",
}


def grep_line_refs(path: Path, pattern: str, *, max_matches: int = 12) -> List[Dict[str, Any]]:
    if not path.exists():
        return []
    regex = re.compile(pattern, re.IGNORECASE)
    refs: List[Dict[str, Any]] = []
    for line_no, line in enumerate(path.read_text(encoding="utf-8", errors="replace").splitlines(), start=1):
        if regex.search(line):
            refs.append({"path": str(path), "line": line_no, "text": line.strip()})
            if len(refs) >= max_matches:
                break
    return refs


def rredis_paper_target_rows(paper_dir: Path) -> Dict[str, Dict[str, Any]]:
    rows: Dict[str, Dict[str, Any]] = {}
    for dataset, rel in RREDIS_PAPER_DATASETS.items():
        path = paper_dir / "data" / rel
        if not path.exists():
            rows[dataset] = {"path": str(path), "exists": False, "row": None}
            continue
        parsed = parse_dat(path)
        rredis_rows = [
            row for row in parsed.get("rows", []) if str(row.get("benchmark") or "").strip('"') == "RRedis*"
        ]
        rows[dataset] = {
            "path": str(path),
            "exists": True,
            "row": rredis_rows[0] if rredis_rows else None,
            "columns": parsed.get("columns", []),
        }
    return rows


def paper_contains_redis_benchmark_command(paper_dir: Path) -> List[Dict[str, Any]]:
    refs: List[Dict[str, Any]] = []
    for rel in ("eval.tex", "extended-abstract.tex", "tbl/tbl-benches.tex", "cmds.tex"):
        refs.extend(
            grep_line_refs(
                paper_dir / rel,
                r"redis-benchmark|(?:RRedis|Rsedis).{0,80}command|command.{0,80}(?:RRedis|Rsedis)",
            )
        )
    return refs


def audit_rredis_paper_command_contract(args: argparse.Namespace) -> int:
    cfg = load_config()
    paper_dir = Path(args.paper_dir or cfg.get("paper_dir_default", "") or DEFAULT_PAPER_REPO).expanduser()
    if not paper_dir.exists():
        print(f"paper dir not found: {paper_dir}", file=sys.stderr)
        return 2
    config_path = Path(args.config).expanduser()
    config_path = config_path if config_path.is_absolute() else ROOT / config_path
    local_config = read_json_if_exists(config_path) if config_path.exists() else {}
    if not isinstance(local_config, dict):
        local_config = {}
    redis_wrapper = local_config.get("redis_load_json_wrapper") if isinstance(local_config.get("redis_load_json_wrapper"), dict) else {}
    redis_benchmark_wrapper = (
        local_config.get("redis_benchmark_json_wrapper")
        if isinstance(local_config.get("redis_benchmark_json_wrapper"), dict)
        else {}
    )
    command_template = local_config.get("command_template") if isinstance(local_config.get("command_template"), list) else []
    child_command = redis_wrapper.get("child_command_template") if isinstance(redis_wrapper.get("child_command_template"), list) else []
    benchmark_child_command = (
        redis_benchmark_wrapper.get("child_command_template")
        if isinstance(redis_benchmark_wrapper.get("child_command_template"), list)
        else []
    )
    benchmark_wrapper_tokens = [
        str(item)
        for item in [
            redis_benchmark_wrapper.get("script"),
            redis_benchmark_wrapper.get("redis_benchmark_bin"),
            *benchmark_child_command,
        ]
        if item
    ]
    all_command_tokens = [str(item) for item in command_template + child_command]
    active_uses_redis_benchmark = any(
        "redis-benchmark" in token or "paper_external_redis_benchmark_json.py" in token
        for token in all_command_tokens
    )
    redis_benchmark_json_wrapper_configured = bool(redis_benchmark_wrapper)
    uses_redis_benchmark = active_uses_redis_benchmark or any(
        "redis-benchmark" in token or "paper_external_redis_benchmark_json.py" in token
        for token in benchmark_wrapper_tokens
    )
    active_uses_resp_bridge = any("paper_external_redis_load_json.py" in token for token in all_command_tokens)
    resp_bridge_configured = bool(redis_wrapper)
    uses_resp_bridge = active_uses_resp_bridge
    redis_benchmark_binary = str(args.redis_benchmark_binary or "redis-benchmark")
    if probe_redis_benchmark_tool is not None:
        redis_benchmark_probe = probe_redis_benchmark_tool(redis_benchmark_binary)
        redis_benchmark_path = redis_benchmark_probe.get("selected_path")
    else:
        redis_benchmark_path = shutil.which(redis_benchmark_binary)
        redis_benchmark_probe = {
            "source": "redis-benchmark-tool-probe-fallback",
            "available": bool(redis_benchmark_path),
            "selected_path": redis_benchmark_path,
            "selected_source": "path",
        }
    target_rows = rredis_paper_target_rows(paper_dir)
    paper_command_refs = paper_contains_redis_benchmark_command(paper_dir)
    source_refs = {
        "rredis_multithreaded_benchmark": grep_line_refs(paper_dir / "eval.tex", r"Rsedis|multithreaded", max_matches=8),
        "recommended_settings": grep_line_refs(paper_dir / "eval.tex", r"recommended settings|four threads", max_matches=8),
        "baselines_default_settings": grep_line_refs(paper_dir / "eval.tex", r"optional features|default settings|baselines", max_matches=12),
        "six_runs_last_five_toolchain": grep_line_refs(
            paper_dir / "extended-abstract.tex",
            r"six times|last five|nightly-2021-08-04",
            max_matches=8,
        ),
        "benchmark_table": grep_line_refs(paper_dir / "tbl" / "tbl-benches.tex", r"Rust-Redis|Rsedis", max_matches=8),
    }
    required_conditions = {
        "workload": "Rsedis / RRedis*",
        "benchmark_class": "macro_multi_thread",
        "settings": "recommended benchmark settings when available; otherwise four threads",
        "baseline_allocators": ["jemalloc", "ptmalloc", "mimalloc", "tcmalloc", "snmalloc", "scudo"],
        "runs_per_benchmark": 6,
        "reported_runs": "geometric mean of last five runs",
        "toolchain": "nightly-2021-08-04",
        "target_data_files": RREDIS_PAPER_DATASETS,
    }
    paper_command_specified = bool(paper_command_refs)
    local_command_preserves_selectors = all(
        token in json.dumps(local_config)
        for token in ("{dataset}", "{benchmark}", "{allocator}", "{variant_feature}", "{run_index}")
    )
    local_configured = local_config.get("configured") is True
    benchmark_owned_json = local_config.get("benchmark_owned_json") is True
    measurement_source = str(local_config.get("measurement_source") or local_config.get("measurement") or "")
    paper_target_rows_found = sum(1 for row in target_rows.values() if row.get("row"))
    blockers: List[str] = []
    if not paper_command_specified:
        blockers.append("paper source text names Rsedis/RRedis but does not specify an exact redis-benchmark command")
    if not redis_benchmark_path:
        blockers.append("redis-benchmark binary is not available in PATH, configured environment, repo-local deps, or Homebrew candidates")
    if not uses_redis_benchmark:
        blockers.append("local RRedis config does not expose a redis-benchmark JSON bridge")
    if active_uses_resp_bridge and not active_uses_redis_benchmark:
        blockers.append("active local RRedis command still uses the RESP SET/GET JSON bridge rather than redis-benchmark")
    if active_uses_resp_bridge:
        blockers.append("local RRedis bridge is representative load evidence unless replaced by the redis-benchmark JSON bridge")
    if not local_configured:
        blockers.append("local RRedis workload config is not configured")
    if not local_command_preserves_selectors:
        blockers.append("local RRedis command template does not preserve all dataset/benchmark/allocator/variant/run selectors")
    if not benchmark_owned_json:
        blockers.append("local RRedis config does not mark benchmark_owned_json=true")
    if paper_target_rows_found != len(RREDIS_PAPER_DATASETS):
        blockers.append(f"missing RRedis target rows in paper data files: {paper_target_rows_found}/{len(RREDIS_PAPER_DATASETS)} found")
    blockers = unique_strings(blockers)
    run_id = args.run_id or _dt.datetime.now().strftime("rredis-paper-command-contract-%Y%m%d-%H%M%S")
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)

    audit = {
        "schema_version": 1,
        "generated_at": now_iso(),
        "run_id": run_id,
        "source": "rredis-paper-command-contract-audit",
        "paper_dir": str(paper_dir),
        "config": str(config_path),
        "host": host_metadata(),
        "summary": {
            "methodology_contract_recorded": True,
            "paper_command_specified": paper_command_specified,
            "redis_benchmark_available": bool(redis_benchmark_path),
            "redis_benchmark_selected_source": redis_benchmark_probe.get("selected_source"),
            "uses_redis_benchmark": uses_redis_benchmark,
            "active_uses_redis_benchmark": active_uses_redis_benchmark,
            "redis_benchmark_json_wrapper_configured": redis_benchmark_json_wrapper_configured,
            "uses_resp_bridge": uses_resp_bridge,
            "active_uses_resp_bridge": active_uses_resp_bridge,
            "resp_bridge_configured": resp_bridge_configured,
            "local_configured": local_configured,
            "local_command_preserves_selectors": local_command_preserves_selectors,
            "benchmark_owned_json": benchmark_owned_json,
            "measurement_source": measurement_source,
            "paper_target_row_count": paper_target_rows_found,
            "paper_command_provenance_verified": False,
            "ready_for_claim_grade_import": False,
            "blocker_count": len(blockers),
        },
        "required_conditions": required_conditions,
        "source_refs": source_refs,
        "paper_command_refs": paper_command_refs,
        "paper_target_rows": target_rows,
        "local_config_summary": {
            "configured": local_configured,
            "source": local_config.get("source"),
            "measurement_source": local_config.get("measurement_source"),
            "benchmark_owned_json": local_config.get("benchmark_owned_json"),
            "claim_grade": local_config.get("claim_grade"),
            "real_workload_dir": local_config.get("real_workload_dir"),
            "command_template": command_template,
            "redis_load_json_wrapper": redis_wrapper,
            "redis_benchmark_json_wrapper": redis_benchmark_wrapper,
            "redis_benchmark_tool_probe": local_config.get("redis_benchmark_tool_probe"),
        },
        "tooling": {
            "redis_benchmark_binary": redis_benchmark_binary,
            "redis_benchmark_path": redis_benchmark_path,
            "redis_benchmark_probe": redis_benchmark_probe,
        },
        "blockers": blockers,
    }
    audit_path = out_dir / "rredis-paper-command-contract-audit.json"
    write_json(audit_path, audit)
    published_results: List[str] = []
    if not args.no_update_results:
        results_path = RESULTS / "rredis_paper_command_contract_audit.json"
        write_json(results_path, audit)
        published_results.append(str(results_path))
    if args.results_out:
        results_out = Path(args.results_out).expanduser()
        write_json(results_out, audit)
        published_results.append(str(results_out))
    if published_results:
        audit["published_results"] = published_results
        write_json(audit_path, audit)
        if not args.no_update_results:
            write_json(RESULTS / "rredis_paper_command_contract_audit.json", audit)
    print(json.dumps(audit, indent=2, sort_keys=True))
    return 0


def rredis_parity_sample_issue_summary(
    samples: List[Dict[str, Any]],
    samples_path: Path,
) -> Tuple[List[Dict[str, Any]], Dict[str, int], Dict[str, Any]]:
    invalid_examples: List[Dict[str, Any]] = []
    issue_counts: Dict[str, int] = {}
    verified_count = 0
    missing_evidence: List[str] = []
    missing_hashes: List[str] = []
    hash_mismatches: List[str] = []
    for fallback_index, sample in enumerate(samples, start=1):
        issues: List[str] = []
        if not sample_succeeded(sample):
            issues.append("sample did not succeed")
        if sample_time_value(sample) is None:
            issues.append("sample lacks finite positive timing")
        blockers = sample_claim_grade_blockers(sample, samples_path)
        issues.extend(blockers)
        evidence_entries = sample_evidence_entries(sample)
        ok, _verified, missing, missing_digest, mismatches = verify_evidence_entries_with_roots(
            evidence_entries,
            [samples_path.parent, ROOT],
        )
        if ok:
            verified_count += 1
        else:
            issues.append("sample raw evidence paths and sha256 digests are not all verified")
            missing_evidence.extend(missing)
            missing_hashes.extend(missing_digest)
            hash_mismatches.extend(mismatches)
        for issue in unique_strings(issues):
            issue_counts[issue] = issue_counts.get(issue, 0) + 1
        if issues and len(invalid_examples) < 12:
            invalid_examples.append(
                {
                    "dataset": sample.get("dataset"),
                    "benchmark": sample.get("benchmark"),
                    "allocator": normalize_sample_allocator(sample.get("allocator")),
                    "run_index": sample_run_index(sample, fallback_index),
                    "issues": unique_strings(issues),
                }
            )
    evidence_summary = {
        "sample_count": len(samples),
        "verified_evidence_sample_count": verified_count,
        "all_sample_evidence_verified": verified_count == len(samples) and bool(samples),
        "missing_evidence_examples": unique_strings(missing_evidence)[:12],
        "missing_hash_examples": unique_strings(missing_hashes)[:12],
        "hash_mismatch_examples": unique_strings(hash_mismatches)[:12],
    }
    return invalid_examples, dict(sorted(issue_counts.items())), evidence_summary


def audit_rredis_paper_parity(args: argparse.Namespace) -> int:
    matrix_path = Path(args.matrix_summary).expanduser() if args.matrix_summary else RESULTS / "rredis_allocator_matrix_smoke.json"
    matrix_path = matrix_path if matrix_path.is_absolute() else ROOT / matrix_path
    matrix_summary = read_json_if_exists(matrix_path) if matrix_path.exists() else {}
    if not isinstance(matrix_summary, dict):
        matrix_summary = {}
    samples_path = path_from_cli_or_summary(args.samples, matrix_summary, "samples")
    run_records_path = path_from_cli_or_summary(args.run_records, matrix_summary, "run_records")
    routing_path = Path(args.routing_audit).expanduser() if args.routing_audit else RESULTS / "rredis_allocator_routing_audit.json"
    routing_path = routing_path if routing_path.is_absolute() else ROOT / routing_path
    routing_audit = read_json_if_exists(routing_path) if routing_path.exists() else {}
    if not isinstance(routing_audit, dict):
        routing_audit = {}
    command_contract_path = (
        Path(args.command_contract_audit).expanduser()
        if getattr(args, "command_contract_audit", None)
        else RESULTS / "rredis_paper_command_contract_audit.json"
    )
    command_contract_path = command_contract_path if command_contract_path.is_absolute() else ROOT / command_contract_path
    command_contract = read_json_if_exists(command_contract_path) if command_contract_path.exists() else {}
    if not isinstance(command_contract, dict):
        command_contract = {}
    command_contract_summary = command_contract.get("summary", {}) if isinstance(command_contract, dict) else {}
    if not isinstance(command_contract_summary, dict):
        command_contract_summary = {}
    command_contract_blockers = command_contract.get("blockers", []) if isinstance(command_contract, dict) else []
    if not isinstance(command_contract_blockers, list):
        command_contract_blockers = []
    if samples_path is None or not samples_path.exists():
        print("RRedis samples path is missing; pass --samples or generate rredis_allocator_matrix_smoke.json", file=sys.stderr)
        return 2

    samples = read_paper_performance_samples(samples_path)
    run_records = read_paper_performance_samples(run_records_path) if run_records_path and run_records_path.exists() else []
    expected_allocators = parse_allocator_list(args.expected_allocators or matrix_summary.get("allocators") or RREDIS_REPRESENTATIVE_ALLOCATORS)
    required_runs = int(args.required_runs_per_allocator or matrix_summary.get("runs_per_allocator") or 6)
    dataset = str(args.dataset or matrix_summary.get("dataset") or "default_performance")
    benchmark = str(args.benchmark or matrix_summary.get("benchmark") or "RRedis*")
    matching_samples = [
        sample
        for sample in samples
        if str(sample.get("dataset") or "") == dataset and str(sample.get("benchmark") or "") == benchmark
    ]
    samples_by_allocator: Dict[str, List[Dict[str, Any]]] = {allocator: [] for allocator in expected_allocators}
    extra_allocators: List[str] = []
    for sample in matching_samples:
        allocator = normalize_sample_allocator(sample.get("allocator"))
        if allocator in samples_by_allocator:
            samples_by_allocator[allocator].append(sample)
        else:
            extra_allocators.append(allocator)

    per_allocator: Dict[str, Dict[str, Any]] = {}
    missing_allocators: List[str] = []
    insufficient_allocators: List[str] = []
    for allocator in expected_allocators:
        allocator_samples = samples_by_allocator.get(allocator, [])
        successful = [sample for sample in allocator_samples if sample_succeeded(sample)]
        finite = [sample for sample in allocator_samples if sample_time_value(sample) is not None]
        times = [sample_time_value(sample) for sample in allocator_samples]
        finite_times = [value for value in times if value is not None]
        run_indices = sorted(sample_run_index(sample, index) for index, sample in enumerate(allocator_samples, start=1))
        if not allocator_samples:
            missing_allocators.append(allocator)
        if len(successful) < required_runs or len(finite) < required_runs:
            insufficient_allocators.append(allocator)
        per_allocator[allocator] = {
            "sample_count": len(allocator_samples),
            "successful_sample_count": len(successful),
            "finite_timing_sample_count": len(finite),
            "run_indices": run_indices,
            "mean_seconds": arithmean(finite_times),
            "min_seconds": min(finite_times) if finite_times else None,
            "max_seconds": max(finite_times) if finite_times else None,
            "measurement_sources": compact_counter(sample.get("measurement_source") for sample in allocator_samples),
            "operations": compact_counter(sample.get("operation") for sample in allocator_samples),
            "operation_counts": compact_counter(sample.get("operation_count") for sample in allocator_samples),
            "concurrency": compact_counter(sample.get("concurrency") for sample in allocator_samples),
            "warmup_operations": compact_counter(sample.get("warmup_operations") for sample in allocator_samples),
        }

    invalid_examples, issue_counts, evidence_summary = rredis_parity_sample_issue_summary(matching_samples, samples_path)
    routing_summary = routing_audit.get("summary", {}) if isinstance(routing_audit, dict) else {}
    allocator_routing_verified = (
        isinstance(routing_summary, dict)
        and routing_summary.get("allocator_routing_verified") is True
        and routing_summary.get("allocator_route_consumed_by_child") is True
        and routing_summary.get("source_allocator_hooks_present") is True
    )
    all_samples_successful = bool(matching_samples) and all(sample_succeeded(sample) for sample in matching_samples)
    all_samples_finite = bool(matching_samples) and all(sample_time_value(sample) is not None for sample in matching_samples)
    all_expected_allocators_present = not missing_allocators and not insufficient_allocators
    measurement_sources = compact_counter(sample.get("measurement_source") for sample in matching_samples)
    benchmark_owned_json = bool(matching_samples) and all(sample.get("benchmark_owned_json") is True for sample in matching_samples)
    redis_load_json_only = set(measurement_sources) == {"redis_load_json"}
    redis_benchmark_json_only = set(measurement_sources) == {"redis_benchmark_json"}
    redis_benchmark_owned_json_sources = bool(measurement_sources) and set(measurement_sources).issubset(
        {"redis_load_json", "redis_benchmark_json"}
    )
    redis_benchmark_parity_verified = bool(matching_samples) and all(
        sample_paper_context(sample).get("redis_benchmark_parity_verified") is True for sample in matching_samples
    )
    sample_paper_command_provenance_verified = bool(matching_samples) and all(
        sample_paper_context(sample).get("paper_command_provenance_verified") is True for sample in matching_samples
    )
    paper_command_provenance_verified = (
        sample_paper_command_provenance_verified
        or command_contract_summary.get("paper_command_provenance_verified") is True
    )
    methodology_contract_recorded = command_contract_summary.get("methodology_contract_recorded") is True
    redis_benchmark_available = command_contract_summary.get("redis_benchmark_available") is True
    paper_command_contract_ready = command_contract_summary.get("ready_for_claim_grade_import") is True
    host_systems = compact_counter(sample_host_system(sample) for sample in matching_samples)
    linux_host_parity = bool(matching_samples) and set(host_systems) == {"Linux"}
    all_claim_grade = bool(matching_samples) and all(not sample_claim_grade_blockers(sample, samples_path) for sample in matching_samples)
    matrix_attempts = int(matrix_summary.get("attempted_run_count") or 0)
    matrix_successes = int(matrix_summary.get("successful_sample_count") or 0)
    matrix_succeeded = (
        matrix_attempts >= len(expected_allocators) * required_runs
        and matrix_successes >= len(expected_allocators) * required_runs
        and int(matrix_summary.get("failed_run_count") or 0) == 0
    )

    blockers: List[str] = []
    if not matching_samples:
        blockers.append(f"no RRedis samples found for {dataset}/{benchmark}")
    if missing_allocators:
        blockers.append("missing allocator samples: " + ", ".join(missing_allocators))
    if insufficient_allocators:
        blockers.append(
            "insufficient successful/finite runs per allocator: "
            + ", ".join(
                f"{allocator}={per_allocator[allocator]['successful_sample_count']}/{required_runs}"
                for allocator in insufficient_allocators
            )
        )
    if not all_samples_successful:
        blockers.append("one or more RRedis samples did not succeed")
    if not all_samples_finite:
        blockers.append("one or more RRedis samples lacks finite positive timing")
    if not evidence_summary.get("all_sample_evidence_verified"):
        blockers.append("not all RRedis sample raw evidence paths and sha256 digests verified")
    if not allocator_routing_verified:
        blockers.append("RRedis allocator selector routing is not fully verified")
    if not benchmark_owned_json or not redis_benchmark_owned_json_sources:
        blockers.append("RRedis timing source is not uniformly benchmark-owned Redis JSON output")
    if not matrix_succeeded:
        blockers.append(
            f"RRedis matrix did not cover all expected cells: {matrix_successes}/{len(expected_allocators) * required_runs} successful samples"
        )
    if not redis_benchmark_parity_verified:
        blockers.append("redis-benchmark parity is not verified for the RRedis samples")
    if not command_contract:
        blockers.append("RRedis paper command/methodology contract audit is missing")
    elif not paper_command_contract_ready:
        for blocker in command_contract_blockers[:8]:
            blockers.append(f"paper command contract blocker: {blocker}")
    if not paper_command_provenance_verified:
        blockers.append("exact paper command/provenance is not verified for the RRedis samples")
    if not linux_host_parity:
        blockers.append(
            "paper host parity is not satisfied for RRedis samples: observed host systems "
            + ", ".join(f"{key}={value}" for key, value in host_systems.items())
        )
    if not all_claim_grade:
        blockers.append("RRedis samples are diagnostic-only and must not be imported as claim-grade evidence")
    blockers = unique_strings(blockers)

    run_id = args.run_id or _dt.datetime.now().strftime("rredis-paper-parity-audit-%Y%m%d-%H%M%S")
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)
    audit = {
        "schema_version": 1,
        "generated_at": now_iso(),
        "run_id": run_id,
        "source": "rredis-paper-parity-audit",
        "dataset": dataset,
        "benchmark": benchmark,
        "matrix_summary": str(matrix_path),
        "routing_audit": str(routing_path),
        "paper_command_contract": str(command_contract_path),
        "samples": str(samples_path),
        "run_records": str(run_records_path) if run_records_path else None,
        "host": host_metadata(),
        "summary": {
            "sample_count": len(samples),
            "matching_sample_count": len(matching_samples),
            "run_record_count": len(run_records),
            "expected_allocator_count": len(expected_allocators),
            "observed_allocator_count": len([allocator for allocator in expected_allocators if per_allocator[allocator]["sample_count"]]),
            "required_runs_per_allocator": required_runs,
            "expected_sample_count": len(expected_allocators) * required_runs,
            "all_expected_allocators_present": all_expected_allocators_present,
            "all_samples_successful": all_samples_successful,
            "all_samples_finite": all_samples_finite,
            "raw_evidence_verified": evidence_summary.get("all_sample_evidence_verified") is True,
            "allocator_routing_verified": allocator_routing_verified,
            "matrix_succeeded": matrix_succeeded,
            "benchmark_owned_json": benchmark_owned_json,
            "redis_load_json_only": redis_load_json_only,
            "redis_benchmark_json_only": redis_benchmark_json_only,
            "redis_benchmark_owned_json_sources": redis_benchmark_owned_json_sources,
            "redis_benchmark_parity_verified": redis_benchmark_parity_verified,
            "methodology_contract_recorded": methodology_contract_recorded,
            "paper_command_contract_ready": paper_command_contract_ready,
            "paper_command_specified": command_contract_summary.get("paper_command_specified"),
            "redis_benchmark_available": redis_benchmark_available,
            "uses_redis_benchmark": command_contract_summary.get("uses_redis_benchmark"),
            "uses_resp_bridge": command_contract_summary.get("uses_resp_bridge"),
            "sample_paper_command_provenance_verified": sample_paper_command_provenance_verified,
            "paper_command_provenance_verified": paper_command_provenance_verified,
            "linux_host_parity": linux_host_parity,
            "ready_for_claim_grade_import": False,
            "claim_grade": False,
            "diagnostic_only": True,
            "blocker_count": len(blockers),
        },
        "conditions": {
            "expected_allocators": expected_allocators,
            "missing_allocators": missing_allocators,
            "insufficient_allocators": insufficient_allocators,
            "extra_allocators": unique_strings(extra_allocators),
            "measurement_sources": measurement_sources,
            "host_systems": host_systems,
            "operation_counts": compact_counter(sample.get("operation_count") for sample in matching_samples),
            "concurrency": compact_counter(sample.get("concurrency") for sample in matching_samples),
            "warmup_operations": compact_counter(sample.get("warmup_operations") for sample in matching_samples),
            "operations": compact_counter(sample.get("operation") for sample in matching_samples),
        },
        "per_allocator": per_allocator,
        "sample_issue_counts": issue_counts,
        "invalid_sample_examples": invalid_examples,
        "evidence_summary": evidence_summary,
        "matrix_summary_excerpt": {
            key: matrix_summary.get(key)
            for key in (
                "run_id",
                "attempted_run_count",
                "successful_sample_count",
                "failed_run_count",
                "successful_allocator_count",
                "failed_allocator_count",
                "diagnostic_only",
                "diagnostic_reason",
            )
        },
        "routing_summary": routing_summary,
        "paper_command_contract_summary": command_contract_summary,
        "paper_command_contract_blockers": command_contract_blockers,
        "blockers": blockers,
        "methodology_notes": [
            "This audit consumes existing RRedis local samples and does not run new benchmark commands.",
            "Passing local compile/run coverage is necessary but not sufficient for paper-performance claims.",
            "Redis-benchmark parity, exact paper command provenance, and Linux paper-host parity remain separate claim-grade gates.",
        ],
    }
    audit_path = out_dir / "rredis-paper-parity-audit.json"
    write_json(audit_path, audit)
    published_results: List[str] = []
    if not args.no_update_results:
        results_path = RESULTS / "rredis_paper_parity_audit.json"
        write_json(results_path, audit)
        published_results.append(str(results_path))
    if args.results_out:
        results_out = Path(args.results_out).expanduser()
        write_json(results_out, audit)
        published_results.append(str(results_out))
    if published_results:
        audit["published_results"] = published_results
        write_json(audit_path, audit)
        if not args.no_update_results:
            write_json(RESULTS / "rredis_paper_parity_audit.json", audit)
    print(json.dumps(audit, indent=2, sort_keys=True))
    return 0


def rredis_config_rule_id(config: Dict[str, Any]) -> str:
    activation = config.get("claim_grade_activation") if isinstance(config.get("claim_grade_activation"), dict) else {}
    return str(config.get("workload_id") or activation.get("rule_id") or "external-RRedis").strip()


def rredis_paper_source_metadata(config: Dict[str, Any]) -> Dict[str, Any]:
    rule = default_external_workload_bundle_rule_by_id(rredis_config_rule_id(config)) or {}
    paper_source = rule.get("paper_source") if isinstance(rule.get("paper_source"), dict) else {}
    config_source = config.get("paper_source") if isinstance(config.get("paper_source"), dict) else {}
    merged = copy.deepcopy(paper_source)
    merged.update(copy.deepcopy(config_source))
    return merged


def rredis_paper_source_contract(
    config: Dict[str, Any],
    checkout: Path,
    *,
    allow_newer_benchmark_sources: bool = False,
) -> Dict[str, Any]:
    rule_id = rredis_config_rule_id(config)
    rule = default_external_workload_bundle_rule_by_id(rule_id)
    if rule is None:
        rule = {"id": rule_id, "paper_source": rredis_paper_source_metadata(config)}
    checkout_record = external_checkout_records_by_rule_id().get(rule_id)
    return adapter_paper_source_contract_status(
        rule,
        config,
        checkout_record,
        allow_newer_benchmark_sources=allow_newer_benchmark_sources,
    )


def rredis_config_path_default() -> Path:
    local = EVAL / "external" / "RRedis" / "workload_config.local.json"
    return local if local.exists() else EVAL / "external" / "RRedis" / "workload_config.json"


def rredis_resolve_checkout(config: Dict[str, Any], config_path: Path, override: Optional[str] = None) -> Path:
    raw = override if override else str(config.get("real_workload_dir") or "")
    checkout = Path(raw).expanduser()
    if not checkout.is_absolute():
        checkout = (config_path.parent / checkout).resolve()
    return checkout


def rredis_render_plan_command(
    *,
    config: Dict[str, Any],
    config_path: Path,
    checkout: Path,
    cell: Dict[str, Any],
) -> List[str]:
    fields = {
        "dataset": str(cell.get("dataset") or ""),
        "benchmark": str(cell.get("benchmark") or "RRedis*"),
        "allocator": str(cell.get("allocator") or ""),
        "variant_feature": str(cell.get("variant_feature") or ""),
        "run_index": "{run_index}",
        "real_workload_dir": str(checkout),
    }
    command_template = config.get("command_template") or []
    rendered = render_adapter_config_value(command_template, fields)
    if isinstance(rendered, list):
        return [str(part) for part in rendered]
    return shlex.split(str(rendered or ""))


def rredis_command_uses_redis_benchmark(command: List[str]) -> bool:
    serialized = json.dumps(command)
    return "paper_external_redis_benchmark_json.py" in serialized and "--redis-benchmark-bin" in command


def rredis_command_uses_runner(command: List[str]) -> bool:
    return "paper_external_rredis_runner.py" in json.dumps(command)


def rredis_plan_prepare_probe(workload: Dict[str, Any], *, timeout: int) -> Dict[str, Any]:
    runtime_workload = dict(workload)
    for key in ("command", "cwd", "env"):
        if key in runtime_workload:
            runtime_workload[key] = render_paper_performance_template_value(
                runtime_workload.get(key),
                runtime_workload,
                extra_fields={"run_index": "1"},
            )
    try:
        _command, shell, command_for_record = normalize_plan_command(runtime_workload)
    except ValueError as exc:
        return {"ok": False, "issue": str(exc)}
    command = command_with_flag_before_remainder(command_for_record, "--prepare-only")
    cwd = resolve_plan_cwd(runtime_workload.get("cwd"))
    env = os.environ.copy()
    for key, value in (runtime_workload.get("env") or {}).items():
        env[str(key)] = str(value)
    try:
        proc = subprocess.run(
            command,
            cwd=str(cwd),
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            shell=shell,
            timeout=timeout,
        )
    except subprocess.TimeoutExpired as exc:
        return {
            "ok": False,
            "returncode": 124,
            "issue": f"RRedis prepare probe timed out after {timeout}s: {exc}",
            "command": command,
            "stdout": short_probe_text(exc.stdout or ""),
            "stderr": short_probe_text(exc.stderr or ""),
        }
    records = parse_json_objects_from_text(proc.stdout)
    prepare_record = next(
        (
            record
            for record in records
            if isinstance(record, dict) and record.get("source") == "paper-external-rredis-runner-prepare"
        ),
        records[0] if records else None,
    )
    issue = None
    if proc.returncode != 0:
        issue = f"RRedis prepare probe exited {proc.returncode}"
    elif not isinstance(prepare_record, dict):
        issue = "RRedis prepare probe did not emit a JSON preparation record"
    elif prepare_record.get("prepared") is not True:
        issue = "RRedis prepare probe did not report prepared=true"
    return {
        "ok": issue is None,
        "returncode": proc.returncode,
        "issue": issue,
        "command": command,
        "stdout": short_probe_text(proc.stdout),
        "stderr": short_probe_text(proc.stderr),
        "prepare_record": prepare_record,
    }


def rredis_claim_grade_plan_blockers(
    *,
    config: Dict[str, Any],
    source_contract: Dict[str, Any],
    command_contract: Dict[str, Any],
    routing_audit: Dict[str, Any],
    tool_probe: Dict[str, Any],
) -> List[str]:
    blockers: List[str] = []
    if config.get("claim_grade") is not True:
        blockers.append("RRedis adapter config is not claim_grade")
    blockers.extend(
        source_contract_claim_grade_blockers(
            {
                "source_contract": source_contract,
                "source_provenance_class": source_provenance_class_from_contract(source_contract),
            }
        )
    )
    command_summary = command_contract.get("summary") if isinstance(command_contract.get("summary"), dict) else {}
    if command_summary.get("redis_benchmark_available") is not True and tool_probe.get("available") is not True:
        blockers.append("redis-benchmark tool is not available")
    if command_summary.get("uses_redis_benchmark") is not True:
        blockers.append("RRedis command contract does not use redis-benchmark")
    if command_summary.get("paper_command_specified") is not True:
        blockers.append("paper does not specify an exact redis-benchmark command")
    if command_summary.get("paper_command_provenance_verified") is not True:
        blockers.append("RRedis exact paper command provenance is not verified")
    routing_summary = routing_audit.get("summary") if isinstance(routing_audit.get("summary"), dict) else {}
    if routing_summary.get("allocator_routing_verified") is not True:
        blockers.append("RRedis allocator routing audit is not verified")
    if platform.system() != "Linux":
        blockers.append(f"RRedis paper host parity requires Linux; current host is {platform.system()}")
    return unique_strings(blockers)


def build_rredis_paper_plan(
    *,
    cfg: Dict[str, Any],
    paper_dir: Path,
    config: Dict[str, Any],
    config_path: Path,
    checkout: Path,
    dataset_names: List[str],
    runs: int,
    timeout: int,
    allow_newer_benchmark_sources: bool = False,
) -> Dict[str, Any]:
    all_required, target_errors = required_performance_sample_cells(cfg, paper_dir, dataset_names)
    required_cells = [cell for cell in all_required if str(cell.get("benchmark") or "") == "RRedis*"]
    source_contract = rredis_paper_source_contract(
        config,
        checkout,
        allow_newer_benchmark_sources=allow_newer_benchmark_sources,
    )
    paper_source = rredis_paper_source_metadata(config)
    command_contract = read_json_if_exists(RESULTS / "rredis_paper_command_contract_audit.json")
    command_contract = command_contract if isinstance(command_contract, dict) else {}
    routing_audit = read_json_if_exists(RESULTS / "rredis_allocator_routing_audit.json")
    routing_audit = routing_audit if isinstance(routing_audit, dict) else {}
    tool_probe = read_json_if_exists(RESULTS / "redis_benchmark_tool_probe.json")
    tool_probe = tool_probe if isinstance(tool_probe, dict) else {}
    claim_grade_blockers = rredis_claim_grade_plan_blockers(
        config=config,
        source_contract=source_contract,
        command_contract=command_contract,
        routing_audit=routing_audit,
        tool_probe=tool_probe,
    )
    workloads: List[Dict[str, Any]] = []
    for index, cell in enumerate(required_cells, start=1):
        env = render_adapter_config_value(
            config.get("env") if isinstance(config.get("env"), dict) else {},
            {
                "dataset": str(cell.get("dataset") or ""),
                "benchmark": "RRedis*",
                "allocator": str(cell.get("allocator") or ""),
                "variant_feature": str(cell.get("variant_feature") or ""),
                "run_index": "{run_index}",
                "real_workload_dir": str(checkout),
            },
        )
        if not isinstance(env, dict):
            env = {}
        workload = {
            "dataset": cell["dataset"],
            "benchmark": "RRedis*",
            "allocator": cell["allocator"],
            "role": cell.get("role"),
            "paper_row_id": cell.get("paper_row_id"),
            "category": cell.get("category"),
            "variant_feature": cell.get("variant_feature"),
            "reference": cell.get("reference"),
            "runs": runs,
            "command": rredis_render_plan_command(config=config, config_path=config_path, checkout=checkout, cell=cell),
            "cwd": str(checkout),
            "env": {str(key): str(value) for key, value in env.items()},
            "measurement": "stdout_json",
            "time_fields": ["seconds", "operations_per_second", "average_latency_seconds"],
            "timeout": timeout,
            "label": plan_workload_label(cell, index),
            "driver_kind": "rredis-redis-benchmark-json-plan",
            "claim_grade": False,
            "claim_grade_scope": "rredis-redis-benchmark-reproducible-plan",
            "not_claim_grade_reason": (
                "RRedis redis-benchmark execution plan is reproducible bridge evidence only; "
                "paper command provenance, Linux host parity, repeated timing import, and exact source gates remain separate."
            ),
            "claim_grade_blockers": claim_grade_blockers,
            "paper_source": paper_source,
            "source_contract": source_contract,
            "source_provenance_class": source_provenance_class_from_contract(source_contract),
            "redis_benchmark_tool_probe": {
                key: tool_probe.get(key)
                for key in ("available", "selected_path", "selected_source", "selected_version", "claim_grade")
                if key in tool_probe
            },
            "paper_command_contract_summary": command_contract.get("summary", {}),
        }
        workloads.append(workload)
    return {
        "schema_version": 1,
        "generated_at": now_iso(),
        "source": "rredis-paper-plan",
        "paper_dir": str(paper_dir),
        "config_path": str(config_path),
        "checkout": str(checkout),
        "dataset_names": dataset_names,
        "runs": runs,
        "timeout": timeout,
        "methodology": cfg.get("methodology", {}),
        "target_errors": target_errors,
        "paper_source": paper_source,
        "source_contract": source_contract,
        "source_provenance_class": source_provenance_class_from_contract(source_contract),
        "redis_benchmark_tool_probe": tool_probe,
        "paper_command_contract": command_contract,
        "allocator_routing_audit": routing_audit,
        "allow_newer_benchmark_sources": bool(allow_newer_benchmark_sources),
        "notes": [
            "This is an RRedis-only redis-benchmark execution plan; it is not timing evidence by itself.",
            "The plan uses the real configured Rsedis checkout and repo-local redis-benchmark bridge.",
            "It remains fail-closed for claim import until paper command provenance, Linux host parity, and repeated sample import are satisfied.",
        ],
        "workloads": workloads,
    }


def audit_rredis_paper_plan_object(
    *,
    cfg: Dict[str, Any],
    paper_dir: Path,
    config: Dict[str, Any],
    config_path: Path,
    checkout: Path,
    plan: Dict[str, Any],
    plan_path: Optional[Path],
    dataset_names: List[str],
    required_runs: int,
    prepare_probe: bool = False,
    prepare_probe_limit: int = 0,
    prepare_probe_timeout: int = 30,
    allow_newer_benchmark_sources: bool = False,
) -> Dict[str, Any]:
    all_required, target_errors = required_performance_sample_cells(cfg, paper_dir, dataset_names)
    required_cells = [cell for cell in all_required if str(cell.get("benchmark") or "") == "RRedis*"]
    required_keys = {
        (str(cell["dataset"]), "RRedis*", str(cell["allocator"])): cell
        for cell in required_cells
    }
    workloads = plan.get("workloads") if isinstance(plan.get("workloads"), list) else []
    planned_counts: Dict[Tuple[str, str, str], int] = {}
    audited_workloads: List[Dict[str, Any]] = []
    invalid_workloads: List[Dict[str, Any]] = []
    claim_grade_blocked_workloads: List[Dict[str, Any]] = []
    prepare_probe_failures: List[Dict[str, Any]] = []
    prepare_probe_count = 0
    prepare_probe_skipped_count = 0
    prepare_probe_limit_value = max(0, int(prepare_probe_limit or 0))
    for index, raw in enumerate(workloads, start=1):
        if not isinstance(raw, dict):
            invalid = {"index": index, "issues": ["workload is not an object"]}
            audited_workloads.append(invalid)
            invalid_workloads.append(invalid)
            continue
        audited = audit_plan_workload(raw, index, int(plan.get("runs") or required_runs))
        issues = list(audited.get("issues") or [])
        claim_blockers = [
            str(issue).split("blocked cell claim-grade blocker:", 1)[1].strip()
            for issue in issues
            if str(issue).startswith("blocked cell claim-grade blocker:")
        ]
        for issue in issues:
            text = str(issue)
            if text.startswith("workload declares non-claim-grade evidence:"):
                claim_blockers.append(text.split(":", 1)[1].strip())
        issues = [
            issue
            for issue in issues
            if not str(issue).startswith("blocked cell claim-grade blocker:")
            and not str(issue).startswith("workload declares non-claim-grade evidence:")
        ]
        try:
            _cmd, _shell, command_for_record = normalize_plan_command(raw)
        except ValueError:
            command_for_record = []
        if audited.get("benchmark") != "RRedis*":
            issues.append("workload is not for RRedis*")
        if command_for_record:
            if not rredis_command_uses_runner(command_for_record):
                issues.append("RRedis workload command does not use paper_external_rredis_runner.py")
            if not rredis_command_uses_redis_benchmark(command_for_record):
                issues.append("RRedis workload command does not delegate to paper_external_redis_benchmark_json.py with --redis-benchmark-bin")
        audited["issues"] = unique_strings(issues)
        if claim_blockers:
            audited["claim_grade_blockers"] = unique_strings(claim_blockers)
            claim_grade_blocked_workloads.append(audited)
        key = (audited.get("dataset"), audited.get("benchmark"), audited.get("allocator"))
        if all(key):
            planned_counts[key] = planned_counts.get(key, 0) + int(audited.get("runs") or 0)
        if prepare_probe and not audited.get("issues"):
            if prepare_probe_limit_value and prepare_probe_count >= prepare_probe_limit_value:
                prepare_probe_skipped_count += 1
                audited["prepare_probe_skipped"] = True
            else:
                prepare_probe_count += 1
                probe = rredis_plan_prepare_probe(raw, timeout=prepare_probe_timeout)
                audited["prepare_probe"] = probe
                if not probe.get("ok"):
                    audited["issues"] = unique_strings(
                        [*audited.get("issues", []), str(probe.get("issue") or "RRedis prepare probe failed")]
                    )
                    prepare_probe_failures.append(audited)
        audited_workloads.append(audited)
        if audited.get("issues"):
            invalid_workloads.append(audited)
    missing_cells: List[Dict[str, Any]] = []
    insufficient_cells: List[Dict[str, Any]] = []
    extra_cells: List[Dict[str, Any]] = []
    for key, cell in required_keys.items():
        planned = planned_counts.get(key, 0)
        if planned == 0:
            missing_cells.append({**cell, "planned_runs": planned, "required_runs": required_runs})
        elif planned < required_runs:
            insufficient_cells.append({**cell, "planned_runs": planned, "required_runs": required_runs})
    for key, count in sorted(planned_counts.items()):
        if key not in required_keys:
            extra_cells.append({"dataset": key[0], "benchmark": key[1], "allocator": key[2], "planned_runs": count})
    source_contract = (
        plan.get("source_contract")
        if isinstance(plan.get("source_contract"), dict)
        else rredis_paper_source_contract(
            config,
            checkout,
            allow_newer_benchmark_sources=allow_newer_benchmark_sources,
        )
    )
    command_contract = plan.get("paper_command_contract") if isinstance(plan.get("paper_command_contract"), dict) else {}
    command_summary = command_contract.get("summary") if isinstance(command_contract.get("summary"), dict) else {}
    tool_probe = plan.get("redis_benchmark_tool_probe") if isinstance(plan.get("redis_benchmark_tool_probe"), dict) else {}
    routing_audit = plan.get("allocator_routing_audit") if isinstance(plan.get("allocator_routing_audit"), dict) else {}
    routing_summary = routing_audit.get("summary") if isinstance(routing_audit.get("summary"), dict) else {}
    source_reproducible = source_contract.get("reproducible_snapshot_complete") is True
    tool_available = tool_probe.get("available") is True or command_summary.get("redis_benchmark_available") is True
    routing_ready = routing_summary.get("allocator_routing_verified") is True
    fallback_ready = (
        not target_errors
        and not invalid_workloads
        and not missing_cells
        and not insufficient_cells
        and source_reproducible
        and tool_available
        and routing_ready
    )
    paper_ready = (
        fallback_ready
        and source_contract.get("claim_grade_complete") is True
        and command_summary.get("ready_for_claim_grade_import") is True
        and platform.system() == "Linux"
        and not claim_grade_blocked_workloads
    )
    current_source_ready = (
        fallback_ready
        and source_contract.get("claim_grade_complete") is True
        and command_summary.get("uses_redis_benchmark") is True
        and command_summary.get("benchmark_owned_json") is True
        and prepare_probe
        and prepare_probe_count > 0
        and not prepare_probe_failures
    )
    summary = {
        "ready_for_reproducible_fallback_execution": fallback_ready,
        "ready_for_paper_equivalent_execution": paper_ready,
        "ready_for_claim_grade_execution": paper_ready,
        "ready_for_accepted_current_execution": current_source_ready,
        "ready_for_current_non_paper_exact_execution": current_source_ready,
        "ready_for_claim_grade_import": False,
        "claim_grade_import_blocker": (
            "RRedis plan lacks exact paper command provenance, Linux host parity, or repeated timing sample import"
            if not paper_ready
            else "RRedis plan has no repeated timing sample audit/import yet"
        ),
        "dataset_count": len(dataset_names),
        "required_cell_count": len(required_cells),
        "planned_workload_count": len(workloads),
        "invalid_workload_count": len(invalid_workloads),
        "claim_grade_blocked_workload_count": len(claim_grade_blocked_workloads),
        "missing_cell_count": len(missing_cells),
        "insufficient_cell_count": len(insufficient_cells),
        "extra_cell_count": len(extra_cells),
        "target_error_count": len(target_errors),
        "source_reproducible_snapshot_complete": source_reproducible,
        "source_claim_grade_complete": source_contract.get("claim_grade_complete") is True,
        "source_provenance_class": source_contract.get("source_provenance_class"),
        "redis_benchmark_available": tool_available,
        "allocator_routing_verified": routing_ready,
        "paper_command_contract_ready": command_summary.get("ready_for_claim_grade_import") is True,
        "redis_benchmark_json_contract_ready": command_summary.get("uses_redis_benchmark") is True
        and command_summary.get("benchmark_owned_json") is True,
        "paper_command_specified": command_summary.get("paper_command_specified"),
        "paper_command_provenance_verified": command_summary.get("paper_command_provenance_verified"),
        "linux_host_parity": platform.system() == "Linux",
        "accepted_current_source_not_paper_exact": bool(current_source_ready and not paper_ready),
        "prepare_probe_enabled": bool(prepare_probe),
        "prepare_probe_count": prepare_probe_count,
        "prepare_probe_failure_count": len(prepare_probe_failures),
        "prepare_probe_skipped_count": prepare_probe_skipped_count,
        "prepare_probe_limit": prepare_probe_limit_value,
        "prepare_probe_timeout_seconds": int(prepare_probe_timeout),
    }
    blockers: List[str] = []
    if not source_reproducible:
        blockers.extend(str(item) for item in source_contract.get("blockers", []) if str(item).strip())
    if not tool_available:
        blockers.append("redis-benchmark tool is not available")
    if not routing_ready:
        blockers.append("RRedis allocator routing is not verified")
    if claim_grade_blocked_workloads:
        blockers.append(f"RRedis paper plan has {len(claim_grade_blocked_workloads)} claim-grade-blocked workloads")
    return {
        "schema_version": 1,
        "generated_at": now_iso(),
        "source": "rredis-paper-plan-audit",
        "paper_dir": str(paper_dir),
        "config_path": str(config_path),
        "checkout": str(checkout),
        "plan_path": str(plan_path) if plan_path else None,
        "dataset_names": dataset_names,
        "required_runs_per_cell": required_runs,
        "summary": summary,
        "target_errors": target_errors,
        "source_contract": source_contract,
        "paper_command_contract_summary": command_summary,
        "allocator_routing_summary": routing_summary,
        "redis_benchmark_tool_probe": tool_probe,
        "audited_workloads": audited_workloads,
        "invalid_workloads": invalid_workloads,
        "claim_grade_blocked_workloads": claim_grade_blocked_workloads,
        "missing_cells": missing_cells,
        "insufficient_cells": insufficient_cells,
        "extra_cells": extra_cells,
        "prepare_probe_failures": prepare_probe_failures,
        "blockers": unique_strings(blockers),
        "notes": [
            "This audit proves RRedis plan shape and prepare path only; it is not timing evidence.",
            "ready_for_reproducible_fallback_execution means every RRedis paper cell is scheduled over the real redis-benchmark bridge.",
            "ready_for_paper_equivalent_execution remains false without exact paper command provenance and Linux paper-host parity.",
        ],
    }


def generate_rredis_paper_plan(args: argparse.Namespace) -> int:
    cfg = load_config()
    config_path = Path(args.config).expanduser()
    if not config_path.exists():
        print(f"RRedis config not found: {config_path}", file=sys.stderr)
        return 2
    config = read_json(config_path)
    paper_dir = Path(args.paper_dir or cfg.get("paper_dir_default", "")).expanduser()
    checkout = rredis_resolve_checkout(config if isinstance(config, dict) else {}, config_path, args.checkout)
    if not checkout.exists():
        print(f"RRedis checkout not found: {checkout}", file=sys.stderr)
        return 2
    dataset_names = performance_plan_dataset_names(cfg, selected=args.dataset, include_all_paper_data=False)
    runs = int(args.runs or cfg.get("methodology", {}).get("runs_per_benchmark", 6))
    required_runs = int(args.required_runs or runs)
    timeout = int(args.timeout or 1800)
    run_id = args.run_id or _dt.datetime.now().strftime("rredis-paper-plan-%Y%m%d-%H%M%S")
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)
    plan = build_rredis_paper_plan(
        cfg=cfg,
        paper_dir=paper_dir,
        config=config if isinstance(config, dict) else {},
        config_path=config_path,
        checkout=checkout,
        dataset_names=dataset_names,
        runs=runs,
        timeout=timeout,
        allow_newer_benchmark_sources=bool(getattr(args, "allow_newer_benchmark_sources", False)),
    )
    plan_path = Path(args.plan_out).expanduser() if args.plan_out else out_dir / "rredis-paper-plan.json"
    write_json(plan_path, plan)
    audit = audit_rredis_paper_plan_object(
        cfg=cfg,
        paper_dir=paper_dir,
        config=config if isinstance(config, dict) else {},
        config_path=config_path,
        checkout=checkout,
        plan=plan,
        plan_path=plan_path,
        dataset_names=dataset_names,
        required_runs=required_runs,
        prepare_probe=bool(args.prepare_probe),
        prepare_probe_limit=int(args.prepare_probe_limit or 0),
        prepare_probe_timeout=int(args.prepare_probe_timeout or 30),
        allow_newer_benchmark_sources=bool(getattr(args, "allow_newer_benchmark_sources", False)),
    )
    audit_path = out_dir / "rredis-paper-plan-audit.json"
    write_json(audit_path, audit)
    if not args.no_update_results:
        write_json(RESULTS / "rredis_paper_plan.json", plan)
        write_json(RESULTS / "rredis_paper_plan_audit.json", audit)
    print(json.dumps({"plan": str(plan_path), "audit": str(audit_path), **audit["summary"]}, indent=2, sort_keys=True))
    return 0 if audit["summary"]["ready_for_reproducible_fallback_execution"] else 1


RREDIS_ALLOCATOR_CRATE_PATTERNS = {
    "unialloc": r"\bunialloc\b",
    "jemalloc": r"\b(?:jemallocator|tikv-jemallocator|jemalloc)\b",
    "mimalloc": r"\bmimalloc\b",
    "tcmalloc": r"\btcmalloc\b",
    "snmalloc": r"\b(?:snmalloc|snmalloc-rs)\b",
    "scudo": r"\bscudo\b",
}


def iter_rredis_checkout_text_files(checkout_dir: Path) -> Iterable[Path]:
    for path in checkout_dir.rglob("*"):
        if not path.is_file():
            continue
        parts = set(path.relative_to(checkout_dir).parts)
        if ".git" in parts or "target" in parts:
            continue
        if path.name == "Cargo.toml" or path.suffix == ".rs":
            yield path


def grep_text_file(path: Path, pattern: str) -> List[Dict[str, Any]]:
    regex = re.compile(pattern)
    matches: List[Dict[str, Any]] = []
    try:
        lines = path.read_text(encoding="utf-8", errors="replace").splitlines()
    except OSError:
        return matches
    for line_no, line in enumerate(lines, start=1):
        if regex.search(line):
            matches.append({"path": str(path), "line": line_no, "text": line.strip()[:240]})
    return matches


def command_segment_after_wrapper_separator(command_template: Any) -> List[str]:
    if not isinstance(command_template, list):
        return []
    parts = [str(item) for item in command_template]
    try:
        index = parts.index("--")
    except ValueError:
        return parts
    return parts[index + 1 :]


def audit_rredis_allocator_routing(args: argparse.Namespace) -> int:
    config_path = Path(args.config).expanduser()
    if not config_path.exists():
        print(f"RRedis config not found: {config_path}", file=sys.stderr)
        return 2
    config = read_json(config_path)
    if not isinstance(config, dict):
        print(f"RRedis config is not a JSON object: {config_path}", file=sys.stderr)
        return 2
    checkout_dir = Path(args.checkout or config.get("real_workload_dir") or "").expanduser()
    if not checkout_dir.is_absolute():
        checkout_dir = (ROOT / checkout_dir).resolve()
    if not checkout_dir.exists():
        print(f"RRedis checkout not found: {checkout_dir}", file=sys.stderr)
        return 2
    runner_path = Path(config.get("redis_load_json_wrapper", {}).get("prepare_script") or EVAL / "scripts" / "paper_external_rredis_runner.py")
    wrapper_path = Path(config.get("redis_load_json_wrapper", {}).get("script") or EVAL / "scripts" / "paper_external_redis_load_json.py")
    runner_text = runner_path.read_text(encoding="utf-8", errors="replace") if runner_path.exists() else ""
    wrapper_text = wrapper_path.read_text(encoding="utf-8", errors="replace") if wrapper_path.exists() else ""

    text_files = list(iter_rredis_checkout_text_files(checkout_dir))
    cargo_tomls = [path for path in text_files if path.name == "Cargo.toml"]
    rust_sources = [path for path in text_files if path.suffix == ".rs"]
    global_allocator_matches = [
        match
        for path in rust_sources
        for match in grep_text_file(path, r"#\s*\[\s*global_allocator\s*\]|GlobalAlloc|std::alloc::System")
    ]
    allocator_dependency_matches: Dict[str, List[Dict[str, Any]]] = {}
    for allocator, pattern in RREDIS_ALLOCATOR_CRATE_PATTERNS.items():
        allocator_dependency_matches[allocator] = [
            match
            for path in cargo_tomls
            for match in grep_text_file(path, pattern)
        ]
    allocator_feature_matches = [
        match
        for path in cargo_tomls
        for match in grep_text_file(path, r"\[features\]|\bbench_(?:ourself|jemalloc|mimalloc|tcmalloc|snmalloc|scudo|ptmalloc)\b")
    ]

    command_template = config.get("command_template")
    child_command = command_segment_after_wrapper_separator(command_template)
    env_template = config.get("env") if isinstance(config.get("env"), dict) else {}
    child_command_mentions_allocator = any("{allocator}" in str(part) for part in child_command)
    child_command_mentions_preload = any(
        re.search(
            r"(?:LD_PRELOAD|DYLD_INSERT_LIBRARIES|--features|--cfg|bench_(?:ourself|jemalloc|mimalloc|tcmalloc|snmalloc|scudo|ptmalloc)|jemallocator|mimalloc|tcmalloc|snmalloc-rs|scudo)",
            str(part),
            re.I,
        )
        for part in child_command
    )
    env_mentions_allocator = any("{allocator}" in str(value) for value in env_template.values())
    env_mentions_preload = any(str(key) in {"LD_PRELOAD", "DYLD_INSERT_LIBRARIES"} for key in env_template)
    runner_consumes_allocator_env = "UNIALLOC_PAPER_ALLOCATOR" in runner_text or re.search(r"os\.environ.*allocator", runner_text, re.I) is not None
    wrapper_consumes_allocator_for_command = (
        "UNIALLOC_PAPER_ALLOCATOR" in wrapper_text
        or re.search(r"server_command.*allocator|allocator.*server_command", wrapper_text, re.I) is not None
    )
    adapter_selector_complete = False
    selector_contract = None
    try:
        from paper_external_workload_adapter import selector_contract_status  # type: ignore

        selector_contract = selector_contract_status(config)
        adapter_selector_complete = bool(selector_contract.get("complete"))
    except Exception:
        selector_contract = None

    source_allocator_hooks_present = bool(global_allocator_matches) and any(
        bool(matches) for matches in allocator_dependency_matches.values()
    )
    dynamic_preload_present = env_mentions_preload or any(
        re.search(r"(?:LD_PRELOAD|DYLD_INSERT_LIBRARIES)", str(part), re.I) for part in child_command
    )
    allocator_route_consumed_by_child = (
        child_command_mentions_allocator
        or child_command_mentions_preload
        or runner_consumes_allocator_env
        or wrapper_consumes_allocator_for_command
        or dynamic_preload_present
    )
    allocator_routing_verified = bool(source_allocator_hooks_present and allocator_route_consumed_by_child)

    blockers: List[str] = []
    if not adapter_selector_complete:
        blockers.append("adapter selector contract is not complete")
    if not source_allocator_hooks_present:
        blockers.append("Rsedis checkout has no allocator-specific global allocator hook or allocator crate dependency")
    if not allocator_route_consumed_by_child:
        blockers.append("allocator selector is recorded by the adapter but is not consumed by the child server build/run command")
    if env_mentions_allocator and not runner_consumes_allocator_env and not wrapper_consumes_allocator_for_command:
        blockers.append("UNIALLOC_PAPER_ALLOCATOR-style env is rendered but the RRedis runner/wrapper does not use it to alter the server binary")
    if not dynamic_preload_present and not (source_allocator_hooks_present and allocator_route_consumed_by_child):
        blockers.append("no LD_PRELOAD/DYLD_INSERT_LIBRARIES allocator interposition path is configured")

    audit = {
        "schema_version": 1,
        "generated_at": now_iso(),
        "source": "rredis-allocator-routing-audit",
        "config": str(config_path),
        "checkout_dir": str(checkout_dir),
        "runner": str(runner_path),
        "wrapper": str(wrapper_path),
        "summary": {
            "allocator_routing_verified": allocator_routing_verified,
            "adapter_selector_complete": adapter_selector_complete,
            "source_allocator_hooks_present": source_allocator_hooks_present,
            "allocator_route_consumed_by_child": allocator_route_consumed_by_child,
            "dynamic_preload_present": dynamic_preload_present,
            "cargo_toml_count": len(cargo_tomls),
            "rust_source_count": len(rust_sources),
            "global_allocator_match_count": len(global_allocator_matches),
            "allocator_dependency_match_count": sum(len(matches) for matches in allocator_dependency_matches.values()),
            "allocator_feature_match_count": len(allocator_feature_matches),
            "blocker_count": len(unique_strings(blockers)),
            "claim_grade": False,
        },
        "selector_contract": selector_contract,
        "command_template": command_template,
        "child_command_after_wrapper_separator": child_command,
        "env_template": env_template,
        "routing_observations": {
            "child_command_mentions_allocator_placeholder": child_command_mentions_allocator,
            "child_command_mentions_allocator_or_preload": child_command_mentions_preload,
            "env_mentions_allocator_placeholder": env_mentions_allocator,
            "env_mentions_preload": env_mentions_preload,
            "runner_consumes_allocator_env": bool(runner_consumes_allocator_env),
            "wrapper_consumes_allocator_for_command": bool(wrapper_consumes_allocator_for_command),
        },
        "source_observations": {
            "global_allocator_matches": global_allocator_matches[:20],
            "allocator_dependency_matches": {
                allocator: matches[:20] for allocator, matches in allocator_dependency_matches.items()
            },
            "allocator_feature_matches": allocator_feature_matches[:20],
        },
        "blockers": unique_strings(blockers),
        "next_actions": [
            "Add an auditable Rsedis allocator-selection patch or wrapper that links the requested allocator into the rsedis binary.",
            "Keep selector propagation in command/env, but require the child server build/run path to consume the selector before claim-grade timing import.",
            "Record build evidence for each requested allocator and rerun representative timing only after the binary identity changes with the selector.",
        ],
    }
    run_id = args.run_id or _dt.datetime.now().strftime("rredis-allocator-routing-audit-%Y%m%d-%H%M%S")
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)
    audit_path = out_dir / "rredis-allocator-routing-audit.json"
    write_json(audit_path, audit)
    published_results: List[str] = []
    if not args.no_update_results:
        results_path = RESULTS / "rredis_allocator_routing_audit.json"
        write_json(results_path, audit)
        published_results.append(str(results_path))
    print(
        json.dumps(
            {
                "audit": str(audit_path),
                "published_results": published_results,
                "allocator_routing_verified": allocator_routing_verified,
                "summary": audit["summary"],
                "blockers": audit["blockers"],
            },
            indent=2,
            sort_keys=True,
        )
    )
    return 0 if args.allow_unverified or allocator_routing_verified else 1


def performance_plan_dataset_names(
    cfg: Dict[str, Any],
    *,
    selected: Optional[List[str]] = None,
    include_all_paper_data: bool = False,
) -> List[str]:
    if selected:
        return unique_strings(selected)
    names = list(claims_by_dataset(cfg).keys())
    if include_all_paper_data:
        for name in cfg.get("paper_data", {}):
            if name not in names:
                names.append(name)
    return names


def required_performance_sample_cells(
    cfg: Dict[str, Any],
    paper_dir: Path,
    dataset_names: List[str],
) -> Tuple[List[Dict[str, Any]], List[Dict[str, Any]]]:
    cells: List[Dict[str, Any]] = []
    errors: List[Dict[str, Any]] = []
    category_lookup = benchmark_category_lookup(cfg)
    dataset_to_variant_feature = {value: key for key, value in VARIANT_FEATURE_TO_DATASET.items()}
    for dataset_name in dataset_names:
        rel = cfg.get("paper_data", {}).get(dataset_name)
        if not rel:
            errors.append({"dataset": dataset_name, "error": "dataset missing from paper_data config"})
            continue
        ref_path = paper_dir / rel
        if not ref_path.exists():
            errors.append({"dataset": dataset_name, "error": f"paper reference dataset missing: {ref_path}"})
            continue
        reference_ds = parse_dat(ref_path)
        allocators = ["unialloc"] + [str(column) for column in reference_ds.get("columns", [])]
        for row in reference_ds.get("rows", []):
            benchmark = str(row.get("benchmark"))
            for allocator in allocators:
                cells.append(
                    {
                        "dataset": dataset_name,
                        "benchmark": benchmark,
                        "allocator": allocator,
                        "paper_row_id": row.get("id"),
                        "role": "baseline" if allocator == "unialloc" else "comparison",
                        "reference": str(ref_path),
                        "category": category_lookup.get(benchmark, "unknown"),
                        "variant_feature": dataset_to_variant_feature.get(dataset_name),
                    }
                )
    return cells, errors


def paper_performance_template_fields(
    cell: Dict[str, Any],
    *,
    extra_fields: Optional[Dict[str, Any]] = None,
) -> Dict[str, str]:
    fields = {
        "dataset": str(cell.get("dataset") or ""),
        "benchmark": str(cell.get("benchmark") or ""),
        "allocator": str(cell.get("allocator") or ""),
        "role": str(cell.get("role") or ""),
        "reference": str(cell.get("reference") or ""),
        "category": str(cell.get("category") or ""),
        "variant_feature": str(cell.get("variant_feature") or ""),
        "paper_row_id": str(cell.get("paper_row_id") or ""),
    }
    fields.update(
        {
            "dataset_slug": slugify_label(fields["dataset"], "dataset"),
            "benchmark_slug": slugify_label(fields["benchmark"], "benchmark"),
            "allocator_slug": slugify_label(fields["allocator"], "allocator"),
        }
    )
    if extra_fields:
        for key, value in extra_fields.items():
            fields[str(key)] = str(value)
    return fields


def render_paper_performance_command_template(template: str, cell: Dict[str, Any], *, shell: bool) -> Any:
    fields = paper_performance_template_fields(cell)
    try:
        rendered = template.format(**fields)
    except KeyError as exc:
        missing = exc.args[0]
        raise ValueError(f"unknown command-template placeholder: {missing}") from exc
    return rendered if shell else shlex.split(rendered)


def default_paper_workload_placeholder_command(cell: Dict[str, Any]) -> List[str]:
    command = [
        "python3",
        "evaluation/scripts/paper_workload_placeholder.py",
        "--dataset",
        str(cell.get("dataset") or ""),
        "--benchmark",
        str(cell.get("benchmark") or ""),
        "--allocator",
        str(cell.get("allocator") or ""),
    ]
    variant = str(cell.get("variant_feature") or "")
    if variant:
        command.extend(["--variant-feature", variant])
    return command


def render_paper_performance_template_value(
    value: Any,
    cell: Dict[str, Any],
    *,
    extra_fields: Optional[Dict[str, Any]] = None,
) -> Any:
    if isinstance(value, str):
        fields = paper_performance_template_fields(cell, extra_fields=extra_fields)
        if not any(f"{{{name}}}" in value for name in fields):
            return value
        try:
            return value.format(**fields)
        except KeyError as exc:
            missing = exc.args[0]
            raise ValueError(f"unknown paper workload wrapper placeholder: {missing}") from exc
    if isinstance(value, list):
        return [
            render_paper_performance_template_value(item, cell, extra_fields=extra_fields)
            for item in value
        ]
    if isinstance(value, dict):
        return {
            str(key): render_paper_performance_template_value(item, cell, extra_fields=extra_fields)
            for key, item in value.items()
        }
    return value


def render_paper_performance_command_parts(
    template: Any,
    cell: Dict[str, Any],
    *,
    shell: bool = False,
    extra_fields: Optional[Dict[str, Any]] = None,
) -> Any:
    rendered = render_paper_performance_template_value(template, cell, extra_fields=extra_fields)
    if isinstance(rendered, list):
        argv = [str(part) for part in rendered]
        if shell:
            return " ".join(shlex.quote(part) for part in argv)
        return argv
    if isinstance(rendered, str):
        return rendered if shell else shlex.split(rendered)
    raise ValueError("paper workload wrapper command must be a string or list")


def load_wrapper_manifest(path: Optional[str]) -> Optional[Dict[str, Any]]:
    if not path:
        return None
    manifest_path = Path(path).expanduser()
    if not manifest_path.exists():
        raise FileNotFoundError(f"wrapper manifest not found: {manifest_path}")
    manifest = read_json(manifest_path)
    if not isinstance(manifest, dict):
        raise ValueError("wrapper manifest must be a JSON object")
    manifest["_manifest_path"] = str(manifest_path)
    return manifest


def paper_workload_wrapper_rules(manifest: Optional[Dict[str, Any]]) -> List[Dict[str, Any]]:
    if not manifest:
        return []
    rules = manifest.get("rules")
    if rules is None:
        rules = manifest.get("wrappers")
    if not isinstance(rules, list):
        return []
    return [rule for rule in rules if isinstance(rule, dict)]


def wrapper_match_values(rule: Dict[str, Any], singular: str, plural: str) -> Optional[List[str]]:
    if plural in rule:
        raw = rule.get(plural)
    elif singular in rule:
        raw = rule.get(singular)
    else:
        return None
    if raw is None:
        return None
    if isinstance(raw, list):
        return [str(item) for item in raw]
    return [str(raw)]


def wrapper_pattern_matches(patterns: Optional[List[str]], value: Any) -> bool:
    if not patterns:
        return True
    text = str(value or "")
    return any(pattern == "*" or fnmatch.fnmatchcase(text, pattern) for pattern in patterns)


def wrapper_rule_matches(rule: Dict[str, Any], cell: Dict[str, Any]) -> bool:
    if rule.get("enabled") is False:
        return False
    dimensions = [
        ("dataset", "datasets"),
        ("benchmark", "benchmarks"),
        ("allocator", "allocators"),
        ("category", "categories"),
        ("variant_feature", "variant_features"),
        ("role", "roles"),
        ("paper_row_id", "paper_row_ids"),
    ]
    for singular, plural in dimensions:
        if not wrapper_pattern_matches(wrapper_match_values(rule, singular, plural), cell.get(singular)):
            return False
    return True


def find_wrapper_rule(manifest: Optional[Dict[str, Any]], cell: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    for rule in paper_workload_wrapper_rules(manifest):
        if wrapper_rule_matches(rule, cell):
            return rule
    return None


def serialized_contains_template_marker(value: Any) -> bool:
    text = json.dumps(value, sort_keys=True)
    lowered = text.lower()
    return (
        "/path/to/" in lowered
        or "<replace" in lowered
        or "todo" in lowered
        or "replace-with" in lowered
    )


ADAPTER_SELECTOR_PLACEHOLDERS = ["dataset", "benchmark", "allocator", "variant_feature", "run_index"]


def external_adapter_selector_env_template() -> Dict[str, str]:
    return {
        "UNIALLOC_PAPER_DATASET": "{dataset}",
        "UNIALLOC_PAPER_BENCHMARK": "{benchmark}",
        "UNIALLOC_PAPER_ALLOCATOR": "{allocator}",
        "UNIALLOC_PAPER_VARIANT_FEATURE": "{variant_feature}",
        "UNIALLOC_PAPER_RUN_INDEX": "{run_index}",
    }


def serialized_template_text(value: Any) -> str:
    return json.dumps(value, sort_keys=True, default=str)


def template_uses_placeholder(value: Any, name: str) -> bool:
    return f"{{{name}}}" in serialized_template_text(value)


def adapter_selector_contract_status(config: Dict[str, Any]) -> Dict[str, Any]:
    surfaces = {
        "command_template": config.get("command_template"),
        "cwd": config.get("cwd") or "",
        "env": config.get("env") or {},
    }
    present = {
        name: any(template_uses_placeholder(surface, name) for surface in surfaces.values())
        for name in ADAPTER_SELECTOR_PLACEHOLDERS
    }
    missing = [name for name in ADAPTER_SELECTOR_PLACEHOLDERS if not present.get(name)]
    return {
        "required_placeholders": ADAPTER_SELECTOR_PLACEHOLDERS,
        "present": present,
        "missing": missing,
        "complete": not missing,
        "checked_surfaces": list(surfaces.keys()),
    }


def adapter_timing_contract_status(config: Dict[str, Any]) -> Dict[str, Any]:
    contract = config.get("timing_contract") if isinstance(config.get("timing_contract"), dict) else {}
    time_fields = config.get("time_fields")
    if not isinstance(time_fields, list):
        time_fields = []
    time_field = str(config.get("time_field") or "").strip()
    declared_fields = unique_strings([time_field, *[str(field or "").strip() for field in time_fields]])
    measurement_source = first_nonempty_text(
        [
            config.get("measurement_source"),
            config.get("timing_source"),
            contract.get("measurement_source"),
            contract.get("source"),
            config.get("measurement"),
        ],
        default="",
    )
    benchmark_owned_json = (
        config.get("benchmark_owned_json") is True
        or contract.get("benchmark_owned_json") is True
        or str(measurement_source).strip().lower() in {"benchmark_owned_json", "benchmark-json", "benchmark_json"}
    )
    return {
        "declared_time_fields": declared_fields,
        "declares_time_fields": bool(declared_fields),
        "measurement_source": measurement_source or None,
        "benchmark_owned_json": bool(benchmark_owned_json),
    }


HEAD_LIKE_REFS = {"", "head", "main", "master", "trunk", "latest"}
GIT_FULL_SHA_RE = re.compile(r"^[0-9a-fA-F]{40}$")
NON_EXACT_REPRODUCIBLE_REF_KINDS = {"fallback", "newer"}
USER_ACCEPTED_NEWER_SOURCE_PROVENANCE_CLASS = "user_accepted_newer_pinned_source"


def accepted_newer_benchmark_source_policy(*containers: Any) -> Dict[str, Any]:
    """Return the explicit policy that allows a pinned newer benchmark source.

    The default remains paper-exact-only.  This policy is intentionally opt-in
    because a newer upstream checkout is useful current evidence, but it must
    never be confused with an exact rust-alloc-paper source revision.
    """

    reason = ""
    accepted = False
    for container in containers:
        if not isinstance(container, dict):
            continue
        raw = (
            container.get("accepted_newer_benchmark_source")
            if "accepted_newer_benchmark_source" in container
            else container.get("accept_newer_benchmark_source")
        )
        if raw is None:
            raw = container.get("newer_benchmark_source_policy")
        if isinstance(raw, dict):
            raw_accepted = (
                raw.get("accepted") is True
                or raw.get("allow") is True
                or raw.get("enabled") is True
                or raw.get("allow_newer_benchmark_source") is True
            )
            if raw_accepted:
                accepted = True
                reason = first_nonempty_text(
                    [
                        raw.get("reason"),
                        raw.get("rationale"),
                        raw.get("source"),
                    ],
                    reason,
                )
        elif raw is True:
            accepted = True
        if container.get("user_accepted_newer_source") is True:
            accepted = True
            reason = first_nonempty_text([container.get("reason")], reason)
    if accepted and not reason:
        reason = (
            "user explicitly allowed pinned newer benchmark sources for current "
            "non-paper-exact evaluation"
        )
    return {
        "accepted": bool(accepted),
        "reason": reason or None,
        "paper_exact": False if accepted else None,
    }


def external_checkout_records_by_rule_id(
    checkout_audit: Optional[Dict[str, Any]] = None,
) -> Dict[str, Dict[str, Any]]:
    if checkout_audit is None:
        loaded = read_json_if_exists(RESULTS / "paper_external_workload_checkouts.json")
        checkout_audit = loaded if isinstance(loaded, dict) else {}
    records = checkout_audit.get("checkouts") if isinstance(checkout_audit, dict) else []
    if not isinstance(records, list):
        return {}
    out: Dict[str, Dict[str, Any]] = {}
    for record in records:
        if not isinstance(record, dict):
            continue
        rule_id = str(record.get("rule_id") or "").strip()
        if rule_id:
            out[rule_id] = record
    return out


def adapter_checkout_pin_status(checkout_record: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    """Return reproducible-checkout pin evidence without promoting it to paper-exact provenance."""

    if not isinstance(checkout_record, dict):
        return {
            "available": False,
            "pinned": False,
            "exact_pinned": False,
            "commit": None,
            "resolved_ref": None,
            "status": None,
            "symref": None,
            "checkout_dir": None,
            "blockers": ["missing checkout audit record"],
        }
    resolution = checkout_record.get("resolution") if isinstance(checkout_record.get("resolution"), dict) else {}
    existing = (
        checkout_record.get("existing_checkout")
        if isinstance(checkout_record.get("existing_checkout"), dict)
        else {}
    )
    commit = str(existing.get("current_commit") or resolution.get("commit") or "").strip()
    checkout_ready = checkout_record.get("checkout_ready") is True
    matches_resolved = existing.get("matches_resolved_commit") is True or not existing
    pinned = bool(checkout_ready and matches_resolved and GIT_FULL_SHA_RE.match(commit))
    blockers: List[str] = []
    if not checkout_ready:
        blockers.append("checkout audit does not mark checkout_ready=true")
    if not GIT_FULL_SHA_RE.match(commit):
        blockers.append("checkout audit does not expose a 40-hex resolved commit")
    if existing and existing.get("matches_resolved_commit") is not True:
        blockers.append("existing checkout commit does not match resolved commit")
    exact_pinned = bool(pinned and resolution.get("status") == "exact" and resolution.get("fallback_used") is not True)
    resolution_status = str(resolution.get("status") or "").strip().lower()
    non_exact_ref_used = bool(
        resolution.get("fallback_used") is True
        or resolution.get("newer_used") is True
        or resolution_status in NON_EXACT_REPRODUCIBLE_REF_KINDS
    )
    return {
        "available": True,
        "pinned": pinned,
        "exact_pinned": exact_pinned,
        "commit": commit or None,
        "resolved_ref": resolution.get("resolved_ref") or resolution.get("ref"),
        "requested_ref": resolution.get("ref"),
        "status": resolution.get("status"),
        "symref": resolution.get("symref"),
        "checkout_dir": checkout_record.get("checkout_dir"),
        "fallback_used": resolution.get("fallback_used") is True,
        "newer_used": resolution.get("newer_used") is True or resolution_status == "newer",
        "non_exact_ref_used": non_exact_ref_used,
        "blockers": unique_strings(blockers),
    }


def adapter_paper_source_contract_status(
    rule: Dict[str, Any],
    config: Optional[Dict[str, Any]] = None,
    checkout_record: Optional[Dict[str, Any]] = None,
    *,
    allow_newer_benchmark_sources: bool = False,
) -> Dict[str, Any]:
    """Return the paper-source provenance contract for a configured adapter.

    A configured external runner can be useful for dry-run and diagnostic
    execution while still being unsafe as paper-grade evidence if it is pointed
    at whatever upstream HEAD happens to be today.  Claim-grade adapter configs
    must therefore carry an exact paper source ref (tag, commit, revision, or
    equivalent exact version), not merely a HEAD/main/master candidate.
    """

    source = paper_external_source_metadata(rule)
    config_source = config.get("paper_source") if isinstance(config, dict) else None
    if isinstance(config_source, dict):
        merged = copy.deepcopy(source)
        merged.update(copy.deepcopy(config_source))
        source = merged
    policy_source = {"accept_newer_benchmark_source": True} if allow_newer_benchmark_sources else {}
    accepted_newer_policy = accepted_newer_benchmark_source_policy(
        config if isinstance(config, dict) else {},
        source,
        policy_source,
    )
    accept_newer_source = accepted_newer_policy.get("accepted") is True
    ref_candidates = normalized_external_source_ref_candidates(source)
    exact_candidates = [
        candidate
        for candidate in ref_candidates
        if str(candidate.get("kind") or "").strip().lower() == "exact"
        and str(candidate.get("ref") or "").strip().lower() not in HEAD_LIKE_REFS
    ]
    reproducible_non_exact_candidates = [
        candidate
        for candidate in ref_candidates
        if str(candidate.get("kind") or "").strip().lower() in NON_EXACT_REPRODUCIBLE_REF_KINDS
        and str(candidate.get("ref") or "").strip().lower() not in HEAD_LIKE_REFS
    ]
    newer_candidates = [
        candidate
        for candidate in reproducible_non_exact_candidates
        if str(candidate.get("kind") or "").strip().lower() == "newer"
    ]
    fallback_candidates = [
        candidate
        for candidate in reproducible_non_exact_candidates
        if str(candidate.get("kind") or "").strip().lower() == "fallback"
    ]
    head_candidates = [
        candidate
        for candidate in ref_candidates
        if str(candidate.get("kind") or "").strip().lower() == "head"
        or str(candidate.get("ref") or "").strip().lower() in HEAD_LIKE_REFS
    ]
    matchers = normalized_external_source_matchers(source)
    upstream_url = str(source.get("upstream_url") or "").strip()
    blockers: List[str] = []
    if not source:
        blockers.append("adapter paper_source metadata is missing")
    if not upstream_url:
        blockers.append("adapter paper_source upstream_url is missing")
    if not ref_candidates:
        blockers.append("adapter paper_source ref_candidates are missing")
    elif not exact_candidates:
        if accept_newer_source and reproducible_non_exact_candidates:
            pass
        elif head_candidates:
            blockers.append("adapter paper_source has only HEAD-like refs; exact paper version/ref provenance is required")
        else:
            blockers.append("adapter paper_source lacks an exact non-HEAD ref candidate")
    if not matchers:
        blockers.append("adapter paper_source repository matchers are missing")
    checkout_pin = adapter_checkout_pin_status(checkout_record)
    accepted_newer_ref_complete = bool(
        accept_newer_source and upstream_url and reproducible_non_exact_candidates and matchers
    )
    accepted_newer_checkout_pin_complete = bool(
        accepted_newer_ref_complete
        and checkout_pin["pinned"]
        and checkout_pin.get("non_exact_ref_used") is True
    )
    if checkout_pin["pinned"] and not exact_candidates and not accepted_newer_checkout_pin_complete:
        blockers.append(
            "adapter checkout is pinned to a reproducible non-paper-exact commit but paper exact-ref provenance is still missing"
        )
    if (
        upstream_url
        and exact_candidates
        and matchers
        and not checkout_pin.get("exact_pinned")
        and not accepted_newer_checkout_pin_complete
    ):
        checkout_blockers = checkout_pin.get("blockers") if isinstance(checkout_pin.get("blockers"), list) else []
        blockers.extend(
            str(item)
            for item in (checkout_blockers or ["adapter checkout is not pinned to the exact paper ref"])
            if str(item).strip()
        )
    if (
        checkout_pin["pinned"]
        and checkout_pin.get("non_exact_ref_used") is True
        and not accepted_newer_checkout_pin_complete
    ):
        label = "newer ref" if checkout_pin.get("newer_used") else "fallback ref"
        blockers.append(
            f"adapter checkout used a {label}; claim-grade paper evidence requires the exact paper ref"
        )
    if (
        checkout_pin["pinned"]
        and checkout_pin.get("status") not in {None, "exact"}
        and exact_candidates
        and not accepted_newer_checkout_pin_complete
    ):
        blockers.append(
            f"adapter checkout resolution status is {checkout_pin.get('status')!r}, not exact"
        )
    exact_checkout_pin_complete = bool(
        checkout_pin["pinned"]
        and checkout_pin.get("exact_pinned") is True
        and upstream_url
        and exact_candidates
        and matchers
    )
    metadata_exact_complete = bool(upstream_url and exact_candidates and matchers)
    claim_grade_complete = bool(exact_checkout_pin_complete or accepted_newer_checkout_pin_complete)
    source_provenance_class = (
        "paper_exact_ref"
        if exact_checkout_pin_complete
        else (
            USER_ACCEPTED_NEWER_SOURCE_PROVENANCE_CLASS
            if accepted_newer_checkout_pin_complete
            else source_provenance_class_from_contract(
                {
                    "paper_exact_ref_complete": metadata_exact_complete,
                    "reproducible_snapshot_complete": bool(
                        upstream_url and matchers and checkout_pin["pinned"]
                    ),
                    "head_only": bool(head_candidates and not exact_candidates and not reproducible_non_exact_candidates),
                }
            )
        )
    )
    return {
        "complete": metadata_exact_complete,
        "paper_exact_ref_complete": metadata_exact_complete,
        "exact_checkout_pin_complete": exact_checkout_pin_complete,
        "paper_exact_claim_grade_complete": exact_checkout_pin_complete,
        "accepted_newer_ref_complete": accepted_newer_ref_complete,
        "accepted_newer_checkout_pin_complete": accepted_newer_checkout_pin_complete,
        "accepted_non_exact_ref_complete": accepted_newer_ref_complete,
        "accepted_non_exact_checkout_pin_complete": accepted_newer_checkout_pin_complete,
        "accepted_newer_policy": accepted_newer_policy,
        "claim_grade_complete": claim_grade_complete,
        "source_provenance_class": source_provenance_class,
        "reproducible_snapshot_complete": bool(upstream_url and matchers and checkout_pin["pinned"]),
        "upstream_url": upstream_url or None,
        "ref_candidates": ref_candidates,
        "exact_ref_candidates": exact_candidates,
        "reproducible_non_exact_ref_candidates": reproducible_non_exact_candidates,
        "newer_ref_candidates": newer_candidates,
        "fallback_ref_candidates": fallback_candidates,
        "head_ref_candidates": head_candidates,
        "has_exact_ref_candidate": bool(exact_candidates),
        "has_newer_ref_candidate": bool(newer_candidates),
        "has_fallback_ref_candidate": bool(fallback_candidates),
        "has_reproducible_non_exact_ref_candidate": bool(reproducible_non_exact_candidates),
        "has_head_ref_candidate": bool(head_candidates),
        "head_without_exact_ref_candidate": bool(head_candidates and not exact_candidates),
        "head_only": bool(head_candidates and not exact_candidates and not reproducible_non_exact_candidates),
        "matcher_count": len(matchers),
        "paper_source_from_config": isinstance(config_source, dict),
        "checkout_pin": checkout_pin,
        "blockers": unique_strings(blockers),
    }


def wrapper_rule_issues(rule: Dict[str, Any], cell: Optional[Dict[str, Any]] = None) -> List[str]:
    issues: List[str] = []
    if rule.get("template_only"):
        issues.append("wrapper rule is template_only and must be replaced with a real runner command")
    rendered_command: Any = None
    command = rule.get("command_template") if "command_template" in rule else rule.get("command")
    if command is None:
        issues.append("wrapper rule is missing command_template/command")
    elif cell is not None:
        try:
            rendered_command = render_paper_performance_command_parts(command, cell, shell=bool(rule.get("shell")))
            if serialized_contains_template_marker(rendered_command):
                issues.append("wrapper command still contains placeholder/template markers")
        except ValueError as exc:
            issues.append(str(exc))
    elif serialized_contains_template_marker(command):
        issues.append("wrapper command still contains placeholder/template markers")
    if cell is not None and rendered_command is not None:
        issues.extend(wrapper_external_workload_bundle_issues(rendered_command, cell))
    if "cwd" not in rule:
        issues.append("wrapper rule should name cwd so paper/repo-relative execution is auditable")
    measurement = str(rule.get("measurement") or "stdout_json").strip().lower()
    if measurement in {"stdout_json", "json"} and not (rule.get("time_field") or rule.get("time_fields")):
        issues.append("stdout_json wrapper rule should name time_field/time_fields")
    env = rule.get("env")
    if env is not None and not isinstance(env, dict):
        issues.append("wrapper rule env must be an object")
    if "timeout" in rule:
        try:
            if int(rule.get("timeout")) <= 0:
                issues.append("wrapper rule timeout must be positive")
        except (TypeError, ValueError):
            issues.append("wrapper rule timeout must be an integer")
    return unique_strings(issues)


def command_parts_for_external_bundle_probe(rendered_command: Any) -> List[str]:
    if isinstance(rendered_command, list):
        return [str(part) for part in rendered_command]
    if isinstance(rendered_command, str):
        try:
            return shlex.split(rendered_command)
        except ValueError:
            return [rendered_command]
    return []


def wrapper_external_workload_bundle_issues(rendered_command: Any, cell: Dict[str, Any]) -> List[str]:
    parts = command_parts_for_external_bundle_probe(rendered_command)
    if not any(str(part).endswith("paper_external_workload.py") for part in parts):
        return []
    issues: List[str] = []
    bundle_arg = None
    for index, part in enumerate(parts):
        if part == "--bundle" and index + 1 < len(parts):
            bundle_arg = parts[index + 1]
            break
    if not bundle_arg:
        return ["paper_external_workload.py wrapper command is missing --bundle"]
    bundle_path = Path(str(bundle_arg)).expanduser()
    if not bundle_path.is_absolute():
        bundle_path = ROOT / bundle_path
    try:
        bundle = load_external_workload_bundle(str(bundle_path))
    except (FileNotFoundError, ValueError, json.JSONDecodeError) as exc:
        return [f"external workload bundle issue: {exc}"]
    assert bundle is not None
    bundle_rule = find_external_workload_bundle_rule(bundle, cell)
    if bundle_rule is None:
        return [
            "external workload bundle issue: no rule matches "
            f"{cell.get('dataset')}/{cell.get('benchmark')}/{cell.get('allocator')}"
        ]
    for issue in external_workload_bundle_rule_issues(bundle_rule, cell):
        issues.append(f"external workload bundle issue: {issue}")
    return issues


def wrapper_external_workload_dry_run_probe(
    rendered_command: Any,
    cell: Dict[str, Any],
    *,
    timeout: int,
) -> Optional[Dict[str, Any]]:
    parts = command_parts_for_external_bundle_probe(rendered_command)
    if not any(str(part).endswith("paper_external_workload.py") for part in parts):
        return None
    bundle_arg = None
    for index, part in enumerate(parts):
        if part == "--bundle" and index + 1 < len(parts):
            bundle_arg = parts[index + 1]
            break
    if not bundle_arg:
        return {
            "ok": False,
            "issue": "paper_external_workload.py wrapper dry-run probe is missing --bundle",
            "command": parts,
        }
    bundle_path = Path(str(bundle_arg)).expanduser()
    if not bundle_path.is_absolute():
        bundle_path = ROOT / bundle_path
    probe = external_workload_runner_dry_run_probe(bundle_path, cell, timeout=timeout)
    probe["wrapper_command"] = parts
    return probe


def wrapper_rule_template_issue(issue: str) -> bool:
    lowered = issue.lower()
    return "template_only" in lowered or "placeholder" in lowered or "template markers" in lowered


def wrapper_manifest_workload_options(
    rule: Dict[str, Any],
    cell: Dict[str, Any],
    *,
    default_cwd: str,
    default_timeout: int,
    default_measurement: str,
    default_time_field: str,
) -> Dict[str, Any]:
    shell = bool(rule.get("shell"))
    command_template = rule.get("command_template") if "command_template" in rule else rule.get("command")
    if command_template is None:
        raise ValueError("wrapper rule is missing command_template/command")
    issues = wrapper_rule_issues(rule, cell)
    rule_id = str(rule.get("id") or rule.get("name") or "")
    capability = rule.get("capability") if isinstance(rule.get("capability"), dict) else {}
    capability_kind = str(capability.get("kind") or "")
    external_rule_id = str(capability.get("external_rule_id") or "").strip()
    source_rule: Optional[Dict[str, Any]] = None
    if capability_kind in {"external_adapter_claim_grade_runner", "external_workload_required"}:
        source_rule = default_external_workload_bundle_rule_by_id(external_rule_id) or rule
    elif paper_external_source_metadata(rule):
        source_rule = rule
    source_contract: Dict[str, Any] = {}
    paper_source: Dict[str, Any] = {}
    if source_rule is not None:
        checkout_rule_id = external_rule_id or rule_id
        source_contract = adapter_paper_source_contract_status(
            source_rule,
            None,
            external_checkout_records_by_rule_id().get(checkout_rule_id),
        )
        paper_source = paper_external_source_metadata(source_rule)
    # Wrapper manifest rows describe one workload cell, while the plan runner
    # expands that cell into run_index=1..N at execution time.  Preserve a
    # literal {run_index} selector in generated plan surfaces and render it in
    # run_paper_performance_plan_one.
    per_run_placeholders = {"run_index": "{run_index}"}
    options: Dict[str, Any] = {
        "command": render_paper_performance_command_parts(
            command_template,
            cell,
            shell=shell,
            extra_fields=per_run_placeholders,
        ),
        "cwd": str(
            render_paper_performance_template_value(
                rule.get("cwd", default_cwd),
                cell,
                extra_fields=per_run_placeholders,
            )
        ),
        "measurement": str(rule.get("measurement") or default_measurement),
        "time_field": str(rule.get("time_field") or default_time_field),
        "timeout": int(rule.get("timeout") or default_timeout),
        "driver_kind": "wrapper-manifest-template"
        if rule.get("template_only") or any(wrapper_rule_template_issue(issue) for issue in issues)
        else "wrapper-manifest",
        "wrapper_manifest_rule_id": rule_id,
        "wrapper_manifest_issues": issues,
    }
    if source_rule is not None:
        options["paper_source"] = paper_source
        options["source_contract"] = source_contract
        options["source_provenance_class"] = source_provenance_class_from_contract(source_contract)
    if capability:
        options["capability"] = capability
    raw_blockers = rule.get("claim_grade_blockers")
    if isinstance(raw_blockers, list):
        options["claim_grade_blockers"] = unique_strings(raw_blockers)
    elif raw_blockers:
        options["claim_grade_blockers"] = unique_strings([raw_blockers])
    source_blockers = source_contract_claim_grade_blockers(options)
    if source_blockers:
        options["claim_grade"] = False
        options["claim_grade_blockers"] = unique_strings(
            [
                *claim_grade_blocker_values(options.get("claim_grade_blockers")),
                *source_blockers,
            ]
        )
    if isinstance(rule.get("blocked_cell_contract"), dict):
        options["blocked_cell_contract"] = rule.get("blocked_cell_contract")
    if shell:
        options["shell"] = True
    if isinstance(rule.get("env"), dict):
        options["env"] = render_paper_performance_template_value(
            rule.get("env"),
            cell,
            extra_fields=per_run_placeholders,
        )
    return options


def paper_performance_sample_contract() -> Dict[str, Any]:
    return {
        "required_fields": ["dataset", "benchmark", "allocator", "run_index", "seconds"],
        "required_provenance": ["command", "host_or_target", "raw_evidence_path_or_uri", "raw_evidence_sha256"],
        "timing_fields": [
            "seconds",
            "wall_seconds",
            "elapsed_seconds",
            "ns_per_iter",
            "time_ns",
            "nanoseconds",
            "ms",
            "milliseconds",
        ],
        "claim_grade_rule": (
            "every successful sample must carry command provenance, host/target provenance, "
            "verified raw evidence paths or URIs, sha256 digests for the raw evidence, "
            "benchmark-owned JSON timing, and paper-exact source provenance for external workloads"
        ),
        "example_jsonl_record": {
            "dataset": "default_performance",
            "benchmark": "RJS-Compiler",
            "allocator": "jemalloc",
            "run_index": 1,
            "seconds": 10.91,
            "command": ["./run-paper-workload", "--benchmark", "RJS-Compiler", "--allocator", "jemalloc"],
            "host": {"system": "Linux", "machine": "x86_64"},
            "evidence": [
                {
                    "path": "logs/default_performance-RJS-Compiler-jemalloc-run1.stdout.txt",
                    "sha256": "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef",
                }
            ],
        },
    }


def paper_performance_sample_template_record(cell: Dict[str, Any], run_index: int) -> Dict[str, Any]:
    fields = paper_performance_template_fields(cell)
    evidence_stub = (
        f"logs/{fields['dataset_slug']}-{fields['benchmark_slug']}-"
        f"{fields['allocator_slug']}-run{run_index}.stdout.txt"
    )
    return {
        "dataset": cell["dataset"],
        "benchmark": cell["benchmark"],
        "allocator": cell["allocator"],
        "run_index": run_index,
        "seconds": "<replace-with-finite-seconds>",
        "command": [
            "/path/to/paper-workload-wrapper",
            "--dataset",
            cell["dataset"],
            "--benchmark",
            cell["benchmark"],
            "--allocator",
            cell["allocator"],
        ],
        "host": {
            "system": "<replace-with-host-system>",
            "machine": "<replace-with-host-machine>",
        },
        "evidence": [
            {
                "path": evidence_stub,
                "sha256": "<replace-with-64-hex-sha256>",
            }
        ],
        "category": cell.get("category"),
        "variant_feature": cell.get("variant_feature"),
        "paper_row_id": cell.get("paper_row_id"),
        "reference": cell.get("reference"),
        "role": cell.get("role"),
        "template_only": True,
        "template_note": "Fill real timing/provenance before import-paper-performance-samples; this placeholder is not evidence.",
    }


def build_paper_performance_sample_template(
    cfg: Dict[str, Any],
    paper_dir: Path,
    *,
    dataset_names: List[str],
    required_runs: int,
) -> Dict[str, Any]:
    cells, target_errors = required_performance_sample_cells(cfg, paper_dir, dataset_names)
    records = [
        paper_performance_sample_template_record(cell, run_index)
        for cell in cells
        for run_index in range(1, required_runs + 1)
    ]
    by_dataset: Dict[str, Dict[str, Any]] = {}
    for cell in cells:
        item = by_dataset.setdefault(
            cell["dataset"],
            {"cell_count": 0, "sample_count": 0, "benchmarks": set(), "allocators": set()},
        )
        item["cell_count"] += 1
        item["sample_count"] += required_runs
        item["benchmarks"].add(cell["benchmark"])
        item["allocators"].add(cell["allocator"])
    for item in by_dataset.values():
        item["benchmarks"] = sorted(item["benchmarks"])
        item["allocators"] = sorted(item["allocators"])
    return {
        "schema_version": 1,
        "generated_at": now_iso(),
        "source": "paper-performance-sample-template",
        "paper_dir": str(paper_dir),
        "dataset_names": dataset_names,
        "required_runs_per_cell": required_runs,
        "sample_contract": paper_performance_sample_contract(),
        "summary": {
            "required_cell_count": len(cells),
            "template_sample_count": len(records),
            "dataset_count": len(by_dataset),
            "target_error_count": len(target_errors),
            "datasets": by_dataset,
        },
        "target_errors": target_errors,
        "notes": [
            "This is a JSONL fill-in template for import-paper-performance-samples, not performance evidence.",
            "Replace placeholder seconds, command, host, evidence path, and sha256 values with real run artifacts.",
            "Use import-paper-performance-samples --claim-grade only after every required row/column/run has verified raw evidence.",
        ],
        "records": records,
    }


def write_paper_performance_sample_template(path: Path, template: Dict[str, Any]) -> Path:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8") as f:
        for record in template.get("records", []):
            json.dump(record, f, sort_keys=True)
            f.write("\n")
    summary_path = path.with_name(path.name + ".summary.json")
    summary = {k: v for k, v in template.items() if k != "records"}
    write_json(summary_path, summary)
    return summary_path


def paper_collections_driver_command(
    cell: Dict[str, Any],
    *,
    bench_filter: Optional[str] = None,
    extra_features: Optional[List[str]] = None,
    allow_host_allocator_mismatch: bool = False,
    compiler_site_replay_type_mapping: Optional[str] = None,
    compiler_site_id_mode: str = "cyclic-replay",
    compiler_site_replay_limit: Optional[int] = None,
    compiler_site_recovery_scope: str = "thread-local",
) -> List[str]:
    command = [
        "python3",
        "evaluation/scripts/paper_workload_driver.py",
        "--dataset",
        str(cell.get("dataset") or ""),
        "--benchmark",
        str(cell.get("benchmark") or ""),
        "--allocator",
        str(cell.get("allocator") or ""),
    ]
    variant = str(cell.get("variant_feature") or "")
    if variant:
        command.extend(["--variant-feature", variant])
    if bench_filter:
        command.extend(["--bench-filter", bench_filter])
    for feature in extra_features or []:
        command.extend(["--extra-feature", feature])
    if allow_host_allocator_mismatch:
        command.append("--allow-host-allocator-mismatch")
    if compiler_site_replay_type_mapping and collections_cell_uses_unialloc_semantic_policy(cell):
        command.extend(["--compiler-site-replay-type-mapping", str(compiler_site_replay_type_mapping)])
        command.extend(["--compiler-site-id-mode", str(compiler_site_id_mode or "cyclic-replay")])
        command.extend(
            ["--compiler-site-recovery-scope", str(compiler_site_recovery_scope or "thread-local")]
        )
        if compiler_site_replay_limit is not None:
            command.extend(["--compiler-site-replay-limit", str(int(compiler_site_replay_limit))])
    return command


def collections_cell_uses_unialloc_semantic_policy(cell: Dict[str, Any]) -> bool:
    """True when a local Collections cell needs compiler type-id replay.

    Baseline allocators in semantic datasets intentionally do not receive
    UniAlloc's runtime metadata stream.  Only UniAlloc semantic variants need
    the bridge from a MIR type_mapping artifact into paper_workload_driver.py.
    """

    if str(cell.get("allocator") or "") != "unialloc":
        return False
    dataset = str(cell.get("dataset") or "")
    variant = str(cell.get("variant_feature") or "")
    return dataset in SEMANTIC_COLLECTIONS_DATASETS or variant in SEMANTIC_COLLECTIONS_VARIANT_FEATURES


def paper_collections_docker_driver_command(
    cell: Dict[str, Any],
    *,
    image: Optional[str] = None,
    platform_name: Optional[str] = None,
    bench_filter: Optional[str] = None,
    extra_features: Optional[List[str]] = None,
    allow_host_allocator_mismatch: bool = False,
    scudo_mode: Optional[str] = None,
    scudo_runtime_library: Optional[str] = None,
) -> List[str]:
    command = [
        "python3",
        "evaluation/scripts/paper_collections_docker_driver.py",
        "--dataset",
        str(cell.get("dataset") or ""),
        "--benchmark",
        str(cell.get("benchmark") or ""),
        "--allocator",
        str(cell.get("allocator") or ""),
    ]
    variant = str(cell.get("variant_feature") or "")
    if variant:
        command.extend(["--variant-feature", variant])
    if image:
        command.extend(["--image", str(image)])
    if platform_name:
        command.extend(["--platform", str(platform_name)])
    if bench_filter:
        command.extend(["--bench-filter", bench_filter])
    for feature in extra_features or []:
        command.extend(["--extra-feature", feature])
    if str(cell.get("allocator") or "") == "scudo" and scudo_mode:
        command.extend(["--scudo-mode", str(scudo_mode)])
    if str(cell.get("allocator") or "") == "scudo" and scudo_runtime_library:
        command.extend(["--scudo-runtime-library", str(scudo_runtime_library)])
    if allow_host_allocator_mismatch:
        command.append("--allow-host-allocator-mismatch")
    return command


def prepend_env_path(existing: Optional[str], path: Path) -> str:
    prefix = str(path)
    if not existing:
        return prefix
    parts = [part for part in str(existing).split(os.pathsep) if part]
    if prefix in parts:
        return str(existing)
    return os.pathsep.join([prefix, *parts])


def append_env_flags(existing: Optional[str], flags: str) -> str:
    parts = [part for part in str(existing or "").split() if part]
    for flag in flags.split():
        if flag not in parts:
            parts.append(flag)
    return " ".join(parts)


def normalize_optional_path(value: Optional[str]) -> Optional[Path]:
    if not value:
        return None
    path = Path(str(value)).expanduser()
    if not path.is_absolute():
        path = (ROOT / path).resolve()
    return path


def path_mtime(path: Path) -> float:
    try:
        return path.stat().st_mtime
    except OSError:
        return 0.0


def tcmalloc_library_files(path: Optional[Path]) -> List[str]:
    if not path:
        return []
    return sorted(name for name in TCMALLOC_LIBRARY_NAMES if (path / name).exists())


def tcmalloc_library_dir_is_usable(path: Optional[Path]) -> bool:
    return bool(path and path.is_dir() and tcmalloc_library_files(path))


def discover_tcmalloc_library_candidates() -> List[Dict[str, Any]]:
    candidates: List[Dict[str, Any]] = []
    seen = set()
    for pattern in TCMALLOC_LIBRARY_DIR_GLOBS:
        for path in ROOT.glob(pattern):
            key = str(path.resolve())
            if key in seen:
                continue
            seen.add(key)
            files = tcmalloc_library_files(path)
            candidates.append(
                {
                    "source": "repo_auto_discovery",
                    "pattern": pattern,
                    "path": str(path),
                    "exists": path.exists(),
                    "is_dir": path.is_dir(),
                    "library_files": files,
                    "usable": bool(path.is_dir() and files),
                    "mtime": path_mtime(path),
                }
            )
    return sorted(candidates, key=lambda item: (float(item.get("mtime") or 0.0), str(item.get("path") or "")), reverse=True)


def tcmalloc_library_probe() -> Dict[str, Any]:
    configured_candidates: List[Dict[str, Any]] = []
    selected: Optional[Path] = None
    for env_key in ("UNIALLOC_TCMALLOC_LIB_DIR", "TCMALLOC_LIB_DIR"):
        raw = os.environ.get(env_key)
        path = normalize_optional_path(raw)
        files = sorted(name for name in TCMALLOC_LIBRARY_NAMES if path and (path / name).exists())
        candidate = {
            "env_key": env_key,
            "value": raw,
            "path": str(path) if path else None,
            "exists": bool(path and path.exists()),
            "is_dir": bool(path and path.is_dir()),
            "library_files": files,
        }
        configured_candidates.append(candidate)
        if selected is None and tcmalloc_library_dir_is_usable(path):
            selected = path
    discovered_candidates = discover_tcmalloc_library_candidates()
    if selected is None:
        for candidate in discovered_candidates:
            if candidate.get("usable"):
                selected = Path(str(candidate.get("path"))).resolve()
                break
    return {
        "ctypes_find_library_tcmalloc": ctypes.util.find_library("tcmalloc"),
        "ctypes_find_library_tcmalloc_minimal": ctypes.util.find_library("tcmalloc_minimal"),
        "driver_required_library_name": "tcmalloc",
        "configured_candidates": configured_candidates,
        "auto_discovery_candidates": discovered_candidates,
        "configured_library_dir": str(selected) if selected else None,
        "configured_library_files": tcmalloc_library_files(selected),
    }


def discover_cmake_candidates() -> List[Dict[str, Any]]:
    candidates: List[Dict[str, Any]] = []
    seen = set()
    for pattern in CMAKE_BIN_GLOBS:
        for path in ROOT.glob(pattern):
            key = str(path.resolve())
            if key in seen:
                continue
            seen.add(key)
            candidates.append(
                {
                    "source": "repo_auto_discovery",
                    "pattern": pattern,
                    "path": str(path),
                    "exists": path.exists(),
                    "is_file": path.is_file(),
                    "executable": bool(path.is_file() and os.access(path, os.X_OK)),
                    "usable": bool(path.is_file() and os.access(path, os.X_OK)),
                    "mtime": path_mtime(path),
                }
            )
    return sorted(candidates, key=lambda item: (float(item.get("mtime") or 0.0), str(item.get("path") or "")), reverse=True)


def cmake_binary_probe() -> Dict[str, Any]:
    candidates: List[Dict[str, Any]] = []
    selected: Optional[Path] = None
    for env_key in ("UNIALLOC_CMAKE_BIN", "CMAKE_BIN", "CMAKE"):
        raw = os.environ.get(env_key)
        path = normalize_optional_path(raw)
        candidate = {
            "env_key": env_key,
            "value": raw,
            "path": str(path) if path else None,
            "exists": bool(path and path.exists()),
            "is_file": bool(path and path.is_file()),
            "executable": bool(path and path.is_file() and os.access(path, os.X_OK)),
        }
        candidates.append(candidate)
        if selected is None and path and path.is_file() and os.access(path, os.X_OK):
            selected = path
    path_lookup = shutil.which("cmake")
    discovered_candidates = discover_cmake_candidates()
    if selected is None and path_lookup:
        selected = Path(path_lookup)
    if selected is None:
        for candidate in discovered_candidates:
            if candidate.get("usable"):
                selected = Path(str(candidate.get("path"))).resolve()
                break
    return {
        "configured_candidates": candidates,
        "auto_discovery_candidates": discovered_candidates,
        "configured_cmake_bin": str(selected) if selected else None,
        "path_lookup": path_lookup,
    }


def rustc_toolchain_command_prefix() -> List[str]:
    rustc = shutil.which("rustc") or "rustc"
    command = [rustc]
    toolchain = (ROOT / "rust-toolchain").read_text(encoding="utf-8").strip() if (ROOT / "rust-toolchain").exists() else ""
    if toolchain:
        command.append(f"+{toolchain}")
    return command


def scudo_toolchain_probe() -> Dict[str, Any]:
    global _SCUDO_TOOLCHAIN_PROBE_CACHE
    if _SCUDO_TOOLCHAIN_PROBE_CACHE is not None:
        return dict(_SCUDO_TOOLCHAIN_PROBE_CACHE)
    command = [
        *rustc_toolchain_command_prefix(),
        "-",
        "--crate-name",
        "___unialloc_scudo_probe",
        "--print=cfg",
        "-Z",
        "sanitizer=scudo",
    ]
    try:
        proc = subprocess.run(
            command,
            input="fn main() {}\n",
            cwd=str(ROOT),
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=20,
        )
        result = {
            "command": command,
            "ok": proc.returncode == 0,
            "exit_code": proc.returncode,
            "rustflags": SCUDO_SANITIZER_RUSTFLAGS,
            "stdout_tail": proc.stdout[-2000:],
            "stderr_tail": proc.stderr[-4000:],
        }
    except subprocess.TimeoutExpired as exc:
        result = {
            "command": command,
            "ok": False,
            "exit_code": None,
            "timed_out": True,
            "rustflags": SCUDO_SANITIZER_RUSTFLAGS,
            "stdout_tail": subprocess_text(exc.stdout)[-2000:],
            "stderr_tail": subprocess_text(exc.stderr)[-4000:],
        }
    _SCUDO_TOOLCHAIN_PROBE_CACHE = dict(result)
    return result


def local_collections_dependency_env(cell: Dict[str, Any]) -> Dict[str, str]:
    allocator = str(cell.get("allocator") or "")
    env: Dict[str, str] = {}
    if allocator == "scudo":
        env["RUSTFLAGS"] = append_env_flags(os.environ.get("RUSTFLAGS"), SCUDO_SANITIZER_RUSTFLAGS)
        return env
    if allocator == "tcmalloc":
        probe = tcmalloc_library_probe()
        lib_dir = probe.get("configured_library_dir")
        if lib_dir:
            env["UNIALLOC_TCMALLOC_LIB_DIR"] = str(lib_dir)
    if allocator not in {"snmalloc", "tcmalloc"}:
        return env
    cmake_probe = cmake_binary_probe()
    cmake_bin = cmake_probe.get("configured_cmake_bin")
    if cmake_bin:
        env["UNIALLOC_CMAKE_BIN"] = str(cmake_bin)
    return env


def tcmalloc_library_available() -> bool:
    probe = tcmalloc_library_probe()
    return bool(probe.get("ctypes_find_library_tcmalloc") or probe.get("configured_library_dir"))


def scudo_toolchain_available() -> bool:
    return bool(scudo_toolchain_probe().get("ok"))


def local_collections_driver_support(
    cell: Dict[str, Any],
    *,
    allow_host_allocator_mismatch: bool = False,
) -> Tuple[bool, Optional[str]]:
    benchmark = str(cell.get("benchmark") or "")
    allocator = str(cell.get("allocator") or "")
    if benchmark != "Collections":
        return False, "only the paper Collections row has an in-tree std_bench driver"
    supported = {"unialloc", "jemalloc", "mimalloc", "tcmalloc", "snmalloc", "ptmalloc", "scudo"}
    if allocator not in supported:
        return False, f"allocator has no local Collections driver mapping: {allocator}"
    if allocator == "ptmalloc" and platform.system() != "Linux" and not allow_host_allocator_mismatch:
        return False, "ptmalloc paper evidence requires a Linux/glibc host"
    if allocator == "tcmalloc" and not tcmalloc_library_available():
        return False, "tcmalloc link library was not found on this host"
    if allocator == "scudo" and not scudo_toolchain_available():
        return False, "scudo sanitizer runtime is not supported by the active Rust toolchain/target"
    return True, None


def load_external_adapter_config_audit(path: Optional[str] = None) -> Optional[Dict[str, Any]]:
    audit_path = Path(path).expanduser() if path else RESULTS / "paper_external_workload_config_audit.json"
    if not audit_path.exists():
        return None
    audit = read_json(audit_path)
    if not isinstance(audit, dict):
        return None
    audit["_audit_path"] = str(audit_path)
    return audit


def external_adapter_config_records(config_audit: Optional[Dict[str, Any]]) -> List[Dict[str, Any]]:
    if not isinstance(config_audit, dict):
        return []
    records = config_audit.get("configs")
    if not isinstance(records, list):
        return []
    return [record for record in records if isinstance(record, dict)]


def external_adapter_config_record_for_cell(
    cell: Dict[str, Any],
    config_audit: Optional[Dict[str, Any]],
) -> Optional[Dict[str, Any]]:
    benchmark = str(cell.get("benchmark") or "")
    dataset = str(cell.get("dataset") or "")
    category = str(cell.get("category") or "")
    matches: List[Dict[str, Any]] = []
    for record in external_adapter_config_records(config_audit):
        if not wrapper_pattern_matches(record.get("benchmarks"), benchmark):
            continue
        if not wrapper_pattern_matches(record.get("datasets"), dataset):
            continue
        categories = record.get("categories")
        if categories and not wrapper_pattern_matches(categories, category):
            continue
        matches.append(record)
    if not matches:
        return None
    matches.sort(
        key=lambda record: (
            record.get("claim_grade_runner_ready") is not True,
            record.get("runner_ready") is not True,
            str(record.get("rule_id") or ""),
        )
    )
    return matches[0]


def external_adapter_runner_command(cell: Dict[str, Any], adapter_script: Any) -> List[str]:
    return [
        "python3",
        str(adapter_script),
        "--dataset",
        str(cell.get("dataset") or ""),
        "--benchmark",
        str(cell.get("benchmark") or ""),
        "--allocator",
        str(cell.get("allocator") or ""),
        "--variant-feature",
        str(cell.get("variant_feature") or ""),
        "--run-index",
        "{run_index}",
        "--json",
    ]


def cargo_features_declared() -> List[str]:
    cargo_toml = ROOT / "unialloc" / "Cargo.toml"
    if not cargo_toml.exists():
        return []
    if tomllib is not None:
        try:
            data = tomllib.loads(cargo_toml.read_text(encoding="utf-8"))
            features = data.get("features", {}) if isinstance(data, dict) else {}
            if isinstance(features, dict):
                return sorted(str(name) for name in features)
        except Exception:
            pass
    in_features = False
    names: List[str] = []
    for raw in cargo_toml.read_text(encoding="utf-8").splitlines():
        line = raw.strip()
        if line.startswith("[") and line.endswith("]"):
            in_features = line == "[features]"
            continue
        if in_features and line and not line.startswith("#") and "=" in line:
            names.append(line.split("=", 1)[0].strip())
    return sorted(names)


def cargo_toolchain_command_prefix() -> List[str]:
    cargo = shutil.which("cargo") or "cargo"
    command = [cargo]
    toolchain = (ROOT / "rust-toolchain").read_text(encoding="utf-8").strip() if (ROOT / "rust-toolchain").exists() else ""
    if toolchain:
        command.append(f"+{toolchain}")
    return command


def shell_probe(
    command: List[str],
    *,
    timeout: int,
    cwd: Optional[Path] = None,
    env_overrides: Optional[Dict[str, str]] = None,
) -> Dict[str, Any]:
    started = time.time()
    env = os.environ.copy()
    env.setdefault("GLIBC_TUNABLES", "glibc.pthread.rseq=0")
    for key, value in (env_overrides or {}).items():
        env[str(key)] = str(value)
    tcmalloc_dir = env.get("UNIALLOC_TCMALLOC_LIB_DIR")
    if tcmalloc_dir:
        env["LIBRARY_PATH"] = prepend_env_path(env.get("LIBRARY_PATH"), Path(tcmalloc_dir))
        env["DYLD_LIBRARY_PATH"] = prepend_env_path(env.get("DYLD_LIBRARY_PATH"), Path(tcmalloc_dir))
    cmake_bin = env.get("UNIALLOC_CMAKE_BIN")
    if cmake_bin:
        env["PATH"] = prepend_env_path(env.get("PATH"), Path(cmake_bin).parent)
    try:
        proc = subprocess.run(
            command,
            cwd=str(cwd or ROOT),
            env=env,
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=timeout,
        )
        return {
            "command": command,
            "exit_code": proc.returncode,
            "ok": proc.returncode == 0,
            "duration_seconds": round(time.time() - started, 3),
            "stdout_tail": proc.stdout[-4000:],
            "stderr_tail": proc.stderr[-4000:],
        }
    except subprocess.TimeoutExpired as exc:
        return {
            "command": command,
            "exit_code": None,
            "ok": False,
            "duration_seconds": round(time.time() - started, 3),
            "timed_out": True,
            "stdout_tail": (exc.stdout or "")[-4000:] if isinstance(exc.stdout, str) else "",
            "stderr_tail": (exc.stderr or "")[-4000:] if isinstance(exc.stderr, str) else "",
        }
    except Exception as exc:  # pragma: no cover - diagnostic path
        return {
            "command": command,
            "exit_code": None,
            "ok": False,
            "duration_seconds": round(time.time() - started, 3),
            "error": str(exc),
        }


def cargo_link_probe_warning_audit(probe: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    """Summarize compiler warnings from a narrow cargo bench link probe."""

    stderr = str((probe or {}).get("stderr_tail") or "")
    lazy_marker = "iterators are lazy and do nothing unless consumed"
    unused_must_use_marker = "unused_must_use"
    return {
        "schema_version": 1,
        "source": "cargo-link-probe-warning-audit",
        "warning_tail_present": bool(stderr.strip()),
        "unused_must_use_warning_count": stderr.count(unused_must_use_marker),
        "lazy_iterator_warning_count": stderr.count(lazy_marker),
        "claim_grade_blockers": (
            ["cargo link probe reported lazy iterator unused_must_use warnings in benchmark source"]
            if lazy_marker in stderr
            else []
        ),
    }


def homebrew_package_probe(package: str) -> Dict[str, Any]:
    brew = shutil.which("brew")
    if not brew:
        return {"package": package, "brew_path": None, "installed": False, "versions": []}
    versions = shell_probe([brew, "list", "--versions", package], timeout=10, cwd=ROOT)
    prefix = shell_probe([brew, "--prefix", package], timeout=10, cwd=ROOT)
    return {
        "package": package,
        "brew_path": brew,
        "installed": bool(versions.get("ok") and str(versions.get("stdout_tail") or "").strip()),
        "versions": str(versions.get("stdout_tail") or "").strip().split(),
        "prefix": str(prefix.get("stdout_tail") or "").strip() if prefix.get("ok") else None,
        "list_probe": versions,
    }


def allocator_link_probe_command(allocator: str, feature: str, bench_filter: str) -> List[str]:
    command = cargo_toolchain_command_prefix()
    command.extend(["bench", "-p", "unialloc", "--bench", "std_bench", "--features", feature])
    command.extend([bench_filter, "--", "--test"])
    return command


def build_collections_allocator_preflight_audit(
    cfg: Dict[str, Any],
    paper_dir: Path,
    *,
    dataset_names: List[str],
    allow_host_allocator_mismatch: bool = False,
    link_probe_allocators: Optional[List[str]] = None,
    link_probe_timeout: int = 60,
    link_probe_bench_filter: str = "vec::bench_new",
) -> Dict[str, Any]:
    required_cells, target_errors = required_performance_sample_cells(cfg, paper_dir, dataset_names)
    collections_cells = [cell for cell in required_cells if cell.get("benchmark") == "Collections"]
    feature_names = set(cargo_features_declared())
    link_probe_set = set(link_probe_allocators or [])
    allocators: Dict[str, Dict[str, Any]] = {}

    for cell in collections_cells:
        allocator = str(cell.get("allocator") or "")
        record = allocators.setdefault(
            allocator,
            {
                "allocator": allocator,
                "required_cell_count": 0,
                "datasets": [],
                "feature": COLLECTIONS_ALLOCATOR_FEATURES.get(allocator),
                "feature_declared": False,
                "library_probe": {},
                "host_probe": {},
                "package_probe": {},
                "link_probe": None,
                "capability": {},
                "claim_grade_ready_on_this_host": False,
                "claim_grade_blockers": [],
            },
        )
        record["required_cell_count"] += 1
        dataset = str(cell.get("dataset") or "")
        if dataset and dataset not in record["datasets"]:
            record["datasets"].append(dataset)
        capability = paper_performance_cell_capability(
            cell,
            allow_host_allocator_mismatch=allow_host_allocator_mismatch,
        )
        record["capability"] = capability

    for allocator, record in sorted(allocators.items()):
        feature = record.get("feature")
        record["datasets"] = sorted(record.get("datasets", []))
        record["feature_declared"] = bool(feature and feature in feature_names)
        record["host_probe"] = {
            "system": platform.system(),
            "machine": platform.machine(),
            "libc": platform.libc_ver(),
            "ptmalloc_claim_host_ok": bool(platform.system() == "Linux"),
        }
        if allocator == "tcmalloc":
            record["library_probe"] = tcmalloc_library_probe()
            record["build_dependency_probe"] = {"cmake": cmake_binary_probe()}
            record["package_probe"] = {"homebrew_gperftools": homebrew_package_probe("gperftools")}
        elif allocator == "scudo":
            record["library_probe"] = {
                "ctypes_find_library_scudo": ctypes.util.find_library("scudo"),
                "in_tree_feature": feature,
                "scudo_toolchain_probe": scudo_toolchain_probe(),
            }
        elif allocator == "ptmalloc":
            record["library_probe"] = {
                "glibc_required": True,
                "platform_libc": platform.libc_ver(),
            }
        elif allocator == "snmalloc":
            record["library_probe"] = {
                "cargo_feature_only_probe": True,
                "feature": feature,
                "cmake_required_for_fresh_build": True,
            }
            record["build_dependency_probe"] = {"cmake": cmake_binary_probe()}
        elif allocator in {"jemalloc", "mimalloc", "unialloc"}:
            record["library_probe"] = {
                "cargo_feature_only_probe": True,
                "feature": feature,
            }

        if allocator in link_probe_set and feature:
            link_probe_env = local_collections_dependency_env({"allocator": allocator})
            record["link_probe"] = shell_probe(
                allocator_link_probe_command(allocator, str(feature), link_probe_bench_filter),
                timeout=link_probe_timeout,
                cwd=ROOT,
                env_overrides=link_probe_env,
            )
            if link_probe_env:
                record["link_probe"]["env_overrides"] = link_probe_env
            record["link_probe_warning_audit"] = cargo_link_probe_warning_audit(record["link_probe"])

        blockers: List[str] = []
        capability = record.get("capability", {}) if isinstance(record.get("capability"), dict) else {}
        if capability.get("claim_grade_blocker"):
            blockers.append(str(capability.get("claim_grade_blocker")))
        if feature and not record.get("feature_declared"):
            blockers.append(f"Cargo feature {feature} is not declared")
        if allocator == "scudo" and not feature:
            blockers.append("scudo has no in-tree Collections feature mapping")
        if allocator == "scudo" and not scudo_toolchain_available():
            blockers.append("scudo sanitizer runtime is not supported by the active Rust toolchain/target")
        if allocator == "snmalloc" and not (record.get("build_dependency_probe", {}).get("cmake", {}).get("configured_cmake_bin")):
            blockers.append("snmalloc fresh build requires cmake")
        if allocator == "ptmalloc" and platform.system() != "Linux" and not allow_host_allocator_mismatch:
            blockers.append("ptmalloc requires Linux/glibc host provenance for paper Collections evidence")
        if allocator == "tcmalloc" and not (
            record.get("library_probe", {}).get("ctypes_find_library_tcmalloc")
            or record.get("library_probe", {}).get("configured_library_dir")
        ):
            blockers.append("local dynamic linker cannot resolve libtcmalloc")
        link_probe = record.get("link_probe")
        if isinstance(link_probe, dict) and not link_probe.get("ok"):
            blockers.append("narrow cargo bench link probe failed")
        warning_audit = record.get("link_probe_warning_audit")
        if isinstance(warning_audit, dict):
            blockers.extend(str(item) for item in warning_audit.get("claim_grade_blockers", []) if str(item).strip())
        record["claim_grade_blockers"] = sorted(set(blockers))
        record["claim_grade_ready_on_this_host"] = (
            bool(capability.get("locally_runnable"))
            and bool(record.get("feature_declared") or allocator == "unialloc")
            and not record["claim_grade_blockers"]
        )

    blocked_allocators = {
        name: rec
        for name, rec in allocators.items()
        if rec.get("required_cell_count") and not rec.get("claim_grade_ready_on_this_host")
    }
    link_probe_records = [
        rec.get("link_probe") for rec in allocators.values() if isinstance(rec.get("link_probe"), dict)
    ]
    return {
        "schema_version": 1,
        "generated_at": now_iso(),
        "source": "paper-collections-allocator-preflight-audit",
        "paper_dir": str(paper_dir),
        "dataset_names": dataset_names,
        "allow_host_allocator_mismatch": allow_host_allocator_mismatch,
        "host": host_metadata(),
        "rust_toolchain_file": (ROOT / "rust-toolchain").read_text(encoding="utf-8").strip() if (ROOT / "rust-toolchain").exists() else None,
        "link_probe": {
            "enabled_allocators": sorted(link_probe_set),
            "bench_filter": link_probe_bench_filter,
            "timeout_seconds": link_probe_timeout,
        },
        "summary": {
            "target_error_count": len(target_errors),
            "collections_required_cell_count": len(collections_cells),
            "collections_allocator_count": len(allocators),
            "claim_grade_ready_allocator_count": sum(
                1 for rec in allocators.values() if rec.get("claim_grade_ready_on_this_host")
            ),
            "blocked_allocator_count": len(blocked_allocators),
            "blocked_required_cell_count": sum(int(rec.get("required_cell_count") or 0) for rec in blocked_allocators.values()),
            "link_probe_count": len(link_probe_records),
            "link_probe_failure_count": sum(1 for probe in link_probe_records if not probe.get("ok")),
            "link_probe_unused_must_use_warning_count": sum(
                int((rec.get("link_probe_warning_audit") or {}).get("unused_must_use_warning_count") or 0)
                for rec in allocators.values()
            ),
            "link_probe_lazy_iterator_warning_count": sum(
                int((rec.get("link_probe_warning_audit") or {}).get("lazy_iterator_warning_count") or 0)
                for rec in allocators.values()
            ),
            "ready_for_claim_grade_collections_on_this_host": not target_errors and not blocked_allocators,
        },
        "target_errors": target_errors,
        "allocators": allocators,
        "notes": [
            "This audit explains local Collections allocator feasibility; it is not performance evidence.",
            "ptmalloc paper evidence requires Linux/glibc host provenance unless a run is explicitly marked as a non-claim smoke run.",
            "tcmalloc must resolve and link libtcmalloc before local std_bench cells can be treated as runnable.",
            "scudo has an in-tree bench feature but remains blocked unless the active Rust toolchain/target accepts the scudo sanitizer runtime or an external wrapper supplies provenance.",
        ],
    }


def audit_paper_collections_allocator_preflight(args: argparse.Namespace) -> int:
    cfg = load_config()
    paper_dir = Path(args.paper_dir or cfg.get("paper_dir_default", "")).expanduser()
    if not paper_dir.exists():
        print(f"paper dir not found: {paper_dir}", file=sys.stderr)
        return 2
    dataset_names = performance_plan_dataset_names(
        cfg,
        selected=args.dataset,
        include_all_paper_data=bool(args.all_paper_data),
    )
    link_probe_allocators = list(args.link_probe_allocator or [])
    if args.link_probe_all:
        link_probe_allocators = sorted(COLLECTIONS_ALLOCATOR_FEATURES)
    audit = build_collections_allocator_preflight_audit(
        cfg,
        paper_dir,
        dataset_names=dataset_names,
        allow_host_allocator_mismatch=bool(args.allow_host_allocator_mismatch),
        link_probe_allocators=link_probe_allocators,
        link_probe_timeout=int(args.link_probe_timeout),
        link_probe_bench_filter=str(args.link_probe_bench_filter),
    )
    run_id = args.run_id or _dt.datetime.now().strftime("paper-collections-allocator-preflight-%Y%m%d-%H%M%S")
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)
    raw_path = out_dir / "paper-collections-allocator-preflight-audit.json"
    write_json(raw_path, audit)
    if not args.no_update_results:
        write_json(RESULTS / "paper_collections_allocator_preflight_audit.json", audit)
    summary = {
        "raw_audit": str(raw_path),
        "results_audit": None if args.no_update_results else str(RESULTS / "paper_collections_allocator_preflight_audit.json"),
        **audit.get("summary", {}),
    }
    print(json.dumps(summary, indent=2, sort_keys=True))
    return 0 if audit.get("summary", {}).get("ready_for_claim_grade_collections_on_this_host") else 1


def paper_performance_cell_capability(
    cell: Dict[str, Any],
    *,
    allow_host_allocator_mismatch: bool = False,
    external_config_audit: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Classify how a required paper-performance cell can be produced.

    The classification is intentionally about runner capability, not evidence
    quality.  Even locally runnable cells still need repeated execution,
    provenance, and import validation before they can support a paper claim.
    """
    benchmark = str(cell.get("benchmark") or "")
    allocator = str(cell.get("allocator") or "")
    supported, reason = local_collections_driver_support(
        cell,
        allow_host_allocator_mismatch=allow_host_allocator_mismatch,
    )
    if supported:
        dependency_env = local_collections_dependency_env(cell)
        return {
            "kind": "local_collections_driver",
            "locally_runnable": True,
            "claim_grade_blocker": None,
            "reason": "in-tree std_bench Collections driver is available for this allocator/dataset cell",
            **({"dependency_env": dependency_env} if dependency_env else {}),
        }
    if benchmark != "Collections":
        adapter_record = external_adapter_config_record_for_cell(cell, external_config_audit)
        if adapter_record and adapter_record.get("claim_grade_runner_ready") is True:
            source_contract = adapter_record.get("source_contract") if isinstance(adapter_record.get("source_contract"), dict) else {}
            source_class = str(
                source_contract.get("source_provenance_class")
                or adapter_record.get("source_provenance_class")
                or ""
            ).strip()
            if source_contract.get("accepted_newer_checkout_pin_complete") is True or source_class == USER_ACCEPTED_NEWER_SOURCE_PROVENANCE_CLASS:
                source_reason = (
                    "strict external paper workload adapter is runner-ready with an explicitly accepted "
                    "pinned newer benchmark checkout labelled non-paper-exact, selector coverage, and "
                    "benchmark-owned JSON timing contract"
                )
            else:
                source_reason = (
                    "strict external paper workload adapter is runner-ready with exact checkout, "
                    "selector coverage, and benchmark-owned JSON timing contract"
                )
            return {
                "kind": "external_adapter_claim_grade_runner",
                "locally_runnable": True,
                "external_adapter_runner_ready": True,
                "claim_grade_blocker": None,
                "reason": source_reason,
                "external_rule_id": adapter_record.get("rule_id"),
                "adapter_script": adapter_record.get("adapter_script"),
                "adapter_config": adapter_record.get("adapter_active_config"),
                "real_workload_dir": adapter_record.get("resolved_real_workload_dir"),
                "source_contract": {
                    key: source_contract.get(key)
                    for key in [
                        "claim_grade_complete",
                        "exact_checkout_pin_complete",
                        "accepted_newer_checkout_pin_complete",
                        "paper_exact_claim_grade_complete",
                        "paper_exact_ref_complete",
                        "reproducible_snapshot_complete",
                        "source_provenance_class",
                    ]
                },
            }
        if adapter_record and adapter_record.get("runner_ready") is True:
            source_contract = adapter_record.get("source_contract") if isinstance(adapter_record.get("source_contract"), dict) else {}
            runner_blockers = [
                str(item)
                for item in adapter_record.get("claim_grade_runner_blockers", [])
                if str(item).strip()
            ]
            source_blockers = [
                str(item)
                for item in source_contract.get("blockers", [])
                if str(item).strip()
            ]
            reason_tail = "; ".join([*runner_blockers, *source_blockers[:3]])
            return {
                "kind": "external_workload_required",
                "locally_runnable": False,
                "external_adapter_runner_ready": True,
                "claim_grade_blocker": "external adapter is runnable but not claim-grade ready",
                "reason": (
                    "external adapter is structurally runner-ready but lacks claim-grade runner gates: "
                    + reason_tail
                ).rstrip(": "),
                "external_rule_id": adapter_record.get("rule_id"),
                "adapter_script": adapter_record.get("adapter_script"),
                "adapter_config": adapter_record.get("adapter_active_config"),
            }
        return {
            "kind": "external_workload_required",
            "locally_runnable": False,
            "claim_grade_blocker": "external paper workload wrapper required",
            "reason": reason or "paper macro/web row has no in-tree runner",
        }
    if allocator == "ptmalloc" and platform.system() != "Linux" and not allow_host_allocator_mismatch:
        return {
            "kind": "host_blocked_allocator",
            "locally_runnable": False,
            "claim_grade_blocker": "Linux/glibc host required for ptmalloc paper evidence",
            "reason": reason or "ptmalloc paper evidence requires a Linux/glibc host",
        }
    if allocator == "scudo":
        return {
            "kind": "toolchain_blocked_allocator",
            "locally_runnable": False,
            "claim_grade_blocker": "scudo sanitizer runtime/toolchain support required",
            "reason": reason or "scudo sanitizer runtime is not supported by the active Rust toolchain/target",
        }
    if allocator == "tcmalloc" and "tcmalloc" in str(reason or ""):
        return {
            "kind": "missing_allocator_dependency",
            "locally_runnable": False,
            "claim_grade_blocker": "tcmalloc system library or wrapper support required on this host",
            "reason": reason or "tcmalloc link library was not found on this host",
        }
    return {
        "kind": "unsupported_local_collections_allocator",
        "locally_runnable": False,
        "claim_grade_blocker": reason or "allocator has no local Collections driver mapping",
        "reason": reason or "allocator has no local Collections driver mapping",
    }


def paper_performance_wrapper_command_template(cell: Dict[str, Any]) -> List[str]:
    return [
        "/path/to/paper-workload-wrapper",
        "--dataset",
        str(cell.get("dataset") or ""),
        "--benchmark",
        str(cell.get("benchmark") or ""),
        "--allocator",
        str(cell.get("allocator") or ""),
        "--variant",
        str(cell.get("variant_feature") or "default"),
        "--json",
    ]


def paper_performance_wrapper_contract_record(
    cell: Dict[str, Any],
    *,
    required_runs: int,
    allow_host_allocator_mismatch: bool = False,
    external_config_audit: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    capability = paper_performance_cell_capability(
        cell,
        allow_host_allocator_mismatch=allow_host_allocator_mismatch,
        external_config_audit=external_config_audit,
    )
    command_template: Any
    if capability.get("kind") == "local_collections_driver":
        command_template = paper_collections_driver_command(
            cell,
            allow_host_allocator_mismatch=allow_host_allocator_mismatch,
        )
    elif capability.get("kind") == "external_adapter_claim_grade_runner":
        command_template = external_adapter_runner_command(cell, capability.get("adapter_script"))
    else:
        command_template = paper_performance_wrapper_command_template(cell)
    return {
        "dataset": cell["dataset"],
        "benchmark": cell["benchmark"],
        "allocator": cell["allocator"],
        "role": cell.get("role"),
        "category": cell.get("category"),
        "paper_row_id": cell.get("paper_row_id"),
        "variant_feature": cell.get("variant_feature"),
        "reference": cell.get("reference"),
        "required_runs": required_runs,
        "capability": capability,
        "command_template": command_template,
        "cwd": ".",
        "measurement": "stdout_json",
        "time_field": "seconds",
        "timeout": 1800,
        "required_stdout_json_fields": ["seconds"],
        "required_sample_fields": paper_performance_sample_contract()["required_fields"],
        "required_provenance": paper_performance_sample_contract()["required_provenance"],
        "required_evidence": [
            "stdout/stderr logs for every run",
            "command line and environment/allocator selection for every run",
            "host or target metadata proving the intended platform/allocator",
            "sha256 digest for each raw evidence file",
        ],
        "claim_grade_ready": False,
        "claim_grade_runner_ready": capability.get("kind") == "external_adapter_claim_grade_runner",
        "template_only": capability.get("kind") not in {
            "local_collections_driver",
            "external_adapter_claim_grade_runner",
        },
        "template_note": (
            "This is a runner contract. It becomes evidence only after the command is replaced/executed, "
            "the samples contain finite timings, and import-paper-performance-samples verifies provenance."
        ),
    }


def build_paper_performance_wrapper_contracts(
    cfg: Dict[str, Any],
    paper_dir: Path,
    *,
    dataset_names: List[str],
    required_runs: int,
    allow_host_allocator_mismatch: bool = False,
    external_config_audit: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    cells, target_errors = required_performance_sample_cells(cfg, paper_dir, dataset_names)
    contracts = [
        paper_performance_wrapper_contract_record(
            cell,
            required_runs=required_runs,
            allow_host_allocator_mismatch=allow_host_allocator_mismatch,
            external_config_audit=external_config_audit,
        )
        for cell in cells
    ]
    capability_counts: Dict[str, int] = {}
    datasets: Dict[str, Dict[str, Any]] = {}
    for contract in contracts:
        kind = str(contract.get("capability", {}).get("kind") or "unknown")
        capability_counts[kind] = capability_counts.get(kind, 0) + 1
        dataset = str(contract.get("dataset") or "")
        item = datasets.setdefault(
            dataset,
            {
                "required_cells": 0,
                "required_samples": 0,
                "capability_counts": {},
                "locally_runnable_cells": 0,
                "external_or_blocked_cells": 0,
                "benchmarks": set(),
                "allocators": set(),
            },
        )
        item["required_cells"] += 1
        item["required_samples"] += required_runs
        item["capability_counts"][kind] = item["capability_counts"].get(kind, 0) + 1
        if contract.get("capability", {}).get("locally_runnable"):
            item["locally_runnable_cells"] += 1
        else:
            item["external_or_blocked_cells"] += 1
        item["benchmarks"].add(contract.get("benchmark"))
        item["allocators"].add(contract.get("allocator"))

    for item in datasets.values():
        item["benchmarks"] = sorted(str(v) for v in item["benchmarks"] if v)
        item["allocators"] = sorted(str(v) for v in item["allocators"] if v)

    external_or_blocked = [
        contract
        for contract in contracts
        if not contract.get("capability", {}).get("locally_runnable")
    ]
    return {
        "schema_version": 1,
        "generated_at": now_iso(),
        "source": "paper-performance-wrapper-contracts",
        "paper_dir": str(paper_dir),
        "external_config_audit": external_config_audit.get("_audit_path") if isinstance(external_config_audit, dict) else None,
        "host": host_metadata(),
        "dataset_names": dataset_names,
        "methodology": cfg.get("methodology", {}),
        "required_runs_per_cell": required_runs,
        "allow_host_allocator_mismatch": allow_host_allocator_mismatch,
        "summary": {
            "dataset_count": len(datasets),
            "required_cell_count": len(cells),
            "required_sample_count": len(cells) * required_runs,
            "target_error_count": len(target_errors),
            "capability_counts": capability_counts,
            "locally_runnable_cell_count": sum(
                1 for contract in contracts if contract.get("capability", {}).get("locally_runnable")
            ),
            "external_adapter_claim_grade_runner_cell_count": sum(
                1
                for contract in contracts
                if contract.get("capability", {}).get("kind") == "external_adapter_claim_grade_runner"
            ),
            "external_or_blocked_cell_count": len(external_or_blocked),
            "claim_grade_ready": False,
        },
        "datasets": datasets,
        "target_errors": target_errors,
        "sample_contract": paper_performance_sample_contract(),
        "notes": [
            "This artifact is a wrapper contract and capability matrix, not timing evidence.",
            "external_adapter_claim_grade_runner means the cell has a real adapter command and exact-checkout runner gate; repeated finite timing samples are still required before claim import.",
            "External and blocked cells must be replaced by real workload commands before run-paper-performance-plan.",
            "All cells still require repeated finite samples, raw evidence, sha256 digests, and import validation.",
        ],
        "contracts": contracts,
    }


def generate_paper_performance_wrapper_contracts(args: argparse.Namespace) -> int:
    cfg = load_config()
    paper_dir = Path(args.paper_dir or cfg.get("paper_dir_default", "")).expanduser()
    if not paper_dir.exists():
        print(f"paper dir not found: {paper_dir}", file=sys.stderr)
        return 2
    dataset_names = performance_plan_dataset_names(
        cfg,
        selected=args.dataset,
        include_all_paper_data=bool(args.all_paper_data),
    )
    required_runs = int(args.required_runs or cfg.get("methodology", {}).get("runs_per_benchmark", 6))
    external_config_audit = load_external_adapter_config_audit(getattr(args, "external_config_audit", None))
    run_id = args.run_id or _dt.datetime.now().strftime("paper-performance-wrapper-contracts-%Y%m%d-%H%M%S")
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)
    contracts = build_paper_performance_wrapper_contracts(
        cfg,
        paper_dir,
        dataset_names=dataset_names,
        required_runs=required_runs,
        allow_host_allocator_mismatch=bool(args.allow_host_allocator_mismatch),
        external_config_audit=external_config_audit,
    )
    contract_path = Path(args.contract_out).expanduser() if args.contract_out else out_dir / "paper-performance-wrapper-contracts.json"
    write_json(contract_path, contracts)
    raw_path = out_dir / "paper-performance-wrapper-contracts.json"
    if raw_path.resolve() != contract_path.resolve():
        write_json(raw_path, contracts)
    if not args.no_update_results:
        write_json(RESULTS / "paper_performance_wrapper_contracts.json", contracts)
    summary = {
        "contract": str(contract_path),
        "raw_contract": str(raw_path),
        "dataset_names": dataset_names,
        **contracts.get("summary", {}),
    }
    print(json.dumps(summary, indent=2, sort_keys=True))
    return 0


def blocked_collections_cell_remediation(capability: Dict[str, Any]) -> List[str]:
    kind = str(capability.get("kind") or "")
    if kind == "host_blocked_allocator":
        return [
            "rerun the Collections allocator cell on a Linux/glibc host",
            "record libc/OS/architecture metadata in the sample host or target provenance",
            "preserve the benchmark stdout/stderr logs with sha256 digests before import",
        ]
    if kind == "missing_allocator_dependency":
        return [
            "install or build the requested allocator runtime/library for the benchmark host",
            "rerun the narrow link probe and record a passing probe artifact",
            "run the full Collections row with allocator-selection provenance and raw evidence digests",
        ]
    if kind == "unsupported_allocator":
        return [
            "add an in-tree allocator feature or external wrapper for the requested allocator",
            "prove the wrapper selects the requested allocator for the Collections row",
            "run the full Collections row with repeated finite samples and raw evidence digests",
        ]
    if kind == "toolchain_blocked_allocator":
        return [
            "run the Collections cell with a Rust toolchain/target that accepts the scudo sanitizer runtime",
            "record the sanitizer/toolchain probe and allocator-selection flags in provenance",
            "run the full Collections row with repeated finite samples and raw evidence digests",
        ]
    return [
        "replace the template wrapper with a real paper workload runner",
        "prove allocator selection and host/target provenance",
        "run repeated finite samples and preserve raw evidence digests",
    ]


def blocked_collections_cell_required_evidence(capability: Dict[str, Any]) -> List[str]:
    kind = str(capability.get("kind") or "")
    common = [
        "paper-performance sample records for every required run",
        "command and allocator-selection provenance",
        "stdout/stderr raw evidence with sha256 digests",
        "host or target metadata matching the allocator requirements",
    ]
    if kind == "host_blocked_allocator":
        return [
            "Linux/glibc host metadata for ptmalloc",
            *common,
        ]
    if kind == "missing_allocator_dependency":
        return [
            "passing allocator library/link probe artifact",
            *common,
        ]
    if kind == "unsupported_allocator":
        return [
            "allocator wrapper or feature implementation evidence",
            *common,
        ]
    if kind == "toolchain_blocked_allocator":
        return [
            "passing scudo sanitizer toolchain/runtime probe artifact",
            *common,
        ]
    return common


def paper_workload_wrapper_manifest_rule(
    contract: Dict[str, Any],
    *,
    external_bundle_path: str = "evaluation/config/paper_external_workloads.template.json",
    docker_collections_driver: bool = False,
    docker_collections_image: Optional[str] = None,
    docker_collections_platform: Optional[str] = None,
    docker_collections_scudo_mode: Optional[str] = None,
    docker_collections_scudo_runtime_library: Optional[str] = None,
) -> Dict[str, Any]:
    cell = {
        "dataset": contract.get("dataset"),
        "benchmark": contract.get("benchmark"),
        "allocator": contract.get("allocator"),
        "variant_feature": contract.get("variant_feature"),
    }
    fields = paper_performance_template_fields(cell)
    capability = contract.get("capability") if isinstance(contract.get("capability"), dict) else {}
    if capability.get("kind") == "external_adapter_claim_grade_runner":
        command_template = contract.get("command_template")
        if command_template is None:
            command_template = external_adapter_runner_command(cell, capability.get("adapter_script"))
        template_note = (
            "This rule directly invokes the strict external adapter already promoted as exact-checkout "
            "claim-grade-runner-ready. It is runner wiring only; finite repeated timing samples and import "
            "validation are still required before claims pass."
        )
        template_only = False
        claim_grade_blockers = []
        blocked_cell_contract = None
        rule_env = None
    elif capability.get("kind") == "external_workload_required":
        command_template: Any = [
            "python3",
            "evaluation/scripts/paper_external_workload.py",
            "--bundle",
            external_bundle_path,
            "--dataset",
            "{dataset}",
            "--benchmark",
            "{benchmark}",
            "--allocator",
            "{allocator}",
            "--variant-feature",
            "{variant_feature}",
            "--category",
            "{category}",
            "--run-id",
            "{dataset_slug}-{benchmark_slug}-{allocator_slug}",
        ]
        template_note = (
            "This rule delegates external macro execution to paper_external_workload.py. "
            "Readiness is determined by auditing the referenced external workload bundle; "
            "template bundles and missing workload directories are rejected before plan execution."
        )
        template_only = False
        claim_grade_blockers = unique_strings([capability.get("claim_grade_blocker"), capability.get("reason")])
        blocked_cell_contract = None
        rule_env: Optional[Dict[str, Any]] = external_adapter_selector_env_template()
    elif (
        docker_collections_driver
        and str(contract.get("benchmark") or "") == "Collections"
        and str(capability.get("kind") or "") in {"host_blocked_allocator", "toolchain_blocked_allocator"}
    ):
        command_template = paper_collections_docker_driver_command(
            cell,
            image=docker_collections_image,
            platform_name=docker_collections_platform,
            scudo_mode=docker_collections_scudo_mode,
            scudo_runtime_library=docker_collections_scudo_runtime_library,
        )
        template_note = (
            "This rule delegates a host/toolchain-blocked Collections cell to "
            "paper_collections_docker_driver.py. It remains fail-closed until "
            "audit dry-run proves Docker image, glibc, Python, Cargo, and the "
            "repo-pinned Rust toolchain are available."
        )
        template_only = False
        claim_grade_blockers = []
        blocked_cell_contract = None
        rule_env = None
        capability = {
            "kind": "docker_collections_driver",
            "locally_runnable": False,
            "containerized_runner": True,
            "runner_requires_dry_run_probe": True,
            "reason": (
                "blocked host/toolchain Collections cell is wired through "
                "evaluation/scripts/paper_collections_docker_driver.py"
            ),
            "source_capability": capability,
        }
    else:
        claim_grade_blockers = unique_strings([capability.get("claim_grade_blocker"), capability.get("reason")])
        required_remediation = blocked_collections_cell_remediation(capability)
        required_evidence = blocked_collections_cell_required_evidence(capability)
        command_template = [
            "python3",
            "evaluation/scripts/paper_blocked_workload.py",
            "--dataset",
            "{dataset}",
            "--benchmark",
            "{benchmark}",
            "--allocator",
            "{allocator}",
            "--variant-feature",
            "{variant_feature}",
            "--capability-kind",
            str(capability.get("kind") or "blocked"),
            "--reason",
            str(capability.get("reason") or capability.get("claim_grade_blocker") or "paper workload is blocked on this host"),
        ]
        for item in required_remediation:
            command_template.extend(["--required-remediation", str(item)])
        for item in required_evidence:
            command_template.extend(["--required-evidence", str(item)])
        template_note = (
            "This non-template wrapper emits structured blocked JSON and exits nonzero; it is not "
            "performance evidence and must be replaced by real host/toolchain evidence before claim import."
        )
        template_only = False
        blocked_cell_contract = {
            "status": "not_runnable_on_this_host",
            "capability_kind": capability.get("kind"),
            "capability_reason": capability.get("reason"),
            "claim_grade_blockers": claim_grade_blockers,
            "required_remediation": required_remediation,
            "required_evidence": required_evidence,
            "blocked_wrapper_command": "evaluation/scripts/paper_blocked_workload.py",
        }
        rule_env = external_adapter_selector_env_template()
    rule = {
        "id": f"wrap-{fields['dataset_slug']}-{fields['benchmark_slug']}-{fields['allocator_slug']}",
        "dataset": contract.get("dataset"),
        "benchmark": contract.get("benchmark"),
        "allocator": contract.get("allocator"),
        "category": contract.get("category"),
        "variant_feature": contract.get("variant_feature"),
        "paper_row_id": contract.get("paper_row_id"),
        "capability_kind": capability.get("kind"),
        "capability_reason": capability.get("reason"),
        "capability": capability,
        "claim_grade_blockers": claim_grade_blockers,
        "required_runs": contract.get("required_runs"),
        "command_template": command_template,
        "cwd": ".",
        "measurement": "stdout_json",
        "time_field": "seconds",
        "timeout": contract.get("timeout", 1800),
        "template_only": template_only,
        "template_note": template_note,
        **({"blocked_cell_contract": blocked_cell_contract} if blocked_cell_contract else {}),
    }
    if rule_env is not None:
        rule["env"] = rule_env
    return rule


def build_paper_workload_wrapper_manifest_template(
    cfg: Dict[str, Any],
    paper_dir: Path,
    *,
    dataset_names: List[str],
    required_runs: int,
    allow_host_allocator_mismatch: bool = False,
    external_config_audit: Optional[Dict[str, Any]] = None,
    external_bundle_path: str = "evaluation/config/paper_external_workloads.template.json",
    docker_collections_driver: bool = False,
    docker_collections_image: Optional[str] = None,
    docker_collections_platform: Optional[str] = None,
    docker_collections_scudo_mode: Optional[str] = None,
    docker_collections_scudo_runtime_library: Optional[str] = None,
) -> Dict[str, Any]:
    contracts = build_paper_performance_wrapper_contracts(
        cfg,
        paper_dir,
        dataset_names=dataset_names,
        required_runs=required_runs,
        allow_host_allocator_mismatch=allow_host_allocator_mismatch,
        external_config_audit=external_config_audit,
    )
    wrapper_contracts = [
        contract
        for contract in contracts.get("contracts", [])
        if isinstance(contract, dict) and not contract.get("capability", {}).get("locally_runnable")
    ]
    rules = [
        paper_workload_wrapper_manifest_rule(
            contract,
            external_bundle_path=external_bundle_path,
            docker_collections_driver=docker_collections_driver,
            docker_collections_image=docker_collections_image,
            docker_collections_platform=docker_collections_platform,
            docker_collections_scudo_mode=docker_collections_scudo_mode,
            docker_collections_scudo_runtime_library=docker_collections_scudo_runtime_library,
        )
        for contract in wrapper_contracts
    ]
    return {
        "schema_version": 1,
        "generated_at": now_iso(),
        "source": "paper-workload-wrapper-manifest-template",
        "paper_dir": str(paper_dir),
        "dataset_names": dataset_names,
        "required_runs_per_cell": required_runs,
        "allow_host_allocator_mismatch": allow_host_allocator_mismatch,
        "external_config_audit": external_config_audit.get("_audit_path") if isinstance(external_config_audit, dict) else None,
        "external_workload_bundle": external_bundle_path,
        "summary": {
            **contracts.get("summary", {}),
            "wrapper_required_cell_count": len(wrapper_contracts),
            "template_rule_count": len(rules),
            "external_bundle_delegated_rule_count": sum(
                1 for rule in rules if rule.get("capability_kind") == "external_workload_required"
            ),
            "docker_collections_driver_rule_count": sum(
                1 for rule in rules if rule.get("capability_kind") == "docker_collections_driver"
            ),
            "ready_for_plan": False,
        },
        "capability_summary": contracts.get("summary", {}),
        "sample_contract": paper_performance_sample_contract(),
        "notes": [
            "This manifest template is not performance evidence.",
            "Rules are generated only for required cells that are not locally runnable on this host.",
            "External macro rules delegate to paper_external_workload.py and inherit readiness from the referenced external workload bundle audit.",
            "Host/toolchain-blocked Collections rules can delegate to paper_collections_docker_driver.py when --docker-collections-driver is used; audit dry-run must pass before timing runs.",
            "Host/dependency/allocator-blocked rules use paper_blocked_workload.py to emit structured non-claim JSON instead of placeholder commands.",
            "Blocked wrapper commands must still be replaced with real host/toolchain evidence before claim-grade import.",
            "The wrapper command should emit JSON containing the configured time_field and preserve raw evidence for import-paper-performance-samples.",
        ],
        "rules": rules,
    }


def generate_paper_workload_wrapper_manifest_template(args: argparse.Namespace) -> int:
    cfg = load_config()
    paper_dir = Path(args.paper_dir or cfg.get("paper_dir_default", "")).expanduser()
    if not paper_dir.exists():
        print(f"paper dir not found: {paper_dir}", file=sys.stderr)
        return 2
    dataset_names = performance_plan_dataset_names(
        cfg,
        selected=args.dataset,
        include_all_paper_data=bool(args.all_paper_data),
    )
    required_runs = int(args.required_runs or cfg.get("methodology", {}).get("runs_per_benchmark", 6))
    external_config_audit = load_external_adapter_config_audit(getattr(args, "external_config_audit", None))
    run_id = args.run_id or _dt.datetime.now().strftime("paper-workload-wrapper-manifest-template-%Y%m%d-%H%M%S")
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)
    manifest = build_paper_workload_wrapper_manifest_template(
        cfg,
        paper_dir,
        dataset_names=dataset_names,
        required_runs=required_runs,
        allow_host_allocator_mismatch=bool(args.allow_host_allocator_mismatch),
        external_config_audit=external_config_audit,
        external_bundle_path=str(args.external_workload_bundle),
        docker_collections_driver=bool(args.docker_collections_driver),
        docker_collections_image=args.docker_collections_image,
        docker_collections_platform=args.docker_collections_platform,
        docker_collections_scudo_mode=args.docker_collections_scudo_mode,
        docker_collections_scudo_runtime_library=args.docker_collections_scudo_runtime_library,
    )
    manifest_path = (
        Path(args.manifest_out).expanduser()
        if args.manifest_out
        else EVAL / "config" / "paper_workload_wrappers.template.json"
    )
    tracked_manifest = portable_tracked_template(manifest, paper_dir=paper_dir)
    write_json(manifest_path, tracked_manifest)
    raw_path = out_dir / "paper-workload-wrapper-manifest.template.json"
    if raw_path.resolve() != manifest_path.resolve():
        write_json(raw_path, manifest)
    summary = {
        "manifest": str(manifest_path),
        "raw_manifest": str(raw_path),
        "dataset_names": dataset_names,
        **manifest.get("summary", {}),
    }
    print(json.dumps(summary, indent=2, sort_keys=True))
    return 0


def build_paper_workload_wrapper_manifest_audit(
    cfg: Dict[str, Any],
    paper_dir: Path,
    manifest: Dict[str, Any],
    *,
    dataset_names: List[str],
    required_runs: int,
    allow_host_allocator_mismatch: bool = False,
    external_config_audit: Optional[Dict[str, Any]] = None,
    dry_run_probe: bool = False,
    dry_run_probe_limit: int = 0,
    dry_run_probe_timeout: int = 30,
) -> Dict[str, Any]:
    required_cells, target_errors = required_performance_sample_cells(cfg, paper_dir, dataset_names)
    datasets: Dict[str, Dict[str, Any]] = {}
    locally_runnable_cells: List[Dict[str, Any]] = []
    wrapper_covered_cells: List[Dict[str, Any]] = []
    missing_wrapper_cells: List[Dict[str, Any]] = []
    template_only_wrapper_cells: List[Dict[str, Any]] = []
    invalid_wrapper_cells: List[Dict[str, Any]] = []
    dry_run_probe_failures: List[Dict[str, Any]] = []
    capability_counts: Dict[str, int] = {}
    wrapper_required_cells: List[Dict[str, Any]] = []
    dry_run_probe_count = 0
    dry_run_probe_skipped_count = 0
    dry_run_probe_limit_value = max(0, int(dry_run_probe_limit or 0))

    for cell in required_cells:
        capability = paper_performance_cell_capability(
            cell,
            allow_host_allocator_mismatch=allow_host_allocator_mismatch,
            external_config_audit=external_config_audit,
        )
        kind = str(capability.get("kind") or "unknown")
        capability_counts[kind] = capability_counts.get(kind, 0) + 1
        dataset_summary = datasets.setdefault(
            cell["dataset"],
            {
                "required_cells": 0,
                "locally_runnable_cells": 0,
                "wrapper_required_cells": 0,
                "wrapper_covered_cells": 0,
                "missing_wrapper_cells": 0,
                "template_only_wrapper_cells": 0,
                "invalid_wrapper_cells": 0,
                "capability_counts": {},
            },
        )
        dataset_summary["required_cells"] += 1
        dataset_summary["capability_counts"][kind] = dataset_summary["capability_counts"].get(kind, 0) + 1
        cell_record = {**cell, "capability": capability}
        if capability.get("locally_runnable"):
            locally_runnable_cells.append(cell_record)
            dataset_summary["locally_runnable_cells"] += 1
            continue

        wrapper_required_cells.append(cell_record)
        dataset_summary["wrapper_required_cells"] += 1
        rule = find_wrapper_rule(manifest, cell)
        if rule is None:
            missing_wrapper_cells.append(cell_record)
            dataset_summary["missing_wrapper_cells"] += 1
            continue
        issues = wrapper_rule_issues(rule, cell)
        template_issues = [issue for issue in issues if wrapper_rule_template_issue(issue)]
        invalid_issues = [issue for issue in issues if not wrapper_rule_template_issue(issue)]
        probe_record: Optional[Dict[str, Any]] = None
        if dry_run_probe and not issues:
            command_template = rule.get("command_template") if "command_template" in rule else rule.get("command")
            try:
                rendered_command = render_paper_performance_command_parts(
                    command_template,
                    cell,
                    shell=bool(rule.get("shell")),
                )
                probe_candidate = wrapper_external_workload_dry_run_probe(
                    rendered_command,
                    cell,
                    timeout=dry_run_probe_timeout,
                )
                if probe_candidate is None:
                    probe_candidate = docker_collections_driver_dry_run_probe(
                        command_parts_for_external_bundle_probe(rendered_command),
                        {
                            "cwd": rule.get("cwd", "."),
                            "env": rule.get("env") if isinstance(rule.get("env"), dict) else {},
                        },
                        cell,
                        timeout=dry_run_probe_timeout,
                    )
            except ValueError as exc:
                probe_candidate = {
                    "ok": False,
                    "issue": str(exc),
                }
            if probe_candidate is not None:
                if dry_run_probe_limit_value and dry_run_probe_count >= dry_run_probe_limit_value:
                    dry_run_probe_skipped_count += 1
                else:
                    probe_record = probe_candidate
                    dry_run_probe_count += 1
                    if not probe_record.get("ok"):
                        invalid_issues.append(str(probe_record.get("issue") or "wrapper manifest dry-run probe failed"))
        matched_record = {
            **cell_record,
            "wrapper_rule_id": rule.get("id") or rule.get("name"),
            "wrapper_rule_issues": issues,
        }
        raw_claim_blockers = rule.get("claim_grade_blockers", [])
        if not isinstance(raw_claim_blockers, list):
            raw_claim_blockers = [raw_claim_blockers]
        claim_blockers = unique_strings(raw_claim_blockers)
        if claim_blockers:
            matched_record["claim_grade_blockers"] = claim_blockers
        if isinstance(rule.get("blocked_cell_contract"), dict):
            matched_record["blocked_cell_contract"] = rule.get("blocked_cell_contract")
        if probe_record is not None:
            matched_record["dry_run_probe"] = probe_record
        if template_issues:
            template_only_wrapper_cells.append({**matched_record, "template_issues": template_issues})
            dataset_summary["template_only_wrapper_cells"] += 1
        if invalid_issues:
            invalid_wrapper_cells.append({**matched_record, "invalid_issues": invalid_issues})
            dataset_summary["invalid_wrapper_cells"] += 1
            if probe_record is not None and not probe_record.get("ok"):
                dry_run_probe_failures.append({**matched_record, "invalid_issues": invalid_issues})
        if not template_issues and not invalid_issues:
            wrapper_covered_cells.append(matched_record)
            dataset_summary["wrapper_covered_cells"] += 1

    wrapper_required_count = len(wrapper_required_cells)
    ready = (
        not target_errors
        and not missing_wrapper_cells
        and not template_only_wrapper_cells
        and not invalid_wrapper_cells
        and wrapper_required_count == len(wrapper_covered_cells)
    )
    return {
        "schema_version": 1,
        "generated_at": now_iso(),
        "source": "paper-workload-wrapper-manifest-audit",
        "paper_dir": str(paper_dir),
        "manifest": manifest.get("_manifest_path"),
        "external_config_audit": external_config_audit.get("_audit_path") if isinstance(external_config_audit, dict) else None,
        "dataset_names": dataset_names,
        "required_runs_per_cell": required_runs,
        "allow_host_allocator_mismatch": allow_host_allocator_mismatch,
        "summary": {
            "ready_for_plan": ready,
            "dataset_count": len(dataset_names),
            "required_cell_count": len(required_cells),
            "locally_runnable_cell_count": len(locally_runnable_cells),
            "wrapper_required_cell_count": wrapper_required_count,
            "wrapper_covered_cell_count": len(wrapper_covered_cells),
            "missing_wrapper_cell_count": len(missing_wrapper_cells),
            "template_only_wrapper_cell_count": len(template_only_wrapper_cells),
            "invalid_wrapper_cell_count": len(invalid_wrapper_cells),
            "target_error_count": len(target_errors),
            "capability_counts": capability_counts,
            "dry_run_probe_enabled": dry_run_probe,
            "dry_run_probe_count": dry_run_probe_count,
            "dry_run_probe_failure_count": len(dry_run_probe_failures),
            "dry_run_probe_skipped_count": dry_run_probe_skipped_count,
            "dry_run_probe_limit": dry_run_probe_limit_value,
            "dry_run_probe_timeout_seconds": dry_run_probe_timeout,
        },
        "datasets": datasets,
        "target_errors": target_errors,
        "missing_wrapper_cells": missing_wrapper_cells,
        "template_only_wrapper_cells": template_only_wrapper_cells,
        "invalid_wrapper_cells": invalid_wrapper_cells,
        "dry_run_probe_failures": dry_run_probe_failures,
        "wrapper_covered_cells": wrapper_covered_cells,
        "locally_runnable_cells": locally_runnable_cells,
        "wrapper_required_cells": wrapper_required_cells,
    }


def audit_paper_workload_wrapper_manifest(args: argparse.Namespace) -> int:
    cfg = load_config()
    paper_dir = Path(args.paper_dir or cfg.get("paper_dir_default", "")).expanduser()
    if not paper_dir.exists():
        print(f"paper dir not found: {paper_dir}", file=sys.stderr)
        return 2
    try:
        manifest = load_wrapper_manifest(args.manifest)
    except (FileNotFoundError, ValueError) as exc:
        print(str(exc), file=sys.stderr)
        return 2
    assert manifest is not None
    dataset_names = performance_plan_dataset_names(
        cfg,
        selected=args.dataset,
        include_all_paper_data=bool(args.all_paper_data),
    )
    required_runs = int(args.required_runs or cfg.get("methodology", {}).get("runs_per_benchmark", 6))
    external_config_audit = load_external_adapter_config_audit(getattr(args, "external_config_audit", None))
    audit = build_paper_workload_wrapper_manifest_audit(
        cfg,
        paper_dir,
        manifest,
        dataset_names=dataset_names,
        required_runs=required_runs,
        allow_host_allocator_mismatch=bool(args.allow_host_allocator_mismatch),
        external_config_audit=external_config_audit,
        dry_run_probe=bool(args.dry_run_probe),
        dry_run_probe_limit=int(args.dry_run_probe_limit or 0),
        dry_run_probe_timeout=int(args.dry_run_probe_timeout or 30),
    )
    run_id = args.run_id or _dt.datetime.now().strftime("paper-workload-wrapper-manifest-audit-%Y%m%d-%H%M%S")
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)
    audit_path = out_dir / "paper-workload-wrapper-manifest-audit.json"
    write_json(audit_path, audit)
    if not args.no_update_results:
        write_json(RESULTS / "paper_workload_wrapper_manifest_audit.json", audit)
    summary = {
        "audit": str(audit_path),
        "manifest": args.manifest,
        "dataset_names": dataset_names,
        **audit.get("summary", {}),
    }
    print(json.dumps(summary, indent=2, sort_keys=True))
    return 0 if audit["summary"]["ready_for_plan"] else 1


def load_external_workload_bundle(path: Optional[str]) -> Optional[Dict[str, Any]]:
    if not path:
        return None
    bundle_path = Path(path).expanduser()
    if not bundle_path.exists():
        raise FileNotFoundError(f"external workload bundle not found: {bundle_path}")
    bundle = read_json(bundle_path)
    if not isinstance(bundle, dict):
        raise ValueError("external workload bundle must be a JSON object")
    bundle["_bundle_path"] = str(bundle_path)
    return bundle


def paper_external_workload_bundle_rules(bundle: Optional[Dict[str, Any]]) -> List[Dict[str, Any]]:
    if not bundle:
        return []
    rules = bundle.get("workloads")
    if rules is None:
        rules = bundle.get("rules")
    if not isinstance(rules, list):
        return []
    return [rule for rule in rules if isinstance(rule, dict)]


def find_external_workload_bundle_rule(bundle: Optional[Dict[str, Any]], cell: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    for rule in paper_external_workload_bundle_rules(bundle):
        if wrapper_rule_matches(rule, cell):
            return rule
    return None


def default_external_workload_bundle_rule_by_id(rule_id: str) -> Optional[Dict[str, Any]]:
    """Return an external bundle rule by id for wrapper-manifest provenance checks.

    Paper-performance wrapper rows often invoke external workloads indirectly
    through ``paper_external_workload.py --bundle ...``.  Those wrapper rows
    intentionally do not duplicate the external workload's paper_source metadata;
    the authoritative source contract remains in the external workload bundle.
    """

    text = str(rule_id or "").strip()
    if not text:
        return None
    global _DEFAULT_EXTERNAL_WORKLOAD_BUNDLE_CACHE
    if _DEFAULT_EXTERNAL_WORKLOAD_BUNDLE_CACHE is None:
        try:
            _DEFAULT_EXTERNAL_WORKLOAD_BUNDLE_CACHE = load_external_workload_bundle(
                str(DEFAULT_EXTERNAL_WORKLOAD_BUNDLE)
            )
        except (FileNotFoundError, ValueError, json.JSONDecodeError):
            _DEFAULT_EXTERNAL_WORKLOAD_BUNDLE_CACHE = {}
    for rule in paper_external_workload_bundle_rules(_DEFAULT_EXTERNAL_WORKLOAD_BUNDLE_CACHE):
        candidate = str(rule.get("id") or rule.get("name") or "").strip()
        if candidate == text:
            return rule
    return None


def external_workload_required_cells(
    cfg: Dict[str, Any],
    paper_dir: Path,
    *,
    dataset_names: List[str],
    allow_host_allocator_mismatch: bool = False,
) -> Tuple[List[Dict[str, Any]], List[Dict[str, Any]]]:
    cells, target_errors = required_performance_sample_cells(cfg, paper_dir, dataset_names)
    out: List[Dict[str, Any]] = []
    for cell in cells:
        capability = paper_performance_cell_capability(
            cell,
            allow_host_allocator_mismatch=allow_host_allocator_mismatch,
        )
        if capability.get("kind") == "external_workload_required":
            out.append({**cell, "capability": capability})
    return out, target_errors


def external_workload_bundle_template_fields(
    rule: Dict[str, Any],
    cell: Dict[str, Any],
    *,
    bundle_path: Optional[Path] = None,
) -> Dict[str, str]:
    fields = paper_performance_template_fields(cell)
    workload_dir = str(rule.get("workload_dir") or ".")
    fields.update(
        {
            "root": str(ROOT),
            "evaluation_dir": str(EVAL),
            "bundle": str(bundle_path or rule.get("_bundle_path") or ""),
            "bundle_dir": str((bundle_path or Path(rule.get("_bundle_path", "."))).parent),
            "workload_dir": workload_dir,
            "workload_dir_slug": slugify_label(workload_dir, "workload-dir"),
            "rule_id": str(rule.get("id") or rule.get("name") or ""),
            "run_id": "audit-run",
            "run_index": "1",
        }
    )
    return fields


def render_external_workload_template_value(value: Any, rule: Dict[str, Any], cell: Dict[str, Any]) -> Any:
    fields = external_workload_bundle_template_fields(rule, cell)
    if isinstance(value, str):
        try:
            return value.format(**fields)
        except KeyError as exc:
            missing = exc.args[0]
            raise ValueError(f"unknown external workload bundle placeholder: {missing}") from exc
    if isinstance(value, list):
        return [render_external_workload_template_value(item, rule, cell) for item in value]
    if isinstance(value, dict):
        return {str(key): render_external_workload_template_value(item, rule, cell) for key, item in value.items()}
    return value


def resolve_external_workload_path(raw: Any) -> Path:
    path = Path(str(raw or ".")).expanduser()
    if path.is_absolute():
        return path
    return ROOT / path


def external_bundle_allocator_selection_ready(rule: Dict[str, Any], allocator: str) -> bool:
    mode = str(rule.get("allocator_selection") or "").strip().lower()
    if mode in {"command_argument", "environment", "wrapper", "system"}:
        return True
    allocator_env = rule.get("allocator_env")
    if isinstance(allocator_env, dict):
        return allocator in allocator_env or "*" in allocator_env
    return False


def external_bundle_benchmark_owned_json_declared(rule: Dict[str, Any]) -> bool:
    contract = rule.get("timing_contract") if isinstance(rule.get("timing_contract"), dict) else {}
    measurement_source = str(
        rule.get("measurement_source")
        or rule.get("timing_source")
        or contract.get("measurement_source")
        or contract.get("source")
        or ""
    ).strip().lower()
    return (
        rule.get("benchmark_owned_json") is True
        or contract.get("benchmark_owned_json") is True
        or measurement_source in {"benchmark_owned_json", "benchmark-json", "benchmark_json"}
    )


def external_workload_bundle_rule_issues(rule: Dict[str, Any], cell: Optional[Dict[str, Any]] = None) -> List[str]:
    issues: List[str] = []
    template_only = bool(rule.get("template_only"))
    if template_only:
        issues.append("external workload bundle rule is template_only and must be replaced with a real workload repo command")
    workload_dir = rule.get("workload_dir")
    if not workload_dir:
        issues.append("external workload bundle rule is missing workload_dir")
    elif serialized_contains_template_marker(workload_dir):
        issues.append("external workload bundle workload_dir still contains placeholder/template markers")
    elif not template_only:
        rendered_dir = (
            render_external_workload_template_value(workload_dir, rule, cell)
            if cell is not None
            else workload_dir
        )
        resolved_dir = resolve_external_workload_path(rendered_dir)
        if not resolved_dir.exists():
            issues.append(f"external workload bundle workload_dir does not exist: {resolved_dir}")
    command = rule.get("command_template") if "command_template" in rule else rule.get("command")
    if command is None:
        issues.append("external workload bundle rule is missing command_template/command")
    elif cell is not None:
        try:
            rendered_command = render_external_workload_template_value(command, rule, cell)
            if serialized_contains_template_marker(rendered_command):
                issues.append("external workload bundle command still contains placeholder/template markers")
        except ValueError as exc:
            issues.append(str(exc))
    elif serialized_contains_template_marker(command):
        issues.append("external workload bundle command still contains placeholder/template markers")
    cwd = rule.get("cwd", "{workload_dir}")
    if not template_only and cell is not None:
        try:
            rendered_cwd = render_external_workload_template_value(cwd, rule, cell)
            resolved_cwd = resolve_external_workload_path(rendered_cwd)
            if not resolved_cwd.exists():
                issues.append(f"external workload bundle cwd does not exist: {resolved_cwd}")
        except ValueError as exc:
            issues.append(str(exc))
    measurement = str(rule.get("measurement") or "stdout_json").strip().lower()
    if measurement not in {"stdout_json", "json"}:
        issues.append("external workload bundle should use stdout_json measurement for claim-grade paper timing")
    if measurement in {"stdout_json", "json"} and not (rule.get("time_field") or rule.get("time_fields")):
        issues.append("external workload bundle stdout_json rule should name time_field/time_fields")
    if rule.get("claim_grade") is True and not external_bundle_benchmark_owned_json_declared(rule):
        issues.append("external workload bundle timing contract must mark benchmark_owned_json=true for claim-grade paper timing")
    if cell is not None and not external_bundle_allocator_selection_ready(rule, str(cell.get("allocator") or "")):
        issues.append("external workload bundle rule must define allocator_selection or allocator_env for this allocator")
    if "timeout" in rule:
        try:
            if int(rule.get("timeout")) <= 0:
                issues.append("external workload bundle timeout must be positive")
        except (TypeError, ValueError):
            issues.append("external workload bundle timeout must be an integer")
    return unique_strings(issues)


def external_workload_bundle_template_issue(issue: str) -> bool:
    lowered = issue.lower()
    return "template_only" in lowered or "placeholder" in lowered or "template markers" in lowered


def external_workload_adapter_state(resolved_workload_dir: Optional[Path]) -> Dict[str, Any]:
    if resolved_workload_dir is None:
        return {}
    script_path = resolved_workload_dir / "run_paper_workload.py"
    template_config_path = resolved_workload_dir / "workload_config.template.json"
    config_path = resolved_workload_dir / "workload_config.json"
    local_config_path = resolved_workload_dir / "workload_config.local.json"
    active_config_path: Optional[Path] = None
    config: Optional[Any] = None
    config_error: Optional[str] = None
    for candidate in (config_path, local_config_path):
        if not candidate.exists():
            continue
        active_config_path = candidate
        try:
            config = read_json(candidate)
        except Exception as exc:  # keep audit robust against partial hand-edits
            config_error = str(exc)
        break
    configured = isinstance(config, dict) and config.get("configured") is True
    state = {
        "adapter_script": str(script_path),
        "adapter_script_exists": script_path.exists(),
        "adapter_template_config": str(template_config_path),
        "adapter_template_config_exists": template_config_path.exists(),
        "adapter_config": str(config_path),
        "adapter_config_exists": config_path.exists(),
        "adapter_local_config": str(local_config_path),
        "adapter_local_config_exists": local_config_path.exists(),
        "adapter_active_config": str(active_config_path) if active_config_path else None,
        "adapter_configured": configured,
    }
    if config_error:
        state["adapter_config_error"] = config_error
    return state


def external_workload_queue_actions(
    *,
    cell: Dict[str, Any],
    rule: Optional[Dict[str, Any]],
    issues: List[str],
    workload_dir_exists: Optional[bool],
    cwd_exists: Optional[bool],
    adapter_script_exists: Optional[bool] = None,
    adapter_template_config_exists: Optional[bool] = None,
    adapter_configured: Optional[bool] = None,
) -> List[str]:
    actions: List[str] = []
    if rule is None:
        actions.append(
            "add an external workload bundle rule matching "
            f"{cell.get('dataset')}/{cell.get('benchmark')}/{cell.get('allocator')}"
        )
        return actions
    if rule.get("template_only"):
        actions.append("replace the template rule with a real workload checkout command and set template_only=false")
    if workload_dir_exists is False:
        actions.append("provide the workload_dir checkout or change workload_dir to the real macro benchmark repository")
    elif workload_dir_exists is True and adapter_script_exists is False:
        actions.append("generate or add a strict run_paper_workload.py adapter in the workload_dir")
    if workload_dir_exists is True and adapter_template_config_exists is False:
        actions.append("add workload_config.template.json documenting the real benchmark checkout contract")
    if workload_dir_exists is True and adapter_script_exists and adapter_configured is False:
        actions.append("copy workload_config.template.json to workload_config.json and point it at a real benchmark command")
    if cwd_exists is False:
        actions.append("make the rendered cwd exist before runner dry-run probing")
    if not external_bundle_allocator_selection_ready(rule, str(cell.get("allocator") or "")):
        actions.append("wire allocator selection through command arguments, environment, wrapper logic, or allocator_env")
    if not (rule.get("time_field") or rule.get("time_fields")):
        actions.append("declare the stdout JSON timing field used by the workload command")
    if rule.get("claim_grade") is True and not external_bundle_benchmark_owned_json_declared(rule):
        actions.append("mark the bundle timing contract as benchmark_owned_json=true only after the child command emits benchmark-owned JSON timing")
    command = rule.get("command_template") if "command_template" in rule else rule.get("command")
    if command is None:
        actions.append("define the command_template/command that runs exactly this paper workload cell")
    for issue in issues:
        lowered = issue.lower()
        if "placeholder" in lowered or "template markers" in lowered:
            actions.append("remove placeholder markers from rendered bundle fields")
        elif "does not exist" in lowered and "workload_dir" not in lowered and "cwd" not in lowered:
            actions.append(str(issue))
        elif "stdout_json" in lowered:
            actions.append("make the workload emit machine-readable JSON timing on stdout")
    actions.append("after the rule is real, run audit-paper-external-workload-bundle --dry-run-probe")
    return unique_strings(actions)


def build_external_workload_queue_record(
    cell: Dict[str, Any],
    rule: Optional[Dict[str, Any]],
    *,
    bundle_path: Optional[Path],
    required_runs: int,
) -> Dict[str, Any]:
    record: Dict[str, Any] = {
        "dataset": cell.get("dataset"),
        "benchmark": cell.get("benchmark"),
        "allocator": cell.get("allocator"),
        "category": cell.get("category"),
        "paper_row_id": cell.get("paper_row_id"),
        "variant_feature": cell.get("variant_feature"),
        "required_runs": required_runs,
        "capability": cell.get("capability", {}),
        "ready_for_runner": False,
    }
    if rule is None:
        record["bundle_rule_id"] = None
        record["bundle_rule_issues"] = ["missing external workload bundle rule"]
        record["required_actions"] = external_workload_queue_actions(
            cell=cell,
                rule=None,
                issues=record["bundle_rule_issues"],
                workload_dir_exists=None,
                cwd_exists=None,
            )
        return record

    rule_id = str(rule.get("id") or rule.get("name") or "")
    issues = external_workload_bundle_rule_issues(rule, cell)
    record.update(
        {
            "bundle_rule_id": rule_id,
            "template_only": bool(rule.get("template_only")),
            "measurement": str(rule.get("measurement") or "stdout_json"),
            "time_field": rule.get("time_field"),
            "time_fields": rule.get("time_fields"),
            "timeout": rule.get("timeout"),
            "allocator_selection": rule.get("allocator_selection"),
            "bundle_rule_issues": issues,
            "ready_for_runner": not issues,
        }
    )
    workload_dir_exists: Optional[bool] = None
    cwd_exists: Optional[bool] = None
    workload_dir = rule.get("workload_dir")
    adapter_state: Dict[str, Any] = {}
    if workload_dir is not None:
        try:
            rendered_dir = render_external_workload_template_value(workload_dir, rule, cell)
            resolved_dir = resolve_external_workload_path(rendered_dir)
            workload_dir_exists = resolved_dir.exists()
            record["rendered_workload_dir"] = str(rendered_dir)
            record["resolved_workload_dir"] = str(resolved_dir)
            record["workload_dir_exists"] = workload_dir_exists
            adapter_state = external_workload_adapter_state(resolved_dir)
            record.update(adapter_state)
        except ValueError as exc:
            record["workload_dir_render_error"] = str(exc)
    cwd = rule.get("cwd", "{workload_dir}")
    try:
        rendered_cwd = render_external_workload_template_value(cwd, rule, cell)
        resolved_cwd = resolve_external_workload_path(rendered_cwd)
        cwd_exists = resolved_cwd.exists()
        record["rendered_cwd"] = str(rendered_cwd)
        record["resolved_cwd"] = str(resolved_cwd)
        record["cwd_exists"] = cwd_exists
    except ValueError as exc:
        record["cwd_render_error"] = str(exc)
    command = rule.get("command_template") if "command_template" in rule else rule.get("command")
    if command is not None:
        try:
            rendered_command = render_external_workload_template_value(command, rule, cell)
            record["rendered_command"] = rendered_command
            record["rendered_command_shell"] = (
                " ".join(shlex.quote(str(part)) for part in rendered_command)
                if isinstance(rendered_command, list)
                else str(rendered_command)
            )
        except ValueError as exc:
            record["command_render_error"] = str(exc)
    if bundle_path is not None:
        record["bundle"] = str(bundle_path)
    record["required_actions"] = external_workload_queue_actions(
        cell=cell,
        rule=rule,
        issues=issues,
        workload_dir_exists=workload_dir_exists,
        cwd_exists=cwd_exists,
        adapter_script_exists=adapter_state.get("adapter_script_exists"),
        adapter_template_config_exists=adapter_state.get("adapter_template_config_exists"),
        adapter_configured=adapter_state.get("adapter_configured"),
    )
    return record


def external_workload_queue_summary(queue: List[Dict[str, Any]]) -> Dict[str, Any]:
    by_dataset: Dict[str, int] = {}
    by_benchmark: Dict[str, int] = {}
    by_allocator: Dict[str, int] = {}
    for item in queue:
        dataset = str(item.get("dataset") or "")
        benchmark = str(item.get("benchmark") or "")
        allocator = str(item.get("allocator") or "")
        by_dataset[dataset] = by_dataset.get(dataset, 0) + 1
        by_benchmark[benchmark] = by_benchmark.get(benchmark, 0) + 1
        by_allocator[allocator] = by_allocator.get(allocator, 0) + 1
    return {
        "workload_queue_count": len(queue),
        "workload_queue_ready_count": sum(1 for item in queue if item.get("ready_for_runner")),
        "workload_queue_template_count": sum(1 for item in queue if item.get("template_only")),
        "workload_queue_missing_rule_count": sum(1 for item in queue if not item.get("bundle_rule_id")),
        "workload_queue_missing_workload_dir_count": sum(1 for item in queue if item.get("workload_dir_exists") is False),
        "workload_queue_missing_cwd_count": sum(1 for item in queue if item.get("cwd_exists") is False),
        "workload_queue_adapter_script_count": sum(1 for item in queue if item.get("adapter_script_exists")),
        "workload_queue_adapter_template_config_count": sum(1 for item in queue if item.get("adapter_template_config_exists")),
        "workload_queue_adapter_configured_count": sum(1 for item in queue if item.get("adapter_configured")),
        "workload_queue_by_dataset": by_dataset,
        "workload_queue_by_benchmark": by_benchmark,
        "workload_queue_by_allocator": by_allocator,
    }


def write_paper_external_workload_queue_report(path: Path, audit: Dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    summary = audit.get("summary", {})
    lines = [
        "# Paper external workload queue",
        "",
        f"Generated: `{audit.get('generated_at')}`",
        f"Bundle: `{audit.get('bundle')}`",
        f"Ready for runner: `{summary.get('ready_for_runner')}`",
        "",
        "## Summary",
        "",
    ]
    for key in (
        "external_required_cell_count",
        "covered_cell_count",
        "template_only_cell_count",
        "invalid_cell_count",
        "workload_queue_count",
        "workload_queue_ready_count",
        "workload_queue_template_count",
        "workload_queue_missing_workload_dir_count",
        "workload_queue_adapter_script_count",
        "workload_queue_adapter_configured_count",
    ):
        lines.append(f"- `{key}`: `{summary.get(key)}`")
    lines.extend(
        [
            "",
            "## Queue",
            "",
            "| Dataset | Benchmark | Allocator | Rule | Ready | Workload dir exists | Adapter | First required action |",
            "|---|---|---|---|---:|---:|---:|---|",
        ]
    )
    for item in audit.get("workload_queue", []):
        actions = item.get("required_actions", [])
        first_action = str(actions[0]) if isinstance(actions, list) and actions else "-"
        lines.append(
            "| "
            f"`{item.get('dataset')}` | "
            f"`{item.get('benchmark')}` | "
            f"`{item.get('allocator')}` | "
            f"`{item.get('bundle_rule_id')}` | "
            f"`{item.get('ready_for_runner')}` | "
            f"`{item.get('workload_dir_exists')}` | "
            f"`{item.get('adapter_script_exists')}` | "
            f"{first_action} |"
        )
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")


def parse_last_json_object_from_text(text: str) -> Optional[Dict[str, Any]]:
    for raw in reversed(text.splitlines()):
        line = raw.strip()
        if not line:
            continue
        try:
            value = json.loads(line)
        except json.JSONDecodeError:
            continue
        if isinstance(value, dict):
            return value
    return None


def parse_json_objects_from_text(text: str) -> List[Dict[str, Any]]:
    records: List[Dict[str, Any]] = []
    decoder = json.JSONDecoder()
    for raw in text.splitlines():
        line = raw.strip()
        if not line:
            continue
        start = line.find("{")
        while start != -1:
            try:
                value, end = decoder.raw_decode(line[start:])
            except json.JSONDecodeError:
                start = line.find("{", start + 1)
                continue
            if isinstance(value, dict):
                records.append(value)
            start = line.find("{", start + max(end, 1))
    return records


def short_probe_text(text: str, limit: int = 2000) -> str:
    if len(text) <= limit:
        return text
    return text[-limit:]


def external_workload_runner_dry_run_probe(
    bundle_path: Path,
    cell: Dict[str, Any],
    *,
    timeout: int,
) -> Dict[str, Any]:
    command = [
        sys.executable,
        str(EVAL / "scripts" / "paper_external_workload.py"),
        "--bundle",
        str(bundle_path),
        "--dataset",
        str(cell.get("dataset") or ""),
        "--benchmark",
        str(cell.get("benchmark") or ""),
        "--allocator",
        str(cell.get("allocator") or ""),
        "--variant-feature",
        str(cell.get("variant_feature") or ""),
        "--category",
        str(cell.get("category") or ""),
        "--run-id",
        "external-bundle-audit-dry-run",
        "--run-index",
        "1",
        "--dry-run",
    ]
    try:
        proc = subprocess.run(
            command,
            cwd=str(ROOT),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=timeout,
        )
    except subprocess.TimeoutExpired as exc:
        return {
            "ok": False,
            "returncode": 124,
            "issue": f"external workload runner dry-run timed out after {timeout}s: {exc}",
            "command": command,
            "stdout": short_probe_text(exc.stdout or ""),
            "stderr": short_probe_text(exc.stderr or ""),
        }
    record = parse_last_json_object_from_text(proc.stdout)
    issue = None
    if proc.returncode != 0:
        issue = f"external workload runner dry-run exited {proc.returncode}"
    elif not isinstance(record, dict):
        issue = "external workload runner dry-run did not emit a JSON object"
    elif record.get("success") is not True or record.get("runnable") is not True:
        issue = "external workload runner dry-run did not report runnable=true"
    return {
        "ok": issue is None,
        "returncode": proc.returncode,
        "issue": issue,
        "command": command,
        "stdout": short_probe_text(proc.stdout),
        "stderr": short_probe_text(proc.stderr),
        "record": record,
    }


def command_targets_paper_workload_driver(command: List[str]) -> bool:
    return any(str(part).endswith("paper_workload_driver.py") for part in command)


def command_targets_paper_collections_docker_driver(command: List[str]) -> bool:
    return any(str(part).endswith("paper_collections_docker_driver.py") for part in command)


def command_targets_strict_external_adapter(command: List[str]) -> bool:
    return any(str(part).endswith("run_paper_workload.py") for part in command) or any(
        str(part).endswith("paper_external_workload_adapter.py") for part in command
    )


def command_with_flag(command: List[str], flag: str) -> List[str]:
    if flag in command:
        return list(command)
    return [*command, flag]


def local_collections_driver_dry_run_probe(
    command_for_record: List[str],
    workload: Dict[str, Any],
    audited: Dict[str, Any],
    *,
    timeout: int,
) -> Optional[Dict[str, Any]]:
    if not command_targets_paper_workload_driver(command_for_record):
        return None
    command = command_with_flag_before_remainder(command_for_record, "--dry-run")
    cwd = resolve_plan_cwd(workload.get("cwd"))
    env = os.environ.copy()
    env.setdefault("GLIBC_TUNABLES", "glibc.pthread.rseq=0")
    for key, value in (workload.get("env") or {}).items():
        env[str(key)] = str(value)
    try:
        proc = subprocess.run(
            command,
            cwd=str(cwd),
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=timeout,
        )
    except subprocess.TimeoutExpired as exc:
        return {
            "ok": False,
            "returncode": 124,
            "issue": f"local Collections driver dry-run timed out after {timeout}s: {exc}",
            "command": command,
            "cwd": str(cwd),
            "stdout": short_probe_text(exc.stdout or ""),
            "stderr": short_probe_text(exc.stderr or ""),
        }
    record = parse_last_json_object_from_text(proc.stdout) or parse_last_json_object_from_text(proc.stderr)
    issues: List[str] = []
    if proc.returncode != 0:
        record_error = record.get("error") if isinstance(record, dict) else None
        suffix = f": {record_error}" if record_error else ""
        issues.append(f"local Collections driver dry-run exited {proc.returncode}{suffix}")
    if not isinstance(record, dict):
        issues.append("local Collections driver dry-run did not emit a JSON object")
    else:
        if record.get("ok") is not True:
            issues.append("local Collections driver dry-run did not report ok=true")
        if record.get("source") != "paper-workload-driver":
            issues.append("local Collections driver dry-run JSON has unexpected source")
        if record.get("dry_run") is not True:
            issues.append("local Collections driver dry-run JSON did not report dry_run=true")
        for field in ("dataset", "benchmark", "allocator"):
            expected = str(audited.get(field) or "")
            if field not in record:
                if record.get("ok") is True:
                    issues.append(f"local Collections driver dry-run JSON is missing {field}")
                continue
            actual = str(record.get(field) or "")
            if actual != expected:
                issues.append(f"local Collections driver dry-run {field} mismatch: expected {expected}, got {actual}")
        if workload.get("claim_grade_scope") == "collections-subset" or record.get("claim_grade_scope") == "collections-subset":
            issues.append("local Collections driver dry-run resolved to a subset/smoke scope")
    issue = "; ".join(unique_strings(issues)) if issues else None
    return {
        "ok": issue is None,
        "returncode": proc.returncode,
        "issue": issue,
        "command": command,
        "cwd": str(cwd),
        "stdout": short_probe_text(proc.stdout),
        "stderr": short_probe_text(proc.stderr),
        "record": record,
    }


def strict_external_adapter_dry_run_probe(
    command_for_record: List[str],
    workload: Dict[str, Any],
    audited: Dict[str, Any],
    *,
    timeout: int,
) -> Optional[Dict[str, Any]]:
    if not command_targets_strict_external_adapter(command_for_record):
        return None
    try:
        command = render_paper_performance_command_parts(
            command_for_record,
            {
                "dataset": audited.get("dataset"),
                "benchmark": audited.get("benchmark"),
                "allocator": audited.get("allocator"),
                "variant_feature": workload.get("variant_feature"),
                "category": workload.get("category"),
            },
            extra_fields={"run_index": "1"},
        )
    except ValueError as exc:
        return {
            "ok": False,
            "issue": f"strict external adapter dry-run render failed: {exc}",
            "command": command_for_record,
        }
    command = command_with_flag([str(part) for part in command], "--dry-run")
    cwd = resolve_plan_cwd(workload.get("cwd"))
    env = os.environ.copy()
    env.setdefault("GLIBC_TUNABLES", "glibc.pthread.rseq=0")
    for key, value in (workload.get("env") or {}).items():
        env[str(key)] = str(value)
    try:
        proc = subprocess.run(
            command,
            cwd=str(cwd),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=timeout,
            env=env,
        )
    except subprocess.TimeoutExpired as exc:
        return {
            "ok": False,
            "returncode": 124,
            "issue": f"strict external adapter dry-run timed out after {timeout}s: {exc}",
            "command": command,
            "stdout": short_probe_text(exc.stdout or ""),
            "stderr": short_probe_text(exc.stderr or ""),
        }
    record = parse_last_json_object_from_text(proc.stdout)
    issue = None
    if proc.returncode != 0:
        issue = f"strict external adapter dry-run exited {proc.returncode}"
    elif not isinstance(record, dict):
        issue = "strict external adapter dry-run did not emit a JSON object"
    elif record.get("success") is not True or record.get("runnable") is not True:
        issue = "strict external adapter dry-run did not report runnable=true"
    elif not isinstance(record.get("checkout_pin_validation"), dict) or record.get("checkout_pin_validation", {}).get("validated") is not True:
        issue = "strict external adapter dry-run did not validate the promoted exact checkout pin"
    return {
        "ok": issue is None,
        "returncode": proc.returncode,
        "issue": issue,
        "command": command,
        "stdout": short_probe_text(proc.stdout),
        "stderr": short_probe_text(proc.stderr),
        "record": record,
    }


