def crates_io_head_source(
    *,
    paper_benchmark: str,
    paper_project: str,
    crate_name: str,
    upstream_url: str,
    matchers: List[str],
    note: Optional[str] = None,
) -> Dict[str, Any]:
    reason = (
        "rust-alloc-paper data/web-perf.dat names this web benchmark but does not specify a "
        "version/tag; repository is seeded from crates.io crate metadata and therefore remains "
        "HEAD-only until exact paper provenance is found"
    )
    if note:
        reason = f"{reason}; {note}"
    return {
        "paper_benchmark": paper_benchmark,
        "paper_project": paper_project,
        "paper_version": None,
        "crate_name": crate_name,
        "source_basis": "crates.io repository metadata plus rust-alloc-paper data/web-perf.dat row name",
        "source_confidence": "candidate_head_only",
        "upstream_url": upstream_url,
        "source_evidence": [f"https://crates.io/api/v1/crates/{crate_name}"],
        "matchers": matchers,
        "ref_candidates": [
            {"ref": "HEAD", "kind": "head", "reason": reason},
        ],
    }


