def paper_external_source_metadata(rule: Dict[str, Any]) -> Dict[str, Any]:
    rule_id = str(rule.get("id") or rule.get("name") or "")
    source = copy.deepcopy(PAPER_EXTERNAL_WORKLOAD_SOURCES.get(rule_id, {}))
    embedded = rule.get("paper_source")
    if isinstance(embedded, dict):
        source.update(copy.deepcopy(embedded))
    return source


def normalized_external_source_ref_candidates(source: Dict[str, Any]) -> List[Dict[str, Any]]:
    out: List[Dict[str, Any]] = []
    for candidate in source.get("ref_candidates", []) or []:
        if not isinstance(candidate, dict):
            continue
        ref = str(candidate.get("ref") or "").strip()
        if not ref:
            continue
        out.append({**candidate, "ref": ref})
    return out


def external_source_ref_kind(candidate: Dict[str, Any]) -> str:
    return str(candidate.get("kind") or "exact").strip().lower()


def external_source_ref_is_head_like(candidate: Dict[str, Any]) -> bool:
    ref = str(candidate.get("ref") or "").strip().lower()
    kind = external_source_ref_kind(candidate)
    return bool(kind == "head" or ref in HEAD_LIKE_REFS)


def external_source_ref_tag_name(ref: str) -> str:
    text = str(ref or "").strip()
    if text.startswith("refs/tags/"):
        return text[len("refs/tags/") :]
    return text


def external_source_ref_equivalence_keys(ref: str) -> Set[str]:
    text = str(ref or "").strip()
    if not text:
        return set()
    tag = external_source_ref_tag_name(text)
    return {text, tag, f"refs/tags/{tag}"}


def ordered_external_source_ref_candidates(
    source: Dict[str, Any],
    *,
    allow_fallback: bool = False,
) -> List[Dict[str, Any]]:
    """Return ref candidates in the resolution order for checkout fetching.

    Without ``--allow-fallback`` the historic order is preserved.  When the user
    explicitly allows fallback/newer source revisions, exact candidates still
    come first, but reproducible non-exact refs are tried before moving-target
    HEAD/main/master candidates.  This keeps newer benchmark versions
    reproducible while preserving fail-closed paper-exact semantics elsewhere.
    """

    candidates = normalized_external_source_ref_candidates(source)
    if not allow_fallback:
        return candidates

    def rank(item: Tuple[int, Dict[str, Any]]) -> Tuple[int, int]:
        index, candidate = item
        kind = external_source_ref_kind(candidate)
        if kind == "exact":
            return (0, index)
        if kind in NON_EXACT_REPRODUCIBLE_REF_KINDS:
            return (1, index)
        if external_source_ref_is_head_like(candidate):
            return (2, index)
        return (3, index)

    return [candidate for _, candidate in sorted(enumerate(candidates), key=rank)]


def normalized_external_source_matchers(source: Dict[str, Any]) -> List[str]:
    matchers = source.get("matchers", []) or []
    if not isinstance(matchers, list):
        return []
    return [str(item).strip() for item in matchers if str(item).strip()]


