def adapter_template_literal(value: Any) -> str:
    """Serialize a JSON value for a command_template string that later uses str.format."""

    text = json.dumps(value, sort_keys=True, separators=(",", ":"))
    return text.replace("{", "{{").replace("}", "}}")


def replace_command_option(command: List[str], option: str, value: str) -> None:
    if option in command:
        idx = command.index(option)
        if idx + 1 < len(command):
            command[idx + 1] = value
            return
    command.extend([option, value])


def remove_command_option_with_value(command: List[str], option: str) -> None:
    while option in command:
        idx = command.index(option)
        del command[idx : min(idx + 2, len(command))]


def replace_command_option_before_remainder(command: List[str], option: str, value: str) -> List[str]:
    """Set a wrapper option before the first ``--`` separator.

    RRedis commands are shaped as ``runner wrapper-options -- cargo run ...``.
    Appending a wrapper option at the end would hand it to the upstream server
    command instead, so claim-grade contract arguments must be inserted before
    the remainder separator.
    """

    out = [str(part) for part in command]
    try:
        separator_index = out.index("--")
    except ValueError:
        separator_index = len(out)
    prefix = out[:separator_index]
    suffix = out[separator_index:]
    while option in prefix:
        idx = prefix.index(option)
        del prefix[idx : min(idx + 2, len(prefix))]
    prefix.extend([option, value])
    return [*prefix, *suffix]


def first_plan_workload(plan: Dict[str, Any], benchmark: str) -> Optional[Dict[str, Any]]:
    workloads = plan.get("workloads") if isinstance(plan.get("workloads"), list) else []
    for workload in workloads:
        if isinstance(workload, dict) and str(workload.get("benchmark") or "") == benchmark:
            return workload
    return None


def claim_grade_command_template_from_plan_workload(
    workload: Dict[str, Any],
    *,
    contract: str,
) -> List[str]:
    workload_command = workload.get("command") if isinstance(workload.get("command"), list) else []
    command = [str(part) for part in workload_command]
    remove_command_option_with_value(command, "--bench-name-filter")
    replace_command_option(command, "--dataset", "{dataset}")
    replace_command_option(command, "--benchmark", "{benchmark}")
    replace_command_option(command, "--allocator", "{allocator}")
    replace_command_option(command, "--variant-feature", "{variant_feature}")
    replace_command_option(command, "--run-index", "{run_index}")
    replace_command_option(command, "--real-workload-dir", "{real_workload_dir}")
    replace_command_option(command, "--claim-grade-contract", contract)
    expected_targets = [str(item) for item in workload.get("expected_cargo_bench_targets", []) if str(item).strip()]
    if expected_targets:
        joined_targets = ",".join(expected_targets)
        replace_command_option(command, "--cargo-bench-targets", joined_targets)
        replace_command_option(command, "--expected-cargo-bench-targets", joined_targets)
    expected_leafs = [str(item) for item in workload.get("expected_libtest_bench_functions", []) if str(item).strip()]
    if expected_leafs:
        replace_command_option(command, "--expected-libtest-bench-functions", ",".join(expected_leafs))
    source_contract = workload.get("source_contract")
    if isinstance(source_contract, dict) and source_contract:
        replace_command_option(command, "--paper-source-contract-json", adapter_template_literal(source_contract))
    paper_source = workload.get("paper_source")
    if isinstance(paper_source, dict) and paper_source:
        replace_command_option(command, "--paper-source-json", adapter_template_literal(paper_source))
    return command


def sync_rredis_claim_grade_config_record(rule_id: str, spec: Dict[str, Any], *, write: bool) -> Dict[str, Any]:
    """Promote RRedis' redis-benchmark bridge as accepted-current evidence.

    The paper does not publish an exact redis-benchmark command for Rsedis, so
    this path deliberately does **not** mark the runner paper-exact.  It only
    enables a real, pinned, redis-benchmark-backed current-source runner after
    the RRedis plan audit proves source pinning, allocator routing, tool
    availability, selector coverage, and at least one bounded prepare probe.
    """

    config_path = Path(spec["config"])
    plan_path = Path(spec["plan"])
    plan_audit_path = Path(spec["plan_audit"])
    contract = str(spec.get("contract") or "rredis-redis-benchmark-current-run")
    record: Dict[str, Any] = {
        "rule_id": rule_id,
        "label": spec.get("label"),
        "config_path": str(config_path),
        "plan": str(plan_path),
        "plan_audit": str(plan_audit_path),
        "write_requested": write,
        "action": "skipped",
        "not_timing_evidence": True,
    }
    config = read_json_if_exists(config_path)
    plan = read_json_if_exists(plan_path)
    plan_audit = read_json_if_exists(plan_audit_path)
    blockers: List[str] = []
    if not isinstance(config, dict):
        blockers.append("active RRedis config missing or invalid")
    if not isinstance(plan, dict):
        blockers.append("RRedis paper plan missing or invalid")
    if not isinstance(plan_audit, dict):
        blockers.append("RRedis paper plan audit missing or invalid")
    audit_summary = plan_audit.get("summary", {}) if isinstance(plan_audit, dict) else {}
    ready_key = str(spec.get("requires_audit_key") or "ready_for_accepted_current_execution")
    if audit_summary.get(ready_key) is not True:
        blockers.append(f"RRedis plan audit does not satisfy {ready_key}=true")
    for key, label in (
        ("source_claim_grade_complete", "accepted pinned source contract"),
        ("redis_benchmark_available", "redis-benchmark availability"),
        ("allocator_routing_verified", "allocator routing audit"),
        ("redis_benchmark_json_contract_ready", "redis-benchmark JSON timing contract"),
    ):
        if audit_summary.get(key) is not True:
            blockers.append(f"RRedis plan audit lacks {label}")
    if audit_summary.get("prepare_probe_enabled") is not True:
        blockers.append("RRedis plan audit did not run a prepare probe")
    if int(audit_summary.get("prepare_probe_count") or 0) <= 0:
        blockers.append("RRedis plan audit has no successful prepare probe coverage")
    if int(audit_summary.get("prepare_probe_failure_count") or 0) != 0:
        blockers.append("RRedis plan audit has prepare probe failures")
    workload = first_plan_workload(plan, str(spec.get("benchmark") or "RRedis*")) if isinstance(plan, dict) else None
    if not isinstance(workload, dict):
        blockers.append("RRedis plan has no representative workload")
    source_contract = plan.get("source_contract") if isinstance(plan, dict) and isinstance(plan.get("source_contract"), dict) else {}
    if source_contract.get("accepted_newer_checkout_pin_complete") is not True:
        blockers.append("RRedis source contract is not an explicitly accepted pinned fallback/newer checkout")
    if blockers:
        record["blockers"] = unique_strings(blockers)
        return record

    assert isinstance(config, dict)
    assert isinstance(workload, dict)
    command_template = [str(part) for part in config.get("command_template", []) if str(part)]
    if not command_template:
        blockers.append("active RRedis config has no command_template")
        record["blockers"] = unique_strings(blockers)
        return record
    command_template = replace_command_option_before_remainder(command_template, "--claim-grade-contract", contract)
    command_template = replace_command_option_before_remainder(
        command_template,
        "--paper-source-contract-json",
        adapter_template_literal(source_contract),
    )

    updated = copy.deepcopy(config)
    updated["source"] = "paper-external-workload-rredis-current-claim-grade-config"
    updated["configured"] = True
    updated["claim_grade"] = True
    updated["command_template"] = command_template
    updated.pop("not_claim_grade_reason", None)
    wrapper = updated.get("redis_benchmark_json_wrapper") if isinstance(updated.get("redis_benchmark_json_wrapper"), dict) else {}
    wrapper = copy.deepcopy(wrapper)
    wrapper.pop("not_claim_grade_reason", None)
    wrapper["claim_grade_contract"] = contract
    wrapper["paper_exact"] = False
    wrapper["accepted_current_source"] = True
    wrapper["plan_audit"] = str(plan_audit_path)
    updated["redis_benchmark_json_wrapper"] = wrapper
    updated["accept_newer_benchmark_source"] = True
    updated["accepted_newer_benchmark_source"] = {
        "accepted": True,
        "source": "sync-specialized-external-claim-grade-configs",
        "reason": (
            "RRedis paper source lacks an exact version/ref, so this runner uses the "
            "explicitly pinned current fallback checkout as non-paper-exact evidence."
        ),
        "paper_exact": False,
    }
    updated["claim_grade_activation"] = {
        "source": "sync-rredis-current-claim-grade-config",
        "activated_at": now_iso(),
        "rule_id": rule_id,
        "audit_contract": (
            "runner_ready + redis_benchmark_json + accepted_pinned_current_checkout + "
            "allocator_routing_verified + bounded_prepare_probe"
        ),
        "checkout_commit": source_contract.get("checkout_pin", {}).get("commit"),
        "resolved_ref": source_contract.get("checkout_pin", {}).get("resolved_ref"),
        "requested_ref": source_contract.get("checkout_pin", {}).get("requested_ref"),
        "source_provenance_class": source_contract.get("source_provenance_class"),
        "paper_exact": False,
        "accepted_newer_benchmark_source": True,
        "accepted_newer_policy": source_contract.get("accepted_newer_policy"),
        "scope": (
            "RRedis may emit claim-grade current-source timing only after the real "
            "redis-benchmark child produces finite benchmark-owned JSON.  This is "
            "not paper-exact RRedis methodology because the paper does not publish "
            "an exact redis-benchmark command and this host may differ from the paper host."
        ),
    }
    updated["plan_claim_grade_metadata"] = {
        "source": "sync-specialized-external-claim-grade-configs",
        "plan": str(plan_path),
        "plan_audit": str(plan_audit_path),
        "contract": contract,
        "ready_key": ready_key,
        "ready_for_accepted_current_execution": True,
        "paper_exact": False,
        "not_timing_evidence": True,
    }
    changed = updated != config
    record.update(
        {
            "action": "updated" if (write and changed) else ("would_update" if changed else "preserved"),
            "contract": contract,
            "ready_key": ready_key,
            "source_provenance_class": source_contract.get("source_provenance_class"),
            "checkout_commit": source_contract.get("checkout_pin", {}).get("commit"),
            "paper_exact": False,
            "blockers": [],
        }
    )
    if write and changed:
        write_json(config_path, updated)
    return record


def sync_rpython_claim_grade_config_record(rule_id: str, spec: Dict[str, Any], *, write: bool) -> Dict[str, Any]:
    """Promote RPython only as paper-exact or explicitly accepted current evidence.

    RPython has two safe execution-readiness states:

    * paper-exact: the RustPython checkout is pinned to the exact paper source
      contract and the plan audit proves the full bench surface; and
    * accepted-current: the user explicitly accepted a pinned newer RustPython
      checkout, which is useful current evidence but must stay labelled
      non-paper-exact.

    A merely reproducible fallback checkout is intentionally not enough to set
    ``claim_grade=true`` because downstream import code would otherwise treat
    diagnostic timing as paper-equivalent evidence.
    """

    config_path = Path(spec["config"])
    plan_path = Path(spec["plan"])
    plan_audit_path = Path(spec["plan_audit"])
    contract = str(spec.get("contract") or "rpython-paper-run")
    record: Dict[str, Any] = {
        "rule_id": rule_id,
        "label": spec.get("label"),
        "config_path": str(config_path),
        "plan": str(plan_path),
        "plan_audit": str(plan_audit_path),
        "write_requested": write,
        "action": "skipped",
        "not_timing_evidence": True,
    }
    config = read_json_if_exists(config_path)
    plan = read_json_if_exists(plan_path)
    plan_audit = read_json_if_exists(plan_audit_path)
    blockers: List[str] = []
    if not isinstance(config, dict):
        blockers.append("active RPython config missing or invalid")
    if not isinstance(plan, dict):
        blockers.append("RPython paper plan missing or invalid")
    if not isinstance(plan_audit, dict):
        blockers.append("RPython paper plan audit missing or invalid")

    audit_summary = plan_audit.get("summary", {}) if isinstance(plan_audit, dict) else {}
    if not isinstance(audit_summary, dict):
        audit_summary = {}
    workload = first_plan_workload(plan, str(spec.get("benchmark") or "RPython")) if isinstance(plan, dict) else None
    if not isinstance(workload, dict):
        blockers.append("RPython plan has no representative workload")
    source_contract = plan.get("source_contract") if isinstance(plan, dict) and isinstance(plan.get("source_contract"), dict) else {}
    source_provenance_class = str(
        source_contract.get("source_provenance_class") or source_provenance_class_from_contract(source_contract)
    )
    source_claim_grade_complete = source_contract.get("claim_grade_complete") is True
    source_exact_checkout_pin_complete = source_contract.get("exact_checkout_pin_complete") is True
    accepted_current_source = bool(
        source_contract.get("accepted_newer_checkout_pin_complete") is True
        or source_provenance_class == USER_ACCEPTED_NEWER_SOURCE_PROVENANCE_CLASS
    )
    source_contract_blockers = source_contract_claim_grade_blockers(
        {"source_contract": source_contract, "source_provenance_class": source_provenance_class}
    )
    paper_exact_audit_ready = bool(
        audit_summary.get("ready_for_paper_exact_execution") is True
        or audit_summary.get("ready_for_paper_equivalent_execution") is True
        or audit_summary.get("ready_for_claim_grade_execution") is True
    )
    accepted_current_audit_ready = bool(
        audit_summary.get("ready_for_accepted_current_execution") is True
        or audit_summary.get("ready_for_current_non_paper_exact_execution") is True
    )
    fallback_only_ready = (
        audit_summary.get("ready_for_reproducible_fallback_execution") is True
        and not paper_exact_audit_ready
        and not accepted_current_audit_ready
    )
    if fallback_only_ready:
        blockers.append(
            "RPython plan is only fallback-ready; refusing claim_grade config sync without "
            "paper-exact or accepted-current source provenance"
        )
    if source_contract_blockers:
        blockers.extend(source_contract_blockers)
    paper_exact = (
        paper_exact_audit_ready
        and source_claim_grade_complete
        and source_exact_checkout_pin_complete
        and not source_contract_blockers
    )
    accepted_current = (
        not paper_exact
        and accepted_current_audit_ready
        and source_claim_grade_complete
        and accepted_current_source
        and not source_contract_blockers
    )
    if not paper_exact and not accepted_current and not fallback_only_ready:
        blockers.append(
            "RPython plan audit is not ready for paper-exact execution or accepted-current non-paper-exact execution"
        )
    if accepted_current_audit_ready and not accepted_current_source:
        blockers.append("RPython audit claims accepted-current readiness but source contract is not accepted-current")
    if paper_exact_audit_ready and not source_exact_checkout_pin_complete:
        blockers.append("RPython audit claims paper-exact readiness but source contract lacks exact checkout pin")
    if not source_claim_grade_complete:
        blockers.append("RPython source contract is not claim-grade complete")
    if blockers:
        record["blockers"] = unique_strings(blockers)
        record.update(
            {
                "source_provenance_class": source_provenance_class,
                "paper_exact": False,
                "accepted_current_source": False,
            }
        )
        return record

    assert isinstance(config, dict)
    assert isinstance(workload, dict)
    expected_targets = [str(item) for item in workload.get("expected_cargo_bench_targets", []) if str(item).strip()]
    expected_leafs = [str(item) for item in workload.get("expected_libtest_bench_functions", []) if str(item).strip()]
    command_template = claim_grade_command_template_from_plan_workload(workload, contract=contract)
    checkout_pin = source_contract.get("checkout_pin") if isinstance(source_contract.get("checkout_pin"), dict) else {}
    claim_grade_scope = "rpython-paper-exact-matrix" if paper_exact else "rpython-current-non-paper-exact-matrix"
    ready_key = "ready_for_paper_exact_execution" if paper_exact else "ready_for_accepted_current_execution"

    updated = copy.deepcopy(config)
    updated["source"] = (
        "paper-external-workload-rpython-paper-exact-claim-grade-config"
        if paper_exact
        else "paper-external-workload-rpython-current-claim-grade-config"
    )
    updated["configured"] = True
    updated["claim_grade"] = True
    updated["command_template"] = command_template
    updated.pop("not_claim_grade_reason", None)
    wrapper = updated.get("cargo_bench_json_wrapper") if isinstance(updated.get("cargo_bench_json_wrapper"), dict) else {}
    wrapper = copy.deepcopy(wrapper)
    wrapper.pop("not_claim_grade_reason", None)
    wrapper.pop("bench_name_filter", None)
    workload_command = workload.get("command") if isinstance(workload.get("command"), list) else []
    if "--" in workload_command:
        wrapper["child_command_template"] = workload_command[workload_command.index("--") + 1 :]
    wrapper["claim_grade_contract"] = contract
    wrapper["cargo_bench_targets"] = expected_targets
    wrapper["expected_cargo_bench_targets"] = expected_targets
    wrapper["expected_libtest_bench_functions"] = expected_leafs
    wrapper["not_timing_evidence"] = True
    wrapper["paper_exact"] = bool(paper_exact)
    wrapper["accepted_current_source"] = bool(accepted_current)
    wrapper["source_provenance_class"] = source_provenance_class
    wrapper["plan_audit"] = str(plan_audit_path)
    updated["cargo_bench_json_wrapper"] = wrapper
    if accepted_current:
        updated["accept_newer_benchmark_source"] = True
        updated["accepted_newer_benchmark_source"] = {
            "accepted": True,
            "source": "sync-specialized-external-claim-grade-configs",
            "reason": (
                "RPython uses an explicitly accepted pinned newer RustPython checkout. "
                "This is current-source evidence and is not paper-exact methodology."
            ),
            "paper_exact": False,
        }
    else:
        updated.pop("accept_newer_benchmark_source", None)
        updated.pop("accepted_newer_benchmark_source", None)

    updated["claim_grade_activation"] = {
        "source": (
            "sync-rpython-paper-exact-claim-grade-config"
            if paper_exact
            else "sync-rpython-current-claim-grade-config"
        ),
        "activated_at": now_iso(),
        "rule_id": rule_id,
        "audit_contract": (
            "runner_ready + full_rpython_bench_surface + source_claim_grade_contract + "
            + ("exact_paper_checkout" if paper_exact else "accepted_pinned_current_checkout")
        ),
        "checkout_commit": checkout_pin.get("commit"),
        "resolved_ref": checkout_pin.get("resolved_ref"),
        "requested_ref": checkout_pin.get("requested_ref"),
        "source_provenance_class": source_provenance_class,
        "paper_exact": bool(paper_exact),
        "accepted_newer_benchmark_source": bool(accepted_current),
        "accepted_newer_policy": source_contract.get("accepted_newer_policy"),
        "claim_grade_scope": claim_grade_scope,
        "scope": (
            "RPython may emit paper-exact claim-grade timing only after repeated raw timing "
            "samples are collected/imported from this exact-source runner."
            if paper_exact
            else "RPython may emit accepted-current timing only after repeated raw timing samples "
            "are collected/imported from this pinned newer-source runner; those samples must remain "
            "labelled non-paper-exact."
        ),
    }
    updated["plan_claim_grade_metadata"] = {
        "source": "sync-specialized-external-claim-grade-configs",
        "plan": str(plan_path),
        "plan_audit": str(plan_audit_path),
        "contract": contract,
        "expected_cargo_bench_targets": expected_targets,
        "expected_libtest_bench_function_count": len(expected_leafs),
        "ready_key": ready_key,
        "ready_for_paper_exact_execution": bool(paper_exact),
        "ready_for_accepted_current_execution": bool(accepted_current),
        "paper_exact": bool(paper_exact),
        "accepted_current_source": bool(accepted_current),
        "accepted_newer_benchmark_source": bool(accepted_current),
        "source_provenance_class": source_provenance_class,
        "claim_grade_scope": claim_grade_scope,
        "not_timing_evidence": True,
    }
    changed = updated != config
    record.update(
        {
            "action": "updated" if (write and changed) else ("would_update" if changed else "preserved"),
            "expected_cargo_bench_targets": expected_targets,
            "expected_libtest_bench_function_count": len(expected_leafs),
            "contract": contract,
            "ready_key": ready_key,
            "source_provenance_class": source_provenance_class,
            "checkout_commit": checkout_pin.get("commit"),
            "paper_exact": bool(paper_exact),
            "accepted_current_source": bool(accepted_current),
            "claim_grade_scope": claim_grade_scope,
            "blockers": [],
        }
    )
    if write and changed:
        write_json(config_path, updated)
    return record


def sync_specialized_claim_grade_config_record(rule_id: str, spec: Dict[str, Any], *, write: bool) -> Dict[str, Any]:
    if spec.get("sync_kind") == "rredis_redis_benchmark_json":
        return sync_rredis_claim_grade_config_record(rule_id, spec, write=write)
    if spec.get("sync_kind") == "rpython_current_or_exact_claim_grade_config":
        return sync_rpython_claim_grade_config_record(rule_id, spec, write=write)
    config_path = Path(spec["config"])
    plan_path = Path(spec["plan"])
    plan_audit_path = Path(spec["plan_audit"])
    record: Dict[str, Any] = {
        "rule_id": rule_id,
        "label": spec.get("label"),
        "config_path": str(config_path),
        "plan": str(plan_path),
        "plan_audit": str(plan_audit_path),
        "write_requested": write,
        "action": "skipped",
        "not_timing_evidence": True,
    }
    config = read_json_if_exists(config_path)
    plan = read_json_if_exists(plan_path)
    plan_audit = read_json_if_exists(plan_audit_path)
    blockers: List[str] = []
    if not isinstance(config, dict):
        blockers.append("active config missing or invalid")
    if not isinstance(plan, dict):
        blockers.append("specialized paper plan missing or invalid")
    audit_summary = plan_audit.get("summary", {}) if isinstance(plan_audit, dict) else {}
    ready_key = str(spec.get("requires_audit_key") or "")
    if ready_key and audit_summary.get(ready_key) is not True:
        blockers.append(f"specialized plan audit does not satisfy {ready_key}=true")
    extra_ready_key = str(spec.get("extra_ready_key") or "")
    if extra_ready_key and audit_summary.get(extra_ready_key) is not True:
        blockers.append(f"specialized plan audit does not satisfy {extra_ready_key}=true")
    workload = first_plan_workload(plan, str(spec.get("benchmark") or "")) if isinstance(plan, dict) else None
    if not isinstance(workload, dict):
        blockers.append("specialized plan has no representative workload for this benchmark")
    if blockers:
        record["blockers"] = unique_strings(blockers)
        return record
    assert isinstance(config, dict)
    assert isinstance(workload, dict)
    expected_targets = [str(item) for item in workload.get("expected_cargo_bench_targets", []) if str(item).strip()]
    expected_leafs = [str(item) for item in workload.get("expected_libtest_bench_functions", []) if str(item).strip()]
    command_template = claim_grade_command_template_from_plan_workload(workload, contract=str(spec.get("contract") or ""))
    updated = copy.deepcopy(config)
    updated["source"] = "paper-external-workload-specialized-claim-grade-config"
    updated["configured"] = True
    updated["claim_grade"] = True
    updated.pop("not_claim_grade_reason", None)
    wrapper = updated.get("cargo_bench_json_wrapper") if isinstance(updated.get("cargo_bench_json_wrapper"), dict) else {}
    wrapper = copy.deepcopy(wrapper)
    wrapper.pop("not_claim_grade_reason", None)
    wrapper.pop("bench_name_filter", None)
    workload_command = workload.get("command") if isinstance(workload.get("command"), list) else []
    if "--" in workload_command:
        wrapper["child_command_template"] = workload_command[workload_command.index("--") + 1 :]
    wrapper["claim_grade_contract"] = spec.get("contract")
    wrapper["cargo_bench_targets"] = expected_targets
    wrapper["expected_cargo_bench_targets"] = expected_targets
    wrapper["expected_libtest_bench_functions"] = expected_leafs
    wrapper["not_timing_evidence"] = True
    updated["cargo_bench_json_wrapper"] = wrapper
    updated["command_template"] = command_template
    updated["plan_claim_grade_metadata"] = {
        "source": "sync-specialized-external-claim-grade-configs",
        "plan": str(plan_path),
        "plan_audit": str(plan_audit_path),
        "contract": spec.get("contract"),
        "expected_cargo_bench_targets": expected_targets,
        "expected_libtest_bench_function_count": len(expected_leafs),
        "ready_key": ready_key,
        "not_timing_evidence": True,
    }
    changed = updated != config
    record.update(
        {
            "action": "updated" if (write and changed) else ("would_update" if changed else "preserved"),
            "expected_cargo_bench_targets": expected_targets,
            "expected_libtest_bench_function_count": len(expected_leafs),
            "contract": spec.get("contract"),
            "ready_key": ready_key,
            "blockers": [],
        }
    )
    if write and changed:
        write_json(config_path, updated)
    return record


def sync_specialized_external_claim_grade_configs(args: argparse.Namespace) -> int:
    selected = {str(item).strip() for item in (args.family or []) if str(item).strip()}
    write = bool(args.write)
    records: List[Dict[str, Any]] = []
    for rule_id, spec in SPECIALIZED_CLAIM_GRADE_CONFIG_SYNC.items():
        if selected and rule_id not in selected and str(spec.get("label") or "") not in selected:
            continue
        records.append(sync_specialized_claim_grade_config_record(rule_id, spec, write=write))
    summary = {
        "family_count": len(records),
        "write_requested": write,
        "updated_count": sum(1 for record in records if record.get("action") == "updated"),
        "would_update_count": sum(1 for record in records if record.get("action") == "would_update"),
        "preserved_count": sum(1 for record in records if record.get("action") == "preserved"),
        "blocked_count": sum(1 for record in records if record.get("blockers")),
        "ready_for_claim_grade_import": False,
    }
    artifact = {
        "schema_version": 1,
        "generated_at": now_iso(),
        "source": "specialized-external-claim-grade-config-sync",
        "summary": summary,
        "configs": records,
        "notes": [
            "This command updates active adapter configs from already audited specialized paper plans; it does not run benchmarks.",
            "A synced config is claim-grade executable only when the wrapper command still passes runtime source/evidence contracts and downstream matrix audits observe the required repeated raw samples.",
            "R-Polars remains blocked until canonical input provenance is claim-grade ready.",
        ],
    }
    run_id = args.run_id or _dt.datetime.now().strftime("specialized-external-claim-grade-config-sync-%Y%m%d-%H%M%S")
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)
    artifact_path = out_dir / "specialized-external-claim-grade-config-sync.json"
    write_json(artifact_path, artifact)
    if not args.no_update_results:
        write_json(RESULTS / "specialized_external_claim_grade_config_sync.json", artifact)
    print(json.dumps({"artifact": str(artifact_path), **summary}, indent=2, sort_keys=True))
    return 1 if summary["blocked_count"] and not args.allow_blocked else 0


def run_adapter_validation_case(name: str, command: List[str], *, timeout_seconds: int = 30) -> Dict[str, Any]:
    started = time.monotonic()
    try:
        proc = subprocess.run(
            command,
            cwd=str(ROOT),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=timeout_seconds,
        )
        elapsed = time.monotonic() - started
        return {
            "name": name,
            "command": command,
            "returncode": proc.returncode,
            "elapsed_seconds": elapsed,
            "stdout": proc.stdout,
            "stderr": proc.stderr,
            "last_json": parse_last_json_object_from_text(proc.stdout),
            "outer_timeout_seconds": timeout_seconds,
            "outer_timed_out": False,
        }
    except subprocess.TimeoutExpired as exc:
        elapsed = time.monotonic() - started
        stdout = exc.stdout if isinstance(exc.stdout, str) else (exc.stdout or b"").decode("utf-8", errors="replace")
        stderr = exc.stderr if isinstance(exc.stderr, str) else (exc.stderr or b"").decode("utf-8", errors="replace")
        return {
            "name": name,
            "command": command,
            "returncode": 124,
            "elapsed_seconds": elapsed,
            "stdout": stdout,
            "stderr": stderr,
            "last_json": parse_last_json_object_from_text(stdout),
            "outer_timeout_seconds": timeout_seconds,
            "outer_timed_out": True,
        }


def write_adapter_validation_config(config_dir: Path, config: Dict[str, Any]) -> None:
    config_dir.mkdir(parents=True, exist_ok=True)
    write_json(config_dir / "workload_config.json", config)


def build_adapter_validation_summary(results: Dict[str, Dict[str, Any]]) -> Dict[str, bool]:
    def last_json(key: str) -> Dict[str, Any]:
        result = results.get(key, {})
        return result.get("last_json") if isinstance(result.get("last_json"), dict) else {}

    def blockers(key: str) -> List[str]:
        raw = last_json(key).get("claim_grade_blockers")
        if isinstance(raw, list):
            return [str(item) for item in raw]
        if raw:
            return [str(raw)]
        return []

    def has_blocker(key: str, needle: str) -> bool:
        return needle in " | ".join(blockers(key))

    def ok_success(key: str) -> bool:
        result = results.get(key, {})
        last = last_json(key)
        return (
            result.get("returncode") == 0
            and last.get("success") is True
            and last.get("selector_contract", {}).get("complete") is True
            and last.get("timing_contract", {}).get("benchmark_owned_json") is True
        )

    def refused_with(key: str, needle: str) -> bool:
        result = results.get(key, {})
        last = last_json(key)
        return result.get("returncode") != 0 and last.get("success") is False and needle in str(last.get("error") or "")

    def toolchain_status(key: str) -> Dict[str, Any]:
        value = last_json(key).get("external_rustup_toolchain")
        return value if isinstance(value, dict) else {}

    unpinned_toolchain = toolchain_status("unpinned_cargo_toolchain_dry_run")
    pinned_toolchain = toolchain_status("pinned_cargo_toolchain_dry_run")
    child_blocked = last_json("child_blockers_real_run")
    child_blocked_semantics = (
        child_blocked.get("allocator_semantics")
        if isinstance(child_blocked.get("allocator_semantics"), dict)
        else {}
    )
    timeout_result = results.get("timeout_real_run", {})
    timeout_record = last_json("timeout_real_run")
    bounded_output_record = last_json("bounded_output_real_run")
    return {
        "valid_dry_run_ok": ok_success("valid_dry_run"),
        "valid_real_run_ok": ok_success("valid_real_run"),
        "valid_real_run_claim_grade_true": last_json("valid_real_run").get("claim_grade") is True,
        "valid_dry_run_reports_non_timing_blocker": has_blocker(
            "valid_dry_run",
            "adapter dry-run validates shape only and is not timing evidence",
        ),
        "valid_real_run_has_host_and_no_blockers": bool(last_json("valid_real_run").get("host"))
        and not blockers("valid_real_run"),
        "timeout_real_run_refused_and_killed": (
            timeout_result.get("returncode") == 124
            and timeout_result.get("outer_timed_out") is False
            and timeout_record.get("success") is False
            and timeout_record.get("timed_out") is True
            and timeout_record.get("child_returncode") == 124
            and has_blocker("timeout_real_run", "workload command timed out after 1s")
            and float(timeout_result.get("elapsed_seconds") or 999.0) < 10.0
        ),
        "bounded_output_tail_json_blocks_claim_grade": (
            results.get("bounded_output_real_run", {}).get("returncode") == 0
            and bounded_output_record.get("success") is True
            and bounded_output_record.get("claim_grade") is False
            and bounded_output_record.get("child_stdout_truncated") is True
            and bounded_output_record.get("child_stdout_bytes", 0) > bounded_output_record.get("child_stdout_retained_bytes", 0)
            and has_blocker("bounded_output_real_run", "child stdout exceeded max-output-bytes=1024")
        ),
        "child_blockers_real_run_ok": (
            ok_success("child_blockers_real_run")
            and child_blocked.get("claim_grade") is False
            and has_blocker("child_blockers_real_run", "synthetic child bridge blocker")
            and has_blocker("child_blockers_real_run", "synthetic allocator semantic blocker")
            and "synthetic child bridge blocker" in (child_blocked.get("child_claim_grade_blockers") or [])
            and "synthetic allocator semantic blocker" in (child_blocked.get("child_claim_grade_blockers") or [])
            and child_blocked.get("allocator_feature") == "bench_scudo"
            and child_blocked_semantics.get("implementation_kind") == "std_alloc_system_fallback"
        ),
        "missing_selector_refused": refused_with("missing_selector_refused", "missing selector placeholders"),
        "missing_selector_reports_claim_blocker": has_blocker(
            "missing_selector_refused",
            "adapter selector contract is incomplete",
        ),
        "missing_benchmark_owned_timing_refused": refused_with(
            "missing_benchmark_owned_timing_refused",
            "benchmark_owned_json",
        ),
        "missing_benchmark_owned_timing_reports_claim_blocker": has_blocker(
            "missing_benchmark_owned_timing_refused",
            "adapter timing contract is not marked benchmark_owned_json=true",
        ),
        "missing_time_fields_refused": refused_with("missing_time_fields_refused", "time_field/time_fields"),
        "missing_time_fields_reports_claim_blocker": has_blocker(
            "missing_time_fields_refused",
            "adapter timing contract does not declare stdout JSON timing fields",
        ),
        "unconfigured_config_refused": (
            results.get("unconfigured_config_refused", {}).get("returncode") != 0
            and last_json("unconfigured_config_refused").get("success") is False
        ),
        "unconfigured_config_reports_claim_blocker": has_blocker(
            "unconfigured_config_refused",
            "adapter config remains configured=false",
        ),
        "unpinned_cargo_toolchain_injected": (
            ok_success("unpinned_cargo_toolchain_dry_run")
            and unpinned_toolchain.get("cargo_command_present") is True
            and unpinned_toolchain.get("unpinned_cargo_command_present") is True
            and unpinned_toolchain.get("rustup_toolchain_injected") is True
            and unpinned_toolchain.get("effective_rustup_toolchain") == "stable"
        ),
        "pinned_cargo_toolchain_not_overridden": (
            ok_success("pinned_cargo_toolchain_dry_run")
            and pinned_toolchain.get("cargo_command_present") is True
            and pinned_toolchain.get("unpinned_cargo_command_present") is False
            and pinned_toolchain.get("rustup_toolchain_injected") is False
            and pinned_toolchain.get("effective_rustup_toolchain") is None
        ),
    }


