def generate_compiler_proto_bench(
    *,
    run_id: str,
    target_stem: str,
    exact_dynamic: bool = False,
) -> Tuple[Path, Path, Dict[str, Any]]:
    benches_dir = ROOT / "unialloc" / "benches"
    module_dir = benches_dir / f"{target_stem}_modules"
    target_file = benches_dir / f"{target_stem}.rs"
    if target_file.exists():
        if target_stem in COMPILER_GENERATED_STD_BENCH_TARGET_STEMS:
            _GENERATED_COMPILER_BENCH_RESTORE_SOURCES[str(target_file)] = target_file.read_text(
                encoding="utf-8"
            )
        target_file.unlink()
    if module_dir.exists():
        shutil.rmtree(module_dir)
    module_dir.mkdir(parents=True, exist_ok=True)

    manifest: Dict[str, Any] = {
        "schema_version": 1,
        "run_id": run_id,
        "target": target_stem,
        "generator": "evaluation/scripts/evaluate.py:generate_compiler_proto_bench",
        "instrumentation_mode": "exact-dynamic-allocation-site-scope" if exact_dynamic else "source-to-source-prototype",
        "exact_dynamic_allocation_site_scope": bool(exact_dynamic),
        "event_source": COMPILER_EXACT_DYNAMIC_STD_BENCH_EVENT_SOURCE if exact_dynamic else COMPILER_PROTO_EVENT_SOURCE,
        "type_id_basis": COMPILER_EXACT_DYNAMIC_TYPE_ID_BASIS if exact_dynamic else None,
        "compiler_site_replay": False,
        "compiler_site_id_stream_mode": "exact-dynamic" if exact_dynamic else "source-scoped",
        "source_root": str(benches_dir),
        "generated_root_file": str(target_file),
        "generated_module_dir": str(module_dir),
        "files": [],
        "instrumented_function_count": 0,
        "macro_template_count": 0,
        "rust_type_inferred_count": 0,
        "known_no_heap_scope_count": 0,
        "scope_id_fallback_count": 0,
        "typed_or_known_no_heap_scope_count": 0,
        "allocation_semantics_counts": {},
        "inferred_rust_types": [],
        "limitations": [
            "Source-to-source generated benchmark target; not a rustc/LLVM/MIR compiler pass.",
            "Where the in-tree benchmark source is unambiguous, semantic ids are derived from inferred Rust collection types.",
            "Some macro templates are split into value-inferred scopes when the generated value's Rust type is only known after macro substitution.",
            "Audited no-heap string traversal benchmarks are reported separately from allocation-bearing fallback scopes.",
            "Ambiguous allocation-bearing benchmark functions fall back to generated benchmark scopes/templates.",
            "The inferred Rust types are source-level heuristics, not exact compiler allocation-site object types.",
            "The generated source is copied into evaluation/raw/<run-id>/generated-source for auditability.",
        ],
    }
    if exact_dynamic:
        manifest["limitations"].extend(
            [
                "Exact-dynamic mode uses the semantic-scope ABI to model compiler-emitted allocation-site metadata without a replayed runtime id stream.",
                "It is a short, generated std_bench evidence path and remains non-claim-grade until scaled to a full compiler-instrumented std_bench run without source rewriting.",
            ]
        )

    for relative in STD_BENCH_SOURCE_FILES:
        src = benches_dir / relative
        dst = module_dir / relative
        module_path = module_path_for_bench_source(relative)
        transformed, records = instrument_bench_source(src.read_text(encoding="utf-8"), module_path)
        dst.parent.mkdir(parents=True, exist_ok=True)
        dst.write_text(transformed, encoding="utf-8")
        manifest["files"].append(
            {
                "source": str(src),
                "generated": str(dst),
                "module_path": module_path,
                "instrumented_functions": records,
                "instrumented_function_count": len(records),
            }
        )
        manifest["instrumented_function_count"] += len(records)
        manifest["macro_template_count"] += sum(1 for record in records if record["macro_template"])
        manifest["rust_type_inferred_count"] += sum(1 for record in records if record.get("inferred_rust_type"))
        manifest["known_no_heap_scope_count"] += sum(
            1 for record in records if record.get("allocation_semantics") == COMPILER_PROTO_SCOPE_KNOWN_NO_HEAP
        )
        manifest["scope_id_fallback_count"] += sum(
            1 for record in records if record.get("allocation_semantics") == COMPILER_PROTO_SCOPE_FALLBACK
        )
        manifest["typed_or_known_no_heap_scope_count"] += sum(
            1
            for record in records
            if record.get("inferred_rust_type")
            or record.get("allocation_semantics") == COMPILER_PROTO_SCOPE_KNOWN_NO_HEAP
        )
        for record in records:
            semantics = str(record.get("allocation_semantics") or "unknown")
            manifest["allocation_semantics_counts"][semantics] = (
                manifest["allocation_semantics_counts"].get(semantics, 0) + 1
            )

    manifest["inferred_rust_types"] = sorted(
        {
            str(record.get("inferred_rust_type"))
            for file_record in manifest["files"]
            for record in file_record["instrumented_functions"]
            if record.get("inferred_rust_type")
        }
    )
    manifest["type_id_basis"] = compiler_proto_manifest_type_id_basis(manifest)

    target_file.write_text(
        compiler_proto_root_source(
            module_dir.name,
            manifest["type_id_basis"],
            exact_dynamic=exact_dynamic,
        ),
        encoding="utf-8",
    )
    return target_file, module_dir, manifest


def cleanup_generated_compiler_proto(target_file: Path, module_dir: Path, keep: bool) -> None:
    if keep:
        return
    if target_file.exists():
        if target_file.stem in COMPILER_GENERATED_STD_BENCH_TARGET_STEMS:
            restore_source = _GENERATED_COMPILER_BENCH_RESTORE_SOURCES.pop(str(target_file), None)
            if restore_source is None:
                restore_source = compiler_generated_bench_fallback_source(target_file.stem)
            target_file.write_text(restore_source, encoding="utf-8")
        else:
            target_file.unlink()
    elif target_file.stem in COMPILER_GENERATED_STD_BENCH_TARGET_STEMS:
        restore_source = _GENERATED_COMPILER_BENCH_RESTORE_SOURCES.pop(str(target_file), None)
        if restore_source is None:
            restore_source = compiler_generated_bench_fallback_source(target_file.stem)
        target_file.write_text(restore_source, encoding="utf-8")
    if module_dir.exists():
        shutil.rmtree(module_dir)


def copy_generated_compiler_proto_source(
    target_file: Path, module_dir: Path, out_dir: Path, manifest: Dict[str, Any]
) -> Path:
    artifact_dir = out_dir / "generated-source"
    if artifact_dir.exists():
        shutil.rmtree(artifact_dir)
    artifact_dir.mkdir(parents=True, exist_ok=True)
    shutil.copy2(target_file, artifact_dir / target_file.name)
    shutil.copytree(module_dir, artifact_dir / module_dir.name)
    manifest = dict(manifest)
    manifest["artifact_generated_source_dir"] = str(artifact_dir)
    manifest_path = artifact_dir / "instrumentation-manifest.json"
    write_json(manifest_path, manifest)
    return manifest_path


def compiler_exact_dynamic_std_bench_type_mapping_rows(manifest: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Build machine-auditable allocation-site rows for exact-dynamic std_bench slices.

    These rows intentionally use the generated bench labels as allocation-site
    provenance.  They are stronger than the replay bridge because the runtime
    event stream is exact-dynamic and non-cyclic, but they remain non-claim-grade
    until a real compiler pass covers the full std_bench target without source
    rewriting.
    """

    rows: List[Dict[str, Any]] = []
    for file_record in manifest.get("files", []):
        if not isinstance(file_record, dict):
            continue
        module_path = str(file_record.get("module_path") or "")
        source_path = str(file_record.get("source") or "")
        generated_path = str(file_record.get("generated") or "")
        for record in file_record.get("instrumented_functions", []):
            if not isinstance(record, dict):
                continue
            label = str(record.get("label") or "").strip()
            if not label:
                continue
            allocation_semantics = str(record.get("allocation_semantics") or "")
            if allocation_semantics == COMPILER_PROTO_SCOPE_KNOWN_NO_HEAP:
                continue
            site_class = {
                COMPILER_PROTO_SCOPE_TYPED: "typed-rust-object",
                COMPILER_PROTO_SCOPE_VALUE_TYPED: "value-typed-rust-object",
                COMPILER_PROTO_SCOPE_FALLBACK: "allocation-site-scope",
            }.get(allocation_semantics, "allocation-site-scope")
            type_id = compiler_proto_type_id_for_label(label, exact_dynamic=True)
            inferred_type = str(record.get("inferred_rust_type") or "").strip()
            object_type = inferred_type or f"compiler-allocation-site-scope::{label}"
            rows.append(
                {
                    "allocation_site_id": f"generated-mir:{label}:allocation-scope",
                    "type_id": type_id,
                    "object_type": object_type,
                    "mir_location": f"{label}::bb0[generated-allocation-scope]",
                    "source_span": source_path or f"std_bench::{module_path}",
                    "generated_source": generated_path,
                    "module_path": module_path,
                    "label": label,
                    "site_class": site_class,
                    "compiler_pass": COMPILER_EXACT_DYNAMIC_STD_BENCH_PASS_NAME,
                }
            )
    return rows


def write_compiler_exact_dynamic_std_bench_type_mapping(manifest: Dict[str, Any], path: Path) -> Path:
    write_json(
        path,
        {
            "schema_version": 1,
            "source": "compiler-exact-dynamic-std-bench-slice-type-mapping",
            "compiler_pass": COMPILER_EXACT_DYNAMIC_STD_BENCH_PASS_NAME,
            "type_id_basis": COMPILER_EXACT_DYNAMIC_TYPE_ID_BASIS,
            "allocation_sites": compiler_exact_dynamic_std_bench_type_mapping_rows(manifest),
        },
    )
    return path


def normalize_feature_csv(features: str, required: Iterable[str]) -> str:
    ordered = [part.strip() for part in str(features).split(",") if part.strip()]
    seen = set(ordered)
    for item in required:
        if item not in seen:
            ordered.append(item)
            seen.add(item)
    return ",".join(ordered)


def features_include(features: Any, feature: str) -> bool:
    return feature in {part.strip() for part in str(features or "").split(",") if part.strip()}


