def hugepage_platform_error_name(stage: Any, code: Any) -> str:
    stage_text = str(stage or "none")
    try:
        code_int = int(code or 0)
    except (TypeError, ValueError):
        code_int = 0
    if stage_text == "none":
        return "none"
    if stage_text in {
        "macos-mach-vm-allocate",
        "macos-mprotect",
        "macos-superpage-unsupported",
    }:
        return {
            0: "none",
            1: "KERN_INVALID_ADDRESS",
            2: "KERN_PROTECTION_FAILURE",
            3: "KERN_NO_SPACE",
            4: "KERN_INVALID_ARGUMENT",
            5: "KERN_FAILURE",
            6: "KERN_RESOURCE_SHORTAGE",
            46: "KERN_NOT_SUPPORTED",
            49: "KERN_OPERATION_TIMED_OUT",
            53: "KERN_DENIED",
        }.get(code_int, "kern-return")
    if stage_text == "linux-hugetlb-mmap":
        return {1: "EPERM", 12: "ENOMEM", 22: "EINVAL", 38: "ENOSYS"}.get(
            code_int, "linux-errno"
        )
    if stage_text == "windows-large-page-minimum-unavailable":
        return "large-page-minimum-unavailable"
    if stage_text == "windows-large-page-alloc":
        return {
            5: "ERROR_ACCESS_DENIED",
            87: "ERROR_INVALID_PARAMETER",
            1314: "ERROR_PRIVILEGE_NOT_HELD",
            1455: "ERROR_COMMITMENT_LIMIT",
        }.get(code_int, "windows-error")
    if stage_text == "unix-unsupported-platform":
        return "unsupported-platform"
    if stage_text == "invalid-request":
        return "invalid-request"
    return "unknown"

def hugepage_mmap_stats_from_coverage_stats(event_stats: Dict[str, Any]) -> Dict[str, Any]:
    stats = event_stats.get("hugepage_mmap_stats") if isinstance(event_stats, dict) else None
    if not isinstance(stats, dict):
        return {
            "attempts": 0,
            "successes": 0,
            "fallbacks": 0,
            "aligned_fallbacks": 0,
            "advised_fallbacks": 0,
            "fallback_failures": 0,
            "event_count": 0,
            "platform_error_stage": "none",
            "platform_error_stages": [],
            "platform_error_code": 0,
            "platform_error_name": "none",
        }
    platform_error_stages = unique_strings(stats.get("platform_error_stages") or [])
    platform_error_stage = str(
        stats.get("platform_error_stage")
        or (platform_error_stages[-1] if platform_error_stages else "none")
    )
    platform_error_code = int(stats.get("platform_error_code") or 0)
    platform_error_name = str(
        stats.get("platform_error_name")
        or hugepage_platform_error_name(platform_error_stage, platform_error_code)
    )
    return {
        "attempts": int(stats.get("attempts") or 0),
        "successes": int(stats.get("successes") or 0),
        "fallbacks": int(stats.get("fallbacks") or 0),
        "aligned_fallbacks": int(stats.get("aligned_fallbacks") or 0),
        "advised_fallbacks": int(stats.get("advised_fallbacks") or 0),
        "fallback_failures": int(stats.get("fallback_failures") or 0),
        "event_count": int(stats.get("event_count") or 0),
        "platform_error_stage": platform_error_stage,
        "platform_error_stages": platform_error_stages,
        "platform_error_code": platform_error_code,
        "platform_error_name": platform_error_name,
    }


