def hugepage_metadata_side_cache_validated(features: Any, event_stats: Dict[str, Any]) -> bool:
    stats = hugepage_metadata_side_cache_probe_from_coverage_stats(event_stats)
    side_cache_backing_observed = bool(
        stats["mmap_attempts_delta"] > 0
        or stats["preexisting_allocated"] > 0
        or any(
            backing and backing not in {"unallocated", "unmapped"}
            for backing in stats["mapping_backings"]
        )
        or any(
            backing and backing not in {"unallocated", "unmapped"}
            for backing in stats["preexisting_mapping_backings"]
        )
    )
    return bool(
        features_include(features, "hugepage")
        and stats["event_count"] > 0
        and stats["feature_enabled"] > 0
        and stats["attempted"] > 0
        and stats["allocated"] > 0
        and stats["reused"] > 0
        and stats["cache_hits_delta"] > 0
        and stats["cache_inserts_delta"] > 0
        and side_cache_backing_observed
    )


