def pac_metadata_auth_validated(features: Any, event_stats: Dict[str, Any]) -> bool:
    stats = pac_metadata_auth_probe_from_coverage_stats(event_stats)
    return bool(
        features_include(features, "pac")
        and stats["event_count"] > 0
        and stats["feature_enabled"] > 0
        and stats["attempted"] > 0
        and stats["context_binding_active"]
        and not stats["software_fallback_active"]
        and stats["pac_probe_strip_roundtrip"]
        and stats["pac_probe_correct_context_roundtrip"]
        and stats["pac_probe_wrong_context_rejected"]
        and any(
            key not in {"", "none"}
            for key in stats.get("pac_probe_active_keys", [])
        )
        and any(
            isinstance(entry, dict)
            and entry.get("key") in set(stats.get("pac_probe_active_keys", []))
            and entry.get("available") is True
            for entry in stats.get("pac_probe_key_matrix", [])
        )
        and stats["allocated"] > 0
        and stats["reused"] > 0
        and stats["cache_hits_delta"] > 0
        and stats["cache_inserts_delta"] > 0
        and stats["pac_signs_delta"] > 0
        and stats["pac_verifications_delta"] > 0
        and stats["pac_failures_delta"] == 0
    )


