PAC_HARDWARE_ABI_PROBE_SOURCE = "pac-hardware-abi-probe"
PAC_ARM64E_SHIM_COMPAT_PROBE_SOURCE = "pac-arm64e-shim-compat-probe"


def parse_probe_key_values(text: str) -> Dict[str, str]:
    return {
        match.group(1): match.group(2)
        for match in re.finditer(r"\b([A-Za-z_][A-Za-z0-9_]*)=([^\s]+)", text or "")
    }


def bool_probe_value(value: Any) -> bool:
    return str(value).strip().lower() in {"1", "true", "yes", "ok"}


PAC_RUST_ARM64E_TARGET_NAMES = {"arm64e-apple-darwin", "aarch64e-apple-darwin"}


def rust_target_list_contains_arm64e(target_list_stdout: str) -> bool:
    """Return whether rustc knows an Apple arm64e target triple."""

    return any(
        line.strip().lower() in PAC_RUST_ARM64E_TARGET_NAMES
        for line in (target_list_stdout or "").splitlines()
    )


def rustup_arm64e_std_status(target_list_stdout: str) -> Dict[str, bool]:
    """Summarize rustup std-component status for Apple arm64e targets.

    `rustc --print target-list` can list low-tier targets even when rustup has
    no prebuilt standard-library artifact for that target.  PAC claim gates need
    the stricter buildable distinction, otherwise a newer compiler's target-list
    entry can be mistaken for allocator runtime support.
    """

    available = False
    installed = False
    for raw in (target_list_stdout or "").splitlines():
        line = raw.strip().lower()
        if not any(line.startswith(name) for name in PAC_RUST_ARM64E_TARGET_NAMES):
            continue
        available = True
        if "(installed)" in line:
            installed = True
    return {"available": available, "installed": installed}


def rust_proxy_command(binary: str, toolchain: str, *args: str) -> List[str]:
    """Build a rustup-proxy command while keeping the selected toolchain audited."""

    cmd = [binary]
    if toolchain:
        cmd.append(rust_toolchain_arg(toolchain))
    cmd.extend(args)
    return cmd


def command_record(cmd: Sequence[str], *, cwd: Path, timeout: int) -> Dict[str, Any]:
    started = now_iso()
    start = time.perf_counter()
    error = None
    try:
        proc = subprocess.run(
            list(cmd),
            cwd=str(cwd),
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=timeout,
        )
        returncode = proc.returncode
        stdout_text = proc.stdout
        stderr_text = proc.stderr
    except subprocess.TimeoutExpired as exc:
        returncode = 124
        error = f"timeout after {timeout}s: {exc}"
        stdout_text = exc.stdout or ""
        stderr_text = exc.stderr or ""
        if isinstance(stdout_text, bytes):
            stdout_text = stdout_text.decode("utf-8", errors="replace")
        if isinstance(stderr_text, bytes):
            stderr_text = stderr_text.decode("utf-8", errors="replace")
    return {
        "command": list(cmd),
        "cwd": str(cwd),
        "started_at": started,
        "ended_at": now_iso(),
        "wall_seconds": time.perf_counter() - start,
        "returncode": returncode,
        "stdout": stdout_text,
        "stderr": stderr_text,
        "error": error,
    }


def collect_pac_hardware_abi_probe(args: argparse.Namespace) -> int:
    """Probe whether host PAC hardware is usable by the current ABI/toolchain."""

    run_id = args.run_id or _dt.datetime.now().strftime("pac-hardware-abi-probe-%Y%m%d-%H%M%S")
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)
    timeout = max(1, int(getattr(args, "timeout", 30) or 30))

    clang = shutil.which("clang")
    rustc = shutil.which("rustc")
    rustup = shutil.which("rustup")
    rust_toolchain = str(getattr(args, "rust_toolchain", "nightly") or "nightly")
    blockers: List[str] = []
    if not clang:
        blockers.append("clang not found; cannot compile PAC ABI probes")

    arm64_source = out_dir / "pac-raw-asm-arm64-probe.c"
    arm64e_source = out_dir / "pac-ptrauth-arm64e-probe.c"
    arm64e_wrong_source = out_dir / "pac-ptrauth-arm64e-wrong-auth-probe.c"
    arm64_binary = out_dir / "pac-raw-asm-arm64-probe"
    arm64e_binary = out_dir / "pac-ptrauth-arm64e-probe"
    arm64e_wrong_binary = out_dir / "pac-ptrauth-arm64e-wrong-auth-probe"

    arm64_source.write_text(
        r'''
#include <stdint.h>
#include <stdio.h>
static inline uintptr_t pacib(uintptr_t ptr, uintptr_t ctx) { __asm__("pacib %0, %1" : "+r"(ptr) : "r"(ctx)); return ptr; }
static inline uintptr_t autib(uintptr_t ptr, uintptr_t ctx) { __asm__("autib %0, %1" : "+r"(ptr) : "r"(ctx)); return ptr; }
static inline uintptr_t xpaci(uintptr_t ptr) { __asm__("xpaci %0" : "+r"(ptr)); return ptr; }
int main(void) {
  uintptr_t word = 0;
  uintptr_t ptr = (uintptr_t)&word;
  uintptr_t owner = 0x1111111111111111ULL;
  uintptr_t wrong_owner = 0x2222222222222222ULL;
  uintptr_t signed_ptr = pacib(ptr, owner);
  uintptr_t stripped = xpaci(signed_ptr);
  uintptr_t correct = autib(signed_ptr, owner);
  uintptr_t wrong = autib(signed_ptr, wrong_owner);
  printf("probe=arm64_raw_asm ptr=0x%llx signed=0x%llx signed_changed=%d strip_roundtrip=%d correct_context_roundtrip=%d wrong_context_rejected=%d\n",
         (unsigned long long)ptr, (unsigned long long)signed_ptr, signed_ptr != ptr,
         stripped == ptr, correct == ptr, wrong != ptr);
  return 0;
}
'''.lstrip(),
        encoding="utf-8",
    )
    arm64e_source.write_text(
        r'''
#include <stdint.h>
#include <stdio.h>
#include <ptrauth.h>
int main(void) {
  uintptr_t word = 0;
  void *ptr = (void *)&word;
  uintptr_t owner = 0x1111111111111111ULL;
  void *signed_ptr = ptrauth_sign_unauthenticated(ptr, ptrauth_key_process_dependent_data, owner);
  void *stripped = ptrauth_strip(signed_ptr, ptrauth_key_process_dependent_data);
  void *correct = ptrauth_auth_data(signed_ptr, ptrauth_key_process_dependent_data, owner);
  printf("probe=arm64e_ptrauth ptr=0x%llx signed=0x%llx signed_changed=%d strip_roundtrip=%d correct_context_roundtrip=%d\n",
         (unsigned long long)(uintptr_t)ptr, (unsigned long long)(uintptr_t)signed_ptr,
         signed_ptr != ptr, stripped == ptr, correct == ptr);
  return !((signed_ptr != ptr) && (stripped == ptr) && (correct == ptr));
}
'''.lstrip(),
        encoding="utf-8",
    )
    arm64e_wrong_source.write_text(
        r'''
#include <stdint.h>
#include <stdio.h>
#include <ptrauth.h>
int main(void) {
  uintptr_t word = 0;
  void *ptr = (void *)&word;
  uintptr_t owner = 0x1111111111111111ULL;
  uintptr_t wrong_owner = 0x2222222222222222ULL;
  void *signed_ptr = ptrauth_sign_unauthenticated(ptr, ptrauth_key_process_dependent_data, owner);
  fprintf(stderr, "before_wrong_context_auth signed_changed=%d\n", signed_ptr != ptr);
  fflush(stderr);
  void *wrong = ptrauth_auth_data(signed_ptr, ptrauth_key_process_dependent_data, wrong_owner);
  printf("probe=arm64e_wrong_auth wrong_auth_returned=1 wrong=0x%llx wrong_context_rejected=%d\n",
         (unsigned long long)(uintptr_t)wrong, wrong != ptr);
  return wrong == ptr ? 2 : 0;
}
'''.lstrip(),
        encoding="utf-8",
    )

    compile_arm64 = run_arm64 = compile_arm64e = run_arm64e = compile_arm64e_wrong = run_arm64e_wrong = None
    if clang:
        compile_arm64 = command_record(
            [clang, "-arch", "arm64", str(arm64_source), "-o", str(arm64_binary)],
            cwd=ROOT,
            timeout=timeout,
        )
        if compile_arm64["returncode"] == 0:
            run_arm64 = command_record([str(arm64_binary)], cwd=ROOT, timeout=timeout)
        else:
            blockers.append("arm64 raw PAC asm probe failed to compile")

        compile_arm64e = command_record(
            [clang, "-arch", "arm64e", str(arm64e_source), "-o", str(arm64e_binary)],
            cwd=ROOT,
            timeout=timeout,
        )
        if compile_arm64e["returncode"] == 0:
            run_arm64e = command_record([str(arm64e_binary)], cwd=ROOT, timeout=timeout)
        else:
            blockers.append("arm64e ptrauth probe failed to compile")

        compile_arm64e_wrong = command_record(
            [clang, "-arch", "arm64e", str(arm64e_wrong_source), "-o", str(arm64e_wrong_binary)],
            cwd=ROOT,
            timeout=timeout,
        )
        if compile_arm64e_wrong["returncode"] == 0:
            run_arm64e_wrong = command_record([str(arm64e_wrong_binary)], cwd=ROOT, timeout=timeout)
        else:
            blockers.append("arm64e wrong-context ptrauth probe failed to compile")

    arm64_kv = parse_probe_key_values((run_arm64 or {}).get("stdout", ""))
    arm64e_kv = parse_probe_key_values((run_arm64e or {}).get("stdout", ""))
    arm64e_wrong_kv = parse_probe_key_values((run_arm64e_wrong or {}).get("stdout", ""))

    arm64_raw_pac_noop = bool(
        run_arm64
        and run_arm64.get("returncode") == 0
        and not bool_probe_value(arm64_kv.get("signed_changed"))
        and bool_probe_value(arm64_kv.get("strip_roundtrip"))
        and bool_probe_value(arm64_kv.get("correct_context_roundtrip"))
        and not bool_probe_value(arm64_kv.get("wrong_context_rejected"))
    )
    arm64e_sign_correct_auth = bool(
        run_arm64e
        and run_arm64e.get("returncode") == 0
        and bool_probe_value(arm64e_kv.get("signed_changed"))
        and bool_probe_value(arm64e_kv.get("strip_roundtrip"))
        and bool_probe_value(arm64e_kv.get("correct_context_roundtrip"))
    )
    wrong_returncode = None if run_arm64e_wrong is None else run_arm64e_wrong.get("returncode")
    arm64e_wrong_rejected_by_signal = bool(
        isinstance(wrong_returncode, int) and wrong_returncode < 0
    )
    arm64e_wrong_rejected_by_value = bool(
        run_arm64e_wrong
        and run_arm64e_wrong.get("returncode") == 0
        and bool_probe_value(arm64e_wrong_kv.get("wrong_context_rejected"))
    )
    arm64e_wrong_context_rejected = arm64e_wrong_rejected_by_signal or arm64e_wrong_rejected_by_value
    hardware_pac_context_binding_observed = bool(
        arm64e_sign_correct_auth and arm64e_wrong_context_rejected
    )

    rust_targets = ""
    rustup_targets = ""
    rust_target_list_returncode: Optional[int] = None
    rustup_target_list_returncode: Optional[int] = None
    rust_target_list = None
    rustup_target_list = None
    if rustc:
        rust_target_list = command_record(
            rust_proxy_command(rustc, rust_toolchain, "--print", "target-list"),
            cwd=ROOT,
            timeout=timeout,
        )
        rust_target_list_returncode = rust_target_list.get("returncode")
        if rust_target_list_returncode == 0:
            rust_targets = str(rust_target_list.get("stdout") or "")
        else:
            blockers.append(f"rustc {rust_toolchain} target-list probe failed")
    else:
        blockers.append("rustc not found; cannot inspect Rust PAC target availability")
    if rustup:
        rustup_target_list = command_record(
            [rustup, "target", "list", "--toolchain", rust_toolchain.lstrip("+")],
            cwd=ROOT,
            timeout=timeout,
        )
        rustup_target_list_returncode = rustup_target_list.get("returncode")
        if rustup_target_list_returncode == 0:
            rustup_targets = str(rustup_target_list.get("stdout") or "")
        else:
            blockers.append(f"rustup target list failed for {rust_toolchain}")
    else:
        blockers.append("rustup not found; cannot verify arm64e standard-library availability")
    rust_arm64e_target_listed = rust_target_list_contains_arm64e(rust_targets)
    rustup_arm64e_status = rustup_arm64e_std_status(rustup_targets)
    rust_arm64e_std_available = rustup_arm64e_status["available"]
    rust_arm64e_std_installed = rustup_arm64e_status["installed"]
    rust_arm64e_target_available = bool(
        rust_arm64e_target_listed and rust_arm64e_std_installed
    )
    if rust_arm64e_target_listed and not rust_arm64e_std_installed:
        blockers.append(
            "Rust compiler lists arm64e-apple-darwin, but this toolchain has no "
            "installed/prebuilt arm64e standard library; allocator PAC cannot "
            "build/run as arm64e without build-std evidence"
        )
    elif not rust_arm64e_target_listed:
        blockers.append("Rust target list lacks arm64e/aarch64e Apple Darwin support")

    if run_arm64 is None or run_arm64.get("returncode") != 0:
        blockers.append("arm64 raw PAC asm probe did not run successfully")
    if run_arm64e is None or run_arm64e.get("returncode") != 0:
        blockers.append("arm64e ptrauth sign/correct-auth probe did not run successfully")
    if run_arm64e_wrong is None:
        blockers.append("arm64e wrong-context ptrauth probe did not run")
    elif not arm64e_wrong_context_rejected:
        blockers.append("arm64e wrong-context ptrauth probe did not reject the wrong context")

    removed_binaries: List[str] = []
    for path in (arm64_binary, arm64e_binary, arm64e_wrong_binary):
        if path.exists():
            try:
                path.unlink()
                removed_binaries.append(str(path))
            except OSError:
                pass

    audit = {
        "schema_version": 1,
        "generated_at": now_iso(),
        "source": PAC_HARDWARE_ABI_PROBE_SOURCE,
        "run_id": run_id,
        "host": host_metadata(),
        "clang": clang,
        "rustc": rustc,
        "rustup": rustup,
        "rust_toolchain": rust_toolchain,
        "artifacts": {
            "arm64_source": str(arm64_source),
            "arm64e_source": str(arm64e_source),
            "arm64e_wrong_auth_source": str(arm64e_wrong_source),
            "removed_binaries": removed_binaries,
        },
        "commands": {
            "compile_arm64": compile_arm64,
            "run_arm64": run_arm64,
            "compile_arm64e": compile_arm64e,
            "run_arm64e": run_arm64e,
            "compile_arm64e_wrong_auth": compile_arm64e_wrong,
            "run_arm64e_wrong_auth": run_arm64e_wrong,
            "rust_target_list": rust_target_list,
            "rustup_target_list": rustup_target_list,
        },
        "rust_target_list_returncode": rust_target_list_returncode,
        "rustup_target_list_returncode": rustup_target_list_returncode,
        "summary": {
            "arm64_raw_pac_noop": arm64_raw_pac_noop,
            "arm64e_sign_correct_auth": arm64e_sign_correct_auth,
            "arm64e_wrong_context_rejected": arm64e_wrong_context_rejected,
            "arm64e_wrong_context_rejected_by_signal": arm64e_wrong_rejected_by_signal,
            "arm64e_wrong_context_rejected_by_value": arm64e_wrong_rejected_by_value,
            "hardware_pac_context_binding_observed": hardware_pac_context_binding_observed,
            "rust_arm64e_target_listed": rust_arm64e_target_listed,
            "rust_arm64e_std_available": rust_arm64e_std_available,
            "rust_arm64e_std_installed": rust_arm64e_std_installed,
            "rust_arm64e_target_available": rust_arm64e_target_available,
            "rust_allocator_current_target_can_use_hardware_pac": rust_arm64e_target_available,
            "claim_grade": False,
            "complete_for_claim": False,
            "blockers": unique_strings(
                [
                    *blockers,
                    *(
                        [
                            "hardware PAC was observed only through an external arm64e C probe; current Rust allocator target is not buildable as arm64e"
                        ]
                        if hardware_pac_context_binding_observed and not rust_arm64e_target_available
                        else []
                    ),
                    "this ABI probe does not replace the allocator runtime PAC metadata-auth probe",
                ]
            ),
        },
    }
    audit_path = out_dir / "pac-hardware-abi-probe-audit.json"
    write_json(audit_path, audit)
    if not getattr(args, "no_update_results", False):
        write_json(RESULTS / "pac_hardware_abi_probe_audit.json", audit)
    print(str(audit_path))
    return 0 if hardware_pac_context_binding_observed else 1


def latest_pac_arm64e_shim_compat_probe_audit() -> Tuple[Optional[Path], Dict[str, Any]]:
    """Return newest arm64-host/arm64e-dylib PAC shim compatibility audit."""

    candidate_paths: List[Path] = [RESULTS / "pac_arm64e_shim_compat_probe_audit.json"]
    candidate_paths.extend(RAW.glob("*/pac-arm64e-shim-compat-probe-audit.json"))
    candidates: List[Tuple[float, str, Path, Dict[str, Any]]] = []
    seen: Set[str] = set()
    for path in candidate_paths:
        resolved = str(path)
        if resolved in seen:
            continue
        seen.add(resolved)
        try:
            data = read_json(path)
        except (OSError, json.JSONDecodeError):
            continue
        if not isinstance(data, dict):
            continue
        if data.get("source") != PAC_ARM64E_SHIM_COMPAT_PROBE_SOURCE:
            continue
        try:
            mtime = path.stat().st_mtime
        except OSError:
            mtime = 0.0
        candidates.append((mtime, str(path), path, data))
    if not candidates:
        return None, {}
    candidates.sort(key=lambda item: (item[0], item[1]), reverse=True)
    _mtime, _name, path, data = candidates[0]
    return path, data


def collect_pac_arm64e_shim_compat_probe(args: argparse.Namespace) -> int:
    """Probe whether an arm64 Rust process could use an arm64e PAC dylib shim."""

    run_id = args.run_id or _dt.datetime.now().strftime("pac-arm64e-shim-compat-probe-%Y%m%d-%H%M%S")
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)
    timeout = max(1, int(getattr(args, "timeout", 30) or 30))

    clang = shutil.which("clang")
    rustc = shutil.which("rustc")
    rustup = shutil.which("rustup")
    rust_toolchain = str(getattr(args, "rust_toolchain", "nightly") or "nightly")
    blockers: List[str] = []
    if platform.system() != "Darwin" or platform.machine() not in {"arm64", "aarch64"}:
        blockers.append("PAC arm64e shim compatibility probe requires an Apple arm64 host")
    if not clang:
        blockers.append("clang not found; cannot compile arm64/arm64e PAC shim probes")

    shim_source = out_dir / "pac-arm64e-shim.c"
    host_source = out_dir / "pac-shim-host.c"
    shim_dylib = out_dir / "libpac_arm64e_shim.dylib"
    host_arm64 = out_dir / "pac-shim-host-arm64"
    host_arm64e = out_dir / "pac-shim-host-arm64e"

    shim_source.write_text(
        r'''
#include <stdint.h>
#include <ptrauth.h>
uintptr_t pacshim_sign(uintptr_t ptr, uintptr_t ctx) {
  return (uintptr_t)ptrauth_sign_unauthenticated((void *)ptr, ptrauth_key_process_dependent_data, ctx);
}
uintptr_t pacshim_strip(uintptr_t ptr) {
  return (uintptr_t)ptrauth_strip((void *)ptr, ptrauth_key_process_dependent_data);
}
uintptr_t pacshim_auth(uintptr_t ptr, uintptr_t ctx) {
  return (uintptr_t)ptrauth_auth_data((void *)ptr, ptrauth_key_process_dependent_data, ctx);
}
'''.lstrip(),
        encoding="utf-8",
    )
    host_source.write_text(
        r'''
#include <dlfcn.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
typedef uintptr_t (*pacshim_fn)(uintptr_t, uintptr_t);
typedef uintptr_t (*pacshim_strip_fn)(uintptr_t);
int main(int argc, char **argv) {
  if (argc < 2) return 2;
  int run_wrong = argc > 2 && strcmp(argv[2], "--wrong") == 0;
  void *handle = dlopen(argv[1], RTLD_NOW);
  if (!handle) {
    printf("dlopen_ok=0 dlopen_error=%s\n", dlerror());
    return 3;
  }
  pacshim_fn sign_fn = (pacshim_fn)dlsym(handle, "pacshim_sign");
  pacshim_fn auth_fn = (pacshim_fn)dlsym(handle, "pacshim_auth");
  pacshim_strip_fn strip_fn = (pacshim_strip_fn)dlsym(handle, "pacshim_strip");
  if (!sign_fn || !auth_fn || !strip_fn) {
    printf("dlopen_ok=1 dlsym_ok=0 dlsym_error=%s\n", dlerror());
    return 4;
  }
  uintptr_t word = 0;
  uintptr_t ptr = (uintptr_t)&word;
  uintptr_t owner = 0x1111111111111111ULL;
  uintptr_t wrong_owner = 0x2222222222222222ULL;
  uintptr_t signed_ptr = sign_fn(ptr, owner);
  uintptr_t stripped = strip_fn(signed_ptr);
  uintptr_t correct = auth_fn(signed_ptr, owner);
  printf("dlopen_ok=1 dlsym_ok=1 ptr=0x%llx signed=0x%llx signed_changed=%d strip_roundtrip=%d correct_context_roundtrip=%d ",
         (unsigned long long)ptr,
         (unsigned long long)signed_ptr,
         signed_ptr != ptr,
         stripped == ptr,
         correct == ptr);
  fflush(stdout);
  if (run_wrong) {
    uintptr_t wrong = auth_fn(signed_ptr, wrong_owner);
    printf("wrong=0x%llx wrong_context_rejected=%d\n",
           (unsigned long long)wrong,
           wrong != ptr);
    return wrong == ptr ? 5 : 0;
  }
  printf("wrong_context_rejected=not-run\n");
  return !((signed_ptr != ptr) && (stripped == ptr) && (correct == ptr));
}
'''.lstrip(),
        encoding="utf-8",
    )

    compile_shim = compile_host_arm64 = compile_host_arm64e = None
    run_arm64_host = run_arm64_host_wrong = run_arm64e_host = run_arm64e_host_wrong = None
    if clang:
        compile_shim = command_record(
            [clang, "-arch", "arm64e", "-dynamiclib", str(shim_source), "-o", str(shim_dylib)],
            cwd=ROOT,
            timeout=timeout,
        )
        if compile_shim.get("returncode") != 0:
            blockers.append("arm64e PAC shim dylib failed to compile")
        compile_host_arm64 = command_record(
            [clang, "-arch", "arm64", str(host_source), "-o", str(host_arm64)],
            cwd=ROOT,
            timeout=timeout,
        )
        if compile_host_arm64.get("returncode") != 0:
            blockers.append("arm64 PAC shim host failed to compile")
        compile_host_arm64e = command_record(
            [clang, "-arch", "arm64e", str(host_source), "-o", str(host_arm64e)],
            cwd=ROOT,
            timeout=timeout,
        )
        if compile_host_arm64e.get("returncode") != 0:
            blockers.append("arm64e PAC shim host failed to compile")

        if (
            compile_shim.get("returncode") == 0
            and compile_host_arm64.get("returncode") == 0
        ):
            run_arm64_host = command_record([str(host_arm64), str(shim_dylib)], cwd=ROOT, timeout=timeout)
            run_arm64_host_wrong = command_record(
                [str(host_arm64), str(shim_dylib), "--wrong"],
                cwd=ROOT,
                timeout=timeout,
            )
        if (
            compile_shim.get("returncode") == 0
            and compile_host_arm64e.get("returncode") == 0
        ):
            run_arm64e_host = command_record([str(host_arm64e), str(shim_dylib)], cwd=ROOT, timeout=timeout)
            run_arm64e_host_wrong = command_record(
                [str(host_arm64e), str(shim_dylib), "--wrong"],
                cwd=ROOT,
                timeout=timeout,
            )

    arm64_host_kv = parse_probe_key_values((run_arm64_host or {}).get("stdout", ""))
    arm64_host_wrong_kv = parse_probe_key_values((run_arm64_host_wrong or {}).get("stdout", ""))
    arm64e_host_kv = parse_probe_key_values((run_arm64e_host or {}).get("stdout", ""))
    arm64e_host_wrong_returncode = None if run_arm64e_host_wrong is None else run_arm64e_host_wrong.get("returncode")
    arm64e_host_wrong_rejected_by_signal = bool(
        isinstance(arm64e_host_wrong_returncode, int) and arm64e_host_wrong_returncode < 0
    )
    arm64_host_loads_arm64e_dylib = bool(
        run_arm64_host and bool_probe_value(arm64_host_kv.get("dlopen_ok"))
    )
    arm64_host_arm64e_shim_context_binding = bool(
        run_arm64_host
        and run_arm64_host.get("returncode") == 0
        and bool_probe_value(arm64_host_kv.get("signed_changed"))
        and bool_probe_value(arm64_host_kv.get("strip_roundtrip"))
        and bool_probe_value(arm64_host_kv.get("correct_context_roundtrip"))
    )
    arm64_host_wrong_context_rejected = bool(
        run_arm64_host_wrong
        and run_arm64_host_wrong.get("returncode") == 0
        and bool_probe_value(arm64_host_wrong_kv.get("wrong_context_rejected"))
    )
    arm64e_host_arm64e_shim_context_binding = bool(
        run_arm64e_host
        and run_arm64e_host.get("returncode") == 0
        and bool_probe_value(arm64e_host_kv.get("signed_changed"))
        and bool_probe_value(arm64e_host_kv.get("strip_roundtrip"))
        and bool_probe_value(arm64e_host_kv.get("correct_context_roundtrip"))
    )

    rust_targets = ""
    rustup_targets = ""
    rust_target_list_returncode: Optional[int] = None
    rustup_target_list_returncode: Optional[int] = None
    rust_target_list = None
    rustup_target_list = None
    if rustc:
        rust_target_list = command_record(
            rust_proxy_command(rustc, rust_toolchain, "--print", "target-list"),
            cwd=ROOT,
            timeout=timeout,
        )
        rust_target_list_returncode = rust_target_list.get("returncode")
        if rust_target_list_returncode == 0:
            rust_targets = str(rust_target_list.get("stdout") or "")
        else:
            blockers.append(f"rustc {rust_toolchain} target-list probe failed")
    else:
        blockers.append("rustc not found; cannot inspect Rust PAC target availability")
    if rustup:
        rustup_target_list = command_record(
            [rustup, "target", "list", "--toolchain", rust_toolchain.lstrip("+")],
            cwd=ROOT,
            timeout=timeout,
        )
        rustup_target_list_returncode = rustup_target_list.get("returncode")
        if rustup_target_list_returncode == 0:
            rustup_targets = str(rustup_target_list.get("stdout") or "")
        else:
            blockers.append(f"rustup target list failed for {rust_toolchain}")
    else:
        blockers.append("rustup not found; cannot verify arm64e standard-library availability")
    rust_arm64e_target_listed = rust_target_list_contains_arm64e(rust_targets)
    rustup_arm64e_status = rustup_arm64e_std_status(rustup_targets)
    rust_arm64e_std_available = rustup_arm64e_status["available"]
    rust_arm64e_std_installed = rustup_arm64e_status["installed"]
    rust_arm64e_target_available = bool(
        rust_arm64e_target_listed and rust_arm64e_std_installed
    )
    arm64_host_can_use_arm64e_shim = bool(
        arm64_host_loads_arm64e_dylib
        and arm64_host_arm64e_shim_context_binding
        and arm64_host_wrong_context_rejected
    )
    current_rust_target_can_use_arm64e_shim = bool(
        rust_arm64e_target_available or arm64_host_can_use_arm64e_shim
    )
    if rust_arm64e_target_listed and not rust_arm64e_std_installed:
        blockers.append(
            "Rust compiler lists arm64e-apple-darwin, but this toolchain has no "
            "installed/prebuilt arm64e standard library; allocator PAC cannot "
            "build/run as arm64e without build-std evidence"
        )
    elif not rust_arm64e_target_listed:
        blockers.append("Rust target list lacks arm64e/aarch64e Apple Darwin support")

    if not arm64_host_loads_arm64e_dylib:
        blockers.append("arm64 host could not load the arm64e PAC shim dylib")
    if not arm64_host_arm64e_shim_context_binding:
        blockers.append("arm64 host loaded the arm64e PAC shim but PAC operations remained no-op")
    if not arm64_host_wrong_context_rejected:
        blockers.append("arm64 host did not reject wrong-context auth through the arm64e PAC shim")
    if not arm64e_host_arm64e_shim_context_binding:
        blockers.append("arm64e host did not validate sign/strip/correct-auth through the PAC shim")
    if not arm64e_host_wrong_rejected_by_signal:
        blockers.append("arm64e host wrong-context shim auth did not terminate with a PAC failure signal")
    removed_binaries: List[str] = []
    for path in (shim_dylib, host_arm64, host_arm64e):
        if path.exists():
            try:
                path.unlink()
                removed_binaries.append(str(path))
            except OSError:
                pass

    summary = {
        "arm64_host_loads_arm64e_dylib": arm64_host_loads_arm64e_dylib,
        "arm64_host_arm64e_shim_context_binding": arm64_host_arm64e_shim_context_binding,
        "arm64_host_wrong_context_rejected": arm64_host_wrong_context_rejected,
        "arm64e_host_arm64e_shim_context_binding": arm64e_host_arm64e_shim_context_binding,
        "arm64e_host_wrong_context_rejected_by_signal": arm64e_host_wrong_rejected_by_signal,
        "rust_arm64e_target_listed": rust_arm64e_target_listed,
        "rust_arm64e_std_available": rust_arm64e_std_available,
        "rust_arm64e_std_installed": rust_arm64e_std_installed,
        "rust_arm64e_target_available": rust_arm64e_target_available,
        "arm64_host_can_use_arm64e_shim": arm64_host_can_use_arm64e_shim,
        "current_rust_target_can_use_arm64e_shim": current_rust_target_can_use_arm64e_shim,
        "claim_grade": False,
        "complete_for_claim": False,
        "blockers": unique_strings(blockers),
    }
    audit = {
        "schema_version": 1,
        "generated_at": now_iso(),
        "source": PAC_ARM64E_SHIM_COMPAT_PROBE_SOURCE,
        "run_id": run_id,
        "host": host_metadata(),
        "clang": clang,
        "rustc": rustc,
        "rustup": rustup,
        "rust_toolchain": rust_toolchain,
        "artifacts": {
            "shim_source": str(shim_source),
            "host_source": str(host_source),
            "removed_binaries": removed_binaries,
        },
        "commands": {
            "compile_shim": compile_shim,
            "compile_host_arm64": compile_host_arm64,
            "compile_host_arm64e": compile_host_arm64e,
            "run_arm64_host": run_arm64_host,
            "run_arm64_host_wrong": run_arm64_host_wrong,
            "run_arm64e_host": run_arm64e_host,
            "run_arm64e_host_wrong": run_arm64e_host_wrong,
            "rust_target_list": rust_target_list,
            "rustup_target_list": rustup_target_list,
        },
        "rust_target_list_returncode": rust_target_list_returncode,
        "rustup_target_list_returncode": rustup_target_list_returncode,
        "summary": summary,
    }
    audit_path = out_dir / "pac-arm64e-shim-compat-probe-audit.json"
    write_json(audit_path, audit)
    if not getattr(args, "no_update_results", False):
        write_json(RESULTS / "pac_arm64e_shim_compat_probe_audit.json", audit)
    print(str(audit_path))
    return 0 if current_rust_target_can_use_arm64e_shim else 1



PAC_METADATA_DIRECT_PROBE_SOURCE = "pac-metadata-direct-probe"


def pac_metadata_direct_probe_summary(event: Dict[str, Any], record: Dict[str, Any]) -> Dict[str, Any]:
    """Normalize the direct allocator/PAC metadata-auth probe output."""

    return {
        "probe_validated": bool(record.get("passed") and event.get("passed") is True),
        "runtime": str(event.get("runtime") or "std"),
        "claim_grade": event.get("claim_grade") is True,
        "allocator_validated": event.get("allocator_validated") is True,
        "full_allocator_side_cache_validated": event.get("full_allocator_side_cache_validated")
        is True,
        "metadata_pac_negative_auth_requires_signal_probe": event.get(
            "metadata_pac_negative_auth_requires_signal_probe"
        )
        is True,
        "hardware_pac_validated": event.get("hardware_pac_validated") is True,
        "software_fallback_validated": event.get("software_fallback_validated") is True,
        "context_binding_active": event.get("context_binding_active") is True,
        "software_fallback_active": event.get("software_fallback_active") is True,
        "pac_probe_uses_allocated_object": event.get("pac_probe_uses_allocated_object") is True,
        "backend_observation_consistent": event.get("backend_observation_consistent") is True,
        "pac_probe_key": str(event.get("pac_probe_key") or "none"),
        "pac_probe_active_key": str(event.get("pac_probe_active_key") or "none"),
        "pac_probe_key_matrix": event.get("pac_probe_key_matrix") if isinstance(event.get("pac_probe_key_matrix"), list) else [],
        "pac_probe_signed_changed": event.get("pac_probe_signed_changed") is True,
        "pac_probe_strip_roundtrip": event.get("pac_probe_strip_roundtrip") is True,
        "pac_probe_correct_context_roundtrip": event.get("pac_probe_correct_context_roundtrip") is True,
        "pac_probe_wrong_context_rejected": event.get("pac_probe_wrong_context_rejected") is True,
        "reused_same_ptr": event.get("reused_same_ptr") is True,
        "typed_cache_inserts": int(event.get("typed_cache_inserts") or 0),
        "typed_cache_hits": int(event.get("typed_cache_hits") or 0),
        "pac_signs": int(event.get("pac_signs") or 0),
        "pac_verifications": int(event.get("pac_verifications") or 0),
        "pac_failures": int(event.get("pac_failures") or 0),
        "pac_software_fallback_signs": int(event.get("pac_software_fallback_signs") or 0),
        "pac_software_fallback_verifications": int(event.get("pac_software_fallback_verifications") or 0),
        "pac_software_fallback_failures": int(event.get("pac_software_fallback_failures") or 0),
        "exit_code": int(record.get("exit_code") or 0),
    }


def pac_metadata_direct_probe_blockers(audit: Dict[str, Any]) -> List[str]:
    """Return fail-closed C006 blockers for the direct allocator/PAC probe."""

    if not isinstance(audit, dict):
        return ["missing direct PAC metadata allocator probe audit"]
    summary = audit.get("summary") if isinstance(audit.get("summary"), dict) else {}
    blockers: List[str] = []
    if (
        summary.get("skipped_allocator_probe_due_to_preflight") is True
        or summary.get("arm64e_std_runtime_preflight_passed") is False
    ):
        blockers.append(
            "arm64e std runtime preflight failed before the UniAlloc allocator probe: "
            f"exit_code={summary.get('exit_code')}; "
            "use the arm64e no_std direct PAC probe for allocator hardware-PAC evidence"
        )
        return unique_strings(blockers)
    if summary.get("probe_validated") is not True:
        blockers.append("direct PAC metadata probe did not validate allocator side-cache reuse")
    if summary.get("allocator_validated") is not True:
        blockers.append("direct PAC metadata probe did not validate typed-cache insert/hit reuse")
    if (
        summary.get("runtime") == "nostd"
        and summary.get("full_allocator_side_cache_validated") is not True
    ):
        blockers.append(
            "no_std PAC primitive probe validated hardware PAC but did not validate the full "
            "allocator type-cache side-cache insert/hit path"
        )
    if optional_int(summary.get("typed_cache_inserts")) in (None, 0):
        blockers.append("direct PAC metadata probe observed no typed-cache inserts")
    if optional_int(summary.get("typed_cache_hits")) in (None, 0):
        blockers.append("direct PAC metadata probe observed no typed-cache hits")
    exit_code = optional_int(summary.get("exit_code"))
    if exit_code is not None and exit_code < 0:
        blockers.append(
            "direct PAC metadata probe terminated by signal "
            f"{-exit_code} before emitting claim-grade JSON"
        )
    if summary.get("hardware_pac_validated") is not True:
        matrix = summary.get("pac_probe_key_matrix")
        matrix_detail = ""
        if isinstance(matrix, list) and matrix:
            compact = ",".join(
                f"{entry.get('key')}:avail={entry.get('available')},wrong_reject={entry.get('wrong_context_rejected')}"
                for entry in matrix
                if isinstance(entry, dict)
            )
            if compact:
                matrix_detail = f", key_matrix=[{compact}]"
        blockers.append(
            "direct PAC metadata probe did not validate allocator hardware PAC context binding: "
            f"context_binding_active={summary.get('context_binding_active')}, "
            f"software_fallback_active={summary.get('software_fallback_active')}, "
            f"hardware_pac_validated={summary.get('hardware_pac_validated')}, "
            f"software_fallback_validated={summary.get('software_fallback_validated')}, "
            f"active_key={summary.get('pac_probe_active_key')}, "
            f"signed_changed={summary.get('pac_probe_signed_changed')}, "
            f"wrong_context_rejected={summary.get('pac_probe_wrong_context_rejected')}, "
            f"pac_signs={summary.get('pac_signs')}, "
            f"pac_verifications={summary.get('pac_verifications')}, "
            f"software_fallback_signs={summary.get('pac_software_fallback_signs')}, "
            f"software_fallback_verifications={summary.get('pac_software_fallback_verifications')}"
            f"{matrix_detail}"
        )
    return unique_strings(blockers)


def latest_pac_metadata_direct_probe_audit() -> Tuple[Optional[Path], Dict[str, Any]]:
    """Return the strongest direct allocator/PAC metadata-auth probe audit.

    A later software-fallback diagnostic must not hide an existing allocator
    hardware-PAC audit.  Prefer blocker-free hardware-PAC claim-grade evidence
    first, then use mtime as the tie-breaker within the same evidence strength.
    """

    candidate_paths: List[Path] = [RESULTS / "pac_metadata_direct_probe_audit.json"]
    candidate_paths.extend(RAW.glob("*/pac-metadata-direct-probe-audit.json"))
    candidates: List[Tuple[Tuple[int, int, int, int, float, str], Path, Dict[str, Any]]] = []
    seen: Set[str] = set()
    for path in candidate_paths:
        resolved = str(path)
        if resolved in seen:
            continue
        seen.add(resolved)
        try:
            data = read_json(path)
        except (OSError, json.JSONDecodeError):
            continue
        if not isinstance(data, dict):
            continue
        if data.get("source") != PAC_METADATA_DIRECT_PROBE_SOURCE:
            continue
        try:
            mtime = path.stat().st_mtime
        except OSError:
            mtime = 0.0
        summary = data.get("summary") if isinstance(data.get("summary"), dict) else {}
        claim_grade_ready = bool(
            summary.get("claim_grade") is True
            and summary.get("hardware_pac_validated") is True
            and not pac_metadata_direct_probe_blockers(data)
        )
        score = (
            1 if claim_grade_ready else 0,
            1 if summary.get("claim_grade") is True else 0,
            1 if summary.get("hardware_pac_validated") is True else 0,
            1 if summary.get("probe_validated") is True else 0,
            mtime,
            str(path),
        )
        candidates.append((score, path, data))
    if not candidates:
        return None, {}
    candidates.sort(key=lambda item: item[0], reverse=True)
    _score, path, data = candidates[0]
    return path, data


def latest_pac_arm64e_build_std_direct_probe_audit() -> Tuple[Optional[Path], Dict[str, Any]]:
    """Return the newest direct arm64e allocator probe that used cargo build-std.

    The strongest direct PAC probe may still be a host-target software fallback
    because it validates allocator reuse.  Keep the arm64e build-std attempt as
    a separate evidence channel so C006 can report whether the target now builds
    and where the true runtime blocker is.
    """

    candidates: List[Tuple[float, str, Path, Dict[str, Any]]] = []
    seen: Set[str] = set()
    for path in [RESULTS / "pac_metadata_direct_probe_audit.json", *RAW.glob("*/pac-metadata-direct-probe-audit.json")]:
        resolved = str(path)
        if resolved in seen:
            continue
        seen.add(resolved)
        try:
            data = read_json(path)
        except (OSError, json.JSONDecodeError):
            continue
        if not isinstance(data, dict) or data.get("source") != PAC_METADATA_DIRECT_PROBE_SOURCE:
            continue
        summary = data.get("summary") if isinstance(data.get("summary"), dict) else {}
        if summary.get("rust_target") != "arm64e-apple-darwin":
            continue
        if summary.get("build_std_requested") is not True:
            continue
        try:
            mtime = path.stat().st_mtime
        except OSError:
            mtime = 0.0
        candidates.append((mtime, str(path), path, data))
    if not candidates:
        return None, {}
    candidates.sort(reverse=True)
    _mtime, _text, path, data = candidates[0]
    return path, data


def write_arm64e_std_runtime_preflight_crate(out_dir: Path) -> Path:
    """Create the smallest Rust std binary used to separate runtime failure from allocator failure."""

    crate_dir = out_dir / "arm64e-std-runtime-preflight"
    src_dir = crate_dir / "src"
    src_dir.mkdir(parents=True, exist_ok=True)
    (crate_dir / "Cargo.toml").write_text(
        "\n".join(
            [
                "[package]",
                'name = "arm64e_std_runtime_preflight"',
                'version = "0.1.0"',
                'edition = "2021"',
                "",
                "[workspace]",
                "",
            ]
        ),
        encoding="utf-8",
    )
    (src_dir / "main.rs").write_text(
        'fn main() {\n    println!("arm64e_std_runtime_preflight_ok");\n}\n',
        encoding="utf-8",
    )
    return crate_dir


def run_arm64e_std_runtime_preflight(
    out_dir: Path,
    *,
    cargo: str,
    toolchain: str,
    target: str,
    build_std_crates: str,
    timeout: int,
    cargo_target_dir: Path,
) -> Dict[str, Any]:
    """Run a tiny arm64e std binary before blaming the allocator probe.

    On current macOS/Rust nightly, `arm64e-apple-darwin` may be target-listed
    and buildable with `-Z build-std` while a minimal Rust std binary still
    aborts before `main`.  In that case the allocator PAC evidence should come
    from the no_std arm64e probe, and the std probe should fail with a precise
    runtime blocker instead of a misleading allocator-side SIGSEGV.
    """

    crate_dir = write_arm64e_std_runtime_preflight_crate(out_dir)
    cmd = [
        cargo,
        rust_toolchain_arg(toolchain),
        "run",
        "-Z",
        f"build-std={build_std_crates}",
        "-q",
        "--manifest-path",
        str(crate_dir / "Cargo.toml"),
        "--target",
        target,
    ]
    return run_platform_command(
        out_dir,
        "pac-arm64e-std-runtime-preflight",
        cmd,
        timeout,
        extra_env={"CARGO_TARGET_DIR": str(cargo_target_dir)},
    )


def collect_pac_metadata_direct_probe(args: argparse.Namespace) -> int:
    """Run a real allocator/PAC metadata-auth side-cache probe."""

    run_id = args.run_id or _dt.datetime.now().strftime("pac-metadata-direct-probe-%Y%m%d-%H%M%S")
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)
    timeout = max(1, int(getattr(args, "timeout", 120) or 120))
    toolchain = str(getattr(args, "toolchain", "nightly") or "nightly")
    features = str(getattr(args, "features", "pac,stats") or "pac,stats")
    target = str(getattr(args, "target", "") or "").strip()
    build_std = bool(getattr(args, "build_std", False))
    build_std_crates = str(getattr(args, "build_std_crates", "std,panic_abort") or "std,panic_abort")
    runtime = str(getattr(args, "runtime", "std") or "std")
    if runtime not in {"std", "nostd"}:
        raise ValueError(f"unsupported PAC metadata probe runtime: {runtime}")
    example = "pac_metadata_probe_nostd" if runtime == "nostd" else "pac_metadata_probe"
    cargo = shutil.which("cargo") or "cargo"
    cmd = [cargo, rust_toolchain_arg(toolchain), "run"]
    if build_std:
        # `arm64e-apple-darwin` is visible to current rustc, but rustup does not
        # ship a prebuilt std artifact for this low-tier target.  Keep the
        # build-from-source choice explicit in the command line and audit record
        # instead of silently treating target-list visibility as buildability.
        cmd.extend(["-Z", f"build-std={build_std_crates}"])
    cmd.extend(["-q", "-p", "unialloc"])
    if target:
        cmd.extend(["--target", target])
    cmd.extend(
        [
            "--example",
            example,
            "--features",
            features,
        ]
    )
    cargo_target_dir = out_dir / "cargo-target"
    arm64e_std_preflight: Optional[Dict[str, Any]] = None
    skip_allocator_probe_due_to_preflight = False
    if target == "arm64e-apple-darwin" and runtime == "std" and build_std:
        arm64e_std_preflight = run_arm64e_std_runtime_preflight(
            out_dir,
            cargo=cargo,
            toolchain=toolchain,
            target=target,
            build_std_crates=build_std_crates,
            timeout=timeout,
            cargo_target_dir=cargo_target_dir,
        )
        skip_allocator_probe_due_to_preflight = arm64e_std_preflight.get("passed") is not True

    if skip_allocator_probe_due_to_preflight:
        record = {
            "schema_version": 1,
            "label": "pac-metadata-direct-probe",
            "command": cmd,
            "started_at": now_iso(),
            "ended_at": now_iso(),
            "wall_seconds": 0.0,
            "exit_code": arm64e_std_preflight.get("exit_code"),
            "error": "skipped because arm64e std runtime preflight failed",
            "stdout": arm64e_std_preflight.get("stdout"),
            "stderr": arm64e_std_preflight.get("stderr"),
            "env_overrides": {"CARGO_TARGET_DIR": str(cargo_target_dir)},
            "passed": False,
        }
    else:
        record = run_platform_command(
            out_dir,
            "pac-metadata-direct-probe",
            cmd,
            timeout,
            extra_env={"CARGO_TARGET_DIR": str(cargo_target_dir)},
        )
    cargo_target_cleanup = remove_directory_if_present(cargo_target_dir)
    event = parse_last_json_stdout_event(record) or {}
    if event.get("source") != "pac_metadata_probe":
        event = {}
    summary = pac_metadata_direct_probe_summary(event, record)
    summary["rust_toolchain"] = toolchain
    summary["rust_target"] = target or None
    summary["runtime"] = runtime
    summary["build_std_requested"] = build_std
    summary["build_std_crates"] = build_std_crates if build_std else None
    summary["cargo_target_cleaned"] = bool(cargo_target_cleanup.get("removed"))
    summary["cargo_target_removed_bytes"] = cargo_target_cleanup.get("removed_bytes")
    summary["arm64e_std_runtime_preflight_passed"] = (
        arm64e_std_preflight.get("passed") if isinstance(arm64e_std_preflight, dict) else None
    )
    summary["skipped_allocator_probe_due_to_preflight"] = skip_allocator_probe_due_to_preflight
    blockers = pac_metadata_direct_probe_blockers(
        {"source": PAC_METADATA_DIRECT_PROBE_SOURCE, "summary": summary}
    )
    stderr_ref = str(record.get("stderr") or "")
    stderr_path = Path(stderr_ref) if stderr_ref else None
    stderr_text = (
        stderr_path.read_text(encoding="utf-8", errors="replace")
        if stderr_path is not None and stderr_path.exists()
        else stderr_ref
    )
    if target and "can't find crate for `core`" in stderr_text:
        if build_std:
            blockers.append(
                f"Rust target {target} still could not provide core/std for {toolchain} even with "
                f"-Zbuild-std={build_std_crates}; allocator PAC cannot build/run as arm64e"
            )
        else:
            blockers.append(
                f"Rust target {target} lacks an installed standard library for {toolchain}; "
                "allocator PAC cannot build/run as arm64e without build-std evidence"
            )
    blockers = unique_strings(blockers)
    audit = {
        "schema_version": 1,
        "source": PAC_METADATA_DIRECT_PROBE_SOURCE,
        "run_id": run_id,
        "generated_at": now_iso(),
        "features": features,
        "rust_toolchain": toolchain,
        "rust_target": target or None,
        "runtime": runtime,
        "build_std_requested": build_std,
        "build_std_crates": build_std_crates if build_std else None,
        "command": record.get("command"),
        "stdout": record.get("stdout"),
        "stderr": record.get("stderr"),
        "cargo_target_dir": str(cargo_target_dir),
        "cargo_target_cleanup": cargo_target_cleanup,
        "arm64e_std_runtime_preflight": arm64e_std_preflight,
        "event": event,
        "summary": summary,
        "blockers": blockers,
        "claim_grade": summary.get("claim_grade") is True and not blockers,
    }
    audit_path = out_dir / "pac-metadata-direct-probe-audit.json"
    write_json(audit_path, audit)
    if not getattr(args, "no_update_results", False):
        write_json(RESULTS / "pac_metadata_direct_probe_audit.json", audit)
    print(str(audit_path))
    return 0 if summary.get("probe_validated") is True else 1

HUGEPAGE_METADATA_DIRECT_PROBE_SOURCE = "hugepage-metadata-direct-probe"


def hugepage_metadata_direct_probe_summary(event: Dict[str, Any], record: Dict[str, Any]) -> Dict[str, Any]:
    """Normalize the direct allocator/PAL hugepage metadata probe output."""

    return {
        "probe_validated": bool(record.get("passed") and event.get("passed") is True),
        "claim_grade": event.get("claim_grade") is True,
        "hugepage_backed": event.get("hugepage_backed") is True,
        "side_cache_allocated": event.get("side_cache_allocated") is True,
        "backing": str(event.get("backing") or "unknown"),
        "mmap_attempts": int(event.get("mmap_attempts") or 0),
        "mmap_successes": int(event.get("mmap_successes") or 0),
        "mmap_fallbacks": int(event.get("mmap_fallbacks") or 0),
        "mmap_aligned_fallbacks": int(event.get("mmap_aligned_fallbacks") or 0),
        "mmap_advised_fallbacks": int(event.get("mmap_advised_fallbacks") or 0),
        "mmap_fallback_failures": int(event.get("mmap_fallback_failures") or 0),
        "mmap_hugetlb_syscalls": int(event.get("mmap_hugetlb_syscalls") or 0),
        "mmap_hugetlb_skips": int(event.get("mmap_hugetlb_skips") or 0),
        "last_error_stage": str(event.get("last_error_stage") or "none"),
        "last_error_code": int(event.get("last_error_code") or 0),
        "last_error_name": str(event.get("last_error_name") or "none"),
        "reused_same_ptr": event.get("reused_same_ptr") is True,
        "typed_cache_inserts": int(event.get("typed_cache_inserts") or 0),
        "typed_cache_hits": int(event.get("typed_cache_hits") or 0),
        "side_cache_mapping_size": int(event.get("side_cache_mapping_size") or 0),
        "fallback_alignment": int(event.get("fallback_alignment") or 0),
        # Backward-compatible field: support for the hugepage-sized PAL fallback request.
        # The probe also reports whether the final side-cache mapping remains eligible
        # after compact fallback remapping.
        "aligned_fallback_supported": event.get("aligned_fallback_supported") is True,
        "side_cache_mapping_aligned_fallback_supported": event.get(
            "side_cache_mapping_aligned_fallback_supported"
        ) is True,
        "linux_smaps_mapping_found": event.get("linux_smaps_mapping_found") is True,
        "linux_smaps_kernel_page_kb": int(event.get("linux_smaps_kernel_page_kb") or 0),
        "linux_smaps_mmu_page_kb": int(event.get("linux_smaps_mmu_page_kb") or 0),
        "linux_smaps_anon_huge_kb": int(event.get("linux_smaps_anon_huge_kb") or 0),
        "linux_smaps_thp_eligible": event.get("linux_smaps_thp_eligible"),
        "linux_smaps_vmflags_ht": event.get("linux_smaps_vmflags_ht") is True,
        "linux_smaps_vmflags_hg": event.get("linux_smaps_vmflags_hg") is True,
        "linux_smaps_vmflags_nh": event.get("linux_smaps_vmflags_nh") is True,
        "linux_prefaulted_pages": int(event.get("linux_prefaulted_pages") or 0),
        "exit_code": int(record.get("exit_code") or 0),
    }


def hugepage_metadata_direct_probe_blockers(audit: Dict[str, Any]) -> List[str]:
    """Return fail-closed C005 blockers for the direct hugepage probe."""

    if not isinstance(audit, dict):
        return ["missing direct hugepage metadata allocator/PAL probe audit"]
    summary = audit.get("summary") if isinstance(audit.get("summary"), dict) else {}
    blockers: List[str] = []
    if summary.get("probe_validated") is not True:
        blockers.append("direct hugepage metadata probe did not validate allocator side-cache reuse")
    if summary.get("side_cache_allocated") is not True:
        blockers.append("direct hugepage metadata probe did not allocate the out-of-line side cache")
    if optional_int(summary.get("mmap_attempts")) in (None, 0):
        blockers.append("direct hugepage metadata probe observed no mmap_huge attempts")
    if optional_int(summary.get("typed_cache_inserts")) in (None, 0):
        blockers.append("direct hugepage metadata probe observed no typed-cache inserts")
    if optional_int(summary.get("typed_cache_hits")) in (None, 0):
        blockers.append("direct hugepage metadata probe observed no typed-cache hits")
    if summary.get("hugepage_backed") is not True:
        blockers.append(
            "direct hugepage metadata probe did not observe real hugepage backing: "
            f"backing={summary.get('backing')}, "
            f"mmap_successes={summary.get('mmap_successes')}, "
            f"mmap_fallbacks={summary.get('mmap_fallbacks')}, "
            f"aligned_fallbacks={summary.get('mmap_aligned_fallbacks')}, "
            f"last_error={summary.get('last_error_stage')} "
            f"code={summary.get('last_error_code')} "
            f"name={summary.get('last_error_name')}, "
            "linux_smaps="
            f"found={summary.get('linux_smaps_mapping_found')}, "
            f"kernel_page_kb={summary.get('linux_smaps_kernel_page_kb')}, "
            f"mmu_page_kb={summary.get('linux_smaps_mmu_page_kb')}, "
            f"anon_huge_kb={summary.get('linux_smaps_anon_huge_kb')}, "
            f"vmflags_ht={summary.get('linux_smaps_vmflags_ht')}, "
            f"vmflags_hg={summary.get('linux_smaps_vmflags_hg')}, "
            f"vmflags_nh={summary.get('linux_smaps_vmflags_nh')}, "
            f"prefaulted_pages={summary.get('linux_prefaulted_pages')}"
        )
    return unique_strings(blockers)


def latest_hugepage_metadata_direct_probe_audit() -> Tuple[Optional[Path], Dict[str, Any]]:
    """Return the strongest direct allocator/PAL hugepage metadata probe audit.

    Diagnostic probes may run after a real Linux THP-backed probe on hosts
    where huge pages are unavailable (for example macOS superpage fallbacks).
    Those later fail-closed diagnostics are useful evidence, but they must not
    hide an existing claim-grade allocator/PAL probe from claim-check output.
    Prefer claim-grade, blocker-free hugepage-backed audits first; use mtime as
    the tie-breaker within the same evidence strength.
    """

    candidate_paths: List[Path] = [RESULTS / "hugepage_metadata_direct_probe_audit.json"]
    candidate_paths.extend(RAW.glob("*/hugepage-metadata-direct-probe-audit.json"))
    candidates: List[Tuple[Tuple[int, int, int, int, float, str], Path, Dict[str, Any]]] = []
    seen: Set[str] = set()
    for path in candidate_paths:
        resolved = str(path)
        if resolved in seen:
            continue
        seen.add(resolved)
        try:
            data = read_json(path)
        except (OSError, json.JSONDecodeError):
            continue
        if not isinstance(data, dict):
            continue
        if data.get("source") != HUGEPAGE_METADATA_DIRECT_PROBE_SOURCE:
            continue
        try:
            mtime = path.stat().st_mtime
        except OSError:
            mtime = 0.0
        summary = data.get("summary") if isinstance(data.get("summary"), dict) else {}
        claim_grade_ready = bool(
            summary.get("claim_grade") is True
            and summary.get("hugepage_backed") is True
            and not hugepage_metadata_direct_probe_blockers(data)
        )
        score = (
            1 if claim_grade_ready else 0,
            1 if summary.get("claim_grade") is True else 0,
            1 if summary.get("hugepage_backed") is True else 0,
            1 if summary.get("probe_validated") is True else 0,
            mtime,
            str(path),
        )
        candidates.append((score, path, data))
    if not candidates:
        return None, {}
    candidates.sort(key=lambda item: item[0], reverse=True)
    _score, path, data = candidates[0]
    return path, data


def collect_hugepage_metadata_direct_probe(args: argparse.Namespace) -> int:
    """Run a real allocator/PAL hugepage metadata side-cache probe."""

    run_id = args.run_id or _dt.datetime.now().strftime("hugepage-metadata-direct-probe-%Y%m%d-%H%M%S")
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)
    timeout = max(1, int(getattr(args, "timeout", 120) or 120))
    toolchain = str(getattr(args, "toolchain", "nightly-2022-07-01") or "nightly-2022-07-01")
    features = str(getattr(args, "features", "hugepage,stats") or "hugepage,stats")
    cargo = shutil.which("cargo") or "cargo"
    cmd = [cargo, rust_toolchain_arg(toolchain)]
    cmd.extend(
        [
            "run",
            "-q",
            "-p",
            "unialloc",
            "--example",
            "hugepage_metadata_probe",
            "--features",
            features,
        ]
    )
    cargo_target_dir = out_dir / "cargo-target"
    record = run_platform_command(
        out_dir,
        "hugepage-metadata-direct-probe",
        cmd,
        timeout,
        extra_env={"CARGO_TARGET_DIR": str(cargo_target_dir)},
    )
    cargo_target_cleanup = remove_directory_if_present(cargo_target_dir)
    event = parse_last_json_stdout_event(record) or {}
    if event.get("source") != "hugepage_metadata_probe":
        event = {}
    summary = hugepage_metadata_direct_probe_summary(event, record)
    summary["cargo_target_cleaned"] = bool(cargo_target_cleanup.get("removed"))
    summary["cargo_target_removed_bytes"] = cargo_target_cleanup.get("removed_bytes")
    blockers = hugepage_metadata_direct_probe_blockers(
        {"source": HUGEPAGE_METADATA_DIRECT_PROBE_SOURCE, "summary": summary}
    )
    audit = {
        "schema_version": 1,
        "source": HUGEPAGE_METADATA_DIRECT_PROBE_SOURCE,
        "run_id": run_id,
        "generated_at": now_iso(),
        "features": features,
        "command": record.get("command"),
        "stdout": record.get("stdout"),
        "stderr": record.get("stderr"),
        "cargo_target_dir": str(cargo_target_dir),
        "cargo_target_cleanup": cargo_target_cleanup,
        "event": event,
        "summary": summary,
        "blockers": blockers,
        "claim_grade": summary.get("claim_grade") is True and not blockers,
    }
    audit_path = out_dir / "hugepage-metadata-direct-probe-audit.json"
    write_json(audit_path, audit)
    if not getattr(args, "no_update_results", False):
        write_json(RESULTS / "hugepage_metadata_direct_probe_audit.json", audit)
    print(str(audit_path))
    return 0 if summary.get("probe_validated") is True else 1


SEMANTIC_FALLBACK_ATTRIBUTION_PROBE_SOURCE = "semantic-fallback-attribution-probe"


def semantic_fallback_attribution_probe_summary(
    event: Dict[str, Any], record: Dict[str, Any]
) -> Dict[str, Any]:
    """Normalize the focused allocator fallback-attribution probe output."""

    return {
        "probe_validated": bool(record.get("passed") and event.get("passed") is True),
        "fallback_allocations": int(event.get("fallback_allocations") or 0),
        "fallback_deallocations": int(event.get("fallback_deallocations") or 0),
        "typed_allocations": int(event.get("typed_allocations") or 0),
        "typed_deallocations": int(event.get("typed_deallocations") or 0),
        "raw_alloc_no_metadata": int(event.get("raw_alloc_no_metadata") or 0),
        "raw_alloc_no_metadata_bytes": int(event.get("raw_alloc_no_metadata_bytes") or 0),
        "raw_dealloc_no_metadata": int(event.get("raw_dealloc_no_metadata") or 0),
        "raw_realloc_no_metadata": int(event.get("raw_realloc_no_metadata") or 0),
        "raw_realloc_no_metadata_bytes": int(event.get("raw_realloc_no_metadata_bytes") or 0),
        "raw_realloc_moved_dealloc_no_metadata": int(
            event.get("raw_realloc_moved_dealloc_no_metadata") or 0
        ),
        "realloc_recorded_old_metadata_new_allocations": int(
            event.get("realloc_recorded_old_metadata_new_allocations") or 0
        ),
        "realloc_recorded_old_metadata_new_allocation_bytes": int(
            event.get("realloc_recorded_old_metadata_new_allocation_bytes") or 0
        ),
        "exit_code": int(record.get("exit_code") or 0),
    }


def semantic_fallback_attribution_probe_blockers(audit: Dict[str, Any]) -> List[str]:
    """Return fail-closed blockers for the focused fallback-attribution probe."""

    if not isinstance(audit, dict):
        return ["missing semantic fallback attribution probe audit"]
    summary = audit.get("summary") if isinstance(audit.get("summary"), dict) else {}
    blockers: List[str] = []
    if summary.get("probe_validated") is not True:
        blockers.append("semantic fallback attribution probe did not validate")
    if int(summary.get("fallback_allocations") or 0) < 3:
        blockers.append("probe observed fewer than three fallback allocation events")
    if int(summary.get("fallback_deallocations") or 0) < 3:
        blockers.append("probe observed fewer than three fallback deallocation events")
    if int(summary.get("typed_allocations") or 0) < 1:
        blockers.append("probe did not exercise the recovered old-metadata typed allocation setup")
    if int(summary.get("typed_deallocations") or 0) < 1:
        blockers.append("probe did not exercise typed deallocation of the recovered old object")
    if int(summary.get("raw_alloc_no_metadata") or 0) < 2:
        blockers.append("probe did not attribute raw alloc-without-metadata fallbacks")
    if int(summary.get("raw_dealloc_no_metadata") or 0) < 3:
        blockers.append("probe did not attribute raw dealloc-without-metadata fallbacks")
    if int(summary.get("raw_realloc_no_metadata") or 0) < 1:
        blockers.append("probe did not attribute raw realloc-without-metadata fallbacks")
    if int(summary.get("realloc_recorded_old_metadata_new_allocations") or 0) < 1:
        blockers.append(
            "probe did not attribute reallocations with recovered old metadata but missing new allocation metadata"
        )
    return unique_strings(blockers)


def latest_semantic_fallback_attribution_probe_audit() -> Tuple[Optional[Path], Dict[str, Any]]:
    """Return newest focused semantic fallback-attribution probe audit."""

    candidate_paths: List[Path] = [RESULTS / "semantic_fallback_attribution_probe_audit.json"]
    candidate_paths.extend(RAW.glob("*/semantic-fallback-attribution-probe-audit.json"))
    candidates: List[Tuple[float, str, Path, Dict[str, Any]]] = []
    seen: Set[str] = set()
    for path in candidate_paths:
        resolved = str(path)
        if resolved in seen:
            continue
        seen.add(resolved)
        try:
            data = read_json(path)
        except (OSError, json.JSONDecodeError):
            continue
        if not isinstance(data, dict):
            continue
        if data.get("source") != SEMANTIC_FALLBACK_ATTRIBUTION_PROBE_SOURCE:
            continue
        try:
            mtime = path.stat().st_mtime
        except OSError:
            mtime = 0.0
        candidates.append((mtime, str(path), path, data))
    if not candidates:
        return None, {}
    candidates.sort(key=lambda item: (item[0], item[1]), reverse=True)
    _mtime, _name, path, data = candidates[0]
    return path, data


def collect_semantic_fallback_attribution_probe(args: argparse.Namespace) -> int:
    """Run the real allocator fallback-attribution probe."""

    run_id = args.run_id or _dt.datetime.now().strftime(
        "semantic-fallback-attribution-probe-%Y%m%d-%H%M%S"
    )
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)
    timeout = max(1, int(getattr(args, "timeout", 120) or 120))
    toolchain = str(getattr(args, "toolchain", "nightly-2022-07-01") or "nightly-2022-07-01")
    features = str(getattr(args, "features", "stats") or "stats")
    cargo = shutil.which("cargo") or "cargo"
    cmd = [cargo, rust_toolchain_arg(toolchain)]
    cmd.extend(
        [
            "run",
            "-q",
            "-p",
            "unialloc",
            "--example",
            "semantic_fallback_attribution_probe",
            "--features",
            features,
        ]
    )
    cargo_target_dir = out_dir / "cargo-target"
    record = run_platform_command(
        out_dir,
        "semantic-fallback-attribution-probe",
        cmd,
        timeout,
        extra_env={"CARGO_TARGET_DIR": str(cargo_target_dir)},
    )
    cargo_target_cleaned = False
    if cargo_target_dir.exists():
        shutil.rmtree(cargo_target_dir, ignore_errors=True)
        cargo_target_cleaned = not cargo_target_dir.exists()
    event = parse_last_json_stdout_event(record) or {}
    if event.get("source") != "semantic_fallback_attribution_probe":
        event = {}
    summary = semantic_fallback_attribution_probe_summary(event, record)
    blockers = semantic_fallback_attribution_probe_blockers(
        {"source": SEMANTIC_FALLBACK_ATTRIBUTION_PROBE_SOURCE, "summary": summary}
    )
    audit = {
        "schema_version": 1,
        "source": SEMANTIC_FALLBACK_ATTRIBUTION_PROBE_SOURCE,
        "run_id": run_id,
        "generated_at": now_iso(),
        "features": features,
        "command": record.get("command"),
        "stdout": record.get("stdout"),
        "stderr": record.get("stderr"),
        "cargo_target_dir": str(cargo_target_dir),
        "cargo_target_dir_cleaned": cargo_target_cleaned,
        "event": event,
        "summary": summary,
        "blockers": blockers,
        "claim_grade": summary.get("probe_validated") is True and not blockers,
    }
    audit_path = out_dir / "semantic-fallback-attribution-probe-audit.json"
    write_json(audit_path, audit)
    if not getattr(args, "no_update_results", False):
        write_json(RESULTS / "semantic_fallback_attribution_probe_audit.json", audit)
    print(str(audit_path))
    return 0 if summary.get("probe_validated") is True else 1


