def allocator_footprint_regression_specs(only: Optional[List[str]] = None) -> Tuple[List[Dict[str, Any]], List[str]]:
    """Return selected fast allocator footprint regressions and unknown filters.

    These are real Cargo tests, not mock evidence.  The evaluator keeps them
    separate from the slow paper performance matrix so a status query does not
    unexpectedly compile/run allocator tests, while still giving the footprint
    workstream a single fail-closed gate.
    """

    if not only:
        return [dict(spec) for spec in ALLOCATOR_FOOTPRINT_REGRESSION_SPECS], []
    wanted = {str(item) for item in only}
    selected = [
        dict(spec)
        for spec in ALLOCATOR_FOOTPRINT_REGRESSION_SPECS
        if str(spec.get("id")) in wanted or str(spec.get("test")) in wanted
    ]
    matched = {str(spec.get("id")) for spec in selected}
    matched.update(str(spec.get("test")) for spec in selected)
    unknown = sorted(item for item in wanted if item not in matched)
    return selected, unknown


def allocator_footprint_regression_command(
    spec: Dict[str, Any],
    *,
    cargo: str,
    toolchain: str,
) -> List[str]:
    """Build the Cargo command for one focused allocator-footprint regression."""

    cmd = [cargo]
    clean_toolchain = str(toolchain or "").strip()
    if clean_toolchain:
        cmd.append(rust_toolchain_arg(clean_toolchain))
    cmd.extend(["test", "-p", "unialloc", "--lib", str(spec["test"])])
    features = str(spec.get("features") or "").strip()
    if features:
        cmd.extend(["--features", features])
    if spec.get("no_default_features", True):
        cmd.append("--no-default-features")
    cmd.append("--")
    cmd.extend(str(arg) for arg in spec.get("test_args") or ["--format", "terse"])
    return cmd


def allocator_footprint_regression_blockers(audit: Dict[str, Any]) -> List[str]:
    """Return fail-closed blockers from a focused allocator-footprint gate audit."""

    blockers: List[str] = []
    if not isinstance(audit, dict):
        return ["missing allocator footprint regression gate audit"]
    blockers.extend(str(item) for item in audit.get("configuration_blockers") or [])
    for result in audit.get("results") or []:
        if not isinstance(result, dict):
            blockers.append("malformed allocator footprint regression result")
            continue
        if result.get("passed") is True:
            continue
        detail = f"{result.get('id') or result.get('test') or 'unknown'} failed"
        if result.get("timed_out"):
            detail += " by timeout"
        exit_code = result.get("exit_code")
        if exit_code is not None:
            detail += f" with exit_code={exit_code}"
        stderr_tail = str(result.get("stderr_tail") or "").strip()
        if stderr_tail:
            detail += f": {stderr_tail[-300:]}"
        blockers.append(detail)
    if int((audit.get("summary") or {}).get("selected_count") or 0) == 0:
        blockers.append("no allocator footprint regressions were selected")
    return unique_strings(blockers)


def audit_allocator_footprint_regressions(args: argparse.Namespace) -> int:
    """Run fast real allocator footprint/fragmentation regressions and write an audit."""

    run_id = args.run_id or _dt.datetime.now().strftime(
        "allocator-footprint-regressions-%Y%m%d-%H%M%S"
    )
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)
    selected, unknown = allocator_footprint_regression_specs(getattr(args, "only", None))
    timeout = max(1, int(getattr(args, "timeout", 180) or 180))
    cargo = shutil.which("cargo") or ""
    toolchain = str(getattr(args, "toolchain", "") or "")
    results: List[Dict[str, Any]] = []
    configuration_blockers: List[str] = []
    if unknown:
        configuration_blockers.append("unknown allocator footprint regression selector(s): " + ", ".join(unknown))
    if not cargo:
        configuration_blockers.append("cargo not found")

    if cargo and not configuration_blockers:
        for spec in selected:
            command = allocator_footprint_regression_command(spec, cargo=cargo, toolchain=toolchain)
            label = re.sub(r"[^A-Za-z0-9_.-]+", "-", str(spec["id"])).strip("-")
            record = run_platform_command(
                out_dir,
                label,
                command,
                timeout,
                extra_env={"CARGO_INCREMENTAL": "0"},
            )
            stdout_tail = ""
            stderr_tail = ""
            for key, target in (("stdout", "stdout_tail"), ("stderr", "stderr_tail")):
                path_text = str(record.get(key) or "")
                path = Path(path_text) if path_text else None
                if path is not None and path.exists():
                    text = path.read_text(encoding="utf-8", errors="replace")
                    if target == "stdout_tail":
                        stdout_tail = text[-2000:]
                    else:
                        stderr_tail = text[-4000:]
            results.append(
                {
                    "id": spec.get("id"),
                    "test": spec.get("test"),
                    "category": spec.get("category"),
                    "why": spec.get("why"),
                    "command": command,
                    "features": spec.get("features") or "",
                    "no_default_features": spec.get("no_default_features", True),
                    "test_args": spec.get("test_args") or [],
                    "exit_code": record.get("exit_code"),
                    "passed": record.get("passed") is True,
                    "timed_out": record.get("exit_code") == 124,
                    "wall_seconds": record.get("wall_seconds"),
                    "stdout": record.get("stdout"),
                    "stderr": record.get("stderr"),
                    "stdout_tail": stdout_tail,
                    "stderr_tail": stderr_tail,
                }
            )

    summary = {
        "selected_count": len(selected),
        "passed_count": sum(1 for result in results if result.get("passed") is True),
        "failed_count": sum(1 for result in results if result.get("passed") is not True),
        "configuration_blocker_count": len(configuration_blockers),
        "timed_out_count": sum(1 for result in results if result.get("timed_out") is True),
        "slow_benchmark_matrix_run": False,
        "extra_cargo_target_dir_created": False,
    }
    audit = {
        "schema_version": 1,
        "source": ALLOCATOR_FOOTPRINT_REGRESSION_SOURCE,
        "run_id": run_id,
        "generated_at": now_iso(),
        "host": host_metadata(),
        "toolchain": toolchain or None,
        "timeout_seconds_per_test": timeout,
        "configuration_blockers": configuration_blockers,
        "results": results,
        "summary": summary,
    }
    blockers = allocator_footprint_regression_blockers(audit)
    audit["blockers"] = blockers
    audit["passed"] = not blockers
    audit_path = out_dir / "allocator-footprint-regression-gate-audit.json"
    write_json(audit_path, audit)
    if not getattr(args, "no_update_results", False):
        write_json(RESULTS / "allocator_footprint_regression_gate_audit.json", audit)
    print(str(audit_path))
    return 0 if audit["passed"] else 1


def hugepage_mmap_claim_blockers(features: Any, event_stats: Dict[str, Any]) -> List[str]:
    stats = hugepage_mmap_stats_from_coverage_stats(event_stats)
    side_cache = hugepage_metadata_side_cache_probe_from_coverage_stats(event_stats)
    real_hugepage_observed = bool(
        stats["successes"] > 0
        or side_cache.get("hugepage_backed")
        or side_cache.get("linux_smaps_hugepage_backed")
    )
    blockers: List[str] = []
    if not features_include(features, "hugepage"):
        blockers.append("hugepage feature was not enabled for this run")
    if stats["event_count"] <= 0:
        blockers.append("runtime did not emit hugepage_mmap_stats")
    if stats["attempts"] <= 0:
        blockers.append("no hugepage mmap attempts were observed")
    if not real_hugepage_observed:
        if stats["fallbacks"] > 0:
            fallback_kind = (
                "2MiB-aligned ordinary mmap"
                if stats.get("aligned_fallbacks", 0) > 0
                else "ordinary mmap"
            )
            smaps_detail = ""
            if side_cache.get("linux_smaps_attempted"):
                smaps_detail = (
                    "; linux smaps: "
                    f"found={bool(side_cache.get('linux_smaps_found'))}, "
                    f"kernel_page_size_kb={side_cache.get('linux_smaps_kernel_page_size_kb')}, "
                    f"mmu_page_size_kb={side_cache.get('linux_smaps_mmu_page_size_kb')}, "
                    f"anon_huge_pages_kb={side_cache.get('linux_smaps_anon_huge_pages_kb')}, "
                    f"vmflags_ht={side_cache.get('linux_smaps_vmflags_ht')}, "
                    f"vmflags_hg={side_cache.get('linux_smaps_vmflags_hg')}"
                )
            platform_stage = str(stats.get("platform_error_stage") or "none")
            platform_code = int(stats.get("platform_error_code") or 0)
            platform_name = str(
                stats.get("platform_error_name")
                or hugepage_platform_error_name(platform_stage, platform_code)
            )
            platform_detail = (
                f"; last primary hugepage failure: {platform_stage} "
                f"code={platform_code} name={platform_name}"
                if platform_stage and platform_stage != "none"
                else ""
            )
            blockers.append(
                f"hugepage mmap attempts fell back to {fallback_kind}{platform_detail}{smaps_detail}"
            )
        else:
            blockers.append("no successful hugepage mmap was observed")
    return unique_strings(blockers)


def append_jsonl(path: Path, record: Dict[str, Any]) -> None:
    with path.open("a", encoding="utf-8") as f:
        json.dump(record, f, sort_keys=True)
        f.write("\n")


def feature_flags(feature: str) -> set[str]:
    return {part.strip() for part in str(feature).split(",") if part.strip()}


def local_run_scope(
    records: List[Dict[str, Any]],
    run_dir: Path,
    *,
    kind: str = "local-std-bench-libtest",
    variant_feature: Optional[str] = None,
    comparison_feature: Optional[str] = None,
) -> Dict[str, Any]:
    bench_filters = sorted({str(r.get("bench_filter")) for r in records if r.get("bench_filter")})
    observed_features = sorted({str(r.get("feature")) for r in records if r.get("feature")})
    runs_per_feature = {
        feature: max([r.get("run_index", 0) for r in records if r.get("feature") == feature] or [0])
        for feature in observed_features
    }
    scope = {
        "kind": kind,
        "run_dir": str(run_dir),
        "bench_filters": bench_filters,
        "observed_features": observed_features,
        "runs_per_feature": runs_per_feature,
        "complete_for_claim": False,
        "limitations": [
            "Local std_bench per-benchmark data is useful regression evidence.",
            "It does not include the paper's full Linux macro/web benchmark suite.",
            "Filtered or short runs are smoke tests and cannot satisfy overclaim gates.",
        ],
    }
    if variant_feature:
        scope.update(
            {
                "variant_feature": variant_feature,
                "comparison_feature": comparison_feature,
                "baseline_feature": "bench_ourself",
                "ratio_meaning": (
                    "baseline allocator ns_per_iter / variant UniAlloc ns_per_iter; "
                    "values greater than 1 mean the local variant was faster than that baseline allocator"
                ),
            }
        )
        scope["limitations"].append(
            "Variant smoke ratios compare local feature toggles only and are not paper claim-grade datasets."
        )
    return scope


def select_variant_feature(benchmark_summaries: Dict[str, Any], variant_feature: str) -> Optional[str]:
    candidates: List[Tuple[int, str]] = []
    for feature in benchmark_summaries:
        flags = feature_flags(feature)
        if "bench_ourself" in flags and variant_feature in flags:
            candidates.append((len(flags), feature))
    if not candidates:
        return None
    # Prefer the narrowest feature combination so one variant dataset reflects
    # one paper claim knob whenever both exact and combined feature runs exist.
    return sorted(candidates)[0][1]


def paper_dataset_candidates(data_dir: Path, rel: str) -> List[Path]:
    """Return accepted locations for a paper-shaped dataset in a data dir."""

    return [data_dir / rel, data_dir / Path(rel).name]


def merge_current_datasets(args: argparse.Namespace) -> int:
    """Merge multiple current .dat import directories into one reproducible import.

    This replaces the previous manual pattern of copying selected .dat files into
    a synthetic directory.  Later sources win by default so a more complete
    local/external import can override an older smoke export while preserving the
    original source manifest as an evidence root.
    """

    cfg = load_config()
    raw_sources = [Path(value).expanduser() for value in args.data_dir]
    if not raw_sources:
        print("at least one --data-dir is required", file=sys.stderr)
        return 2

    sources: List[Dict[str, Any]] = []
    for source in raw_sources:
        data_dir = source / "data" if (source / "data").is_dir() else source
        if not data_dir.exists():
            print(f"data dir not found: {source}", file=sys.stderr)
            return 2
        manifest, manifest_path = load_dataset_manifest(data_dir, None)
        sources.append(
            {
                "data_dir": data_dir,
                "manifest": manifest or {},
                "manifest_path": manifest_path,
            }
        )

    run_id = args.run_id or _dt.datetime.now().strftime("current-datasets-merged-%Y%m%d-%H%M%S")
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id / "data"
    out_dir.mkdir(parents=True, exist_ok=True)

    selected: Dict[str, Dict[str, Any]] = {}
    for source in sources:
        data_dir = source["data_dir"]
        manifest = source["manifest"]
        manifest_path = source["manifest_path"]
        manifest_datasets = manifest.get("datasets", {}) if isinstance(manifest, dict) else {}
        for dataset_name, rel in cfg["paper_data"].items():
            if args.dataset and dataset_name not in args.dataset:
                continue
            if args.prefer == "first" and dataset_name in selected:
                continue
            path = next((candidate for candidate in paper_dataset_candidates(data_dir, rel) if candidate.exists()), None)
            if path is None:
                continue
            selected[dataset_name] = {
                "data_dir": data_dir,
                "path": path,
                "rel": rel,
                "manifest": manifest,
                "manifest_path": manifest_path,
                "manifest_entry": dict(manifest_datasets.get(dataset_name, {})),
            }

    manifest: Dict[str, Any] = {
        "schema_version": 1,
        "generated_at": now_iso(),
        "source": "merge-current-datasets",
        "paper_shape": True,
        "claim_grade": False,
        "complete_for_claim": False,
        "host": host_metadata(),
        "input_data_dirs": [str(source["data_dir"]) for source in sources],
        "merge_policy": f"prefer-{args.prefer}",
        "merge_sources": {},
        "datasets": {},
        "limitations": [
            "Merged current datasets are only as strong as their source manifests and raw evidence.",
            "The merge command preserves provenance roots but never upgrades smoke or partial data to claim-grade evidence.",
        ],
    }
    merged_source_fingerprint = shared_evidence_source_fingerprint(
        source["manifest"] for source in sources
    )
    if merged_source_fingerprint is not None:
        manifest["evidence_source_fingerprint"] = merged_source_fingerprint
    else:
        manifest["limitations"].append(
            "Input manifests do not share one evidence source fingerprint; the merged output remains non-claim-grade."
        )
    written: Dict[str, str] = {}
    missing: List[str] = []
    current_source_fingerprint = repository_source_fingerprint()
    for dataset_name, rel in cfg["paper_data"].items():
        if args.dataset and dataset_name not in args.dataset:
            continue
        selected_entry = selected.get(dataset_name)
        if not selected_entry:
            missing.append(dataset_name)
            continue
        src_path = selected_entry["path"]
        target = out_dir / Path(rel).name
        shutil.copyfile(src_path, target)
        written[dataset_name] = str(target)

        source_manifest_path = selected_entry.get("manifest_path")
        if source_manifest_path:
            manifest["merge_sources"][dataset_name] = str(source_manifest_path)

        source_manifest = selected_entry["manifest"] if isinstance(selected_entry.get("manifest"), dict) else {}
        source_entry = selected_entry["manifest_entry"] if isinstance(selected_entry.get("manifest_entry"), dict) else {}
        source_data_dir = Path(selected_entry["data_dir"])
        source_roots = dataset_manifest_evidence_roots(
            source_data_dir,
            source_manifest_path,
            source_manifest,
            dataset_name,
            source_entry,
        )
        source_manifest_evidence = sample_evidence_entries(
            {"evidence": source_entry.get("evidence", [])}
        )
        source_evidence_entries = sample_evidence_entries(
            {
                "evidence": [
                    {
                        "path": str(src_path.resolve()),
                        "sha256": normalize_sha256_digest(source_entry.get("sha256")),
                        "kind": "dataset",
                    },
                    *source_manifest_evidence,
                ]
            }
        )
        (
            source_evidence_ok,
            _source_verified_evidence,
            source_missing_evidence,
            source_missing_hashes,
            source_hash_mismatches,
        ) = verify_evidence_entries_with_roots(source_evidence_entries, source_roots)
        source_dataset_aliases = {src_path.name, str(src_path), str(src_path.resolve())}
        if not any(
            evidence_entry_path(item) not in source_dataset_aliases
            for item in source_manifest_evidence
        ):
            source_evidence_ok = False
            source_missing_evidence = unique_strings(
                [*source_missing_evidence, "<dataset provenance evidence>"]
            )
        source_binding_blockers = repository_source_binding_blockers(
            source_manifest,
            current=current_source_fingerprint,
        )
        merged_entry = dict(source_entry)
        merged_entry["path"] = target.name
        merged_entry.setdefault("rows", len(parse_dat(target).get("rows", [])))
        merged_entry.setdefault("columns", parse_dat(target).get("columns", []))
        merged_entry["claim_grade"] = bool(
            source_entry.get("claim_grade")
            and source_manifest.get("claim_grade")
            and source_evidence_ok
            and not source_binding_blockers
        )
        merged_entry["complete_for_claim"] = bool(
            source_entry.get("complete_for_claim")
            and source_manifest.get("complete_for_claim")
            and source_evidence_ok
            and not source_binding_blockers
        )
        merged_entry["sha256"] = file_sha256(target)
        source_evidence = sample_evidence_entries(
            {"evidence": source_entry.get("evidence", [])}
        )
        merged_entry["evidence"] = sample_evidence_entries(
            {
                "evidence": [
                    {
                        "path": target.name,
                        "sha256": merged_entry["sha256"],
                        "kind": "dataset",
                    },
                    *source_evidence,
                ]
            }
        )
        scope = dict(source_entry.get("scope", {})) if isinstance(source_entry.get("scope"), dict) else {}
        scope.update(
            {
                "merged_from": str(src_path),
                "merged_source_manifest": str(source_manifest_path) if source_manifest_path else None,
                "merged_source_dataset_sha256": normalize_sha256_digest(
                    source_entry.get("sha256")
                ),
                "merged_source_evidence_verified": source_evidence_ok,
            }
        )
        merged_entry["scope"] = scope
        blockers = list(source_entry.get("claim_grade_blockers", []))
        if not merged_entry["claim_grade"] or not merged_entry["complete_for_claim"]:
            blockers.append("merged current dataset source is not claim-grade/complete_for_claim")
        blockers.extend(
            f"merged source evidence missing: {item}"
            for item in source_missing_evidence
        )
        blockers.extend(
            f"merged source evidence missing sha256: {item}"
            for item in source_missing_hashes
        )
        blockers.extend(
            f"merged source evidence sha256 mismatch: {item}"
            for item in source_hash_mismatches
        )
        blockers.extend(
            f"merged source evidence binding: {item}"
            for item in source_binding_blockers
        )
        merged_entry["claim_grade_blockers"] = unique_strings(blockers)
        manifest["datasets"][dataset_name] = merged_entry

    if not written:
        print("no paper-shaped datasets found in supplied sources", file=sys.stderr)
        return 1

    manifest_path = out_dir / "dataset-manifest.json"
    write_json(manifest_path, manifest)
    summary = {
        "schema_version": 1,
        "generated_at": now_iso(),
        "data_dir": str(out_dir),
        "manifest": str(manifest_path),
        "datasets": written,
        "missing": missing,
        "input_data_dirs": manifest["input_data_dirs"],
        "merge_policy": manifest["merge_policy"],
    }
    write_json(out_dir / "merge-summary.json", summary)
    exit_code = 0 if not missing else 1
    if args.import_results:
        import_status = import_current_datasets(
            argparse.Namespace(
                data_dir=str(out_dir),
                manifest=str(manifest_path),
                dataset=args.dataset,
                quiet=True,
            )
        )
        summary["import_results"] = {
            "requested": True,
            "status": import_status,
            "summary_path": str(RESULTS / "current_datasets_summary.json"),
        }
        if import_status != 0:
            exit_code = import_status
    else:
        summary["import_results"] = {"requested": False}
    write_json(out_dir / "merge-summary.json", summary)
    print(json.dumps(summary, indent=2, sort_keys=True))
    return exit_code



def import_current_datasets(args: argparse.Namespace) -> int:
    """Import current-run datasets that use the same .dat shape as the paper."""
    cfg = load_config()
    data_dir = Path(args.data_dir).expanduser()
    if not data_dir.exists():
        print(f"data dir not found: {data_dir}", file=sys.stderr)
        return 2
    manifest, manifest_path = load_dataset_manifest(data_dir, getattr(args, "manifest", None))
    manifest_datasets = (manifest or {}).get("datasets", {})
    manifest_source_binding_blockers = repository_source_binding_blockers(
        manifest or {},
        current=repository_source_fingerprint(),
    )
    selected_datasets = set(getattr(args, "dataset", None) or [])
    datasets: Dict[str, Any] = {}
    missing: List[str] = []
    for name, rel in cfg["paper_data"].items():
        if selected_datasets and name not in selected_datasets:
            continue
        candidates = paper_dataset_candidates(data_dir, rel)
        path = next((c for c in candidates if c.exists()), None)
        if path:
            current_ds = parse_dat(path)
            reference_ds = None
            ref_path = Path(cfg.get("paper_dir_default", "")).expanduser() / rel
            if ref_path.exists():
                reference_ds = parse_dat(ref_path)
            shape_complete = dataset_covers_reference(current_ds, reference_ds)
            manifest_entry = manifest_datasets.get(name, {})
            manifest_claim_grade = bool(
                manifest_entry.get("complete_for_claim") or manifest_entry.get("claim_grade")
            )
            dataset_sha256 = normalize_sha256_digest(manifest_entry.get("sha256"))
            manifest_evidence = sample_evidence_entries(
                {"evidence": manifest_entry.get("evidence", [])}
            )
            evidence_entries = sample_evidence_entries(
                {
                    "evidence": [
                        {
                            "path": str(path.resolve()),
                            "sha256": dataset_sha256,
                            "kind": "dataset",
                        },
                        *manifest_evidence,
                    ]
                }
            )
            evidence = [evidence_entry_path(item) for item in evidence_entries]
            if manifest_path:
                evidence.append(str(manifest_path.resolve()))
            evidence_roots = dataset_manifest_evidence_roots(
                data_dir,
                manifest_path,
                manifest,
                name,
                manifest_entry,
            )
            (
                evidence_ok,
                verified,
                missing_manifest_evidence,
                missing_manifest_hashes,
                mismatched_manifest_hashes,
            ) = verify_evidence_entries_with_roots(
                evidence_entries,
                evidence_roots,
            )
            dataset_path_aliases = {
                path.name,
                str(path),
                str(path.resolve()),
            }
            provenance_entries = [
                item
                for item in manifest_evidence
                if evidence_entry_path(item) not in dataset_path_aliases
            ]
            if not provenance_entries:
                evidence_ok = False
                missing_manifest_evidence = unique_strings(
                    [*missing_manifest_evidence, "<dataset provenance evidence>"]
                )
            complete_for_claim = (
                shape_complete
                and manifest_claim_grade
                and evidence_ok
                and not manifest_source_binding_blockers
            )
            gaps = dataset_reference_gaps(current_ds, reference_ds)
            blockers: List[str] = []
            if not reference_ds:
                blockers.append("paper reference dataset missing; cannot prove row/column coverage")
            if gaps["missing_reference_rows"]:
                blockers.append(
                    "missing reference rows: " + ", ".join(gaps["missing_reference_rows"])
                )
            if gaps["missing_reference_columns"]:
                blockers.append(
                    "missing reference columns: " + ", ".join(gaps["missing_reference_columns"])
                )
            if gaps.get("missing_reference_cells"):
                blockers.append(
                    "missing finite reference cells: " + ", ".join(gaps["missing_reference_cells"])
                )
            if not manifest_claim_grade:
                blockers.append(
                    "dataset manifest does not mark this dataset complete_for_claim/claim_grade"
                )
            if not evidence_ok:
                details = [
                    *(f"missing {item}" for item in missing_manifest_evidence),
                    *(f"missing sha256 {item}" for item in missing_manifest_hashes),
                    *(f"sha256 mismatch {item}" for item in mismatched_manifest_hashes),
                ]
                blockers.append(
                    "dataset provenance evidence is missing or unverifiable: "
                    + ", ".join(details)
                )
            blockers.extend(
                f"dataset manifest evidence source binding: {blocker}"
                for blocker in manifest_source_binding_blockers
            )
            current_ds["claim_grade"] = complete_for_claim
            current_ds["scope"] = {
                "kind": "paper-shaped-current-import",
                "source": str(path),
                "reference": str(ref_path) if ref_path.exists() else None,
                "manifest": str(manifest_path) if manifest_path else None,
                "complete_for_claim": complete_for_claim,
                "shape_complete": shape_complete,
                "manifest_claim_grade": manifest_claim_grade,
                "evidence_verified": evidence_ok,
                "evidence_source_binding_ready": not manifest_source_binding_blockers,
                "evidence_roots": [str(root) for root in evidence_roots],
                "verified_evidence": verified,
                "missing_evidence": missing_manifest_evidence,
                "missing_evidence_sha256": missing_manifest_hashes,
                "mismatched_evidence_sha256": mismatched_manifest_hashes,
                "claim_grade_blockers": unique_strings(blockers),
                "current_rows": len(current_ds.get("rows", [])),
                "reference_rows": len(reference_ds.get("rows", [])) if reference_ds else None,
                "current_columns": current_ds.get("columns", []),
                "reference_columns": reference_ds.get("columns", []) if reference_ds else None,
                **gaps,
            }
            datasets[name] = current_ds
        else:
            missing.append(str(candidates[-1]))
    summary = {
        "schema_version": 1,
        "generated_at": now_iso(),
        "source": "current",
        "data_dir": str(data_dir),
        "manifest": str(manifest_path) if manifest_path else None,
        "datasets": datasets,
        "missing": missing,
        "notes": [
            "Current datasets are repository evidence only when raw provenance is recorded and verified.",
            "Paper-shaped row/column coverage is necessary but not sufficient for claim-grade import; the manifest must also mark the dataset complete_for_claim/claim_grade.",
        ],
    }
    manifest_source_fingerprint = (
        manifest.get("evidence_source_fingerprint")
        if isinstance(manifest, dict)
        else None
    )
    if isinstance(manifest_source_fingerprint, dict):
        summary["evidence_source_fingerprint"] = copy.deepcopy(
            manifest_source_fingerprint
        )
    out = RESULTS / "current_datasets_summary.json"
    write_json(out, summary)
    write_markdown_report(REPORTS / "current_datasets_summary.md", summary, source="current-datasets")
    if not getattr(args, "quiet", False):
        print(str(out))
    return 0 if not missing else 1


def dataset_covers_reference(current_ds: Dict[str, Any], reference_ds: Optional[Dict[str, Any]]) -> bool:
    if not reference_ds:
        return False
    gaps = dataset_reference_gaps(current_ds, reference_ds)
    return (
        not gaps["missing_reference_rows"]
        and not gaps["missing_reference_columns"]
        and not gaps["missing_reference_cells"]
    )


def unique_strings(items: Iterable[Any]) -> List[str]:
    seen = set()
    values = []
    for item in items:
        if item is None:
            continue
        value = str(item).strip()
        if not value or value in seen:
            continue
        seen.add(value)
        values.append(value)
    return values


def infer_coverage_type_id_basis(
    *,
    claim_grade: bool,
    scope_kind: str,
    event_sources: List[str],
    event_type_id_bases: List[str],
    explicit_basis: Optional[str],
) -> str:
    if explicit_basis:
        return explicit_basis
    if event_type_id_bases:
        if len(event_type_id_bases) == 1:
            return event_type_id_bases[0]
        return "mixed:" + ",".join(event_type_id_bases)
    if claim_grade:
        return "compiler-assigned-type-id"

    sources = set(event_sources)
    scope = scope_kind or ""
    if "std_bench_auto_metadata" in sources or "layout-auto" in scope:
        return "layout-derived-size-align"
    if "std_bench_compiler_proto" in sources or "compiler-prototype" in scope:
        return "source-to-source-prototype-bench-scope-id"
    if "compiler_abi_coverage_example" in sources or "compiler-abi" in scope:
        return "ffi-abi-proxy-rust-type-id"
    if (
        "semantic_std_bench" in sources
        or "scoped_std_coverage_example" in sources
        or "semantic-std" in scope
        or "scoped-metadata" in scope
    ):
        return "source-scoped-rust-type-id"
    if "semantic_coverage_example" in sources or "semantic-coverage-example" in scope:
        return "manual-semantic-api-type-id"
    return "manual-or-smoke-type-id"


def coverage_claim_grade_blockers(
    *,
    claim_grade: bool,
    type_id_basis: str,
    explicit_blockers: Iterable[str],
) -> List[str]:
    if claim_grade:
        return []

    basis = type_id_basis.lower()
    blockers: List[str] = []
    if "layout-derived" in basis:
        blockers.extend(
            [
                "type IDs are derived from allocation size/alignment, not from Rust semantic types",
                "no rustc/LLVM instrumentation pass evidence rewrites the full benchmark suite",
            ]
        )
    elif "source-inferred-rust-type" in basis:
        blockers.extend(
            [
                "type IDs come from source-to-source inferred Rust collection types, not compiler allocation-site object types",
                "the source-to-source generator is an evaluation prototype, not a rustc/LLVM/MIR pass",
                "without-source-changes paper coverage still requires compiler-pass evidence over the full benchmark suite",
            ]
        )
    elif "source-to-source-prototype" in basis:
        blockers.extend(
            [
                "type IDs come from generated benchmark-scope labels, not compiler-assigned Rust allocation object types",
                "the source-to-source generator is an evaluation prototype, not a rustc/LLVM/MIR pass",
                "without-source-changes paper coverage still requires compiler-pass evidence over the full benchmark suite",
            ]
        )
    elif "source-scoped" in basis:
        blockers.extend(
            [
                "type IDs come from source-scoped runtime wrappers, not an automatic compiler pass",
                "the scoped workload is not the full standard alloc benchmark suite without source changes",
            ]
        )
    elif "ffi-abi" in basis:
        blockers.extend(
            [
                "type IDs come from a proxy C ABI harness, not compiler-rewritten Rust allocation sites",
                "the proxy patterns are not the complete paper benchmark suite",
            ]
        )
    elif "manual-semantic" in basis:
        blockers.extend(
            [
                "type IDs come from manual SemanticAlloc/API calls",
                "manual coverage smoke tests cannot prove without-source-changes compiler coverage",
            ]
        )
    else:
        blockers.append("coverage provenance is not a full paper-equivalent compiler-instrumented run")

    blockers.append("coverage import was not marked --claim-grade")
    blockers.extend(str(item) for item in explicit_blockers if str(item).strip())
    return unique_strings(blockers)


