def coverage_claim_threshold() -> float:
    config = load_config()
    for claim in config.get("claims", []):
        if claim.get("id") == "C002-type-coverage":
            threshold = claim.get("threshold", {})
            if isinstance(threshold, dict) and threshold.get("gte") is not None:
                return float(threshold["gte"])
            if claim.get("expected") is not None:
                return float(claim["expected"])
    return 72.17


def parse_json_int(value: Any) -> Optional[int]:
    """Parse JSON scalar integers used by evaluator artifacts.

    Runtime events and rustc-derived type maps occasionally carry ids as
    strings (including base-prefixed forms).  Centralizing the conversion keeps
    evidence parsers fail-clean: malformed optional ids become zero/absent,
    while required counters can raise a targeted parse error instead of an
    incidental Python traceback.
    """

    if value is None:
        return None
    try:
        return int(str(value).strip(), 0)
    except (TypeError, ValueError):
        return None


def parse_json_int_or_zero(value: Any) -> int:
    parsed = parse_json_int(value)
    return parsed if parsed is not None else 0


def percent_or_none(numerator: int, denominator: int) -> Optional[float]:
    if denominator <= 0:
        return None
    return numerator * 100.0 / denominator


def type_id_callsite_pair_from_mapping_row(row: Dict[str, Any]) -> Optional[Tuple[int, int]]:
    type_id, _ = find_mapping_field(row, TYPE_MAPPING_TYPE_ID_KEYS)
    callsite, _ = find_mapping_field(row, TYPE_MAPPING_CALLSITE_KEYS)
    parsed_type_id = parse_json_int_or_zero(type_id)
    parsed_callsite = parse_json_int_or_zero(callsite)
    if parsed_type_id > 0 and parsed_callsite:
        return parsed_type_id, parsed_callsite
    return None


def type_id_callsite_pair_from_event(event: Dict[str, Any]) -> Optional[Tuple[int, int]]:
    parsed_type_id = parse_json_int_or_zero(event.get("type_id"))
    parsed_callsite = parse_json_int_or_zero(event.get("callsite"))
    if parsed_type_id > 0 and parsed_callsite:
        return parsed_type_id, parsed_callsite
    return None


