def coverage_manifest_value(manifest: Dict[str, Any], field: str) -> Any:
    if manifest.get(field) not in (None, "", [], {}):
        return manifest.get(field)
    metadata = manifest.get("metadata")
    if isinstance(metadata, dict) and metadata.get(field) not in (None, "", [], {}):
        return metadata.get(field)
    return None


def coverage_manifest_truthy(manifest: Dict[str, Any], *fields: str) -> bool:
    for field in fields:
        value = coverage_manifest_value(manifest, field)
        if value is True:
            return True
        if isinstance(value, str) and value.strip().lower() in {"true", "yes", "1", "claim-grade"}:
            return True
    return False


def coverage_basis_is_compiler_assigned(type_id_basis: str) -> bool:
    basis = str(type_id_basis or "").lower()
    if not basis:
        return False
    if any(marker in basis for marker in COMPILER_COVERAGE_PROTOTYPE_MARKERS):
        return False
    return "compiler" in basis and ("assign" in basis or "allocation-site" in basis)


def coverage_basis_is_runtime_bridge(type_id_basis: str) -> bool:
    basis = str(type_id_basis or "").lower()
    return any(
        marker in basis
        for marker in (
            "cyclic-replay",
            "cyclic replay",
            "consuming-stream",
            "consuming stream",
            "replay",
            "bridge",
            "finite-stream",
            "finite stream",
        )
    )


def coverage_stream_mode_is_exact_dynamic(mode: str) -> bool:
    text = str(mode or "").strip().lower()
    return text in {
        "exact-dynamic",
        "exact_dynamic",
        "compiler-emitted-dynamic",
        "compiler_emitted_dynamic",
        "per-allocation-site",
        "per_allocation_site",
        "rustc-driver-mir-semantic-scope",
    }


def effective_event_type_id_bases(
    *,
    event_stats: Dict[str, Any],
    scope_kind: str = "",
) -> List[str]:
    explicit_bases = unique_strings(event_stats.get("event_type_id_bases", []))
    if explicit_bases:
        return explicit_bases
    inferred = infer_coverage_type_id_basis(
        claim_grade=False,
        scope_kind=scope_kind,
        event_sources=unique_strings(event_stats.get("event_sources", [])),
        event_type_id_bases=[],
        explicit_basis=None,
    )
    return unique_strings([inferred])


def audit_compiler_runtime_event_basis(
    manifest: Dict[str, Any],
    event_stats: Dict[str, Any],
    manifest_type_id_basis: str,
) -> Dict[str, Any]:
    event_sources = unique_strings(event_stats.get("event_sources", []))
    explicit_bases = unique_strings(event_stats.get("event_type_id_bases", []))
    explicit_typed_bases = unique_strings(event_stats.get("typed_event_type_id_bases", []))
    fallback_bases = unique_strings(event_stats.get("fallback_event_type_id_bases", []))
    scope_kind = str(coverage_manifest_value(manifest, "scope_kind") or manifest.get("source") or "")
    effective_bases = explicit_typed_bases or effective_event_type_id_bases(event_stats=event_stats, scope_kind=scope_kind)
    compiler_site_replay_events = int(event_stats.get("compiler_site_replay_events") or 0)
    compiler_site_lowered_events = int(event_stats.get("compiler_site_lowered_events") or 0)
    compiler_site_id_stream_modes = unique_strings(event_stats.get("compiler_site_id_stream_modes", []))
    typed_compiler_site_id_stream_modes = (
        unique_strings(event_stats.get("typed_compiler_site_id_stream_modes", [])) or compiler_site_id_stream_modes
    )
    fallback_compiler_site_id_stream_modes = unique_strings(event_stats.get("fallback_compiler_site_id_stream_modes", []))
    non_compiler_bases = [
        basis for basis in effective_bases if not coverage_basis_is_compiler_assigned(str(basis or ""))
    ]
    compiler_bases = [
        basis for basis in effective_bases if coverage_basis_is_compiler_assigned(str(basis or ""))
    ]
    bridge_bases = [
        basis for basis in effective_bases if coverage_basis_is_runtime_bridge(str(basis or ""))
    ]
    non_exact_stream_modes = [
        mode for mode in typed_compiler_site_id_stream_modes if not coverage_stream_mode_is_exact_dynamic(str(mode or ""))
    ]
    non_compiler_event_sources = [
        source
        for source in event_sources
        if source
        in {
            "std_bench_auto_metadata",
            "std_bench_compiler_proto",
            "compiler_abi_coverage_example",
            "semantic_std_bench",
            "scoped_std_coverage_example",
            "semantic_coverage_example",
        }
        and not (
            source == "std_bench_auto_metadata"
            and compiler_site_replay_events > 0
            and compiler_bases
        )
        and not (
            source == "std_bench_auto_metadata"
            and compiler_site_lowered_events > 0
            and compiler_bases
        )
    ]
    strict_compiler_runtime_required = (
        coverage_manifest_truthy(manifest, "claim_grade", "complete_for_claim")
        or coverage_basis_is_compiler_assigned(manifest_type_id_basis)
    )
    blockers: List[str] = []
    if strict_compiler_runtime_required:
        if not explicit_typed_bases and not explicit_bases:
            blockers.append(
                "coverage events must record type_id_basis for compiler coverage audit; "
                + "effective basis inferred from source/provenance is "
                + ", ".join(effective_bases)
            )
        if not compiler_bases:
            blockers.append(
                "runtime coverage events must include compiler-assigned allocation-site object type IDs; "
                + "observed event bases: "
                + ", ".join(effective_bases)
            )
        if non_compiler_bases:
            blockers.append(
                "runtime coverage events use non-compiler type-id bases: "
                + ", ".join(non_compiler_bases)
            )
        if non_compiler_event_sources:
            blockers.append(
                "runtime coverage event sources are non-compiler prototype/layout paths: "
                + ", ".join(non_compiler_event_sources)
            )
        if bridge_bases:
            blockers.append(
                "runtime coverage events use compiler-site replay/bridge type-id bases rather than exact dynamic allocation-site attribution: "
                + ", ".join(bridge_bases)
            )
        if compiler_site_replay_events:
            blockers.append(
                "runtime coverage events are marked compiler_site_replay=true; claim-grade C002 requires compiler-emitted IDs at the actual dynamic allocation event"
            )
        if non_exact_stream_modes:
            blockers.append(
                "compiler_site_id_stream_modes are preflight bridge modes, not exact dynamic attribution: "
                + ", ".join(non_exact_stream_modes)
            )
    return {
        "status": "pass" if not unique_strings(blockers) else "fail",
        "strict_compiler_runtime_required": strict_compiler_runtime_required,
        "event_sources": event_sources,
        "compiler_site_replay_events": compiler_site_replay_events,
        "compiler_site_lowered_events": compiler_site_lowered_events,
        "compiler_site_id_stream_modes": compiler_site_id_stream_modes,
        "typed_compiler_site_id_stream_modes": typed_compiler_site_id_stream_modes,
        "fallback_compiler_site_id_stream_modes": fallback_compiler_site_id_stream_modes,
        "explicit_event_type_id_bases": explicit_bases,
        "explicit_typed_event_type_id_bases": explicit_typed_bases,
        "fallback_event_type_id_bases": fallback_bases,
        "effective_event_type_id_bases": effective_bases,
        "compiler_event_type_id_bases": compiler_bases,
        "bridge_event_type_id_bases": bridge_bases,
        "non_exact_stream_modes": non_exact_stream_modes,
        "non_compiler_event_type_id_bases": non_compiler_bases,
        "non_compiler_event_sources": non_compiler_event_sources,
        "blockers": unique_strings(blockers),
    }


def compiler_coverage_audit_valid_row_count(audit: Dict[str, Any]) -> int:
    summary = audit.get("summary", {}) if isinstance(audit, dict) else {}
    try:
        return int(summary.get("type_mapping_valid_record_count") or 0)
    except (TypeError, ValueError):
        return 0


def compiler_coverage_audit_is_current_strongest(audit: Dict[str, Any]) -> bool:
    summary = audit.get("summary", {}) if isinstance(audit, dict) else {}
    basis = audit.get("type_id_basis") if isinstance(audit, dict) else None
    return bool(
        coverage_basis_is_compiler_assigned(str(basis or ""))
        and compiler_coverage_audit_valid_row_count(audit) > 0
        and summary.get("type_mapping_status") == "pass"
    )


def optional_float(value: Any) -> Optional[float]:
    try:
        candidate = float(value)
    except (TypeError, ValueError):
        return None
    return candidate if math.isfinite(candidate) else None


def optional_int(value: Any) -> Optional[int]:
    try:
        return int(value)
    except (TypeError, ValueError):
        return None


def path_within(path: Path, parent: Path) -> bool:
    """Return whether ``path`` resolves under ``parent`` without requiring 3.9+ helpers."""

    try:
        path.resolve().relative_to(parent.resolve())
        return True
    except ValueError:
        return False


def rustc_driver_target_rewrite_artifact_blockers(
    target_rewrite: Dict[str, Any],
    *,
    label: str,
    required_source_prefix: Optional[str] = None,
) -> List[str]:
    """Validate the raw rustc_driver rewrite-map artifact behind a summary.

    Summary fields alone are easy to spoof in hand-written JSON.  Claim-grade C002
    evidence should point at a repo-local raw rewrite map emitted by the
    rustc_driver optimized_mir provider override and that map must contain actual
    applied MIR rewrite candidates with source spans from the intended surface.
    """

    blockers: List[str] = []
    raw_path = str(target_rewrite.get("path") or "").strip()
    if not raw_path:
        return [f"{label} target_rewrite does not reference a raw rewrite-map artifact"]
    path = Path(raw_path).expanduser()
    if not path.is_absolute():
        path = (ROOT / path).resolve()
    if not path.exists() or not path.is_file():
        return [f"{label} raw rewrite-map artifact is missing: {path}"]
    if not path_within(path, RAW):
        blockers.append(f"{label} raw rewrite-map artifact is not under evaluation/raw: {path}")
    try:
        artifact = json.loads(path.read_text(encoding="utf-8"))
    except Exception as exc:
        return [f"{label} raw rewrite-map artifact is not valid JSON: {exc}"]

    summary = artifact.get("summary") if isinstance(artifact.get("summary"), dict) else {}
    compiler_pass = (
        artifact.get("compiler_pass") if isinstance(artifact.get("compiler_pass"), dict) else {}
    )
    if compiler_pass.get("kind") != "rustc_driver_optimized_mir_provider_override":
        blockers.append(f"{label} rewrite-map was not emitted by the optimized_mir provider override")
    if compiler_pass.get("query_overridden") != "optimized_mir":
        blockers.append(f"{label} rewrite-map does not identify optimized_mir as the overridden rustc query")
    if summary.get("provider_override_installed") is not True:
        blockers.append(f"{label} rewrite-map summary does not prove provider_override_installed=true")
    if summary.get("body_clone_returned_to_rustc") is not True:
        blockers.append(f"{label} rewrite-map summary does not prove cloned MIR bodies were returned to rustc")
    if summary.get("actual_semantic_scope_rewrite") is not True:
        blockers.append(f"{label} rewrite-map summary did not run actual semantic-scope rewrite mode")
    applied_count = optional_int(summary.get("semantic_scope_rewrite_applied_count"))
    if applied_count is None or applied_count <= 0:
        blockers.append(f"{label} rewrite-map summary reports no applied semantic-scope rewrites")
    candidates = artifact.get("rewrite_candidates")
    if not isinstance(candidates, list) or not candidates:
        blockers.append(f"{label} rewrite-map contains no rewrite_candidates")
        candidates = []
    applied = [
        candidate
        for candidate in candidates
        if isinstance(candidate, dict)
        and str(candidate.get("rewrite_status") or "").startswith("actual_semantic_scope")
        and candidate.get("replacement_symbol")
        in {"__unialloc_semantic_scope_enter_exit", "__unialloc_semantic_scope_push_hints"}
    ]
    if not applied:
        blockers.append(f"{label} rewrite-map contains no actual applied semantic-scope candidates")
    if required_source_prefix is not None:
        matched_source = [
            candidate
            for candidate in applied
            if str(candidate.get("source_span") or "").startswith(required_source_prefix)
        ]
        if not matched_source:
            blockers.append(
                f"{label} rewrite-map contains no applied candidates from {required_source_prefix}"
            )
    return unique_strings(blockers)


def rustc_driver_probe_rewrite_artifact_blockers(
    target_rewrite: Dict[str, Any],
    *,
    label: str,
    mode: str,
    required_source_prefix: str,
) -> List[str]:
    """Validate probe companion rewrite-map provenance against the raw rustc pass output.

    The small MIR companion probes are intentionally cheap, but their JSON
    summaries must not become self-attesting fixtures.  Each accepted probe must
    point back to the raw rewrite map emitted under ``evaluation/raw`` by the
    real rustc_driver optimized_mir provider override, and that map must contain
    the applied rewrite class claimed by the probe summary.  This keeps the
    type-isolation gates tied to compiler-lowered heap-object evidence rather
    than hand-written/mock audit JSON.
    """

    blockers: List[str] = []
    if not isinstance(target_rewrite, dict):
        return [f"{label} is missing target_rewrite provider-override evidence"]
    raw_path = str(target_rewrite.get("path") or "").strip()
    if not raw_path:
        return [f"{label} target_rewrite does not reference a raw rewrite-map artifact"]
    path = Path(raw_path).expanduser()
    if not path.is_absolute():
        path = (ROOT / path).resolve()
    if not path.exists() or not path.is_file():
        return [f"{label} raw rewrite-map artifact is missing: {path}"]
    if not path_within(path, RAW):
        blockers.append(f"{label} raw rewrite-map artifact is not under evaluation/raw: {path}")
    try:
        artifact = json.loads(path.read_text(encoding="utf-8"))
    except Exception as exc:
        return [f"{label} raw rewrite-map artifact is not valid JSON: {exc}"]

    summary = artifact.get("summary") if isinstance(artifact.get("summary"), dict) else {}
    compiler_pass = (
        artifact.get("compiler_pass") if isinstance(artifact.get("compiler_pass"), dict) else {}
    )
    if compiler_pass.get("kind") != "rustc_driver_optimized_mir_provider_override":
        blockers.append(f"{label} rewrite-map was not emitted by the optimized_mir provider override")
    if compiler_pass.get("query_overridden") != "optimized_mir":
        blockers.append(f"{label} rewrite-map does not identify optimized_mir as the overridden rustc query")
    if summary.get("provider_override_installed") is not True:
        blockers.append(f"{label} rewrite-map summary does not prove provider_override_installed=true")
    if summary.get("body_clone_returned_to_rustc") is not True:
        blockers.append(f"{label} rewrite-map summary does not prove cloned MIR bodies were returned to rustc")

    candidates = artifact.get("rewrite_candidates")
    if not isinstance(candidates, list) or not candidates:
        blockers.append(f"{label} rewrite-map contains no rewrite_candidates")
        candidates = []

    source_candidates = [
        candidate
        for candidate in candidates
        if isinstance(candidate, dict)
        and str(candidate.get("source_span") or "").startswith(required_source_prefix)
    ]
    if not source_candidates:
        blockers.append(
            f"{label} rewrite-map contains no candidates from {required_source_prefix}"
        )

    if mode == "semantic_scope":
        if summary.get("actual_semantic_scope_rewrite") is not True:
            blockers.append(f"{label} rewrite-map did not run actual semantic-scope rewrite mode")
        if optional_int(summary.get("semantic_scope_rewrite_applied_count")) in (None, 0):
            blockers.append(f"{label} rewrite-map summary reports no applied semantic-scope rewrites")
        applied = [
            candidate
            for candidate in source_candidates
            if isinstance(candidate, dict)
            and str(candidate.get("rewrite_status") or "").startswith("actual_semantic_scope")
            and candidate.get("replacement_symbol")
            in {
                "__unialloc_semantic_scope_enter_exit",
                "__unialloc_semantic_scope_push",
                "__unialloc_semantic_scope_push_local",
                "__unialloc_semantic_scope_push_hints",
            }
        ]
        if not applied:
            blockers.append(f"{label} rewrite-map contains no actual semantic-scope candidates")
    elif mode == "cross_thread_hint":
        if summary.get("actual_semantic_scope_rewrite") is not True:
            blockers.append(f"{label} rewrite-map did not run actual semantic-scope rewrite mode")
        if optional_int(summary.get("semantic_scope_rewrite_applied_count")) in (None, 0):
            blockers.append(f"{label} rewrite-map summary reports no applied semantic-scope rewrites")
        if optional_int(summary.get("cross_thread_recovery_hint_count")) in (None, 0):
            blockers.append(f"{label} rewrite-map summary reports no cross-thread recovery hints")
        hinted = [
            candidate
            for candidate in source_candidates
            if isinstance(candidate, dict)
            and str(candidate.get("rewrite_status") or "").startswith("actual_semantic_scope")
            and candidate.get("replacement_symbol") == "__unialloc_semantic_scope_push_hints"
            and candidate.get("cross_thread_recovery_hint") is True
            and candidate.get("placement_hint_basis") == "auto_cross_thread_escape"
        ]
        if not hinted:
            blockers.append(f"{label} rewrite-map contains no applied cross-thread recovery-hint candidates")
    elif mode == "direct_allocator":
        if summary.get("actual_allocator_call_replacement") is not True:
            blockers.append(f"{label} rewrite-map did not run actual allocator-call replacement mode")
        if optional_int(summary.get("rewrite_applied_count")) in (None, 0):
            blockers.append(f"{label} rewrite-map summary reports no applied allocator-call rewrites")
        applied = [
            candidate
            for candidate in source_candidates
            if isinstance(candidate, dict)
            and candidate.get("rewrite_status") == "actual_allocator_call_replacement_applied"
            and str(candidate.get("replacement_symbol") or "").startswith("__unialloc_")
            and "with_metadata" in str(candidate.get("replacement_symbol") or "")
        ]
        if not applied:
            blockers.append(f"{label} rewrite-map contains no actual direct allocator metadata-ABI candidates")
    else:
        blockers.append(f"{label} rewrite-map validator has unknown mode: {mode}")

    return unique_strings(blockers)


def compiler_coverage_manifest_runtime_audit_status(
    audit: Optional[Dict[str, Any]],
) -> Dict[str, Any]:
    """Resolve the only runtime companion authorized by a compiler manifest."""

    status: Dict[str, Any] = {
        "ready": False,
        "manifest_path": None,
        "runtime_audit_path": None,
        "runtime_audit": None,
        "blockers": [],
    }
    if not isinstance(audit, dict):
        status["blockers"] = ["compiler coverage audit is missing"]
        return status
    manifest_ref = audit.get("manifest")
    if not manifest_ref:
        status["blockers"] = [
            "compiler coverage audit does not reference its source manifest"
        ]
        return status
    try:
        manifest_path = resolve_local_artifact_path(manifest_ref, base=ROOT)
        manifest = read_json(manifest_path)
        if not isinstance(manifest, dict):
            raise ValueError("compiler coverage manifest is not a JSON object")
        runtime_ref = manifest.get("runtime_audit")
        if not runtime_ref:
            raise ValueError("compiler coverage manifest is missing runtime_audit")
        runtime_path = resolve_local_artifact_path(
            runtime_ref,
            base=manifest_path.parent,
        )
        runtime_audit = read_json(runtime_path)
        if not isinstance(runtime_audit, dict):
            raise ValueError("runtime audit is not a JSON object")
    except (OSError, json.JSONDecodeError, ValueError) as exc:
        status["blockers"] = [
            f"compiler coverage manifest runtime audit could not be resolved: {exc}"
        ]
        return status
    status.update(
        {
            "ready": True,
            "manifest_path": str(manifest_path),
            "runtime_audit_path": str(runtime_path),
            "runtime_audit": runtime_audit,
        }
    )
    return status


def compiler_coverage_claim_critical_snapshot(audit: Dict[str, Any]) -> Dict[str, Any]:
    """Select saved compiler-audit fields that must match a fresh rebuild."""

    summary = audit.get("summary", {}) if isinstance(audit.get("summary"), dict) else {}
    summary_keys = (
        "ready_for_claim_grade_import",
        "claim_requested",
        "coverage_percent",
        "benchmark_surface_status",
        "benchmark_surface_expected_count",
        "benchmark_surface_observed_count",
        "benchmark_surface_missing_count",
        "event_type_id_basis_status",
        "event_type_id_bases",
        "type_id_basis",
        "event_type_mapping_correlation_status",
        "type_mapping_status",
        "type_mapping_valid_record_count",
    )
    return {
        "type_id_basis": audit.get("type_id_basis"),
        **{key: summary.get(key) for key in summary_keys},
    }


def compiler_coverage_claim_grade_status(
    audit: Optional[Dict[str, Any]],
    *,
    threshold: Optional[float] = None,
) -> Dict[str, Any]:
    """Fail-closed C002 acceptance status for the current compiler audit.

    `coverage_summary.json` may still contain an older non-claim-grade import.
    The paper claim should use the current final compiler-coverage audit when
    that audit is explicitly claim-requested, import-ready, complete on the
    canonical std_bench surface, and backed by compiler-assigned MIR
    semantic-scope IDs.  Legacy dynamic-gap/preflight artifacts remain useful
    diagnostics, but they must not mask a stronger current claim-grade audit.
    """

    blockers: List[str] = []
    if not isinstance(audit, dict):
        return {
            "ready": False,
            "observed": None,
            "summary": {},
            "blockers": ["missing evaluation/results/compiler_coverage_evidence_audit.json"],
        }
    summary = audit.get("summary", {}) if isinstance(audit.get("summary"), dict) else {}
    observed = optional_float(summary.get("coverage_percent"))
    if not compiler_coverage_audit_is_current_strongest(audit):
        blockers.append(
            "compiler coverage audit is not the current strongest compiler-assigned type-id evidence"
        )
    if summary.get("ready_for_claim_grade_import") is not True:
        blockers.append("compiler coverage audit is not ready_for_claim_grade_import")
    if summary.get("claim_requested") is not True:
        blockers.append("compiler coverage audit was not requested as claim-grade evidence")
    if summary.get("benchmark_surface_status") != "pass":
        blockers.append(
            f"compiler coverage benchmark surface status is {summary.get('benchmark_surface_status')}"
        )
    if optional_int(summary.get("benchmark_surface_expected_count")) in (None, 0):
        blockers.append("compiler coverage benchmark surface has no expected std_bench entries")
    if optional_int(summary.get("benchmark_surface_observed_count")) in (None, 0):
        blockers.append("compiler coverage benchmark surface has no observed std_bench entries")
    missing_count = optional_int(summary.get("benchmark_surface_missing_count"))
    if missing_count not in (0, None):
        blockers.append(f"compiler coverage benchmark surface still misses {missing_count} std_bench entries")
    if summary.get("event_type_id_basis_status") != "pass":
        blockers.append(
            f"compiler coverage event type-id basis status is {summary.get('event_type_id_basis_status')}"
        )
    if summary.get("event_type_mapping_correlation_status") != "pass":
        blockers.append(
            "compiler coverage event/type-mapping correlation status is "
            f"{summary.get('event_type_mapping_correlation_status')}"
        )
    if observed is None:
        blockers.append("compiler coverage audit does not report coverage_percent")
    elif threshold is not None and observed < threshold:
        blockers.append(f"compiler coverage {observed:.4f}% is below required {threshold:.4f}%")
    basis_text = " ".join(
        str(value)
        for value in (
            audit.get("type_id_basis"),
            summary.get("event_type_id_bases"),
            summary.get("type_id_basis"),
        )
        if value is not None
    )
    runtime_companion = None
    mir_probe_companions = None
    runtime_companion_path: Optional[str] = None
    runtime_manifest_status: Optional[Dict[str, Any]] = None
    if "rustc-driver-mir-semantic-scope" in basis_text:
        runtime_manifest_status = compiler_coverage_manifest_runtime_audit_status(audit)
        for blocker in runtime_manifest_status.get("blockers", []):
            blockers.append(f"compiler runtime companion blocker: {blocker}")
        runtime_audit = runtime_manifest_status.get("runtime_audit")
        if isinstance(runtime_audit, dict):
            runtime_companion = rustc_driver_mir_semantic_scope_runtime_companion_status(
                runtime_audit
            )
            runtime_companion_path = str(
                runtime_manifest_status.get("runtime_audit_path") or ""
            )
            for blocker in runtime_companion.get("blockers", []):
                blockers.append(f"compiler runtime companion blocker: {blocker}")
        mir_probe_companions = rustc_driver_mir_probe_companion_status()
        for blocker in mir_probe_companions.get("blockers", []):
            blockers.append(f"compiler MIR probe companion blocker: {blocker}")
    return {
        "ready": not blockers,
        "observed": observed,
        "summary": summary,
        "runtime_companion": runtime_companion,
        "runtime_companion_path": runtime_companion_path,
        "runtime_manifest_status": runtime_manifest_status,
        "mir_probe_companions": mir_probe_companions,
        "blockers": unique_strings(blockers),
    }


def rustc_driver_mir_semantic_scope_runtime_companion_status(
    audit: Optional[Dict[str, Any]],
) -> Dict[str, Any]:
    """Require real rustc_driver MIR semantic-scope runtime evidence for C002.

    The compiler-coverage manifest proves the MIR/type map surface.  It should
    not by itself prove that allocator metadata is delivered at runtime.  This
    companion gate therefore requires the original std_bench target to have
    executed through the actual rustc_driver optimized_mir semantic-scope
    rewrite path, with lowered-module typed allocation events observed across
    the canonical benchmark surface.  It is still coverage evidence, not a
    performance benchmark: `test-once` is allowed and preferred.
    """

    blockers: List[str] = []
    if not isinstance(audit, dict):
        return {
            "ready": False,
            "summary": {},
            "blockers": [
                "missing evaluation/results/rustc_driver_mir_semantic_scope_std_bench_runtime_smoke_audit.json"
            ],
        }
    summary = audit.get("summary", {}) if isinstance(audit.get("summary"), dict) else {}
    if summary.get("runtime_smoke_validated") is not True:
        blockers.append("MIR semantic-scope runtime smoke is not validated")
    if summary.get("actual_semantic_scope_rewrite") is not True:
        blockers.append("MIR semantic-scope runtime did not use the actual optimized_mir rewrite path")
    if optional_int(summary.get("semantic_scope_rewrite_applied_count")) in (None, 0):
        blockers.append("MIR semantic-scope runtime reports no applied semantic-scope rewrites")
    is_aggregate = (
        audit.get("source") == "rustc-driver-mir-semantic-scope-std-bench-runtime-shard-aggregate-audit"
        or summary.get("runtime_aggregate_validated") is True
    )
    runtime_target_rewrite: Optional[Dict[str, Any]] = None
    if is_aggregate:
        source_audits = audit.get("source_audits")
        if not isinstance(source_audits, list) or not source_audits:
            blockers.append("MIR semantic-scope runtime aggregate does not list validated source audits")
        else:
            invalid_sources = [
                str(source.get("path") or source.get("run_id") or idx)
                for idx, source in enumerate(source_audits)
                if not isinstance(source, dict) or source.get("validated") is not True
            ]
            if invalid_sources:
                blockers.append(
                    "MIR semantic-scope runtime aggregate contains unvalidated source audits: "
                    + ", ".join(invalid_sources[:5])
                )
            compiler_pass_invalid_sources = [
                str(source.get("path") or source.get("run_id") or idx)
                for idx, source in enumerate(source_audits)
                if not isinstance(source, dict)
                or source.get("target_rewrite_compiler_pass_validated") is not True
            ]
            if compiler_pass_invalid_sources:
                blockers.append(
                    "MIR semantic-scope runtime aggregate contains source audits without optimized_mir compiler_pass evidence: "
                    + ", ".join(compiler_pass_invalid_sources[:5])
                )
            direct_invalid_sources = [
                str(source.get("path") or source.get("run_id") or idx)
                for idx, source in enumerate(source_audits)
                if not isinstance(source, dict)
                or source.get("direct_allocator_rewrite_requested") is not True
                or source.get("direct_allocator_rewrite_validated") is not True
                or source.get("direct_local_size_align_with_semantic_drop") is not True
                or source.get("direct_size_align_local_pairing_validated") is not True
            ]
            if direct_invalid_sources:
                blockers.append(
                    "MIR semantic-scope runtime aggregate contains source audits without requested+validated direct allocator local size/align semantic-drop evidence: "
                    + ", ".join(direct_invalid_sources[:5])
                )
        if summary.get("target_rewrite_compiler_pass_validated") is not True:
            blockers.append("MIR semantic-scope runtime aggregate does not prove optimized_mir compiler_pass evidence for all source shards")
    else:
        target_rewrite = audit.get("target_rewrite")
        if not isinstance(target_rewrite, dict):
            blockers.append("MIR semantic-scope runtime is missing target_rewrite provider-override evidence")
            target_rewrite = {}
        runtime_target_rewrite = target_rewrite
        compiler_pass_status = rustc_driver_optimized_mir_provider_override_compiler_pass_status(
            target_rewrite,
            label="MIR semantic-scope runtime target_rewrite",
        )
        blockers.extend(compiler_pass_status["blockers"])
        if target_rewrite.get("provider_override_installed") is not True:
            blockers.append("MIR semantic-scope runtime target_rewrite did not install optimized_mir provider override")
        if target_rewrite.get("body_clone_returned_to_rustc") is not True:
            blockers.append("MIR semantic-scope runtime target_rewrite did not return a cloned MIR body to rustc")
        if target_rewrite.get("actual_semantic_scope_rewrite_requested") is not True:
            blockers.append("MIR semantic-scope runtime target_rewrite did not request actual semantic-scope rewrite")
        if target_rewrite.get("actual_semantic_scope_rewrite") is not True:
            blockers.append("MIR semantic-scope runtime target_rewrite did not apply actual semantic-scope rewrite mode")
        if optional_int(target_rewrite.get("semantic_scope_rewrite_applied_count")) in (None, 0):
            blockers.append("MIR semantic-scope runtime target_rewrite reports no applied semantic-scope rewrites")
        target_resolution = (
            target_rewrite.get("semantic_scope_replacement_resolution_status")
            or target_rewrite.get("replacement_resolution_status")
        )
        if target_resolution not in RUSTC_DRIVER_SEMANTIC_SCOPE_RESOLVED_STATUSES:
            blockers.append(
                "MIR semantic-scope runtime target_rewrite did not resolve __unialloc_semantic_scope enter/exit or push/pop symbols"
            )
        blockers.extend(
            rustc_driver_target_rewrite_artifact_blockers(
                target_rewrite,
                label="MIR semantic-scope runtime",
                required_source_prefix="unialloc/benches/",
            )
        )
    direct_mode_status = rustc_driver_mir_semantic_scope_direct_claim_mode_status(
        summary,
        label="MIR semantic-scope runtime",
    )
    if direct_mode_status["blockers"]:
        direct_probe_companion = rustc_driver_direct_allocator_mir_probe_companion_status(
            read_json_if_exists(RESULTS / "rustc_driver_direct_allocator_mir_probe_audit.json")
        )
        if direct_probe_companion.get("ready") is True:
            direct_mode_status["satisfied_by_direct_allocator_probe_companion"] = True
            direct_mode_status["direct_allocator_probe_companion_summary"] = (
                direct_probe_companion.get("summary", {})
                if isinstance(direct_probe_companion.get("summary"), dict)
                else {}
            )
        else:
            blockers.extend(direct_mode_status["blockers"])
    if optional_int(summary.get("lowered_module_typed_allocation_site_event_count")) in (None, 0):
        blockers.append("MIR semantic-scope runtime reports no lowered-module typed allocation events")
    if summary.get("lowered_module_compiler_basis_present") is not True:
        blockers.append("MIR semantic-scope runtime lowered-module events do not carry compiler-assigned basis")
    raw_stream_modes = summary.get("lowered_module_compiler_site_id_stream_modes")
    if isinstance(raw_stream_modes, list):
        stream_modes = set(str(value) for value in raw_stream_modes)
    elif raw_stream_modes:
        stream_modes = {str(raw_stream_modes)}
    else:
        stream_modes = set()
    if "rustc-driver-mir-semantic-scope" not in stream_modes:
        blockers.append("MIR semantic-scope runtime lowered-module events do not use rustc-driver-mir-semantic-scope stream mode")
    if summary.get("runtime_full_surface_candidate_validated") is not True:
        blockers.append("MIR semantic-scope runtime has not validated the canonical std_bench full surface")
    missing_count = optional_int(summary.get("canonical_missing_benchmark_count"))
    if missing_count not in (0, None):
        blockers.append(f"MIR semantic-scope runtime still misses {missing_count} canonical std_bench benchmarks")
    selected_count = optional_int(summary.get("selected_benchmark_count"))
    expected_count = optional_int(summary.get("canonical_expected_benchmark_count"))
    if expected_count in (None, 0):
        blockers.append("MIR semantic-scope runtime does not report a canonical expected benchmark count")
    if selected_count in (None, 0):
        blockers.append("MIR semantic-scope runtime does not report selected benchmark coverage")
    elif expected_count not in (None, 0) and selected_count < expected_count:
        blockers.append(
            f"MIR semantic-scope runtime selected {selected_count}/{expected_count} canonical std_bench benchmarks"
        )
    return {
        "ready": not blockers,
        "summary": summary,
        "target_rewrite": runtime_target_rewrite,
        "direct_claim_mode": direct_mode_status,
        "blockers": unique_strings(blockers),
    }


def rustc_driver_mir_semantic_scope_probe_companion_status(
    audit: Optional[Dict[str, Any]],
) -> Dict[str, Any]:
    """Require the small semantic-scope probe as compiler-path smoke evidence.

    The full std_bench runtime companion proves the paper surface.  This smaller
    probe proves a different invariant cheaply: ordinary high-level heap APIs
    only become typed when the rustc_driver optimized_mir semantic-scope rewrite
    is active, and the no-wrapper negative control fails as expected.
    """

    blockers: List[str] = []
    if not isinstance(audit, dict):
        return {
            "ready": False,
            "summary": {},
            "blockers": ["missing evaluation/results/rustc_driver_mir_semantic_scope_probe_audit.json"],
        }
    summary = audit.get("summary", {}) if isinstance(audit.get("summary"), dict) else {}
    target_rewrite = audit.get("target_rewrite")
    if not isinstance(target_rewrite, dict):
        blockers.append("semantic-scope MIR probe is missing target_rewrite provider-override evidence")
        target_rewrite = {}
    else:
        if target_rewrite.get("provider_override_installed") is not True:
            blockers.append("semantic-scope MIR probe target_rewrite did not install optimized_mir provider override")
        if target_rewrite.get("body_clone_returned_to_rustc") is not True:
            blockers.append("semantic-scope MIR probe target_rewrite did not return a cloned MIR body to rustc")
        if target_rewrite.get("actual_semantic_scope_rewrite_requested") is not True:
            blockers.append("semantic-scope MIR probe target_rewrite did not request actual semantic-scope rewrite")
        if target_rewrite.get("actual_semantic_scope_rewrite") is not True:
            blockers.append("semantic-scope MIR probe target_rewrite did not apply actual semantic-scope rewrite mode")
        if optional_int(target_rewrite.get("semantic_scope_rewrite_applied_count")) in (None, 0):
            blockers.append("semantic-scope MIR probe target_rewrite reports no applied semantic-scope rewrites")
        if target_rewrite.get("semantic_scope_replacement_resolution_status") not in RUSTC_DRIVER_SEMANTIC_SCOPE_RESOLVED_STATUSES:
            blockers.append("semantic-scope MIR probe target_rewrite did not resolve semantic-scope symbols")
        blockers.extend(
            rustc_driver_probe_rewrite_artifact_blockers(
                target_rewrite,
                label="semantic-scope MIR probe",
                mode="semantic_scope",
                required_source_prefix="unialloc/src/bin/rustc_driver_mir_semantic_scope_probe.rs",
            )
        )
    if summary.get("runtime_probe_validated") is not True:
        blockers.append("semantic-scope MIR probe is not runtime_probe_validated")
    if summary.get("actual_semantic_scope_rewrite") is not True:
        blockers.append("semantic-scope MIR probe did not use actual optimized_mir rewrite")
    if optional_int(summary.get("semantic_scope_rewrite_applied_count")) in (None, 0):
        blockers.append("semantic-scope MIR probe reports no applied semantic-scope rewrites")
    if summary.get("semantic_scope_replacement_resolution_status") not in RUSTC_DRIVER_SEMANTIC_SCOPE_RESOLVED_STATUSES:
        blockers.append(
            "semantic-scope MIR probe did not resolve __unialloc_semantic_scope enter/exit or push/pop symbols"
        )
    if optional_int(summary.get("typed_allocations")) in (None, 0):
        blockers.append("semantic-scope MIR probe reports no typed allocations")
    if optional_int(summary.get("typed_deallocations")) in (None, 0):
        blockers.append("semantic-scope MIR probe reports no typed deallocations")
    blockers.extend(
        rustc_driver_probe_semantic_metadata_validation_blockers(
            summary,
            label="semantic-scope MIR probe",
        )
    )
    if optional_int(summary.get("fallback_allocations")) not in (0,):
        blockers.append("semantic-scope MIR probe reports fallback allocations")
    if optional_int(summary.get("lowered_rows")) in (None, 0):
        blockers.append("semantic-scope MIR probe reports no lowered type rows")
    if optional_int(summary.get("type_mapping_record_count")) in (None, 0):
        blockers.append("semantic-scope MIR probe reports no type mapping rows")
    if optional_int(summary.get("semantic_scope_drop_unsolved_candidate_count")) != 0:
        blockers.append("semantic-scope MIR probe still has unsolved non-generic Drop heap-object candidates")
    if optional_int(summary.get("unsolved_drop_mapping_record_count")) != 0:
        blockers.append("semantic-scope MIR probe still exports unsolved non-generic Drop mapping rows")
    if optional_int(summary.get("semantic_scope_drop_generic_type_parameter_skipped_count")) in (None, 0):
        blockers.append("semantic-scope MIR probe does not classify generic Drop<T> cleanup separately")
    if optional_int(summary.get("semantic_scope_unwind_pop_inserted_count")) in (None, 0):
        blockers.append("semantic-scope MIR probe does not prove cleanup/unwind pop insertion")
    if summary.get("unwind_scope_cleanup_validated") is not True:
        blockers.append("semantic-scope MIR probe did not validate cleanup pop on panic unwind")
    if summary.get("unwind_scope_panic_observed") is not True:
        blockers.append("semantic-scope MIR probe did not observe the expected caught panic")
    if optional_int(summary.get("post_unwind_direct_alloc_total_allocations")) != 1:
        blockers.append("semantic-scope MIR probe did not execute exactly one post-unwind direct allocation")
    if optional_int(summary.get("post_unwind_direct_alloc_typed_allocations")) != 0:
        blockers.append("semantic-scope MIR probe leaked typed metadata into post-unwind direct allocation")
    if optional_int(summary.get("post_unwind_direct_alloc_fallback_allocations")) != 1:
        blockers.append("semantic-scope MIR probe post-unwind direct allocation was not fallback")
    if optional_int(summary.get("post_unwind_direct_alloc_typed_deallocations")) != 0:
        blockers.append("semantic-scope MIR probe leaked typed metadata into post-unwind direct deallocation")
    if optional_int(summary.get("post_unwind_direct_alloc_fallback_deallocations")) != 1:
        blockers.append("semantic-scope MIR probe post-unwind direct deallocation was not fallback")
    canonical_heap_family_counts = (
        summary.get("canonical_heap_family_type_mapping_record_counts")
        if isinstance(summary.get("canonical_heap_family_type_mapping_record_counts"), dict)
        else {}
    )
    required_heap_families = (
        "vec",
        "vec_deque",
        "binary_heap",
        "btree_map",
        "btree_set",
        "linked_list",
        "hash_map",
        "hash_set",
        "string",
        "box",
        "rc",
        "arc",
        "pathbuf",
        "osstring",
        "cstring",
    )
    for family in required_heap_families:
        family_rows = optional_int(
            summary.get(f"{family}_type_mapping_record_count")
            if summary.get(f"{family}_type_mapping_record_count") is not None
            else canonical_heap_family_counts.get(family)
        )
        if family_rows is None or family_rows < 1:
            blockers.append(
                f"semantic-scope MIR probe does not prove {family} heap-object type mapping"
            )
    std_collection_rows = optional_int(summary.get("std_collection_type_mapping_record_count"))
    if std_collection_rows is None or std_collection_rows < 8:
        blockers.append("semantic-scope MIR probe does not prove broad std collection heap-object mapping")
    receiver_rows = optional_int(
        summary.get("receiver_mutating_collection_type_mapping_record_count")
    )
    if (
        receiver_rows is None
        or receiver_rows < RUSTC_DRIVER_RECEIVER_MUTATING_COLLECTION_MIN_RECORDS
    ):
        blockers.append(
            "semantic-scope MIR probe does not prove receiver-mutating collection heap-owner attribution"
        )
    receiver_misattributed_rows = optional_int(
        summary.get("receiver_mutating_collection_misattributed_record_count")
    )
    if receiver_misattributed_rows != 0:
        blockers.append(
            "semantic-scope MIR probe has receiver-mutating collection rows misattributed away from the receiver heap owner"
        )
    hash_collection_rows = optional_int(summary.get("hash_collection_type_mapping_record_count"))
    if hash_collection_rows is None or hash_collection_rows < 2:
        blockers.append("semantic-scope MIR probe does not prove HashMap/HashSet heap-object mapping")
    hash_collection_owned_return_rows = optional_int(
        summary.get("hash_collection_owned_return_type_mapping_record_count")
    )
    if hash_collection_owned_return_rows is None or hash_collection_owned_return_rows < 2:
        blockers.append(
            "semantic-scope MIR probe does not prove HashMap/HashSet owned-return heap-object lowering"
        )
    smart_pointer_owned_return_rows = optional_int(
        summary.get("smart_pointer_owned_return_type_mapping_record_count")
    )
    if smart_pointer_owned_return_rows is None or smart_pointer_owned_return_rows < 2:
        blockers.append(
            "semantic-scope MIR probe does not prove Rc/Arc owned-return heap-object lowering"
        )
    owned_buffer_return_rows = optional_int(summary.get("owned_buffer_return_type_mapping_record_count"))
    if owned_buffer_return_rows is None or owned_buffer_return_rows < 2:
        blockers.append(
            "semantic-scope MIR probe does not prove PathBuf/OsString owned-buffer heap-object lowering"
        )
    c_string_rows = optional_int(summary.get("c_string_return_type_mapping_record_count"))
    if c_string_rows is None or c_string_rows < 1:
        blockers.append(
            "semantic-scope MIR probe does not prove CString owned-buffer heap-object lowering"
        )
    destination_type_candidate_rows = optional_int(
        summary.get("destination_type_candidate_mapping_record_count")
    )
    if destination_type_candidate_rows is None or destination_type_candidate_rows < 1:
        blockers.append(
            "semantic-scope MIR probe does not prove MIR destination-type candidate discovery"
        )
    nested_heap_owner_rows = optional_int(summary.get("nested_heap_owner_type_mapping_record_count"))
    if nested_heap_owner_rows is None or nested_heap_owner_rows < 4:
        blockers.append(
            "semantic-scope MIR probe does not prove nested ADT heap-owner lowering"
        )
    nested_probe_return_rows = optional_int(summary.get("nested_probe_return_type_mapping_record_count"))
    if nested_probe_return_rows is None or nested_probe_return_rows < 4:
        blockers.append(
            "semantic-scope MIR probe does not prove all nested-owner probe return functions"
        )
    if summary.get("no_wrapper_control_validated") is not True:
        blockers.append("semantic-scope MIR probe no-wrapper negative control is not validated")
    if summary.get("compiler_site_id_stream_mode") != "rustc-driver-mir-semantic-scope":
        blockers.append("semantic-scope MIR probe did not emit rustc-driver-mir-semantic-scope stream mode")
    if not coverage_basis_is_compiler_assigned(str(summary.get("type_id_basis") or "")):
        blockers.append("semantic-scope MIR probe does not report compiler-assigned type-id basis")
    return {
        "ready": not blockers,
        "summary": summary,
        "target_rewrite": target_rewrite,
        "blockers": unique_strings(blockers),
    }



def rustc_driver_direct_allocator_runtime_layout_provenance_blockers(
    audit: Dict[str, Any],
    target_rewrite: Dict[str, Any],
) -> List[str]:
    """Bind every applied direct MIR metadata ABI row to runtime layout evidence.

    Summary counts alone are self-attesting. Claim-grade direct allocator MIR
    companion evidence must contain raw optimized_mir rewrite rows with non-empty
    size/align operands and runtime semantic-type stats rows for every applied
    UniAlloc metadata ABI rewrite row. Each row is checked independently so one
    good runtime match cannot hide another missing or mismatched applied row.
    Concrete numeric operands are enforced on the allocator side they describe;
    symbolic MIR operands remain provenance- and non-zero-runtime-layout checked
    because exact numeric layout equality cannot be proven from the raw symbolic
    operand text alone. Recovery-backed realloc is intentionally split: the
    realloc callsite records the new allocation layout, while the old-object
    deallocation is recorded under the recovered allocation-site metadata row.
    """

    def applied_row_kind(row: Dict[str, Any]) -> Optional[str]:
        symbol = str(row.get("replacement_symbol") or row.get("callee") or "")
        if "__unialloc_realloc" in symbol:
            return "realloc"
        if "__unialloc_dealloc" in symbol:
            return "dealloc"
        if "__unialloc_alloc_zeroed" in symbol or "__unialloc_alloc" in symbol:
            return "alloc"
        return None

    def has_positive(value: Any) -> bool:
        number = optional_int(value)
        return number is not None and number > 0

    def runtime_layout_sides(runtime: Dict[str, Any]) -> Dict[str, Any]:
        allocations_ok = has_positive(runtime.get("allocations"))
        deallocations_ok = has_positive(runtime.get("deallocations"))
        allocated_bytes_ok = has_positive(runtime.get("allocated_bytes"))
        alloc_size = optional_int(runtime.get("observed_alloc_size"))
        alloc_align = optional_int(runtime.get("observed_alloc_align"))
        dealloc_size = optional_int(runtime.get("observed_dealloc_size"))
        dealloc_align = optional_int(runtime.get("observed_dealloc_align"))
        alloc_layout_ok = (
            allocations_ok
            and allocated_bytes_ok
            and alloc_size is not None and alloc_size > 0
            and alloc_align is not None and alloc_align > 0
        )
        dealloc_layout_ok = (
            deallocations_ok
            and dealloc_size is not None and dealloc_size > 0
            and dealloc_align is not None and dealloc_align > 0
        )
        return {
            "allocations_ok": allocations_ok,
            "deallocations_ok": deallocations_ok,
            "allocated_bytes_ok": allocated_bytes_ok,
            "alloc_size": alloc_size,
            "alloc_align": alloc_align,
            "dealloc_size": dealloc_size,
            "dealloc_align": dealloc_align,
            "alloc_layout_ok": alloc_layout_ok,
            "dealloc_layout_ok": dealloc_layout_ok,
        }

    def dealloc_layout_matches_operands(
        runtime: Dict[str, Any],
        size_operand: Optional[int],
        align_operand: Optional[int],
    ) -> Tuple[bool, bool, bool]:
        """Return (matched, numeric_mismatch, observed_dealloc_layout)."""

        sides = runtime_layout_sides(runtime)
        if not sides["dealloc_layout_ok"]:
            return False, False, False
        dealloc_size = sides["dealloc_size"]
        dealloc_align = sides["dealloc_align"]
        if size_operand is not None and dealloc_size != size_operand:
            return False, True, True
        if align_operand is not None and dealloc_align != align_operand:
            return False, True, True
        return True, False, True

    def recovery_backed_realloc_old_layout_matches(
        row: Dict[str, Any],
        type_id: int,
        module_id: int,
        callsite: int,
        size_operand: Optional[int],
        align_operand: Optional[int],
        runtime_by_type_module: Dict[Tuple[int, int], List[Dict[str, Any]]],
    ) -> Tuple[bool, bool, bool]:
        """Validate the old-layout half of a recovery-backed realloc.

        The metadata ABI for `__unialloc_realloc_layout_with_metadata` first
        recovers the old allocation's metadata from the side table, records the
        old-object deallocation under that recovered allocation-site identity,
        and records the new object under the realloc callsite identity.  Requiring
        both sides on the realloc callsite would be false for the real runtime.
        This helper therefore accepts either a same-row deallocation observation
        or a same `(type_id, module_id)` row with both allocation and deallocation
        layout evidence, which proves the old object was actually allocated and
        released through recovered metadata rather than inferred from summary
        counters.
        """

        rows = runtime_by_type_module.get((type_id, module_id), [])
        saw_numeric_mismatch = False
        saw_dealloc_layout = False
        recovery_backed = row.get("metadata_pairing_contract") == "recovery_backed_layout_metadata_abi"
        for runtime in rows:
            runtime_callsite = optional_int(runtime.get("callsite"))
            if runtime_callsite == callsite:
                matched, mismatch, observed = dealloc_layout_matches_operands(
                    runtime,
                    size_operand,
                    align_operand,
                )
                saw_numeric_mismatch = saw_numeric_mismatch or mismatch
                saw_dealloc_layout = saw_dealloc_layout or observed
                if matched:
                    return True, saw_numeric_mismatch, True
                continue

            if not recovery_backed:
                continue
            sides = runtime_layout_sides(runtime)
            if not (sides["alloc_layout_ok"] and sides["dealloc_layout_ok"]):
                continue
            saw_dealloc_layout = True
            if size_operand is not None and sides["dealloc_size"] != size_operand:
                saw_numeric_mismatch = True
                continue
            if align_operand is not None and sides["dealloc_align"] != align_operand:
                saw_numeric_mismatch = True
                continue
            # A recovered-old allocation row should be internally balanced for
            # the old object's layout: it observed an allocation and the
            # corresponding deallocation with the same layout.  This excludes
            # final dealloc-only rows for the post-realloc object.
            if (
                sides["alloc_size"] != sides["dealloc_size"]
                or sides["alloc_align"] != sides["dealloc_align"]
            ):
                continue
            return True, saw_numeric_mismatch, True
        return False, saw_numeric_mismatch, saw_dealloc_layout

    blockers: List[str] = []
    raw_path = str(target_rewrite.get("path") or "").strip()
    if not raw_path:
        return ["direct allocator MIR probe has no raw rewrite-map rows for layout provenance"]
    path = Path(raw_path).expanduser()
    if not path.is_absolute():
        path = (ROOT / path).resolve()
    try:
        artifact = json.loads(path.read_text(encoding="utf-8"))
    except Exception as exc:
        return [f"direct allocator MIR probe cannot read raw rewrite-map rows for layout provenance: {exc}"]

    candidates = artifact.get("rewrite_candidates")
    if not isinstance(candidates, list):
        candidates = []
    direct_rows = [
        row
        for row in candidates
        if isinstance(row, dict)
        and row.get("rewrite_status") == "actual_allocator_call_replacement_applied"
        and str(row.get("replacement_symbol") or row.get("callee") or "").startswith("__unialloc_")
        and "with_metadata" in str(row.get("replacement_symbol") or row.get("callee") or "")
    ]
    if not direct_rows:
        blockers.append("direct allocator MIR probe has no applied direct allocator source rows")

    runtime_rows = audit.get("runtime_layout_observation_rows")
    if runtime_rows is None and isinstance(audit.get("summary"), dict):
        runtime_rows = audit["summary"].get("runtime_layout_observation_rows")
    if not isinstance(runtime_rows, list) or not runtime_rows:
        blockers.append("direct allocator MIR probe has no runtime layout observation rows")
        runtime_rows = []

    runtime_by_key: Dict[Tuple[int, int, int], List[Dict[str, Any]]] = {}
    runtime_by_type_module: Dict[Tuple[int, int], List[Dict[str, Any]]] = {}
    for row in runtime_rows:
        if not isinstance(row, dict):
            continue
        key_values = (
            optional_int(row.get("type_id")),
            optional_int(row.get("module_id")),
            optional_int(row.get("callsite")),
        )
        if any(value is None for value in key_values):
            continue
        runtime_by_key.setdefault(key_values, []).append(row)  # type: ignore[arg-type]
        runtime_by_type_module.setdefault((key_values[0], key_values[1]), []).append(row)  # type: ignore[arg-type]

    valid_operand_rows = 0
    matched_rows = 0
    for index, row in enumerate(direct_rows):
        row_label = f"row {index}"
        row_kind = applied_row_kind(row)
        if row_kind is None:
            blockers.append(
                f"direct allocator MIR probe raw rewrite {row_label} has unclassified metadata ABI callee"
            )
            continue
        raw_size_operand = row.get("size_operand")
        raw_align_operand = row.get("align_operand")
        if raw_size_operand in (None, "") or raw_align_operand in (None, ""):
            blockers.append(
                f"direct allocator MIR probe raw rewrite {row_label} lacks non-empty size/align operands"
            )
            continue
        size_operand = optional_int(raw_size_operand)
        align_operand = optional_int(raw_align_operand)
        if (size_operand is not None and size_operand <= 0) or (align_operand is not None and align_operand <= 0):
            blockers.append(
                f"direct allocator MIR probe raw rewrite {row_label} has zero size/align operand"
            )
            continue
        type_id = optional_int(row.get("type_id"))
        module_id = optional_int(row.get("module_id"))
        callsite = optional_int(row.get("callsite"))
        if type_id is None or module_id is None or callsite is None:
            blockers.append(
                f"direct allocator MIR probe raw rewrite {row_label} lacks valid type/module/callsite provenance"
            )
            continue
        valid_operand_rows += 1

        key = (type_id, module_id, callsite)
        rows = runtime_by_key.get(key, [])
        if not rows:
            blockers.append(
                "direct allocator MIR probe has no runtime layout observation matching "
                f"raw {row_kind} type/module/callsite operand {key}"
            )
            continue

        saw_nonzero_layout = False
        saw_numeric_mismatch = False
        for runtime in rows:
            sides = runtime_layout_sides(runtime)
            alloc_size = sides["alloc_size"]
            alloc_align = sides["alloc_align"]
            dealloc_size = sides["dealloc_size"]
            dealloc_align = sides["dealloc_align"]
            alloc_layout_ok = sides["alloc_layout_ok"]
            dealloc_layout_ok = sides["dealloc_layout_ok"]

            if row_kind == "alloc":
                if not alloc_layout_ok:
                    continue
                saw_nonzero_layout = True
                if size_operand is not None and alloc_size != size_operand:
                    saw_numeric_mismatch = True
                    continue
                if align_operand is not None and alloc_align != align_operand:
                    saw_numeric_mismatch = True
                    continue
            elif row_kind == "dealloc":
                if not dealloc_layout_ok:
                    continue
                saw_nonzero_layout = True
                if size_operand is not None and dealloc_size != size_operand:
                    saw_numeric_mismatch = True
                    continue
                if align_operand is not None and dealloc_align != align_operand:
                    saw_numeric_mismatch = True
                    continue
            else:
                if not alloc_layout_ok:
                    continue
                saw_nonzero_layout = True
                # Realloc size_operand is the old layout size; the allocation
                # side may observe the new size. Alignment is inherited from the
                # old layout and should still be visible on the new allocation
                # side when the pass provides it numerically.
                if align_operand is not None and alloc_align != align_operand:
                    saw_numeric_mismatch = True
                    continue
                old_layout_matched, old_numeric_mismatch, old_layout_observed = (
                    recovery_backed_realloc_old_layout_matches(
                        row,
                        type_id,
                        module_id,
                        callsite,
                        size_operand,
                        align_operand,
                        runtime_by_type_module,
                    )
                )
                saw_numeric_mismatch = saw_numeric_mismatch or old_numeric_mismatch
                saw_nonzero_layout = saw_nonzero_layout or old_layout_observed
                if not old_layout_matched:
                    continue
            matched_rows += 1
            break
        else:
            if saw_numeric_mismatch:
                blockers.append(
                    "direct allocator MIR probe runtime layout observation does not match "
                    f"raw {row_kind} size/align operands for {key}"
                )
            elif saw_nonzero_layout:
                blockers.append(
                    "direct allocator MIR probe runtime layout observation failed layout validation "
                    f"for raw {row_kind} type/module/callsite operand {key}"
                )
            else:
                blockers.append(
                    "direct allocator MIR probe runtime layout observation does not match "
                    f"raw {row_kind} size/align operands for {key}: lacks "
                    f"{row_kind}-required allocation/deallocation/bytes or non-zero observed size/align"
                )

    if direct_rows and valid_operand_rows == 0:
        blockers.append("direct allocator MIR probe has no applied direct allocator row with concrete size/align operands")
    if valid_operand_rows and matched_rows != valid_operand_rows:
        blockers.append(
            "direct allocator MIR probe has unmatched or invalid runtime layout provenance rows"
        )
    return unique_strings(blockers)


SEMANTIC_METADATA_VALIDATION_KEYS = (
    "recovery_identity_matches",
    "recovery_identity_mismatches",
    "last_mismatch_requested_type_id",
    "last_mismatch_recorded_type_id",
    "last_mismatch_requested_module_id",
    "last_mismatch_recorded_module_id",
    "last_mismatch_requested_callsite",
    "last_mismatch_recorded_callsite",
)


def rustc_driver_probe_semantic_metadata_validation_summary(
    runtime_event: Dict[str, Any],
) -> Dict[str, int]:
    """Extract the real runtime recovery-identity validation snapshot.

    Typed/fallback totals cannot prove that recovered deallocation metadata
    kept the same compiler allocation identity.  These fields come from the
    runtime `semantic_metadata_validation_snapshot` and gate semantic recovery
    identity, not just fallback rate.
    """

    nested = (
        runtime_event.get("semantic_metadata_validation")
        if isinstance(runtime_event.get("semantic_metadata_validation"), dict)
        else {}
    )
    summary: Dict[str, int] = {}
    for key in SEMANTIC_METADATA_VALIDATION_KEYS:
        value = runtime_event.get(key)
        if value is None:
            value = nested.get(key)
        summary[key] = int(value or 0)
    return summary


def rustc_driver_probe_semantic_metadata_validation_blockers(
    summary: Dict[str, Any],
    *,
    label: str,
    require_recovery_identity_match: bool = True,
) -> List[str]:
    """Fail closed when a MIR probe hides or reports recovery identity errors.

    Recovery-backed deallocation paths must observe at least one successful
    recovery-identity match.  A direct-local metadata ABI probe can be stricter
    in a different way: it deliberately bypasses recovery for local
    alloc/realloc/dealloc metadata, so zero recovery matches is expected there
    as long as the caller has independently proved the local ABI pairing and
    runtime layout provenance.  `require_recovery_identity_match=False` is only
    for that independently proved no-recovery local ABI path; mismatches and
    missing reporting still fail closed.
    """

    blockers: List[str] = []
    if "recovery_identity_mismatches" not in summary:
        blockers.append(
            f"{label} does not report semantic metadata recovery-identity validation"
        )
        return blockers
    if optional_int(summary.get("recovery_identity_mismatches")) != 0:
        blockers.append(f"{label} reports semantic metadata recovery identity mismatches")
    if (
        require_recovery_identity_match
        and optional_int(summary.get("recovery_identity_matches")) in (None, 0)
    ):
        blockers.append(
            f"{label} did not observe any matching semantic metadata recovery identity"
        )
    return blockers


def rustc_driver_direct_allocator_local_no_recovery_metadata_abi_validated(
    summary: Dict[str, Any],
) -> bool:
    """Return true when direct-local ABI evidence can replace recovery matches.

    In `--direct-local-size-align-with-semantic-drop` mode the probe can rewrite
    Layout alloc/realloc/dealloc calls to local metadata ABI symbols.  Those
    calls intentionally do not exercise recovery metadata, so
    `recovery_identity_matches == 0` is not by itself a failure.  This helper
    makes the exception narrow: the audit must prove real local rewrites,
    dealloc/realloc coverage, no recovery-backed rows still requiring recovery
    identity validation, no local pairing or metadata-contract gaps, zero
    recovery mismatches, and row-by-row runtime layout provenance.
    """

    local_metadata_rewrites_present = (
        summary.get("direct_local_metadata_abi") is True
        and optional_int(summary.get("direct_local_metadata_abi_rewrite_applied_count"))
        not in (None, 0)
        and optional_int(summary.get("direct_local_realloc_rewrite_applied_count"))
        not in (None, 0)
        and optional_int(summary.get("direct_local_dealloc_rewrite_applied_count"))
        not in (None, 0)
    )
    no_recovery_backed_rows_remain = (
        optional_int(summary.get("direct_size_align_recovery_backed_required_count")) in (0,)
    )
    local_pairing_contract_validated = (
        summary.get("direct_size_align_alloc_recovery_contract_validated") is True
        and summary.get("direct_size_align_local_pairing_validated") is True
        and optional_int(summary.get("direct_local_size_align_metadata_contract_violation_count"))
        in (0,)
        and optional_int(summary.get("direct_local_size_align_pairing_gap_count")) in (0,)
    )
    runtime_layout_provenance_validated = (
        summary.get("runtime_layout_provenance_validated") is True
        and not summary.get("runtime_layout_provenance_blockers")
    )
    semantic_recovery_report_clean = (
        optional_int(summary.get("recovery_identity_mismatches")) in (0,)
    )
    return bool(
        local_metadata_rewrites_present
        and no_recovery_backed_rows_remain
        and local_pairing_contract_validated
        and runtime_layout_provenance_validated
        and semantic_recovery_report_clean
    )


def rustc_driver_direct_allocator_mir_probe_companion_status(
    audit: Optional[Dict[str, Any]],
) -> Dict[str, Any]:
    """Require the small direct allocator-call MIR replacement probe evidence."""

    blockers: List[str] = []
    if not isinstance(audit, dict):
        return {
            "ready": False,
            "summary": {},
            "blockers": ["missing evaluation/results/rustc_driver_direct_allocator_mir_probe_audit.json"],
        }
    summary = audit.get("summary", {}) if isinstance(audit.get("summary"), dict) else {}
    target_rewrite = audit.get("target_rewrite")
    if not isinstance(target_rewrite, dict):
        blockers.append("direct allocator MIR probe is missing target_rewrite provider-override evidence")
        target_rewrite = {}
    else:
        if target_rewrite.get("provider_override_installed") is not True:
            blockers.append("direct allocator MIR probe target_rewrite did not install optimized_mir provider override")
        if target_rewrite.get("body_clone_returned_to_rustc") is not True:
            blockers.append("direct allocator MIR probe target_rewrite did not return a cloned MIR body to rustc")
        if target_rewrite.get("actual_allocator_call_replacement_requested") is not True:
            blockers.append("direct allocator MIR probe target_rewrite did not request allocator-call replacement")
        if target_rewrite.get("actual_allocator_call_replacement") is not True:
            blockers.append("direct allocator MIR probe target_rewrite did not apply allocator-call replacement")
        if optional_int(target_rewrite.get("rewrite_applied_count")) in (None, 0):
            blockers.append("direct allocator MIR probe target_rewrite reports no applied allocator-call rewrites")
        if target_rewrite.get("direct_replacement_resolution_status") not in RUSTC_DRIVER_DIRECT_ALLOCATOR_RESOLVED_STATUSES:
            blockers.append("direct allocator MIR probe target_rewrite did not resolve UniAlloc metadata ABI")
        blockers.extend(
            rustc_driver_probe_rewrite_artifact_blockers(
                target_rewrite,
                label="direct allocator MIR probe",
                mode="direct_allocator",
                required_source_prefix="unialloc/src/bin/rustc_driver_direct_allocator_mir_probe.rs",
            )
        )
        blockers.extend(
            rustc_driver_direct_allocator_runtime_layout_provenance_blockers(
                audit,
                target_rewrite,
            )
        )
    if summary.get("runtime_probe_validated") is not True:
        blockers.append("direct allocator MIR probe is not runtime_probe_validated")
    if summary.get("actual_allocator_call_replacement") is not True:
        blockers.append("direct allocator MIR probe did not use actual allocator-call replacement")
    if optional_int(summary.get("direct_allocator_rewrite_applied_count")) in (None, 0):
        blockers.append("direct allocator MIR probe reports no applied allocator-call rewrites")
    if optional_int(summary.get("direct_layout_allocator_rewrite_applied_count")) in (None, 0):
        blockers.append("direct allocator MIR probe reports no applied std::alloc Layout rewrites")
    if optional_int(summary.get("direct_heap_object_solved_rewrite_applied_count")) in (None, 0):
        blockers.append("direct allocator MIR probe reports no solved heap-object direct rewrites")
    direct_box_shallow_init_candidate_count = optional_int(
        summary.get("direct_box_shallow_init_candidate_count")
    )
    direct_box_shallow_init_rewrite_count = optional_int(
        summary.get("direct_box_shallow_init_rewrite_applied_count")
    )
    if (
        direct_box_shallow_init_candidate_count not in (0,)
        and direct_box_shallow_init_rewrite_count in (None, 0)
    ):
        blockers.append("direct allocator MIR probe reports no Box ShallowInitBox-solved exchange_malloc rewrites")
    if optional_int(summary.get("direct_layout_constructor_rewrite_applied_count")) in (None, 0):
        blockers.append("direct allocator MIR probe reports no Layout-constructor-provenance direct rewrites")
    if optional_int(summary.get("direct_layout_raw_value_constructor_rewrite_applied_count")) in (None, 0):
        blockers.append("direct allocator MIR probe reports no raw-pointer Layout constructor direct rewrites")
    if optional_int(summary.get("direct_layout_runtime_array_constructor_rewrite_applied_count")) in (None, 0):
        blockers.append("direct allocator MIR probe reports no runtime-length Layout::array direct rewrites")
    if optional_int(summary.get("direct_layout_transformer_rewrite_applied_count")) in (None, 0):
        blockers.append("direct allocator MIR probe reports no Layout-transformer-provenance direct rewrites")
    if optional_int(summary.get("direct_layout_result_option_passthrough_rewrite_applied_count")) in (None, 0):
        blockers.append(
            "direct allocator MIR probe reports no Result<Layout>::ok / "
            "Option<Layout>::expect/unwrap passthrough direct rewrites"
        )
    if optional_int(summary.get("direct_layout_reconstructed_rewrite_applied_count")) in (None, 0):
        blockers.append("direct allocator MIR probe reports no same-source Layout-reconstruction direct rewrites")
    if optional_int(summary.get("direct_layout_size_align_constructor_rewrite_applied_count")) in (None, 0):
        blockers.append("direct allocator MIR probe reports no size_of/align_of Layout reconstruction direct rewrites")
    if optional_int(summary.get("direct_layout_composite_rewrite_applied_count")) in (None, 0):
        blockers.append("direct allocator MIR probe reports no Layout-composite-provenance direct rewrites")
    if optional_int(summary.get("direct_layout_packed_composite_rewrite_applied_count")) in (None, 0):
        blockers.append("direct allocator MIR probe reports no packed Layout-composite-provenance direct rewrites")
    layout_provenance_validated = (
        summary.get("runtime_layout_provenance_validated") is True
        and not summary.get("runtime_layout_provenance_blockers")
    )
    if not layout_provenance_validated:
        # Older claim gates required the experimental direct-local Layout ABI,
        # where alloc/realloc/dealloc size+align pairings were kept in local MIR
        # state.  The production probe now uses the safer metadata ABI plus
        # runtime layout-provenance rows: realloc records the new allocation at
        # the realloc callsite while the old-object deallocation is tied back to
        # recovered allocation-site metadata.  When that split provenance has
        # been validated row-by-row, absence of direct-local ABI rows is not a
        # blocker.
        if summary.get("direct_local_metadata_abi") is not True:
            blockers.append("direct allocator MIR probe did not validate direct-local Layout metadata ABI mode")
        if optional_int(summary.get("direct_local_metadata_abi_rewrite_applied_count")) in (None, 0):
            blockers.append("direct allocator MIR probe reports no direct-local metadata ABI rewrites")
        if optional_int(summary.get("direct_local_realloc_rewrite_applied_count")) in (None, 0):
            blockers.append("direct allocator MIR probe reports no direct-local realloc rewrite")
        if optional_int(summary.get("direct_local_dealloc_rewrite_applied_count")) in (None, 0):
            blockers.append("direct allocator MIR probe reports no direct-local dealloc rewrites")
    local_size_align_count = optional_int(
        summary.get("direct_local_size_align_alloc_rewrite_applied_count")
    )
    recovery_backed_size_align_count = optional_int(
        summary.get("direct_size_align_recovery_backed_required_count")
    )
    semantic_drop_scope_count = optional_int(
        summary.get("direct_local_size_align_semantic_drop_scope_count")
    )
    if summary.get("direct_local_size_align_with_semantic_drop") is True:
        if local_size_align_count in (None, 0):
            if (
                direct_box_shallow_init_candidate_count not in (0,)
                and recovery_backed_size_align_count in (None, 0)
            ):
                blockers.append(
                    "direct allocator MIR probe reports neither semantic-drop-paired local "
                    "size/align alloc rewrite nor recovery-backed fail-closed size/align rewrite"
                )
        else:
            if semantic_drop_scope_count in (None, 0):
                blockers.append("direct allocator MIR probe reports no semantic Drop scope for local size/align alloc")
            if (
                semantic_drop_scope_count is not None
                and semantic_drop_scope_count < local_size_align_count
            ):
                blockers.append("direct allocator MIR probe has fewer semantic Drop scopes than local size/align alloc rewrites")
    else:
        if local_size_align_count not in (0,):
            blockers.append("direct allocator MIR probe incorrectly lowered unpaired size/align alloc to local ABI")
        if (
            recovery_backed_size_align_count is None
            and summary.get("direct_size_align_alloc_recovery_contract_validated") is not True
        ):
            blockers.append("direct allocator MIR probe did not prove unpaired size/align alloc stays recovery-backed")
    if optional_int(summary.get("direct_local_size_align_metadata_contract_violation_count")) not in (0,):
        blockers.append("direct allocator MIR probe reports local metadata ABI contract violations")
    pairing_gap_count = optional_int(summary.get("direct_local_size_align_pairing_gap_count"))
    if pairing_gap_count not in (0,):
        blockers.append("direct allocator MIR probe reports unpaired local size/align heap-object identities")
    pairing_details = summary.get("direct_local_size_align_pairing_details")
    if (
        summary.get("direct_local_size_align_with_semantic_drop") is True
        and local_size_align_count not in (None, 0)
    ):
        if not isinstance(pairing_details, list) or not pairing_details:
            blockers.append("direct allocator MIR probe does not report per-identity local size/align pairing details")
        else:
            detail_alloc_count = 0
            detail_gap_count = 0
            for detail in pairing_details:
                if not isinstance(detail, dict):
                    detail_gap_count += 1
                    continue
                alloc_count = optional_int(detail.get("local_size_align_alloc_count"))
                drop_count = optional_int(detail.get("semantic_drop_scope_count"))
                if alloc_count is None or alloc_count <= 0 or drop_count is None:
                    detail_gap_count += 1
                    continue
                detail_alloc_count += alloc_count
                if drop_count < alloc_count or detail.get("paired") is not True:
                    detail_gap_count += 1
            if local_size_align_count not in (None, 0) and detail_alloc_count != local_size_align_count:
                blockers.append("direct allocator MIR probe pairing details do not cover all local size/align rewrites")
            if pairing_gap_count is not None and detail_gap_count != pairing_gap_count:
                blockers.append("direct allocator MIR probe pairing detail gap count does not match summary")
    if summary.get("direct_size_align_alloc_recovery_contract_validated") is not True:
        blockers.append("direct allocator MIR probe did not validate size/align recovery-backed contract")
    if summary.get("direct_size_align_local_pairing_validated") is not True:
        blockers.append("direct allocator MIR probe did not validate local ABI pairing contract")
    if (
        summary.get("direct_replacement_resolution_status")
        not in RUSTC_DRIVER_DIRECT_ALLOCATOR_RESOLVED_STATUSES
    ):
        blockers.append("direct allocator MIR probe did not resolve UniAlloc metadata ABI")
    if summary.get("manual_metadata_abi_calls") is not False:
        blockers.append("direct allocator MIR probe source/runtime did not prove manual_metadata_abi_calls=false")
    if optional_int(summary.get("typed_allocations")) in (None, 0):
        blockers.append("direct allocator MIR probe reports no typed allocations")
    if optional_int(summary.get("typed_deallocations")) in (None, 0):
        blockers.append("direct allocator MIR probe reports no typed deallocations")
    direct_local_no_recovery_metadata_abi_validated = (
        rustc_driver_direct_allocator_local_no_recovery_metadata_abi_validated(summary)
    )
    blockers.extend(
        rustc_driver_probe_semantic_metadata_validation_blockers(
            summary,
            label="direct allocator MIR probe",
            require_recovery_identity_match=not direct_local_no_recovery_metadata_abi_validated,
        )
    )
    if (
        optional_int(summary.get("fallback_allocations")) not in (0,)
        and not (layout_provenance_validated and summary.get("no_wrapper_control_validated") is True)
    ):
        blockers.append("direct allocator MIR probe reports fallback allocations")
    if optional_int(summary.get("lowered_rows")) in (None, 0):
        blockers.append("direct allocator MIR probe reports no lowered type rows")
    if optional_int(summary.get("type_mapping_record_count")) in (None, 0):
        blockers.append("direct allocator MIR probe reports no type mapping rows")
    direct_box_shallow_init_type_mapping_count = optional_int(
        summary.get("direct_box_shallow_init_type_mapping_record_count")
    )
    if (
        direct_box_shallow_init_candidate_count not in (0,)
        and direct_box_shallow_init_type_mapping_count in (None, 0)
    ):
        blockers.append("direct allocator MIR probe type mapping has no Box ShallowInitBox object-type rows")
    if optional_int(summary.get("direct_layout_constructor_type_mapping_record_count")) in (None, 0):
        blockers.append("direct allocator MIR probe type mapping has no Layout constructor object-type rows")
    if optional_int(summary.get("direct_layout_raw_value_constructor_type_mapping_record_count")) in (None, 0):
        blockers.append("direct allocator MIR probe type mapping has no raw-pointer Layout constructor object-type rows")
    if optional_int(summary.get("direct_layout_runtime_array_constructor_type_mapping_record_count")) in (None, 0):
        blockers.append("direct allocator MIR probe type mapping has no runtime-length Layout::array object-type rows")
    if optional_int(summary.get("direct_layout_transformer_type_mapping_record_count")) in (None, 0):
        blockers.append("direct allocator MIR probe type mapping has no Layout transformer object-type rows")
    if optional_int(summary.get("direct_layout_result_option_passthrough_type_mapping_record_count")) in (None, 0):
        blockers.append(
            "direct allocator MIR probe type mapping has no Result<Layout>::ok / "
            "Option<Layout>::expect/unwrap passthrough object-type rows"
        )
    if optional_int(summary.get("direct_layout_reconstructed_type_mapping_record_count")) in (None, 0):
        blockers.append("direct allocator MIR probe type mapping has no same-source Layout reconstruction object-type rows")
    if optional_int(summary.get("direct_layout_size_align_constructor_type_mapping_record_count")) in (None, 0):
        blockers.append("direct allocator MIR probe type mapping has no size_of/align_of Layout reconstruction object-type rows")
    if optional_int(summary.get("direct_layout_composite_type_mapping_record_count")) in (None, 0):
        blockers.append("direct allocator MIR probe type mapping has no Layout composite object-type rows")
    if optional_int(summary.get("direct_layout_packed_composite_type_mapping_record_count")) in (None, 0):
        blockers.append("direct allocator MIR probe type mapping has no packed Layout composite object-type rows")
    if summary.get("no_wrapper_control_validated") is not True:
        blockers.append("direct allocator MIR probe no-wrapper negative control is not validated")
    if summary.get("compiler_site_id_stream_mode") != "rustc-driver-direct-allocator-mir":
        blockers.append("direct allocator MIR probe did not emit rustc-driver-direct-allocator-mir stream mode")
    if not coverage_basis_is_compiler_assigned(str(summary.get("type_id_basis") or "")):
        blockers.append("direct allocator MIR probe does not report compiler-assigned type-id basis")
    return {
        "ready": not blockers,
        "summary": summary,
        "target_rewrite": target_rewrite,
        "blockers": unique_strings(blockers),
    }


def rustc_driver_mir_cross_thread_hint_probe_companion_status(
    audit: Optional[Dict[str, Any]],
) -> Dict[str, Any]:
    """Require the cross-thread MIR hint probe as C002 companion evidence.

    The semantic-scope probe covers ordinary typed allocation/deallocation
    lowering in a single thread.  The cross-thread probe covers the harder
    object-lifetime case where a heap-owning value moves to another thread and
    the compiler-side semantic scope must be recovered at the worker-thread
    drop site.  This intentionally stays a cheap runtime probe, but it must be
    generated by the real rustc_driver rewrite path and backed by the runtime
    allocator event stream.
    """

    blockers: List[str] = []
    if not isinstance(audit, dict):
        return {
            "ready": False,
            "summary": {},
            "blockers": ["missing evaluation/results/rustc_driver_mir_cross_thread_hint_probe_audit.json"],
        }
    summary = audit.get("summary", {}) if isinstance(audit.get("summary"), dict) else {}
    target_rewrite = audit.get("target_rewrite")
    if not isinstance(target_rewrite, dict):
        blockers.append("cross-thread MIR hint probe is missing target_rewrite provider-override evidence")
        target_rewrite = {}
    else:
        if target_rewrite.get("provider_override_installed") is not True:
            blockers.append("cross-thread MIR hint probe target_rewrite did not install optimized_mir provider override")
        if target_rewrite.get("body_clone_returned_to_rustc") is not True:
            blockers.append("cross-thread MIR hint probe target_rewrite did not return a cloned MIR body to rustc")
        if target_rewrite.get("actual_semantic_scope_rewrite_requested") is not True:
            blockers.append("cross-thread MIR hint probe target_rewrite did not request actual semantic-scope rewrite")
        if target_rewrite.get("actual_semantic_scope_rewrite") is not True:
            blockers.append("cross-thread MIR hint probe target_rewrite did not apply actual semantic-scope rewrite mode")
        if optional_int(target_rewrite.get("cross_thread_recovery_hint_count")) in (None, 0):
            blockers.append("cross-thread MIR hint probe target_rewrite reports no cross-thread recovery hints")
        if optional_int(target_rewrite.get("semantic_scope_rewrite_applied_count")) in (None, 0):
            blockers.append("cross-thread MIR hint probe target_rewrite reports no applied semantic-scope rewrites")
        if target_rewrite.get("semantic_scope_replacement_resolution_status") not in RUSTC_DRIVER_SEMANTIC_SCOPE_RESOLVED_STATUSES:
            blockers.append("cross-thread MIR hint probe target_rewrite did not resolve semantic-scope symbols")
        blockers.extend(
            rustc_driver_probe_rewrite_artifact_blockers(
                target_rewrite,
                label="cross-thread MIR hint probe",
                mode="cross_thread_hint",
                required_source_prefix="unialloc/src/bin/rustc_driver_mir_cross_thread_hint_probe.rs",
            )
        )
    if summary.get("runtime_probe_validated") is not True:
        blockers.append("cross-thread MIR hint probe is not runtime_probe_validated")
    if summary.get("actual_semantic_scope_rewrite") is not True:
        blockers.append("cross-thread MIR hint probe did not use actual optimized_mir rewrite")
    if summary.get("semantic_scope_resolution_status_ok") is not True:
        blockers.append("cross-thread MIR hint probe did not resolve semantic-scope push/hint/pop symbols")
    if summary.get("no_wrapper_control_validated") is not True:
        blockers.append("cross-thread MIR hint probe no-wrapper negative control is not validated")
    if optional_int(summary.get("cross_thread_recovery_hint_count")) in (None, 0):
        blockers.append("cross-thread MIR hint probe reports no cross-thread recovery hints")
    if optional_int(summary.get("hinted_semantic_scope_rewrite_applied_count")) in (None, 0):
        blockers.append("cross-thread MIR hint probe reports no hinted semantic-scope rewrites")
    if optional_int(summary.get("semantic_scope_rewrite_applied_count")) in (None, 0):
        blockers.append("cross-thread MIR hint probe reports no applied semantic-scope rewrites")
    if optional_int(summary.get("semantic_scope_drop_rewrite_applied_count")) in (None, 0):
        blockers.append("cross-thread MIR hint probe reports no drop-site semantic-scope rewrites")
    if optional_int(summary.get("typed_allocations")) in (None, 0):
        blockers.append("cross-thread MIR hint probe reports no typed allocations")
    if optional_int(summary.get("typed_deallocations")) in (None, 0):
        blockers.append("cross-thread MIR hint probe reports no typed deallocations")
    blockers.extend(
        rustc_driver_probe_semantic_metadata_validation_blockers(
            summary,
            label="cross-thread MIR hint probe",
        )
    )
    fallback_allocations = optional_int(summary.get("fallback_allocations"))
    if fallback_allocations not in (None, 0):
        if summary.get("fallback_attribution_matches_stats") is not True:
            blockers.append(
                "cross-thread MIR hint probe has fallback allocations without matching runtime fallback attribution"
            )
        if optional_int(summary.get("fallback_attribution_allocations")) != fallback_allocations:
            blockers.append(
                "cross-thread MIR hint probe fallback attribution total does not match fallback allocations"
            )
        if optional_int(summary.get("fallback_attribution_raw_alloc_no_metadata")) in (None, 0):
            blockers.append(
                "cross-thread MIR hint probe fallback allocations are not classified as raw no-metadata allocations"
            )
        if optional_int(summary.get("fallback_trace_worker_start_raw_alloc_no_metadata")) is None:
            blockers.append(
                "cross-thread MIR hint probe fallback attribution lacks worker-start stage trace"
            )
        if optional_int(summary.get("fallback_trace_after_spawn_raw_alloc_no_metadata")) is None:
            blockers.append(
                "cross-thread MIR hint probe fallback attribution lacks parent after-spawn stage trace"
            )
    if optional_int(summary.get("lowered_rows")) in (None, 0):
        blockers.append("cross-thread MIR hint probe reports no lowered allocation type rows")
    if optional_int(summary.get("lowered_deallocation_rows")) in (None, 0):
        blockers.append("cross-thread MIR hint probe reports no lowered deallocation type rows")
    if optional_int(summary.get("arc_cross_thread_type_mapping_record_count")) in (None, 0):
        blockers.append("cross-thread MIR hint probe reports no Arc cross-thread type-mapping rows")
    if optional_int(summary.get("non_escaping_vecdeque_cross_thread_hint_count")) != 0:
        blockers.append("cross-thread MIR hint probe over-tagged non-escaping VecDeque rows")
    if optional_int(summary.get("non_escaping_direct_allocator_cross_thread_hint_count")) != 0:
        blockers.append("cross-thread MIR hint probe over-tagged non-escaping direct allocator rows")
    if optional_int(summary.get("type_mapping_record_count")) in (None, 0):
        blockers.append("cross-thread MIR hint probe reports no type mapping rows")
    if optional_int(summary.get("semantic_scope_drop_unsolved_candidate_count")) != 0:
        blockers.append("cross-thread MIR hint probe still has unsolved non-generic Drop heap-object candidates")
    if optional_int(summary.get("unsolved_drop_mapping_record_count")) != 0:
        blockers.append("cross-thread MIR hint probe still exports unsolved non-generic Drop mapping rows")
    if summary.get("compiler_site_id_stream_mode") != "rustc-driver-mir-cross-thread-hint":
        blockers.append("cross-thread MIR hint probe did not emit rustc-driver-mir-cross-thread-hint stream mode")
    if not coverage_basis_is_compiler_assigned(str(summary.get("type_id_basis") or "")):
        blockers.append("cross-thread MIR hint probe does not report compiler-assigned type-id basis")
    return {
        "ready": not blockers,
        "summary": summary,
        "target_rewrite": target_rewrite,
        "blockers": unique_strings(blockers),
    }


def rustc_driver_mir_probe_companion_status(
    *,
    semantic_scope_probe_audit: Optional[Dict[str, Any]] = None,
    direct_allocator_probe_audit: Optional[Dict[str, Any]] = None,
    cross_thread_hint_probe_audit: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    semantic_scope = rustc_driver_mir_semantic_scope_probe_companion_status(
        semantic_scope_probe_audit
        if semantic_scope_probe_audit is not None
        else read_json_if_exists(RESULTS / "rustc_driver_mir_semantic_scope_probe_audit.json")
    )
    direct_allocator = rustc_driver_direct_allocator_mir_probe_companion_status(
        direct_allocator_probe_audit
        if direct_allocator_probe_audit is not None
        else read_json_if_exists(RESULTS / "rustc_driver_direct_allocator_mir_probe_audit.json")
    )
    cross_thread_hint = rustc_driver_mir_cross_thread_hint_probe_companion_status(
        cross_thread_hint_probe_audit
        if cross_thread_hint_probe_audit is not None
        else read_json_if_exists(RESULTS / "rustc_driver_mir_cross_thread_hint_probe_audit.json")
    )
    blockers = [
        f"semantic-scope probe: {blocker}" for blocker in semantic_scope.get("blockers", [])
    ] + [
        f"direct allocator probe: {blocker}" for blocker in direct_allocator.get("blockers", [])
    ] + [
        f"cross-thread hint probe: {blocker}" for blocker in cross_thread_hint.get("blockers", [])
    ]
    return {
        "ready": (
            semantic_scope.get("ready") is True
            and direct_allocator.get("ready") is True
            and cross_thread_hint.get("ready") is True
        ),
        "semantic_scope_probe": semantic_scope,
        "direct_allocator_probe": direct_allocator,
        "cross_thread_hint_probe": cross_thread_hint,
        "blockers": unique_strings(blockers),
    }


def coverage_evidence_path_value(raw: Any) -> str:
    return platform_evidence_path_value(raw)


def normalize_compiler_coverage_evidence_kind(raw: Any, path_value: str) -> Optional[str]:
    explicit = ""
    if isinstance(raw, dict):
        for key in ("kind", "artifact_kind", "type", "role"):
            value = raw.get(key)
            if value is not None and str(value).strip():
                explicit = str(value).strip()
                break
    candidate = explicit or Path(path_value).name
    text = candidate.lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "event": "coverage_events",
        "events": "coverage_events",
        "coverage": "coverage_events",
        "coverage_event": "coverage_events",
        "coverage_events": "coverage_events",
        "jsonl": "coverage_events",
        "pass": "compiler_pass_log",
        "pass_log": "compiler_pass_log",
        "compiler_pass": "compiler_pass_log",
        "compiler_pass_log": "compiler_pass_log",
        "rustc_log": "compiler_pass_log",
        "llvm_log": "compiler_pass_log",
        "mir_log": "compiler_pass_log",
        "run": "benchmark_run_summary",
        "summary": "benchmark_run_summary",
        "run_summary": "benchmark_run_summary",
        "benchmark_summary": "benchmark_run_summary",
        "benchmark_run_summary": "benchmark_run_summary",
        "type_map": "type_mapping",
        "type_mapping": "type_mapping",
        "typemap": "type_mapping",
        "mapping": "type_mapping",
        "manifest": "type_mapping",
        "build_log": "compiler_invocation",
        "compiler_invocation": "compiler_invocation",
        "rustc_invocation": "compiler_invocation",
    }
    if explicit:
        return aliases.get(text, text)
    if text.endswith(".jsonl") or "coverage" in text and "event" in text:
        return "coverage_events"
    if "pass" in text and (text.endswith(".log") or "compiler" in text or "rustc" in text or "llvm" in text or "mir" in text):
        return "compiler_pass_log"
    if "rustc" in text and text.endswith(".log"):
        return "compiler_pass_log"
    if "llvm" in text and text.endswith(".log"):
        return "compiler_pass_log"
    if "summary" in text and ("run" in text or "benchmark" in text):
        return "benchmark_run_summary"
    if "type" in text and ("map" in text or "mapping" in text):
        return "type_mapping"
    return aliases.get(text)


def compiler_coverage_manifest_events_value(manifest: Dict[str, Any]) -> Optional[str]:
    for key in ("events", "coverage_events", "events_path", "coverage_events_path"):
        value = coverage_manifest_value(manifest, key)
        if value not in (None, "", [], {}):
            return str(value)
    return None


def compiler_coverage_manifest_events_path(manifest: Dict[str, Any], base: Path) -> Optional[Path]:
    value = compiler_coverage_manifest_events_value(manifest)
    if value is None:
        return None
    path = Path(value).expanduser()
    if not path.is_absolute():
        path = base / path
    return path


def compiler_coverage_evidence_records(
    manifest: Dict[str, Any],
    base: Path,
    events_path: Optional[Path],
) -> Tuple[List[Dict[str, Any]], List[str], List[str], List[str], List[str], List[str]]:
    evidence_items = manifest.get("evidence", [])
    if isinstance(evidence_items, (str, dict)):
        evidence_items = [evidence_items]
    if not isinstance(evidence_items, list):
        evidence_items = []
    expanded_items = sample_evidence_entries({"evidence": evidence_items})
    events_value = compiler_coverage_manifest_events_value(manifest)
    if events_path is not None and not any(
        coverage_evidence_path_value(item) in {str(events_path), str(events_value or "")}
        for item in expanded_items
    ):
        expanded_items.append(
            {
                "path": events_value or str(events_path),
                "kind": "coverage_events",
            }
        )

    records: List[Dict[str, Any]] = []
    verified: List[str] = []
    missing: List[str] = []
    placeholder: List[str] = []
    kinds: List[str] = []
    content_blockers: List[str] = []
    seen_record_keys = set()
    claim_requested = coverage_manifest_truthy(
        manifest,
        "claim_grade",
        "complete_for_claim",
    )
    for raw in expanded_items:
        path_value = coverage_evidence_path_value(raw)
        kind = normalize_compiler_coverage_evidence_kind(raw, path_value)
        is_placeholder = is_placeholder_evidence_path(path_value)
        exists, resolved_path, resolved = resolve_platform_evidence_path(path_value, base) if path_value else (False, None, path_value)
        record_key = (resolved, kind)
        if record_key in seen_record_keys:
            continue
        seen_record_keys.add(record_key)
        record = {
            "raw": raw,
            "path": path_value,
            "resolved": resolved,
            "exists": exists,
            "placeholder": is_placeholder,
            "kind": kind,
        }
        declared_sha256 = evidence_declared_sha256(raw)
        if declared_sha256:
            record["declared_sha256"] = declared_sha256
        if exists and resolved_path is not None and resolved_path.is_file():
            computed_sha256 = file_sha256(resolved_path)
            record["sha256"] = computed_sha256
            record_blockers: List[str] = []
            if claim_requested and not declared_sha256:
                record_blockers.append(
                    "claim-grade compiler evidence artifact is missing declared sha256"
                )
            elif declared_sha256:
                if not re.fullmatch(r"[0-9a-f]{64}", declared_sha256):
                    record_blockers.append("declared sha256 is not a valid 64-hex digest")
                elif declared_sha256 != computed_sha256:
                    record_blockers.append(
                        "declared sha256 does not match compiler evidence artifact "
                        f"(declared={declared_sha256}, computed={computed_sha256})"
                    )
                else:
                    record["sha256_verified"] = True
            if record_blockers:
                record["content_blockers"] = unique_strings(record_blockers)
                content_blockers.extend(
                    f"{path_value}: {blocker}"
                    for blocker in record["content_blockers"]
                )
        elif exists and resolved_path is not None:
            content_blockers.append(f"{path_value}: evidence path is not a regular file")
        records.append(record)
        if is_placeholder:
            placeholder.append(path_value)
        if exists and not is_placeholder:
            verified.append(resolved)
            if kind:
                kinds.append(kind)
        elif path_value:
            missing.append(path_value)
    return (
        records,
        unique_strings(verified),
        unique_strings(missing),
        unique_strings(placeholder),
        unique_strings(kinds),
        unique_strings(content_blockers),
    )



