def read_json_or_jsonl(path: Path) -> Any:
    text = path.read_text(encoding="utf-8")
    if path.suffix.lower() == ".jsonl":
        rows = []
        for line_no, line in enumerate(text.splitlines(), start=1):
            if not line.strip():
                continue
            try:
                rows.append(json.loads(line))
            except json.JSONDecodeError as exc:
                raise ValueError(f"{path}:{line_no}: {exc}") from exc
        return rows
    return json.loads(text)


def read_mixed_jsonl_objects(path: Path) -> List[Dict[str, Any]]:
    """Extract JSON object lines from wrapper stdout that may include logs.

    Real benchmark wrappers can intentionally preserve child stdout next to
    their JSON records (for example libtest `test ... bench:` lines).  Claim
    matrix audits need the JSON objects, but those non-JSON benchmark lines are
    still useful raw evidence and should not make the sample path unreadable.
    This helper is deliberately stricter for lines that look like JSON: a
    malformed `{...}` or `[...]` line is still treated as corrupted evidence.
    """

    rows: List[Dict[str, Any]] = []
    for line_no, line in enumerate(path.read_text(encoding="utf-8").splitlines(), start=1):
        stripped = line.strip()
        if not stripped:
            continue
        if stripped[0] not in "{[":
            continue
        try:
            value = json.loads(stripped)
        except json.JSONDecodeError as exc:
            raise ValueError(f"{path}:{line_no}: malformed JSON-looking line in mixed JSONL: {exc}") from exc
        if isinstance(value, dict):
            rows.append(value)
        elif isinstance(value, list) and all(isinstance(item, dict) for item in value):
            rows.extend(value)
        else:
            raise ValueError(f"{path}:{line_no}: expected JSON object or list of objects in mixed JSONL")
    if not rows:
        raise ValueError(f"{path}: no JSON object lines found in mixed JSONL")
    return rows


def string_list_value(value: Any) -> List[str]:
    if isinstance(value, str):
        return [value] if value.strip() else []
    if isinstance(value, dict):
        for key in ("name", "benchmark", "benchmark_name", "target", "id"):
            item = value.get(key)
            if isinstance(item, str) and item.strip():
                return [item]
        return []
    if not isinstance(value, list):
        return []
    values: List[str] = []
    for item in value:
        values.extend(string_list_value(item))
    return unique_strings(values)


def is_synthetic_std_bench_helper(name: str) -> bool:
    text = str(name or "").strip()
    return any(text.startswith(prefix) for prefix in STD_BENCH_SYNTHETIC_BENCHMARK_PREFIXES)


def normalize_benchmark_names(values: Iterable[Any]) -> List[str]:
    names: List[str] = []
    for value in values:
        if not isinstance(value, str):
            continue
        name = value.strip()
        if not name or is_synthetic_std_bench_helper(name):
            continue
        names.append(name)
    return unique_strings(names)


def benchmark_names_from_object(data: Any) -> List[str]:
    if isinstance(data, list):
        names: List[str] = []
        for item in data:
            names.extend(benchmark_names_from_object(item))
        return normalize_benchmark_names(names)
    if not isinstance(data, dict):
        return []
    names: List[str] = []
    for key in ("benchmark", "benchmark_name", "bench_name", "test_name"):
        value = data.get(key)
        if isinstance(value, str) and value.strip():
            names.append(value)
    for key in (
        "expected_benchmarks",
        "observed_benchmarks",
        "benchmarks",
        "bench_results",
        "benchmark_results",
        "benchmark_names",
        "benchmark_list",
        "covered_benchmarks",
        "executed_benchmarks",
        "selected_benchmarks",
        "timing_rows",
        "parsed_timing_rows",
        "targets",
        "cases",
        "tests",
    ):
        value = data.get(key)
        if isinstance(value, (dict, list)):
            names.extend(benchmark_names_from_object(value))
        else:
            names.extend(string_list_value(value))
    return normalize_benchmark_names(names)


def command_names_benchmark_target(command: Any, target: str) -> bool:
    if not isinstance(command, list):
        return False
    parts = [str(part) for part in command]
    for idx, part in enumerate(parts):
        if part == "--bench" and idx + 1 < len(parts) and parts[idx + 1] == target:
            return True
    return target in parts


def latest_complete_std_bench_surface() -> Dict[str, Any]:
    candidates: List[Tuple[float, Path, Dict[str, Any], List[str]]] = []
    for summary_path in RAW.glob("*/std-bench-auto-summary.json"):
        try:
            summary = read_json(summary_path)
        except (OSError, json.JSONDecodeError):
            continue
        if not isinstance(summary, dict):
            continue
        if summary.get("exit_code") != 0:
            continue
        if summary.get("bench_filter"):
            continue
        if summary.get("only_with_sentinels"):
            continue
        if int(summary.get("derived_skip_count") or 0) != 0:
            continue
        if summary.get("skip"):
            continue
        if not command_names_benchmark_target(summary.get("command"), "std_bench"):
            continue
        names = benchmark_names_from_object(summary.get("bench_results") or summary)
        if len(names) < 100:
            continue
        candidates.append((summary_path.stat().st_mtime, summary_path, summary, names))
    if not candidates:
        return {
            "status": "missing",
            "benchmarks": [],
            "source_summary": None,
            "blockers": [
                "no successful unfiltered std_bench auto-metadata summary was found under evaluation/raw"
            ],
        }
    _mtime, summary_path, summary, names = sorted(candidates, key=lambda item: item[0])[-1]
    return {
        "status": "present",
        "benchmarks": names,
        "source_summary": str(summary_path),
        "run_id": summary.get("run_id"),
        "bench_count": len(names),
        "raw_bench_result_count": len(summary.get("bench_results") or []),
        "excluded_synthetic_prefixes": list(STD_BENCH_SYNTHETIC_BENCHMARK_PREFIXES),
        "blockers": [],
    }


def exact_dynamic_std_bench_surface_status(
    observed_benchmarks: Iterable[Any],
    *,
    bench_filter: Any = None,
    skip: Any = None,
    only_with_sentinels: Any = None,
    derived_skip_count: int = 0,
) -> Dict[str, Any]:
    """Compare an exact-dynamic generated std_bench run against the canonical surface.

    This intentionally does not make the generated target claim-grade.  It gives
    the dynamic-attribution audit a precise distinction between a filtered slice
    and an unfiltered full-surface *candidate* that still needs production
    compiler-pass/no-source-change provenance before C002 import.
    """

    reference = latest_complete_std_bench_surface()
    expected = normalize_benchmark_names(reference.get("benchmarks") or [])
    observed = normalize_benchmark_names(observed_benchmarks)
    try:
        derived_skips = int(derived_skip_count or 0)
    except (TypeError, ValueError):
        derived_skips = 0
    skip_values = string_list_value(skip)
    filter_options_present = bool(
        bench_filter
        or skip_values
        or only_with_sentinels
        or derived_skips
    )
    expected_set = set(expected)
    observed_set = set(observed)
    missing = sorted(expected_set - observed_set) if expected else []
    unexpected = sorted(observed_set - expected_set) if expected else []
    full_surface_candidate = bool(
        expected
        and reference.get("status") == "present"
        and not filter_options_present
        and not missing
        and len(observed_set) >= len(expected_set)
    )
    blockers: List[str] = []
    if reference.get("status") != "present" or not expected:
        blockers.extend(string_list_value(reference.get("blockers")) or ["canonical std_bench surface is unavailable"])
    if filter_options_present:
        blockers.append("run used libtest filters, skips, or sentinel-only selection")
    if missing:
        blockers.append("run is missing canonical std_bench benchmarks: " + ", ".join(missing[:8]))
    if not observed:
        blockers.append("run reported no non-synthetic benchmark names")
    return {
        "status": "full-surface-candidate" if full_surface_candidate else "slice-or-incomplete",
        "full_surface_candidate": full_surface_candidate,
        "canonical_surface_status": reference.get("status"),
        "canonical_surface_summary": reference.get("source_summary"),
        "canonical_surface_run_id": reference.get("run_id"),
        "expected_benchmarks": expected,
        "observed_benchmarks": observed,
        "expected_benchmark_count": len(expected),
        "observed_benchmark_count": len(observed),
        "missing_expected_benchmarks": missing,
        "missing_expected_benchmark_count": len(missing),
        "unexpected_observed_benchmarks": unexpected,
        "unexpected_observed_benchmark_count": len(unexpected),
        "filter_options_present": filter_options_present,
        "bench_filter": bench_filter,
        "skip": skip_values,
        "only_with_sentinels": only_with_sentinels,
        "derived_skip_count": derived_skips,
        "blockers": unique_strings(blockers),
    }


def select_std_bench_runtime_targets(
    bench_list: Iterable[str],
    *,
    bench_patterns: Optional[Iterable[str]] = None,
    explicit_benchmarks: Optional[Iterable[str]] = None,
    default_bench_patterns: Optional[Iterable[str]] = None,
    full_surface: bool = False,
    shard_index: Optional[int] = None,
    shard_count: Optional[int] = None,
    shard_offset: Optional[int] = None,
    max_benchmarks: Optional[int] = None,
    sentinel_prefixes: Tuple[str, ...] = STD_BENCH_AUTO_METADATA_SENTINEL_PREFIXES,
) -> Dict[str, Any]:
    """Select real std_bench targets while keeping setup/report sentinels.

    The C002 MIR-semantic-scope path needs more than a hard-coded smoke.  This
    helper centralizes the selection rules so the same command can run:

    * an explicit list of exact benchmarks,
    * a small pattern-based smoke,
    * a deterministic shard of the full canonical bench list, or
    * the whole runtime surface when the operator is ready for a long run.

    The helper intentionally returns both selected targets and derived skips:
    libtest still performs the execution filtering, while the audit records
    exactly which benchmarks were excluded.
    """

    ordered_benches = unique_strings(str(bench).strip() for bench in bench_list if str(bench).strip())
    sentinel_benches = sorted(
        bench for bench in ordered_benches if bench.startswith(sentinel_prefixes)
    )
    target_benches = sorted(
        bench for bench in ordered_benches if not bench.startswith(sentinel_prefixes)
    )
    normalized_patterns = sorted(
        pattern
        for pattern in unique_strings(bench_patterns or [])
        if str(pattern).strip()
    )
    normalized_explicit_benchmarks = unique_strings(
        str(bench).strip() for bench in (explicit_benchmarks or []) if str(bench).strip()
    )
    target_set = set(target_benches)
    unknown_explicit = sorted(bench for bench in normalized_explicit_benchmarks if bench not in target_set)
    if unknown_explicit:
        raise ValueError(
            "--benchmarks references unknown std_bench target(s): " + ", ".join(unknown_explicit[:8])
        )
    if normalized_explicit_benchmarks:
        selected_targets = list(normalized_explicit_benchmarks)
        selection_mode = "explicit-benchmarks"
    elif full_surface:
        selected_targets = list(target_benches)
        selection_mode = "full-surface"
    elif not normalized_patterns:
        normalized_patterns = sorted(
            pattern
            for pattern in unique_strings(default_bench_patterns or [])
            if str(pattern).strip()
        )
        selected_targets = [
            bench
            for bench in target_benches
            if any(pattern in bench for pattern in normalized_patterns)
        ]
        selection_mode = "pattern-smoke"
    else:
        selected_targets = [
            bench
            for bench in target_benches
            if any(pattern in bench for pattern in normalized_patterns)
        ]
        selection_mode = "pattern-smoke"

    try:
        parsed_shard_count = int(shard_count) if shard_count not in (None, "") else None
    except (TypeError, ValueError) as exc:
        raise ValueError(f"invalid shard_count: {shard_count!r}") from exc
    try:
        parsed_shard_index = int(shard_index) if shard_index not in (None, "") else None
    except (TypeError, ValueError) as exc:
        raise ValueError(f"invalid shard_index: {shard_index!r}") from exc
    if parsed_shard_count is not None:
        if parsed_shard_count <= 0:
            raise ValueError("--shard-count must be positive")
        if parsed_shard_index is None:
            parsed_shard_index = 0
        if parsed_shard_index < 0 or parsed_shard_index >= parsed_shard_count:
            raise ValueError("--shard-index must satisfy 0 <= index < shard-count")
        selected_targets = [
            bench
            for idx, bench in enumerate(selected_targets)
            if idx % parsed_shard_count == parsed_shard_index
        ]
        if normalized_explicit_benchmarks:
            selection_mode = "explicit-benchmarks-shard"
        elif full_surface:
            selection_mode = "full-surface-shard"
        else:
            selection_mode = "pattern-shard"
    elif parsed_shard_index is not None:
        raise ValueError("--shard-index requires --shard-count")

    try:
        parsed_shard_offset = int(shard_offset) if shard_offset not in (None, "") else 0
    except (TypeError, ValueError) as exc:
        raise ValueError(f"invalid shard_offset: {shard_offset!r}") from exc
    if parsed_shard_offset < 0:
        raise ValueError("--shard-offset must be non-negative")
    if parsed_shard_offset:
        selected_targets = selected_targets[parsed_shard_offset:]
        selection_mode = selection_mode + "-offset"

    try:
        parsed_max_benchmarks = int(max_benchmarks) if max_benchmarks not in (None, "") else None
    except (TypeError, ValueError) as exc:
        raise ValueError(f"invalid max_benchmarks: {max_benchmarks!r}") from exc
    if parsed_max_benchmarks is not None:
        if parsed_max_benchmarks <= 0:
            raise ValueError("--max-benchmarks must be positive")
        if len(selected_targets) > parsed_max_benchmarks:
            selected_targets = selected_targets[:parsed_max_benchmarks]
            selection_mode = selection_mode + "-capped"

    selected_benches = sorted(set(sentinel_benches + selected_targets))
    selected_set = set(selected_benches)
    derived_skips = [bench for bench in ordered_benches if bench not in selected_set]
    return {
        "selection_mode": selection_mode,
        "bench_patterns": normalized_patterns,
        "explicit_benchmarks": normalized_explicit_benchmarks,
        "sentinel_benches": sentinel_benches,
        "target_benches": target_benches,
        "selected_benches": selected_benches,
        "selected_target_benches": selected_targets,
        "derived_skips": derived_skips,
        "shard_index": parsed_shard_index,
        "shard_count": parsed_shard_count,
        "shard_offset": parsed_shard_offset,
        "max_benchmarks": parsed_max_benchmarks,
        "full_surface_requested": bool(full_surface),
    }


def libtest_exact_filter_args(selected_benches: Iterable[Any]) -> List[str]:
    """Return libtest args that run exactly the selected benchmarks.

    libtest's `--skip` and positional filters default to substring matching.
    That is unsafe for std_bench names such as `btree::set::clone_100` and
    `btree::set::clone_100_and_remove_half`: skipping the former also skips the
    latter.  Exact positive filters keep sentinel + target selection faithful
    without constructing a large, prefix-fragile skip list.
    """

    filters = unique_strings(str(bench).strip() for bench in selected_benches if str(bench).strip())
    return ["--exact", *filters] if filters else []


def normalize_std_bench_libtest_mode(value: Any) -> str:
    """Normalize the std_bench runtime execution mode.

    ``bench`` preserves the historical ``cargo bench`` behavior and lets
    libtest calibrate each benchmark for performance measurement.  ``test-once``
    runs the same ``#[bench]`` functions through libtest's benchmark-as-test
    path, where ``Bencher::iter`` executes once.  The latter is intended only
    for runtime coverage/typing evidence: it still compiles and executes the
    real std_bench target under the rustc_driver wrapper, but avoids spending a
    performance-calibration budget when the claim gate only needs allocation
    coverage.
    """

    mode = str(value or "bench").strip().lower().replace("_", "-")
    aliases = {
        "bench": "bench",
        "benchmark": "bench",
        "cargo-bench": "bench",
        "test": "test-once",
        "test-once": "test-once",
        "once": "test-once",
        "run-once": "test-once",
        "coverage": "test-once",
        "coverage-once": "test-once",
    }
    if mode not in aliases:
        raise ValueError("--libtest-mode must be one of: bench, test-once")
    return aliases[mode]


def std_bench_runtime_libtest_args(
    selected_benches: Iterable[Any],
    *,
    libtest_mode: str,
) -> List[str]:
    """Return libtest args for the selected real std_bench runtime mode."""

    args = ["--nocapture"]
    if normalize_std_bench_libtest_mode(libtest_mode) == "test-once":
        # libtest otherwise runs converted bench-as-test functions in parallel,
        # which can race the aaa/zzz semantic metadata sentinel benches.  A
        # single worker preserves sorted execution order: enable -> targets ->
        # report, while still exercising real bench bodies.
        args.append("--test-threads=1")
    args.extend(libtest_exact_filter_args(selected_benches))
    return args


def split_std_bench_benchmark_request_values(values: Iterable[Any]) -> List[str]:
    """Normalize comma/newline separated std_bench benchmark names."""

    benches: List[str] = []
    for raw in values or []:
        if raw is None:
            continue
        for line in str(raw).splitlines():
            for token in line.split(","):
                bench = token.strip()
                if bench:
                    benches.append(bench)
    return unique_strings(benches)


def load_std_bench_benchmark_requests(
    values: Optional[Iterable[Any]] = None,
    files: Optional[Iterable[Any]] = None,
) -> List[str]:
    """Load exact benchmark requests from CLI values and text/JSON files."""

    benches = split_std_bench_benchmark_request_values(values or [])
    for raw_path in files or []:
        if raw_path is None or not str(raw_path).strip():
            continue
        path = Path(str(raw_path)).expanduser()
        text = path.read_text(encoding="utf-8")
        loaded: Any = None
        try:
            loaded = json.loads(text)
        except json.JSONDecodeError:
            loaded = None
        if isinstance(loaded, list):
            benches.extend(split_std_bench_benchmark_request_values(loaded))
        elif isinstance(loaded, dict):
            candidate_values: List[Any] = []
            for key in ("benchmarks", "selected_benchmarks", "selected_target_benches", "missing_benchmarks"):
                value = loaded.get(key)
                if isinstance(value, list):
                    candidate_values.extend(value)
            benches.extend(split_std_bench_benchmark_request_values(candidate_values))
        else:
            benches.extend(split_std_bench_benchmark_request_values([text]))
    return unique_strings(benches)


def load_std_bench_recommended_batch_requests(
    plan_files: Optional[Iterable[Any]] = None,
    batch_index: int = 0,
    batch_count: int = 1,
) -> List[str]:
    """Load exact benchmark names from planner recommended batch records.

    This is intentionally separate from --benchmark-file: passing a full shard
    plan to --benchmark-file would select every missing benchmark, while this
    helper selects one or more bounded recommended batches for real incremental
    runtime validation.
    """

    try:
        parsed_batch_index = int(batch_index or 0)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"invalid recommended batch index: {batch_index!r}") from exc
    if parsed_batch_index < 0:
        raise ValueError("--recommended-batch-index must be non-negative")
    try:
        parsed_batch_count = int(batch_count or 1)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"invalid recommended batch count: {batch_count!r}") from exc
    if parsed_batch_count <= 0:
        raise ValueError("--recommended-batch-count must be positive")

    benches: List[str] = []
    for raw_path in plan_files or []:
        if raw_path is None or not str(raw_path).strip():
            continue
        path = Path(str(raw_path)).expanduser()
        plan = read_json(path)
        if not isinstance(plan, dict):
            raise ValueError(f"{path} is not a JSON object")
        recommended = plan.get("recommended_shards")
        if not isinstance(recommended, list):
            recommended = plan.get("recommended_commands")
        if not isinstance(recommended, list):
            raise ValueError(f"{path} does not contain recommended_shards/recommended_commands")
        if parsed_batch_index >= len(recommended):
            raise ValueError(
                f"{path} has {len(recommended)} recommended batches; "
                f"index {parsed_batch_index} is out of range"
            )
        end_index = parsed_batch_index + parsed_batch_count
        if end_index > len(recommended):
            raise ValueError(
                f"{path} has {len(recommended)} recommended batches; "
                f"range {parsed_batch_index}..{end_index - 1} is out of range"
            )
        for record_index in range(parsed_batch_index, end_index):
            record = recommended[record_index]
            if not isinstance(record, dict):
                raise ValueError(f"{path}: recommended batch {record_index} is not an object")
            batch_values: List[Any] = []
            for key in ("missing_benchmarks", "benchmarks", "selected_target_benches"):
                value = record.get(key)
                if isinstance(value, list):
                    batch_values.extend(value)
            if not batch_values:
                raise ValueError(f"{path}: recommended batch {record_index} has no benchmark list")
            benches.extend(split_std_bench_benchmark_request_values(batch_values))
    return unique_strings(benches)


def std_bench_adaptive_batches(
    benchmarks: Iterable[Any],
    *,
    batch_size: int,
    max_batches: Optional[int] = None,
) -> List[List[str]]:
    """Split benchmark names into bounded batches for adaptive real runs."""

    try:
        parsed_batch_size = int(batch_size)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"invalid adaptive batch size: {batch_size!r}") from exc
    if parsed_batch_size <= 0:
        raise ValueError("--batch-size must be positive")
    parsed_max_batches: Optional[int] = None
    if max_batches is not None:
        try:
            parsed_max_batches = int(max_batches)
        except (TypeError, ValueError) as exc:
            raise ValueError(f"invalid adaptive max batches: {max_batches!r}") from exc
        if parsed_max_batches <= 0:
            raise ValueError("--max-batches must be positive when provided")
    normalized = split_std_bench_benchmark_request_values(benchmarks)
    batches = [
        normalized[start : start + parsed_batch_size]
        for start in range(0, len(normalized), parsed_batch_size)
    ]
    if parsed_max_batches is not None:
        batches = batches[:parsed_max_batches]
    return batches


def std_bench_adaptive_child_run_id(parent_run_id: Any, tag: Any, benchmarks: Iterable[Any]) -> str:
    """Build a stable bounded child run id for an adaptive real collector run."""

    batch = split_std_bench_benchmark_request_values(benchmarks)
    digest_source = json.dumps(batch, sort_keys=True, separators=(",", ":"))
    digest = hashlib.sha256(digest_source.encode("utf-8")).hexdigest()[:10]
    parent = slugify_label(parent_run_id, "adaptive")[:58].rstrip("-._") or "adaptive"
    tag_slug = slugify_label(tag, "batch")[:14].rstrip("-._") or "batch"
    first = slugify_label(batch[0] if batch else "empty", "empty")[:10].rstrip("-._") or "empty"
    return slugify_label(f"{parent}-{tag_slug}-n{len(batch)}-{first}-{digest}", "adaptive-child")


def bounded_digest_run_id(prefix: Any, suffix: Any, salt: Any, *, limit: int = 96) -> str:
    """Return a bounded run id that keeps a human suffix and a collision guard."""

    digest_source = json.dumps(
        {"prefix": str(prefix or ""), "suffix": str(suffix or ""), "salt": str(salt or "")},
        sort_keys=True,
        separators=(",", ":"),
    )
    digest = hashlib.sha256(digest_source.encode("utf-8")).hexdigest()[:10]
    suffix_slug = slugify_label(suffix, "step")[:18].rstrip("-._") or "step"
    reserve = len(suffix_slug) + len(digest) + 2
    prefix_limit = max(8, int(limit) - reserve)
    prefix_slug = slugify_label(prefix, "run")[:prefix_limit].rstrip("-._") or "run"
    return slugify_label(f"{prefix_slug}-{suffix_slug}-{digest}", "run")


def compiler_benchmark_summary_records(records: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    summaries: List[Dict[str, Any]] = []
    for record in records:
        if record.get("kind") != "benchmark_run_summary":
            continue
        summary_record = {
            "path": record.get("resolved") or record.get("path"),
            "exists": bool(record.get("exists")),
            "placeholder": bool(record.get("placeholder")),
            "parse_error": None,
            "exit_code": None,
            "benchmark_names": [],
        }
        summaries.append(summary_record)
        if record.get("placeholder") or not record.get("exists"):
            continue
        resolved = str(record.get("resolved") or "")
        if is_uri(resolved):
            summary_record["parse_error"] = "benchmark_run_summary URI evidence is not machine-auditable by this local evaluator"
            continue
        path = Path(resolved)
        try:
            data = read_json_or_jsonl(path)
        except (OSError, json.JSONDecodeError, ValueError) as exc:
            summary_record["parse_error"] = str(exc)
            continue
        if isinstance(data, dict):
            for key in ("exit_code", "returncode", "return_code", "status_code"):
                if data.get(key) is not None:
                    summary_record["exit_code"] = data.get(key)
                    break
        summary_record["benchmark_names"] = benchmark_names_from_object(data)
    return summaries


def compiler_coverage_benchmark_surface_audit(
    manifest: Dict[str, Any],
    records: List[Dict[str, Any]],
) -> Dict[str, Any]:
    suite = coverage_manifest_value(manifest, "benchmark_suite")
    blockers: List[str] = []
    expected: List[str] = []
    observed: List[str] = []
    missing_expected: List[str] = []
    present_unexpected: List[str] = []
    without_source_changes = coverage_manifest_truthy(manifest, "without_source_changes")
    suite_complete_for_claim = coverage_manifest_truthy(manifest, "complete_for_claim", "paper_equivalent")
    benchmark_target = None
    observed_source = None
    suite_text = ""

    if not isinstance(suite, dict):
        blockers.append("benchmark_suite metadata must be an object describing the full C002 benchmark surface")
    else:
        expected = normalize_benchmark_names(
            string_list_value(suite.get("expected_benchmarks"))
            or string_list_value(suite.get("required_benchmarks"))
            or string_list_value(suite.get("benchmark_names"))
        )
        observed = normalize_benchmark_names(
            string_list_value(suite.get("observed_benchmarks"))
            or string_list_value(suite.get("covered_benchmarks"))
            or string_list_value(suite.get("executed_benchmarks"))
        )
        without_source_changes = without_source_changes or suite.get("without_source_changes") is True
        suite_complete_for_claim = (
            suite_complete_for_claim
            or suite.get("complete_for_claim") is True
            or suite.get("paper_equivalent") is True
        )
        benchmark_target = suite.get("benchmark_target") or suite.get("target") or suite.get("name")
        observed_source = suite.get("observed_benchmark_source")
        suite_text = json.dumps(suite, sort_keys=True, default=str).lower()
        marker_hits = [marker for marker in COMPILER_COVERAGE_NON_FULL_SURFACE_MARKERS if marker in suite_text]
        if marker_hits:
            blockers.append(
                "benchmark_suite metadata indicates non-full benchmark surface: "
                + ", ".join(marker_hits[:4])
            )
        if not without_source_changes:
            blockers.append("benchmark_suite must explicitly run without source changes")
        if not suite_complete_for_claim:
            blockers.append("benchmark_suite must explicitly be complete_for_claim or paper_equivalent")
        target_text = " ".join(
            str(suite.get(key) or "")
            for key in ("benchmark_target", "expected_benchmark_target", "observed_benchmark_target", "target", "name")
        ).lower()
        if "std_bench" not in target_text and "standard rust alloc" not in target_text and "paper_equivalent" not in target_text:
            blockers.append("benchmark_suite must name the std_bench or paper-equivalent Rust alloc benchmark target")
        if not expected:
            blockers.append("benchmark_suite must list expected_benchmarks for the full C002 benchmark surface")
        if observed and isinstance(observed_source, dict):
            source_text = json.dumps(observed_source, sort_keys=True, default=str).lower()
            source_marker_hits = [
                marker for marker in COMPILER_COVERAGE_NON_CLAIM_OBSERVED_SURFACE_MARKERS if marker in source_text
            ]
            if observed_source.get("compiler_instrumented") is False or source_marker_hits:
                blockers.append(
                    "observed_benchmarks source must be the compiler-instrumented C002 run, not a non-claim reference surface"
                )

    run_summaries = compiler_benchmark_summary_records(records)
    for summary in run_summaries:
        observed.extend(string_list_value(summary.get("benchmark_names")))
    observed = normalize_benchmark_names(observed)
    if not observed:
        blockers.append("benchmark_suite must list observed_benchmarks or provide them in benchmark_run_summary evidence")
        if expected:
            missing_expected = sorted(expected)
    if expected and observed:
        expected_set = set(expected)
        observed_set = set(observed)
        missing_expected = sorted(expected_set - observed_set)
        present_unexpected = sorted(observed_set - expected_set)
        if missing_expected:
            blockers.append(
                "benchmark surface is missing expected benchmarks: "
                + ", ".join(missing_expected[:8])
            )
    parse_errors = [str(item.get("parse_error")) for item in run_summaries if item.get("parse_error")]
    if parse_errors:
        blockers.append(f"benchmark_run_summary evidence has parse errors: {parse_errors[0]}")
    nonzero_exit = []
    for summary in run_summaries:
        exit_code = summary.get("exit_code")
        if exit_code in (None, ""):
            continue
        try:
            if int(exit_code) != 0:
                nonzero_exit.append({"path": summary.get("path"), "exit_code": exit_code})
        except (TypeError, ValueError):
            nonzero_exit.append({"path": summary.get("path"), "exit_code": exit_code})
    if nonzero_exit:
        blockers.append("benchmark_run_summary evidence contains nonzero exit status")

    return {
        "status": "pass" if not unique_strings(blockers) else "fail",
        "required_fields": list(COMPILER_COVERAGE_REQUIRED_BENCHMARK_SURFACE_FIELDS),
        "benchmark_target": benchmark_target,
        "observed_benchmark_source": observed_source,
        "without_source_changes": bool(without_source_changes),
        "complete_for_claim_or_paper_equivalent": bool(suite_complete_for_claim),
        "expected_benchmarks": expected,
        "observed_benchmarks": observed,
        "missing_expected_benchmarks": missing_expected,
        "unexpected_observed_benchmarks": present_unexpected,
        "run_summary_count": len(run_summaries),
        "run_summary_parse_error_count": len(parse_errors),
        "run_summary_nonzero_exit_count": len(nonzero_exit),
        "run_summaries": run_summaries,
        "blockers": unique_strings(blockers),
    }


def mapping_rows_from_json(data: Any) -> List[Dict[str, Any]]:
    if isinstance(data, list):
        return [row for row in data if isinstance(row, dict)]
    if not isinstance(data, dict):
        return []
    for key in TYPE_MAPPING_COLLECTION_KEYS:
        value = data.get(key)
        if isinstance(value, list):
            return [row for row in value if isinstance(row, dict)]
        if isinstance(value, dict):
            return [dict({"mapping_key": k}, **v) for k, v in value.items() if isinstance(v, dict)]
    inferred = data.get("inferred_rust_types")
    if isinstance(inferred, dict):
        return [
            {
                "source_inferred_scope": key,
                "source_inferred_rust_type": value,
                "provenance": data.get("generator") or data.get("source") or "source-inferred",
            }
            for key, value in inferred.items()
        ]
    if isinstance(inferred, list):
        rows = []
        for idx, value in enumerate(inferred):
            if isinstance(value, dict):
                rows.append(value)
            else:
                rows.append({"source_inferred_scope": idx, "source_inferred_rust_type": value})
        return rows
    dict_values = [value for value in data.values() if isinstance(value, dict)]
    if dict_values and any(any(key in value for key in TYPE_MAPPING_TYPE_ID_KEYS + TYPE_MAPPING_OBJECT_TYPE_KEYS) for value in dict_values):
        return dict_values
    return [data]


def value_is_present(value: Any) -> bool:
    if value in (None, "", [], {}):
        return False
    if isinstance(value, str) and not value.strip():
        return False
    return True


def find_mapping_field(row: Dict[str, Any], keys: List[str]) -> Tuple[Optional[Any], Optional[str]]:
    for key in keys:
        value = row.get(key)
        if value_is_present(value):
            return value, key
    for container in TYPE_MAPPING_NESTED_CONTAINERS:
        nested = row.get(container)
        if not isinstance(nested, dict):
            continue
        for key in keys:
            value = nested.get(key)
            if value_is_present(value):
                return value, f"{container}.{key}"
    return None, None


def mapping_text_has_placeholder(row: Dict[str, Any]) -> bool:
    text = json.dumps(row, sort_keys=True, default=str)
    lowered = text.lower()
    return (
        "path/to/" in lowered
        or "replace-me" in lowered
        or "placeholder" in lowered
        or "todo" in lowered
        or "fill real" in lowered
    )


def compiler_mapping_marker(text: str) -> Optional[str]:
    lowered = text.lower()
    for marker in COMPILER_COVERAGE_PROTOTYPE_MARKERS:
        if marker == "ffi":
            if re.search(r"(^|[^a-z0-9])ffi([^a-z0-9]|$)", lowered):
                return marker
            continue
        if marker in lowered:
            return marker
    if "source_inferred" in lowered or "source-inferred" in lowered:
        return "source-inferred"
    return None


def audit_compiler_type_mapping_evidence(
    manifest: Dict[str, Any],
    records: List[Dict[str, Any]],
) -> Dict[str, Any]:
    mapping_records = [record for record in records if record.get("kind") == "type_mapping"]
    claim_requested = coverage_manifest_truthy(manifest, "claim_grade", "complete_for_claim")
    type_id_basis = str(coverage_manifest_value(manifest, "type_id_basis") or "")
    manifest_pass_text = json.dumps(coverage_manifest_value(manifest, "compiler_pass"), sort_keys=True, default=str)
    manifest_marker = compiler_mapping_marker(" ".join([manifest_pass_text, type_id_basis]))

    artifacts: List[Dict[str, Any]] = []
    blockers: List[str] = []
    total_rows = 0
    valid_rows = 0
    placeholder_rows = 0
    source_inferred_rows = 0
    valid_type_ids: List[int] = []
    valid_type_id_callsite_pairs: List[Dict[str, int]] = []
    missing_counts = {
        "allocation_site_id": 0,
        "type_id": 0,
        "object_type": 0,
        "source_or_mir_location": 0,
        "compiler_pass_provenance": 0,
    }
    provenance_markers: List[str] = []
    parse_errors: List[str] = []

    if not mapping_records:
        blockers.append("missing type_mapping evidence artifact")

    for record in mapping_records:
        artifact = {
            "path": record.get("resolved") or record.get("path"),
            "exists": bool(record.get("exists")),
            "placeholder": bool(record.get("placeholder")),
            "record_count": 0,
            "valid_record_count": 0,
            "source_inferred_record_count": 0,
            "placeholder_record_count": 0,
            "parse_error": None,
        }
        artifacts.append(artifact)
        if record.get("placeholder") or not record.get("exists"):
            continue
        resolved = str(record.get("resolved") or "")
        if is_uri(resolved):
            artifact["parse_error"] = "type_mapping URI evidence is not machine-auditable by this local evaluator"
            parse_errors.append(str(artifact["parse_error"]))
            continue
        path = Path(resolved)
        try:
            data = read_json_or_jsonl(path)
        except (OSError, json.JSONDecodeError, ValueError) as exc:
            artifact["parse_error"] = str(exc)
            parse_errors.append(str(exc))
            continue
        artifact_marker = compiler_mapping_marker(json.dumps(data, sort_keys=True, default=str))
        if artifact_marker:
            provenance_markers.append(artifact_marker)
        rows = mapping_rows_from_json(data)
        artifact["record_count"] = len(rows)
        for row in rows:
            total_rows += 1
            allocation_site, _ = find_mapping_field(row, TYPE_MAPPING_ALLOCATION_SITE_KEYS)
            type_id, _ = find_mapping_field(row, TYPE_MAPPING_TYPE_ID_KEYS)
            callsite, _ = find_mapping_field(row, TYPE_MAPPING_CALLSITE_KEYS)
            object_type, _ = find_mapping_field(row, TYPE_MAPPING_OBJECT_TYPE_KEYS)
            location, _ = find_mapping_field(row, TYPE_MAPPING_LOCATION_KEYS)
            provenance, _ = find_mapping_field(row, TYPE_MAPPING_PROVENANCE_KEYS)
            provenance = provenance or coverage_manifest_value(manifest, "compiler_pass")
            row_marker = compiler_mapping_marker(json.dumps(row, sort_keys=True, default=str))
            if row_marker:
                provenance_markers.append(row_marker)
            if "source_inferred" in row or "source_inferred_rust_type" in row or "source_inferred_scope" in row:
                source_inferred_rows += 1
                artifact["source_inferred_record_count"] = int(artifact["source_inferred_record_count"]) + 1
            if mapping_text_has_placeholder(row):
                placeholder_rows += 1
                artifact["placeholder_record_count"] = int(artifact["placeholder_record_count"]) + 1
            missing = []
            if not value_is_present(allocation_site):
                missing.append("allocation_site_id")
            if not value_is_present(type_id):
                missing.append("type_id")
            if not value_is_present(object_type):
                missing.append("object_type")
            if not value_is_present(location):
                missing.append("source_or_mir_location")
            if not value_is_present(provenance):
                missing.append("compiler_pass_provenance")
            for key in missing:
                missing_counts[key] += 1
            if not missing and not mapping_text_has_placeholder(row) and not row_marker:
                valid_rows += 1
                artifact["valid_record_count"] = int(artifact["valid_record_count"]) + 1
                parsed_type_id = parse_json_int_or_zero(type_id)
                if parsed_type_id > 0:
                    valid_type_ids.append(parsed_type_id)
                parsed_pair = type_id_callsite_pair_from_mapping_row(row)
                if parsed_pair is not None:
                    valid_type_id_callsite_pairs.append(
                        {"type_id": parsed_pair[0], "callsite": parsed_pair[1]}
                    )

    if parse_errors:
        blockers.append(f"type_mapping evidence has parse errors: {parse_errors[0]}")
    if mapping_records and not any(artifact.get("exists") and not artifact.get("placeholder") for artifact in artifacts):
        blockers.append("type_mapping evidence must be concrete local JSON/JSONL, not missing or placeholder paths")
    if total_rows <= 0 and mapping_records:
        blockers.append("type_mapping evidence contains no mapping records")
    if total_rows > 0 and valid_rows <= 0:
        blockers.append(
            "type_mapping evidence contains no compiler allocation-site rows with allocation_site_id, type_id, object_type, location, and compiler_pass provenance"
        )
    if source_inferred_rows:
        blockers.append(
            "type_mapping evidence still exposes source-inferred Rust type scopes instead of compiler allocation-site object mappings"
        )
    if placeholder_rows:
        blockers.append(f"type_mapping evidence contains placeholder rows: {placeholder_rows}")
    present_missing = {key: count for key, count in missing_counts.items() if count}
    if present_missing:
        blockers.append(
            "type_mapping records are missing required fields: "
            + ", ".join(f"{key}={count}" for key, count in present_missing.items())
        )
    provenance_markers = unique_strings(provenance_markers)
    if manifest_marker and valid_rows <= 0:
        provenance_markers = unique_strings([manifest_marker, *provenance_markers])
    if provenance_markers:
        blockers.append(
            "type_mapping provenance still indicates non-compiler/prototype data: "
            + ", ".join(provenance_markers)
        )
    if claim_requested and total_rows > 0 and valid_rows != total_rows:
        blockers.append(
            f"claim-grade type_mapping requires every row to be compiler allocation-site typed; valid={valid_rows} total={total_rows}"
        )
    if coverage_basis_is_compiler_assigned(type_id_basis) and valid_rows <= 0:
        blockers.append(
            "compiler-assigned type_id_basis requires machine-auditable allocation-site type_mapping rows"
        )

    return {
        "status": "pass" if not unique_strings(blockers) else "fail",
        "artifact_count": len(mapping_records),
        "artifacts": artifacts,
        "record_count": total_rows,
        "valid_record_count": valid_rows,
        "valid_type_id_count": len(set(valid_type_ids)),
        "valid_type_ids": sorted(set(valid_type_ids)),
        "valid_type_ids_sample": sorted(set(valid_type_ids))[:256],
        "valid_type_id_callsite_pair_count": len(
            {(pair["type_id"], pair["callsite"]) for pair in valid_type_id_callsite_pairs}
        ),
        "valid_type_id_callsite_pairs": [
            {"type_id": type_id, "callsite": callsite}
            for type_id, callsite in sorted(
                {(pair["type_id"], pair["callsite"]) for pair in valid_type_id_callsite_pairs}
            )
        ],
        "invalid_record_count": max(0, total_rows - valid_rows),
        "source_inferred_record_count": source_inferred_rows,
        "placeholder_record_count": placeholder_rows,
        "missing_field_counts": missing_counts,
        "provenance_markers": provenance_markers,
        "blockers": unique_strings(blockers),
    }


def audit_compiler_event_type_mapping_correlation(
    manifest: Dict[str, Any],
    event_stats: Dict[str, Any],
    type_mapping_audit: Dict[str, Any],
    type_id_basis: str,
) -> Dict[str, Any]:
    """Verify dynamic per-site events are backed by machine-auditable type mapping rows."""

    event_type_ids = {int(value) for value in event_stats.get("per_type_event_type_ids", []) if int(value) > 0}
    mapping_type_ids = {int(value) for value in type_mapping_audit.get("valid_type_ids", []) if int(value) > 0}
    event_pairs = {
        (parse_json_int_or_zero(pair.get("type_id")), parse_json_int_or_zero(pair.get("callsite")))
        for pair in event_stats.get("per_type_event_type_id_callsite_pairs", [])
        if isinstance(pair, dict)
    }
    event_pairs = {(type_id, callsite) for type_id, callsite in event_pairs if type_id > 0 and callsite}
    mapping_pairs = {
        (parse_json_int_or_zero(pair.get("type_id")), parse_json_int_or_zero(pair.get("callsite")))
        for pair in type_mapping_audit.get("valid_type_id_callsite_pairs", [])
        if isinstance(pair, dict)
    }
    mapping_pairs = {(type_id, callsite) for type_id, callsite in mapping_pairs if type_id > 0 and callsite}
    claim_requested = coverage_manifest_truthy(manifest, "claim_grade", "complete_for_claim")
    requires_per_type_events = coverage_manifest_truthy(manifest, "requires_per_type_events")
    compiler_assigned = coverage_basis_is_compiler_assigned(type_id_basis)
    bridge_bases = [
        basis
        for basis in event_stats.get("event_type_id_bases", [])
        if coverage_basis_is_runtime_bridge(str(basis or ""))
    ]
    strict_per_type_required = bool(
        requires_per_type_events
        or (
            claim_requested
            and compiler_assigned
            and not bridge_bases
            and int(event_stats.get("compiler_site_replay_events") or 0) == 0
        )
    )

    blockers: List[str] = []
    if strict_per_type_required and int(event_stats.get("per_type_event_count") or 0) <= 0:
        blockers.append(
            "compiler-assigned exact-dynamic coverage must include per-allocation-site typed_allocation_site events"
        )
    if event_type_ids and not mapping_type_ids:
        blockers.append("typed_allocation_site events exist but type_mapping audit has no valid type_id rows")
    missing_from_mapping = sorted(event_type_ids - mapping_type_ids)
    if missing_from_mapping:
        blockers.append(
            "typed_allocation_site event type_ids are absent from type_mapping evidence: "
            + ", ".join(str(value) for value in missing_from_mapping[:8])
        )
    missing_pairs_from_mapping = sorted(event_pairs - mapping_pairs)
    if missing_pairs_from_mapping:
        blockers.append(
            "typed_allocation_site event (type_id, callsite) pairs are absent from type_mapping evidence: "
            + ", ".join(f"({type_id}, {callsite})" for type_id, callsite in missing_pairs_from_mapping[:8])
        )

    return {
        "status": "pass" if not unique_strings(blockers) else "fail",
        "strict_per_type_required": strict_per_type_required,
        "requires_per_type_events": requires_per_type_events,
        "per_type_event_count": int(event_stats.get("per_type_event_count") or 0),
        "per_type_event_type_id_count": len(event_type_ids),
        "per_type_event_callsite_count": int(event_stats.get("per_type_event_callsite_count") or 0),
        "mapping_valid_type_id_count": len(mapping_type_ids),
        "per_type_event_type_id_callsite_pair_count": len(event_pairs),
        "mapping_valid_type_id_callsite_pair_count": len(mapping_pairs),
        "event_type_ids_missing_from_mapping": missing_from_mapping[:256],
        "event_type_id_callsite_pairs_missing_from_mapping": [
            {"type_id": type_id, "callsite": callsite} for type_id, callsite in missing_pairs_from_mapping[:256]
        ],
        "event_type_ids_sample": sorted(event_type_ids)[:256],
        "event_type_id_callsite_pairs_sample": [
            {"type_id": type_id, "callsite": callsite} for type_id, callsite in sorted(event_pairs)[:256]
        ],
        "blockers": unique_strings(blockers),
    }


def compiler_coverage_metadata_blockers(manifest: Dict[str, Any]) -> Tuple[List[str], List[str]]:
    blockers: List[str] = []
    missing_fields: List[str] = []
    for field in COMPILER_COVERAGE_REQUIRED_METADATA_FIELDS:
        if coverage_manifest_value(manifest, field) in (None, "", [], {}):
            missing_fields.append(field)
    compiler_pass = coverage_manifest_value(manifest, "compiler_pass")
    if compiler_pass not in (None, "", [], {}):
        text = json.dumps(compiler_pass, sort_keys=True) if isinstance(compiler_pass, dict) else str(compiler_pass)
        lowered = text.lower()
        for marker in COMPILER_COVERAGE_PROTOTYPE_MARKERS:
            if marker in lowered:
                blockers.append(f"compiler_pass metadata still indicates non-compiler/prototype provenance: {marker}")
                break
    benchmark_suite = coverage_manifest_value(manifest, "benchmark_suite")
    without_source_changes = coverage_manifest_truthy(manifest, "without_source_changes")
    complete_for_claim = coverage_manifest_truthy(manifest, "complete_for_claim", "paper_equivalent")
    if isinstance(benchmark_suite, dict):
        without_source_changes = without_source_changes or benchmark_suite.get("without_source_changes") is True
        complete_for_claim = complete_for_claim or benchmark_suite.get("complete_for_claim") is True or benchmark_suite.get("paper_equivalent") is True
    if benchmark_suite not in (None, "", [], {}):
        if not without_source_changes:
            blockers.append("benchmark_suite must explicitly cover the benchmark surface without source changes")
        if not complete_for_claim:
            blockers.append("benchmark_suite must explicitly be complete_for_claim or paper_equivalent")
    return unique_strings(blockers), missing_fields



RUSTC_MIR_PLACE_DECL_RE = re.compile(r"^\s*let\s+(?:mut\s+)?(?P<place>_[0-9]+):\s*(?P<type>[^;]+);")
RUSTC_MIR_BB_RE = re.compile(r"^\s*(?P<bb>bb[0-9]+)(?:\s*\([^)]*\))?:\s*\{")
RUSTC_MIR_CALL_RE = re.compile(
    r"^\s*(?P<dest>_[0-9]+)\s*=\s*(?P<callee>.+?)\((?P<args>.*)\)\s*->\s*(?P<target>.+?);\s*//\s*scope\s+[^ ]+\s+at\s+(?P<span>.+)$"
)
RUSTC_MIR_FN_RE = re.compile(r"^fn\s+(?P<name>[A-Za-z_][A-Za-z0-9_]*)[<(]")


RUSTC_MIR_ALLOCATION_CALLEE_MARKERS = [
    "::with_capacity",
    "::new",
    "::from",
    "::insert",
    "::push_back",
    "Vec::<",
    "VecDeque::<",
    "BinaryHeap::<",
    "BTreeMap::<",
    "BTreeSet::<",
    "LinkedList::<",
    "HashMap::<",
    "HashSet::<",
    "Box::<",
    "String as From",
    "String::with_capacity",
    "String::from",
    "RawVec",
    "alloc::alloc",
    "exchange_malloc",
]


def default_rustc_mir_fixture_source() -> str:
    return """use std::collections::{BTreeMap, BTreeSet, BinaryHeap, HashMap, HashSet, LinkedList, VecDeque};

fn main() {
    let mut vec_values: Vec<u64> = Vec::with_capacity(8);
    vec_values.push(1);
    vec_values.extend([2, 3, 4]);

    let mut deque_values: VecDeque<u64> = VecDeque::with_capacity(8);
    deque_values.push_back(5);
    deque_values.push_front(6);

    let mut heap_values: BinaryHeap<u64> = BinaryHeap::with_capacity(8);
    heap_values.push(7);
    heap_values.push(8);

    let mut map_values: BTreeMap<u64, u64> = BTreeMap::new();
    map_values.insert(9, 10);

    let mut set_values: BTreeSet<u64> = BTreeSet::new();
    set_values.insert(11);

    let mut linked_values: LinkedList<u64> = LinkedList::new();
    linked_values.push_back(12);

    let mut hash_map_values: HashMap<u64, u64> = HashMap::with_capacity(8);
    hash_map_values.insert(13, 14);

    let mut hash_set_values: HashSet<u64> = HashSet::with_capacity(8);
    hash_set_values.insert(15);

    let boxed_value = Box::new(16_u64);
    let boxed_slice: Box<[u64]> = vec_values.clone().into_boxed_slice();
    let string_value = String::from("unialloc");
    let mut string_buffer = String::with_capacity(32);
    string_buffer.push_str(&string_value);

    let _keep_live = (
        deque_values,
        heap_values,
        map_values,
        set_values,
        linked_values,
        hash_map_values,
        hash_set_values,
        boxed_value,
        boxed_slice,
        string_buffer,
    );
}
"""


def rustc_mir_surface_function_name(index: int, benchmark_name: str) -> str:
    digest = hashlib.sha256(benchmark_name.encode("utf-8")).hexdigest()[:10]
    stem = sanitize_rust_identifier(benchmark_name)
    return f"c002_surface_{index:04d}_{digest}_{stem[:80]}"


def rustc_mir_surface_operation(benchmark_name: str) -> Tuple[str, List[str]]:
    prefix = benchmark_name.split("::", 1)[0].lower()
    lowered = benchmark_name.lower()
    if lowered.startswith("btree::map::"):
        return "btree_map", [
            "let mut map_values: BTreeMap<u64, u64> = BTreeMap::new();",
            "map_values.insert(1, 2);",
            "map_values.insert((score as u64) + 3, 4);",
            "score += map_values.len();",
        ]
    if lowered.startswith("btree::set::"):
        return "btree_set", [
            "let mut set_values: BTreeSet<u64> = BTreeSet::new();",
            "set_values.insert(1);",
            "set_values.insert((score as u64) + 2);",
            "score += set_values.len();",
        ]
    if prefix == "binary_heap":
        return "binary_heap", [
            "let mut heap_values: BinaryHeap<u64> = BinaryHeap::with_capacity(8);",
            "heap_values.push(1);",
            "heap_values.push((score as u64) + 2);",
            "score += heap_values.len();",
        ]
    if prefix == "linked_list":
        return "linked_list", [
            "let mut linked_values: LinkedList<u64> = LinkedList::new();",
            "linked_values.push_back(1);",
            "linked_values.push_front((score as u64) + 2);",
            "score += linked_values.len();",
        ]
    if prefix == "vec_deque":
        return "vec_deque", [
            "let mut deque_values: VecDeque<u64> = VecDeque::with_capacity(8);",
            "deque_values.push_back(1);",
            "deque_values.push_front((score as u64) + 2);",
            "score += deque_values.len();",
        ]
    if prefix in {"str", "string"}:
        return "string", [
            "let mut string_value = String::with_capacity(32);",
            "string_value.push_str(benchmark_name);",
            "score += string_value.len();",
        ]
    if prefix == "slice":
        return "slice_vec_box", [
            "let mut vec_values: Vec<u64> = Vec::with_capacity(8);",
            "vec_values.extend_from_slice(&[1, 2, 3, score as u64]);",
            "let boxed_values: Box<[u64]> = vec_values.into_boxed_slice();",
            "score += boxed_values.len();",
        ]
    return "vec", [
        "let mut vec_values: Vec<u64> = Vec::with_capacity(8);",
        "vec_values.push(1);",
        "vec_values.extend_from_slice(&[2, 3, score as u64]);",
        "score += vec_values.len();",
    ]


def generate_rustc_mir_std_bench_surface_source(benchmarks: List[str]) -> Tuple[str, List[Dict[str, Any]]]:
    lines = [
        "#![allow(dead_code, unused_variables, unused_mut)]",
        "use std::collections::{BTreeMap, BTreeSet, BinaryHeap, LinkedList, VecDeque};",
        "",
    ]
    mapping: List[Dict[str, Any]] = []
    for index, benchmark_name in enumerate(benchmarks, start=1):
        function_name = rustc_mir_surface_function_name(index, benchmark_name)
        operation_kind, operation_lines = rustc_mir_surface_operation(benchmark_name)
        module = benchmark_name.split("::", 1)[0]
        mapping.append(
            {
                "benchmark_name": benchmark_name,
                "benchmark_module": module,
                "mir_function": function_name,
                "operation_kind": operation_kind,
            }
        )
        lines.extend(
            [
                "#[inline(never)]",
                f"fn {function_name}() -> usize {{",
                f"    let benchmark_name: &str = {json.dumps(benchmark_name)};",
                "    let mut score = benchmark_name.len();",
            ]
        )
        lines.extend(f"    {line}" for line in operation_lines)
        lines.extend(
            [
                "    score",
                "}",
                "",
            ]
        )
    lines.extend(["fn main() {}", ""])
    return "\n".join(lines), mapping


def normalize_mir_object_type(raw: str) -> str:
    text = re.sub(r"\s+", " ", str(raw or "").strip())
    return text or "<unknown>"


def rustc_mir_callee_looks_allocating(callee: str, dest_type: str) -> bool:
    text = f"{callee} {dest_type}"
    return any(marker in text for marker in RUSTC_MIR_ALLOCATION_CALLEE_MARKERS)


def rustc_mir_object_type_for_call(dest_type: str, callee: str) -> str:
    if (
        dest_type
        and dest_type != "()"
        and dest_type != "bool"
        and not dest_type.startswith("std::option::Option")
    ):
        return dest_type
    collection_match = re.search(
        r"(?P<name>VecDeque|BinaryHeap|BTreeMap|BTreeSet|LinkedList|HashMap|HashSet|Vec|Box)::<(?P<inner>.+?)>::",
        callee,
    )
    if collection_match:
        name = collection_match.group("name")
        inner = collection_match.group("inner")
        namespaces = {
            "Vec": "std::vec::Vec",
            "VecDeque": "std::collections::VecDeque",
            "BinaryHeap": "std::collections::BinaryHeap",
            "BTreeMap": "std::collections::BTreeMap",
            "BTreeSet": "std::collections::BTreeSet",
            "LinkedList": "std::collections::LinkedList",
            "HashMap": "std::collections::HashMap",
            "HashSet": "std::collections::HashSet",
            "Box": "std::boxed::Box",
        }
        return f"{namespaces[name]}<{inner}>"
    vec_match = re.search(r"Vec::<(?P<inner>[^>]+)>", callee)
    if vec_match:
        return f"std::vec::Vec<{vec_match.group('inner')}>"
    box_match = re.search(r"Box::<(?P<inner>[^>]+)>", callee)
    if box_match:
        return f"std::boxed::Box<{box_match.group('inner')}>"
    if "String as From" in callee:
        return "std::string::String"
    return dest_type or callee


def parse_rustc_mir_allocation_type_mappings(mir_text: str) -> List[Dict[str, Any]]:
    place_types: Dict[str, str] = {}
    records: List[Dict[str, Any]] = []
    current_bb = "<unknown>"
    current_fn = "<unknown>"
    for line_no, line in enumerate(mir_text.splitlines(), start=1):
        fn_match = RUSTC_MIR_FN_RE.match(line)
        if fn_match:
            current_fn = fn_match.group("name")
            place_types = {}
            current_bb = "<unknown>"
            continue
        decl = RUSTC_MIR_PLACE_DECL_RE.match(line)
        if decl:
            place_types[decl.group("place")] = normalize_mir_object_type(decl.group("type"))
            continue
        bb = RUSTC_MIR_BB_RE.match(line)
        if bb:
            current_bb = bb.group("bb")
            continue
        call = RUSTC_MIR_CALL_RE.match(line)
        if not call:
            continue
        dest = call.group("dest")
        callee = call.group("callee").strip()
        dest_type = place_types.get(dest, "")
        if not rustc_mir_callee_looks_allocating(callee, dest_type):
            continue
        span = call.group("span").strip()
        object_type = rustc_mir_object_type_for_call(dest_type, callee)
        record_key = f"{dest}:{current_bb}:{line_no}:{callee}"
        type_hash = hashlib.sha256(f"{object_type}\0{callee}".encode("utf-8")).hexdigest()[:16]
        records.append(
            {
                "allocation_site_id": f"mir:{record_key}",
                "type_id": int(type_hash, 16),
                "object_type": object_type,
                "mir_location": f"{current_bb}:line{line_no}:{dest}",
                "source_span": span,
                "compiler_pass": "rustc-mir-unpretty-allocation-site-audit",
                "mir_function": current_fn,
                "callee": callee,
                "destination_place": dest,
                "rustc_mir_text_line": line_no,
                "notes": "Candidate allocation-site object mapping parsed from rustc -Zunpretty=mir text; not runtime paper coverage by itself.",
            }
        )
    return records


def run_rustc_unpretty_mir(source_path: Path, out_dir: Path, *, toolchain: str, timeout: int) -> Tuple[Path, Path, Path, Dict[str, Any]]:
    rustc_cmd = ["rustc"]
    if toolchain:
        rustc_cmd.append(f"+{toolchain}" if not toolchain.startswith("+") else toolchain)
    rustc_cmd.extend(["--edition=2021", "-Zunpretty=mir", str(source_path)])
    stdout_path = out_dir / "rustc-mir.stdout.txt"
    stderr_path = out_dir / "rustc-mir.stderr.txt"
    mir_path = out_dir / "rustc-mir.txt"
    try:
        proc = subprocess.run(
            rustc_cmd,
            cwd=str(ROOT),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=timeout,
        )
    except subprocess.TimeoutExpired as exc:
        stdout = exc.stdout if isinstance(exc.stdout, str) else (exc.stdout or b"").decode("utf-8", errors="replace")
        stderr = exc.stderr if isinstance(exc.stderr, str) else (exc.stderr or b"").decode("utf-8", errors="replace")
        stdout_path.write_text(stdout, encoding="utf-8")
        stderr_path.write_text(stderr, encoding="utf-8")
        mir_path.write_text(stdout, encoding="utf-8")
        return stdout_path, stderr_path, mir_path, {
            "command": rustc_cmd,
            "returncode": 124,
            "timed_out": True,
            "timeout_seconds": timeout,
        }
    stdout_path.write_text(proc.stdout, encoding="utf-8")
    stderr_path.write_text(proc.stderr, encoding="utf-8")
    mir_path.write_text(proc.stdout, encoding="utf-8")
    return stdout_path, stderr_path, mir_path, {
        "command": rustc_cmd,
        "returncode": proc.returncode,
        "timed_out": False,
        "timeout_seconds": timeout,
    }


