RUSTC_DRIVER_PASS_DIR = ROOT / "tools" / "unialloc-rustc-pass"
RUSTC_DRIVER_ALLOCATION_PASS = RUSTC_DRIVER_PASS_DIR / "unialloc-rustc-allocation-sites.rs"
RUSTC_DRIVER_MIR_REWRITE_DRY_RUN_PASS = (
    RUSTC_DRIVER_PASS_DIR / "unialloc-rustc-mir-rewrite-dry-run.rs"
)


def rust_toolchain_arg(toolchain: str) -> str:
    return f"+{toolchain}" if toolchain and not toolchain.startswith("+") else toolchain


def rustc_driver_tool_build_cfg_args(source: Path, toolchain: str) -> List[str]:
    """Return cfg flags required by rustc-private pass sources.

    The MIR rewrite pass supports the pinned paper-era rustc API by default and
    a separately audited current-nightly API behind ``unialloc_rustc_current``.
    Keep this explicit instead of auto-probing compiler internals so audit JSON
    records the exact source mode used for each real rustc_driver validation.
    """

    normalized = str(toolchain or "").lstrip("+").strip()
    if source == RUSTC_DRIVER_MIR_REWRITE_DRY_RUN_PASS and (
        normalized == "nightly"
        or normalized.startswith("nightly-2025")
        or normalized.startswith("nightly-2026")
    ):
        return ["--cfg", "unialloc_rustc_current"]
    return []


def run_logged_subprocess(
    out_dir: Path,
    label: str,
    cmd: List[str],
    *,
    timeout: int,
    env: Optional[Dict[str, str]] = None,
) -> Dict[str, Any]:
    stdout_path = out_dir / f"{label}.stdout.txt"
    stderr_path = out_dir / f"{label}.stderr.txt"
    started = now_iso()
    start = time.perf_counter()
    error = None
    process_group_started = os.name != "nt"

    def stop_process_tree(proc: subprocess.Popen[str], sig: int) -> None:
        try:
            if process_group_started:
                os.killpg(proc.pid, sig)
            elif sig == signal.SIGTERM:
                proc.terminate()
            else:
                proc.kill()
        except ProcessLookupError:
            return
        except OSError as exc:
            nonlocal error
            suffix = f"failed to signal timed-out subprocess tree with {sig}: {exc}"
            error = f"{error}; {suffix}" if error else suffix

    def coerce_text(value: Any) -> str:
        if isinstance(value, str):
            return value
        if value is None:
            return ""
        if isinstance(value, bytes):
            return value.decode("utf-8", errors="replace")
        return str(value)

    try:
        proc = subprocess.Popen(
            cmd,
            cwd=str(ROOT),
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            start_new_session=process_group_started,
        )
        try:
            stdout_text, stderr_text = proc.communicate(timeout=timeout)
            timed_out = False
        except subprocess.TimeoutExpired:
            timed_out = True
            error = f"timeout after {timeout}s"
            stop_process_tree(proc, signal.SIGTERM)
            try:
                stdout_text, stderr_text = proc.communicate(timeout=3)
            except subprocess.TimeoutExpired as exc:
                stop_process_tree(proc, signal.SIGKILL)
                try:
                    stdout_text, stderr_text = proc.communicate(timeout=3)
                except subprocess.TimeoutExpired as final_exc:
                    stdout_text = coerce_text(final_exc.stdout if final_exc.stdout is not None else exc.stdout)
                    stderr_text = coerce_text(final_exc.stderr if final_exc.stderr is not None else exc.stderr)
                    error = f"{error}; timed-out subprocess tree did not exit after SIGKILL"
        returncode = proc.returncode
        stdout_text = coerce_text(stdout_text)
        stderr_text = coerce_text(stderr_text)
        if timed_out:
            returncode = 124
    except OSError as exc:
        stdout_text = ""
        stderr_text = str(exc)
        returncode = 127
        timed_out = False
        error = str(exc)
    except subprocess.TimeoutExpired as exc:
        stdout_text = coerce_text(exc.stdout)
        stderr_text = coerce_text(exc.stderr)
        returncode = 124
        timed_out = True
        error = f"timeout after {timeout}s"
    ended = now_iso()
    stdout_path.write_text(stdout_text, encoding="utf-8")
    stderr_path.write_text(stderr_text, encoding="utf-8")
    return {
        "schema_version": 1,
        "label": label,
        "command": cmd,
        "started_at": started,
        "ended_at": ended,
        "wall_seconds": time.perf_counter() - start,
        "returncode": returncode,
        "timed_out": timed_out,
        "timeout_seconds": timeout,
        "error": error,
        "process_group_started": process_group_started,
        "stdout": str(stdout_path),
        "stderr": str(stderr_path),
    }


def unattempted_logged_result(
    label: str,
    error: str,
    *,
    command: Optional[List[str]] = None,
    returncode: Optional[int] = None,
) -> Dict[str, Any]:
    return {
        "schema_version": 1,
        "label": label,
        "command": command or [],
        "returncode": returncode,
        "timed_out": False,
        "error": error,
        "stdout": None,
        "stderr": None,
    }


def read_logged_text_path(path_value: Any) -> str:
    """Read a subprocess log path only when it is a real file.

    Unattempted logged results deliberately store ``None`` for stdout/stderr.
    ``Path(str(None or ""))`` becomes ``.`` and can accidentally try to read
    the repository directory as a text file, masking the real build/probe
    blocker with ``IsADirectoryError``.  Keep fail-closed probe summaries
    reportable even when a prerequisite command was skipped.
    """

    if not path_value:
        return ""
    path = Path(str(path_value))
    if not path.is_file():
        return ""
    return path.read_text(encoding="utf-8", errors="replace")


def purge_cargo_bench_target_artifacts(
    target_dir: Path,
    bench_name: str,
    *,
    profiles: Iterable[str] = ("release",),
) -> Dict[str, Any]:
    """Remove only one Cargo bench target's cached artifacts.

    A full fresh target rebuild pulls in all Unix allocator dev-dependencies
    (including snmalloc's cmake build).  For compiler-wrapper runtime smoke
    tests we only need to force Cargo to recompile the original bench crate
    through the wrapper, so this targeted purge keeps dependency caches intact
    while avoiding stale unwrapped std_bench binaries.
    """

    started = now_iso()
    removed: List[str] = []
    errors: List[str] = []
    normalized_profiles = unique_strings(
        str(profile).strip() for profile in profiles if str(profile).strip()
    ) or ["release"]
    patterns: List[Path] = []
    for profile in normalized_profiles:
        patterns.extend(
            [
                target_dir / profile / "deps" / f"{bench_name}-*",
                target_dir / profile / ".fingerprint" / f"{bench_name}-*",
                target_dir / profile / "incremental" / f"{bench_name}-*",
            ]
        )
    for pattern in patterns:
        for path in sorted(pattern.parent.glob(pattern.name)):
            try:
                if path.is_dir():
                    shutil.rmtree(path)
                else:
                    path.unlink()
                removed.append(str(path))
            except OSError as exc:
                errors.append(f"{path}: {exc}")
    return {
        "schema_version": 1,
        "label": f"purge-cargo-bench-target-artifacts-{bench_name}",
        "command": [
            "purge-cargo-bench-target-artifacts",
            str(target_dir),
            bench_name,
            "--profiles",
            ",".join(normalized_profiles),
        ],
        "started_at": started,
        "ended_at": now_iso(),
        "returncode": 0 if not errors else 1,
        "timed_out": False,
        "error": "; ".join(errors) if errors else None,
        "stdout": None,
        "stderr": None,
        "removed_count": len(removed),
        "removed": removed,
        "profiles": normalized_profiles,
    }


def toolchain_command(program: str, toolchain_arg: str, parts: Iterable[str]) -> List[str]:
    cmd = [program]
    if toolchain_arg:
        cmd.append(toolchain_arg)
    cmd.extend(parts)
    return cmd


def build_rustc_driver_allocation_pass(
    out_dir: Path,
    *,
    toolchain: str,
    timeout: int,
) -> Tuple[Path, Dict[str, Any]]:
    return build_rustc_driver_tool(
        out_dir,
        source=RUSTC_DRIVER_ALLOCATION_PASS,
        binary_name="unialloc-rustc-allocation-sites",
        label="build-rustc-driver-pass",
        toolchain=toolchain,
        timeout=timeout,
    )


def build_rustc_driver_mir_rewrite_dry_run_pass(
    out_dir: Path,
    *,
    toolchain: str,
    timeout: int,
) -> Tuple[Path, Dict[str, Any]]:
    return build_rustc_driver_tool(
        out_dir,
        source=RUSTC_DRIVER_MIR_REWRITE_DRY_RUN_PASS,
        binary_name="unialloc-rustc-mir-rewrite-dry-run",
        label="build-rustc-driver-mir-rewrite-dry-run-pass",
        toolchain=toolchain,
        timeout=timeout,
    )


def build_rustc_driver_tool(
    out_dir: Path,
    *,
    source: Path,
    binary_name: str,
    label: str,
    toolchain: str,
    timeout: int,
) -> Tuple[Path, Dict[str, Any]]:
    rustc = shutil.which("rustc") or "rustc"
    pass_bin = out_dir / binary_name
    build_env = os.environ.copy()
    build_env["RUSTC_BOOTSTRAP"] = "1"
    build_result = run_logged_subprocess(
        out_dir,
        label,
        toolchain_command(
            rustc,
            rust_toolchain_arg(toolchain),
            [*rustc_driver_tool_build_cfg_args(source, toolchain), str(source), "-o", str(pass_bin)],
        ),
        timeout=timeout,
        env=build_env,
    )
    return pass_bin, build_result


def rustc_driver_wrapper_env(
    *,
    pass_bin: Path,
    maps_dir: Path,
    logs_dir: Path,
    sysroot: str,
    base_env: Optional[Dict[str, str]] = None,
) -> Dict[str, str]:
    env = dict(base_env or os.environ.copy())
    env["RUSTC_WRAPPER"] = str(pass_bin)
    env["UNIALLOC_TYPE_MAP_DIR"] = str(maps_dir)
    env["UNIALLOC_PASS_LOG_DIR"] = str(logs_dir)
    env["UNIALLOC_CONTINUE_COMPILATION"] = "1"
    env["UNIALLOC_RUSTC_SYSROOT"] = sysroot
    env["DYLD_LIBRARY_PATH"] = (
        f"{sysroot}/lib"
        if not env.get("DYLD_LIBRARY_PATH")
        else f"{sysroot}/lib{os.pathsep}{env['DYLD_LIBRARY_PATH']}"
    )
    return env


def rustc_driver_mir_rewrite_dry_run_wrapper_env(
    *,
    pass_bin: Path,
    rewrites_dir: Path,
    logs_dir: Path,
    sysroot: str,
    actual_rewrite: bool = False,
    semantic_scope_rewrite: bool = False,
    auto_cross_thread_recovery_hint: bool = False,
    direct_local_metadata_abi: bool = False,
    direct_local_size_align_with_semantic_drop: bool = False,
    base_env: Optional[Dict[str, str]] = None,
) -> Dict[str, str]:
    env = dict(base_env or os.environ.copy())
    env["RUSTC_WRAPPER"] = str(pass_bin)
    env["UNIALLOC_REWRITE_AUDIT_DIR"] = str(rewrites_dir)
    env["UNIALLOC_PASS_LOG_DIR"] = str(logs_dir)
    env["UNIALLOC_CONTINUE_COMPILATION"] = "1"
    env["UNIALLOC_ACTUAL_MIR_REWRITE"] = "1" if actual_rewrite else "0"
    env["UNIALLOC_ACTUAL_SEMANTIC_SCOPE_REWRITE"] = "1" if semantic_scope_rewrite else "0"
    env["UNIALLOC_LOWERING_AUTO_CROSS_THREAD_HINT"] = "1" if auto_cross_thread_recovery_hint else "0"
    env["UNIALLOC_DIRECT_LOCAL_METADATA_ABI"] = "1" if direct_local_metadata_abi else "0"
    env["UNIALLOC_DIRECT_LOCAL_SIZE_ALIGN_WITH_SEMANTIC_DROP"] = (
        "1" if direct_local_size_align_with_semantic_drop else "0"
    )
    env["UNIALLOC_RUSTC_SYSROOT"] = sysroot
    env["DYLD_LIBRARY_PATH"] = (
        f"{sysroot}/lib"
        if not env.get("DYLD_LIBRARY_PATH")
        else f"{sysroot}/lib{os.pathsep}{env['DYLD_LIBRARY_PATH']}"
    )
    return env


def rustc_sysroot_for_toolchain(toolchain: str, timeout: int = 30) -> str:
    rustc = shutil.which("rustc") or "rustc"
    cmd = [rustc]
    if toolchain:
        cmd.append(rust_toolchain_arg(toolchain))
    cmd.extend(["--print", "sysroot"])
    proc = subprocess.run(
        cmd,
        cwd=str(ROOT),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        timeout=timeout,
    )
    if proc.returncode != 0:
        raise RuntimeError(proc.stderr.strip() or "rustc --print sysroot failed")
    return proc.stdout.strip()


def rustc_arg_value(args: List[str], name: str) -> Optional[str]:
    for index, value in enumerate(args):
        if value == name and index + 1 < len(args):
            return args[index + 1]
        if value.startswith(f"{name}="):
            return value.split("=", 1)[1]
    return None


def collect_rustc_driver_pass_maps(map_dir: Path) -> List[Dict[str, Any]]:
    entries: List[Dict[str, Any]] = []
    for path in sorted(map_dir.glob("*.json")):
        try:
            data = read_json(path)
        except Exception as exc:
            entries.append(
                {
                    "path": str(path),
                    "valid": False,
                    "error": str(exc),
                    "crate_name": None,
                    "allocation_site_count": 0,
                    "unique_type_id_count": 0,
                }
            )
            continue
        sites = data.get("allocation_sites") if isinstance(data, dict) else []
        if not isinstance(sites, list):
            sites = []
        rustc_args = data.get("rustc_args") if isinstance(data, dict) else []
        if not isinstance(rustc_args, list):
            rustc_args = []
        crate_name = rustc_arg_value([str(item) for item in rustc_args], "--crate-name")
        map_summary = data.get("summary") if isinstance(data, dict) and isinstance(data.get("summary"), dict) else {}
        lowering_contract = (
            data.get("lowering_contract")
            if isinstance(data, dict) and isinstance(data.get("lowering_contract"), dict)
            else {}
        )
        type_ids = {
            str(site.get("type_id"))
            for site in sites
            if isinstance(site, dict) and site.get("type_id") not in (None, "", 0)
        }
        layout_resolved_count = sum(
            1
            for site in sites
            if isinstance(site, dict)
            and (
                site.get("destination_layout_status") == "resolved"
                or site.get("layout_status") == "resolved"
                or (site.get("destination_layout_size") is not None and site.get("destination_layout_align") is not None)
                or (site.get("layout_size") is not None and site.get("layout_align") is not None)
            )
        )
        layout_resolved_lowering_eligible_count = sum(
            1
            for site in sites
            if isinstance(site, dict)
            and site.get("lowering_eligible") is True
            and (
                site.get("destination_layout_status") == "resolved"
                or site.get("layout_status") == "resolved"
                or (site.get("destination_layout_size") is not None and site.get("destination_layout_align") is not None)
                or (site.get("layout_size") is not None and site.get("layout_align") is not None)
            )
        )
        direct_allocator_metadata_ready_count = sum(
            1
            for site in sites
            if isinstance(site, dict)
            and isinstance(site.get("direct_allocator_abi_plan"), dict)
            and site.get("direct_allocator_abi_plan", {}).get("status") == "metadata_operands_ready"
        )
        direct_allocator_call_count = sum(
            1
            for site in sites
            if isinstance(site, dict) and site.get("allocation_effect") == "direct_allocator_call"
        )
        semantic_scope_metadata_ready_count = sum(
            1 for site in sites if isinstance(site, dict) and site.get("lowering_eligible") is True
        )
        direct_allocator_metadata_ready_lowering_eligible_count = sum(
            1
            for site in sites
            if isinstance(site, dict)
            and site.get("lowering_eligible") is True
            and isinstance(site.get("direct_allocator_abi_plan"), dict)
            and site.get("direct_allocator_abi_plan", {}).get("status") == "metadata_operands_ready"
        )
        entries.append(
            {
                "path": str(path),
                "valid": True,
                "source": data.get("source") if isinstance(data, dict) else None,
                "crate_name": crate_name,
                "compiler_pass": data.get("compiler_pass") if isinstance(data, dict) else None,
                "summary": map_summary,
                "lowering_contract": lowering_contract,
                "allocation_site_count": len(sites),
                "unique_type_id_count": len(type_ids),
                "lowering_eligible_allocation_site_count": sum(
                    1 for site in sites if isinstance(site, dict) and site.get("lowering_eligible") is True
                ),
                "no_instrument_allocation_site_count": sum(
                    1 for site in sites if isinstance(site, dict) and site.get("no_instrument") is True
                ),
                "layout_resolved_allocation_site_count": int(
                    map_summary.get("layout_resolved_allocation_site_count") or layout_resolved_count
                ),
                "layout_resolved_lowering_eligible_allocation_site_count": int(
                    map_summary.get("layout_resolved_lowering_eligible_allocation_site_count")
                    or layout_resolved_lowering_eligible_count
                ),
                "direct_allocator_call_site_count": int(
                    map_summary.get("direct_allocator_call_site_count") or direct_allocator_call_count
                ),
                "semantic_scope_metadata_operands_ready_allocation_site_count": int(
                    map_summary.get("semantic_scope_metadata_operands_ready_allocation_site_count")
                    or semantic_scope_metadata_ready_count
                ),
                "direct_allocator_metadata_operands_ready_allocation_site_count": int(
                    map_summary.get("direct_allocator_metadata_operands_ready_allocation_site_count")
                    or direct_allocator_metadata_ready_count
                ),
                "direct_allocator_metadata_operands_ready_lowering_eligible_allocation_site_count": (
                    direct_allocator_metadata_ready_lowering_eligible_count
                ),
                "direct_allocator_abi": lowering_contract.get("direct_allocator_abi"),
                "direct_allocator_abi_size_align_basis": lowering_contract.get(
                    "direct_allocator_abi_size_align_basis"
                ),
                "destination_layout_basis": lowering_contract.get("destination_layout_basis"),
                "sample_sites": sites[:5],
            }
        )
    return entries


def audit_rustc_driver_allocation_sites(args: argparse.Namespace) -> int:
    run_id = args.run_id or _dt.datetime.now().strftime("rustc-driver-allocation-sites-%Y%m%d-%H%M%S")
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)
    maps_dir = out_dir / "maps"
    logs_dir = out_dir / "logs"
    cargo_target_dir = out_dir / "cargo-target"
    maps_dir.mkdir(parents=True, exist_ok=True)
    logs_dir.mkdir(parents=True, exist_ok=True)
    if not RUSTC_DRIVER_ALLOCATION_PASS.exists():
        print(f"rustc_driver pass source not found: {RUSTC_DRIVER_ALLOCATION_PASS}", file=sys.stderr)
        return 2

    toolchain_arg = rust_toolchain_arg(args.toolchain)
    cargo = shutil.which("cargo") or "cargo"
    cargo_base_env = os.environ.copy()
    cargo_base_env["CARGO_TARGET_DIR"] = str(cargo_target_dir)
    cargo_base_env.setdefault("GLIBC_TUNABLES", "glibc.pthread.rseq=0")
    pass_bin, build_result = build_rustc_driver_allocation_pass(
        out_dir,
        toolchain=args.toolchain,
        timeout=args.timeout,
    )

    sysroot = ""
    clean_result: Dict[str, Any]
    cargo_result: Dict[str, Any]
    if build_result.get("returncode") == 0:
        try:
            sysroot = rustc_sysroot_for_toolchain(args.toolchain)
        except Exception as exc:
            clean_result = {
                "schema_version": 1,
                "label": "cargo-clean-unialloc-package",
                "command": [],
                "returncode": None,
                "timed_out": False,
                "error": f"failed to resolve sysroot: {exc}",
                "stdout": None,
                "stderr": None,
            }
            cargo_result = {
                "schema_version": 1,
                "label": "cargo-rustc-driver-pass",
                "command": [],
                "returncode": 1,
                "timed_out": False,
                "error": f"failed to resolve sysroot: {exc}",
                "stdout": None,
                "stderr": None,
            }
        else:
            clean_cmd = [cargo]
            if toolchain_arg:
                clean_cmd.append(toolchain_arg)
            clean_cmd.extend(["clean", "-p", "unialloc"])
            if args.no_clean_unialloc_package:
                clean_result = {
                    "schema_version": 1,
                    "label": "cargo-clean-unialloc-package",
                    "command": clean_cmd,
                    "returncode": 0,
                    "timed_out": False,
                    "error": "skipped by --no-clean-unialloc-package",
                    "stdout": None,
                    "stderr": None,
                }
            else:
                clean_result = run_logged_subprocess(
                    out_dir,
                    "cargo-clean-unialloc-package",
                    clean_cmd,
                    timeout=args.timeout,
                    env=cargo_base_env,
                )
            cargo_cmd = [cargo]
            if toolchain_arg:
                cargo_cmd.append(toolchain_arg)
            cargo_cmd.extend(["rustc", "-p", "unialloc", "--bench", "std_bench"])
            if args.features:
                cargo_cmd.extend(["--features", args.features])
            cargo_cmd.extend(["--", "--emit=metadata"])
            cargo_result = run_logged_subprocess(
                out_dir,
                "cargo-rustc-driver-pass",
                cargo_cmd,
                timeout=args.timeout,
                env=rustc_driver_wrapper_env(
                    pass_bin=pass_bin,
                    maps_dir=maps_dir,
                    logs_dir=logs_dir,
                    sysroot=sysroot,
                    base_env=cargo_base_env,
                ),
            )
    else:
        clean_result = {
            "schema_version": 1,
            "label": "cargo-clean-unialloc-package",
            "command": [],
            "returncode": None,
            "timed_out": False,
            "error": "pass build failed; clean was not attempted",
            "stdout": None,
            "stderr": None,
        }
        cargo_result = {
            "schema_version": 1,
            "label": "cargo-rustc-driver-pass",
            "command": [],
            "returncode": None,
            "timed_out": False,
            "error": "pass build failed; cargo rustc was not attempted",
            "stdout": None,
            "stderr": None,
        }

    maps = collect_rustc_driver_pass_maps(maps_dir)
    cargo_target_cleanup = remove_directory_if_present(cargo_target_dir)
    std_bench_maps = [entry for entry in maps if entry.get("crate_name") == "std_bench"]
    target_map = max(std_bench_maps, key=lambda entry: int(entry.get("allocation_site_count") or 0), default=None)
    total_site_count = sum(int(entry.get("allocation_site_count") or 0) for entry in maps if entry.get("valid"))
    audit = {
        "schema_version": 1,
        "generated_at": now_iso(),
        "source": "rustc-driver-allocation-site-audit",
        "run_id": run_id,
        "artifacts": {
            "pass_source": str(RUSTC_DRIVER_ALLOCATION_PASS),
            "pass_binary": str(pass_bin),
            "maps_dir": str(maps_dir),
            "logs_dir": str(logs_dir),
            "cargo_target_dir": str(cargo_target_dir),
            "cargo_target_cleanup": cargo_target_cleanup,
            "build_stdout": build_result.get("stdout"),
            "build_stderr": build_result.get("stderr"),
            "clean_stdout": clean_result.get("stdout"),
            "clean_stderr": clean_result.get("stderr"),
            "cargo_stdout": cargo_result.get("stdout"),
            "cargo_stderr": cargo_result.get("stderr"),
        },
        "toolchain": {
            "rust_toolchain": args.toolchain,
            "sysroot": sysroot,
            "host_triple": rustc_host_triple(),
            "host": host_metadata(),
        },
        "build": build_result,
        "clean": clean_result,
        "cargo_rustc": cargo_result,
        "maps": maps,
        "target_map": target_map,
        "summary": {
            "build_returncode": build_result.get("returncode"),
            "clean_returncode": clean_result.get("returncode"),
            "cargo_returncode": cargo_result.get("returncode"),
            "cargo_target_cleaned": bool(cargo_target_cleanup.get("removed")),
            "cargo_target_removed_bytes": cargo_target_cleanup.get("removed_bytes"),
            "map_file_count": len(maps),
            "total_allocation_site_count": total_site_count,
            "std_bench_map_count": len(std_bench_maps),
            "std_bench_allocation_site_count": 0 if target_map is None else target_map.get("allocation_site_count"),
            "std_bench_unique_type_id_count": 0 if target_map is None else target_map.get("unique_type_id_count"),
            "std_bench_lowering_eligible_allocation_site_count": 0
            if target_map is None
            else target_map.get("lowering_eligible_allocation_site_count"),
            "std_bench_no_instrument_allocation_site_count": 0
            if target_map is None
            else target_map.get("no_instrument_allocation_site_count"),
            "std_bench_layout_resolved_allocation_site_count": 0
            if target_map is None
            else target_map.get("layout_resolved_allocation_site_count"),
            "std_bench_layout_resolved_lowering_eligible_allocation_site_count": 0
            if target_map is None
            else target_map.get("layout_resolved_lowering_eligible_allocation_site_count"),
            "std_bench_direct_allocator_call_site_count": 0
            if target_map is None
            else target_map.get("direct_allocator_call_site_count"),
            "std_bench_semantic_scope_metadata_operands_ready_allocation_site_count": 0
            if target_map is None
            else target_map.get("semantic_scope_metadata_operands_ready_allocation_site_count"),
            "std_bench_direct_allocator_metadata_operands_ready_allocation_site_count": 0
            if target_map is None
            else target_map.get("direct_allocator_metadata_operands_ready_allocation_site_count"),
            "std_bench_direct_allocator_metadata_operands_ready_lowering_eligible_allocation_site_count": 0
            if target_map is None
            else target_map.get("direct_allocator_metadata_operands_ready_lowering_eligible_allocation_site_count"),
            "direct_allocator_abi": None if target_map is None else target_map.get("direct_allocator_abi"),
            "direct_allocator_abi_size_align_basis": None
            if target_map is None
            else target_map.get("direct_allocator_abi_size_align_basis"),
            "destination_layout_basis": None if target_map is None else target_map.get("destination_layout_basis"),
            "lowering_contract_present": bool(target_map and target_map.get("lowering_contract")),
            "claim_grade": False,
            "complete_for_claim": False,
            "lowering_status": "analysis_only",
            "ready_for_claim_grade_import": False,
            "blockers": [
                "rustc_driver pass now emits MIR allocation-site/type-map rows plus allocator metadata operands, but still does not rewrite MIR",
                "production allocator-call lowering into __unialloc_*_with_metadata and runtime allocation-event correlation are still required",
            ],
        },
        "notes": [
            "This compiles the real unialloc std_bench bench target through a rustc_driver pass with RUSTC_WRAPPER.",
            "The command emits metadata only and does not execute the benchmark matrix.",
            "The artifact is stronger than a mock/text parser but remains non-claim-grade until IDs are lowered into runtime allocator calls.",
            "Destination layouts are emitted for compiler-audit evidence only; allocator size/align must come from the allocator-call MIR operands.",
        ],
    }
    audit_path = out_dir / "rustc-driver-allocation-site-audit.json"
    write_json(audit_path, audit)
    if not args.no_update_results:
        write_json(RESULTS / "rustc_driver_allocation_site_audit.json", audit)
    print(
        json.dumps(
            {
                "audit": str(audit_path),
                "map_file_count": audit["summary"]["map_file_count"],
                "std_bench_allocation_site_count": audit["summary"]["std_bench_allocation_site_count"],
                "std_bench_unique_type_id_count": audit["summary"]["std_bench_unique_type_id_count"],
                "std_bench_lowering_eligible_allocation_site_count": audit["summary"][
                    "std_bench_lowering_eligible_allocation_site_count"
                ],
                "std_bench_no_instrument_allocation_site_count": audit["summary"][
                    "std_bench_no_instrument_allocation_site_count"
                ],
                "std_bench_layout_resolved_allocation_site_count": audit["summary"][
                    "std_bench_layout_resolved_allocation_site_count"
                ],
                "std_bench_direct_allocator_metadata_operands_ready_allocation_site_count": audit["summary"][
                    "std_bench_direct_allocator_metadata_operands_ready_allocation_site_count"
                ],
                "std_bench_direct_allocator_call_site_count": audit["summary"][
                    "std_bench_direct_allocator_call_site_count"
                ],
                "std_bench_semantic_scope_metadata_operands_ready_allocation_site_count": audit["summary"][
                    "std_bench_semantic_scope_metadata_operands_ready_allocation_site_count"
                ],
                "lowering_contract_present": audit["summary"]["lowering_contract_present"],
                "build_returncode": audit["summary"]["build_returncode"],
                "clean_returncode": audit["summary"]["clean_returncode"],
                "cargo_returncode": audit["summary"]["cargo_returncode"],
                "lowering_status": audit["summary"]["lowering_status"],
            },
            indent=2,
            sort_keys=True,
        )
    )
    if (
        build_result.get("returncode") != 0
        or clean_result.get("returncode") != 0
        or cargo_result.get("returncode") != 0
        or not target_map
    ):
        return 1
    return 0


def summary_int_or_default(summary: Dict[str, Any], key: str, default: int = 0) -> int:
    raw = summary.get(key)
    if raw is None:
        return int(default)
    try:
        return int(raw)
    except (TypeError, ValueError):
        return int(default)


def rustc_driver_rewrite_candidates(
    rewrite_data: Dict[str, Any],
    lowering_kind: str,
    rewrite_status: Optional[str] = None,
) -> List[Dict[str, Any]]:
    """Return rewrite-candidate audit rows for a lowering kind/status.

    Several rustc-driver collectors build type maps from the same dry-run audit
    schema. Keeping this filtering in one helper avoids duplicated list
    comprehensions drifting apart, especially for drop-scope rows that must be
    counted even when they only produce deallocation evidence.
    """

    rows = rewrite_data.get("rewrite_candidates", []) if isinstance(rewrite_data, dict) else []
    return [
        row
        for row in rows
        if isinstance(row, dict)
        and row.get("lowering_kind") == lowering_kind
        and (rewrite_status is None or row.get("rewrite_status") == rewrite_status)
    ]


def rustc_driver_semantic_scope_type_mapping_row(row: Dict[str, Any]) -> Dict[str, Any]:
    """Return the common type-map projection for MIR semantic-scope rewrites.

    Runtime evidence can come from either enter/exit scopes around allocation-
    producing calls or Drop scopes that only emit deallocation rows.  Keeping one
    projection for both paths prevents performance-smoke validators from
    accidentally dropping deallocation-only compiler evidence while the full
    runtime collector keeps it.
    """

    return {
        "allocation_site_id": row.get("allocation_site_id"),
        "type_id": row.get("type_id"),
        "module_id": row.get("module_id"),
        "policy_flags": row.get("flags"),
        "callsite": row.get("callsite"),
        "mir_function": row.get("mir_function"),
        "basic_block": row.get("basic_block"),
        "source_span": row.get("source_span"),
        "callee": row.get("callee"),
        "destination_type": row.get("destination_type"),
        "argument_types": row.get("argument_types"),
        "semantic_object_type": row.get("semantic_object_type"),
        "type_id_basis": row.get("type_id_basis"),
        "lowering_kind": row.get("lowering_kind"),
        "rewrite_status": row.get("rewrite_status"),
    }


def rustc_driver_semantic_scope_type_mapping_rows(
    rows: Iterable[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    return [rustc_driver_semantic_scope_type_mapping_row(row) for row in rows]


