def rustc_driver_normalized_callee_text(callee: object) -> str:
    """Normalize rustc debug-path crate disambiguators while preserving type brackets."""

    text = str(callee or "")
    out: List[str] = []
    idx = 0
    while idx < len(text):
        bracket = text.find("[", idx)
        if bracket < 0:
            out.append(text[idx:])
            break
        close = text.find("]", bracket + 1)
        if close < 0:
            out.append(text[idx:])
            break
        if text[close + 1 : close + 3] == "::":
            crate_start = bracket - 1
            while crate_start >= idx and (text[crate_start].isalnum() or text[crate_start] == "_"):
                crate_start -= 1
            crate_start += 1
            if crate_start < bracket and all(ch in "0123456789abcdefABCDEF" for ch in text[bracket + 1 : close]):
                out.append(text[idx:bracket])
                idx = close + 1
                continue
        out.append(text[idx : bracket + 1])
        idx = bracket + 1
    return "".join(out)


def rustc_driver_marker_has_boundary(text: str, marker_start: int, marker: str) -> bool:
    suffix = text[marker_start + len(marker) :]
    if suffix.startswith("::"):
        return True
    if not suffix:
        return True
    return suffix[0] in "<{(, \t\n})"


def rustc_driver_marker_has_prefix_boundary(text: str, marker_start: int) -> bool:
    if marker_start <= 0:
        return True
    prefix = text[:marker_start]
    return prefix[-1] not in "_:" and not prefix[-1].isalnum()


def rustc_driver_callee_contains_current_impl_method(
    callee: object, module_path: str, method: str
) -> bool:
    text = rustc_driver_normalized_callee_text(callee)
    impl_marker = f"{module_path}::{{impl#"
    method_marker = f"::{method}"
    start = 0
    while True:
        impl_start = text.find(impl_marker, start)
        if impl_start < 0:
            return False
        rest_start = impl_start + len(impl_marker)
        impl_close = text.find("}", rest_start)
        if impl_close < 0:
            return False
        after_impl = text[impl_close + 1 :]
        method_start = after_impl.find(method_marker)
        if method_start >= 0 and rustc_driver_marker_has_boundary(
            after_impl, method_start, method_marker
        ):
            return True
        start = impl_close + 1


def rustc_driver_callee_contains_any_current_impl_method(
    callee: object, impl_methods: Iterable[Tuple[str, Tuple[str, ...]]]
) -> bool:
    return any(
        rustc_driver_callee_contains_current_impl_method(callee, module_path, method)
        for module_path, methods in impl_methods
        for method in methods
    )


def rustc_driver_callee_contains_named_receiver_method(
    callee: object, receiver_path: str, method: str
) -> bool:
    text = rustc_driver_normalized_callee_text(callee)
    marker = f"{receiver_path}::{method}"
    start = 0
    while True:
        marker_start = text.find(marker, start)
        if marker_start < 0:
            return False
        if rustc_driver_marker_has_prefix_boundary(
            text, marker_start
        ) and rustc_driver_marker_has_boundary(text, marker_start, marker):
            return True
        start = marker_start + len(marker)

    generic_prefix = f"{receiver_path}::<"
    method_marker = f"::{method}"
    start = 0
    while True:
        generic_start = text.find(generic_prefix, start)
        if generic_start < 0:
            return False
        if not rustc_driver_marker_has_prefix_boundary(text, generic_start):
            start = generic_start + len(generic_prefix)
            continue
        rest_start = generic_start + len(generic_prefix)
        depth = 1
        for offset, ch in enumerate(text[rest_start:]):
            if ch == "<":
                depth += 1
            elif ch == ">":
                depth -= 1
                if depth == 0:
                    after_generics = text[rest_start + offset + 1 :]
                    if after_generics.startswith(
                        method_marker
                    ) and rustc_driver_marker_has_boundary(
                        after_generics, 0, method_marker
                    ):
                        return True
                    break
        start = generic_start + len(generic_prefix)


def rustc_driver_callee_contains_any_named_receiver_method(
    callee: object, receiver_methods: Iterable[Tuple[str, Tuple[str, ...]]]
) -> bool:
    return any(
        rustc_driver_callee_contains_named_receiver_method(callee, receiver_path, method)
        for receiver_path, methods in receiver_methods
        for method in methods
    )


