def compiler_stream_mode_audit_excerpt(path: Path) -> Dict[str, Any]:
    audit = read_json(path)
    if not isinstance(audit, dict):
        raise ValueError(f"stream-mode audit must be a JSON object: {path}")
    summary = audit.get("summary", {}) if isinstance(audit.get("summary"), dict) else {}
    stats = audit.get("runtime_coverage_stats", {}) if isinstance(audit.get("runtime_coverage_stats"), dict) else {}
    total_allocations = int(stats.get("total_allocations") or 0)
    typed_allocations = int(stats.get("typed_allocations") or 0)
    total_bytes = int(stats.get("total_allocated_bytes") or 0)
    typed_bytes = int(stats.get("typed_allocated_bytes") or 0)
    return {
        "path": str(path),
        "mode": summary.get("compiler_site_id_mode"),
        "runtime_event_valid": summary.get("runtime_event_valid"),
        "runtime_coverage_percent": summary.get("runtime_coverage_percent"),
        "runtime_coverage_bytes_percent": summary.get("runtime_coverage_bytes_percent"),
        "runtime_expected_benchmark_count": summary.get("runtime_expected_benchmark_count"),
        "runtime_observed_benchmark_count": summary.get("runtime_observed_benchmark_count"),
        "runtime_event_type_id_bases": summary.get("runtime_event_type_id_bases"),
        "compiler_site_id_stream_modes": summary.get("compiler_site_id_stream_modes"),
        "compiler_site_replay_type_id_count": summary.get("compiler_site_replay_type_id_count"),
        "compiler_site_replay_events": summary.get("compiler_site_replay_events"),
        "typed_allocations": typed_allocations,
        "total_allocations": total_allocations,
        "typed_allocation_fraction": (typed_allocations / total_allocations) if total_allocations else None,
        "typed_allocated_bytes": typed_bytes,
        "total_allocated_bytes": total_bytes,
        "typed_byte_fraction": (typed_bytes / total_bytes) if total_bytes else None,
        "blockers": audit.get("blockers", []) if isinstance(audit.get("blockers"), list) else [],
        "runtime_summary": audit.get("runtime_summary"),
        "manifest": audit.get("manifest"),
    }


def audit_compiler_site_stream_modes(args: argparse.Namespace) -> int:
    run_id = args.run_id or _dt.datetime.now().strftime("compiler-site-stream-modes-%Y%m%d-%H%M%S")
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)
    cyclic_path = (
        Path(args.cyclic_audit).expanduser()
        if args.cyclic_audit
        else RESULTS / "std_bench_compiler_site_replay_audit.json"
    )
    consuming_path = Path(args.consuming_audit).expanduser()
    cyclic_path = cyclic_path if cyclic_path.is_absolute() else ROOT / cyclic_path
    consuming_path = consuming_path if consuming_path.is_absolute() else ROOT / consuming_path
    if not cyclic_path.exists():
        print(f"cyclic stream-mode audit not found: {cyclic_path}", file=sys.stderr)
        return 2
    if not consuming_path.exists():
        print(f"consuming stream-mode audit not found: {consuming_path}", file=sys.stderr)
        return 2
    try:
        cyclic = compiler_stream_mode_audit_excerpt(cyclic_path)
        consuming = compiler_stream_mode_audit_excerpt(consuming_path)
    except (OSError, json.JSONDecodeError, ValueError) as exc:
        print(f"failed to load stream-mode audit: {exc}", file=sys.stderr)
        return 2
    coverage_threshold = float(args.coverage_threshold)

    def full_surface(entry: Dict[str, Any]) -> bool:
        expected = int(entry.get("runtime_expected_benchmark_count") or 0)
        observed = int(entry.get("runtime_observed_benchmark_count") or 0)
        return expected > 0 and observed == expected

    cyclic_high_coverage = (
        cyclic.get("mode") == "cyclic-replay"
        and cyclic.get("runtime_event_valid") is True
        and full_surface(cyclic)
        and float(cyclic.get("runtime_coverage_percent") or 0.0) >= coverage_threshold
    )
    consuming_full_surface = (
        consuming.get("mode") == "consuming-stream"
        and consuming.get("runtime_event_valid") is True
        and full_surface(consuming)
    )
    finite_stream_exhaustion_observed = bool(
        consuming_full_surface
        and int(consuming.get("typed_allocations") or 0) < int(consuming.get("total_allocations") or 0)
        and float(consuming.get("runtime_coverage_percent") or 0.0) < coverage_threshold
    )
    blockers = [
        "cyclic replay remains a high-coverage runtime bridge, not exact dynamic allocation-site attribution",
        "consuming-stream remains bench-harness supplied, not compiler-emitted per-allocation-site metadata",
    ]
    if not cyclic_high_coverage:
        blockers.append("cyclic stream-mode audit is missing full-surface high-coverage bridge evidence")
    if not consuming_full_surface:
        blockers.append("consuming stream-mode audit is missing full-surface finite-stream evidence")
    if consuming_full_surface and finite_stream_exhaustion_observed:
        blockers.append(
            "consuming-stream intentionally exposes finite-id exhaustion; its low typed coverage must not replace the high-coverage bridge"
        )
    blockers.append("neither stream mode is claim-grade C002 evidence until runtime IDs are emitted at exact dynamic allocation sites")
    blockers = unique_strings(blockers)
    audit = {
        "schema_version": 1,
        "generated_at": now_iso(),
        "run_id": run_id,
        "source": "compiler-site-stream-mode-comparison-audit",
        "coverage_threshold": coverage_threshold,
        "inputs": {
            "cyclic_audit": str(cyclic_path),
            "consuming_audit": str(consuming_path),
        },
        "modes": {
            "cyclic_replay": cyclic,
            "consuming_stream": consuming,
        },
        "summary": {
            "cyclic_full_surface_high_coverage_bridge_present": cyclic_high_coverage,
            "consuming_full_surface_probe_present": consuming_full_surface,
            "finite_stream_exhaustion_observed": finite_stream_exhaustion_observed,
            "cyclic_runtime_coverage_percent": cyclic.get("runtime_coverage_percent"),
            "consuming_runtime_coverage_percent": consuming.get("runtime_coverage_percent"),
            "cyclic_observed_benchmark_count": cyclic.get("runtime_observed_benchmark_count"),
            "consuming_observed_benchmark_count": consuming.get("runtime_observed_benchmark_count"),
            "consuming_typed_allocation_fraction": consuming.get("typed_allocation_fraction"),
            "selected_primary_evidence_mode": "cyclic-replay" if cyclic_high_coverage else None,
            "comparison_ready": cyclic_high_coverage and consuming_full_surface,
            "exact_dynamic_attribution_ready": False,
            "blocker_count": len(blockers),
        },
        "blockers": blockers,
        "methodology_notes": [
            "Use cyclic replay as the high-coverage runtime bridge preflight.",
            "Use consuming-stream as a finite-stream exhaustion probe that prevents silent cyclic reuse from being mistaken for exact dynamic attribution.",
            "Do not import either mode as claim-grade C002 evidence until the allocator sees compiler-emitted allocation-site IDs at the actual dynamic allocation event.",
        ],
    }
    audit_path = out_dir / "compiler-site-stream-mode-comparison-audit.json"
    write_json(audit_path, audit)
    if not args.no_update_results:
        write_json(RESULTS / "compiler_site_stream_mode_comparison_audit.json", audit)
    print(json.dumps(audit, indent=2, sort_keys=True))
    return 0 if audit["summary"]["comparison_ready"] else 1


def import_compiler_coverage(args: argparse.Namespace) -> int:
    try:
        audit = build_compiler_coverage_audit(Path(args.manifest))
    except (OSError, json.JSONDecodeError, ValueError) as exc:
        print(f"failed to audit compiler coverage manifest: {exc}", file=sys.stderr)
        return 2
    raw_path = write_compiler_coverage_audit_outputs(args, audit)
    if not audit.get("summary", {}).get("ready_for_claim_grade_import"):
        print(json.dumps(audit, indent=2, sort_keys=True), file=sys.stderr)
        print(f"compiler coverage audit is not ready for claim-grade import: {raw_path}", file=sys.stderr)
        return 1
    evidence = [audit["manifest"], str(raw_path), *audit.get("verified_evidence", [])]
    namespace = argparse.Namespace(
        events=audit.get("events"),
        typed=None,
        total=None,
        typed_bytes=0,
        total_bytes=0,
        evidence=evidence,
        claim_grade=True,
        scope_kind="compiler-instrumented-current-coverage",
        type_id_basis=audit.get("type_id_basis"),
        claim_grade_blocker=[],
        scope_limitations=[],
    )
    return import_coverage(namespace)


def import_coverage(args: argparse.Namespace) -> int:
    event_sources: List[str] = []
    event_type_id_bases: List[str] = []
    event_workload_categories: List[str] = []
    coverage_event_count = 0
    if args.typed is not None or args.total is not None:
        if args.typed is None or args.total is None:
            print("--typed and --total must be provided together", file=sys.stderr)
            return 2
        typed = args.typed
        total = args.total
        evidence = args.evidence or []
    else:
        events_path = Path(args.events).expanduser() if args.events else None
        if not events_path or not events_path.exists():
            print("provide --events JSONL or --typed/--total", file=sys.stderr)
            return 2
        stats = parse_coverage_events_stats(events_path)
        if not stats.get("valid"):
            print(f"invalid coverage events: {stats.get('parse_errors')}", file=sys.stderr)
            return 2
        typed = int(stats["typed_allocations"])
        total = int(stats["total_allocations"])
        typed_bytes = int(stats["typed_allocated_bytes"])
        total_bytes = int(stats["total_allocated_bytes"])
        event_stats = dict(stats["runtime_policy_stats"])
        hugepage_mmap_stats = hugepage_mmap_stats_from_coverage_stats(stats)
        coverage_event_count = int(stats["coverage_event_count"])
        event_sources = list(stats["event_sources"])
        event_type_id_bases = list(stats["event_type_id_bases"])
        event_workload_categories = list(stats["event_workload_categories"])
        evidence = [str(events_path), *(getattr(args, "evidence", None) or [])]
    if args.typed is not None or args.total is not None:
        typed_bytes = int(getattr(args, "typed_bytes", 0) or 0)
        total_bytes = int(getattr(args, "total_bytes", 0) or 0)
        event_stats = {}
        hugepage_mmap_stats = {"attempts": 0, "successes": 0, "fallbacks": 0, "event_count": 0}
    if total <= 0 or typed < 0 or typed > total:
        print(f"invalid coverage counters typed={typed} total={total}", file=sys.stderr)
        return 2
    coverage = typed * 100.0 / total
    evidence_ok, verified, missing_evidence = verify_evidence_paths(evidence)
    claim_grade = bool(getattr(args, "claim_grade", False))
    scope_kind = getattr(args, "scope_kind", None) or (
        "compiler-instrumented-current-coverage" if claim_grade else "manual-or-smoke-current-coverage"
    )
    scope_limitations = getattr(args, "scope_limitations", None)
    if claim_grade:
        scope_limitations = []
    elif scope_limitations is None:
        scope_limitations = [
            "Coverage counters are useful implementation evidence but are not the full compiler-instrumented Rust alloc benchmark run.",
            "Do not use smoke/manual coverage imports to satisfy the paper's 72.17% without-source-changes claim.",
        ]
    event_sources = unique_strings(event_sources)
    event_type_id_bases = unique_strings(event_type_id_bases)
    event_workload_categories = unique_strings(event_workload_categories)
    type_id_basis = infer_coverage_type_id_basis(
        claim_grade=claim_grade,
        scope_kind=scope_kind,
        event_sources=event_sources,
        event_type_id_bases=event_type_id_bases,
        explicit_basis=getattr(args, "type_id_basis", None),
    )
    claim_grade_blockers = coverage_claim_grade_blockers(
        claim_grade=claim_grade,
        type_id_basis=type_id_basis,
        explicit_blockers=getattr(args, "claim_grade_blocker", None) or [],
    )
    summary = {
        "schema_version": 1,
        "generated_at": now_iso(),
        "typed_allocations": typed,
        "total_allocations": total,
        "coverage_percent": coverage,
        "typed_allocated_bytes": typed_bytes,
        "total_allocated_bytes": total_bytes,
        "coverage_bytes_percent": None if total_bytes <= 0 else typed_bytes * 100.0 / total_bytes,
        "runtime_policy_stats": event_stats,
        "hugepage_mmap_stats": hugepage_mmap_stats,
        "coverage_event_count": coverage_event_count,
        "event_sources": event_sources,
        "event_type_id_bases": event_type_id_bases,
        "event_workload_categories": event_workload_categories,
        "type_id_basis": type_id_basis,
        "claim_grade": claim_grade,
        "claim_grade_blockers": claim_grade_blockers,
        "evidence": evidence,
        "verified_evidence": verified,
        "missing_evidence": missing_evidence,
        "evidence_verified": evidence_ok,
        "scope": {
            "kind": scope_kind,
            "complete_for_claim": claim_grade,
            "type_id_basis": type_id_basis,
            "claim_grade_blockers": claim_grade_blockers,
            "limitations": scope_limitations,
        },
    }
    out = RESULTS / "coverage_summary.json"
    write_json(out, summary)
    print(json.dumps(summary, indent=2, sort_keys=True))
    return 0


def collect_coverage(args: argparse.Namespace) -> int:
    """Run the in-tree semantic coverage harness and import its JSONL events."""
    cargo = shutil.which("cargo")
    if not cargo:
        print("cargo not found; run doctor for details", file=sys.stderr)
        return 2

    run_id = args.run_id or _dt.datetime.now().strftime("%Y%m%d-%H%M%S")
    out_dir = RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)

    rust_toolchain = (ROOT / "rust-toolchain").read_text(encoding="utf-8").strip() if (ROOT / "rust-toolchain").exists() else ""
    cmd = [cargo]
    if rust_toolchain:
        cmd.append(f"+{rust_toolchain}")
    cmd.extend(["run", "-q", "-p", "unialloc", "--example", "semantic_coverage"])

    stdout_path = out_dir / "semantic-coverage.stdout.txt"
    stderr_path = out_dir / "semantic-coverage.stderr.txt"
    events_path = out_dir / "semantic-coverage.events.jsonl"
    env = os.environ.copy()
    env.setdefault("GLIBC_TUNABLES", "glibc.pthread.rseq=0")
    start = time.perf_counter()
    started = now_iso()
    proc = subprocess.run(
        cmd,
        cwd=str(ROOT),
        env=env,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        timeout=args.timeout,
    )
    ended = now_iso()
    stdout_path.write_text(proc.stdout, encoding="utf-8")
    stderr_path.write_text(proc.stderr, encoding="utf-8")

    parse_errors = []
    events = parse_json_objects_from_text(proc.stdout)
    with events_path.open("w", encoding="utf-8") as f:
        for event in events:
            json.dump(event, f, sort_keys=True)
            f.write("\n")

    record = {
        "schema_version": 1,
        "run_id": run_id,
        "command": cmd,
        "started_at": started,
        "ended_at": ended,
        "wall_seconds": time.perf_counter() - start,
        "exit_code": proc.returncode,
        "stdout": str(stdout_path),
        "stderr": str(stderr_path),
        "events": str(events_path),
        "event_count": len(events),
        "parse_errors": parse_errors,
        "host": host_metadata(),
        "limitations": [
            "This harness verifies semantic/fallback accounting mechanics only.",
            "It is not a substitute for the paper's full compiler-instrumented Rust alloc benchmark coverage run.",
        ],
    }
    write_json(out_dir / "semantic-coverage-summary.json", record)
    if proc.returncode != 0:
        print(json.dumps(record, indent=2, sort_keys=True))
        return proc.returncode or 1
    if not events or parse_errors:
        print(json.dumps(record, indent=2, sort_keys=True))
        return 1
    print(str(events_path))
    return import_coverage(
        argparse.Namespace(
            events=str(events_path),
            typed=None,
            total=None,
            evidence=None,
            claim_grade=False,
            scope_kind="semantic-coverage-example-smoke",
            scope_limitations=[
                "This harness verifies semantic/fallback accounting mechanics only.",
                "It is not a substitute for the paper's full compiler-instrumented Rust alloc benchmark coverage run.",
            ],
        )
    )


