def compiler_site_replay_type_ids_from_mapping(mapping_path: Path, *, limit: int) -> List[int]:
    data = read_json_or_jsonl(mapping_path)
    rows = mapping_rows_from_json(data)
    ids: List[int] = []
    seen: set[int] = set()
    for row in rows:
        type_id, _ = find_mapping_field(row, TYPE_MAPPING_TYPE_ID_KEYS)
        if type_id in (None, "", [], {}):
            continue
        try:
            parsed = int(str(type_id), 0)
        except (TypeError, ValueError):
            continue
        if parsed <= 0 or parsed in seen:
            continue
        ids.append(parsed)
        seen.add(parsed)
        if limit > 0 and len(ids) >= limit:
            break
    return ids


