def rustc_driver_direct_allocator_rows(audit_path: Path, *, limit: int = 16) -> List[Dict[str, Any]]:
    audit = read_json_if_exists(audit_path)
    if not isinstance(audit, dict):
        return []
    maps_dir = None
    artifacts = audit.get("artifacts")
    if isinstance(artifacts, dict) and artifacts.get("maps_dir"):
        maps_dir = Path(str(artifacts.get("maps_dir"))).expanduser()
    rows: List[Dict[str, Any]] = []
    if maps_dir and maps_dir.exists():
        for path in sorted(maps_dir.glob("*.json")):
            data = read_json_if_exists(path)
            if not isinstance(data, dict):
                continue
            rustc_args = data.get("rustc_args") if isinstance(data.get("rustc_args"), list) else []
            crate_name = rustc_arg_value([str(item) for item in rustc_args], "--crate-name")
            if crate_name != "std_bench":
                continue
            sites = data.get("allocation_sites") if isinstance(data.get("allocation_sites"), list) else []
            for site in sites:
                if not isinstance(site, dict):
                    continue
                plan = site.get("direct_allocator_abi_plan")
                if not isinstance(plan, dict):
                    continue
                if site.get("allocation_effect") != "direct_allocator_call":
                    continue
                if plan.get("status") != "metadata_operands_ready":
                    continue
                rows.append(site)
                if limit > 0 and len(rows) >= limit:
                    return rows
    return rows


def write_rustc_driver_direct_allocator_abi_probe_source(rows: List[Dict[str, Any]], path: Path) -> Path:
    path.parent.mkdir(parents=True, exist_ok=True)
    site_literals: List[str] = []
    for idx, row in enumerate(rows):
        plan = row.get("direct_allocator_abi_plan") if isinstance(row.get("direct_allocator_abi_plan"), dict) else {}
        type_id = int(row.get("type_id") or plan.get("type_id") or 0)
        module_id = int(row.get("module_id") or plan.get("module_id") or 0)
        flags = int(row.get("policy_flags") or plan.get("flags") or 0)
        callsite = int(row.get("callsite") or plan.get("callsite") or 0)
        size = 64 + (idx * 16)
        align = 8
        source_span = portable_rust_source_span(str(row.get("source_span") or ""))
        site_literals.append(
            "\n    AllocationSite {\n"
            f"        type_id: {type_id},\n"
            f"        module_id: {module_id},\n"
            f"        flags: {flags},\n"
            f"        callsite: {callsite},\n"
            f"        size: {size},\n"
            f"        align: {align},\n"
            f"        source_span: {json.dumps(source_span)},\n"
            f"        mir_function: {json.dumps(str(row.get('mir_function') or ''))},\n"
            f"        size_operand: {json.dumps(str(plan.get('size_operand') or ''))},\n"
            f"        align_operand: {json.dumps(str(plan.get('align_operand') or ''))},\n"
            "    },"
        )
    source = f"""use unialloc::alloc_api::{{
    __unialloc_alloc_with_metadata, __unialloc_dealloc_with_metadata, semantic_stats_reset,
    semantic_stats_snapshot, semantic_type_stats_snapshot, SemanticTypeStatsSnapshot,
    FLAG_METADATA_SEGREGATED, FLAG_TYPE_ISOLATED,
}};
use unialloc::UniAlloc;

#[global_allocator]
static A: UniAlloc = UniAlloc;

#[derive(Clone, Copy)]
struct AllocationSite {{
    type_id: u64,
    module_id: u64,
    flags: u32,
    callsite: u64,
    size: usize,
    align: usize,
    source_span: &'static str,
    mir_function: &'static str,
    size_operand: &'static str,
    align_operand: &'static str,
}}

const SITES: &[AllocationSite] = &[{''.join(site_literals)}
];

fn empty_type_stats_row() -> SemanticTypeStatsSnapshot {{
    SemanticTypeStatsSnapshot::empty()
}}

fn run_site(site: AllocationSite) {{
    assert!(
        site.flags & (FLAG_TYPE_ISOLATED | FLAG_METADATA_SEGREGATED) != 0,
        "rustc_driver site should request type-aware metadata flags"
    );
    unsafe {{
        let ptr = __unialloc_alloc_with_metadata(
            site.size,
            site.align,
            site.type_id,
            site.module_id,
            site.flags,
            site.callsite,
        );
        assert!(!ptr.is_null(), "direct allocator ABI probe returned null");
        std::ptr::write_bytes(ptr, 0xA5, site.size);
        assert!(
            __unialloc_dealloc_with_metadata(
                ptr,
                site.size,
                site.align,
                site.type_id,
                site.module_id,
                site.flags,
                site.callsite,
            ),
            "direct allocator ABI probe dealloc failed"
        );
    }}
}}

fn emit_events() {{
    let snap = semantic_stats_snapshot();
    let mut rows = [empty_type_stats_row(); 32];
    let row_count = semantic_type_stats_snapshot(&mut rows);
    for row in rows.iter().take(std::cmp::min(row_count, rows.len())) {{
        if row.allocations == 0 {{
            continue;
        }}
        println!(
            concat!(
                "{{{{",
                "\\"source\\":\\"rustc_driver_direct_allocator_abi_probe\\",",
                "\\"type_id_basis\\":\\"compiler-assigned-allocation-site-object-type-id\\",",
                "\\"compiler_site_replay\\":false,",
                "\\"compiler_site_id_stream_mode\\":\\"rustc-driver-direct-allocator-abi\\",",
                "\\"event\\":\\"typed_allocation_site\\",",
                "\\"typed\\":true,",
                "\\"type_id\\":{{}},",
                "\\"module_id\\":{{}},",
                "\\"callsite\\":{{}},",
                "\\"count\\":{{}},",
                "\\"bytes\\":{{}},",
                "\\"deallocations\\":{{}},",
                "\\"cache_hits\\":{{}},",
                "\\"cache_inserts\\":{{}},",
                "\\"cache_bypasses\\":{{}},",
                "\\"policy_flags_seen\\":{{}},",
                "\\"site_count\\":{{}}",
                "}}}}"
            ),
            row.type_id,
            row.module_id,
            row.callsite,
            row.allocations,
            row.allocated_bytes,
            row.deallocations,
            row.cache_hits,
            row.cache_inserts,
            row.cache_bypasses,
            row.policy_flags_seen,
            SITES.len()
        );
    }}
    println!(
        concat!(
            "{{{{",
            "\\"source\\":\\"rustc_driver_direct_allocator_abi_probe\\",",
            "\\"type_id_basis\\":\\"compiler-assigned-allocation-site-object-type-id\\",",
            "\\"compiler_site_replay\\":false,",
            "\\"compiler_site_id_stream_mode\\":\\"rustc-driver-direct-allocator-abi\\",",
            "\\"event\\":\\"typed_allocations\\",",
            "\\"typed\\":true,",
            "\\"type_id\\":\\"aggregate\\",",
            "\\"count\\":{{}},",
            "\\"bytes\\":{{}},",
            "\\"deallocations\\":{{}},",
            "\\"fallback_allocations\\":{{}},",
            "\\"site_count\\":{{}}",
            "}}}}"
        ),
        snap.typed_allocations,
        snap.typed_allocated_bytes,
        snap.typed_deallocations,
        snap.fallback_allocations,
        SITES.len()
    );
}}

fn assert_probe_is_real() {{
    let snap = semantic_stats_snapshot();
    assert_eq!(
        snap.typed_allocations,
        SITES.len(),
        "one typed allocation should be observed for each rustc_driver direct allocator row"
    );
    assert_eq!(
        snap.typed_deallocations,
        SITES.len(),
        "direct allocator ABI probe should deallocate every typed allocation"
    );
    assert_eq!(
        snap.fallback_allocations, 0,
        "direct allocator ABI probe should not fall back to untyped allocations"
    );
}}

fn main() {{
    for site in SITES {{
        println!(
            concat!(
                "{{{{",
                "\\"source\\":\\"rustc_driver_direct_allocator_abi_probe\\",",
                "\\"event\\":\\"input_site\\",",
                "\\"type_id\\":{{}},",
                "\\"callsite\\":{{}},",
                "\\"source_span\\":{{:?}},",
                "\\"mir_function\\":{{:?}},",
                "\\"size_operand\\":{{:?}},",
                "\\"align_operand\\":{{:?}}",
                "}}}}"
            ),
            site.type_id,
            site.callsite,
            site.source_span,
            site.mir_function,
            site.size_operand,
            site.align_operand
        );
    }}
    semantic_stats_reset();
    for site in SITES {{
        run_site(*site);
    }}
    assert_probe_is_real();
    emit_events();
}}
"""
    path.write_text(source, encoding="utf-8")
    return path


def _collect_rustc_driver_direct_allocator_abi_probe_impl(args: argparse.Namespace) -> int:
    """Replay rustc_driver direct allocator-call rows through the real UniAlloc C ABI."""

    run_id = args.run_id or _dt.datetime.now().strftime(
        "rustc-driver-direct-allocator-abi-probe-%Y%m%d-%H%M%S"
    )
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)
    audit_path = (
        Path(args.rustc_driver_audit).expanduser()
        if getattr(args, "rustc_driver_audit", None)
        else RESULTS / "rustc_driver_allocation_site_audit.json"
    )
    rows = rustc_driver_direct_allocator_rows(audit_path, limit=int(args.limit or 16))
    source_path = write_rustc_driver_direct_allocator_abi_probe_source(
        rows, RUSTC_DRIVER_DIRECT_ALLOCATOR_ABI_PROBE_PATH
    )
    generated_source_artifact = out_dir / RUSTC_DRIVER_DIRECT_ALLOCATOR_ABI_PROBE_PATH.name
    shutil.copyfile(source_path, generated_source_artifact)
    features = normalize_feature_csv(args.features or "bench_ourself,stats", ["bench_ourself", "stats"])
    cmd = [
        *cargo_base_command(),
        "run",
        "-p",
        "unialloc",
        "--example",
        RUSTC_DRIVER_DIRECT_ALLOCATOR_ABI_PROBE_EXAMPLE,
        "--features",
        features,
    ]
    stdout_path = out_dir / "rustc-driver-direct-allocator-abi-probe.stdout.txt"
    stderr_path = out_dir / "rustc-driver-direct-allocator-abi-probe.stderr.txt"
    events_path = out_dir / "rustc-driver-direct-allocator-abi-probe.events.jsonl"
    started = now_iso()
    start = time.perf_counter()
    error = None
    if not rows:
        exit_code = 1
        stdout_text = ""
        stderr_text = f"no rustc_driver direct allocator-call rows found in {audit_path}\n"
        error = stderr_text.strip()
    else:
        try:
            proc = subprocess.run(
                cmd,
                cwd=str(ROOT),
                text=True,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                timeout=args.timeout,
            )
            exit_code = proc.returncode
            stdout_text = proc.stdout
            stderr_text = proc.stderr
        except subprocess.TimeoutExpired as exc:
            exit_code = 124
            error = f"timeout after {args.timeout}s: {exc}"
            stdout_text = subprocess_text(exc.stdout)
            stderr_text = subprocess_text(exc.stderr)
    ended = now_iso()
    stdout_path.write_text(stdout_text, encoding="utf-8")
    stderr_path.write_text(stderr_text, encoding="utf-8")

    events: List[Dict[str, Any]] = []
    parse_errors: List[Dict[str, Any]] = []
    for line_no, line in enumerate(stdout_text.splitlines(), start=1):
        text = line.strip()
        if not text.startswith("{"):
            continue
        try:
            event = json.loads(text)
        except json.JSONDecodeError as exc:
            parse_errors.append({"line": line_no, "error": str(exc), "text": line})
            continue
        if event.get("source") == "rustc_driver_direct_allocator_abi_probe":
            events.append(event)
    with events_path.open("w", encoding="utf-8") as f:
        for event in events:
            json.dump(event, f, sort_keys=True)
            f.write("\n")

    type_mapping_path = out_dir / "rustc-driver-direct-allocator-abi-type-mapping.json"
    mapping_rows = []
    for row in rows:
        plan = row.get("direct_allocator_abi_plan") if isinstance(row.get("direct_allocator_abi_plan"), dict) else {}
        mapping_rows.append(
            {
                "allocation_site_id": row.get("allocation_site_id"),
                "type_id": row.get("type_id") or plan.get("type_id"),
                "object_type": row.get("object_type"),
                "mir_location": row.get("mir_location"),
                "source_span": row.get("source_span"),
                "compiler_pass": row.get("compiler_pass"),
                "callsite": row.get("callsite") or plan.get("callsite"),
                "module_id": row.get("module_id") or plan.get("module_id"),
                "policy_flags": row.get("policy_flags") or plan.get("flags"),
                "allocation_effect": row.get("allocation_effect"),
                "allocator_call_kind": row.get("allocator_call_kind"),
                "size_operand": plan.get("size_operand"),
                "align_operand": plan.get("align_operand"),
            }
        )
    write_json(
        type_mapping_path,
        {
            "schema_version": 1,
            "source": "rustc-driver-direct-allocator-abi-type-map",
            "allocation_sites": mapping_rows,
        },
    )
    pass_log_path = out_dir / "rustc-driver-direct-allocator-abi-pass.log"
    pass_log_path.write_text(
        "\n".join(
            [
                "rustc_driver direct allocator-call ABI probe",
                f"run_id: {run_id}",
                f"rustc_driver_audit: {audit_path}",
                f"input_direct_allocator_row_count: {len(rows)}",
                "allocation ABI: __unialloc_alloc_with_metadata / __unialloc_dealloc_with_metadata",
                "type_id_basis: compiler-assigned-allocation-site-object-type-id",
                "stream_mode: rustc-driver-direct-allocator-abi",
                "compiler_site_replay: false",
                "limitation: generated probe replays rustc_driver metadata rows through the ABI; it is not yet MIR rewriting of the original std_bench call sites",
            ]
        )
        + "\n",
        encoding="utf-8",
    )
    run_summary_path = out_dir / "rustc-driver-direct-allocator-abi-run-summary.json"
    run_summary = {
        "schema_version": 1,
        "source": "rustc-driver-direct-allocator-abi-probe-run",
        "run_id": run_id,
        "command": cmd,
        "features": features,
        "started_at": started,
        "ended_at": ended,
        "wall_seconds": time.perf_counter() - start,
        "exit_code": exit_code,
        "error": error,
        "stdout": str(stdout_path),
        "stderr": str(stderr_path),
        "events": str(events_path),
        "event_count": len(events),
        "parse_errors": parse_errors,
        "generated_source": str(generated_source_artifact),
        "rustc_driver_audit": str(audit_path),
        "input_direct_allocator_row_count": len(rows),
        "host": host_metadata(),
    }
    write_json(run_summary_path, run_summary)

    manifest = {
        "schema_version": 1,
        "source": "rustc-driver-direct-allocator-abi-probe-manifest",
        "claim_grade": False,
        "complete_for_claim": False,
        "events": str(events_path),
        "type_id_basis": "compiler-assigned-allocation-site-object-type-id",
        "compiler_pass": {
            "kind": "rustc-driver-mir-map-to-allocator-abi-probe",
            "name": "unialloc-rustc-driver-mir-allocation-site-pass",
            "source_changes_to_benchmarks": False,
            "dynamic_allocation_site_metadata": True,
            "compiler_site_replay": False,
            "compiler_site_id_stream_mode": "rustc-driver-direct-allocator-abi",
        },
        "toolchain": {
            "rust_toolchain": rust_toolchain(),
            "host_triple": rustc_host_triple(),
            "host": host_metadata(),
        },
        "benchmark_suite": {
            "name": "rustc_driver direct allocator ABI probe",
            "benchmark_target": RUSTC_DRIVER_DIRECT_ALLOCATOR_ABI_PROBE_EXAMPLE,
            "expected_benchmark_target": "std_bench",
            "without_source_changes": False,
            "complete_for_claim": False,
            "paper_equivalent": False,
            "coverage_surface_complete": False,
            "expected_benchmarks": ["rustc_driver_direct_allocator_abi_probe"],
            "observed_benchmarks": ["rustc_driver_direct_allocator_abi_probe"] if events else [],
            "observed_benchmark_source": {
                "compiler_instrumented": True,
                "claim_grade": False,
                "complete_for_claim": False,
                "compiler_site_replay": False,
                "compiler_site_id_stream_mode": "rustc-driver-direct-allocator-abi",
                "rustc_driver_direct_allocator_row_count": len(rows),
            },
            "limitations": [
                "The probe replays real rustc_driver direct allocator-call rows through UniAlloc's exported allocator ABI.",
                "It is a generated runtime ABI probe, not yet MIR rewriting of the original std_bench call sites.",
                "Original MIR size/align operands are retained as evidence, but the probe supplies representative valid runtime size/align values.",
            ],
        },
        "benchmark_command": cmd,
        "evidence": [
            {"path": str(events_path), "kind": "coverage_events"},
            {"path": str(pass_log_path), "kind": "compiler_pass_log"},
            {"path": str(run_summary_path), "kind": "benchmark_run_summary"},
            {"path": str(type_mapping_path), "kind": "type_mapping"},
            {"path": str(generated_source_artifact), "kind": "generated_probe_source"},
            {"path": str(audit_path), "kind": "rustc_driver_allocation_site_audit"},
        ],
    }
    manifest_path = out_dir / "rustc-driver-direct-allocator-abi-probe.manifest.json"
    write_json(manifest_path, manifest)
    coverage_audit = build_compiler_coverage_audit(manifest_path)
    typed_site_events = [event for event in events if event.get("event") == "typed_allocation_site"]
    typed_site_pairs = {
        (str(event.get("type_id")), str(event.get("callsite")))
        for event in typed_site_events
        if event.get("type_id") not in (None, "", "aggregate") and event.get("callsite") not in (None, "")
    }
    mapping_pairs = {
        (str(row.get("type_id")), str(row.get("callsite")))
        for row in mapping_rows
        if row.get("type_id") not in (None, "", 0) and row.get("callsite") not in (None, "", 0)
    }
    audit = {
        "schema_version": 1,
        "generated_at": now_iso(),
        "source": "rustc-driver-direct-allocator-abi-probe-audit",
        "run_id": run_id,
        "artifacts": {
            "stdout": str(stdout_path),
            "stderr": str(stderr_path),
            "events": str(events_path),
            "run_summary": str(run_summary_path),
            "compiler_pass_log": str(pass_log_path),
            "type_mapping": str(type_mapping_path),
            "manifest": str(manifest_path),
            "generated_source": str(generated_source_artifact),
            "rustc_driver_audit": str(audit_path),
        },
        "summary": {
            "exit_code": exit_code,
            "event_count": len(events),
            "parse_error_count": len(parse_errors),
            "input_direct_allocator_row_count": len(rows),
            "typed_allocation_site_event_count": len(typed_site_events),
            "typed_event_type_id_callsite_pair_count": len(typed_site_pairs),
            "type_mapping_type_id_callsite_pair_count": len(mapping_pairs),
            "typed_event_pairs_present_in_mapping": bool(typed_site_pairs) and typed_site_pairs <= mapping_pairs,
            "coverage_event_valid": coverage_audit.get("summary", {}).get("event_valid"),
            "event_type_id_basis_status": coverage_audit.get("summary", {}).get("event_type_id_basis_status"),
            "event_type_mapping_correlation_status": coverage_audit.get("summary", {}).get(
                "event_type_mapping_correlation_status"
            ),
            "ready_for_claim_grade_import": coverage_audit.get("summary", {}).get("ready_for_claim_grade_import"),
            "blocker_count": coverage_audit.get("summary", {}).get("blocker_count"),
            "claim_grade": False,
            "complete_for_claim": False,
        },
        "compiler_coverage_audit": coverage_audit,
        "blockers": [
            "generated ABI probe replays rustc_driver rows; production MIR allocator-call rewrite is still required",
            "probe covers only direct allocator-call rows visible in the local std_bench crate compilation",
        ],
    }
    audit_path_out = out_dir / "rustc-driver-direct-allocator-abi-probe-audit.json"
    write_json(audit_path_out, audit)
    if not args.no_update_results:
        write_json(RESULTS / "rustc_driver_direct_allocator_abi_probe_audit.json", audit)

    print(
        json.dumps(
            {
                "audit": str(audit_path_out),
                "results_audit": None
                if args.no_update_results
                else str(RESULTS / "rustc_driver_direct_allocator_abi_probe_audit.json"),
                "manifest": str(manifest_path),
                "summary": audit["summary"],
                "blockers": audit["blockers"],
            },
            indent=2,
            sort_keys=True,
        )
    )
    if exit_code != 0 or parse_errors or not typed_site_events:
        return exit_code or 1
    return 0 if audit["summary"]["typed_event_pairs_present_in_mapping"] else 1


def collect_rustc_driver_direct_allocator_abi_probe(args: argparse.Namespace) -> int:
    """Collect the ABI probe without leaving its generated example dirty."""

    return run_with_restored_file(
        RUSTC_DRIVER_DIRECT_ALLOCATOR_ABI_PROBE_PATH,
        lambda: _collect_rustc_driver_direct_allocator_abi_probe_impl(args),
    )


def collect_compiler_exact_dynamic_probe(args: argparse.Namespace) -> int:
    """Run a short exact-dynamic allocation-site ABI probe and audit its manifest."""

