RUST_TOOLCHAIN_ENV = "UNIALLOC_RUST_TOOLCHAIN"


def rust_toolchain() -> str:
    """Return the Rust toolchain used by evaluator-managed cargo commands.

    The repository keeps its historical `rust-toolchain` pin for reproducible
    paper-era audits, but platform retargeting probes often need to be rerun on a
    newer compiler/target.  `UNIALLOC_RUST_TOOLCHAIN` (and the
    collect-platform-smoke `--rust-toolchain` convenience flag) can override the
    file without editing repository state.
    """

    env_toolchain = os.environ.get(RUST_TOOLCHAIN_ENV)
    if env_toolchain is not None:
        return env_toolchain.strip()
    return (ROOT / "rust-toolchain").read_text(encoding="utf-8").strip() if (ROOT / "rust-toolchain").exists() else ""


def cargo_base_command() -> List[str]:
    cargo = shutil.which("cargo") or "cargo"
    cmd = [cargo]
    toolchain = rust_toolchain()
    if toolchain:
        cmd.append(f"+{toolchain}")
    return cmd


def installed_rust_targets() -> List[str]:
    rustup = shutil.which("rustup")
    if not rustup:
        return []
    cmd = [rustup, "target", "list", "--installed"]
    toolchain = rust_toolchain()
    if toolchain:
        cmd.extend(["--toolchain", toolchain])
    try:
        proc = subprocess.run(
            cmd,
            cwd=str(ROOT),
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=30,
        )
    except Exception:
        return []
    if proc.returncode != 0:
        return []
    return [line.strip() for line in proc.stdout.splitlines() if line.strip()]


def rustc_host_triple() -> str:
    rustc = shutil.which("rustc")
    if not rustc:
        return ""
    cmd = [rustc]
    toolchain = rust_toolchain()
    if toolchain:
        cmd.append(f"+{toolchain}")
    cmd.append("-vV")
    try:
        proc = subprocess.run(
            cmd,
            cwd=str(ROOT),
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=30,
        )
    except Exception:
        return ""
    if proc.returncode != 0:
        return ""
    for line in proc.stdout.splitlines():
        if line.startswith("host:"):
            return line.split(":", 1)[1].strip()
    return ""


def run_platform_command(
    out_dir: Path,
    label: str,
    cmd: List[str],
    timeout: int,
    *,
    extra_env: Optional[Dict[str, str]] = None,
) -> Dict[str, Any]:
    stdout_path = out_dir / f"{label}.stdout.txt"
    stderr_path = out_dir / f"{label}.stderr.txt"
    env = os.environ.copy()
    env.setdefault("GLIBC_TUNABLES", "glibc.pthread.rseq=0")
    clean_extra_env = {
        str(key): str(value)
        for key, value in (extra_env or {}).items()
        if key is not None and value not in (None, "")
    }
    env.update(clean_extra_env)
    started = now_iso()
    start = time.perf_counter()
    error = None
    try:
        proc = subprocess.run(
            cmd,
            cwd=str(ROOT),
            env=env,
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=timeout,
        )
        exit_code = proc.returncode
        stdout_text = proc.stdout
        stderr_text = proc.stderr
    except subprocess.TimeoutExpired as exc:
        exit_code = 124
        error = f"timeout after {timeout}s: {exc}"
        stdout_text = exc.stdout or ""
        stderr_text = exc.stderr or ""
        if isinstance(stdout_text, bytes):
            stdout_text = stdout_text.decode("utf-8", errors="replace")
        if isinstance(stderr_text, bytes):
            stderr_text = stderr_text.decode("utf-8", errors="replace")
    ended = now_iso()
    stdout_path.write_text(stdout_text, encoding="utf-8")
    stderr_path.write_text(stderr_text, encoding="utf-8")
    return {
        "schema_version": 1,
        "label": label,
        "command": cmd,
        "started_at": started,
        "ended_at": ended,
        "wall_seconds": time.perf_counter() - start,
        "exit_code": exit_code,
        "error": error,
        "stdout": str(stdout_path),
        "stderr": str(stderr_path),
        "env_overrides": clean_extra_env,
        "passed": exit_code == 0,
    }


def write_platform_command_log(out_dir: Path, label: str, record: Dict[str, Any]) -> Path:
    """Write a single human-readable command log for platform matrix evidence."""

    path = out_dir / f"{label}.log"
    stdout_text = Path(record["stdout"]).read_text(encoding="utf-8", errors="replace") if record.get("stdout") else ""
    stderr_text = Path(record["stderr"]).read_text(encoding="utf-8", errors="replace") if record.get("stderr") else ""
    lines = [
        f"label: {record.get('label')}",
        "command: " + shlex.join(str(part) for part in record.get("command") or []),
        "env_overrides: " + json.dumps(record.get("env_overrides") or {}, sort_keys=True),
        f"started_at: {record.get('started_at')}",
        f"ended_at: {record.get('ended_at')}",
        f"wall_seconds: {record.get('wall_seconds')}",
        f"exit_code: {record.get('exit_code')}",
        f"passed: {record.get('passed')}",
        f"error: {record.get('error')}",
        "",
        "== stdout ==",
        stdout_text,
        "",
        "== stderr ==",
        stderr_text,
    ]
    path.write_text("\n".join(lines), encoding="utf-8")
    return path


def preserve_imported_source_artifact(
    out_dir: Path,
    source_path: Path,
    label: str,
    *,
    default_suffix: str = ".log",
) -> Tuple[Optional[Path], Optional[str], Optional[str]]:
    """Copy an imported evidence source into ``out_dir`` and return path/hash/error.

    External imports often come from ``/tmp`` or a developer-local checkout.  The
    normalized evidence artifact must remain auditable after those transient
    sources are cleaned, so collectors preserve a local copy before parsing.
    """

    suffix = source_path.suffix or default_suffix
    destination = out_dir / f"{label}{suffix}"
    try:
        if source_path.resolve() != destination.resolve():
            shutil.copy2(source_path, destination)
        return destination, file_sha256(destination), None
    except Exception as exc:
        return None, None, str(exc)


def local_metadata_artifact_path(status: Dict[str, Any]) -> Optional[Path]:
    """Return the local file behind a path/file-URI metadata status, if any.

    C007 constrained-platform evidence is claim-grade only when the boot
    transcript's image/config hashes can be rechecked later.  This helper keeps
    that rule explicit: labels, non-file URIs, directories, and missing paths do
    not produce a durable artifact path.
    """

    if not isinstance(status, dict):
        return None
    if status.get("kind") not in {"path", "file_uri"}:
        return None
    if not status.get("usable"):
        return None
    resolved = str(status.get("resolved") or "").strip()
    if not resolved:
        return None
    path = Path(resolved)
    if not path.exists() or not path.is_file():
        return None
    return path


def preserve_local_metadata_artifact(
    out_dir: Path,
    status: Dict[str, Any],
    label: str,
    *,
    default_suffix: str = ".bin",
) -> Tuple[Optional[Path], Dict[str, Any], Optional[str], Optional[str]]:
    """Preserve a locally hashable metadata artifact into ``out_dir``.

    Imported BlogOS/Redox boot logs often originate beside temporary VM images
    under ``/tmp``.  Claim-grade artifacts must remain independently auditable
    after those temp directories are cleaned, so image/config metadata used by
    boot-cycle JSON and platform matrices is rewritten to this preserved copy.
    The returned status describes the preserved path when the copy succeeds;
    otherwise it falls back to the original status and returns an error for the
    caller to surface as a fail-closed blocker.
    """

    source_path = local_metadata_artifact_path(status)
    if source_path is None:
        return None, status, None, None
    preserved, sha256, error = preserve_imported_source_artifact(
        out_dir,
        source_path,
        label,
        default_suffix=source_path.suffix or default_suffix,
    )
    if preserved is None:
        return None, status, sha256, error
    return preserved, local_path_status(str(preserved)), sha256, None


def preserve_constrained_boot_metadata_artifacts(
    out_dir: Path,
    *,
    platform_name: str,
    image_status: Dict[str, Any],
    boot_config_status: Dict[str, Any],
) -> Dict[str, Any]:
    """Copy constrained boot image/config metadata into the raw evidence dir."""

    image_preserved, durable_image_status, image_sha256, image_error = (
        preserve_local_metadata_artifact(
            out_dir,
            image_status,
            f"{platform_name}-target-image-artifact",
            default_suffix=".img",
        )
    )
    boot_config_preserved, durable_boot_config_status, boot_config_sha256, boot_config_error = (
        preserve_local_metadata_artifact(
            out_dir,
            boot_config_status,
            f"{platform_name}-boot-config-artifact",
            default_suffix=".cfg",
        )
    )
    return {
        "image": str(image_preserved) if image_preserved is not None else None,
        "image_status": durable_image_status,
        "image_sha256": image_sha256,
        "image_error": image_error,
        "boot_config": str(boot_config_preserved) if boot_config_preserved is not None else None,
        "boot_config_status": durable_boot_config_status,
        "boot_config_sha256": boot_config_sha256,
        "boot_config_error": boot_config_error,
        "blockers": unique_strings(
            [
                f"could not preserve {platform_name} target image artifact: {image_error}"
                if image_error
                else None,
                f"could not preserve {platform_name} boot_config artifact: {boot_config_error}"
                if boot_config_error
                else None,
            ]
        ),
    }


def parse_last_json_stdout_event(record: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Extract the last JSON object printed by a captured platform command."""

    stdout = record.get("stdout")
    if not stdout:
        return None
    path = Path(stdout)
    if not path.exists():
        return None
    for line in reversed(path.read_text(encoding="utf-8", errors="replace").splitlines()):
        line = line.strip()
        if not line.startswith("{"):
            continue
        try:
            event = json.loads(line)
        except json.JSONDecodeError:
            continue
        if isinstance(event, dict):
            return event
    return None


def directory_size_bytes(path: Path) -> int:
    total = 0
    if not path.exists():
        return 0
    if path.is_file():
        try:
            return path.stat().st_size
        except OSError:
            return 0
    for child in path.rglob("*"):
        if not child.is_file():
            continue
        try:
            total += child.stat().st_size
        except OSError:
            continue
    return total


def remove_directory_if_present(path: Path) -> Dict[str, Any]:
    removed_bytes = directory_size_bytes(path)
    existed = path.exists()
    if existed:
        shutil.rmtree(path)
    return {
        "path": str(path),
        "existed": existed,
        "removed": existed,
        "removed_bytes": removed_bytes if existed else 0,
    }


def fixed_heap_small_heap_event_blockers(event: Optional[Dict[str, Any]]) -> List[str]:
    """Validate the constrained fixed-heap runtime smoke event.

    BlogOS/Redox/Rust-for-Linux collection uses the host `small_heap` example as
    a narrow UniAlloc source/link/runtime contract check.  It is not boot
    evidence, but it must still prove the fixed-heap and C ABI paths were
    actually exercised with the target crate constants instead of a stale
    hard-coded 4 KiB assumption.
    """

    if not isinstance(event, dict):
        return ["small_heap did not print a parseable JSON event"]
    blockers: List[str] = []
    page_size = optional_int(event.get("page_size"))
    heap_size = optional_int(event.get("heap_size"))
    initial_heap_size = optional_int(event.get("initial_heap_size"))
    if event.get("passed") is not True:
        blockers.append("small_heap event did not report passed=true")
    if event.get("fixed_heap_ready") is not True:
        blockers.append("small_heap event did not report fixed_heap_ready=true")
    if event.get("init_api") != "unialloc_fixed_heap_try_init":
        blockers.append("small_heap did not use the fixed-heap C init API")
    if event.get("page_size_source") != "unialloc::PAGE_SIZE":
        blockers.append("small_heap page_size was not sourced from unialloc::PAGE_SIZE")
    if not page_size or page_size <= 0 or page_size & (page_size - 1):
        blockers.append("small_heap page_size is missing or not a power of two")
    if not heap_size or heap_size <= 0:
        blockers.append("small_heap heap_size is missing or non-positive")
    if not initial_heap_size or initial_heap_size <= 0:
        blockers.append("small_heap initial_heap_size is missing or non-positive")
    if page_size and heap_size and heap_size % page_size != 0:
        blockers.append("small_heap heap_size is not page-size aligned")
    if page_size and initial_heap_size and initial_heap_size % page_size != 0:
        blockers.append("small_heap initial_heap_size is not page-size aligned")
    if heap_size and initial_heap_size and heap_size <= initial_heap_size:
        blockers.append("small_heap did not reserve a larger range than the initial heap")

    for name in ("before_extend", "after_extend"):
        batch = event.get(name)
        if not isinstance(batch, dict):
            blockers.append(f"small_heap {name} batch report is missing")
            continue
        if not optional_int(batch.get("allocations")):
            blockers.append(f"small_heap {name} allocations is missing or zero")
        if not optional_int(batch.get("bytes")):
            blockers.append(f"small_heap {name} bytes is missing or zero")
        if not optional_int(batch.get("checksum")):
            blockers.append(f"small_heap {name} checksum is missing or zero")

    c_abi = event.get("c_abi")
    if not isinstance(c_abi, dict):
        blockers.append("small_heap C ABI report is missing")
        return unique_strings(blockers)
    if c_abi.get("invoked") is not True:
        blockers.append("small_heap C ABI workload was not invoked")
    if c_abi.get("ready_after_init") is not True:
        blockers.append("small_heap C ABI did not observe fixed heap ready after init")
    if (optional_int(c_abi.get("invalid_layouts_rejected")) or 0) < 3:
        blockers.append("small_heap C ABI did not reject the required invalid layouts")
    if (optional_int(c_abi.get("round_trips")) or 0) < 2:
        blockers.append("small_heap C ABI did not complete alloc/realloc/dealloc round trips")
    if c_abi.get("over_page_alignment_checked") is not True:
        blockers.append("small_heap C ABI did not check over-page alignment")
    over_page_alignment = optional_int(c_abi.get("over_page_alignment"))
    if not over_page_alignment:
        blockers.append("small_heap C ABI over_page_alignment is missing")
    elif page_size and over_page_alignment < page_size * 2:
        blockers.append("small_heap C ABI over_page_alignment is smaller than two target pages")
    elif over_page_alignment & (over_page_alignment - 1):
        blockers.append("small_heap C ABI over_page_alignment is not a power of two")
    if not optional_int(c_abi.get("checksum")):
        blockers.append("small_heap C ABI checksum is missing or zero")
    return unique_strings(blockers)


def parse_platform_workload_event(record: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Extract the JSON event printed by the platform allocator workload."""

    event = parse_last_json_stdout_event(record)
    if event and event.get("source") == "platform_allocator_workload":
        return event
    return None


def collect_platform_runtime_workload_samples(
    *,
    out_dir: Path,
    label_prefix: str,
    command: List[str],
    timeout: int,
    sample_count: int,
    extra_env: Optional[Dict[str, str]] = None,
) -> Tuple[List[Dict[str, Any]], List[Dict[str, Any]], List[Path]]:
    """Run repeated platform_allocator_workload samples with attached events.

    The platform claim gate later validates ``records`` and ``events`` together.
    Keeping event extraction inside this helper avoids future call sites passing
    detached/stale JSON events that did not come from the command record being
    audited.
    """

    records: List[Dict[str, Any]] = []
    events: List[Dict[str, Any]] = []
    logs: List[Path] = []
    for sample_idx in range(sample_count):
        label = f"{label_prefix}-{sample_idx + 1}"
        run_rec = run_platform_command(out_dir, label, list(command), timeout, extra_env=extra_env)
        event = parse_platform_workload_event(run_rec)
        run_rec["parsed_event"] = event
        run_rec["parsed_event_valid"] = bool(event and event.get("passed") is True)
        records.append(run_rec)
        if event:
            events.append(event)
        logs.append(write_platform_command_log(out_dir, label, run_rec))
    return records, events, logs


def collect_imported_platform_runtime_workload_samples(
    *,
    out_dir: Path,
    label_prefix: str,
    artifact_paths: Iterable[Path],
) -> Tuple[List[Dict[str, Any]], List[Dict[str, Any]], List[Path]]:
    """Import externally captured platform_allocator_workload stdout/log files.

    This is intended for platforms that cannot execute locally in the current
    collector process (for example a Windows target when the host has no Wine).
    Imported artifacts are *not* treated specially by the claim gate: the helper
    attaches source paths and sha256 digests, then `platform_workload_runtime_ready`
    applies the same event-shape, checksum, and profile checks used for local
    command execution.
    """

    records: List[Dict[str, Any]] = []
    events: List[Dict[str, Any]] = []
    logs: List[Path] = []
    for sample_idx, raw_path in enumerate(artifact_paths):
        label = f"{label_prefix}-{sample_idx + 1}"
        path = raw_path.expanduser()
        if not path.is_absolute():
            path = (ROOT / path).resolve()
        event: Optional[Dict[str, Any]] = None
        source_sha256: Optional[str] = None
        error: Optional[str] = None
        if path.exists() and path.is_file():
            source_sha256 = file_sha256(path)
            event = parse_platform_workload_event({"stdout": str(path)})
            if event is None:
                error = "imported runtime artifact does not contain a platform_allocator_workload JSON event"
        else:
            error = f"imported runtime artifact does not exist or is not a file: {path}"
        record = {
            "schema_version": 1,
            "label": label,
            "command": ["external-platform-runtime-import", str(path)],
            "started_at": None,
            "ended_at": None,
            "wall_seconds": None,
            "exit_code": 0 if event and event.get("passed") is True else 1,
            "error": error,
            "stdout": str(path) if path.is_file() else None,
            "stderr": None,
            "env_overrides": {},
            "passed": bool(event and event.get("passed") is True),
            "external_runtime_import": True,
            "source_artifact": str(path),
            "source_artifact_sha256": source_sha256,
            "parsed_event": event,
            "parsed_event_valid": bool(event and event.get("passed") is True),
        }
        records.append(record)
        if event:
            events.append(event)
        logs.append(write_platform_command_log(out_dir, label, record))
    return records, events, logs


def platform_workload_profile(event: Dict[str, Any]) -> Dict[str, Any]:
    """Return the stable, security-relevant shape of a workload event."""

    keys = (
        "source",
        "allocator",
        "global_allocator",
        "global_allocator_active",
        "target_os",
        "target_family",
        "target_arch",
        "allocator_backend",
        "system_backend",
        "thread_local_backend",
        "thread_local_key_ready",
        "thread_local_save_failures",
        "threads",
        "iters",
        "max_len",
    )
    return {key: event.get(key) for key in keys}


def platform_workload_runtime_ready(
    *,
    records: Iterable[Dict[str, Any]],
    events: Iterable[Dict[str, Any]],
    requested_samples: int,
    expected_threads: int,
    expected_iters: int,
    expected_max_len: int,
    expected_target_os: Optional[str] = None,
    expected_allocator: str = "UniAlloc",
) -> Tuple[bool, List[str]]:
    """Validate real platform_allocator_workload samples for C007 evidence.

    This is a retargeting/runtime-evidence gate, not a performance-claim gate:
    it proves the platform build can execute UniAlloc as the global allocator
    and produce reproducible workload events.  It intentionally fails closed
    when a command exits successfully but does not emit the expected JSON event.
    """

    record_list = list(records)
    event_list = list(events)
    blockers: List[str] = []
    if requested_samples <= 0:
        blockers.append("requested runtime sample count must be positive")
    if len(record_list) != requested_samples:
        blockers.append(f"runtime executed {len(record_list)}/{requested_samples} requested samples")
    if len(event_list) != requested_samples:
        blockers.append(f"runtime emitted {len(event_list)}/{requested_samples} valid workload events")
    for idx, record in enumerate(record_list, start=1):
        if record.get("passed") is not True:
            blockers.append(f"runtime sample {idx} command did not pass")
        command = record.get("command")
        if not isinstance(command, list) or not command:
            blockers.append(f"runtime sample {idx} has no recorded command argv")
        if record.get("parsed_event_valid") is not True:
            blockers.append(f"runtime sample {idx} did not emit a valid workload JSON event")
        parsed_event = record.get("parsed_event")
        expected_event = event_list[idx - 1] if idx - 1 < len(event_list) else None
        if parsed_event != expected_event:
            blockers.append(f"runtime sample {idx} parsed_event is detached from the validated event list")
    checksums: List[int] = []
    profiles: List[str] = []
    for idx, event in enumerate(event_list, start=1):
        if event.get("source") != "platform_allocator_workload":
            blockers.append(f"runtime event {idx} has unexpected source {event.get('source')!r}")
        if event.get("passed") is not True:
            blockers.append(f"runtime event {idx} reports passed=false")
        if expected_allocator:
            if event.get("allocator") != expected_allocator:
                blockers.append(f"runtime event {idx} allocator is not {expected_allocator}")
            if event.get("global_allocator") != expected_allocator:
                blockers.append(f"runtime event {idx} global_allocator is not {expected_allocator}")
        if event.get("global_allocator_active") is not True:
            blockers.append(f"runtime event {idx} does not report an active UniAlloc global allocator")
        if event.get("allocator_stats_recording_active") is not True:
            blockers.append(f"runtime event {idx} did not enable UniAlloc allocator stats recording")
        if event.get("unialloc_allocator_activity_observed") is not True:
            blockers.append(f"runtime event {idx} did not observe UniAlloc allocation/deallocation activity")
        if event.get("allocator_allocation_counters_consistent") is not True:
            blockers.append(f"runtime event {idx} does not report consistent allocation counters")
        if event.get("allocator_deallocation_counters_consistent") is not True:
            blockers.append(f"runtime event {idx} does not report consistent deallocation counters")
        if event.get("allocator_allocated_byte_counters_consistent") is not True:
            blockers.append(f"runtime event {idx} does not report consistent allocated-byte counters")
        if event.get("allocator_coverage_basis_points_valid") is not True:
            blockers.append(f"runtime event {idx} does not report valid coverage basis points")
        total_allocations = optional_int(event.get("allocator_total_allocations"))
        if total_allocations is None or total_allocations <= 0:
            blockers.append(f"runtime event {idx} has no positive allocator_total_allocations counter")
        total_deallocations = optional_int(event.get("allocator_total_deallocations"))
        if total_deallocations is None or total_deallocations <= 0:
            blockers.append(f"runtime event {idx} has no positive allocator_total_deallocations counter")
        fallback_allocations = optional_int(event.get("allocator_fallback_allocations"))
        typed_allocations = optional_int(event.get("allocator_typed_allocations"))
        if fallback_allocations is None:
            blockers.append(f"runtime event {idx} has no allocator_fallback_allocations counter")
        if typed_allocations is None:
            blockers.append(f"runtime event {idx} has no allocator_typed_allocations counter")
        if fallback_allocations is not None and typed_allocations is not None and total_allocations is not None:
            if fallback_allocations + typed_allocations != total_allocations:
                blockers.append(
                    f"runtime event {idx} allocator allocation counters do not add up to total"
                )
        fallback_deallocations = optional_int(event.get("allocator_fallback_deallocations"))
        typed_deallocations = optional_int(event.get("allocator_typed_deallocations"))
        if fallback_deallocations is None:
            blockers.append(f"runtime event {idx} has no allocator_fallback_deallocations counter")
        if typed_deallocations is None:
            blockers.append(f"runtime event {idx} has no allocator_typed_deallocations counter")
        if (
            fallback_deallocations is not None
            and typed_deallocations is not None
            and total_deallocations is not None
        ):
            if fallback_deallocations + typed_deallocations != total_deallocations:
                blockers.append(
                    f"runtime event {idx} allocator deallocation counters do not add up to total"
                )
        live_allocations = optional_int(event.get("allocator_live_allocations"))
        if live_allocations is None:
            blockers.append(f"runtime event {idx} has no allocator_live_allocations counter")
        elif total_allocations is not None and total_deallocations is not None:
            expected_live = max(total_allocations - total_deallocations, 0)
            if live_allocations != expected_live:
                blockers.append(
                    f"runtime event {idx} allocator_live_allocations does not match total allocations minus deallocations"
                )
        total_allocated_bytes = optional_int(event.get("allocator_total_allocated_bytes"))
        if total_allocated_bytes is None or total_allocated_bytes <= 0:
            blockers.append(f"runtime event {idx} has no positive allocator_total_allocated_bytes counter")
        typed_allocated_bytes = optional_int(event.get("allocator_typed_allocated_bytes"))
        fallback_allocated_bytes = optional_int(event.get("allocator_fallback_allocated_bytes"))
        if typed_allocated_bytes is None:
            blockers.append(f"runtime event {idx} has no allocator_typed_allocated_bytes counter")
        if fallback_allocated_bytes is None:
            blockers.append(f"runtime event {idx} has no allocator_fallback_allocated_bytes counter")
        if (
            typed_allocated_bytes is not None
            and fallback_allocated_bytes is not None
            and total_allocated_bytes is not None
        ):
            if typed_allocated_bytes + fallback_allocated_bytes != total_allocated_bytes:
                blockers.append(
                    f"runtime event {idx} allocator allocated-byte counters do not add up to total"
                )
        coverage_basis_points = optional_int(event.get("allocator_coverage_basis_points"))
        if coverage_basis_points is None:
            blockers.append(f"runtime event {idx} has no allocator_coverage_basis_points counter")
        elif coverage_basis_points > 10_000:
            blockers.append(f"runtime event {idx} allocator_coverage_basis_points exceeds 10000")
        if expected_target_os and event.get("target_os") != expected_target_os:
            blockers.append(
                f"runtime event {idx} target_os {event.get('target_os')!r} does not match {expected_target_os!r}"
            )
        if expected_target_os == "windows" and event.get("target_family") != "windows":
            blockers.append(f"runtime event {idx} target_family is not 'windows'")
        if not str(event.get("target_arch") or "").strip():
            blockers.append(f"runtime event {idx} has no target_arch")
        if not str(event.get("allocator_backend") or "").strip():
            blockers.append(f"runtime event {idx} has no allocator_backend")
        if not str(event.get("system_backend") or "").strip():
            blockers.append(f"runtime event {idx} has no system_backend")
        if not str(event.get("thread_local_backend") or "").strip():
            blockers.append(f"runtime event {idx} has no thread_local_backend")
        if event.get("thread_local_key_ready") is not True:
            blockers.append(f"runtime event {idx} thread-local destructor key is not ready")
        tls_failures = optional_int(event.get("thread_local_save_failures"))
        if tls_failures is None:
            blockers.append(f"runtime event {idx} has no thread_local_save_failures counter")
        elif tls_failures != 0:
            blockers.append(f"runtime event {idx} recorded {tls_failures} thread-local save failures")
        if optional_int(event.get("threads")) != expected_threads:
            blockers.append(f"runtime event {idx} threads does not match requested {expected_threads}")
        if optional_int(event.get("iters")) != expected_iters:
            blockers.append(f"runtime event {idx} iters does not match requested {expected_iters}")
        if optional_int(event.get("max_len")) != expected_max_len:
            blockers.append(f"runtime event {idx} max_len does not match requested {expected_max_len}")
        duration_ns = optional_int(event.get("duration_ns"))
        if duration_ns is None or duration_ns <= 0:
            blockers.append(f"runtime event {idx} has no positive duration_ns")
        checksum = optional_int(event.get("checksum"))
        if checksum is None:
            blockers.append(f"runtime event {idx} has no checksum")
        else:
            checksums.append(checksum)
        profiles.append(json.dumps(platform_workload_profile(event), sort_keys=True))
    if len(checksums) == requested_samples and len(set(checksums)) != 1:
        blockers.append("runtime workload checksums are not stable across samples")
    if len(profiles) == requested_samples and len(set(profiles)) != 1:
        blockers.append("runtime workload profiles are not stable across samples")
    return not blockers, unique_strings(blockers)


WINDOWS_RUNTIME_RUNNER_ENV = "UNIALLOC_WINDOWS_RUNTIME_RUNNER"
WINDOWS_LINKER_ENV = "UNIALLOC_WINDOWS_LINKER"
WINDOWS_DOCKER_WINE_IMAGE_ENV = "UNIALLOC_WINDOWS_WINE_IMAGE"
WINDOWS_DOCKER_WINE_DEFAULT_IMAGE = "unialloc-windows-wine-runner:bookworm"


def docker_image_status(image: str, *, timeout: int = 15) -> Dict[str, Any]:
    """Return a fail-closed local Docker image availability record."""

    docker = shutil.which("docker")
    if not docker:
        return {
            "image": image,
            "available": False,
            "docker": None,
            "diagnostics": ["docker is not on PATH"],
        }
    try:
        proc = subprocess.run(
            [docker, "image", "inspect", image, "--format", "{{.Id}}"],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=timeout,
        )
    except subprocess.TimeoutExpired as exc:
        return {
            "image": image,
            "available": False,
            "docker": docker,
            "diagnostics": [f"docker image inspect timed out after {timeout}s: {exc}"],
        }
    except OSError as exc:
        return {
            "image": image,
            "available": False,
            "docker": docker,
            "diagnostics": [f"docker image inspect failed: {exc}"],
        }
    image_id = proc.stdout.strip()
    return {
        "image": image,
        "available": proc.returncode == 0 and bool(image_id),
        "docker": docker,
        "image_id": image_id or None,
        "exit_code": proc.returncode,
        "stderr": proc.stderr.strip(),
        "diagnostics": []
        if proc.returncode == 0 and image_id
        else [
            "Docker/Wine runner image is not available locally; build "
            "evaluation/docker/windows-wine-runner.Dockerfile first"
        ],
    }


def configured_executable_selection(value: Optional[str], *, label: str) -> Dict[str, Any]:
    """Resolve a configured executable path/name without silently accepting typos."""

    raw = str(value or "").strip()
    if not raw:
        return {
            "configured": None,
            "path": None,
            "available": False,
            "diagnostics": [f"{label} is not configured"],
        }
    candidate = Path(raw).expanduser()
    if candidate.is_absolute() or "/" in raw:
        usable = candidate.exists() and os.access(str(candidate), os.X_OK)
        return {
            "configured": raw,
            "path": str(candidate.resolve()) if usable else None,
            "available": usable,
            "diagnostics": []
            if usable
            else [f"configured {label} is not executable or does not exist: {raw}"],
        }
    found = shutil.which(raw)
    return {
        "configured": raw,
        "path": found,
        "available": bool(found),
        "diagnostics": [] if found else [f"configured {label} is not on PATH: {raw}"],
    }


def cargo_target_env_fragment(target: str) -> str:
    return re.sub(r"[^A-Z0-9]", "_", str(target).upper())


def windows_linker_env_key(target: str) -> str:
    return f"CARGO_TARGET_{cargo_target_env_fragment(target)}_LINKER"


def windows_target_requires_external_linker(target: str) -> bool:
    return str(target).endswith("-gnu")


def executable_version_probe(path: str, *, timeout: int = 10) -> Tuple[bool, str]:
    """Return whether an executable can start and print version-like output."""

    try:
        proc = subprocess.run(
            [path, "--version"],
            cwd=str(ROOT),
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=timeout,
        )
    except Exception as exc:
        return False, str(exc)
    output = (proc.stdout + proc.stderr).strip()
    if proc.returncode != 0:
        return False, output or f"exit code {proc.returncode}"
    return True, output.splitlines()[0] if output else ""


def repo_zig_windows_linker_selection(target: str) -> Optional[Dict[str, Any]]:
    """Return the repo-local Zig Windows GNU linker wrapper if it is usable."""

    if target != "x86_64-pc-windows-gnu":
        return None
    wrapper = ROOT / "tools" / "windows" / "zig-rustlink-x86_64-pc-windows-gnu.sh"
    resolved = configured_executable_selection(str(wrapper), label="repo Zig Windows linker wrapper")
    candidate = {"source": "repo-tools", **resolved}
    if not resolved["available"]:
        return {
            "source": "repo-tools",
            "candidate": candidate,
            "available": False,
            "diagnostics": resolved["diagnostics"],
            "linker": None,
        }
    ok, version = executable_version_probe(str(wrapper))
    candidate["version_probe"] = version
    candidate["version_probe_passed"] = ok
    if not ok:
        candidate["available"] = False
        diagnostic = f"repo Zig Windows linker wrapper is present but not runnable: {version}"
        candidate["diagnostics"] = [diagnostic]
        return {
            "source": "repo-tools",
            "candidate": candidate,
            "available": False,
            "diagnostics": [diagnostic],
            "linker": None,
        }
    candidate["diagnostics"] = []
    return {
        "source": "repo-tools",
        "candidate": candidate,
        "available": True,
        "diagnostics": [],
        "linker": str(wrapper.resolve()),
    }


def windows_linker_selection(target: str, configured: Optional[str] = None) -> Dict[str, Any]:
    """Select the Windows target linker used for real executable build evidence.

    Cargo can type-check the Windows target without a MinGW linker, but the C007
    runtime path must produce an executable before it can run under Wine or a
    target host.  Resolve that linker explicitly and record fail-closed
    diagnostics instead of discovering the missing tool only after a long build.
    """

    env_key = windows_linker_env_key(target)
    required = windows_target_requires_external_linker(target)
    selection = {
        "target": target,
        "required": required,
        "env_key": env_key,
        "linker": None,
        "source": None,
        "available": not required,
        "diagnostics": [] if not required else [],
        "candidates": [],
    }
    if not required:
        selection["diagnostics"] = [
            "Windows target does not require an external MinGW-style linker override"
        ]
        return selection

    explicit = str(configured or "").strip()
    if explicit:
        resolved = configured_executable_selection(explicit, label="Windows linker")
        selection["candidates"].append({"source": "--windows-linker", **resolved})
        selection["linker"] = resolved["path"]
        selection["source"] = "--windows-linker"
        selection["available"] = bool(resolved["available"])
        selection["diagnostics"] = resolved["diagnostics"]
        return selection

    env_value = str(os.environ.get(WINDOWS_LINKER_ENV, "")).strip()
    if env_value:
        resolved = configured_executable_selection(env_value, label=f"{WINDOWS_LINKER_ENV} linker")
        selection["candidates"].append({"source": WINDOWS_LINKER_ENV, **resolved})
        selection["linker"] = resolved["path"]
        selection["source"] = WINDOWS_LINKER_ENV
        selection["available"] = bool(resolved["available"])
        selection["diagnostics"] = resolved["diagnostics"]
        return selection

    for candidate in ("x86_64-w64-mingw32-gcc",):
        found = shutil.which(candidate)
        selection["candidates"].append(
            {
                "source": "PATH",
                "configured": candidate,
                "path": found,
                "available": bool(found),
                "diagnostics": [] if found else [f"{candidate} is not on PATH"],
            }
        )
        if found:
            selection["linker"] = found
            selection["source"] = "PATH"
            selection["available"] = True
            selection["diagnostics"] = []
            return selection
    repo_zig = repo_zig_windows_linker_selection(target)
    if repo_zig is not None:
        selection["candidates"].append(repo_zig["candidate"])
        if repo_zig["available"]:
            selection["linker"] = repo_zig["linker"]
            selection["source"] = repo_zig["source"]
            selection["available"] = True
            selection["diagnostics"] = []
            return selection
    selection["diagnostics"] = [
        "missing x86_64-w64-mingw32-gcc linker",
        "repo Zig Windows linker wrapper is unavailable"
        if repo_zig is None
        else "; ".join(str(item) for item in repo_zig.get("diagnostics", [])),
        f"set --windows-linker or {WINDOWS_LINKER_ENV} to an executable linker path",
    ]
    return selection


def windows_cargo_env(target: str, linker_selection: Dict[str, Any]) -> Dict[str, str]:
    linker = linker_selection.get("linker")
    if not linker:
        return {}
    return {windows_linker_env_key(target): str(linker)}


def windows_link_failure_blockers(linker_output: str) -> List[str]:
    """Classify common Windows executable link failures into actionable blockers."""

    text = linker_output or ""
    blockers: List[str] = []
    if "x86_64-w64-mingw32-gcc" in text and "not found" in text:
        blockers.append("missing x86_64-w64-mingw32-gcc linker")
    missing_libraries = unique_strings(
        match.group(1)
        for match in re.finditer(r"unable to find library\s+([^\s]+)", text)
        if match.group(1)
    )
    if missing_libraries:
        preview = ", ".join(missing_libraries[:8])
        if len(missing_libraries) > 8:
            preview += f", ... ({len(missing_libraries)} total)"
        blockers.append(f"missing Windows import/runtime libraries for linker: {preview}")
    return blockers


def windows_runtime_runner_selection(configured: Optional[str] = None) -> Dict[str, Any]:
    """Return the Windows userspace execution selection with auditable provenance.

    A non-Windows host needs an explicit runner (usually Wine).  A native
    Windows host can execute the produced .exe directly, so it must not be
    rejected merely because wine/wine64 is absent.  The returned
    ``command_prefix`` is prepended before the executable path when launching
    runtime samples.
    """

    explicit = str(configured or "").strip()
    if explicit:
        resolved = configured_executable_selection(explicit, label="Windows runtime runner")
        return {
            "runner": resolved["path"],
            "mode": "runner",
            "command_prefix": [resolved["path"]] if resolved["available"] else [],
            "source": "--windows-runtime-runner",
            "available": bool(resolved["available"]),
            "diagnostics": resolved["diagnostics"],
            "candidates": [{"source": "--windows-runtime-runner", **resolved}],
        }
    env_value = str(os.environ.get(WINDOWS_RUNTIME_RUNNER_ENV, "")).strip()
    if env_value:
        resolved = configured_executable_selection(env_value, label=f"{WINDOWS_RUNTIME_RUNNER_ENV} runner")
        return {
            "runner": resolved["path"],
            "mode": "runner",
            "command_prefix": [resolved["path"]] if resolved["available"] else [],
            "source": WINDOWS_RUNTIME_RUNNER_ENV,
            "available": bool(resolved["available"]),
            "diagnostics": resolved["diagnostics"],
            "candidates": [{"source": WINDOWS_RUNTIME_RUNNER_ENV, **resolved}],
        }
    candidates = []
    if platform.system().lower() == "windows":
        native_candidate = {
            "source": "native-host",
            "configured": None,
            "path": None,
            "available": True,
            "diagnostics": [],
        }
        candidates.append(native_candidate)
        return {
            "runner": None,
            "mode": "native",
            "command_prefix": [],
            "source": "native-host",
            "available": True,
            "diagnostics": [],
            "candidates": candidates,
        }
    for candidate in ("wine64", "wine"):
        found = shutil.which(candidate)
        candidates.append(
            {
                "source": "PATH",
                "configured": candidate,
                "path": found,
                "available": bool(found),
                "diagnostics": [] if found else [f"{candidate} is not on PATH"],
            }
        )
        if found:
            return {
                "runner": found,
                "mode": "runner",
                "command_prefix": [found],
                "source": "PATH",
                "available": True,
                "diagnostics": [],
                "candidates": candidates,
            }
    repo_docker_runner = ROOT / "tools" / "windows" / "docker-wine-runner.sh"
    docker_image = str(
        os.environ.get(WINDOWS_DOCKER_WINE_IMAGE_ENV, WINDOWS_DOCKER_WINE_DEFAULT_IMAGE)
    ).strip() or WINDOWS_DOCKER_WINE_DEFAULT_IMAGE
    docker_runner = configured_executable_selection(
        str(repo_docker_runner),
        label="repo Docker/Wine Windows runtime runner",
    )
    docker_status = docker_image_status(docker_image)
    docker_runner_available = bool(docker_runner["available"] and docker_status["available"])
    docker_diagnostics = unique_strings(
        [
            *docker_runner["diagnostics"],
            *docker_status.get("diagnostics", []),
        ]
    )
    docker_candidate = {
        "source": "repo-docker-wine-runner",
        **docker_runner,
        "available": docker_runner_available,
        "diagnostics": docker_diagnostics,
        "docker_image": docker_status,
    }
    candidates.append(docker_candidate)
    if docker_runner_available:
        return {
            "runner": docker_runner["path"],
            "mode": "runner",
            "command_prefix": [docker_runner["path"]],
            "source": "repo-docker-wine-runner",
            "available": True,
            "diagnostics": [],
            "candidates": candidates,
            "docker_image": docker_status,
        }
    return {
        "runner": None,
        "mode": "runner",
        "command_prefix": [],
        "source": None,
        "available": False,
        "diagnostics": [
            "no native Windows host, Wine/wine64 runner, or ready repo Docker/Wine runner available"
        ],
        "candidates": candidates,
    }


def windows_runtime_command_prefix(selection: Dict[str, Any]) -> List[str]:
    """Return the command prefix used before a Windows executable path."""

    raw_prefix = selection.get("command_prefix")
    if isinstance(raw_prefix, list):
        return [str(item) for item in raw_prefix if str(item)]
    runner = selection.get("runner")
    return [str(runner)] if runner else []


def windows_runtime_runner(configured: Optional[str] = None) -> Optional[str]:
    """Return a configured/auto-detected Windows userspace runner, if any.

    Native Windows execution intentionally returns ``None`` because no wrapper
    executable is required; inspect ``windows_runtime_runner_selection`` for the
    full execution mode.
    """

    return windows_runtime_runner_selection(configured).get("runner")


def windows_example_executable(target: str, cargo_target_dir: Optional[Path] = None) -> Optional[Path]:
    """Locate the built Windows platform allocator workload executable."""

    base_target_dir = cargo_target_dir if cargo_target_dir is not None else ROOT / "target"
    examples_dir = base_target_dir / target / "debug" / "examples"
    direct = examples_dir / "platform_allocator_workload.exe"
    if direct.exists():
        return direct
    matches = sorted(examples_dir.glob("platform_allocator_workload*.exe")) if examples_dir.exists() else []
    return matches[0] if matches else None


def platform_command_artifact(
    record: Dict[str, Any],
    *,
    log: Optional[Path] = None,
    passed: Optional[bool] = None,
) -> Dict[str, Any]:
    """Return a normalized command artifact reference for platform evidence JSON.

    Platform claim-grade gates need to distinguish "the command was really run"
    from "we skipped a step because a prerequisite was absent".  Keeping this
    shape consistent makes blocker artifacts auditable without relying on a
    fragile set of ad-hoc top-level fields.
    """

    artifact = {
        "label": record.get("label"),
        "command": record.get("command"),
        "exit_code": record.get("exit_code"),
        "passed": bool(record.get("passed")) if passed is None else bool(passed),
        "error": record.get("error"),
        "stdout": record.get("stdout"),
        "stderr": record.get("stderr"),
        "env_overrides": record.get("env_overrides") or {},
        "started_at": record.get("started_at"),
        "ended_at": record.get("ended_at"),
        "wall_seconds": record.get("wall_seconds"),
    }
    if log is not None:
        artifact["log"] = str(log)
    for key in (
        "external_runtime_import",
        "external_kernel_build_import",
        "external_boot_log_import",
        "platform",
        "display_name",
        "source_artifact",
        "source_artifact_sha256",
        "imported_source_artifact",
        "imported_source_artifact_sha256",
        "success_pattern",
        "success_pattern_matched",
        "required_log_markers",
        "matched_log_markers",
        "missing_required_log_markers",
    ):
        if key in record:
            artifact[key] = record.get(key)
    return artifact


def platform_runtime_run_artifacts(
    records: Iterable[Dict[str, Any]],
    logs: Iterable[Path] = (),
) -> List[Dict[str, Any]]:
    """Return normalized runtime command artifacts with parsed workload events."""

    log_list = list(logs)
    artifacts: List[Dict[str, Any]] = []
    for idx, record in enumerate(records):
        log = log_list[idx] if idx < len(log_list) else None
        artifact = {
            **platform_command_artifact(record, log=log),
            "parsed_event_valid": record.get("parsed_event_valid"),
            "parsed_event": record.get("parsed_event"),
        }
        for key in ("external_runtime_import", "source_artifact", "source_artifact_sha256"):
            if key in record:
                artifact[key] = record.get(key)
        artifacts.append(artifact)
    return artifacts


def windows_runtime_workload_blockers(
    *,
    runtime_check_rec: Dict[str, Any],
    runtime_build_rec: Dict[str, Any],
    windows_linker: Dict[str, Any],
    windows_runner_selection: Dict[str, Any],
    windows_exe: Optional[Path],
    runtime_can_execute: bool,
    runtime_import_requested: bool,
    runtime_passed: bool,
    runtime_validation_blockers: Iterable[str],
) -> List[str]:
    """Classify why Windows runtime workload evidence is not claim-grade.

    This helper intentionally fails closed.  A successful cargo-check is useful
    retargeting evidence, but C007 Windows runtime evidence still needs a linked
    executable, a real Windows userspace runner/host, and valid workload events.
    """

    blockers: List[str] = []
    if not runtime_check_rec.get("passed"):
        blockers.append("Windows workload example cargo check failed")
    if not runtime_build_rec.get("passed"):
        blockers.append("Windows workload executable build/link failed")
        blockers.extend(str(item) for item in windows_linker.get("diagnostics", []) if item)
        blockers.extend(windows_link_failure_blockers(command_output_text(runtime_build_rec)))
    if not windows_runner_selection.get("available") and not runtime_import_requested:
        blockers.extend(str(item) for item in windows_runner_selection.get("diagnostics", []) if item)
    if runtime_build_rec.get("passed") and not windows_exe:
        blockers.append("built Windows workload executable was not found")
    if (runtime_can_execute or runtime_import_requested) and not runtime_passed:
        blockers.extend(
            str(item)
            for item in runtime_validation_blockers
            if item
        )
        if not blockers:
            blockers.append("Windows workload runtime command did not produce valid passing JSON events")
    return unique_strings(blockers or ["Windows runtime workload was requested but not validated"])


def command_output_text(record: Dict[str, Any]) -> str:
    """Return combined stdout/stderr text for a command record."""

    chunks: List[str] = []
    for key in ("stdout", "stderr"):
        path_value = record.get(key)
        if not path_value:
            continue
        path = Path(str(path_value))
        if path.is_file():
            chunks.append(path.read_text(encoding="utf-8", errors="replace"))
    return "\n".join(chunks)


def success_pattern_matches(text: str, pattern: Optional[str]) -> Tuple[bool, Optional[str]]:
    """Check an optional boot-success marker.

    Plain patterns are substring matches. Prefix a pattern with ``re:`` to use a
    regular expression. Returning an error string lets callers fail closed on an
    invalid regex instead of silently treating a bad pattern as success.
    """

    if not pattern:
        return True, None
    if pattern.startswith("re:"):
        try:
            return re.search(pattern[3:], text, flags=re.MULTILINE) is not None, None
        except re.error as exc:
            return False, f"boot success regex is invalid: {exc}"
    return pattern in text, None


def render_boot_command(
    raw_command: str,
    *,
    platform_name: str,
    image: str,
    emulator: str,
    boot_config: str,
) -> Tuple[List[str], Optional[str], Optional[str]]:
    """Expand platform boot-command placeholders and split into argv."""

    try:
        rendered = raw_command.format(
            platform=platform_name,
            image=image,
            emulator=emulator,
            boot_config=boot_config,
        )
    except KeyError as exc:
        return [], None, f"boot command references unknown placeholder: {exc}"
    except ValueError as exc:
        return [], None, f"boot command format string is invalid: {exc}"
    try:
        return shlex.split(rendered), rendered, None
    except ValueError as exc:
        return [], rendered, f"boot command could not be parsed with shlex: {exc}"


def local_path_status(value: str) -> Dict[str, Any]:
    """Describe whether a user-supplied path-like metadata value is usable."""

    if not value:
        return {"value": value, "provided": False, "kind": "empty", "usable": False}
    if is_uri(value):
        if value.lower().startswith("file://"):
            path = local_file_uri_path(value)
            if path is None:
                return {
                    "value": value,
                    "provided": True,
                    "kind": "file_uri",
                    "usable": False,
                    "diagnostics": ["file:// URI does not identify a local filesystem path"],
                }
            return {
                "value": value,
                "provided": True,
                "kind": "file_uri",
                "resolved": str(path),
                "exists": path.exists(),
                "usable": path.exists() and path.is_file(),
                "diagnostics": [] if path.exists() and path.is_file() else [f"file URI path is not a readable file: {path}"],
            }
        return {"value": value, "provided": True, "kind": "uri", "usable": True}
    path = Path(value).expanduser()
    if not path.is_absolute():
        path = (ROOT / path).resolve()
    return {
        "value": value,
        "provided": True,
        "kind": "path",
        "resolved": str(path),
        "exists": path.exists(),
        "usable": path.exists(),
    }


def executable_status(value: str) -> Dict[str, Any]:
    """Describe whether a user-supplied executable/emulator metadata value resolves."""

    if not value:
        return {"value": value, "provided": False, "kind": "empty", "usable": False}
    if is_uri(value):
        return {"value": value, "provided": True, "kind": "uri", "usable": True}
    resolved = shutil.which(value)
    if resolved:
        return {"value": value, "provided": True, "kind": "path", "resolved": resolved, "usable": True}
    path = Path(value).expanduser()
    if not path.is_absolute():
        path = (ROOT / path).resolve()
    exists = path.exists()
    executable = exists and os.access(path, os.X_OK)
    return {
        "value": value,
        "provided": True,
        "kind": "path",
        "resolved": str(path),
        "exists": exists,
        "executable": executable,
        "usable": executable,
    }


def recognized_boot_emulator(value: str, status: Dict[str, Any]) -> bool:
    """Return whether emulator metadata names a plausible VM/boot runner.

    This is intentionally conservative: a passing shell command plus an arbitrary
    executable such as /bin/echo must not be promoted to platform boot evidence.
    Remote/URI metadata is useful as provenance, but it is not a locally
    verifiable boot runner for a claim-grade command executed by this collector.
    """

    if not value:
        return False
    if status.get("kind") == "uri":
        return False
    candidates = [value, str(status.get("resolved") or "")]
    markers = (
        "qemu-system-",
        "qemu-kvm",
        "bochs",
        "redoxer",
        "bootimage",
        "virtualboxvm",
        "vmrun",
        "firecracker",
        "cloud-hypervisor",
    )
    for candidate in candidates:
        name = Path(candidate).name.lower()
        if any(marker in name for marker in markers):
            return True
    return False


def boot_runner_version_probe(
    out_dir: Path,
    platform_name: str,
    emulator_status: Dict[str, Any],
    timeout: int,
) -> Tuple[Optional[Dict[str, Any]], Optional[Path], bool]:
    """Probe a local boot runner so a fake qemu-named wrapper is not enough."""

    if emulator_status.get("kind") == "uri":
        return None, None, False
    executable = str(emulator_status.get("resolved") or emulator_status.get("value") or "")
    if not executable:
        return None, None, False
    record = run_platform_command(
        out_dir,
        f"{platform_name}-emulator-version",
        [executable, "--version"],
        min(max(timeout, 1), 30),
    )
    log = write_platform_command_log(out_dir, f"{platform_name}-emulator-version", record)
    text = command_output_text(record).lower()
    markers = (
        "qemu",
        "bochs",
        "redoxer",
        "bootimage",
        "virtualbox",
        "vmware",
        "firecracker",
        "cloud-hypervisor",
    )
    passed = bool(record.get("passed") and any(marker in text for marker in markers))
    return record, log, passed


def optional_boot_config_status(value: str) -> Dict[str, Any]:
    """Validate boot-config metadata without assuming every config is a file."""

    if not value:
        return {"value": value, "provided": False, "kind": "empty", "usable": False}
    if is_uri(value):
        if value.lower().startswith("file://"):
            return local_path_status(value)
        return {"value": value, "provided": True, "kind": "uri", "usable": True}
    path_like = any(sep in value for sep in ("/", "\\")) or Path(value).suffix in {
        ".cfg",
        ".conf",
        ".json",
        ".toml",
        ".yaml",
        ".yml",
        ".sh",
        ".txt",
    }
    if not path_like:
        return {"value": value, "provided": True, "kind": "label", "usable": True}
    return local_path_status(value)


def constrained_platform_arg(args: argparse.Namespace, platform_name: str, suffix: str) -> Optional[str]:
    return getattr(args, f"{platform_name.replace('-', '_')}_{suffix}", None)


def matched_log_markers(text: str, required_log_markers: Iterable[str]) -> Tuple[List[str], List[str]]:
    """Return matched/missing required log markers using case-insensitive substring matching."""

    marker_list = [str(marker).strip() for marker in required_log_markers if str(marker).strip()]
    lowered_text = text.lower()
    matched = [marker for marker in marker_list if marker.lower() in lowered_text]
    missing = [marker for marker in marker_list if marker.lower() not in lowered_text]
    return matched, missing


def extract_cycle_count_samples_from_text(text: str) -> List[int]:
    """Extract cycle samples from kernel log text using explicit markers only."""

    patterns = (
        r"\bcycle(?:s|_count)?\s*[:=]\s*(\d+)\b",
        r"\bduration_cycles\s*[:=]\s*(\d+)\b",
        r"\bmedian_cycles\s*[:=]\s*(\d+)\b",
    )
    samples: List[int] = []
    for pattern in patterns:
        samples.extend(int(match.group(1)) for match in re.finditer(pattern, text, flags=re.IGNORECASE))
    return samples


RUST_FOR_LINUX_CYCLE_SAMPLE_MARKER = "UNIALLOC_RFL_CYCLE_SAMPLE"


def parse_rust_for_linux_cycle_sample_marker(line: str) -> Optional[Dict[str, Any]]:
    """Parse one structured Rust-for-Linux benchmark marker, if present.

    The kernel module still emits the legacy ``cycle: N`` line for backward
    compatibility.  This marker carries enough context to audit imported boot
    logs without guessing which benchmark produced a cycle count.
    """

    if RUST_FOR_LINUX_CYCLE_SAMPLE_MARKER not in line:
        return None
    pairs = {
        match.group(1): match.group(2)
        for match in re.finditer(r"\b([A-Za-z_][A-Za-z0-9_]*)=([^\s]+)", line)
    }
    cycle_count = optional_int(
        pairs.get("median_cycles")
        or pairs.get("cycle_count")
        or pairs.get("cycles")
        or pairs.get("duration_cycles")
    )
    if cycle_count is None:
        return None
    record: Dict[str, Any] = {
        "cycle_count": cycle_count,
        "source_marker": RUST_FOR_LINUX_CYCLE_SAMPLE_MARKER,
    }
    benchmark = str(pairs.get("benchmark") or "").strip()
    if benchmark:
        record["benchmark"] = benchmark
    byte_count = optional_int(pairs.get("bytes"))
    if byte_count is not None:
        record["bytes"] = byte_count
    return record


def extract_cycle_count_sample_records_from_text(text: str) -> List[Dict[str, Any]]:
    """Extract structured Rust-for-Linux cycle records from kernel log text."""

    records: List[Dict[str, Any]] = []
    for line in text.splitlines():
        record = parse_rust_for_linux_cycle_sample_marker(line)
        if record:
            records.append(record)
    return records


def extract_cycle_count_sample_records(value: Any) -> List[Dict[str, Any]]:
    """Extract structured cycle records from JSON artifacts or kernel log text."""

    records: List[Dict[str, Any]] = []
    if isinstance(value, dict):
        raw_records = (
            value.get("cycle_sample_records")
            or value.get("cycle_count_records")
            or value.get("samples")
        )
        if isinstance(raw_records, list):
            for item in raw_records:
                if not isinstance(item, dict):
                    continue
                cycle_count = optional_int(
                    item.get("cycle_count")
                    or item.get("median_cycles")
                    or item.get("cycles")
                    or item.get("duration_cycles")
                )
                if cycle_count is None:
                    continue
                record: Dict[str, Any] = {"cycle_count": cycle_count}
                source_marker = str(item.get("source_marker") or item.get("marker") or "").strip()
                if source_marker:
                    record["source_marker"] = source_marker
                if str(item.get("benchmark") or "").strip():
                    record["benchmark"] = str(item.get("benchmark")).strip()
                byte_count = optional_int(item.get("bytes"))
                if byte_count is not None:
                    record["bytes"] = byte_count
                records.append(record)
        if not records:
            for key in ("kernel_log", "dmesg", "log", "stdout", "stderr"):
                if isinstance(value.get(key), str):
                    records.extend(extract_cycle_count_sample_records_from_text(value[key]))
    elif isinstance(value, list):
        for item in value:
            records.extend(extract_cycle_count_sample_records(item))
    elif isinstance(value, str):
        records.extend(extract_cycle_count_sample_records_from_text(value))
    return records


def extract_cycle_count_samples(value: Any) -> List[int]:
    """Extract integer cycle-count samples from common JSON/kernel-log shapes.

    Plain kernel logs contain timestamps, CPU ids, addresses, and unrelated
    numeric counters.  For raw text, only explicit cycle markers are accepted;
    JSON values under cycle-count keys may still be numeric lists/objects.
    """

    samples: List[int] = []

    def add_candidate(candidate: Any, *, explicit_context: bool = False) -> None:
        if isinstance(candidate, bool):
            return
        if isinstance(candidate, int):
            samples.append(int(candidate))
            return
        if isinstance(candidate, float) and candidate >= 0 and candidate.is_integer():
            samples.append(int(candidate))
            return
        if isinstance(candidate, str):
            structured_records = extract_cycle_count_sample_records_from_text(candidate)
            if structured_records:
                samples.extend(int(record["cycle_count"]) for record in structured_records)
                return
            stripped = candidate.strip()
            if explicit_context and re.fullmatch(r"\d+", stripped):
                samples.append(int(stripped))
            else:
                samples.extend(extract_cycle_count_samples_from_text(candidate))
            return
        if isinstance(candidate, dict):
            for key in ("cycles", "cycle_count", "duration_cycles", "value", "median_cycles"):
                if key in candidate:
                    add_candidate(candidate[key], explicit_context=True)
                    return
        if isinstance(candidate, list):
            for item in candidate:
                add_candidate(item, explicit_context=explicit_context)

    if isinstance(value, dict):
        explicit_cycle_container = False
        for key in ("cycle_count_samples", "samples", "cycle_counts", "values", "measurements"):
            if key in value:
                add_candidate(value[key], explicit_context=True)
                explicit_cycle_container = True
                break
        if not samples and explicit_cycle_container:
            for record in extract_cycle_count_sample_records(value):
                cycle_count = optional_int(record.get("cycle_count"))
                if cycle_count is not None:
                    samples.append(cycle_count)
        if not samples:
            for key in ("kernel_log", "dmesg", "log", "stdout", "stderr"):
                raw_text = value.get(key)
                if isinstance(raw_text, str):
                    add_candidate(raw_text)
    elif isinstance(value, list):
        add_candidate(value, explicit_context=True)
    else:
        add_candidate(value)
    return samples


def rust_for_linux_cycle_count_blockers(
    raw_artifact: Any,
    samples: Sequence[int],
    records: Sequence[Dict[str, Any]],
    *,
    require_source_artifact_hash: bool = False,
) -> List[str]:
    """Return fail-closed diagnostics for Rust-for-Linux cycle-count evidence.

    A bare integer list can be fabricated or copied from a host benchmark.  For
    claim-grade Rust-for-Linux evidence we require the structured marker emitted
    by ``kernel/kernel-modules/benchmarking/rust_bench.rs`` so the sample is
    tied to the kernel module benchmark name and byte scale.
    """

    blockers: List[str] = []
    normalized_samples = [int(sample) for sample in samples if isinstance(sample, int) and sample > 0]
    if not normalized_samples:
        blockers.append("no positive Rust-for-Linux cycle-count samples were parsed")
    if not records:
        blockers.append(
            f"no structured {RUST_FOR_LINUX_CYCLE_SAMPLE_MARKER} records were parsed from Rust-for-Linux cycle-count evidence"
        )

    record_cycle_counts: List[int] = []
    usable_records = 0
    for index, record in enumerate(records, start=1):
        if not isinstance(record, dict):
            blockers.append(f"cycle sample record {index} is not an object")
            continue
        cycle_count = optional_int(record.get("cycle_count"))
        if cycle_count is None or cycle_count <= 0:
            blockers.append(f"cycle sample record {index} has no positive cycle_count")
        else:
            record_cycle_counts.append(cycle_count)
        if str(record.get("source_marker") or "").strip() != RUST_FOR_LINUX_CYCLE_SAMPLE_MARKER:
            blockers.append(
                f"cycle sample record {index} is not bound to {RUST_FOR_LINUX_CYCLE_SAMPLE_MARKER}"
            )
        if not str(record.get("benchmark") or "").strip():
            blockers.append(f"cycle sample record {index} has no benchmark name")
        if "bytes" not in record or optional_int(record.get("bytes")) is None:
            blockers.append(f"cycle sample record {index} has no byte-scale field")
        elif optional_int(record.get("bytes")) < 0:
            blockers.append(f"cycle sample record {index} has a negative byte-scale field")
        if not blockers or all(
            f"cycle sample record {index}" not in blocker for blocker in blockers
        ):
            usable_records += 1

    if normalized_samples and record_cycle_counts and normalized_samples != record_cycle_counts:
        blockers.append(
            "cycle_count_samples do not match the structured Rust-for-Linux cycle sample records"
        )

    if isinstance(raw_artifact, dict):
        declared_sample_count = optional_int(raw_artifact.get("sample_count"))
        if declared_sample_count is not None and declared_sample_count != len(record_cycle_counts):
            blockers.append(
                "cycle_counts sample_count does not match structured Rust-for-Linux cycle sample records"
            )
        declared_records = raw_artifact.get("cycle_sample_records") or raw_artifact.get("cycle_count_records")
        if isinstance(declared_records, list) and len(declared_records) != len(record_cycle_counts):
            blockers.append(
                "cycle_counts declared cycle_sample_records count does not match parsed cycle sample records"
            )
        if require_source_artifact_hash:
            source_hash = str(raw_artifact.get("source_artifact_sha256") or "").strip().lower()
            if not re.fullmatch(r"[0-9a-f]{64}", source_hash):
                blockers.append(
                    "cycle_counts artifact is missing a valid source_artifact_sha256 for the imported kernel run log"
                )

    if records and usable_records == 0:
        blockers.append("no usable structured Rust-for-Linux cycle sample record remains after validation")
    return unique_strings(blockers)


def read_cycle_count_samples(path: Path) -> Tuple[List[int], List[str], Any]:
    """Read a cycle-count artifact and return samples plus parse diagnostics."""

    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except Exception as exc:
        return [], [f"could not read cycle-count artifact: {exc}"], None
    try:
        data = json.loads(text)
    except json.JSONDecodeError:
        data = text
    samples = extract_cycle_count_samples(data)
    errors: List[str] = []
    if not samples:
        errors.append("cycle-count artifact contains no parseable integer samples")
    return samples, errors, data


RUST_FOR_LINUX_ALLOCATOR_STAT_KEYS = (
    "allocator_total_allocations",
    "allocator_total_deallocations",
    "allocator_typed_allocations",
    "allocator_typed_deallocations",
    "allocator_fallback_allocations",
    "allocator_fallback_deallocations",
    "allocator_total_allocated_bytes",
    "allocator_typed_allocated_bytes",
    "allocator_fallback_allocated_bytes",
    "allocator_coverage_basis_points",
    "allocator_type_stats_rows",
    "allocator_type_stats_dropped_events",
    "allocator_type_stats_probe_matched",
)

RUST_FOR_LINUX_ALLOCATOR_STATS_MARKER = "UniAlloc semantic bridge probe"


def optional_bool_int(value: Any) -> Optional[int]:
    """Return 1/0 for bool-like values, or None when the value is absent/unknown."""

    if isinstance(value, bool):
        return 1 if value else 0
    if isinstance(value, (int, float)) and value in (0, 1):
        return int(value)
    if isinstance(value, str):
        lowered = value.strip().lower()
        if lowered in {"true", "yes"}:
            return 1
        if lowered in {"false", "no"}:
            return 0
        parsed = optional_int(lowered)
        if parsed in (0, 1):
            return parsed
    return None


def normalize_allocator_stats_sample(value: Any) -> Optional[Dict[str, Any]]:
    """Normalize a Rust-for-Linux UniAlloc stats sample object, if present."""

    if not isinstance(value, dict):
        return None
    sample: Dict[str, Any] = {}
    for key in RUST_FOR_LINUX_ALLOCATOR_STAT_KEYS:
        if key == "allocator_type_stats_probe_matched":
            parsed = optional_bool_int(value.get(key))
        else:
            parsed = optional_int(value.get(key))
        if parsed is not None:
            sample[key] = parsed
    source_marker = str(value.get("source_marker") or value.get("marker") or "").strip()
    if source_marker:
        sample["source_marker"] = source_marker
    semantic_dealloc_ok = optional_bool_int(
        value.get("semantic_bridge_dealloc_ok", value.get("dealloc_ok"))
    )
    if semantic_dealloc_ok is not None:
        sample["semantic_bridge_dealloc_ok"] = semantic_dealloc_ok
    return sample or None


def extract_allocator_stats_samples_from_text(text: str) -> List[Dict[str, Any]]:
    """Extract UniAlloc allocator stats from explicit Rust-for-Linux log markers."""

    samples: List[Dict[str, Any]] = []
    for line in text.splitlines():
        if CONSTRAINED_BOOT_SAMPLE_MARKER in line:
            continue
        if "UniAlloc semantic stats" not in line and "allocator_total_allocations" not in line:
            continue
        raw_pairs: Dict[str, Any] = {
            match.group(1): int(match.group(2))
            for match in re.finditer(r"\b(allocator_[A-Za-z0-9_]+)\s*=\s*(\d+)\b", line)
        }
        raw_pairs.update(
            {
                match.group(1): match.group(2).lower()
                for match in re.finditer(
                    r"\b(allocator_[A-Za-z0-9_]+)\s*=\s*(true|false)\b",
                    line,
                    flags=re.IGNORECASE,
                )
            }
        )
        if RUST_FOR_LINUX_ALLOCATOR_STATS_MARKER in line:
            raw_pairs["source_marker"] = RUST_FOR_LINUX_ALLOCATOR_STATS_MARKER
        dealloc_ok = re.search(r"\bdealloc_ok\s*=\s*(true|false|0|1)\b", line, flags=re.IGNORECASE)
        if dealloc_ok:
            raw_pairs["semantic_bridge_dealloc_ok"] = dealloc_ok.group(1).lower()
        sample = normalize_allocator_stats_sample(raw_pairs)
        if sample:
            samples.append(sample)
    return samples


def extract_allocator_stats_samples(value: Any) -> List[Dict[str, Any]]:
    """Extract allocator stats from JSON artifacts or kernel log text."""

    samples: List[Dict[str, Any]] = []
    if isinstance(value, dict):
        for key in ("allocator_stats_samples", "allocator_stats", "unialloc_allocator_stats"):
            if key not in value:
                continue
            raw = value[key]
            if isinstance(raw, list):
                for item in raw:
                    sample = normalize_allocator_stats_sample(item)
                    if sample:
                        samples.append(sample)
            else:
                sample = normalize_allocator_stats_sample(raw)
                if sample:
                    samples.append(sample)
            break
        if not samples:
            sample = normalize_allocator_stats_sample(value)
            if sample:
                samples.append(sample)
        if not samples:
            for key in ("kernel_log", "dmesg", "log", "stdout", "stderr"):
                raw_text = value.get(key)
                if isinstance(raw_text, str):
                    samples.extend(extract_allocator_stats_samples_from_text(raw_text))
    elif isinstance(value, list):
        for item in value:
            samples.extend(extract_allocator_stats_samples(item))
    elif isinstance(value, str):
        samples.extend(extract_allocator_stats_samples_from_text(value))
    return samples


def rust_for_linux_allocator_stats_blockers(samples: Sequence[Dict[str, Any]]) -> List[str]:
    """Return fail-closed diagnostics for Rust-for-Linux allocator stats evidence."""

    if not samples:
        return ["no UniAlloc allocator stats snapshot was parsed from Rust-for-Linux runtime output"]
    blockers: List[str] = []
    typed_probe_samples = 0
    type_row_samples = 0
    matched_type_row_samples = 0
    bridge_marker_samples = 0
    semantic_dealloc_ok_samples = 0
    for index, sample in enumerate(samples, start=1):
        if not isinstance(sample, dict):
            blockers.append(f"allocator stats sample {index} is not an object")
            continue
        total_allocations = sample.get("allocator_total_allocations", 0)
        total_deallocations = sample.get("allocator_total_deallocations", 0)
        total_bytes = sample.get("allocator_total_allocated_bytes", 0)
        typed_allocations = sample.get("allocator_typed_allocations", 0)
        typed_deallocations = sample.get("allocator_typed_deallocations", 0)
        type_stats_rows = sample.get("allocator_type_stats_rows", 0)
        type_stats_dropped_events = sample.get("allocator_type_stats_dropped_events")
        if str(sample.get("source_marker") or "").strip() == RUST_FOR_LINUX_ALLOCATOR_STATS_MARKER:
            bridge_marker_samples += 1
        else:
            blockers.append(
                f"allocator stats sample {index} is not bound to {RUST_FOR_LINUX_ALLOCATOR_STATS_MARKER}"
            )
        if optional_bool_int(sample.get("semantic_bridge_dealloc_ok")) == 1:
            semantic_dealloc_ok_samples += 1
        if total_allocations <= 0:
            blockers.append(f"allocator stats sample {index} has no positive total allocation counter")
        if total_deallocations <= 0:
            blockers.append(f"allocator stats sample {index} has no positive total deallocation counter")
        if total_deallocations > total_allocations:
            blockers.append(
                f"allocator stats sample {index} has deallocations greater than allocations"
            )
        if typed_deallocations > typed_allocations:
            blockers.append(
                f"allocator stats sample {index} has typed deallocations greater than typed allocations"
            )
        if total_bytes <= 0:
            blockers.append(f"allocator stats sample {index} has no positive allocated-byte counter")
        if typed_allocations > 0 and typed_deallocations > 0:
            typed_probe_samples += 1
        if type_stats_rows > 0:
            type_row_samples += 1
        if type_stats_dropped_events is None:
            blockers.append(
                f"allocator stats sample {index} does not report semantic type-stats dropped events"
            )
        elif type_stats_dropped_events != 0:
            blockers.append(
                f"allocator stats sample {index} dropped {type_stats_dropped_events} semantic type-stats events"
            )
        if sample.get("allocator_type_stats_probe_matched") == 1:
            matched_type_row_samples += 1
    if typed_probe_samples == 0:
        blockers.append(
            "no allocator stats sample demonstrates positive typed semantic allocation and deallocation counters"
        )
    if type_row_samples == 0:
        blockers.append("no allocator stats sample reports positive semantic type-stats rows")
    if matched_type_row_samples == 0:
        blockers.append("no allocator stats sample proves the semantic type-stats probe row matched")
    if bridge_marker_samples == 0:
        blockers.append(
            f"no allocator stats sample is bound to the {RUST_FOR_LINUX_ALLOCATOR_STATS_MARKER} kernel marker"
        )
    if semantic_dealloc_ok_samples == 0:
        blockers.append("no allocator stats sample reports semantic_bridge_dealloc_ok=true")
    return unique_strings(blockers)


CONSTRAINED_BOOT_SAMPLE_MARKER = "UNIALLOC_CONSTRAINED_BOOT_SAMPLE"

CONSTRAINED_BOOT_SAMPLE_INT_KEYS = (
    "boot_cycle",
    "boot_cycle_count",
    "allocator_total_allocations",
    "allocator_total_deallocations",
    "allocator_typed_allocations",
    "allocator_typed_deallocations",
    "allocator_fallback_allocations",
    "allocator_fallback_deallocations",
    "allocator_total_allocated_bytes",
    "allocator_typed_allocated_bytes",
    "allocator_fallback_allocated_bytes",
    "allocator_coverage_basis_points",
    "allocator_type_stats_rows",
    "allocator_type_stats_dropped_events",
    "c_abi_round_trips",
    "c_abi_invalid_layouts_rejected",
    "c_abi_over_page_alignment",
)

CONSTRAINED_BOOT_SAMPLE_BOOL_KEYS = (
    "fixed_heap_ready",
    "c_abi_invoked",
    "c_abi_ready_after_init",
    "c_abi_over_page_alignment_checked",
    "allocator_type_stats_probe_matched",
    "c_abi_probe_passed",
)


def normalize_constrained_boot_sample(
    value: Any,
    *,
    platform_name: Optional[str] = None,
    require_marker: bool = False,
    allow_partial: bool = True,
) -> Optional[Dict[str, Any]]:
    """Normalize one constrained target-boot UniAlloc sample.

    A boot success string alone only proves that some image reached a prompt.
    C007 constrained-platform evidence must also show that UniAlloc's fixed-heap
    allocator path ran inside the target boot or kernel/module runtime.  This
    normalizer accepts either a structured marker line emitted by the target or
    an already parsed JSON object with the same fields.
    """

    if not isinstance(value, dict):
        return None
    marker = str(value.get("source_marker") or "").strip()
    if require_marker and marker != CONSTRAINED_BOOT_SAMPLE_MARKER:
        return None
    sample_specific_keys = (
        set(CONSTRAINED_BOOT_SAMPLE_INT_KEYS)
        | set(CONSTRAINED_BOOT_SAMPLE_BOOL_KEYS)
        | {"platform"}
    )
    if not allow_partial and marker != CONSTRAINED_BOOT_SAMPLE_MARKER:
        non_boot_cycle_keys = sample_specific_keys - {"platform", "boot_cycle", "boot_cycle_count"}
        if not any(key in value for key in non_boot_cycle_keys):
            return None

    record: Dict[str, Any] = {}
    raw_platform = str(value.get("platform") or platform_name or "").strip().lower()
    if raw_platform:
        record["platform"] = raw_platform
    if marker:
        record["source_marker"] = marker

    for key in CONSTRAINED_BOOT_SAMPLE_INT_KEYS:
        parsed = optional_int(value.get(key))
        if parsed is not None:
            record[key] = parsed
    for key in CONSTRAINED_BOOT_SAMPLE_BOOL_KEYS:
        parsed_bool = optional_bool_int(value.get(key))
        if parsed_bool is not None:
            record[key] = parsed_bool
    return record or None


def parse_constrained_boot_sample_marker(
    line: str,
    *,
    platform_name: Optional[str] = None,
) -> Optional[Dict[str, Any]]:
    """Parse one structured constrained-platform target boot marker.

    Expected target log shape, for example:
    ``UNIALLOC_CONSTRAINED_BOOT_SAMPLE platform=blogos boot_cycle=1
    fixed_heap_ready=true c_abi_invoked=true c_abi_ready_after_init=true
    c_abi_round_trips=2 c_abi_invalid_layouts_rejected=3
    c_abi_over_page_alignment_checked=true allocator_total_allocations=4
    allocator_total_deallocations=4 allocator_total_allocated_bytes=4096``.
    """

    if CONSTRAINED_BOOT_SAMPLE_MARKER not in line:
        return None
    pairs: Dict[str, Any] = {
        match.group(1): match.group(2)
        for match in re.finditer(r"\b([A-Za-z_][A-Za-z0-9_]*)=([^\s]+)", line)
    }
    pairs["source_marker"] = CONSTRAINED_BOOT_SAMPLE_MARKER
    return normalize_constrained_boot_sample(
        pairs,
        platform_name=platform_name,
        require_marker=True,
    )


def extract_constrained_boot_sample_records_from_text(
    text: str,
    *,
    platform_name: Optional[str] = None,
) -> List[Dict[str, Any]]:
    """Extract UniAlloc constrained boot sample records from target log text."""

    records: List[Dict[str, Any]] = []
    for line in text.splitlines():
        record = parse_constrained_boot_sample_marker(line, platform_name=platform_name)
        if record:
            records.append(record)
    return records


def extract_constrained_boot_sample_records(
    value: Any,
    *,
    platform_name: Optional[str] = None,
) -> List[Dict[str, Any]]:
    """Extract constrained boot samples from JSON artifacts or raw boot logs."""

    records: List[Dict[str, Any]] = []
    if isinstance(value, dict):
        for key in (
            "boot_sample_records",
            "constrained_boot_sample_records",
            "unialloc_boot_sample_records",
            "samples",
        ):
            raw = value.get(key)
            if isinstance(raw, list):
                for item in raw:
                    sample = normalize_constrained_boot_sample(item, platform_name=platform_name)
                    if sample:
                        records.append(sample)
                return records
        sample = normalize_constrained_boot_sample(
            value,
            platform_name=platform_name,
            allow_partial=False,
        )
        if sample:
            records.append(sample)
            return records
        for key in ("boot_log", "kernel_log", "log", "stdout", "stderr", "dmesg"):
            raw_text = value.get(key)
            if isinstance(raw_text, str):
                records.extend(
                    extract_constrained_boot_sample_records_from_text(
                        raw_text,
                        platform_name=platform_name,
                    )
                )
    elif isinstance(value, list):
        for item in value:
            records.extend(extract_constrained_boot_sample_records(item, platform_name=platform_name))
    elif isinstance(value, str):
        records.extend(
            extract_constrained_boot_sample_records_from_text(value, platform_name=platform_name)
        )
    return records


def constrained_boot_sample_blockers(
    records: Sequence[Dict[str, Any]],
    *,
    platform_name: str,
) -> List[str]:
    """Return fail-closed diagnostics for constrained-platform UniAlloc samples."""

    normalized_platform = platform_name.strip().lower()
    if not records:
        return [
            (
                f"no {platform_name} UniAlloc constrained boot sample marker was parsed "
                f"(expected {CONSTRAINED_BOOT_SAMPLE_MARKER} with fixed_heap/C ABI allocator stats)"
            )
        ]

    blockers: List[str] = []
    usable_records = 0
    for index, record in enumerate(records, start=1):
        if not isinstance(record, dict):
            blockers.append(f"boot sample {index} is not an object")
            continue
        sample_blockers: List[str] = []
        platform_value = str(record.get("platform") or "").strip().lower()
        if platform_value != normalized_platform:
            sample_blockers.append(
                f"boot sample {index} platform mismatch: expected {normalized_platform}, got {platform_value or '<missing>'}"
            )
        if record.get("source_marker") != CONSTRAINED_BOOT_SAMPLE_MARKER:
            sample_blockers.append(
                f"boot sample {index} was not bound to {CONSTRAINED_BOOT_SAMPLE_MARKER}"
            )

        boot_cycle = optional_int(record.get("boot_cycle")) or optional_int(record.get("boot_cycle_count"))
        if boot_cycle is None or boot_cycle <= 0:
            sample_blockers.append(f"boot sample {index} has no positive boot_cycle")
        total_allocations = optional_int(record.get("allocator_total_allocations")) or 0
        total_deallocations = optional_int(record.get("allocator_total_deallocations")) or 0
        total_bytes = optional_int(record.get("allocator_total_allocated_bytes")) or 0
        typed_allocations = optional_int(record.get("allocator_typed_allocations")) or 0
        typed_deallocations = optional_int(record.get("allocator_typed_deallocations")) or 0
        typed_bytes = optional_int(record.get("allocator_typed_allocated_bytes")) or 0
        type_stats_rows = optional_int(record.get("allocator_type_stats_rows")) or 0
        type_stats_dropped_events = optional_int(
            record.get("allocator_type_stats_dropped_events")
        )
        if total_allocations <= 0:
            sample_blockers.append(f"boot sample {index} has no positive allocation counter")
        if total_deallocations <= 0:
            sample_blockers.append(f"boot sample {index} has no positive deallocation counter")
        if total_deallocations > total_allocations:
            sample_blockers.append(
                f"boot sample {index} has deallocations greater than allocations"
            )
        if total_bytes <= 0:
            sample_blockers.append(f"boot sample {index} has no positive allocated-byte counter")
        if typed_allocations <= 0:
            sample_blockers.append(
                f"boot sample {index} has no positive typed semantic allocation counter"
            )
        if typed_deallocations <= 0:
            sample_blockers.append(
                f"boot sample {index} has no positive typed semantic deallocation counter"
            )
        if typed_deallocations > typed_allocations:
            sample_blockers.append(
                f"boot sample {index} has typed deallocations greater than typed allocations"
            )
        if typed_bytes <= 0:
            sample_blockers.append(
                f"boot sample {index} has no positive typed allocated-byte counter"
            )
        if type_stats_rows <= 0:
            sample_blockers.append(
                f"boot sample {index} has no positive semantic type-stats rows"
            )
        if type_stats_dropped_events is None:
            sample_blockers.append(
                f"boot sample {index} does not report semantic type-stats dropped events"
            )
        elif type_stats_dropped_events != 0:
            sample_blockers.append(
                f"boot sample {index} dropped {type_stats_dropped_events} semantic type-stats events"
            )
        if optional_bool_int(record.get("allocator_type_stats_probe_matched")) != 1:
            sample_blockers.append(
                f"boot sample {index} did not prove the semantic type-stats probe row matched"
            )

        if optional_bool_int(record.get("fixed_heap_ready")) != 1:
            sample_blockers.append(f"boot sample {index} did not report fixed_heap_ready=true")
        if optional_bool_int(record.get("c_abi_invoked")) != 1:
            sample_blockers.append(f"boot sample {index} did not report c_abi_invoked=true")
        if optional_bool_int(record.get("c_abi_ready_after_init")) != 1:
            sample_blockers.append(f"boot sample {index} did not report c_abi_ready_after_init=true")
        if (optional_int(record.get("c_abi_round_trips")) or 0) < 2:
            sample_blockers.append(f"boot sample {index} has fewer than two C ABI round trips")
        if (optional_int(record.get("c_abi_invalid_layouts_rejected")) or 0) < 3:
            sample_blockers.append(
                f"boot sample {index} did not reject the required invalid C ABI layouts"
            )
        if optional_bool_int(record.get("c_abi_over_page_alignment_checked")) != 1:
            sample_blockers.append(
                f"boot sample {index} did not check over-page C ABI alignment"
            )
        if optional_bool_int(record.get("c_abi_probe_passed")) != 1:
            sample_blockers.append(
                f"boot sample {index} did not report c_abi_probe_passed=true"
            )
        if not sample_blockers:
            usable_records += 1
        blockers.extend(sample_blockers)

    if usable_records == 0:
        blockers.append(
            f"no {platform_name} boot sample proves target-boot UniAlloc fixed-heap allocation/deallocation"
        )
    return unique_strings(blockers)


CONSTRAINED_BOOT_HOST_SMOKE_PROVENANCE_MARKERS = (
    # Emitted by unialloc/examples/small_heap.rs.  Seeing this in a BlogOS/Redox
    # boot transcript means the artifact is host fixed-heap smoke evidence, not
    # target-image boot evidence.
    "host-fixed-heap",
    "host fixed-heap small_heap",
    "fixed_heap host small_heap",
    # Labels used by the platform collector for the local host smoke command.
    "fixed-heap-small-heap",
    # Command/provenance strings from the host example should never appear in a
    # target boot transcript accepted for C007.
    "--example small_heap",
    "--example\", \"small_heap",
    "unialloc/examples/small_heap",
)

CONSTRAINED_BOOT_PROVENANCE_MARKER = "UNIALLOC_CONSTRAINED_BOOT_PROVENANCE"


def constrained_boot_marker_token(value: str) -> str:
    """Return a whitespace-free token suitable for constrained boot markers."""

    out = "".join(
        ch if ch.isascii() and (ch.isalnum() or ch in "-_.:") else "_"
        for ch in str(value or "").strip()
    )
    return out or "unknown"


def constrained_boot_transcript_provenance_blockers(
    text: str,
    *,
    platform_name: str,
) -> List[str]:
    """Reject known host-smoke provenance in target boot transcripts.

    The platform collector intentionally runs ``small_heap`` as local smoke
    evidence before any BlogOS/Redox boot validation.  That output is useful for
    debugging fixed-heap/C-ABI wiring, but it must never be importable as target
    boot evidence.  This check catches both the structured host marker emitted by
    ``small_heap`` and the collector labels/commands that identify the host-only
    smoke path, even if a transcript also contains a valid-looking target marker.
    """

    if not text:
        return []
    lowered = text.lower()
    matched = [
        marker
        for marker in CONSTRAINED_BOOT_HOST_SMOKE_PROVENANCE_MARKERS
        if marker in lowered
    ]
    if not matched:
        return []
    return [
        (
            f"{platform_name} boot transcript contains host fixed-heap small_heap "
            f"smoke provenance markers ({', '.join(unique_strings(matched))}); "
            "host smoke output cannot satisfy constrained target boot evidence"
        )
    ]


def parse_constrained_boot_provenance_marker(line: str) -> Optional[Dict[str, Any]]:
    """Parse a target boot provenance marker, if present.

    ``UNIALLOC_CONSTRAINED_BOOT_SAMPLE`` proves that UniAlloc ran in the target
    runtime. This companion marker binds an imported transcript to the boot
    artifact set that produced it, so a pasted success line cannot stand alone
    as claim-grade platform evidence.
    """

    if CONSTRAINED_BOOT_PROVENANCE_MARKER not in line:
        return None
    pairs = {
        match.group(1): match.group(2)
        for match in re.finditer(r"\b([A-Za-z_][A-Za-z0-9_]*)=([^\s]+)", line)
    }
    if not pairs:
        return None
    pairs["source_marker"] = CONSTRAINED_BOOT_PROVENANCE_MARKER
    return pairs


def extract_constrained_boot_provenance_records_from_text(text: str) -> List[Dict[str, Any]]:
    records: List[Dict[str, Any]] = []
    for line in text.splitlines():
        record = parse_constrained_boot_provenance_marker(line)
        if record:
            records.append(record)
    return records


def constrained_boot_provenance_record_blockers(
    records: Sequence[Dict[str, Any]],
    *,
    platform_name: str,
) -> List[str]:
    """Return fail-closed diagnostics for imported constrained boot provenance."""

    normalized_platform = platform_name.strip().lower()
    if not records:
        return [
            (
                f"no {platform_name} constrained boot provenance marker was parsed "
                f"(expected {CONSTRAINED_BOOT_PROVENANCE_MARKER} with image/config hashes and emulator version)"
            )
        ]
    blockers: List[str] = []
    usable_records = 0
    for index, record in enumerate(records, start=1):
        if not isinstance(record, dict):
            blockers.append(f"boot provenance record {index} is not an object")
            continue
        record_blockers: List[str] = []
        platform_value = str(record.get("platform") or "").strip().lower()
        if platform_value != normalized_platform:
            record_blockers.append(
                f"boot provenance record {index} platform mismatch: expected {normalized_platform}, got {platform_value or '<missing>'}"
            )
        if str(record.get("source_marker") or "").strip() != CONSTRAINED_BOOT_PROVENANCE_MARKER:
            record_blockers.append(
                f"boot provenance record {index} was not bound to {CONSTRAINED_BOOT_PROVENANCE_MARKER}"
            )
        image_sha256 = str(record.get("image_sha256") or "").strip().lower()
        if not re.fullmatch(r"[0-9a-f]{64}", image_sha256):
            record_blockers.append(
                f"boot provenance record {index} is missing a valid image_sha256"
            )
        boot_config_sha256 = str(record.get("boot_config_sha256") or "").strip().lower()
        if not re.fullmatch(r"[0-9a-f]{64}", boot_config_sha256):
            record_blockers.append(
                f"boot provenance record {index} is missing a valid boot_config_sha256"
            )
        if not str(record.get("emulator") or record.get("runner") or "").strip():
            record_blockers.append(f"boot provenance record {index} is missing emulator/runner")
        if not str(record.get("emulator_version") or record.get("runner_version") or "").strip():
            record_blockers.append(
                f"boot provenance record {index} is missing emulator/runner version"
            )
        if not record_blockers:
            usable_records += 1
        blockers.extend(record_blockers)
    if usable_records == 0:
        blockers.append("no usable constrained boot provenance record remains after validation")
    return unique_strings(blockers)


def local_metadata_file_hash(status: Dict[str, Any]) -> Optional[str]:
    """Return sha256 for locally verifiable path/file-URI metadata."""

    if status.get("kind") not in {"path", "file_uri"}:
        return None
    if not status.get("usable"):
        return None
    resolved = str(status.get("resolved") or "").strip()
    if not resolved:
        return None
    path = Path(resolved)
    if not path.exists() or not path.is_file():
        return None
    return file_sha256(path)


def constrained_boot_provenance_artifact_hash_blockers(
    records: Sequence[Dict[str, Any]],
    *,
    platform_name: str,
    image_status: Dict[str, Any],
    boot_config_status: Dict[str, Any],
) -> List[str]:
    """Cross-check provenance hashes against locally provided boot artifacts."""

    image_sha256 = local_metadata_file_hash(image_status)
    boot_config_sha256 = local_metadata_file_hash(boot_config_status)
    if not image_sha256 and not boot_config_sha256:
        return []

    blockers: List[str] = []
    for index, record in enumerate(records, start=1):
        if not isinstance(record, dict):
            continue
        if image_sha256 and str(record.get("image_sha256") or "").strip().lower() != image_sha256:
            blockers.append(
                f"boot provenance record {index} image_sha256 does not match configured {platform_name} image artifact"
            )
        if (
            boot_config_sha256
            and str(record.get("boot_config_sha256") or "").strip().lower() != boot_config_sha256
        ):
            blockers.append(
                f"boot provenance record {index} boot_config_sha256 does not match configured {platform_name} boot_config artifact"
            )
    return unique_strings(blockers)


def constrained_boot_local_artifact_hash_blockers(
    *,
    platform_name: str,
    image_status: Dict[str, Any],
    boot_config_status: Dict[str, Any],
) -> List[str]:
    """Require locally hashable boot artifacts for claim-grade imports.

    A structured boot sample proves that UniAlloc ran in some target runtime, and
    the provenance marker carries SHA-256 values for the boot artifact set.  For
    Redox/BlogOS C007 evidence we also need to verify those hashes against the
    actual image/config files available to the evaluator; otherwise an arbitrary
    URI/label plus copied marker text could be promoted to claim-grade evidence.
    """

    blockers: List[str] = []
    if not local_metadata_file_hash(image_status):
        blockers.append(
            f"{platform_name} target image must be a readable local file or file:// URI so provenance hashes can be verified"
        )
    if not local_metadata_file_hash(boot_config_status):
        blockers.append(
            f"{platform_name} boot_config must be a readable local file or file:// URI so provenance hashes can be verified"
        )
    return blockers


def validate_constrained_boot_transcript_evidence(
    text: str,
    *,
    platform_name: str,
    image_status: Optional[Dict[str, Any]] = None,
    boot_config_status: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Validate the UniAlloc-specific evidence inside a constrained boot transcript.

    This is shared by external transcript import and local boot-command capture.
    A target boot success line is not enough for C007: the transcript must carry
    both the allocator sample marker and the provenance marker that binds the
    transcript to the image/config/emulator artifact set.  When local image and
    boot-config paths are available, their hashes are checked against the
    provenance marker.
    """

    boot_sample_records = extract_constrained_boot_sample_records_from_text(
        text,
        platform_name=platform_name,
    )
    boot_sample_blockers = constrained_boot_sample_blockers(
        boot_sample_records,
        platform_name=platform_name,
    )
    boot_provenance_blockers = constrained_boot_transcript_provenance_blockers(
        text,
        platform_name=platform_name,
    )
    boot_provenance_records = extract_constrained_boot_provenance_records_from_text(text)
    boot_provenance_record_blockers = constrained_boot_provenance_record_blockers(
        boot_provenance_records,
        platform_name=platform_name,
    )
    boot_provenance_artifact_hash_blockers: List[str] = []
    if image_status is not None or boot_config_status is not None:
        boot_provenance_artifact_hash_blockers = (
            constrained_boot_provenance_artifact_hash_blockers(
                boot_provenance_records,
                platform_name=platform_name,
                image_status=image_status or {},
                boot_config_status=boot_config_status or {},
            )
        )
        boot_provenance_record_blockers = unique_strings(
            [
                *boot_provenance_record_blockers,
                *boot_provenance_artifact_hash_blockers,
            ]
        )
    return {
        "boot_sample_records": boot_sample_records,
        "boot_sample_record_count": len(boot_sample_records),
        "boot_sample_blockers": boot_sample_blockers,
        "boot_provenance_blockers": boot_provenance_blockers,
        "boot_provenance_records": boot_provenance_records,
        "boot_provenance_record_count": len(boot_provenance_records),
        "boot_provenance_record_blockers": boot_provenance_record_blockers,
        "boot_provenance_artifact_hash_blockers": boot_provenance_artifact_hash_blockers,
        "blockers": unique_strings(
            [
                *boot_sample_blockers,
                *boot_provenance_blockers,
                *boot_provenance_record_blockers,
            ]
        ),
    }


def redoxer_runtime_passed_json_records(text: str) -> List[Dict[str, Any]]:
    """Extract JSON status records emitted by the Redox target runtime.

    The Redox ``small_heap`` example prints a structured JSON object after the
    human-readable ``UNIALLOC_CONSTRAINED_BOOT_SAMPLE`` line.  Keeping this as a
    separate helper lets a lightweight redoxer runtime audit prove the actual
    target program returned ``passed=true`` without relaxing the stricter
    claim-grade boot provenance gate used by ``validate-constrained-boot-log``.
    """

    records: List[Dict[str, Any]] = []
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped.startswith("{") or not stripped.endswith("}"):
            continue
        try:
            parsed = json.loads(stripped)
        except json.JSONDecodeError:
            continue
        if isinstance(parsed, dict):
            records.append(parsed)
    return records


def audit_redoxer_target_runtime(args: argparse.Namespace) -> int:
    """Audit a real ``redoxer exec`` UniAlloc target-runtime transcript.

    This command intentionally stays below C007 claim-grade.  It validates that
    an actual Redox/redoxer run executed the UniAlloc target binary and emitted
    fixed-heap/C-ABI allocator counters, while documenting the remaining
    provenance gap: a preserved, locally hashable Redox image and boot config
    are still required before the result can be imported as platform-claim
    evidence.
    """

    platform_name = str(getattr(args, "platform", "redox") or "redox").strip().lower()
    run_id = args.run_id or _dt.datetime.now().strftime(
        f"{platform_name}-redoxer-target-runtime-%Y%m%d-%H%M%S"
    )
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)

    log_path = Path(args.log).expanduser()
    if not log_path.is_absolute():
        log_path = (ROOT / log_path).resolve()
    binary_path = Path(args.binary).expanduser()
    if not binary_path.is_absolute():
        binary_path = (ROOT / binary_path).resolve()

    blockers: List[str] = []
    text = ""
    log_sha256: Optional[str] = None
    if not log_path.exists() or not log_path.is_file():
        blockers.append(f"redoxer runtime log does not exist or is not a file: {log_path}")
    else:
        log_sha256 = file_sha256(log_path)
        text = log_path.read_text(encoding="utf-8", errors="replace")

    binary_sha256: Optional[str] = None
    binary_size: Optional[int] = None
    if not binary_path.exists() or not binary_path.is_file():
        blockers.append(f"Redox target binary does not exist or is not a file: {binary_path}")
    else:
        binary_sha256 = file_sha256(binary_path)
        binary_size = binary_path.stat().st_size

    redoxer_success = "## redoxer (success) ##" in text
    redoxer_failure = "## redoxer (failure" in text
    if not redoxer_success:
        blockers.append("redoxer transcript does not contain the success marker")
    if redoxer_failure:
        blockers.append("redoxer transcript contains a failure marker")

    sample_records = extract_constrained_boot_sample_records_from_text(
        text,
        platform_name=platform_name,
    )
    sample_blockers = constrained_boot_sample_blockers(
        sample_records,
        platform_name=platform_name,
    )
    blockers.extend(sample_blockers)

    runtime_json_records = redoxer_runtime_passed_json_records(text)
    passed_json_records = [
        record for record in runtime_json_records if optional_bool_int(record.get("passed")) == 1
    ]
    if not passed_json_records and not getattr(args, "allow_missing_passed_json", False):
        blockers.append("redoxer runtime transcript did not contain a JSON record with passed=true")

    success_pattern = str(getattr(args, "success_pattern", "") or "").strip()
    pattern_matched = False
    pattern_error: Optional[str] = None
    if success_pattern:
        pattern_matched, pattern_error = success_pattern_matches(text, success_pattern)
        if pattern_error:
            blockers.append(pattern_error.replace("boot success", "redoxer runtime success"))
        elif not pattern_matched:
            blockers.append("redoxer runtime success pattern was not observed")

    target_runtime_verified = not unique_strings(blockers)
    claim_grade_blockers = [
        (
            "redoxer target-runtime audit does not preserve a locally hashable Redox "
            "image plus boot_config provenance; validate-constrained-boot-log is still "
            "required before importing C007 platform evidence"
        )
    ]
    audit = {
        "schema_version": 1,
        "source": "redoxer-target-runtime-audit",
        "generated_at": now_iso(),
        "platform": platform_name,
        "target_runtime_verified": target_runtime_verified,
        "passed": target_runtime_verified,
        "claim_grade": False,
        "complete_for_claim": False,
        "claim_grade_blockers": claim_grade_blockers,
        "blockers": unique_strings(blockers),
        "log": str(log_path),
        "log_sha256": log_sha256,
        "binary": str(binary_path),
        "binary_sha256": binary_sha256,
        "binary_size": binary_size,
        "runner": str(getattr(args, "runner", "") or "redoxer"),
        "runner_image": str(getattr(args, "runner_image", "") or ""),
        "redoxer_success_marker_observed": redoxer_success,
        "redoxer_failure_marker_observed": redoxer_failure,
        "success_pattern": success_pattern or None,
        "success_pattern_matched": bool(success_pattern and pattern_matched),
        "success_pattern_error": pattern_error,
        "boot_sample_records": sample_records,
        "boot_sample_record_count": len(sample_records),
        "boot_sample_blockers": sample_blockers,
        "runtime_json_records": runtime_json_records,
        "passed_json_record_count": len(passed_json_records),
        "notes": (
            "This is real Redox target-runtime evidence from redoxer/QEMU.  It is "
            "not claim-grade C007 boot evidence until paired with a preserved "
            "Redox image, boot config, emulator metadata, and a matching "
            f"{CONSTRAINED_BOOT_PROVENANCE_MARKER} marker."
        ),
    }
    audit_path = out_dir / f"{platform_name}-redoxer-target-runtime-audit.json"
    write_json(audit_path, audit)
    print(
        json.dumps(
            {
                "audit": str(audit_path),
                "target_runtime_verified": target_runtime_verified,
                "claim_grade": False,
                "blockers": audit["blockers"],
                "claim_grade_blockers": claim_grade_blockers,
            },
            indent=2,
            sort_keys=True,
        )
    )
    return 0 if target_runtime_verified else 1


PLATFORM_TEXT_EVIDENCE_SUFFIXES = {
    ".json",
    ".log",
    ".txt",
    ".out",
    ".err",
    ".stdout",
    ".stderr",
}
PLATFORM_TEXT_EVIDENCE_KINDS = {
    "build_log",
    "run_summary",
    "boot_cycles",
    "cycle_counts",
    "kernel_build_log",
}
PLATFORM_EVIDENCE_TEXT_AUDIT_LIMIT = 1024 * 1024


def read_platform_text_evidence_for_audit(
    resolved_path: Path,
    *,
    kind: Optional[str],
) -> str:
    """Read a bounded text prefix for evidence-content provenance checks."""

    suffix = resolved_path.suffix.lower()
    if suffix not in PLATFORM_TEXT_EVIDENCE_SUFFIXES and kind not in PLATFORM_TEXT_EVIDENCE_KINDS:
        return ""
    try:
        with resolved_path.open("rb") as handle:
            raw = handle.read(PLATFORM_EVIDENCE_TEXT_AUDIT_LIMIT + 1)
    except OSError:
        return ""
    return raw[:PLATFORM_EVIDENCE_TEXT_AUDIT_LIMIT].decode("utf-8", errors="replace")


RUST_FOR_LINUX_KERNEL_BUILD_CONTEXT_MARKERS = (
    "make[",
    "kbuild",
    "modpost",
    "module.symvers",
    "modules.order",
    "rust-for-linux",
    "linux kernel",
)
RUST_FOR_LINUX_MODULE_BUILD_MARKERS = (
    "rust_bench.ko",
    "rust_bench.o",
    "ld [m]",
    "rustc [m]",
    "cc [m]",
    "btf [m]",
)
RUST_FOR_LINUX_KERNEL_BUILD_SMOKE_REJECT_MARKERS = (
    "source-presence audit only",
    "source presence does not prove kernel integration",
    "kernel_build_executed: false",
    "cargo check only",
    "host cargo check only",
    "smoke-only source presence",
)


def matched_text_markers(text: str, markers: Iterable[str]) -> List[str]:
    lowered = text.lower()
    return unique_strings(marker for marker in markers if marker and marker in lowered)


def rust_for_linux_kernel_build_provenance_audit(text: str) -> Dict[str, Any]:
    """Fail-closed provenance check for imported Rust-for-Linux kernel builds."""

    context_markers = matched_text_markers(
        text,
        RUST_FOR_LINUX_KERNEL_BUILD_CONTEXT_MARKERS,
    )
    module_markers = matched_text_markers(
        text,
        RUST_FOR_LINUX_MODULE_BUILD_MARKERS,
    )
    smoke_markers = matched_text_markers(
        text,
        RUST_FOR_LINUX_KERNEL_BUILD_SMOKE_REJECT_MARKERS,
    )
    blockers: List[str] = []
    if smoke_markers:
        blockers.append(
            "Rust-for-Linux kernel build log contains source/cargo smoke provenance "
            f"markers ({', '.join(smoke_markers)}); smoke output cannot satisfy kernel build evidence"
        )
    if not context_markers:
        blockers.append(
            "Rust-for-Linux kernel build log lacks Linux kernel/Kbuild provenance markers "
            f"such as {', '.join(RUST_FOR_LINUX_KERNEL_BUILD_CONTEXT_MARKERS[:4])}"
        )
    if not module_markers:
        blockers.append(
            "Rust-for-Linux kernel build log lacks rust_bench kernel module compile/link markers "
            f"such as {', '.join(RUST_FOR_LINUX_MODULE_BUILD_MARKERS[:4])}"
        )
    return {
        "matched_kernel_context_markers": context_markers,
        "matched_module_build_markers": module_markers,
        "matched_smoke_reject_markers": smoke_markers,
        "blockers": unique_strings(blockers),
    }


def collect_imported_rust_for_linux_kernel_build_log(
    *,
    out_dir: Path,
    artifact_path: Path,
    success_pattern: Optional[str],
    required_log_markers: Iterable[str] = ("rust_bench",),
) -> Tuple[Dict[str, Any], Path, bool, List[str]]:
    """Import and validate an externally captured Rust-for-Linux build log.

    Many development hosts cannot run a Rust-for-Linux kernel build locally.
    Accepting an external build artifact is useful, but only if it remains a
    real, auditable build log: the caller must provide an explicit success
    marker, the source file must be hashed, and platform-specific markers such
    as the benchmark module name must appear in the log.  This keeps arbitrary
    text files or unrelated successful commands from satisfying C007.
    """

    path = artifact_path.expanduser()
    if not path.is_absolute():
        path = (ROOT / path).resolve()
    blockers: List[str] = []
    source_sha256: Optional[str] = None
    text = ""
    if not path.exists() or not path.is_file():
        blockers.append(f"external Rust-for-Linux kernel build log does not exist or is not a file: {path}")
    else:
        source_sha256 = file_sha256(path)
        text = path.read_text(encoding="utf-8", errors="replace")
    if not success_pattern:
        blockers.append("external Rust-for-Linux kernel build import requires an explicit success pattern")
        pattern_matched = False
        pattern_error = None
    else:
        pattern_matched, pattern_error = success_pattern_matches(text, success_pattern)
        if pattern_error:
            blockers.append(pattern_error.replace("boot success", "kernel build success"))
        elif not pattern_matched:
            blockers.append("external Rust-for-Linux kernel build success pattern was not observed")
    marker_list = [str(marker) for marker in required_log_markers if str(marker).strip()]
    matched_markers, _missing_markers = matched_log_markers(text, marker_list)
    if marker_list and not matched_markers:
        blockers.append(
            "external Rust-for-Linux kernel build log does not mention required module markers: "
            + ", ".join(marker_list)
        )
    kernel_build_provenance = rust_for_linux_kernel_build_provenance_audit(text)
    blockers.extend(kernel_build_provenance["blockers"])
    record = {
        "schema_version": 1,
        "label": "rust-for-linux-kernel-build-import",
        "command": ["external-rust-for-linux-kernel-build-import", str(path)],
        "started_at": None,
        "ended_at": None,
        "wall_seconds": None,
        "exit_code": 0 if not blockers else 1,
        "error": "; ".join(unique_strings(blockers)) if blockers else None,
        "stdout": str(path) if path.is_file() else None,
        "stderr": None,
        "env_overrides": {},
        "passed": not blockers,
        "external_kernel_build_import": True,
        "source_artifact": str(path),
        "source_artifact_sha256": source_sha256,
        "success_pattern": success_pattern,
        "success_pattern_matched": bool(success_pattern and pattern_matched),
        "required_log_markers": marker_list,
        "matched_log_markers": matched_markers,
        "kernel_build_provenance": kernel_build_provenance,
        "kernel_build_provenance_blockers": kernel_build_provenance["blockers"],
    }
    log = write_platform_command_log(out_dir, "rust-for-linux-kernel-build-import", record)
    return record, log, not blockers, unique_strings(blockers)


def collect_imported_constrained_boot_log(
    *,
    out_dir: Path,
    platform_name: str,
    display_name: str,
    artifact_path: Path,
    success_pattern: Optional[str],
    required_log_markers: Iterable[str],
    image_status: Optional[Dict[str, Any]] = None,
    boot_config_status: Optional[Dict[str, Any]] = None,
) -> Tuple[Dict[str, Any], Path, bool, List[str]]:
    """Import and validate an externally captured BlogOS/Redox boot transcript.

    Local hosts often lack the exact VM image/emulator stack used for constrained
    targets.  External boot transcripts are acceptable iteration evidence only
    when they are bound to a real file hash, an explicit success marker,
    platform/UniAlloc markers in the transcript, and a structured
    ``UNIALLOC_CONSTRAINED_BOOT_SAMPLE`` line proving the fixed-heap C ABI and
    allocator counters ran inside the target boot.  This prevents an unrelated
    successful command log from becoming C007 boot-cycle evidence.
    """

    path = artifact_path.expanduser()
    if not path.is_absolute():
        path = (ROOT / path).resolve()
    blockers: List[str] = []
    source_sha256: Optional[str] = None
    imported_source_artifact: Optional[Path] = None
    imported_source_artifact_sha256: Optional[str] = None
    text = ""
    if not path.exists() or not path.is_file():
        blockers.append(f"external {platform_name} boot log does not exist or is not a file: {path}")
    else:
        source_sha256 = file_sha256(path)
        text = path.read_text(encoding="utf-8", errors="replace")
        imported_source_artifact, imported_source_artifact_sha256, preserve_error = (
            preserve_imported_source_artifact(
                out_dir,
                path,
                f"{platform_name}-boot-log-source",
            )
        )
        if preserve_error:
            blockers.append(
                f"could not preserve imported {platform_name} boot log source artifact: {preserve_error}"
            )
    if not success_pattern:
        blockers.append(f"external {platform_name} boot log import requires an explicit success pattern")
        pattern_matched = False
        pattern_error = None
    else:
        pattern_matched, pattern_error = success_pattern_matches(text, success_pattern)
        if pattern_error:
            blockers.append(pattern_error)
        elif not pattern_matched:
            blockers.append(f"external {platform_name} boot success pattern was not observed")
    marker_list = [str(marker) for marker in required_log_markers if str(marker).strip()]
    matched_markers, missing_markers = matched_log_markers(text, marker_list)
    if missing_markers:
        blockers.append(
            f"external {platform_name} boot log is missing required markers: "
            + ", ".join(missing_markers)
        )
    transcript_validation = validate_constrained_boot_transcript_evidence(
        text,
        platform_name=platform_name,
        image_status=image_status,
        boot_config_status=boot_config_status,
    )
    boot_sample_records = transcript_validation["boot_sample_records"]
    boot_sample_blockers = transcript_validation["boot_sample_blockers"]
    boot_provenance_blockers = transcript_validation["boot_provenance_blockers"]
    boot_provenance_records = transcript_validation["boot_provenance_records"]
    boot_provenance_record_blockers = transcript_validation["boot_provenance_record_blockers"]
    boot_provenance_artifact_hash_blockers = transcript_validation[
        "boot_provenance_artifact_hash_blockers"
    ]
    blockers.extend(transcript_validation["blockers"])
    record = {
        "schema_version": 1,
        "label": f"{platform_name}-boot-log-import",
        "command": [f"external-{platform_name}-boot-log-import", str(path)],
        "started_at": None,
        "ended_at": None,
        "wall_seconds": None,
        "exit_code": 0 if not blockers else 1,
        "error": "; ".join(unique_strings(blockers)) if blockers else None,
        "stdout": str(imported_source_artifact or path) if path.is_file() else None,
        "stderr": None,
        "env_overrides": {},
        "passed": not blockers,
        "external_boot_log_import": True,
        "platform": platform_name,
        "display_name": display_name,
        "source_artifact": str(path),
        "source_artifact_sha256": source_sha256,
        "imported_source_artifact": str(imported_source_artifact) if imported_source_artifact else None,
        "imported_source_artifact_sha256": imported_source_artifact_sha256,
        "success_pattern": success_pattern,
        "success_pattern_matched": bool(success_pattern and pattern_matched),
        "required_log_markers": marker_list,
        "matched_log_markers": matched_markers,
        "missing_required_log_markers": missing_markers,
        "boot_sample_required_marker": CONSTRAINED_BOOT_SAMPLE_MARKER,
        "boot_sample_records": boot_sample_records,
        "boot_sample_record_count": len(boot_sample_records),
        "boot_sample_blockers": boot_sample_blockers,
        "boot_provenance_blockers": boot_provenance_blockers,
        "boot_provenance_required_marker": CONSTRAINED_BOOT_PROVENANCE_MARKER,
        "boot_provenance_records": boot_provenance_records,
        "boot_provenance_record_count": len(boot_provenance_records),
        "boot_provenance_record_blockers": boot_provenance_record_blockers,
        "boot_provenance_artifact_hash_blockers": boot_provenance_artifact_hash_blockers,
    }
    log = write_platform_command_log(out_dir, f"{platform_name}-boot-log-import", record)
    return record, log, not blockers, unique_strings(blockers)


def validate_constrained_boot_log(args: argparse.Namespace) -> int:
    """Preflight one BlogOS/Redox boot transcript without rebuilding the matrix."""

    platform_name = str(args.platform).strip().lower()
    display_name = "BlogOS" if platform_name == "blogos" else "Redox"
    run_id = args.run_id or _dt.datetime.now().strftime(
        f"{platform_name}-boot-log-validation-%Y%m%d-%H%M%S"
    )
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)

    image_arg = str(args.image or "")
    emulator_arg = str(args.emulator or "")
    boot_config_arg = str(args.boot_config or "")
    image_status = local_path_status(image_arg)
    emulator_status = executable_status(emulator_arg)
    boot_config_status = optional_boot_config_status(boot_config_arg)
    original_image_arg = image_arg
    original_boot_config_arg = boot_config_arg
    original_image_status = image_status
    original_boot_config_status = boot_config_status
    preserved_metadata = preserve_constrained_boot_metadata_artifacts(
        out_dir,
        platform_name=platform_name,
        image_status=image_status,
        boot_config_status=boot_config_status,
    )
    if preserved_metadata.get("image"):
        image_arg = str(preserved_metadata["image"])
        image_status = preserved_metadata["image_status"]
    if preserved_metadata.get("boot_config"):
        boot_config_arg = str(preserved_metadata["boot_config"])
        boot_config_status = preserved_metadata["boot_config_status"]
    metadata_blockers: List[str] = []
    if not original_image_arg:
        metadata_blockers.append(f"{platform_name} target image metadata is missing")
    elif not image_status.get("usable"):
        metadata_blockers.append(
            f"{platform_name} target image metadata does not resolve to a readable local path or URI"
        )
    if not emulator_arg:
        metadata_blockers.append(f"{platform_name} emulator metadata is missing")
    elif not emulator_status.get("usable"):
        metadata_blockers.append(
            f"{platform_name} emulator metadata does not resolve to an executable or URI"
        )
    elif not recognized_boot_emulator(emulator_arg, emulator_status):
        metadata_blockers.append(
            f"{platform_name} emulator metadata is not a recognized VM or boot runner"
        )
    if image_status.get("resolved"):
        try:
            image_size = Path(str(image_status["resolved"])).stat().st_size
        except OSError:
            image_size = None
        if image_size is not None and image_size < 64 * 1024:
            metadata_blockers.append(
                f"{platform_name} image artifact is implausibly small for a bootable target image: {image_size} bytes"
            )
    if not original_boot_config_arg:
        metadata_blockers.append(f"{platform_name} boot configuration metadata is missing")
    elif not boot_config_status.get("usable"):
        metadata_blockers.append(
            f"{platform_name} boot configuration metadata is path-like but does not exist"
        )
    metadata_blockers.extend(preserved_metadata.get("blockers") or [])
    metadata_blockers.extend(
        constrained_boot_local_artifact_hash_blockers(
            platform_name=platform_name,
            image_status=image_status,
            boot_config_status=boot_config_status,
        )
    )
    if not args.boot_success_pattern:
        metadata_blockers.append(f"{platform_name} boot success pattern metadata is missing")

    required_markers = args.boot_log_required_marker or [platform_name, "unialloc"]
    import_record, import_log, import_passed, import_blockers = collect_imported_constrained_boot_log(
        out_dir=out_dir,
        platform_name=platform_name,
        display_name=display_name,
        artifact_path=Path(args.boot_log),
        success_pattern=args.boot_success_pattern,
        required_log_markers=required_markers,
        image_status=image_status,
        boot_config_status=boot_config_status,
    )
    artifact_hash_blockers = [
        str(item)
        for item in import_record.get("boot_provenance_artifact_hash_blockers", [])
        if item
    ]
    blockers = unique_strings(
        [
            *metadata_blockers,
            *import_blockers,
        ]
    )
    validation = {
        "schema_version": 1,
        "source": "constrained-boot-log-validation",
        "generated_at": now_iso(),
        "platform": platform_name,
        "passed": not blockers,
        "ready_for_platform_import": not blockers,
        "claim_grade_ready": not blockers,
        "blockers": blockers,
        "boot_log": str(Path(args.boot_log).expanduser()),
        "boot_log_import_log": str(import_log),
        "boot_log_import_passed": import_passed,
        "boot_log_import_record": import_record,
        "required_log_markers": required_markers,
        "image": image_arg,
        "image_original": original_image_arg,
        "image_status": image_status,
        "image_original_status": original_image_status,
        "image_preserved_source": preserved_metadata.get("image"),
        "image_preserved_source_sha256": preserved_metadata.get("image_sha256"),
        "image_preserve_error": preserved_metadata.get("image_error"),
        "emulator": emulator_arg,
        "emulator_status": emulator_status,
        "boot_config": boot_config_arg,
        "boot_config_original": original_boot_config_arg,
        "boot_config_status": boot_config_status,
        "boot_config_original_status": original_boot_config_status,
        "boot_config_preserved_source": preserved_metadata.get("boot_config"),
        "boot_config_preserved_source_sha256": preserved_metadata.get("boot_config_sha256"),
        "boot_config_preserve_error": preserved_metadata.get("boot_config_error"),
        "boot_success_pattern": args.boot_success_pattern,
        "boot_provenance_artifact_hash_blockers": artifact_hash_blockers,
        "notes": (
            "Preflight only: this command does not import C007.  Feed the same "
            "boot log and metadata to collect-platform-smoke/import-platform-matrix "
            "only when ready_for_platform_import is true."
        ),
    }
    boot_records = import_record.get("boot_sample_records", []) if isinstance(import_record, dict) else []
    provenance_records = import_record.get("boot_provenance_records", []) if isinstance(import_record, dict) else []
    boot_cycles_ready = not blockers
    boot_cycles = {
        "schema_version": 1,
        "source": "constrained-boot-log-validation-boot-cycles",
        "generated_at": now_iso(),
        "platform": platform_name,
        "passed": boot_cycles_ready,
        "claim_grade": boot_cycles_ready,
        "complete_for_claim": boot_cycles_ready,
        "boot_cycle_count": len(boot_records),
        "boot_sample_records": boot_records,
        "boot_provenance_records": provenance_records,
        "boot_log_import_record": import_record,
        "claim_grade_blockers": [] if boot_cycles_ready else blockers,
        "methodology": "external constrained target boot transcript import with UniAlloc boot sample and provenance markers",
        "image": image_arg,
        "image_original": original_image_arg,
        "image_status": image_status,
        "image_original_status": original_image_status,
        "image_preserved_source": preserved_metadata.get("image"),
        "image_preserved_source_sha256": preserved_metadata.get("image_sha256"),
        "emulator": emulator_arg,
        "emulator_status": emulator_status,
        "boot_config": boot_config_arg,
        "boot_config_original": original_boot_config_arg,
        "boot_config_status": boot_config_status,
        "boot_config_original_status": original_boot_config_status,
        "boot_config_preserved_source": preserved_metadata.get("boot_config"),
        "boot_config_preserved_source_sha256": preserved_metadata.get("boot_config_sha256"),
        "boot_success_pattern": args.boot_success_pattern,
    }
    boot_cycles_path = out_dir / f"{platform_name}-boot-cycles.json"
    write_json(boot_cycles_path, boot_cycles)
    validation["boot_cycles_artifact"] = str(boot_cycles_path)
    validation["boot_cycles_claim_grade_ready"] = boot_cycles_ready

    build_log_arg = str(getattr(args, "build_log", "") or "")
    build_log_status = local_path_status(build_log_arg)
    build_log_preserved: Optional[Path] = None
    build_log_sha256: Optional[str] = None
    build_log_error: Optional[str] = None
    if build_log_arg and build_log_status.get("usable") and build_log_status.get("resolved"):
        build_log_preserved, build_log_sha256, build_log_error = preserve_imported_source_artifact(
            out_dir,
            Path(str(build_log_status["resolved"])),
            f"{platform_name}-build-log-source",
        )
    validation["build_log"] = build_log_arg or None
    validation["build_log_status"] = build_log_status
    validation["build_log_preserved_source"] = str(build_log_preserved) if build_log_preserved else None
    validation["build_log_preserved_source_sha256"] = build_log_sha256
    validation["build_log_preserve_error"] = build_log_error

    matrix_requested = bool(getattr(args, "matrix_out", None) or getattr(args, "matrix_entry_out", None))
    matrix_entry: Optional[Dict[str, Any]] = None
    if matrix_requested:
        def matrix_abs_path(value: Any) -> str:
            return str(Path(str(value)).expanduser().resolve())

        entry_blockers = list(blockers)
        if not build_log_arg:
            entry_blockers.append(f"{platform_name} matrix entry requires --build-log evidence")
        elif not build_log_status.get("usable") or build_log_preserved is None:
            entry_blockers.append(f"{platform_name} build log does not resolve to a readable local file")
        if build_log_error:
            entry_blockers.append(f"{platform_name} build log could not be preserved: {build_log_error}")
        entry_ready = not unique_strings(entry_blockers)
        build_evidence: List[Dict[str, Any]] = []
        if build_log_preserved is not None:
            build_evidence.append(
                {
                    "kind": "build_log",
                    "path": matrix_abs_path(build_log_preserved),
                    "sha256": build_log_sha256,
                    "description": f"{display_name} target image/build log preserved from external evidence.",
                }
            )
        source_path = import_record.get("imported_source_artifact") if isinstance(import_record, dict) else None
        source_sha = import_record.get("imported_source_artifact_sha256") if isinstance(import_record, dict) else None
        boot_log_evidence = []
        if source_path:
            boot_log_evidence.append(
                {
                    "kind": "run_summary",
                    "path": matrix_abs_path(source_path),
                    "sha256": source_sha,
                    "description": f"{display_name} preserved target boot transcript source.",
                }
            )
        matrix_entry = {
            "target": f"{display_name} constrained heap target image boot-cycle validation",
            "passed": entry_ready,
            "claim_grade": entry_ready,
            "complete_for_claim": entry_ready,
            "claim_grade_scope": f"C007 {platform_name} external constrained target boot-cycle validation",
            "claim_grade_blockers": [] if entry_ready else unique_strings(entry_blockers),
            "image": image_arg,
            "emulator": emulator_arg,
            "boot_config": boot_config_arg,
            "image_original": original_image_arg,
            "boot_config_original": original_boot_config_arg,
            "target_triple": str(getattr(args, "target_triple", "") or ("x86_64-unknown-redox" if platform_name == "redox" else "")),
            "rust_target": str(getattr(args, "target_triple", "") or ("x86_64-unknown-redox" if platform_name == "redox" else "")),
            "platform_target": PLATFORM_TEMPLATE_TARGETS.get(platform_name, f"{display_name} constrained heap target image"),
            "methodology": "external constrained boot transcript import; target log must include UniAlloc boot sample and provenance markers",
            "boot_evidence_source": "external-import",
            "boot_log_import_requested": True,
            "boot_log_import_source": str(Path(args.boot_log).expanduser()),
            "boot_log_import_record": import_record,
            "boot_log_import_preserved_source": matrix_abs_path(source_path) if source_path else None,
            "boot_log_import_preserved_source_sha256": source_sha,
            "boot_log_required_markers": required_markers,
            "target_metadata": {
                "image_status": image_status,
                "image_original": original_image_arg,
                "image_original_status": original_image_status,
                "image_preserved_source": matrix_abs_path(preserved_metadata["image"])
                if preserved_metadata.get("image")
                else None,
                "image_preserved_source_sha256": preserved_metadata.get("image_sha256"),
                "image_preserve_error": preserved_metadata.get("image_error"),
                "emulator_status": emulator_status,
                "boot_config_status": boot_config_status,
                "boot_config_original": original_boot_config_arg,
                "boot_config_original_status": original_boot_config_status,
                "boot_config_preserved_source": matrix_abs_path(preserved_metadata["boot_config"])
                if preserved_metadata.get("boot_config")
                else None,
                "boot_config_preserved_source_sha256": preserved_metadata.get("boot_config_sha256"),
                "boot_config_preserve_error": preserved_metadata.get("boot_config_error"),
                "boot_success_pattern": args.boot_success_pattern,
                "boot_log_import_record": import_record,
                "boot_cycles_artifact": matrix_abs_path(boot_cycles_path),
                "build_log_status": build_log_status,
                "build_log_preserved_source": matrix_abs_path(build_log_preserved) if build_log_preserved else None,
            },
            "evidence": [
                *build_evidence,
                {
                    "kind": "boot_cycles",
                    "path": matrix_abs_path(boot_cycles_path),
                    "sha256": file_sha256(boot_cycles_path),
                    "description": f"{display_name} boot-cycle validation artifact from imported target transcript.",
                },
                {
                    "kind": "run_summary",
                    "path": matrix_abs_path(import_log),
                    "sha256": file_sha256(import_log),
                    "description": f"{display_name} boot transcript import validation record.",
                },
                *boot_log_evidence,
            ],
        }
        validation["matrix_entry"] = matrix_entry
        if getattr(args, "matrix_entry_out", None):
            entry_path = Path(args.matrix_entry_out).expanduser()
            write_json(entry_path, matrix_entry)
            validation["matrix_entry_out"] = str(entry_path)
        if getattr(args, "matrix_out", None):
            matrix_path = Path(args.matrix_out).expanduser()
            matrix = {platform_name: matrix_entry}
            preserve_unselected_platform_matrix_entries(matrix, [platform_name])
            write_json(matrix_path, matrix)
            matrix_audit = build_platform_matrix_audit(load_config(), matrix_path, matrix)
            matrix_audit_path = out_dir / f"{platform_name}-platform-matrix-audit.json"
            write_json(matrix_audit_path, matrix_audit)
            validation["matrix_out"] = str(matrix_path)
            validation["matrix_audit"] = str(matrix_audit_path)
            validation["matrix_audit_summary"] = matrix_audit.get("summary", {})
    validation_path = out_dir / f"{platform_name}-boot-log-validation.json"
    write_json(validation_path, validation)
    print(
        json.dumps(
            {
                "validation": str(validation_path),
                "ready_for_platform_import": validation["ready_for_platform_import"],
                "blockers": blockers,
                "boot_log_import_log": str(import_log),
                "boot_cycles_artifact": str(boot_cycles_path),
                "matrix_out": validation.get("matrix_out"),
                "matrix_audit": validation.get("matrix_audit"),
            },
            indent=2,
            sort_keys=True,
        )
    )
    return 0 if validation["ready_for_platform_import"] else 1


def probe_boot_runner_version_text(
    emulator_status: Dict[str, Any],
    *,
    timeout: int,
) -> Tuple[str, Optional[str]]:
    """Return a best-effort one-line runner version string without writing raw logs."""

    if emulator_status.get("kind") == "uri":
        return "", "emulator/runner version must be supplied explicitly for URI metadata"
    executable = str(emulator_status.get("resolved") or emulator_status.get("value") or "")
    if not executable:
        return "", "emulator/runner executable was not resolved"
    try:
        proc = subprocess.run(
            [executable, "--version"],
            cwd=str(ROOT),
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=min(max(timeout, 1), 30),
        )
    except Exception as exc:
        return "", f"emulator/runner version probe failed: {exc}"
    text = "\n".join(part for part in (proc.stdout, proc.stderr) if part)
    first_line = next((line.strip() for line in text.splitlines() if line.strip()), "")
    if proc.returncode != 0 and not first_line:
        return "", f"emulator/runner version probe exited {proc.returncode} without output"
    if not first_line:
        return "", "emulator/runner version probe produced no output"
    return first_line, None


def emit_constrained_boot_provenance_marker(args: argparse.Namespace) -> int:
    """Generate the provenance marker required by constrained boot-log import."""

    platform_name = str(args.platform).strip().lower()
    run_id = args.run_id or _dt.datetime.now().strftime(
        f"{platform_name}-boot-provenance-marker-%Y%m%d-%H%M%S"
    )
    out_dir = Path(args.output_dir).expanduser() if args.output_dir else RAW / run_id
    out_dir.mkdir(parents=True, exist_ok=True)

    image_status = local_path_status(str(args.image or ""))
    boot_config_status = optional_boot_config_status(str(args.boot_config or ""))
    emulator_status = executable_status(str(args.emulator or ""))
    blockers: List[str] = []

    image_sha256 = local_metadata_file_hash(image_status)
    if not image_sha256:
        blockers.append(
            f"{platform_name} image must be a readable local path/file:// URI to emit provenance"
        )
    boot_config_sha256 = local_metadata_file_hash(boot_config_status)
    if not boot_config_sha256:
        blockers.append(
            f"{platform_name} boot_config must be a readable local path/file:// URI to emit provenance"
        )
    if not emulator_status.get("usable"):
        blockers.append(f"{platform_name} emulator/runner metadata is not usable")
    emulator_version = str(args.emulator_version or "").strip()
    version_probe_error: Optional[str] = None
    if not emulator_version and emulator_status.get("usable"):
        emulator_version, version_probe_error = probe_boot_runner_version_text(
            emulator_status,
            timeout=args.timeout,
        )
        if version_probe_error:
            blockers.append(version_probe_error)
    elif not emulator_version:
        blockers.append("emulator/runner version is missing")

    marker = None
    if not blockers and image_sha256 and boot_config_sha256 and emulator_version:
        marker = (
            f"{CONSTRAINED_BOOT_PROVENANCE_MARKER} "
            f"platform={constrained_boot_marker_token(platform_name)} "
            f"image_sha256={image_sha256} "
            f"boot_config_sha256={boot_config_sha256} "
            f"emulator={constrained_boot_marker_token(str(args.emulator or ''))} "
            f"emulator_version={constrained_boot_marker_token(emulator_version)}"
        )
        record_blockers = constrained_boot_provenance_record_blockers(
            [parse_constrained_boot_provenance_marker(marker) or {}],
            platform_name=platform_name,
        )
        artifact_blockers = constrained_boot_provenance_artifact_hash_blockers(
            [parse_constrained_boot_provenance_marker(marker) or {}],
            platform_name=platform_name,
            image_status=image_status,
            boot_config_status=boot_config_status,
        )
        blockers.extend(record_blockers)
        blockers.extend(artifact_blockers)
    result = {
        "schema_version": 1,
        "source": "constrained-boot-provenance-marker",
        "generated_at": now_iso(),
        "platform": platform_name,
        "ready": not blockers,
        "marker": marker if not blockers else None,
        "blockers": unique_strings(blockers),
        "image": str(args.image or ""),
        "image_status": image_status,
        "image_sha256": image_sha256,
        "boot_config": str(args.boot_config or ""),
        "boot_config_status": boot_config_status,
        "boot_config_sha256": boot_config_sha256,
        "emulator": str(args.emulator or ""),
        "emulator_status": emulator_status,
        "emulator_version": emulator_version,
        "emulator_version_probe_error": version_probe_error,
        "usage": (
            "Include marker in the preserved Redox/BlogOS boot transcript before "
            "running validate-constrained-boot-log or collect-platform-smoke --<platform>-boot-log."
        ),
    }
    output_path = out_dir / f"{platform_name}-boot-provenance-marker.json"
    write_json(output_path, result)
    print(
        json.dumps(
            {
                "output": str(output_path),
                "ready": result["ready"],
                "marker": result["marker"],
                "blockers": result["blockers"],
            },
            indent=2,
            sort_keys=True,
        )
    )
    return 0 if result["ready"] else 1


def infer_kernel_version(kernel_tree: Optional[Path], timeout: int) -> str:
    """Best-effort Linux kernel version discovery without making a claim on failure."""

    if not kernel_tree or not kernel_tree.exists():
        return ""
    make = shutil.which("make")
    if not make:
        return ""
    try:
        proc = subprocess.run(
            [make, "-s", "-C", str(kernel_tree), "kernelversion"],
            cwd=str(ROOT),
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=min(max(timeout, 1), 30),
        )
    except Exception:
        return ""
    if proc.returncode != 0:
        return ""
    return proc.stdout.strip().splitlines()[0] if proc.stdout.strip() else ""


