def feature_runtime_gate_for_claim(claim: Dict[str, Any]) -> Optional[Dict[str, str]]:
    dataset = str(claim.get("dataset") or "")
    gate = FEATURE_RUNTIME_CLAIM_GATES.get(dataset)
    return dict(gate) if isinstance(gate, dict) else None


def latest_std_bench_feature_probe_summary(feature: str) -> Tuple[Optional[Path], Dict[str, Any]]:
    """Return the newest std_bench runtime summary for a feature.

    This intentionally scans raw summaries instead of trusting performance
    dataset manifests: C004/C005/C006 need evidence that the allocator actually
    executed the claimed protected-metadata runtime path, not just matching table
    cells.
    """

    candidates: List[Tuple[float, str, Path, Dict[str, Any]]] = []
    for path in RAW.glob("*/std-bench-auto-summary.json"):
        try:
            data = read_json(path)
        except (OSError, json.JSONDecodeError):
            continue
        if not isinstance(data, dict):
            continue
        if not features_include(data.get("features"), feature):
            continue
        try:
            mtime = path.stat().st_mtime
        except OSError:
            mtime = 0.0
        candidates.append((mtime, str(path), path, data))
    if not candidates:
        return None, {}
    candidates.sort(key=lambda item: (item[0], item[1]), reverse=True)
    _mtime, _name, path, data = candidates[0]
    return path, data


def latest_pac_hardware_abi_probe_audit() -> Tuple[Optional[Path], Dict[str, Any]]:
    """Return newest real PAC ABI/environment probe audit, if available."""

    candidate_paths: List[Path] = [RESULTS / "pac_hardware_abi_probe_audit.json"]
    candidate_paths.extend(RAW.glob("*/pac-hardware-abi-probe-audit.json"))
    candidates: List[Tuple[float, str, Path, Dict[str, Any]]] = []
    seen: Set[str] = set()
    for path in candidate_paths:
        resolved = str(path)
        if resolved in seen:
            continue
        seen.add(resolved)
        try:
            data = read_json(path)
        except (OSError, json.JSONDecodeError):
            continue
        if not isinstance(data, dict):
            continue
        if data.get("source") != PAC_HARDWARE_ABI_PROBE_SOURCE:
            continue
        try:
            mtime = path.stat().st_mtime
        except OSError:
            mtime = 0.0
        candidates.append((mtime, str(path), path, data))
    if not candidates:
        return None, {}
    candidates.sort(key=lambda item: (item[0], item[1]), reverse=True)
    _mtime, _name, path, data = candidates[0]
    return path, data


def paper_performance_smoke_dataset_matches(audit: Dict[str, Any], dataset: str) -> bool:
    if audit.get("dataset") == dataset:
        return True
    rows = audit.get("performance_rows")
    if isinstance(rows, list):
        return any(isinstance(row, dict) and row.get("dataset") == dataset for row in rows)
    return False


def latest_mir_semantic_scope_paper_performance_smoke_audit(
    dataset: str,
) -> Tuple[Optional[Path], Dict[str, Any]]:
    """Return newest bounded MIR semantic-scope timing/validation smoke for a dataset."""

    candidate_paths: List[Path] = [
        RESULTS / "rustc_driver_mir_semantic_scope_std_bench_paper_performance_smoke_audit.json"
    ]
    candidate_paths.extend(
        RAW.glob("*/rustc-driver-mir-semantic-scope-std-bench-paper-performance-smoke-audit.json")
    )
    candidates: List[Tuple[float, str, Path, Dict[str, Any]]] = []
    seen: set = set()
    for path in candidate_paths:
        resolved = str(path)
        if resolved in seen:
            continue
        seen.add(resolved)
        try:
            data = read_json(path)
        except (OSError, json.JSONDecodeError):
            continue
        if not isinstance(data, dict):
            continue
        if data.get("source") != "rustc-driver-mir-semantic-scope-std-bench-paper-performance-smoke":
            continue
        if not paper_performance_smoke_dataset_matches(data, dataset):
            continue
        try:
            mtime = path.stat().st_mtime
        except OSError:
            mtime = 0.0
        candidates.append((mtime, str(path), path, data))
    if not candidates:
        return None, {}
    candidates.sort(key=lambda item: (item[0], item[1]), reverse=True)
    _mtime, _name, path, data = candidates[0]
    return path, data


def mir_semantic_scope_paper_performance_smoke_blockers(
    audit: Dict[str, Any],
    dataset: str,
) -> List[str]:
    """Fail closed for C003 table-only imports without a real compiler/timing smoke."""

    blockers: List[str] = []
    if not isinstance(audit, dict):
        return ["missing rustc_driver MIR semantic-scope paper-performance smoke audit"]
    summary = audit.get("summary") if isinstance(audit.get("summary"), dict) else {}
    rows = audit.get("performance_rows") if isinstance(audit.get("performance_rows"), list) else []
    if summary.get("paper_performance_smoke_validated") is not True:
        blockers.append("rustc_driver MIR semantic-scope paper-performance smoke is not validated")
    if summary.get("timing_returncode") != 0:
        blockers.append("paper-performance smoke timing run did not exit successfully")
    if summary.get("validation_returncode") != 0:
        blockers.append("paper-performance smoke validation run did not exit successfully")
    if optional_int(summary.get("timing_bench_result_count")) in (None, 0):
        blockers.append("paper-performance smoke contains no timing benchmark result")
    if optional_int(summary.get("typed_allocation_site_event_count")) in (None, 0):
        blockers.append("paper-performance smoke validation contains no typed allocation events")
    if optional_int(summary.get("lowered_module_typed_allocation_site_event_count")) in (None, 0):
        blockers.append("paper-performance smoke validation contains no lowered-module typed events")
    if summary.get("lowered_module_compiler_basis_present") is not True:
        blockers.append("paper-performance smoke validation lacks compiler-assigned lowered-module basis")
    if summary.get("actual_semantic_scope_rewrite") is not True:
        blockers.append("paper-performance smoke did not use actual MIR semantic-scope rewrite")
    if optional_int(summary.get("semantic_scope_rewrite_applied_count")) in (None, 0):
        blockers.append("paper-performance smoke reports no applied semantic-scope rewrites")
    dataset_rows = [row for row in rows if isinstance(row, dict) and row.get("dataset") == dataset]
    if not dataset_rows:
        blockers.append(f"paper-performance smoke has no performance row for dataset={dataset}")
    else:
        if not any(row.get("semantic_policy_ready") is True for row in dataset_rows):
            blockers.append("paper-performance smoke performance rows are not semantic_policy_ready")
        if not all(row.get("type_id_basis_status") == "compiler-assigned" for row in dataset_rows):
            blockers.append("paper-performance smoke performance rows are not compiler-assigned")
        gate = FEATURE_RUNTIME_CLAIM_GATES.get(dataset)
        required_feature = str(gate.get("feature") or "") if isinstance(gate, dict) else ""
        if required_feature:
            for label in ("timing_features", "validation_features"):
                if not all(features_include(row.get(label), required_feature) for row in dataset_rows):
                    blockers.append(
                        f"paper-performance smoke {label} do not include feature={required_feature}"
                    )
    return unique_strings(blockers)


def apply_feature_runtime_gate(
    result: Dict[str, Any],
    claim: Dict[str, Any],
    source: str,
) -> Dict[str, Any]:
    """Fail closed when a current feature claim lacks runtime proof."""

    if source != "current":
        return result
    gate = feature_runtime_gate_for_claim(claim)
    if gate is None:
        return result

    dataset = str(claim.get("dataset") or "")
    feature = str(gate["feature"])
    validation_key = str(gate["validation_key"])
    probe_key = str(gate["probe_key"])
    path, probe_summary = latest_std_bench_feature_probe_summary(feature)
    blockers: List[str] = []

    if path is None:
        blockers.append(
            f"claim-grade blocker: missing runtime feature probe for {dataset} "
            f"(feature={feature})"
        )
    else:
        path_text = str(path)
        if path_text not in result["evidence"]:
            result["evidence"].append(path_text)
        result["evidence"].append(
            "runtime feature probe: "
            f"dataset={dataset}, feature={feature}, run_id={probe_summary.get('run_id')}, "
            f"{validation_key}={probe_summary.get(validation_key)}, "
            f"{probe_key}_events={probe_summary.get(probe_key, {}).get('event_count') if isinstance(probe_summary.get(probe_key), dict) else 'n/a'}"
        )
        pac_abi_summary: Dict[str, Any] = {}
        if dataset == "pac_authentication":
            pac_abi_path, pac_abi_audit = latest_pac_hardware_abi_probe_audit()
            pac_abi_summary = (
                pac_abi_audit.get("summary", {})
                if isinstance(pac_abi_audit.get("summary"), dict)
                else {}
            )
            if pac_abi_path is not None:
                if str(pac_abi_path) not in result["evidence"]:
                    result["evidence"].append(str(pac_abi_path))
                result["evidence"].append(
                    "PAC hardware ABI probe: "
                    f"run_id={pac_abi_audit.get('run_id')}, "
                    f"arm64_raw_pac_noop={pac_abi_summary.get('arm64_raw_pac_noop')}, "
                    f"arm64e_sign_correct_auth={pac_abi_summary.get('arm64e_sign_correct_auth')}, "
                    "arm64e_wrong_context_rejected="
                    f"{pac_abi_summary.get('arm64e_wrong_context_rejected')}, "
                    "hardware_pac_context_binding_observed="
                    f"{pac_abi_summary.get('hardware_pac_context_binding_observed')}, "
                    "rust_arm64e_target_listed="
                    f"{pac_abi_summary.get('rust_arm64e_target_listed')}, "
                    "rust_arm64e_std_installed="
                    f"{pac_abi_summary.get('rust_arm64e_std_installed')}, "
                    "rust_arm64e_target_available="
                    f"{pac_abi_summary.get('rust_arm64e_target_available')}"
                )
        pac_direct_hardware_validated = False
        pac_direct_claim_grade_ready = False
        pac_arm64e_build_std_summary: Dict[str, Any] = {}
        if dataset == "pac_authentication":
            direct_path, direct_audit = latest_pac_metadata_direct_probe_audit()
            if direct_path is None:
                blockers.append(
                    "claim-grade blocker: missing direct PAC metadata allocator probe"
                )
            else:
                direct_summary = (
                    direct_audit.get("summary", {})
                    if isinstance(direct_audit.get("summary"), dict)
                    else {}
                )
                pac_direct_hardware_validated = direct_summary.get("hardware_pac_validated") is True
                direct_blockers = pac_metadata_direct_probe_blockers(direct_audit)
                if (
                    direct_summary.get("metadata_pac_negative_auth_requires_signal_probe") is True
                    and pac_abi_summary.get("arm64e_wrong_context_rejected_by_signal") is not True
                ):
                    direct_blockers.append(
                        "direct PAC metadata probe requires destructive arm64e "
                        "negative-auth signal evidence, but the latest PAC hardware ABI "
                        "probe did not validate wrong-context rejection by signal"
                    )
                pac_direct_claim_grade_ready = (
                    direct_summary.get("claim_grade") is True
                    and pac_direct_hardware_validated
                    and not direct_blockers
                )
                if str(direct_path) not in result["evidence"]:
                    result["evidence"].append(str(direct_path))
                result["evidence"].append(
                    "direct PAC metadata allocator probe: "
                    f"run_id={direct_audit.get('run_id')}, "
                    f"runtime={direct_summary.get('runtime')}, "
                    f"validated={direct_summary.get('probe_validated')}, "
                    f"claim_grade={direct_summary.get('claim_grade')}, "
                    f"allocator_validated={direct_summary.get('allocator_validated')}, "
                    "full_allocator_side_cache_validated="
                    f"{direct_summary.get('full_allocator_side_cache_validated')}, "
                    f"hardware_pac_validated={direct_summary.get('hardware_pac_validated')}, "
                    f"software_fallback_validated={direct_summary.get('software_fallback_validated')}, "
                    f"context_binding_active={direct_summary.get('context_binding_active')}, "
                    f"software_fallback_active={direct_summary.get('software_fallback_active')}, "
                    "uses_allocated_object="
                    f"{direct_summary.get('pac_probe_uses_allocated_object')}, "
                    "backend_observation_consistent="
                    f"{direct_summary.get('backend_observation_consistent')}, "
                    f"active_key={direct_summary.get('pac_probe_active_key')}, "
                    f"pac_signs={direct_summary.get('pac_signs')}, "
                    f"pac_verifications={direct_summary.get('pac_verifications')}, "
                    "software_fallback="
                    f"signs={direct_summary.get('pac_software_fallback_signs')},"
                    f"verifications={direct_summary.get('pac_software_fallback_verifications')}"
                )
                blockers.extend(
                    "claim-grade blocker: " + blocker
                    for blocker in direct_blockers
                )
            build_std_path, build_std_audit = latest_pac_arm64e_build_std_direct_probe_audit()
            if build_std_path is not None:
                pac_arm64e_build_std_summary = (
                    build_std_audit.get("summary", {})
                    if isinstance(build_std_audit.get("summary"), dict)
                    else {}
                )
                if str(build_std_path) not in result["evidence"]:
                    result["evidence"].append(str(build_std_path))
                result["evidence"].append(
                    "PAC arm64e build-std direct allocator probe: "
                    f"run_id={build_std_audit.get('run_id')}, "
                    f"runtime={pac_arm64e_build_std_summary.get('runtime')}, "
                    "build_std_requested="
                    f"{pac_arm64e_build_std_summary.get('build_std_requested')}, "
                    "build_std_crates="
                    f"{pac_arm64e_build_std_summary.get('build_std_crates')}, "
                    f"validated={pac_arm64e_build_std_summary.get('probe_validated')}, "
                    f"claim_grade={pac_arm64e_build_std_summary.get('claim_grade')}, "
                    f"exit_code={pac_arm64e_build_std_summary.get('exit_code')}, "
                    "hardware_pac_validated="
                    f"{pac_arm64e_build_std_summary.get('hardware_pac_validated')}, "
                    "cargo_target_cleaned="
                    f"{pac_arm64e_build_std_summary.get('cargo_target_cleaned')}, "
                    "cargo_target_removed_bytes="
                    f"{pac_arm64e_build_std_summary.get('cargo_target_removed_bytes')}"
                )
                if (
                    not pac_direct_claim_grade_ready
                    and pac_arm64e_build_std_summary.get("hardware_pac_validated") is not True
                ):
                    blockers.extend(
                        "claim-grade blocker: arm64e build-std direct probe: " + blocker
                        for blocker in pac_metadata_direct_probe_blockers(build_std_audit)
                    )
            if not pac_direct_hardware_validated:
                shim_path, shim_audit = latest_pac_arm64e_shim_compat_probe_audit()
                shim_summary = (
                    shim_audit.get("summary", {})
                    if isinstance(shim_audit.get("summary"), dict)
                    else {}
                )
                if shim_path is not None:
                    if str(shim_path) not in result["evidence"]:
                        result["evidence"].append(str(shim_path))
                    result["evidence"].append(
                        "PAC arm64e shim compatibility probe: "
                        f"run_id={shim_audit.get('run_id')}, "
                        "arm64_host_loads_arm64e_dylib="
                        f"{shim_summary.get('arm64_host_loads_arm64e_dylib')}, "
                        "arm64_host_arm64e_shim_context_binding="
                        f"{shim_summary.get('arm64_host_arm64e_shim_context_binding')}, "
                        "arm64_host_wrong_context_rejected="
                        f"{shim_summary.get('arm64_host_wrong_context_rejected')}, "
                        "arm64e_host_arm64e_shim_context_binding="
                        f"{shim_summary.get('arm64e_host_arm64e_shim_context_binding')}, "
                        "arm64e_host_wrong_context_rejected_by_signal="
                        f"{shim_summary.get('arm64e_host_wrong_context_rejected_by_signal')}, "
                        "rust_arm64e_target_listed="
                        f"{shim_summary.get('rust_arm64e_target_listed')}, "
                        "rust_arm64e_std_installed="
                        f"{shim_summary.get('rust_arm64e_std_installed')}, "
                        "rust_arm64e_target_available="
                        f"{shim_summary.get('rust_arm64e_target_available')}, "
                        "current_rust_target_can_use_arm64e_shim="
                        f"{shim_summary.get('current_rust_target_can_use_arm64e_shim')}"
                    )
                    if shim_summary.get("current_rust_target_can_use_arm64e_shim") is not True:
                        blockers.append(
                            "claim-grade blocker: arm64e PAC shim cannot provide hardware "
                            "PAC to the current Rust allocator target"
                        )
        hugepage_direct_path: Optional[Path] = None
        hugepage_direct_audit: Dict[str, Any] = {}
        hugepage_direct_summary: Dict[str, Any] = {}
        hugepage_direct_claim_grade = False
        if dataset == "hugepage_metadata":
            hugepage_direct_path, hugepage_direct_audit = latest_hugepage_metadata_direct_probe_audit()
            hugepage_direct_summary = (
                hugepage_direct_audit.get("summary", {})
                if isinstance(hugepage_direct_audit.get("summary"), dict)
                else {}
            )
            hugepage_direct_claim_grade = (
                hugepage_direct_summary.get("claim_grade") is True
                and hugepage_direct_summary.get("hugepage_backed") is True
                and not hugepage_metadata_direct_probe_blockers(hugepage_direct_audit)
            )
        validated = probe_summary.get(validation_key) is True
        if dataset == "pac_authentication" and pac_direct_claim_grade_ready:
            validated = True
            result["evidence"].append(
                "PAC runtime feature gate satisfied by direct arm64e allocator PAC probe; "
                "older std_bench PAC runtime probe is retained as diagnostic evidence only"
            )
        if not validated:
            if (
                dataset == "pac_authentication"
                and probe_summary.get("pac_metadata_auth_software_fallback_validated") is True
            ):
                pac_probe = probe_summary.get("pac_metadata_auth_probe")
                pac_probe_detail = ""
                if isinstance(pac_probe, dict):
                    pac_matrix = pac_probe.get("pac_probe_key_matrix")
                    pac_matrix_detail = ""
                    if isinstance(pac_matrix, list) and pac_matrix:
                        compact_matrix = ",".join(
                            f"{entry.get('key')}:avail={entry.get('available')},wrong_reject={entry.get('wrong_context_rejected')}"
                            for entry in pac_matrix
                            if isinstance(entry, dict)
                        )
                        if compact_matrix:
                            pac_matrix_detail = f", key_matrix=[{compact_matrix}]"
                    pac_probe_detail = (
                        " "
                        f"(probe_key={pac_probe.get('pac_probe_key')}, "
                        f"active_key={pac_probe.get('pac_probe_active_key')}, "
                        f"signed_changed={pac_probe.get('pac_probe_signed_changed')}, "
                        f"strip_roundtrip={pac_probe.get('pac_probe_strip_roundtrip')}, "
                        "correct_context_roundtrip="
                        f"{pac_probe.get('pac_probe_correct_context_roundtrip')}, "
                        "wrong_context_rejected="
                        f"{pac_probe.get('pac_probe_wrong_context_rejected')}"
                        f"{pac_matrix_detail})"
                    )
                blockers.append(
                    "claim-grade blocker: PAC runtime probe used software fallback; "
                    "hardware context binding was not validated"
                    f"{pac_probe_detail}"
                )
                if (
                    pac_abi_summary.get("hardware_pac_context_binding_observed") is True
                    and pac_abi_summary.get("rust_arm64e_target_available") is False
                ):
                    std_detail = ""
                    if pac_abi_summary.get("rust_arm64e_target_listed") is True:
                        std_detail = (
                            "; rustc lists arm64e but rustup/std availability is "
                            f"installed={pac_abi_summary.get('rust_arm64e_std_installed')}"
                        )
                    build_std_exit = optional_int(pac_arm64e_build_std_summary.get("exit_code"))
                    if pac_arm64e_build_std_summary:
                        signal_detail = (
                            f"; build-std arm64e direct run terminated by signal {-build_std_exit}"
                            if build_std_exit is not None and build_std_exit < 0
                            else f"; build-std arm64e direct run exit_code={build_std_exit}"
                        )
                        if pac_arm64e_build_std_summary.get("hardware_pac_validated") is True:
                            side_cache_detail = (
                                "; full allocator side-cache validated="
                                f"{pac_arm64e_build_std_summary.get('full_allocator_side_cache_validated')}"
                            )
                            blockers.append(
                                "claim-grade blocker: hardware PAC context binding was observed "
                                "in an arm64e build-std direct probe, but the full allocator "
                                "type-cache side-cache path is still not claim-grade"
                                f"{signal_detail}{side_cache_detail}{std_detail}"
                            )
                        else:
                            blockers.append(
                                "claim-grade blocker: hardware PAC context binding was observed only "
                                "through an external arm64e ABI probe; build-std can reach the "
                                "arm64e allocator run path, but runtime PAC validation is still not "
                                f"claim-grade{signal_detail}{std_detail}"
                            )
                    else:
                        blockers.append(
                            "claim-grade blocker: hardware PAC context binding was observed only "
                            "through an external arm64e ABI probe; the current Rust allocator "
                            "target cannot build/run as arm64e, so allocator PAC remains a "
                            f"software fallback{std_detail}"
                        )
            else:
                blockers.append(
                    "claim-grade blocker: runtime feature probe did not validate "
                    f"{gate['description']}"
                )
        if (
            dataset == "hugepage_metadata"
            and probe_summary.get("hugepage_acceleration_observed") is not True
            and not hugepage_direct_claim_grade
        ):
            hugepage_claim_blockers = unique_strings(
                probe_summary.get("hugepage_claim_grade_blockers") or []
            )
            if hugepage_claim_blockers:
                blockers.extend(
                    f"claim-grade blocker: {blocker}"
                    for blocker in hugepage_claim_blockers
                )
            else:
                blockers.append(
                    "claim-grade blocker: hugepage metadata probe did not observe "
                    "successful hugepage mmap backing"
                )
        if dataset == "hugepage_metadata":
            if hugepage_direct_path is None:
                blockers.append(
                    "claim-grade blocker: missing direct hugepage metadata allocator/PAL probe"
                )
            else:
                direct_summary = hugepage_direct_summary
                if str(hugepage_direct_path) not in result["evidence"]:
                    result["evidence"].append(str(hugepage_direct_path))
                result["evidence"].append(
                    "direct hugepage metadata allocator/PAL probe: "
                    f"run_id={hugepage_direct_audit.get('run_id')}, "
                    f"validated={direct_summary.get('probe_validated')}, "
                    f"claim_grade={direct_summary.get('claim_grade')}, "
                    f"hugepage_backed={direct_summary.get('hugepage_backed')}, "
                    f"backing={direct_summary.get('backing')}, "
                    f"mmap_attempts={direct_summary.get('mmap_attempts')}, "
                    f"mmap_successes={direct_summary.get('mmap_successes')}, "
                    f"mmap_fallbacks={direct_summary.get('mmap_fallbacks')}, "
                    f"aligned_fallbacks={direct_summary.get('mmap_aligned_fallbacks')}, "
                    f"hugetlb_syscalls={direct_summary.get('mmap_hugetlb_syscalls')}, "
                    f"hugetlb_skips={direct_summary.get('mmap_hugetlb_skips')}, "
                    "last_error="
                    f"{direct_summary.get('last_error_stage')} "
                    f"code={direct_summary.get('last_error_code')} "
                    f"name={direct_summary.get('last_error_name')}, "
                    "linux_smaps="
                    f"found={direct_summary.get('linux_smaps_mapping_found')}, "
                    f"kernel_page_kb={direct_summary.get('linux_smaps_kernel_page_kb')}, "
                    f"mmu_page_kb={direct_summary.get('linux_smaps_mmu_page_kb')}, "
                    f"anon_huge_kb={direct_summary.get('linux_smaps_anon_huge_kb')}, "
                    f"thp_eligible={direct_summary.get('linux_smaps_thp_eligible')}, "
                    f"vmflags_ht={direct_summary.get('linux_smaps_vmflags_ht')}, "
                    f"vmflags_hg={direct_summary.get('linux_smaps_vmflags_hg')}, "
                    f"vmflags_nh={direct_summary.get('linux_smaps_vmflags_nh')}, "
                    f"prefaulted_pages={direct_summary.get('linux_prefaulted_pages')}"
                )
                blockers.extend(
                    "claim-grade blocker: " + blocker
                    for blocker in hugepage_metadata_direct_probe_blockers(hugepage_direct_audit)
                )
        if dataset in {"type_isolation", "metadata_segregation"}:
            smoke_path, smoke_audit = latest_mir_semantic_scope_paper_performance_smoke_audit(dataset)
            if smoke_path is None:
                blockers.append(
                    "claim-grade blocker: missing rustc_driver MIR semantic-scope "
                    f"paper-performance smoke for {dataset}"
                )
            else:
                smoke_summary = (
                    smoke_audit.get("summary", {})
                    if isinstance(smoke_audit.get("summary"), dict)
                    else {}
                )
                smoke_rows = (
                    smoke_audit.get("performance_rows", [])
                    if isinstance(smoke_audit.get("performance_rows"), list)
                    else []
                )
                dataset_rows = [
                    row for row in smoke_rows if isinstance(row, dict) and row.get("dataset") == dataset
                ]
                if str(smoke_path) not in result["evidence"]:
                    result["evidence"].append(str(smoke_path))
                result["evidence"].append(
                    "bounded rustc_driver MIR semantic-scope paper-performance smoke: "
                    f"run_id={smoke_audit.get('run_id')}, "
                    f"validated={smoke_summary.get('paper_performance_smoke_validated')}, "
                    f"timing_bench_results={smoke_summary.get('timing_bench_result_count')}, "
                    f"selected_benchmarks={smoke_summary.get('selected_benchmark_count')}, "
                    f"typed_events={smoke_summary.get('typed_allocation_site_event_count')}, "
                    f"lowered_module_typed_events="
                    f"{smoke_summary.get('lowered_module_typed_allocation_site_event_count')}, "
                    f"rewrite_applied={smoke_summary.get('semantic_scope_rewrite_applied_count')}, "
                    f"timing_ns_per_iter="
                    f"{dataset_rows[0].get('ns_per_iter') if dataset_rows else 'n/a'}"
                )
                blockers.extend(
                    "claim-grade blocker: " + blocker
                    for blocker in mir_semantic_scope_paper_performance_smoke_blockers(
                        smoke_audit,
                        dataset,
                    )
                )

    for blocker in unique_strings(blockers):
        if blocker not in result["evidence"]:
            result["evidence"].append(blocker)
    if blockers and result.get("status") == "pass":
        result["status"] = "missing"
    return result


PRIMARY_DYNAMIC_ATTRIBUTION_GAP_ORDER = [
    "mir_semantic_scope_full_surface_c002_runtime_missing",
    "observed_benchmark_source_not_final_c002_run",
    "rustc_driver_mir_semantic_scope_std_bench_runtime_smoke_not_full_surface_claim",
    "rustc_driver_mir_semantic_scope_std_bench_compile_not_runtime_claim",
    "rustc_driver_mir_semantic_scope_probe_not_std_bench_full_surface",
    "rustc_driver_mir_actual_rewrite_runtime_smoke_not_full_surface_claim",
    "rustc_driver_mir_actual_rewrite_compile_not_runtime_validated",
    "rustc_driver_mir_rewrite_dry_run_not_actual_call_replacement",
]


def prioritized_dynamic_attribution_gaps(
    gaps: Iterable[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    """Rank C002 dynamic-attribution gaps by current implementation relevance.

    The real rustc_driver MIR semantic-scope runtime gap is the primary blocker
    once available; legacy smoke and replay-preflight gaps remain useful context
    but should not appear before the current strongest evidence in claim-check
    output.
    """

    priority = {
        gap_id: index for index, gap_id in enumerate(PRIMARY_DYNAMIC_ATTRIBUTION_GAP_ORDER)
    }
    ranked: List[Tuple[int, int, Dict[str, Any]]] = []
    for index, gap in enumerate(gaps):
        if not isinstance(gap, dict):
            continue
        gap_id = str(gap.get("id") or "")
        ranked.append((priority.get(gap_id, len(priority)), index, gap))
    ranked.sort(key=lambda item: (item[0], item[1]))
    return [gap for _priority, _index, gap in ranked]


def accept_compiler_coverage_audit_claim(
    result: Dict[str, Any],
    *,
    compiler_audit: Dict[str, Any],
    claim_grade_status: Dict[str, Any],
    claim: Dict[str, Any],
) -> Dict[str, Any]:
    audit_summary = claim_grade_status["summary"]
    observed = claim_grade_status["observed"]
    result["observed"] = observed
    compiler_audit_path = RESULTS / "compiler_coverage_evidence_audit.json"
    result["source_artifacts"] = [str(compiler_audit_path)]
    result["evidence"].append(str(compiler_audit_path))
    result["evidence"].append(
        "accepted current claim-grade compiler coverage audit; "
        "legacy coverage_summary remains diagnostic only"
    )
    result["evidence"].append(
        "current claim-grade compiler audit basis: "
        f"{compiler_audit.get('type_id_basis')} with "
        f"{audit_summary.get('type_mapping_valid_record_count')} valid MIR type-mapping rows, "
        f"{audit_summary.get('benchmark_surface_observed_count')}/"
        f"{audit_summary.get('benchmark_surface_expected_count')} std_bench benchmarks, "
        f"coverage={fmt(observed)}%"
    )
    runtime_companion = claim_grade_status.get("runtime_companion")
    if isinstance(runtime_companion, dict) and runtime_companion.get("ready") is True:
        runtime_summary = (
            runtime_companion.get("summary", {})
            if isinstance(runtime_companion.get("summary"), dict)
            else {}
        )
        runtime_target_rewrite = (
            runtime_companion.get("target_rewrite", {})
            if isinstance(runtime_companion.get("target_rewrite"), dict)
            else {}
        )
        runtime_companion_path = str(
            claim_grade_status.get("runtime_companion_path") or ""
        )
        if runtime_companion_path:
            result["source_artifacts"].append(runtime_companion_path)
            result["evidence"].append(runtime_companion_path)
        result["evidence"].append(
            "accepted real rustc_driver MIR semantic-scope runtime companion: "
            f"actual_rewrite={runtime_summary.get('actual_semantic_scope_rewrite')}, "
            f"libtest_mode={runtime_summary.get('libtest_mode')}, "
            f"selected_benchmarks={runtime_summary.get('selected_benchmark_count')}/"
            f"{runtime_summary.get('canonical_expected_benchmark_count')}, "
            f"lowered_module_typed_events="
            f"{runtime_summary.get('lowered_module_typed_allocation_site_event_count')}, "
            f"rewrite_applied={runtime_summary.get('semantic_scope_rewrite_applied_count')}, "
            f"raw_rewrite_map={runtime_target_rewrite.get('path')}"
        )
    mir_probe_companions = claim_grade_status.get("mir_probe_companions")
    if isinstance(mir_probe_companions, dict) and mir_probe_companions.get("ready") is True:
        semantic_probe = mir_probe_companions.get("semantic_scope_probe", {})
        direct_probe = mir_probe_companions.get("direct_allocator_probe", {})
        cross_thread_probe = mir_probe_companions.get("cross_thread_hint_probe", {})
        semantic_summary = (
            semantic_probe.get("summary", {}) if isinstance(semantic_probe.get("summary"), dict) else {}
        )
        direct_summary = (
            direct_probe.get("summary", {}) if isinstance(direct_probe.get("summary"), dict) else {}
        )
        cross_thread_summary = (
            cross_thread_probe.get("summary", {})
            if isinstance(cross_thread_probe.get("summary"), dict)
            else {}
        )
        companion_paths = [
            RESULTS / "rustc_driver_mir_semantic_scope_probe_audit.json",
            RESULTS / "rustc_driver_direct_allocator_mir_probe_audit.json",
            RESULTS / "rustc_driver_mir_cross_thread_hint_probe_audit.json",
        ]
        result["source_artifacts"].extend(str(path) for path in companion_paths)
        result["evidence"].extend(str(path) for path in companion_paths)
        result["evidence"].append(
            "accepted small rustc_driver MIR probe companions: "
            f"semantic_scope_probe_validated={semantic_summary.get('runtime_probe_validated')}, "
            f"semantic_scope_rewrite_applied={semantic_summary.get('semantic_scope_rewrite_applied_count')}, "
            f"semantic_scope_typed_allocations={semantic_summary.get('typed_allocations')}, "
            f"semantic_scope_receiver_mutating_rows="
            f"{semantic_summary.get('receiver_mutating_collection_type_mapping_record_count')}, "
            f"semantic_scope_receiver_misattributed="
            f"{semantic_summary.get('receiver_mutating_collection_misattributed_record_count')}, "
            f"direct_allocator_probe_validated={direct_summary.get('runtime_probe_validated')}, "
            f"direct_allocator_rewrite_applied={direct_summary.get('direct_allocator_rewrite_applied_count')}, "
            f"direct_allocator_typed_allocations={direct_summary.get('typed_allocations')}, "
            f"direct_layout_result_option_passthrough_rewrite_applied="
            f"{direct_summary.get('direct_layout_result_option_passthrough_rewrite_applied_count')}, "
            f"direct_layout_result_option_passthrough_type_mapping_rows="
            f"{direct_summary.get('direct_layout_result_option_passthrough_type_mapping_record_count')}, "
            f"cross_thread_hint_probe_validated={cross_thread_summary.get('runtime_probe_validated')}, "
            f"cross_thread_recovery_hints={cross_thread_summary.get('cross_thread_recovery_hint_count')}, "
            f"cross_thread_typed_deallocations={cross_thread_summary.get('typed_deallocations')}, "
            f"cross_thread_fallback_attribution_matches="
            f"{cross_thread_summary.get('fallback_attribution_matches_stats')}, "
            f"cross_thread_raw_no_metadata_fallback_allocations="
            f"{cross_thread_summary.get('fallback_attribution_raw_alloc_no_metadata')}, "
            f"cross_thread_worker_start_raw_no_metadata="
            f"{cross_thread_summary.get('fallback_trace_worker_start_raw_alloc_no_metadata')}, "
            "no_wrapper_controls=true"
        )
    dynamic_gap_audit = read_json_if_exists(RESULTS / "compiler_dynamic_attribution_gap_audit.json")
    if isinstance(dynamic_gap_audit, dict):
        dynamic_summary = dynamic_gap_audit.get("summary", {})
        if isinstance(dynamic_summary, dict):
            result["evidence"].append(
                "dynamic attribution audit retained as diagnostics: "
                f"current_mir_semantic_scope_runtime_evidence_ready="
                f"{dynamic_summary.get('current_mir_semantic_scope_runtime_evidence_ready')}, "
                f"observed_source_claim_ready="
                f"{dynamic_summary.get('observed_source_claim_ready')}, "
                f"benchmark_suite_claim_ready="
                f"{dynamic_summary.get('benchmark_suite_claim_ready')}, "
                f"remaining_legacy_gap_count={dynamic_summary.get('remaining_gap_count')}"
            )
    append_semantic_fallback_attribution_evidence(result)
    append_semantic_metadata_validation_evidence(result)
    result["status"] = passfail(
        observed is not None and observed >= claim["threshold"]["gte"]
    )
    return result


