def evaluate_claim(claim: Dict[str, Any], summary: Dict[str, Any], source: str) -> Dict[str, Any]:
    metric = claim["metric"]
    result = {
        "id": claim["id"],
        "description": claim["description"],
        "metric": metric,
        "status": "missing",
        "observed": None,
        "threshold": claim.get("threshold"),
        "dataset": claim.get("dataset"),
        "baseline_dataset": claim.get("baseline_dataset"),
        "acceptance_rule": claim_acceptance_rule(claim),
        "evidence": [],
        "required_for_overclaim": bool(claim.get("required_for_overclaim")),
    }
    if metric == "coverage_percent":
        if source == "paper":
            observed = claim.get("expected")
            result["observed"] = observed
            result["evidence"].append("paper text states 72.17%; current coverage artifact still required for repository proof")
        else:
            cov = RESULTS / "coverage_summary.json"
            compiler_audit = read_json_if_exists(RESULTS / "compiler_coverage_evidence_audit.json")
            audit_threshold = optional_float(claim.get("threshold", {}).get("gte"))
            claim_grade_status = compiler_coverage_claim_grade_status(
                compiler_audit,
                threshold=audit_threshold,
            )
            if cov.exists():
                cov_data = read_json(cov)
                observed = cov_data.get("coverage_percent")
                result["evidence"].append(str(cov))
                result["observed"] = observed
                if not cov_data.get("evidence_verified"):
                    if claim_grade_status["ready"] and isinstance(compiler_audit, dict):
                        result["evidence"].append(
                            "legacy coverage_summary evidence is unverified; using current compiler coverage audit"
                        )
                        return accept_compiler_coverage_audit_claim(
                            result,
                            compiler_audit=compiler_audit,
                            claim_grade_status=claim_grade_status,
                            claim=claim,
                        )
                    result["evidence"].append("coverage evidence is not verified; provide --events or --evidence paths/URIs")
                    return result
                if not cov_data.get("claim_grade"):
                    result["evidence"].append(
                        "legacy coverage_summary artifact is superseded for the compiler-assisted paper claim; "
                        "checking current compiler coverage audit"
                    )
                    if claim_grade_status["ready"] and isinstance(compiler_audit, dict):
                        return accept_compiler_coverage_audit_claim(
                            result,
                            compiler_audit=compiler_audit,
                            claim_grade_status=claim_grade_status,
                            claim=claim,
                        )
                    if compiler_coverage_audit_is_current_strongest(compiler_audit):
                        audit_summary = compiler_audit.get("summary", {})
                        result["evidence"].append(str(RESULTS / "compiler_coverage_evidence_audit.json"))
                        result["evidence"].append(f"legacy active coverage type-id basis: {cov_data.get('type_id_basis')}")
                        result["evidence"].append(
                            "current strongest compiler audit basis: "
                            f"{compiler_audit.get('type_id_basis')} with "
                            f"{audit_summary.get('type_mapping_valid_record_count')} valid MIR type-mapping rows"
                        )
                        for blocker in compiler_audit.get("blockers", []):
                            result["evidence"].append(f"compiler-audit blocker: {blocker}")
                        for blocker in claim_grade_status.get("blockers", []):
                            result["evidence"].append(f"compiler-audit claim-grade blocker: {blocker}")
                        exact_probe_audit = read_json_if_exists(RESULTS / "compiler_exact_dynamic_probe_audit.json")
                        if isinstance(exact_probe_audit, dict):
                            probe_summary = exact_probe_audit.get("summary", {})
                            if isinstance(probe_summary, dict):
                                result["evidence"].append(
                                    "exact-dynamic probe: "
                                    f"available={probe_summary.get('event_type_id_basis_status') == 'pass'}, "
                                    f"basis={probe_summary.get('event_type_id_bases')}, "
                                    f"type_mapping_valid={probe_summary.get('type_mapping_valid_record_count')}, "
                                    f"coverage={probe_summary.get('coverage_percent')}%"
                                )
                        dynamic_gap_audit = read_json_if_exists(RESULTS / "compiler_dynamic_attribution_gap_audit.json")
                        if isinstance(dynamic_gap_audit, dict):
                            dynamic_summary = dynamic_gap_audit.get("summary", {})
                            if isinstance(dynamic_summary, dict):
                                result["evidence"].append(
                                    "dynamic attribution audit: "
                                    f"exact_probe_available={dynamic_summary.get('exact_dynamic_probe_available')}, "
                                    f"exact_ready={dynamic_summary.get('exact_dynamic_attribution_ready')}, "
                                    f"remaining_gaps={dynamic_summary.get('remaining_gap_count')}"
                                )
                                if dynamic_summary.get("rustc_driver_mir_actual_rewrite_runtime_smoke_validated") is True:
                                    result["evidence"].append(
                                        "actual rustc_driver MIR rewrite smoke: "
                                        f"validated=True, "
                                        f"selected_benchmarks="
                                        f"{dynamic_summary.get('rustc_driver_mir_actual_rewrite_runtime_smoke_selected_benchmark_count')}, "
                                        f"typed_events="
                                        f"{dynamic_summary.get('rustc_driver_mir_actual_rewrite_runtime_smoke_typed_allocation_site_event_count')}, "
                                        f"lowered_module_typed_events="
                                        f"{dynamic_summary.get('rustc_driver_mir_actual_rewrite_runtime_smoke_lowered_module_typed_allocation_site_event_count')}, "
                                        f"rewrite_applied="
                                        f"{dynamic_summary.get('rustc_driver_mir_rewrite_dry_run_rewrite_applied_count')}, "
                                        f"replacement="
                                        f"{dynamic_summary.get('rustc_driver_mir_rewrite_dry_run_replacement_resolution_status')}"
                                    )
                                if dynamic_summary.get("rustc_driver_mir_semantic_scope_probe_validated") is True:
                                    result["evidence"].append(
                                        "actual rustc_driver MIR semantic-scope probe: "
                                        f"validated=True, "
                                        f"typed_allocations="
                                        f"{dynamic_summary.get('rustc_driver_mir_semantic_scope_probe_typed_allocations')}, "
                                        f"fallback_allocations="
                                        f"{dynamic_summary.get('rustc_driver_mir_semantic_scope_probe_fallback_allocations')}, "
                                        f"lowered_rows="
                                        f"{dynamic_summary.get('rustc_driver_mir_semantic_scope_probe_lowered_rows')}, "
                                        f"rewrite_applied="
                                        f"{dynamic_summary.get('rustc_driver_mir_semantic_scope_probe_rewrite_applied_count')}, "
                                        f"stream_mode="
                                        f"{dynamic_summary.get('rustc_driver_mir_semantic_scope_probe_stream_mode')}"
                                    )
                                if (
                                    dynamic_summary.get(
                                        "rustc_driver_mir_semantic_scope_std_bench_compile_validated"
                                    )
                                    is True
                                ):
                                    result["evidence"].append(
                                        "actual rustc_driver MIR semantic-scope std_bench compile: "
                                        f"validated=True, "
                                        f"candidates="
                                        f"{dynamic_summary.get('rustc_driver_mir_semantic_scope_std_bench_compile_candidate_count')}, "
                                        f"rewrite_applied="
                                        f"{dynamic_summary.get('rustc_driver_mir_semantic_scope_std_bench_compile_rewrite_applied_count')}, "
                                        f"replacement="
                                        f"{dynamic_summary.get('rustc_driver_mir_semantic_scope_std_bench_compile_replacement_resolution_status')}"
                                    )
                                if (
                                    dynamic_summary.get(
                                        "rustc_driver_mir_semantic_scope_std_bench_runtime_smoke_validated"
                                    )
                                    is True
                                ):
                                    result["evidence"].append(
                                        "actual rustc_driver MIR semantic-scope std_bench runtime smoke: "
                                        f"validated=True, "
                                        f"selected_benchmarks="
                                        f"{dynamic_summary.get('rustc_driver_mir_semantic_scope_std_bench_runtime_smoke_selected_benchmark_count')}, "
                                        f"typed_events="
                                        f"{dynamic_summary.get('rustc_driver_mir_semantic_scope_std_bench_runtime_smoke_typed_allocation_site_event_count')}, "
                                        f"lowered_module_typed_events="
                                        f"{dynamic_summary.get('rustc_driver_mir_semantic_scope_std_bench_runtime_smoke_lowered_module_typed_allocation_site_event_count')}, "
                                        f"lowered_module_allocations="
                                        f"{dynamic_summary.get('rustc_driver_mir_semantic_scope_std_bench_runtime_smoke_lowered_module_allocations')}, "
                                        f"rewrite_applied="
                                        f"{dynamic_summary.get('rustc_driver_mir_semantic_scope_std_bench_runtime_smoke_rewrite_applied_count')}, "
                                        f"stream_modes="
                                        f"{dynamic_summary.get('rustc_driver_mir_semantic_scope_std_bench_runtime_smoke_stream_modes')}"
                                    )
                            dynamic_gaps = [
                                gap for gap in dynamic_gap_audit.get("remaining_gaps", []) if isinstance(gap, dict)
                            ]
                            prioritized_gaps = prioritized_dynamic_attribution_gaps(dynamic_gaps)
                            seen_gap_ids = set()
                            for gap in prioritized_gaps[:5]:
                                gap_id = gap.get("id")
                                if gap_id in seen_gap_ids:
                                    continue
                                seen_gap_ids.add(gap_id)
                                result["evidence"].append(
                                    f"dynamic attribution gap: {gap_id}: {gap.get('description')}"
                                )
                        append_semantic_fallback_attribution_evidence(result)
                        append_semantic_metadata_validation_evidence(result)
                    else:
                        if cov_data.get("type_id_basis"):
                            result["evidence"].append(f"type-id basis: {cov_data.get('type_id_basis')}")
                        for blocker in cov_data.get("claim_grade_blockers", []):
                            result["evidence"].append(f"claim-grade blocker: {blocker}")
                        append_semantic_fallback_attribution_evidence(result)
                        append_semantic_metadata_validation_evidence(result)
                    result["status"] = "missing"
                    return result
            else:
                result["evidence"].append("missing evaluation/results/coverage_summary.json")
                if claim_grade_status["ready"] and isinstance(compiler_audit, dict):
                    result["evidence"].append(
                        "using current compiler coverage audit because coverage_summary is absent"
                    )
                    return accept_compiler_coverage_audit_claim(
                        result,
                        compiler_audit=compiler_audit,
                        claim_grade_status=claim_grade_status,
                        claim=claim,
                    )
                return result
        result["status"] = passfail(observed is not None and observed >= claim["threshold"]["gte"])
        return result
    if metric == "platform_evidence_matrix":
        matrix = RESULTS / "platform_matrix.json"
        if source == "paper":
            observed = {p: "claimed-in-paper" for p in claim["platforms"]}
            result["evidence"].append("paper eval/sys sections list target platforms; current platform artifacts still required")
            result["observed"] = observed
            result["status"] = "paper-reference"
            return result
        if not matrix.exists():
            result["evidence"].append("missing evaluation/results/platform_matrix.json")
            return result
        data = read_json(matrix)
        result["evidence"].append(str(matrix))
        missing = [p for p in claim["platforms"] if not data.get(p, {}).get("evidence_verified")]
        result["observed"] = data
        result["status"] = passfail(not missing)
        if missing:
            result["evidence"].append("missing, unverified, or non-claim-grade platforms: " + ", ".join(missing))
            for platform in missing:
                info = data.get(platform, {})
                if not isinstance(info, dict):
                    continue
                for blocker in info.get("platform_claim_blockers", [])[:6]:
                    result["evidence"].append(f"{platform}: claim-grade blocker: {blocker}")
                for blocker in info.get("claim_grade_blockers", [])[:6]:
                    result["evidence"].append(f"{platform}: claim-grade blocker: {blocker}")
                missing_kinds = info.get("missing_required_evidence_kinds", [])
                if missing_kinds:
                    result["evidence"].append(
                        f"{platform}: missing required evidence kinds: {', '.join(map(str, missing_kinds))}"
                    )
                missing_fields = info.get("missing_metadata_fields", [])
                if missing_fields:
                    result["evidence"].append(
                        f"{platform}: missing metadata fields: {', '.join(map(str, missing_fields))}"
                    )
                for blocker in info.get("evidence_content_blockers", [])[:8]:
                    result["evidence"].append(f"{platform}: evidence content blocker: {blocker}")
        return result
    datasets = summary.get("datasets", {}) if source == "paper" else summary.get("datasets", {})
    ds_name = claim.get("dataset")
    ds = datasets.get(ds_name) if ds_name else None
    if source == "current" and ds is None:
        # The simple local runner stores feature-normalized data rather than full paper datasets.
        result["evidence"].append(f"current dataset '{ds_name}' missing; import/run matching benchmark suite first")
        return apply_feature_runtime_gate(result, claim, source)
    if ds is None:
        result["evidence"].append(f"dataset '{ds_name}' missing")
        return result
    result["evidence"].append(ds.get("path", ds_name))
    if source == "current" and not ds.get("claim_grade"):
        result["observed"] = {
            "geomean": ds.get("geomean"),
            "count": ds.get("count"),
            "scope": ds.get("scope"),
        }
        result["status"] = "missing"
        result["evidence"].append("current dataset is not claim-grade for this paper claim")
        for blocker in ds.get("scope", {}).get("claim_grade_blockers", []):
            result["evidence"].append(f"claim-grade blocker: {blocker}")
        return apply_feature_runtime_gate(result, claim, source)
    if metric == "geomean_delta_percent_vs_unialloc":
        observed = ds.get("geomean_delta_percent_vs_unialloc")
        result["observed"] = observed
        limit = float(claim["threshold"]["abs_lte"])
        if observed is not None and observed > limit:
            result["evidence"].append(
                f"observed delta {fmt(observed)}% is better than the paper-equivalent +-{fmt(limit)}% window and is accepted"
            )
        result["status"] = passfail(observed is not None and observed >= -limit)
    elif metric == "geomean_speedup_percent_vs_baselines":
        observed = ds.get("speedup_percent_vs_baselines")
        result["observed"] = observed
        th = claim["threshold"]
        if "gte" in th:
            ok = observed is not None and observed >= th["gte"]
        elif "between" in th:
            lo, hi = th["between"]
            ok = observed is not None and observed >= lo
            if observed is not None and observed > hi:
                result["evidence"].append(
                    f"observed speedup {fmt(observed)}% exceeds the paper range upper bound {fmt(hi)}% and is accepted as better-than-paper"
                )
        else:
            ok = False
        result["status"] = passfail(ok)
    elif metric == "slowdown_percent_vs_baselines":
        # If baselines normalized to UniAlloc are below 1, UniAlloc is slower.
        gm = ds.get("geomean")
        observed = None if gm is None else (1.0 / gm - 1.0) * 100.0
        result["observed"] = observed
        lo, hi = claim["threshold"]["between"]
        if observed is not None and observed < lo:
            result["evidence"].append(
                f"observed slowdown {fmt(observed)}% is below the paper range lower bound {fmt(lo)}% and is accepted as better-than-paper"
            )
        result["status"] = passfail(observed is not None and observed <= hi)
    elif metric == "slowdown_percent_range_vs_default_unialloc":
        base_name = claim.get("baseline_dataset")
        base = datasets.get(base_name)
        if not base:
            result["evidence"].append(f"baseline dataset '{base_name}' missing")
            return result
        slowdowns = paired_slowdowns(default_ds=base, variant_ds=ds)
        result["observed"] = {
            "min": min(slowdowns) if slowdowns else None,
            "max": max(slowdowns) if slowdowns else None,
            "geomean": geomean([1 + s / 100.0 for s in slowdowns]),
            "count": len(slowdowns),
        }
        th = claim["threshold"]
        if slowdowns and min(slowdowns) < th["min_gte"]:
            result["evidence"].append(
                f"minimum observed slowdown {fmt(min(slowdowns))}% is below the paper range lower bound {fmt(th['min_gte'])}% and is accepted as better-than-paper"
            )
        ok = bool(slowdowns) and max(slowdowns) <= th["max_lte"]
        result["status"] = passfail(ok)
    else:
        result["evidence"].append(f"unsupported metric {metric}")
    return apply_feature_runtime_gate(result, claim, source)


def paired_slowdowns(default_ds: Dict[str, Any], variant_ds: Dict[str, Any]) -> List[float]:
    # Paper data is normalized as baseline_allocator_time / unialloc_variant_time.
    # For matching allocator+benchmark cells:
    #   unialloc_variant / unialloc_default = default_cell / variant_cell.
    by_bench = {r["benchmark"]: r for r in default_ds.get("rows", [])}
    slowdowns = []
    for vr in variant_ds.get("rows", []):
        dr = by_bench.get(vr["benchmark"])
        if not dr:
            continue
        for alloc, variant_value in vr["values"].items():
            default_value = dr["values"].get(alloc)
            if default_value and variant_value:
                slowdowns.append((default_value / variant_value - 1.0) * 100.0)
    return slowdowns


def passfail(ok: bool) -> str:
    return "pass" if ok else "fail"


def overall_status(results: List[Dict[str, Any]]) -> str:
    hard = [r for r in results if r.get("required_for_overclaim")]
    if any(r["status"] in {"fail", "missing"} for r in hard):
        return "fail"
    if any(r["status"] == "paper-reference" for r in hard):
        return "paper-reference"
    return "pass"


def write_claim_markdown(path: Path, report: Dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    lines = [f"# Claim check ({report['source']})", "", f"Overall: **{report['overall']}**", ""]
    lines.append("| claim | status | observed | threshold | acceptance rule |")
    lines.append("|---|---|---:|---|---|")
    for r in report["results"]:
        lines.append(
            f"| {r['id']} | {r['status']} | `{fmt(r.get('observed'))}` | "
            f"`{r.get('threshold')}` | {r.get('acceptance_rule') or '-'} |"
        )
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")


def overclaim_category(result: Dict[str, Any]) -> str:
    metric = result.get("metric")
    if metric == "coverage_percent":
        return "compiler_coverage"
    if metric == "platform_evidence_matrix":
        return "platform_retargeting"
    if metric in {
        "geomean_delta_percent_vs_unialloc",
        "geomean_speedup_percent_vs_baselines",
        "slowdown_percent_vs_baselines",
        "slowdown_percent_range_vs_default_unialloc",
    }:
        return "paper_performance"
    return "claim_evidence"


def overclaim_severity(result: Dict[str, Any]) -> str:
    status = str(result.get("status", "missing"))
    required = bool(result.get("required_for_overclaim"))
    if status == "fail" and required:
        return "critical"
    if status == "missing" and required:
        return "high"
    if status == "paper-reference" and required:
        return "medium"
    if status in {"fail", "missing"}:
        return "medium"
    return "low"


def clean_blocker(text: str) -> str:
    for prefix in (
        "claim-grade blocker: ",
        "missing, unverified, or non-claim-grade platforms: ",
    ):
        if text.startswith(prefix):
            return text[len(prefix) :]
    return text


def claim_blockers(result: Dict[str, Any]) -> List[str]:
    blockers: List[str] = []
    for evidence in result.get("evidence", []):
        text = str(evidence)
        lower = text.lower()
        if (
            "missing" in lower
            or "not claim-grade" in lower
            or "not verified" in lower
            or "blocker" in lower
            or "still required" in lower
            or "unproven" in lower
        ):
            blockers.append(clean_blocker(text))
    observed = result.get("observed")
    if isinstance(observed, dict):
        scope = observed.get("scope")
        if isinstance(scope, dict):
            blockers.extend(scope.get("claim_grade_blockers", []))
    return unique_strings(blockers)


def artifact_ref(path: Path) -> Dict[str, Any]:
    return {"path": str(path), "exists": path.exists()}


def compact_claim_observed(result: Dict[str, Any]) -> Any:
    observed = result.get("observed")
    if not isinstance(observed, dict):
        return observed
    metric = result.get("metric")
    if metric == "platform_evidence_matrix":
        platforms = {
            name: {
                "evidence_verified": value.get("evidence_verified"),
                "claim_grade": value.get("claim_grade"),
                "complete_for_claim": value.get("complete_for_claim"),
                "blocker_count": len(value.get("platform_claim_blockers", [])),
                "missing_required_evidence_kind_count": len(value.get("missing_required_evidence_kinds", [])),
                "evidence_content_blocker_count": len(value.get("evidence_content_blockers", [])),
                "missing_metadata_field_count": len(value.get("missing_metadata_fields", [])),
            }
            for name, value in observed.items()
            if isinstance(value, dict) and not str(name).startswith("_")
        }
        return {"platforms": platforms}
    scope = observed.get("scope")
    if isinstance(scope, dict):
        return {
            "geomean": observed.get("geomean"),
            "count": observed.get("count"),
            "path": scope.get("source") or scope.get("path"),
            "claim_grade": scope.get("manifest_claim_grade"),
            "complete_for_claim": scope.get("complete_for_claim"),
            "current_rows": scope.get("current_rows"),
            "reference_rows": scope.get("reference_rows"),
            "current_columns": scope.get("current_columns"),
            "missing_reference_rows": scope.get("missing_reference_rows"),
            "missing_reference_columns": scope.get("missing_reference_columns"),
        }
    return observed


def coverage_worklist_summary() -> Dict[str, Any]:
    data = read_json_if_exists(RESULTS / "coverage_summary.json")
    compiler_audit = read_json_if_exists(RESULTS / "compiler_coverage_evidence_audit.json")
    mir_audit = read_json_if_exists(RESULTS / "rustc_mir_allocation_site_audit.json")
    replay_audit = read_json_if_exists(RESULTS / "std_bench_compiler_site_replay_audit.json")
    dynamic_gap_audit = read_json_if_exists(RESULTS / "compiler_dynamic_attribution_gap_audit.json")
    exact_probe_audit = read_json_if_exists(RESULTS / "compiler_exact_dynamic_probe_audit.json")
    stream_mode_audit = read_json_if_exists(RESULTS / "compiler_site_stream_mode_comparison_audit.json")
    compiler_audit_type_id_basis = (
        compiler_audit.get("type_id_basis")
        if isinstance(compiler_audit, dict)
        else None
    )
    compiler_audit_summary = compiler_audit.get("summary", {}) if isinstance(compiler_audit, dict) else {}
    compiler_audit_blockers = compiler_audit.get("blockers", []) if isinstance(compiler_audit, dict) else []
    compiler_audit_benchmark_surface = (
        compiler_audit.get("benchmark_surface_audit", {}) if isinstance(compiler_audit, dict) else {}
    )
    mir_audit_summary = mir_audit.get("summary", {}) if isinstance(mir_audit, dict) else {}
    mir_audit_blockers = mir_audit.get("blockers", []) if isinstance(mir_audit, dict) else []
    replay_audit_summary = replay_audit.get("summary", {}) if isinstance(replay_audit, dict) else {}
    replay_audit_blockers = replay_audit.get("blockers", []) if isinstance(replay_audit, dict) else []
    dynamic_gap_summary = dynamic_gap_audit.get("summary", {}) if isinstance(dynamic_gap_audit, dict) else {}
    dynamic_gap_remaining = dynamic_gap_audit.get("remaining_gaps", []) if isinstance(dynamic_gap_audit, dict) else []
    exact_probe_summary = exact_probe_audit.get("summary", {}) if isinstance(exact_probe_audit, dict) else {}
    stream_mode_summary = stream_mode_audit.get("summary", {}) if isinstance(stream_mode_audit, dict) else {}
    stream_mode_blockers = stream_mode_audit.get("blockers", []) if isinstance(stream_mode_audit, dict) else []
    compiler_audit_uses_compiler_ids = coverage_basis_is_compiler_assigned(str(compiler_audit_type_id_basis or ""))
    compiler_audit_is_current_strongest = compiler_coverage_audit_is_current_strongest(compiler_audit)
    if not isinstance(data, dict):
        summary: Dict[str, Any] = {"present": False}
        if isinstance(compiler_audit, dict):
            summary["compiler_coverage_evidence_audit"] = compiler_audit_summary
            summary["compiler_coverage_audit_blockers"] = compiler_audit_blockers
            summary["compiler_coverage_benchmark_surface_audit"] = compiler_audit_benchmark_surface
            summary["compiler_coverage_audit_type_id_basis"] = compiler_audit_type_id_basis
            summary["compiler_coverage_audit_uses_compiler_assigned_type_ids"] = compiler_audit_uses_compiler_ids
            summary["compiler_coverage_audit_is_current_strongest"] = compiler_audit_is_current_strongest
        if isinstance(mir_audit, dict):
            summary["rustc_mir_allocation_site_audit"] = mir_audit_summary
            summary["rustc_mir_allocation_site_blockers"] = mir_audit_blockers
            summary["rustc_mir_source_kind"] = mir_audit.get("source_kind")
            summary["rustc_mir_allocation_site_count"] = mir_audit_summary.get("allocation_site_count")
            summary["rustc_mir_type_mapping_valid_record_count"] = mir_audit_summary.get(
                "type_mapping_valid_record_count"
            )
        if isinstance(replay_audit, dict):
            summary["std_bench_compiler_site_replay_audit"] = replay_audit_summary
            summary["std_bench_compiler_site_replay_blockers"] = replay_audit_blockers
        if isinstance(dynamic_gap_audit, dict):
            summary["compiler_dynamic_attribution_gap_audit"] = dynamic_gap_summary
            summary["compiler_dynamic_attribution_remaining_gaps"] = dynamic_gap_remaining
        if isinstance(exact_probe_audit, dict):
            summary["compiler_exact_dynamic_probe_audit"] = exact_probe_summary
        if isinstance(stream_mode_audit, dict):
            summary["compiler_site_stream_mode_comparison_audit"] = stream_mode_summary
            summary["compiler_site_stream_mode_comparison_blockers"] = stream_mode_blockers
        return summary
    active_type_id_basis = data.get("type_id_basis")
    return {
        "present": True,
        "coverage_percent": data.get("coverage_percent"),
        "coverage_bytes_percent": data.get("coverage_bytes_percent"),
        "claim_grade": data.get("claim_grade"),
        "evidence_verified": data.get("evidence_verified"),
        "type_id_basis": active_type_id_basis,
        "active_coverage_type_id_basis": active_type_id_basis,
        "event_sources": data.get("event_sources"),
        "event_type_id_bases": data.get("event_type_id_bases"),
        "claim_grade_blockers": data.get("claim_grade_blockers", []),
        "compiler_coverage_evidence_audit": compiler_audit_summary,
        "compiler_coverage_audit_blockers": compiler_audit_blockers,
        "compiler_coverage_benchmark_surface_audit": compiler_audit_benchmark_surface,
        "compiler_coverage_audit_type_id_basis": compiler_audit_type_id_basis,
        "compiler_coverage_audit_uses_compiler_assigned_type_ids": compiler_audit_uses_compiler_ids,
        "compiler_coverage_audit_is_current_strongest": compiler_audit_is_current_strongest,
        "rustc_mir_allocation_site_audit": mir_audit_summary,
        "rustc_mir_allocation_site_blockers": mir_audit_blockers,
        "rustc_mir_source_kind": mir_audit.get("source_kind") if isinstance(mir_audit, dict) else None,
        "rustc_mir_allocation_site_count": mir_audit_summary.get("allocation_site_count"),
        "rustc_mir_type_mapping_valid_record_count": mir_audit_summary.get("type_mapping_valid_record_count"),
        "std_bench_compiler_site_replay_audit": replay_audit_summary,
        "std_bench_compiler_site_replay_blockers": replay_audit_blockers,
        "compiler_dynamic_attribution_gap_audit": dynamic_gap_summary,
        "compiler_dynamic_attribution_remaining_gaps": dynamic_gap_remaining,
        "compiler_exact_dynamic_probe_audit": exact_probe_summary,
        "compiler_site_stream_mode_comparison_audit": stream_mode_summary,
        "compiler_site_stream_mode_comparison_blockers": stream_mode_blockers,
    }


def dataset_worklist_summary(dataset: Optional[str]) -> Dict[str, Any]:
    data = read_json_if_exists(RESULTS / "current_datasets_summary.json")
    if not isinstance(data, dict) or not dataset:
        return {"present": False}
    ds = data.get("datasets", {}).get(dataset)
    if not isinstance(ds, dict):
        return {"present": False, "dataset": dataset}
    scope = ds.get("scope", {}) if isinstance(ds.get("scope"), dict) else {}
    return {
        "present": True,
        "dataset": dataset,
        "path": ds.get("path"),
        "claim_grade": ds.get("claim_grade"),
        "complete_for_claim": scope.get("complete_for_claim"),
        "geomean": ds.get("geomean"),
        "count": ds.get("count"),
        "current_rows": scope.get("current_rows"),
        "reference_rows": scope.get("reference_rows"),
        "current_columns": scope.get("current_columns"),
        "reference_columns": scope.get("reference_columns"),
        "missing_reference_rows": scope.get("missing_reference_rows", []),
        "missing_reference_columns": scope.get("missing_reference_columns", []),
        "claim_grade_blockers": scope.get("claim_grade_blockers", []),
    }


def platform_worklist_summary() -> Dict[str, Any]:
    audit = read_json_if_exists(RESULTS / "platform_matrix_audit.json")
    matrix = read_json_if_exists(RESULTS / "platform_matrix.json")
    platforms: Dict[str, Any] = {}
    if isinstance(audit, dict):
        for name, info in audit.get("platforms", {}).items():
            if isinstance(info, dict):
                platforms[name] = {
                    "ready_for_claim_grade_import": info.get("ready_for_claim_grade_import"),
                    "required_evidence_kinds": info.get("required_evidence_kinds"),
                    "missing_required_evidence_kinds": info.get("missing_required_evidence_kinds"),
                    "evidence_content_blockers": info.get("evidence_content_blockers"),
                    "metadata_fields": info.get("metadata_fields"),
                    "missing_metadata_fields": info.get("missing_metadata_fields"),
                    "blockers": info.get("blockers", []),
                }
    return {
        "audit_present": isinstance(audit, dict),
        "matrix_present": isinstance(matrix, dict),
        "summary": audit.get("summary", {}) if isinstance(audit, dict) else {},
        "platforms": platforms,
        "matrix_meta": matrix.get("_meta", {}) if isinstance(matrix, dict) else {},
    }


def allocator_footprint_worklist_summary() -> Dict[str, Any]:
    """Return the compact status of the fast allocator-footprint gate."""

    audit = read_json_if_exists(RESULTS / "allocator_footprint_regression_gate_audit.json")
    if not isinstance(audit, dict):
        return {"present": False}
    blockers = audit.get("blockers", []) if isinstance(audit.get("blockers"), list) else []
    return {
        "present": True,
        "passed": audit.get("passed") is True,
        "generated_at": audit.get("generated_at"),
        "summary": audit.get("summary", {}),
        "blocker_count": len(blockers),
        "blockers": blockers,
        "source": audit.get("source"),
    }


def paper_performance_dataset_shard_audits(dataset: Optional[str]) -> List[Dict[str, Any]]:
    """Return compact local shard audits that actually cover a paper dataset."""

    if not dataset:
        return []
    matching: List[Dict[str, Any]] = []
    for path in sorted(RESULTS.glob("*_shard_audit.json")):
        audit = read_json_if_exists(path)
        if not isinstance(audit, dict):
            continue
        if audit.get("source") != "paper-performance-shard-audit":
            continue
        dataset_names = [
            str(item)
            for item in audit.get("dataset_names", [])
            if str(item).strip()
        ]
        cell_datasets = {
            str(cell.get("dataset"))
            for cell in audit.get("cells", [])
            if isinstance(cell, dict) and str(cell.get("dataset") or "").strip()
        }
        parity_datasets = {
            str(group.get("dataset"))
            for group in audit.get("parity_groups", [])
            if isinstance(group, dict) and str(group.get("dataset") or "").strip()
        }
        covered = set(dataset_names) | cell_datasets | parity_datasets
        if dataset not in covered:
            continue
        matching.append(
            {
                "path": str(path),
                "samples": audit.get("samples"),
                "dataset_names": dataset_names,
                "summary": audit.get("summary", {}),
                "diagnostic_blockers": audit.get("diagnostic_blockers", []),
            }
        )
    def shard_sort_key(item: Dict[str, Any]) -> Tuple[float, str]:
        path = Path(str(item.get("path") or ""))
        try:
            mtime = path.stat().st_mtime
        except OSError:
            mtime = 0.0
        return (mtime, str(path))

    matching.sort(key=shard_sort_key, reverse=True)
    return matching[:8]


